CREATE OR REPLACE FUNCTION "public"."_assert_parent_warehouse_tenant"("p_parent_tenant_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_parent_id bigint;
begin
  if p_parent_tenant_id is null then
    raise exception 'parent_tenant_id is required';
  end if;

  select parent_id into v_parent_id
  from public.tenants
  where id = p_parent_tenant_id;

  if not found then
    raise exception 'tenant not found';
  end if;

  if v_parent_id is not null then
    raise exception 'stock locations are only for parent warehouse tenants';
  end if;
end;
$$;


ALTER FUNCTION "public"."_assert_parent_warehouse_tenant"("p_parent_tenant_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_can_view_parent_warehouse_stock"("p_parent_tenant_id" bigint) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    public.is_superadmin()
    or public.user_can_manage_parent_tenant(p_parent_tenant_id)
    or public.membership_has_module_action(p_parent_tenant_id, 'global_stock', 'view')
    or exists (
      select 1
      from public.tenants child
      inner join public.memberships m on m.tenant_id = child.id
      where child.parent_id = p_parent_tenant_id
        and lower(trim(m.email)) = public.current_user_email()
        and m.is_active = true
        and public.membership_has_module_action(child.id, 'global_stock', 'view')
    );
$$;


ALTER FUNCTION "public"."_can_view_parent_warehouse_stock"("p_parent_tenant_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_can_view_stock_locations"("p_parent_tenant_id" bigint) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    public._can_view_parent_warehouse_stock(p_parent_tenant_id)
    or public.membership_has_module_action(p_parent_tenant_id, 'global_stock_location', 'view')
    or exists (
      select 1 from public.memberships m
      where m.tenant_id = p_parent_tenant_id
        and lower(trim(m.email)) = public.current_user_email()
        and m.is_active = true
    );
$$;


ALTER FUNCTION "public"."_can_view_stock_locations"("p_parent_tenant_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_guard_global_shipment_costs_locked"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF tg_op = 'UPDATE' THEN
    IF NEW.costs_locked IS DISTINCT FROM OLD.costs_locked
       AND current_setting('app.allow_costs_lock', true) IS DISTINCT FROM '1' THEN
      RAISE EXCEPTION 'use lock_global_shipment_costs to lock shipment costs';
    END IF;

    IF OLD.costs_locked THEN
      IF NEW.received_weight IS DISTINCT FROM OLD.received_weight
         OR NEW.total_weight_kg IS DISTINCT FROM OLD.total_weight_kg THEN
        RAISE EXCEPTION 'shipment costs are locked';
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."_guard_global_shipment_costs_locked"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_recompute_shop_order_item_fulfillment"("p_order_item_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_item public.shop_order_items%rowtype;
  v_pick_qty integer := 0;
  v_first_held bigint;
  v_weighted_cost numeric(12,4);
begin
  select * into v_item from public.shop_order_items where id = p_order_item_id for update;
  if v_item.id is null then
    return;
  end if;

  if coalesce(v_item.is_fulfillment_unavailable, false) then
    update public.shop_order_items
    set
      confirmed_quantity = 0,
      global_stock_id = null,
      cost_price_amount = null,
      updated_at = now()
    where id = p_order_item_id;
    return;
  end if;

  select coalesce(sum(sp.quantity), 0)
  into v_pick_qty
  from public.shop_order_item_stock_picks sp
  where sp.order_item_id = p_order_item_id;

  select sp.held_stock_id
  into v_first_held
  from public.shop_order_item_stock_picks sp
  where sp.order_item_id = p_order_item_id
  order by sp.id asc
  limit 1;

  select case
    when v_pick_qty > 0 then
      coalesce(
        sum(
          coalesce(public.calculate_landed_unit_cost(sp.shipment_item_id), 0)
          * sp.quantity
        ) / nullif(v_pick_qty, 0),
        v_item.cost_price_amount
      )
    else null
  end
  into v_weighted_cost
  from public.shop_order_item_stock_picks sp
  where sp.order_item_id = p_order_item_id;

  update public.shop_order_items
  set
    confirmed_quantity = v_pick_qty,
    global_stock_id = v_first_held,
    cost_price_amount = v_weighted_cost,
    updated_at = now()
  where id = p_order_item_id;
end;
$$;


ALTER FUNCTION "public"."_recompute_shop_order_item_fulfillment"("p_order_item_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_restamp_global_shipment_on_weight_change"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
  if coalesce(current_setting('app.skip_shipment_landed_restamp', true), '') = '1' then
    return new;
  end if;

  if tg_op = 'UPDATE'
     and not public.global_shipment_costs_are_locked(new)
     and (
       new.received_weight is distinct from old.received_weight
       or new.total_weight_kg is distinct from old.total_weight_kg
     )
     and exists (select 1 from public.global_shipment_items where shipment_id = new.id) then
    perform public.stamp_global_shipment_landed_costs(new.id);
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."_restamp_global_shipment_on_weight_change"() OWNER TO "postgres";


