CREATE OR REPLACE FUNCTION "public"."add_shop_order_item_stock_pick"("p_order_item_id" bigint, "p_global_stock_id" bigint, "p_quantity" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_item public.shop_order_items%rowtype;
  v_order public.shop_orders%rowtype;
  v_stock public.global_stocks%rowtype;
  v_held_stock_id bigint;
  v_parent_tenant_id bigint;
  v_existing_qty integer := 0;
  v_total_picked integer := 0;
  v_pick_id bigint;
  v_grade_tag_id bigint;
begin
  if p_quantity is null or p_quantity <= 0 then
    raise exception 'quantity must be positive';
  end if;

  select * into v_item from public.shop_order_items where id = p_order_item_id for update;
  if v_item.id is null then
    raise exception 'order item not found';
  end if;

  select * into v_order from public.shop_orders where id = v_item.order_id for update;
  if not public.is_tenant_staff(v_order.tenant_id) then
    raise exception 'access denied';
  end if;

  if v_order.status <> 'processing'::public.shop_order_status then
    raise exception 'stock pick is only allowed while order is processing';
  end if;

  if coalesce(v_item.is_fulfillment_unavailable, false) then
    raise exception 'line is marked unavailable';
  end if;

  v_grade_tag_id := coalesce(v_item.grade_tag_id, public.default_stock_grade_tag_id());

  select * into v_stock
  from public.global_stocks gs
  join public.global_shipment_items gsi on gsi.id = gs.shipment_item_id
  where gs.id = p_global_stock_id
    and gsi.product_id = v_item.product_id
    and coalesce(gs.grade_tag_id, public.default_stock_grade_tag_id()) = v_grade_tag_id
  for update of gs;

  if v_stock.id is null then
    raise exception 'stock not found or does not match line product/grade';
  end if;

  if v_stock.availability <> 'sellable'::public.stock_availability then
    raise exception 'stock is not sellable';
  end if;

  if public.global_stock_atp_qty(v_stock.id) < p_quantity then
    raise exception 'insufficient ATP (requested %, available %)', p_quantity, public.global_stock_atp_qty(v_stock.id);
  end if;

  select coalesce(sum(sp.quantity), 0)
  into v_total_picked
  from public.shop_order_item_stock_picks sp
  where sp.order_item_id = p_order_item_id;

  select coalesce(sp.quantity, 0)
  into v_existing_qty
  from public.shop_order_item_stock_picks sp
  where sp.order_item_id = p_order_item_id
    and sp.global_stock_id = p_global_stock_id;

  if v_total_picked - v_existing_qty + p_quantity > v_item.quantity then
    raise exception 'pick quantity exceeds ordered qty (ordered %, would pick %)',
      v_item.quantity, v_total_picked - v_existing_qty + p_quantity;
  end if;

  v_parent_tenant_id := public.resolve_parent_tenant_id(v_order.tenant_id);

  perform public.create_and_post_stock_movement(
    p_tenant_id => v_parent_tenant_id,
    p_stock_id => v_stock.id,
    p_quantity => p_quantity,
    p_to_location_id => v_stock.location_id,
    p_to_availability => 'held'::public.stock_availability,
    p_to_grade_tag_id => v_stock.grade_tag_id,
    p_movement_type => 'availability_transfer'::public.stock_movement_type,
    p_notes => 'Dropship processing pick',
    p_reference_type => 'shop_order',
    p_reference_id => v_order.id::text
  );

  select gs.id into v_held_stock_id
  from public.global_stocks gs
  where gs.shipment_item_id = v_stock.shipment_item_id
    and gs.parent_tenant_id = v_parent_tenant_id
    and gs.availability = 'held'::public.stock_availability
    and gs.location_id is not distinct from v_stock.location_id
    and coalesce(gs.grade_tag_id, public.default_stock_grade_tag_id())
      = coalesce(v_stock.grade_tag_id, public.default_stock_grade_tag_id())
  order by gs.id desc
  limit 1;

  insert into public.shop_order_item_stock_picks (
    tenant_id, order_id, order_item_id, global_stock_id,
    shipment_item_id, shipment_id, quantity, held_stock_id, created_by_email
  )
  values (
    v_order.tenant_id, v_order.id, v_item.id, v_stock.id,
    v_stock.shipment_item_id,
    (select shipment_id from public.global_shipment_items where id = v_stock.shipment_item_id),
    p_quantity, v_held_stock_id, public.current_user_email()
  )
  on conflict (order_item_id, global_stock_id) do update
  set
    quantity = public.shop_order_item_stock_picks.quantity + excluded.quantity,
    held_stock_id = excluded.held_stock_id,
    updated_at = now()
  returning id into v_pick_id;

  perform public._recompute_shop_order_item_fulfillment(p_order_item_id);
  perform public.recompute_dropship_cod_collect_amount(v_order.id);

  return jsonb_build_object(
    'success', true,
    'pick_id', v_pick_id,
    'confirmed_quantity', (select confirmed_quantity from public.shop_order_items where id = p_order_item_id),
    'cod_collect_amount', (select cod_collect_amount from public.shop_orders where id = v_order.id)
  );
end;
$$;


ALTER FUNCTION "public"."add_shop_order_item_stock_pick"("p_order_item_id" bigint, "p_global_stock_id" bigint, "p_quantity" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_stock_movement_line"("p_movement_id" bigint, "p_stock_id" bigint, "p_quantity" numeric, "p_from_location_id" bigint DEFAULT NULL::bigint, "p_to_location_id" bigint DEFAULT NULL::bigint, "p_from_availability" "public"."stock_availability" DEFAULT NULL::"public"."stock_availability", "p_to_availability" "public"."stock_availability" DEFAULT NULL::"public"."stock_availability", "p_from_grade_tag_id" bigint DEFAULT NULL::bigint, "p_to_grade_tag_id" bigint DEFAULT NULL::bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_mov public.stock_movements%rowtype;
  v_line public.stock_movement_lines%rowtype;
begin
  select * into v_mov from public.stock_movements where id = p_movement_id for update;
  if not found then
    raise exception 'movement not found';
  end if;
  if v_mov.is_posted then
    raise exception 'movement already posted';
  end if;
  if not public.has_active_tenant_membership(v_mov.tenant_id)
     and not public.is_superadmin() then
    raise exception 'not authorized';
  end if;
  if coalesce(p_quantity, 0) <= 0 then
    raise exception 'quantity must be positive';
  end if;

  insert into public.stock_movement_lines (
    movement_id, stock_id, from_location_id, to_location_id,
    from_availability, to_availability, from_grade_tag_id, to_grade_tag_id, quantity
  ) values (
    p_movement_id, p_stock_id, p_from_location_id, p_to_location_id,
    p_from_availability, p_to_availability, p_from_grade_tag_id, p_to_grade_tag_id, p_quantity
  )
  returning * into v_line;

  return jsonb_build_object('line', to_jsonb(v_line));
end;
$$;


ALTER FUNCTION "public"."add_stock_movement_line"("p_movement_id" bigint, "p_stock_id" bigint, "p_quantity" numeric, "p_from_location_id" bigint, "p_to_location_id" bigint, "p_from_availability" "public"."stock_availability", "p_to_availability" "public"."stock_availability", "p_from_grade_tag_id" bigint, "p_to_grade_tag_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_to_shop_cart"("p_shop_id" bigint, "p_product_id" bigint, "p_global_stock_allocation_id" bigint DEFAULT NULL::bigint, "p_quantity" integer DEFAULT 1, "p_customer_sell_price_amount" numeric DEFAULT NULL::numeric, "p_customer_sell_price_currency_id" bigint DEFAULT NULL::bigint, "p_global_stock_id" bigint DEFAULT NULL::bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_cart_res jsonb;
  v_cart_id bigint;
  v_tenant_id bigint;
  v_shop_type public.shop_type_enum;
  v_pricing_method text;
  v_markup_percentage numeric;
  v_buy_currency_id bigint;
  v_prod_name text;
  v_prod_image text;
  v_prod_vendor text;
  v_prod_is_available boolean;
  v_prod_price_amount numeric;
  v_prod_price_currency_id bigint;
  v_listing_id bigint;
  v_global_stock_id bigint;
  v_sell_price_amount numeric;
  v_sell_price_currency_id bigint;
  v_min_sell_price_amount numeric;
  v_min_sell_price_currency_id bigint;
  v_display_qty_override integer;
  v_landed_cost numeric;
  v_available_to_sell integer;
  v_existing_item_id bigint;
  v_existing_item_qty integer;
  v_target_qty integer;
  v_can_add_to_cart boolean;
  v_can_set_dropship_price boolean;
  v_customer_sell_price_amount numeric;
  v_customer_sell_price_currency_id bigint;
begin
  v_cart_res := public.get_or_create_shop_cart(p_shop_id);
  v_cart_id := (v_cart_res->'cart'->>'id')::bigint;

  select tenant_id, shop_type, pricing_method, markup_percentage, buy_currency_id
  into v_tenant_id, v_shop_type, v_pricing_method, v_markup_percentage, v_buy_currency_id
  from public.shops
  where id = p_shop_id;

  select can_add_to_cart, can_set_dropship_price
  into v_can_add_to_cart, v_can_set_dropship_price
  from public.get_shop_permissions_for_customer(p_shop_id);

  if coalesce(v_can_add_to_cart, false) is not true then
    raise exception 'cart additions not allowed';
  end if;

  select name, image_url, vendor_code, is_available, list_price_amount, list_price_currency_id
  into v_prod_name, v_prod_image, v_prod_vendor, v_prod_is_available, v_prod_price_amount, v_prod_price_currency_id
  from public.products
  where id = p_product_id;

  if v_prod_name is null then
    raise exception 'product not found';
  end if;

  v_global_stock_id := coalesce(p_global_stock_id, p_global_stock_allocation_id);

  if v_shop_type in ('fixed_price', 'dropship') then
    if v_global_stock_id is null then
      raise exception 'global stock required for this shop type';
    end if;

    select
      l.id, l.global_stock_id, l.sell_price_amount, l.sell_price_currency_id,
      l.minimum_sell_price_amount, l.minimum_sell_price_currency_id, l.display_quantity_override
    into
      v_listing_id, v_global_stock_id, v_sell_price_amount, v_sell_price_currency_id,
      v_min_sell_price_amount, v_min_sell_price_currency_id, v_display_qty_override
    from public.shop_product_listings l
    where l.shop_id = p_shop_id
      and l.global_stock_id = v_global_stock_id
      and l.product_id = p_product_id
      and l.is_active = true;

    if v_listing_id is null then
      raise exception 'active product listing not found on this shop';
    end if;

    select coalesce(gsi.landed_cost_bdt, public.calculate_landed_unit_cost(gs.shipment_item_id))
    into v_landed_cost
    from public.global_stocks gs
    join public.global_shipment_items gsi on gsi.id = gs.shipment_item_id
    where gs.id = v_global_stock_id;

    if v_shop_type = 'fixed_price' then
      if v_pricing_method = 'markup' then
        v_sell_price_amount := v_landed_cost * (1 + v_markup_percentage / 100.0);
      elsif v_pricing_method = 'direct_cost' then
        v_sell_price_amount := v_landed_cost;
      end if;
    end if;

    select id, quantity into v_existing_item_id, v_existing_item_qty
    from public.shop_cart_items
    where cart_id = v_cart_id
      and global_stock_id = v_global_stock_id;

    v_existing_item_qty := coalesce(v_existing_item_qty, 0);
    v_target_qty := v_existing_item_qty + p_quantity;
    v_available_to_sell := greatest(0, floor(public.global_stock_atp_qty(v_global_stock_id))::integer);

    if v_target_qty > v_available_to_sell then
      raise exception 'insufficient stock: requested %, available %', v_target_qty, v_available_to_sell;
    end if;

    if v_shop_type = 'dropship' then
      if coalesce(v_can_set_dropship_price, false) then
        if p_customer_sell_price_amount is not null then
          v_customer_sell_price_amount := p_customer_sell_price_amount;
          v_customer_sell_price_currency_id := p_customer_sell_price_currency_id;
        else
          if v_sell_price_currency_id = v_min_sell_price_currency_id then
            v_customer_sell_price_amount := greatest(v_sell_price_amount, coalesce(v_min_sell_price_amount, 0));
          else
            v_customer_sell_price_amount := v_sell_price_amount;
          end if;
          v_customer_sell_price_currency_id := v_sell_price_currency_id;
        end if;

        if v_customer_sell_price_currency_id = v_min_sell_price_currency_id
           and v_customer_sell_price_amount < v_min_sell_price_amount then
          raise exception 'price cannot be lower than the minimum sell price %', v_min_sell_price_amount;
        end if;
      else
        v_customer_sell_price_amount := v_sell_price_amount;
        v_customer_sell_price_currency_id := v_sell_price_currency_id;
      end if;
    end if;
  else
    select id, quantity into v_existing_item_id, v_existing_item_qty
    from public.shop_cart_items
    where cart_id = v_cart_id
      and product_id = p_product_id;

    v_existing_item_qty := coalesce(v_existing_item_qty, 0);
    v_target_qty := v_existing_item_qty + p_quantity;
  end if;

  if v_existing_item_id is not null then
    update public.shop_cart_items
    set
      quantity = v_target_qty,
      unit_sell_price_amount = v_sell_price_amount,
      customer_sell_price_amount = coalesce(v_customer_sell_price_amount, customer_sell_price_amount),
      customer_sell_price_currency_id = coalesce(v_customer_sell_price_currency_id, customer_sell_price_currency_id),
      updated_at = now()
    where id = v_existing_item_id;
  else
    insert into public.shop_cart_items (
      cart_id, product_id, global_stock_id, global_stock_allocation_id,
      quantity, minimum_quantity,
      unit_list_price_amount, unit_list_price_currency_id,
      unit_sell_price_amount, unit_sell_price_currency_id,
      unit_minimum_sell_price_amount, unit_minimum_sell_price_currency_id,
      customer_sell_price_amount, customer_sell_price_currency_id,
      name, image_url
    )
    values (
      v_cart_id, p_product_id, v_global_stock_id, null,
      p_quantity, 1,
      case when v_shop_type = 'dropship' then coalesce(v_landed_cost, v_prod_price_amount) else v_prod_price_amount end,
      case when v_shop_type = 'dropship' then v_buy_currency_id else v_prod_price_currency_id end,
      v_sell_price_amount, v_sell_price_currency_id,
      v_min_sell_price_amount, v_min_sell_price_currency_id,
      v_customer_sell_price_amount, v_customer_sell_price_currency_id,
      v_prod_name, v_prod_image
    );
  end if;

  return public.get_or_create_shop_cart(p_shop_id);
end;
$$;


ALTER FUNCTION "public"."add_to_shop_cart"("p_shop_id" bigint, "p_product_id" bigint, "p_global_stock_allocation_id" bigint, "p_quantity" integer, "p_customer_sell_price_amount" numeric, "p_customer_sell_price_currency_id" bigint, "p_global_stock_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_to_shop_cart"("p_shop_id" bigint, "p_product_id" bigint, "p_global_stock_allocation_id" bigint DEFAULT NULL::bigint, "p_quantity" integer DEFAULT 1, "p_customer_sell_price_amount" numeric DEFAULT NULL::numeric, "p_customer_sell_price_currency_id" bigint DEFAULT NULL::bigint, "p_global_stock_id" bigint DEFAULT NULL::bigint, "p_listing_id" bigint DEFAULT NULL::bigint, "p_grade_slug" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_cart_res jsonb;
  v_cart_id bigint;
  v_tenant_id bigint;
  v_shop_type public.shop_type_enum;
  v_pricing_method text;
  v_markup_percentage numeric;
  v_quantity_display_mode text;
  v_buy_currency_id bigint;
  v_prod_name text;
  v_prod_image text;
  v_prod_price_amount numeric;
  v_prod_price_currency_id bigint;
  v_listing_id bigint;
  v_global_stock_id bigint;
  v_grade_tag_id bigint;
  v_sell_price_amount numeric;
  v_sell_price_currency_id bigint;
  v_min_sell_price_amount numeric;
  v_min_sell_price_currency_id bigint;
  v_display_qty_override integer;
  v_landed_cost numeric;
  v_available_to_sell integer;
  v_existing_item_id bigint;
  v_existing_item_qty integer;
  v_target_qty integer;
  v_can_add_to_cart boolean;
  v_can_set_dropship_price boolean;
  v_customer_sell_price_amount numeric;
  v_customer_sell_price_currency_id bigint;
  v_min_available_units integer;
  v_product_available_units integer;
BEGIN
  v_cart_res := public.get_or_create_shop_cart(p_shop_id);
  v_cart_id := (v_cart_res->'cart'->>'id')::bigint;

  SELECT tenant_id, shop_type, pricing_method, markup_percentage, buy_currency_id, quantity_display_mode, min_available_units
  INTO v_tenant_id, v_shop_type, v_pricing_method, v_markup_percentage, v_buy_currency_id, v_quantity_display_mode, v_min_available_units
  FROM public.shops
  WHERE id = p_shop_id;

  SELECT can_add_to_cart, can_set_dropship_price
  INTO v_can_add_to_cart, v_can_set_dropship_price
  FROM public.get_shop_permissions_for_customer(p_shop_id);

  IF coalesce(v_can_add_to_cart, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'cart additions not allowed';
  END IF;

  SELECT name, image_url, list_price_amount, list_price_currency_id, available_units
  INTO v_prod_name, v_prod_image, v_prod_price_amount, v_prod_price_currency_id, v_product_available_units
  FROM public.products
  WHERE id = p_product_id;

  IF v_prod_name IS NULL THEN
    RAISE EXCEPTION 'product not found';
  END IF;

  v_global_stock_id := coalesce(p_global_stock_id, p_global_stock_allocation_id);

  IF v_shop_type IN ('fixed_price', 'dropship') THEN
    IF p_listing_id IS NOT NULL THEN
      SELECT
        l.id, coalesce(l.grade_tag_id, gs.grade_tag_id), l.sell_price_amount, l.sell_price_currency_id,
        l.minimum_sell_price_amount, l.minimum_sell_price_currency_id, l.display_quantity_override
      INTO
        v_listing_id, v_grade_tag_id, v_sell_price_amount, v_sell_price_currency_id,
        v_min_sell_price_amount, v_min_sell_price_currency_id, v_display_qty_override
      FROM public.shop_product_listings l
      LEFT JOIN public.global_stocks gs ON gs.id = l.global_stock_id
      WHERE l.id = p_listing_id
        AND l.shop_id = p_shop_id
        AND l.product_id = p_product_id
        AND l.is_active = TRUE;
    ELSIF v_global_stock_id IS NOT NULL THEN
      SELECT coalesce(gs_ref.grade_tag_id, public.default_stock_grade_tag_id())
      INTO v_grade_tag_id
      FROM public.global_stocks gs_ref
      WHERE gs_ref.id = v_global_stock_id;

      SELECT
        l.id, coalesce(l.grade_tag_id, gs.grade_tag_id), l.sell_price_amount, l.sell_price_currency_id,
        l.minimum_sell_price_amount, l.minimum_sell_price_currency_id, l.display_quantity_override
      INTO
        v_listing_id, v_grade_tag_id, v_sell_price_amount, v_sell_price_currency_id,
        v_min_sell_price_amount, v_min_sell_price_currency_id, v_display_qty_override
      FROM public.shop_product_listings l
      LEFT JOIN public.global_stocks gs ON gs.id = l.global_stock_id
      WHERE l.shop_id = p_shop_id
        AND l.product_id = p_product_id
        AND l.is_active = TRUE
        AND coalesce(l.grade_tag_id, gs.grade_tag_id) = v_grade_tag_id
      ORDER BY l.id ASC
      LIMIT 1;
    ELSIF p_grade_slug IS NOT NULL AND trim(p_grade_slug) <> '' THEN
      SELECT
        l.id, coalesce(l.grade_tag_id, gs.grade_tag_id), l.sell_price_amount, l.sell_price_currency_id,
        l.minimum_sell_price_amount, l.minimum_sell_price_currency_id, l.display_quantity_override
      INTO
        v_listing_id, v_grade_tag_id, v_sell_price_amount, v_sell_price_currency_id,
        v_min_sell_price_amount, v_min_sell_price_currency_id, v_display_qty_override
      FROM public.shop_product_listings l
      LEFT JOIN public.global_stocks gs ON gs.id = l.global_stock_id
      LEFT JOIN public.tags tg ON tg.id = coalesce(l.grade_tag_id, gs.grade_tag_id)
      WHERE l.shop_id = p_shop_id
        AND l.product_id = p_product_id
        AND l.is_active = TRUE
        AND coalesce(tg.slug, 'standard') = coalesce(nullif(trim(p_grade_slug), ''), 'standard')
      ORDER BY l.id ASC
      LIMIT 1;
    ELSE
      RAISE EXCEPTION 'listing, grade, or global stock required for this shop type';
    END IF;

    IF v_listing_id IS NULL THEN
      RAISE EXCEPTION 'active product listing not found on this shop';
    END IF;

    v_grade_tag_id := coalesce(v_grade_tag_id, public.default_stock_grade_tag_id());

    IF v_grade_tag_id IS NULL THEN
      RAISE EXCEPTION 'listing grade required';
    END IF;

    v_global_stock_id := NULL;

    SELECT public.shop_product_grade_avg_landed_cost(v_tenant_id, p_product_id, v_grade_tag_id)
    INTO v_landed_cost;

    IF v_shop_type = 'fixed_price' THEN
      IF v_pricing_method = 'markup' THEN
        v_sell_price_amount := v_landed_cost * (1 + v_markup_percentage / 100.0);
      ELSIF v_pricing_method = 'direct_cost' THEN
        v_sell_price_amount := v_landed_cost;
      END IF;
    END IF;

    v_available_to_sell := public.shop_product_grade_available_units(v_tenant_id, p_product_id, v_grade_tag_id);
    IF v_display_qty_override IS NOT NULL THEN
      v_available_to_sell := v_display_qty_override;
    END IF;

    SELECT id, quantity INTO v_existing_item_id, v_existing_item_qty
    FROM public.shop_cart_items
    WHERE cart_id = v_cart_id
      AND listing_id = v_listing_id;

    v_existing_item_qty := coalesce(v_existing_item_qty, 0);
    v_target_qty := v_existing_item_qty + p_quantity;

    IF v_target_qty > v_available_to_sell THEN
      RAISE EXCEPTION 'insufficient stock: requested %, available %', v_target_qty, v_available_to_sell;
    END IF;

    IF v_shop_type = 'dropship' THEN
      IF coalesce(v_can_set_dropship_price, false) THEN
        IF p_customer_sell_price_amount IS NOT NULL THEN
          v_customer_sell_price_amount := p_customer_sell_price_amount;
          v_customer_sell_price_currency_id := p_customer_sell_price_currency_id;
        ELSE
          IF v_sell_price_currency_id = v_min_sell_price_currency_id THEN
            v_customer_sell_price_amount := greatest(v_sell_price_amount, coalesce(v_min_sell_price_amount, 0));
          ELSE
            v_customer_sell_price_amount := v_sell_price_amount;
          END IF;
          v_customer_sell_price_currency_id := v_sell_price_currency_id;
        END IF;

        IF v_customer_sell_price_currency_id = v_min_sell_price_currency_id
           AND v_customer_sell_price_amount < v_min_sell_price_amount THEN
          RAISE EXCEPTION 'price cannot be lower than the minimum sell price %', v_min_sell_price_amount;
        END IF;
      ELSE
        v_customer_sell_price_amount := v_sell_price_amount;
        v_customer_sell_price_currency_id := v_sell_price_currency_id;
      END IF;
    END IF;
  ELSE
    IF NOT public.shop_catalog_meets_min_available_units(v_min_available_units, v_product_available_units) THEN
      RAISE EXCEPTION 'product does not meet minimum available units requirement';
    END IF;

    SELECT id, quantity INTO v_existing_item_id, v_existing_item_qty
    FROM public.shop_cart_items
    WHERE cart_id = v_cart_id
      AND product_id = p_product_id;

    v_existing_item_qty := coalesce(v_existing_item_qty, 0);
    v_target_qty := v_existing_item_qty + p_quantity;
  END IF;

  IF v_existing_item_id IS NOT NULL THEN
    UPDATE public.shop_cart_items
    SET
      quantity = v_target_qty,
      unit_sell_price_amount = v_sell_price_amount,
      customer_sell_price_amount = coalesce(v_customer_sell_price_amount, customer_sell_price_amount),
      customer_sell_price_currency_id = coalesce(v_customer_sell_price_currency_id, customer_sell_price_currency_id),
      updated_at = now()
    WHERE id = v_existing_item_id;
  ELSE
    INSERT INTO public.shop_cart_items (
      cart_id, product_id, listing_id, grade_tag_id, global_stock_id, global_stock_allocation_id,
      quantity, minimum_quantity,
      unit_list_price_amount, unit_list_price_currency_id,
      unit_sell_price_amount, unit_sell_price_currency_id,
      unit_minimum_sell_price_amount, unit_minimum_sell_price_currency_id,
      customer_sell_price_amount, customer_sell_price_currency_id,
      name, image_url
    )
    VALUES (
      v_cart_id, p_product_id, v_listing_id, v_grade_tag_id, NULL, NULL,
      p_quantity, 1,
      CASE WHEN v_shop_type = 'dropship' THEN coalesce(v_landed_cost, v_prod_price_amount) ELSE v_prod_price_amount END,
      CASE WHEN v_shop_type = 'dropship' THEN v_buy_currency_id ELSE v_prod_price_currency_id END,
      v_sell_price_amount, v_sell_price_currency_id,
      v_min_sell_price_amount, v_min_sell_price_currency_id,
      v_customer_sell_price_amount, v_customer_sell_price_currency_id,
      v_prod_name, v_prod_image
    );
  END IF;

  RETURN public.get_or_create_shop_cart(p_shop_id);
END;
$$;


ALTER FUNCTION "public"."add_to_shop_cart"("p_shop_id" bigint, "p_product_id" bigint, "p_global_stock_allocation_id" bigint, "p_quantity" integer, "p_customer_sell_price_amount" numeric, "p_customer_sell_price_currency_id" bigint, "p_global_stock_id" bigint, "p_listing_id" bigint, "p_grade_slug" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."adjust_inventory_reserved_for_product"("p_tenant_id" bigint, "p_product_id" bigint, "p_delta" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_remaining integer := coalesce(p_delta, 0);
  v_rec record;
  v_take integer;
  v_slack integer;
begin
  if v_remaining = 0 or p_product_id is null then
    return;
  end if;

  if v_remaining > 0 then
    for v_rec in
      select
        st.id,
        st.available_quantity,
        st.reserved_quantity,
        st.damaged_quantity,
        st.stolen_quantity,
        st.expired_quantity,
        st.open_box_quantity
      from public.inventory_stocks st
      join public.inventory_items ii on ii.id = st.inventory_item_id
      where ii.tenant_id = p_tenant_id
        and ii.product_id = p_product_id
        and ii.status = 'active'
      order by st.id asc
      for update of st
    loop
      v_slack := greatest(
        0,
        coalesce(v_rec.available_quantity, 0)
        - coalesce(v_rec.reserved_quantity, 0)
        - coalesce(v_rec.damaged_quantity, 0)
        - coalesce(v_rec.stolen_quantity, 0)
        - coalesce(v_rec.expired_quantity, 0)
        - coalesce(v_rec.open_box_quantity, 0)
      );

      if v_slack <= 0 then
        continue;
      end if;

      v_take := least(v_remaining, v_slack);

      update public.inventory_stocks
      set reserved_quantity = coalesce(reserved_quantity, 0) + v_take
      where id = v_rec.id;

      v_remaining := v_remaining - v_take;
      exit when v_remaining = 0;
    end loop;

    if v_remaining > 0 then
      raise exception 'Not enough stock to reserve for product %.', p_product_id;
    end if;
  else
    v_remaining := abs(v_remaining);

    for v_rec in
      select
        st.id,
        st.reserved_quantity
      from public.inventory_stocks st
      join public.inventory_items ii on ii.id = st.inventory_item_id
      where ii.tenant_id = p_tenant_id
        and ii.product_id = p_product_id
        and ii.status = 'active'
        and coalesce(st.reserved_quantity, 0) > 0
      order by st.id desc
      for update of st
    loop
      v_take := least(v_remaining, coalesce(v_rec.reserved_quantity, 0));

      update public.inventory_stocks
      set reserved_quantity = greatest(0, coalesce(reserved_quantity, 0) - v_take)
      where id = v_rec.id;

      v_remaining := v_remaining - v_take;
      exit when v_remaining = 0;
    end loop;
  end if;
end;
$$;


ALTER FUNCTION "public"."adjust_inventory_reserved_for_product"("p_tenant_id" bigint, "p_product_id" bigint, "p_delta" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."advance_dropship_order_status"("p_order_id" bigint, "p_target_status" "public"."shop_order_status", "p_remittance_ref" "text" DEFAULT NULL::"text", "p_bank_trx_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_order public.shop_orders;
  v_invoice public.global_invoices;
  v_current_status public.shop_order_status;
  v_is_valid boolean := false;
begin
  select * into v_order from public.shop_orders where id = p_order_id for update;
  if v_order.id is null then
    return jsonb_build_object('success', false, 'error', 'Order not found');
  end if;

  if v_order.shop_type_snapshot <> 'dropship' then
    return jsonb_build_object('success', false, 'error', 'Order is not a dropship order');
  end if;

  v_current_status := v_order.status;

  if v_current_status = p_target_status then
    return jsonb_build_object('success', true, 'message', 'Status unchanged', 'new_status', p_target_status);
  end if;

  if p_target_status in ('shipped'::public.shop_order_status, 'delivered'::public.shop_order_status) then
    return jsonb_build_object(
      'success', false,
      'error', format(
        'Use ship_dropship_order_and_issue_merchant_bill or mark_dropship_order_delivered instead of advance to %s',
        p_target_status
      )
    );
  end if;

  if v_current_status in ('submitted', 'draft', 'placed', 'confirmed')
     and p_target_status in ('processing', 'cancelled') then
    v_is_valid := true;
  elsif v_current_status in ('processing', 'ready_for_pickup', 'shipped', 'delivered', 'returned', 'payment_received') then
    if p_target_status in (
      'processing', 'ready_for_pickup', 'returned', 'payment_received', 'cancelled'
    ) then
      v_is_valid := true;
    end if;
  end if;

  if not v_is_valid then
    return jsonb_build_object(
      'success', false,
      'error', format(
        'Invalid status transition for dropship order from %s to %s',
        v_current_status,
        p_target_status
      )
    );
  end if;

  if p_target_status = 'processing' and v_order.global_invoice_id is not null then
    select * into v_invoice from public.global_invoices where id = v_order.global_invoice_id;
    if v_invoice.payment_status in ('paid', 'partially_paid') then
      return jsonb_build_object(
        'success', false,
        'error', 'Cannot rollback: merchant bill has payments allocated'
      );
    end if;
  end if;

  update public.shop_orders
  set
    status = p_target_status,
    courier_remittance_ref = coalesce(p_remittance_ref, courier_remittance_ref),
    courier_bank_trx_id = coalesce(p_bank_trx_id, courier_bank_trx_id),
    updated_at = now()
  where id = p_order_id;

  select * into v_order from public.shop_orders where id = p_order_id;

  if p_target_status = 'cancelled' then
    perform public.release_dropship_order_stock(p_order_id, true);
  end if;

  if p_target_status = 'processing' and v_order.global_invoice_id is not null then
    select * into v_invoice from public.global_invoices where id = v_order.global_invoice_id;
    if v_invoice.invoice_status = 'issued'::public.global_invoice_status then
      perform public.unpost_global_invoice(v_order.global_invoice_id);
    end if;

    delete from public.universal_wallet_ledger
    where source_type = 'shop_order'
      and (
        source_id = p_order_id::text
        or source_id = v_order.order_no
        or source_id = v_invoice.invoice_no
      )
      and tenant_id = v_order.tenant_id;

    update public.shop_orders
    set global_invoice_id = null, updated_at = now()
    where id = p_order_id;

    delete from public.global_return_items where invoice_id = v_order.global_invoice_id;
    delete from public.global_invoice_items where invoice_id = v_order.global_invoice_id;
    delete from public.global_invoices where id = v_order.global_invoice_id;
  end if;

  return jsonb_build_object('success', true, 'new_status', p_target_status);
end;
$$;


ALTER FUNCTION "public"."advance_dropship_order_status"("p_order_id" bigint, "p_target_status" "public"."shop_order_status", "p_remittance_ref" "text", "p_bank_trx_id" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."invoice_payments" (
    "id" bigint NOT NULL,
    "tenant_id" bigint NOT NULL,
    "payment_id" bigint NOT NULL,
    "invoice_id" bigint,
    "amount" numeric(12,2) NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "global_invoice_id" bigint,
    "commerce_invoice_id" bigint,
    CONSTRAINT "payment_allocations_amount_check" CHECK (("amount" > (0)::numeric))
);


ALTER TABLE "public"."invoice_payments" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."allocate_payment_to_global_invoice"("p_tenant_id" bigint, "p_payment_id" bigint, "p_global_invoice_id" bigint, "p_amount" numeric) RETURNS "public"."invoice_payments"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_payment public.global_payments;
  v_invoice public.global_invoices;
  v_row public.invoice_payments;
begin
  if p_tenant_id is null or p_payment_id is null or p_global_invoice_id is null then
    raise exception 'Tenant, payment and invoice are required.';
  end if;
  if coalesce(p_amount, 0) <= 0 then
    raise exception 'Allocation amount must be greater than zero.';
  end if;

  -- Lock payment
  select * into v_payment from public.global_payments where id = p_payment_id for update;
  if not found then raise exception 'Payment not found.'; end if;
  if v_payment.tenant_id <> p_tenant_id then raise exception 'Payment tenant mismatch.'; end if;

  -- Lock invoice
  select * into v_invoice from public.global_invoices where id = p_global_invoice_id for update;
  if not found then raise exception 'Invoice not found.'; end if;
  if v_invoice.tenant_id <> p_tenant_id then raise exception 'Invoice tenant mismatch.'; end if;

  -- Validate same billing profile
  if coalesce(v_invoice.billing_profile_id, 0) <> coalesce(v_payment.billing_profile_id, 0) then
    raise exception 'Invoice and payment billing profile mismatch.';
  end if;

  -- Check payment unallocated amount
  if p_amount > v_payment.unallocated_amount then
    raise exception 'Allocation amount % exceeds payment unallocated amount %.', p_amount, v_payment.unallocated_amount;
  end if;

  -- Check invoice remaining due balance
  if p_amount > v_invoice.due_amount then
    raise exception 'Allocation amount % exceeds invoice remaining due balance %.', p_amount, v_invoice.due_amount;
  end if;

  -- Insert allocation record
  insert into public.invoice_payments (tenant_id, payment_id, global_invoice_id, amount)
  values (p_tenant_id, p_payment_id, p_global_invoice_id, p_amount)
  returning * into v_row;

  -- Update payment unallocated amount
  update public.global_payments
  set unallocated_amount = unallocated_amount - p_amount
  where id = p_payment_id;

  -- Update invoice paid amount
  update public.global_invoices
  set paid_amount = coalesce(paid_amount, 0.00) + p_amount, updated_at = now()
  where id = p_global_invoice_id;

  -- Recompute invoice payment status and due_amount
  perform public.recompute_global_invoice_payment_status(p_global_invoice_id);

  return v_row;
end;
$$;


ALTER FUNCTION "public"."allocate_payment_to_global_invoice"("p_tenant_id" bigint, "p_payment_id" bigint, "p_global_invoice_id" bigint, "p_amount" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_cart_item_inventory_reservation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_tenant_id bigint;
begin
  if tg_op = 'INSERT' then
    if new.product_id is null then
      return new;
    end if;

    select tenant_id into v_tenant_id from public.carts where id = new.cart_id;
    perform public.adjust_inventory_reserved_for_product(v_tenant_id, new.product_id, new.quantity);
    return new;
  end if;

  if tg_op = 'UPDATE' then
    select tenant_id into v_tenant_id from public.carts where id = new.cart_id;

    if old.product_id is not null then
      perform public.adjust_inventory_reserved_for_product(v_tenant_id, old.product_id, -old.quantity);
    end if;

    if new.product_id is not null then
      perform public.adjust_inventory_reserved_for_product(v_tenant_id, new.product_id, new.quantity);
    end if;

    return new;
  end if;

  if tg_op = 'DELETE' then
    if old.product_id is null then
      return old;
    end if;

    select tenant_id into v_tenant_id from public.carts where id = old.cart_id;
    perform public.adjust_inventory_reserved_for_product(v_tenant_id, old.product_id, -old.quantity);
    return old;
  end if;

  return null;
end;
$$;


ALTER FUNCTION "public"."apply_cart_item_inventory_reservation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_costing_item_calculations"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_cargo_rate_1kg numeric(12,2);
  v_cargo_rate_2kg numeric(12,2);
  v_conversion_rate numeric(12,2);
  v_admin_profit_rate numeric(12,2);
  v_total_weight integer;
  v_auxiliary_price_gbp numeric(12,2);
  v_item_price_gbp numeric(12,2);
  v_cargo_rate numeric(12,2);
  v_costing_price_gbp numeric(12,2);
  v_costing_price_bdt integer;
  v_calculated_offer_price_bdt integer;
begin
  select
    cf.cargo_rate_1kg,
    cf.cargo_rate_2kg,
    cf.conversion_rate,
    cf.admin_profit_rate
  into
    v_cargo_rate_1kg,
    v_cargo_rate_2kg,
    v_conversion_rate,
    v_admin_profit_rate
  from public.costing_files cf
  where cf.id = new.costing_file_id;

  v_total_weight := coalesce(new.product_weight, 0) + coalesce(new.package_weight, 0);
  v_auxiliary_price_gbp := public.calculate_costing_auxiliary_price_gbp(
    new.price_in_web_gbp,
    new.delivery_price_gbp
  )::numeric(12,2);

  v_item_price_gbp := round(
    (
      coalesce(new.price_in_web_gbp, 0)
      + coalesce(new.delivery_price_gbp, 0)
      + coalesce(v_auxiliary_price_gbp, 0)
    )::numeric,
    2
  );

  if coalesce(new.cargo_rate_is_manual, false) and new.cargo_rate is not null then
    v_cargo_rate := round(new.cargo_rate::numeric, 2);
  elsif v_item_price_gbp > 10 then
    v_cargo_rate := coalesce(v_cargo_rate_2kg, 0);
  else
    v_cargo_rate := coalesce(v_cargo_rate_1kg, 0);
  end if;

  v_cargo_rate := round(v_cargo_rate::numeric, 2);

  v_costing_price_gbp := round(
    (
      coalesce(v_item_price_gbp, 0)
      + (coalesce(v_total_weight, 0) / 1000.0) * coalesce(v_cargo_rate, 0)
    )::numeric,
    2
  );

  v_costing_price_bdt := public.round_bdt_up_to_zero_or_five(
    coalesce(v_costing_price_gbp, 0) * coalesce(v_conversion_rate, 0)
  );

  v_calculated_offer_price_bdt := public.round_bdt_up_to_zero_or_five(
    v_costing_price_bdt + (v_costing_price_bdt * coalesce(v_admin_profit_rate, 0) / 100.0)
  );

  new.auxiliary_price_gbp := v_auxiliary_price_gbp;
  new.item_price_gbp := v_item_price_gbp;
  new.cargo_rate := v_cargo_rate;
  new.costing_price_gbp := v_costing_price_gbp;
  new.costing_price_bdt := v_costing_price_bdt;
  new.offer_price_bdt := coalesce(new.offer_price_override_bdt, v_calculated_offer_price_bdt);

  return new;
end;
$$;


ALTER FUNCTION "public"."apply_costing_item_calculations"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_dropship_order_charge_lines"("p_order_id" bigint, "p_charge_lines" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_line jsonb;
  v_delivery_amount numeric(12,2);
  v_print_amount numeric(12,2);
  v_packing_amount numeric(12,2);
  v_cod_amount numeric(12,2);
  v_deduct_delivery boolean;
  v_deduct_print boolean;
  v_deduct_packing boolean;
  v_deduct_cod boolean;
  v_has_delivery boolean := false;
  v_has_print boolean := false;
  v_has_packing boolean := false;
  v_has_cod boolean := false;
begin
  if p_charge_lines is null or jsonb_typeof(p_charge_lines) <> 'array' then
    return;
  end if;

  for v_line in select value from jsonb_array_elements(p_charge_lines)
  loop
    case coalesce(v_line->>'charge_type', '')
      when 'delivery' then
        v_delivery_amount := greatest(coalesce((v_line->>'amount')::numeric, 0), 0);
        v_deduct_delivery := coalesce(v_line->>'payer', '') = 'merchant';
        v_has_delivery := true;
      when 'print' then
        v_print_amount := greatest(coalesce((v_line->>'amount')::numeric, 0), 0);
        v_deduct_print := coalesce(v_line->>'payer', '') = 'merchant';
        v_has_print := true;
      when 'packing' then
        v_packing_amount := greatest(coalesce((v_line->>'amount')::numeric, 0), 0);
        v_deduct_packing := coalesce(v_line->>'payer', '') = 'merchant';
        v_has_packing := true;
      when 'cod' then
        v_cod_amount := greatest(coalesce((v_line->>'amount')::numeric, 0), 0);
        v_deduct_cod := coalesce(v_line->>'payer', '') = 'merchant';
        v_has_cod := true;
      else
        null;
    end case;
  end loop;

  if not (v_has_delivery or v_has_print or v_has_packing or v_has_cod) then
    return;
  end if;

  update public.shop_orders o
  set
    delivery_charge_amount = case when v_has_delivery then v_delivery_amount else o.delivery_charge_amount end,
    print_charge_amount = case when v_has_print then v_print_amount else o.print_charge_amount end,
    packing_charge_amount = case when v_has_packing then v_packing_amount else o.packing_charge_amount end,
    cod_charge_amount = case when v_has_cod then v_cod_amount else o.cod_charge_amount end,
    deduct_delivery_from_margin = case when v_has_delivery then v_deduct_delivery else o.deduct_delivery_from_margin end,
    deduct_print_from_margin = case when v_has_print then v_deduct_print else o.deduct_print_from_margin end,
    deduct_packing_from_margin = case when v_has_packing then v_deduct_packing else o.deduct_packing_from_margin end,
    deduct_cod_from_margin = case when v_has_cod then v_deduct_cod else o.deduct_cod_from_margin end,
    updated_at = now()
  where o.id = p_order_id;

  if not found then
    raise exception 'order not found';
  end if;
end;
$$;


ALTER FUNCTION "public"."apply_dropship_order_charge_lines"("p_order_id" bigint, "p_charge_lines" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_dropship_payout_settlement_fifo"("p_tenant_id" bigint, "p_billing_profile_id" bigint, "p_amount" numeric) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_remaining numeric := greatest(coalesce(p_amount, 0), 0);
  v_parent_tenant_id bigint;
  r record;
  v_hold numeric;
  v_paid numeric;
  v_outstanding numeric;
begin
  if v_remaining <= 0 then
    return;
  end if;

  v_parent_tenant_id := public.resolve_parent_tenant_id(p_tenant_id);

  for r in
    select o.id
    from public.shop_orders o
    where o.tenant_id = p_tenant_id
      and o.billing_profile_id = p_billing_profile_id
      and o.shop_type_snapshot = 'dropship'
      and o.global_invoice_id is not null
      and coalesce(o.payout_settlement_status, 'unpaid') in ('unpaid', 'partial')
    order by o.created_at asc, o.id asc
  loop
    exit when v_remaining <= 0;

    select coalesce(sum(u.amount), 0)
    into v_hold
    from public.universal_wallet_ledger u
    where u.parent_tenant_id = v_parent_tenant_id
      and u.source_type = 'shop_order'
      and u.source_id = r.id::text
      and u.entity_type in ('middleman', 'customer')
      and u.type = 'credit'
      and coalesce(u.metadata->>'transaction_type', '') = 'dropship_profit';

    select coalesce(sum(u.amount), 0)
    into v_paid
    from public.universal_wallet_ledger u
    where u.parent_tenant_id = v_parent_tenant_id
      and u.entity_type in ('middleman', 'customer')
      and u.entity_id = p_billing_profile_id
      and u.type = 'debit'
      and coalesce(u.metadata->>'transaction_type', '') = 'profit_paid_out'
      and coalesce(u.metadata->>'shop_order_id', u.metadata->>'order_id', '') = r.id::text;

    v_outstanding := greatest(v_hold - v_paid, 0);

    if v_outstanding <= 0 then
      continue;
    end if;

    if v_remaining >= v_outstanding then
      update public.shop_orders
      set payout_settlement_status = 'paid',
          updated_at = now()
      where id = r.id;
      v_remaining := v_remaining - v_outstanding;
    else
      update public.shop_orders
      set payout_settlement_status = 'partial',
          updated_at = now()
      where id = r.id;
      v_remaining := 0;
    end if;
  end loop;
end;
$$;


ALTER FUNCTION "public"."apply_dropship_payout_settlement_fifo"("p_tenant_id" bigint, "p_billing_profile_id" bigint, "p_amount" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_dropship_reseller_unit_purchase"("p_order_id" bigint, "p_unit_sell_price_amount" numeric) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if p_unit_sell_price_amount is null or p_unit_sell_price_amount < 0 then
    raise exception 'reseller unit purchase cost must be zero or positive';
  end if;

  update public.shop_order_items soi
  set
    unit_sell_price_amount = p_unit_sell_price_amount,
    updated_at = now()
  where soi.order_id = p_order_id;

  if not found then
    raise exception 'order has no line items';
  end if;
end;
$$;


ALTER FUNCTION "public"."apply_dropship_reseller_unit_purchase"("p_order_id" bigint, "p_unit_sell_price_amount" numeric) OWNER TO "postgres";


