CREATE OR REPLACE FUNCTION "public"."bulk_apply_shop_markup"("p_shop_id" bigint, "p_markup_percentage" numeric DEFAULT NULL::numeric, "p_listing_ids" bigint[] DEFAULT NULL::bigint[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_tenant_id bigint;
  v_markup numeric;
  v_count integer := 0;
begin
  select tenant_id into v_tenant_id from public.shops where id = p_shop_id;
  if v_tenant_id is null then
    raise exception 'shop not found';
  end if;

  if not public.user_can_manage_shop_tenant(v_tenant_id) then
    raise exception 'not allowed';
  end if;

  -- Use provided markup or lookup from rule
  v_markup := p_markup_percentage;
  if v_markup is null then
    select markup_percentage into v_markup
    from public.shop_pricing_rules
    where shop_id = p_shop_id;
  end if;

  v_markup := coalesce(v_markup, 0.00);

  update public.shop_product_listings spl
  set
    sell_price_amount = round(
      coalesce(spl.minimum_sell_price_amount, spl.sell_price_amount) * (1 + (v_markup / 100.0)),
      2
    ),
    updated_at = now()
  where spl.shop_id = p_shop_id
    and (p_listing_ids is null or spl.id = any(p_listing_ids));

  get diagnostics v_count = row_count;
  return v_count;
end;
$$;


ALTER FUNCTION "public"."bulk_apply_shop_markup"("p_shop_id" bigint, "p_markup_percentage" numeric, "p_listing_ids" bigint[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bulk_apply_shop_markup"("p_shop_id" bigint, "p_markup_amount" numeric DEFAULT NULL::numeric, "p_markup_type" "text" DEFAULT 'percentage'::"text", "p_target_price" "text" DEFAULT 'sell_price'::"text", "p_listing_ids" bigint[] DEFAULT NULL::bigint[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_tenant_id bigint;
  v_amount numeric;
  v_count integer := 0;
begin
  select tenant_id into v_tenant_id from public.shops where id = p_shop_id;
  if v_tenant_id is null then
    raise exception 'shop not found';
  end if;

  if not public.user_can_manage_shop_tenant(v_tenant_id) then
    raise exception 'not allowed';
  end if;

  v_amount := p_markup_amount;
  if v_amount is null then
    select markup_percentage into v_amount
    from public.shop_pricing_rules
    where shop_id = p_shop_id;
  end if;

  v_amount := coalesce(v_amount, 0.00);

  if p_target_price = 'min_sell_price' then
    update public.shop_product_listings spl
    set
      minimum_sell_price_amount = case
        when p_markup_type = 'percentage' then
          round(coalesce(spl.minimum_sell_price_amount, 0.00) * (1 + (v_amount / 100.0)), 2)
        else
          round(coalesce(spl.minimum_sell_price_amount, 0.00) + v_amount, 2)
      end,
      updated_at = now()
    where spl.shop_id = p_shop_id
      and (p_listing_ids is null or spl.id = any(p_listing_ids))
      and spl.is_price_locked is false;
  else
    update public.shop_product_listings spl
    set
      sell_price_amount = case
        when p_markup_type = 'percentage' then
          round(coalesce(spl.minimum_sell_price_amount, spl.sell_price_amount) * (1 + (v_amount / 100.0)), 2)
        else
          round(coalesce(spl.minimum_sell_price_amount, spl.sell_price_amount) + v_amount, 2)
      end,
      updated_at = now()
    where spl.shop_id = p_shop_id
      and (p_listing_ids is null or spl.id = any(p_listing_ids))
      and spl.is_price_locked is false;
  end if;

  get diagnostics v_count = row_count;
  return v_count;
end;
$$;


ALTER FUNCTION "public"."bulk_apply_shop_markup"("p_shop_id" bigint, "p_markup_amount" numeric, "p_markup_type" "text", "p_target_price" "text", "p_listing_ids" bigint[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bulk_delete_global_shipment_items"("p_shipment_id" bigint, "p_item_ids" bigint[]) RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_parent bigint;
  v_deleted_count bigint;
  v_ref_count bigint;
begin
  if p_shipment_id is null then
    raise exception 'shipment_id is required';
  end if;

  if p_item_ids is null or array_length(p_item_ids, 1) is null or array_length(p_item_ids, 1) = 0 then
    return 0;
  end if;

  -- 1. Check parent tenant & permissions
  select parent_tenant_id into v_parent
  from public.global_shipments
  where id = p_shipment_id;

  if v_parent is null then
    raise exception 'shipment not found';
  end if;

  if not (
    public.user_can_manage_parent_tenant(v_parent)
    or exists (
      select 1 from public.memberships m
      where m.tenant_id = v_parent
        and lower(trim(m.email)) = public.current_user_email()
        and m.is_active = true
    )
  ) then
    raise exception 'not allowed';
  end if;

  -- 2. Verify none of the items are referenced in warehouse stocks
  select count(*) into v_ref_count
  from public.global_stocks
  where shipment_item_id = any(p_item_ids);

  if v_ref_count > 0 then
    raise exception 'One or more selected items cannot be deleted because they are referenced in Warehouse Stock.';
  end if;

  -- 3. Delete items in bulk atomically
  with deleted as (
    delete from public.global_shipment_items
    where shipment_id = p_shipment_id
      and id = any(p_item_ids)
    returning id
  )
  select count(*) into v_deleted_count from deleted;

  return v_deleted_count;
end;
$$;


ALTER FUNCTION "public"."bulk_delete_global_shipment_items"("p_shipment_id" bigint, "p_item_ids" bigint[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bulk_delete_shipment_items_by_product_id"("p_shipment_id" bigint, "p_items" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_entry jsonb;
  v_product_id bigint;
  v_quantity integer;
  v_item_id bigint;
  v_deleted_count integer := 0;
begin
  if not public.can_manage_shipment_by_id(p_shipment_id) then
    raise exception 'not allowed';
  end if;

  if p_items is null or jsonb_typeof(p_items) <> 'array' then
    raise exception 'p_items must be a json array';
  end if;

  for v_entry in
    select value
    from jsonb_array_elements(p_items)
  loop
    v_product_id := nullif(trim(coalesce(v_entry ->> 'product_id', '')), '')::bigint;
    v_quantity := coalesce(nullif(trim(coalesce(v_entry ->> 'quantity', '')), '')::integer, 0);

    if v_product_id is null or v_quantity <= 0 then
      continue;
    end if;

    select id into v_item_id
    from public.shipment_items
    where shipment_id = p_shipment_id
      and product_id = v_product_id;

    if v_item_id is null then
      continue;
    end if;

    perform public.delete_shipment_item_quantity(v_item_id, v_quantity);
    v_deleted_count := v_deleted_count + 1;
  end loop;

  return v_deleted_count;
end;
$$;


ALTER FUNCTION "public"."bulk_delete_shipment_items_by_product_id"("p_shipment_id" bigint, "p_items" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bulk_update_global_shipment_items"("p_shipment_id" bigint, "p_updates" "jsonb") RETURNS SETOF "public"."global_shipment_items"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_update jsonb;
  v_id bigint;
  v_ship public.global_shipments%ROWTYPE;
BEGIN
  IF p_shipment_id IS NULL THEN
    RAISE EXCEPTION 'shipment_id is required';
  END IF;

  SELECT * INTO v_ship
  FROM public.global_shipments
  WHERE id = p_shipment_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'shipment not found';
  END IF;

  IF NOT public.user_can_manage_parent_tenant(v_ship.parent_tenant_id) THEN
    RAISE EXCEPTION 'not allowed';
  END IF;

  IF public.global_shipment_costs_are_locked(v_ship) THEN
    RAISE EXCEPTION 'shipment costs are locked';
  END IF;

  PERFORM set_config('app.skip_item_landed_restamp', '1', true);

  FOR v_update IN SELECT * FROM jsonb_array_elements(p_updates)
  LOOP
    v_id := (v_update->>'id')::bigint;
    IF v_id IS NOT NULL THEN
      UPDATE public.global_shipment_items
      SET
        section_id = CASE
          WHEN v_update ? 'section_id' THEN nullif((v_update->>'section_id'), '')::bigint
          ELSE section_id
        END,
        vendor_id = CASE
          WHEN v_update ? 'vendor_id' THEN nullif((v_update->>'vendor_id'), '')::bigint
          ELSE vendor_id
        END,
        ordered_quantity = CASE
          WHEN v_update ? 'ordered_quantity' AND (v_update->>'ordered_quantity') IS NOT NULL THEN greatest(1, (v_update->>'ordered_quantity')::integer)
          ELSE ordered_quantity
        END,
        purchase_price = CASE
          WHEN v_update ? 'purchase_price' AND (v_update->>'purchase_price') IS NOT NULL THEN greatest(0, (v_update->>'purchase_price')::numeric)
          ELSE purchase_price
        END,
        product_weight = CASE
          WHEN v_update ? 'product_weight' AND (v_update->>'product_weight') IS NOT NULL THEN greatest(0, (v_update->>'product_weight')::numeric)
          ELSE product_weight
        END,
        package_weight = CASE
          WHEN v_update ? 'package_weight' AND (v_update->>'package_weight') IS NOT NULL THEN greatest(0, (v_update->>'package_weight')::numeric)
          ELSE package_weight
        END,
        barcode = CASE
          WHEN v_update ? 'barcode' THEN v_update->>'barcode'
          ELSE barcode
        END,
        product_code = CASE
          WHEN v_update ? 'product_code' THEN v_update->>'product_code'
          ELSE product_code
        END,
        name = CASE
          WHEN v_update ? 'name' AND (v_update->>'name') IS NOT NULL THEN v_update->>'name'
          ELSE name
        END,
        updated_at = now()
      WHERE id = v_id AND shipment_id = p_shipment_id;
    END IF;
  END LOOP;

  PERFORM set_config('app.skip_item_landed_restamp', '0', true);

  IF EXISTS (SELECT 1 FROM public.global_shipment_items WHERE shipment_id = p_shipment_id) THEN
    PERFORM public.stamp_global_shipment_landed_costs(p_shipment_id);
  END IF;

  RETURN QUERY
  SELECT *
  FROM public.global_shipment_items
  WHERE shipment_id = p_shipment_id
  ORDER BY sort_order ASC, id ASC;
END;
$$;


ALTER FUNCTION "public"."bulk_update_global_shipment_items"("p_shipment_id" bigint, "p_updates" "jsonb") OWNER TO "postgres";


