    AS $$
declare
  v_normalized_type text;
begin
  v_normalized_type := lower(trim(coalesce(p_item_type, '')));

  if v_normalized_type in ('watch', 'perfume') then
    return 3;
  end if;

  return 0;
end;
$$;


