CREATE OR REPLACE FUNCTION "public"."calculate_landed_unit_cost"("p_shipment_item_id" bigint) RETURNS numeric
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_stamp numeric;
  v_shipment_id bigint;
  v_shipment_type public.global_shipment_type;

  v_purchase_price numeric;
  v_product_weight numeric;
  v_package_weight numeric;
  v_qty numeric;

  v_total_packaging_weight_kg numeric := 0;
  v_line_gross_weight_kg numeric;
  v_line_cargo_share numeric := 0;
  v_line_purchase_base numeric;
  v_effective_rate numeric := 1;
  v_landed_cost numeric;
  v_total_qty numeric;

  v_product_amount numeric := 0;
  v_cargo_amount numeric := 0;
  v_goods_bdt numeric := 0;
  v_cargo_bdt numeric := 0;
begin
  select
    shipment_id,
    purchase_price,
    product_weight,
    package_weight,
    ordered_quantity,
    landed_cost_bdt
  into
    v_shipment_id,
    v_purchase_price,
    v_product_weight,
    v_package_weight,
    v_qty,
    v_stamp
  from public.global_shipment_items
  where id = p_shipment_item_id;

  if v_shipment_id is null then
    return 0.00;
  end if;

  if v_stamp is not null then
    return round(v_stamp::numeric, 4);
  end if;

  select type
  into v_shipment_type
  from public.global_shipments
  where id = v_shipment_id;

  select
    coalesce(sum(amount) filter (where cost_type = 'product'), 0),
    coalesce(sum(amount * exchange_rate) filter (where cost_type = 'product'), 0),
    coalesce(sum(amount) filter (where cost_type != 'product'), 0),
    coalesce(sum(amount * exchange_rate) filter (where cost_type != 'product'), 0)
  into v_product_amount, v_goods_bdt, v_cargo_amount, v_cargo_bdt
  from public.global_shipment_cost_entries
  where shipment_id = v_shipment_id;

  select coalesce(sum(((product_weight + package_weight) * ordered_quantity) / 1000.0), 0)
  into v_total_packaging_weight_kg
  from public.global_shipment_items
  where shipment_id = v_shipment_id;

  v_line_gross_weight_kg := ((coalesce(v_product_weight, 0) + coalesce(v_package_weight, 0)) * coalesce(v_qty, 0)) / 1000.0;

  if v_qty > 0 and v_cargo_amount > 0 then
    if v_total_packaging_weight_kg > 0 then
      v_line_cargo_share := ((v_line_gross_weight_kg / v_total_packaging_weight_kg) * v_cargo_amount) / v_qty;
    else
      select coalesce(sum(ordered_quantity), 0) into v_total_qty
      from public.global_shipment_items
      where shipment_id = v_shipment_id;
      if v_total_qty > 0 then
        v_line_cargo_share := ((v_qty / v_total_qty) * v_cargo_amount) / v_qty;
      end if;
    end if;
  end if;

  v_line_purchase_base := coalesce(v_purchase_price, 0) + coalesce(v_line_cargo_share, 0);

  if v_shipment_type::text in ('local', 'domestic') then
    return round(v_line_purchase_base::numeric, 4);
  end if;

  if (v_product_amount + v_cargo_amount) > 0 then
    v_effective_rate := (v_goods_bdt + v_cargo_bdt) / (v_product_amount + v_cargo_amount);
  else
    v_effective_rate := 1.0;
  end if;

  v_landed_cost := v_line_purchase_base * v_effective_rate;
  return round(v_landed_cost::numeric, 4);
end;
$$;


ALTER FUNCTION "public"."calculate_landed_unit_cost"("p_shipment_item_id" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."calculate_landed_unit_cost"("p_shipment_item_id" bigint) IS 'Unit cost: prefer global_shipment_items.landed_cost_bdt stamp; else legacy header-rate formula for drafts.';



CREATE OR REPLACE FUNCTION "public"."calculate_thrift_invoice_total"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
declare
  v_invoice_id bigint;
begin
  if tg_op = 'DELETE' then
    v_invoice_id := old.invoice_id;
  else
    v_invoice_id := new.invoice_id;
  end if;

  update public.thrift_invoices
  set total_invoice_amount = coalesce((
    select sum(sold_price * quantity)
    from public.thrift_invoice_items
    where invoice_id = v_invoice_id
  ), 0.00) 
  + cod_charge 
  + packing_charge 
  + invoice_print_charge 
  + shipping_charge_customer
  where id = v_invoice_id;

  return null;
end;
$$;


ALTER FUNCTION "public"."calculate_thrift_invoice_total"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_thrift_item_net_profit"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_landed numeric(12, 2);
begin
  if tg_op = 'INSERT' or new.landed_unit_cost_at_sale is null or new.landed_unit_cost_at_sale = 0 then
    v_landed := coalesce(public.compute_thrift_landed_unit_cost(new.stock_id), 0.00);
    new.landed_unit_cost_at_sale := v_landed;
  else
    v_landed := new.landed_unit_cost_at_sale;
  end if;

  new.net_profit := (new.sold_price - v_landed) * new.quantity
                    - new.platform_fees
                    - new.shipping_cost_paid_by_shop;

  return new;
end;
$$;


ALTER FUNCTION "public"."calculate_thrift_item_net_profit"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_access_demand_bucket_profile"("p_tenant_id" bigint, "p_billing_profile_id" bigint, "p_staff_only" boolean DEFAULT false) RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_profile record;
  v_is_parent boolean;
begin
  if p_tenant_id is null or p_billing_profile_id is null then
    return false;
  end if;

  select bp.id, bp.tenant_id, bp.customer_group_id
  into v_profile
  from public.billing_profiles bp
  where bp.id = p_billing_profile_id;

  if not found then
    return false;
  end if;

  if v_profile.tenant_id <> p_tenant_id then
    if not exists (
      select 1
      from public.tenants t
      where t.id = v_profile.tenant_id
        and t.parent_id = p_tenant_id
    ) then
      return false;
    end if;
  end if;

  select (t.parent_id is null) into v_is_parent
  from public.tenants t
  where t.id = p_tenant_id;

  if coalesce(v_is_parent, false) then
    if public.user_can_manage_parent_tenant(p_tenant_id) then
      return true;
    end if;
  elsif public.is_tenant_staff(p_tenant_id)
     or public.is_tenant_staff(v_profile.tenant_id) then
    return true;
  end if;

  if p_staff_only then
    return false;
  end if;

  if v_profile.customer_group_id is not null
     and public.is_customer_group_member(v_profile.customer_group_id) then
    return exists (
      select 1
      from public.customer_groups cg
      where cg.id = v_profile.customer_group_id
        and cg.is_active = true
        and cg.deleted_at is null
        and coalesce(cg.parent_tenant_id, cg.tenant_id) = public.resolve_parent_tenant_id(p_tenant_id)
        and (
          p_tenant_id = coalesce(cg.parent_tenant_id, cg.tenant_id)
          or exists (
            select 1
            from public.shop_customer_group_access scga
            inner join public.shops s on s.id = scga.shop_id
            where scga.customer_group_id = cg.id
              and scga.status = true
              and s.tenant_id = p_tenant_id
              and s.is_active = true
              and s.deleted_at is null
          )
        )
    );
  end if;

  return false;
end;
$$;


ALTER FUNCTION "public"."can_access_demand_bucket_profile"("p_tenant_id" bigint, "p_billing_profile_id" bigint, "p_staff_only" boolean) OWNER TO "postgres";


