CREATE OR REPLACE FUNCTION "public"."cancel_demand_bucket_item"("p_bucket_item_id" bigint) RETURNS "public"."customer_demand_bucket_items"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_row public.customer_demand_bucket_items;
begin
  select * into v_row
  from public.customer_demand_bucket_items
  where id = p_bucket_item_id;

  if not found then
    raise exception 'bucket item not found: %', p_bucket_item_id;
  end if;

  if v_row.status <> 'open' then
    raise exception 'bucket item % is not open', p_bucket_item_id;
  end if;

  if not public.can_access_demand_bucket_profile(v_row.tenant_id, v_row.billing_profile_id, true) then
    raise exception 'access denied';
  end if;

  update public.customer_demand_bucket_items
  set
    status = 'cancelled',
    updated_at = now()
  where id = p_bucket_item_id
  returning * into v_row;

  return v_row;
end;
$$;


ALTER FUNCTION "public"."cancel_demand_bucket_item"("p_bucket_item_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_shop_order_dropship"("p_order_id" bigint, "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_order public.shop_orders%rowtype;
  v_invoice public.global_invoices%rowtype;
  v_allowed boolean := false;
  v_pick_count integer := 0;
  v_released_picks integer := 0;
begin
  select * into v_order from public.shop_orders where id = p_order_id for update;
  if v_order.id is null then
    return jsonb_build_object('success', false, 'error', 'order not found');
  end if;

  if v_order.shop_type_snapshot <> 'dropship' then
    return jsonb_build_object('success', false, 'error', 'not a dropship order');
  end if;

  if not public.is_tenant_staff(v_order.tenant_id) then
    return jsonb_build_object('success', false, 'error', 'access denied');
  end if;

  v_allowed := v_order.status in (
    'submitted', 'draft', 'placed', 'confirmed', 'processing', 'ready_for_pickup'
  );

  if not v_allowed then
    return jsonb_build_object(
      'success', false,
      'error', format('cannot cancel order in status %s', v_order.status)
    );
  end if;

  select count(*) into v_pick_count
  from public.shop_order_item_stock_picks where order_id = p_order_id;

  if v_order.status = 'ready_for_pickup' and v_order.global_invoice_id is not null then
    select * into v_invoice from public.global_invoices where id = v_order.global_invoice_id;
    if v_invoice.invoice_status = 'issued'::public.global_invoice_status then
      perform public.unpost_global_invoice(v_order.global_invoice_id);
    end if;

    delete from public.universal_wallet_ledger
    where source_type = 'shop_order'
      and (
        source_id = p_order_id::text
        or source_id = v_order.order_no
        or source_id = v_invoice.invoice_no
      )
      and tenant_id = v_order.tenant_id;

    delete from public.global_return_items where invoice_id = v_order.global_invoice_id;
    delete from public.global_invoice_items where invoice_id = v_order.global_invoice_id;
    delete from public.global_invoices where id = v_order.global_invoice_id;

    update public.shop_orders
    set global_invoice_id = null, updated_at = now()
    where id = p_order_id;
  elsif v_order.global_invoice_id is not null then
    select * into v_invoice from public.global_invoices where id = v_order.global_invoice_id;
    if v_invoice.invoice_status in ('draft'::public.global_invoice_status, 'proforma_generated'::public.global_invoice_status) then
      delete from public.global_return_items where invoice_id = v_order.global_invoice_id;
      delete from public.global_invoice_items where invoice_id = v_order.global_invoice_id;
      delete from public.global_invoices where id = v_order.global_invoice_id;
      update public.shop_orders set global_invoice_id = null, updated_at = now() where id = p_order_id;
    end if;
  end if;

  perform public.release_dropship_order_stock(p_order_id, true);
  v_released_picks := v_pick_count;

  delete from public.shop_order_item_stock_picks where order_id = p_order_id;

  update public.shop_order_items
  set
    is_fulfillment_unavailable = false,
    unavailable_reason = null,
    unavailable_at = null,
    unavailable_by_email = null,
    confirmed_quantity = 0,
    global_stock_id = null,
    updated_at = now()
  where order_id = p_order_id;

  update public.shop_orders
  set status = 'cancelled'::public.shop_order_status, updated_at = now()
  where id = p_order_id;

  return jsonb_build_object(
    'success', true,
    'new_status', 'cancelled',
    'restock_summary', jsonb_build_object(
      'pick_rows_released', v_released_picks,
      'reason', nullif(trim(p_reason), '')
    )
  );
end;
$$;


ALTER FUNCTION "public"."cancel_shop_order_dropship"("p_order_id" bigint, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."canonicalize_dropship_order_wallet_source_ids"("p_order_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_order public.shop_orders;
  v_invoice_no text;
  v_parent_tenant_id bigint;
begin
  select * into v_order from public.shop_orders where id = p_order_id;
  if v_order.id is null or v_order.shop_type_snapshot <> 'dropship' then
    return;
  end if;

  v_parent_tenant_id := public.resolve_parent_tenant_id(v_order.tenant_id);
  v_invoice_no := 'INV-DS-' || v_order.order_no;

  update public.universal_wallet_ledger u
  set
    source_id = p_order_id::text,
    metadata = coalesce(u.metadata, '{}'::jsonb)
      || jsonb_build_object('order_id', p_order_id, 'invoice_no', v_invoice_no)
  where u.source_type = 'shop_order'
    and u.parent_tenant_id = v_parent_tenant_id
    and u.source_id in (v_invoice_no, v_order.order_no);

  if v_order.global_invoice_id is not null then
    update public.universal_wallet_ledger u
    set
      source_id = p_order_id::text,
      metadata = coalesce(u.metadata, '{}'::jsonb)
        || jsonb_build_object('order_id', p_order_id, 'invoice_id', v_order.global_invoice_id)
    from public.global_invoices i
    where i.id = v_order.global_invoice_id
      and u.source_type = 'shop_order'
      and u.parent_tenant_id = v_parent_tenant_id
      and u.source_id = i.invoice_no;
  end if;
end;
$$;


ALTER FUNCTION "public"."canonicalize_dropship_order_wallet_source_ids"("p_order_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ceil_thrift_retail_price"("p_price" numeric) RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE PARALLEL SAFE
    AS $$
DECLARE
  n numeric;
  century numeric;
  ending numeric;
  candidate numeric;
BEGIN
  IF p_price IS NULL OR p_price <= 0 THEN
    RETURN 50;
  END IF;

  n := ceil(p_price);
  century := floor(n / 100) * 100;

  LOOP
    FOREACH ending IN ARRAY ARRAY[50, 90]::numeric[] LOOP
      candidate := century + ending;
      IF candidate >= n THEN
        RETURN candidate;
      END IF;
    END LOOP;
    century := century + 100;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."ceil_thrift_retail_price"("p_price" numeric) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ceil_thrift_retail_price"("p_price" numeric) IS 'Ceil to next thrift retail ending (.50 / .90); matches web ceilThriftRetailPrice.';



CREATE OR REPLACE FUNCTION "public"."check_login_membership"("p_email" "text", "p_scope" "text") RETURNS TABLE("has_match" boolean, "matched_role" "public"."app_role", "member_id" bigint, "member_email" "text", "member_tenant_id" bigint, "member_is_active" boolean, "member_created_at" timestamp with time zone, "member_updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_roles public.app_role[];
  v_email text;
begin
  case lower(coalesce(p_scope, ''))
    when 'platform' then
      v_roles := array['superadmin'::public.app_role];
    when 'app' then
      v_roles := array[
        'owner'::public.app_role,
        'manager'::public.app_role,
        'staff'::public.app_role,
        'viewer'::public.app_role
      ];
    else
      v_roles := array[]::public.app_role[];
  end case;

  v_email := lower(trim(coalesce(p_email, auth.jwt() ->> 'email', '')));

  select
    m.role,
    m.id,
    m.email,
    m.tenant_id,
    m.is_active,
    m.created_at,
    m.updated_at
  into
    matched_role,
    member_id,
    member_email,
    member_tenant_id,
    member_is_active,
    member_created_at,
    member_updated_at
  from public.memberships m
  where lower(trim(m.email)) = v_email
    and m.is_active = true
    and m.role = any(v_roles)
  order by
    case m.role
      when 'owner' then 1
      when 'manager' then 2
      when 'staff' then 3
      when 'viewer' then 4
      else 99
    end,
    m.id asc
  limit 1;

  has_match := matched_role is not null;
  return next;
end;
$$;


ALTER FUNCTION "public"."check_login_membership"("p_email" "text", "p_scope" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_shop_login_access"("p_email" "text", "p_tenant_id" bigint DEFAULT NULL::bigint) RETURNS TABLE("has_match" boolean, "matched_role" "public"."customer_group_role", "member_id" bigint, "member_name" "text", "member_email" "text", "member_tenant_id" bigint, "customer_group_id" bigint, "customer_group_name" "text", "member_is_active" boolean, "customer_group_is_active" boolean, "member_created_at" timestamp with time zone, "member_updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_email text;
begin
  v_email := lower(trim(coalesce(p_email, public.current_user_email(), '')));

  return query
  select
    true,
    cgm.role,
    cgm.id,
    coalesce(
      nullif(trim(cgm.name), ''),
      (select coalesce(u.raw_user_meta_data->>'full_name', u.raw_user_meta_data->>'name') from auth.users u where u.email = v_email limit 1)
    ),
    lower(trim(cgm.email)),
    cg.tenant_id,
    cg.id,
    cg.name,
    cgm.is_active,
    cg.is_active,
    cgm.created_at,
    cgm.updated_at
  from public.customer_group_members cgm
  inner join public.customer_groups cg
    on cg.id = cgm.customer_group_id
  where lower(trim(cgm.email)) = v_email
    and cgm.is_active = true
    and cg.is_active = true
    and cg.deleted_at is null
    and (
      p_tenant_id is null
      or exists (
        select 1
        from public.shop_customer_group_access scga
        inner join public.shops s on s.id = scga.shop_id
        where scga.customer_group_id = cg.id
          and scga.status = true
          and s.tenant_id = p_tenant_id
          and s.is_active = true
          and s.deleted_at is null
          and coalesce(cg.parent_tenant_id, cg.tenant_id)
            = public.resolve_parent_tenant_id(p_tenant_id)
      )
    )
  order by
    cg.name asc,
    cg.id asc,
    case cgm.role
      when 'admin' then 1
      when 'manager' then 2
      when 'staff' then 3
      else 99
    end asc,
    cgm.id asc;
end;
$$;


