CREATE OR REPLACE FUNCTION "public"."collect_wholesale_invoice_payment"("p_invoice_id" bigint, "p_cash_amount" numeric DEFAULT 0, "p_cash_method" "text" DEFAULT 'cash'::"text", "p_wallet_amount" numeric DEFAULT 0, "p_settlement_amount" numeric DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_invoice public.sales_invoices;
  v_cash numeric(12,2);
  v_wallet numeric(12,2);
  v_settle numeric(12,2);
  v_due numeric(12,2);
  v_tenant_id bigint;
  v_payment_id bigint;
begin
  if p_invoice_id is null then
    raise exception 'Invoice ID is required';
  end if;

  v_cash := greatest(coalesce(p_cash_amount, 0.00), 0.00);
  v_wallet := greatest(coalesce(p_wallet_amount, 0.00), 0.00);
  v_settle := greatest(coalesce(p_settlement_amount, 0.00), 0.00);

  if v_cash <= 0 and v_wallet <= 0 and v_settle <= 0 then
    raise exception 'Enter cash, store credit, or settlement';
  end if;

  select * into v_invoice
  from public.sales_invoices
  where id = p_invoice_id
  for update;

  if v_invoice.id is null then
    raise exception 'Invoice not found';
  end if;

  if v_invoice.invoice_status <> 'issued'::public.global_invoice_status then
    raise exception 'Payments can only be recorded on issued invoices';
  end if;

  if v_invoice.billing_profile_id is null then
    raise exception 'Billing profile is required';
  end if;

  v_due := coalesce(v_invoice.due_amount, 0.00);
  if (v_cash + v_wallet + v_settle) > v_due then
    raise exception 'Cash + credit + settlement cannot exceed due';
  end if;

  v_tenant_id := coalesce(v_invoice.parent_tenant_id, v_invoice.tenant_id);

  if v_cash > 0 then
    insert into public.global_payments (
      tenant_id, billing_profile_id, amount, unallocated_amount,
      payment_date, method, note
    ) values (
      v_tenant_id, v_invoice.billing_profile_id, v_cash, 0.00,
      current_date, coalesce(nullif(trim(p_cash_method), ''), 'cash'),
      'Wholesale invoice collect (cash)'
    ) returning id into v_payment_id;

    insert into public.invoice_payments (tenant_id, payment_id, global_invoice_id, amount)
    values (v_tenant_id, v_payment_id, p_invoice_id, v_cash);

    update public.sales_invoices
    set paid_amount = coalesce(paid_amount, 0.00) + v_cash, updated_at = now()
    where id = p_invoice_id;

    perform public.recompute_global_invoice_payment_status(p_invoice_id);

    perform public.record_ledger_transaction(
      p_tenant_id => v_tenant_id,
      p_entity_type => 'tenant',
      p_entity_id => v_tenant_id,
      p_type => 'credit',
      p_amount => v_cash,
      p_currency_code => 'BDT',
      p_exchange_rate => 1.000000,
      p_source_type => 'sales_invoice',
      p_source_id => v_payment_id::text,
      p_metadata => jsonb_build_object(
        'section', 'payments',
        'purpose', 'tenant_payment_received',
        'transaction_type', 'payment_received',
        'label', 'Payment Received',
        'invoice_id', p_invoice_id,
        'payment_id', v_payment_id,
        'method', coalesce(nullif(trim(p_cash_method), ''), 'cash')
      )
    );
  end if;

  if v_wallet > 0 then
    insert into public.wallet_accounts (
      tenant_id, entity_type, entity_id, currency_code,
      available_balance, locked_balance, pending_balance
    ) values (
      v_tenant_id, 'customer', v_invoice.billing_profile_id, 'BDT',
      0.0000, 0.0000, 0.0000
    ) on conflict (tenant_id, entity_type, entity_id, currency_code) do nothing;

    insert into public.global_payments (
      tenant_id, billing_profile_id, amount, unallocated_amount,
      payment_date, method, note
    ) values (
      v_tenant_id, v_invoice.billing_profile_id, v_wallet, 0.00,
      current_date, 'wallet_credit',
      'Wholesale invoice collect (store credit)'
    ) returning id into v_payment_id;

    insert into public.invoice_payments (tenant_id, payment_id, global_invoice_id, amount)
    values (v_tenant_id, v_payment_id, p_invoice_id, v_wallet);

    update public.sales_invoices
    set paid_amount = coalesce(paid_amount, 0.00) + v_wallet, updated_at = now()
    where id = p_invoice_id;

    perform public.recompute_global_invoice_payment_status(p_invoice_id);

    perform public.record_ledger_transaction(
      p_tenant_id => v_tenant_id,
      p_entity_type => 'customer',
      p_entity_id => v_invoice.billing_profile_id,
      p_type => 'debit',
      p_amount => v_wallet,
      p_currency_code => 'BDT',
      p_exchange_rate => 1.000000,
      p_source_type => 'sales_invoice',
      p_source_id => v_payment_id::text,
      p_allow_overdraft => false,
      p_metadata => jsonb_build_object(
        'section', 'payments',
        'purpose', 'apply_store_credit',
        'transaction_type', 'wallet_credit',
        'label', 'Applied store credit',
        'invoice_id', p_invoice_id,
        'payment_id', v_payment_id
      )
    );
  end if;

  if v_settle > 0 then
    perform public.apply_global_invoice_settlement_discount(p_invoice_id, v_settle, 'Wholesale collect settlement');
  end if;

  select * into v_invoice from public.sales_invoices where id = p_invoice_id;

  return jsonb_build_object(
    'success', true,
    'invoice_id', v_invoice.id,
    'paid_amount', v_invoice.paid_amount,
    'due_amount', v_invoice.due_amount,
    'payment_status', v_invoice.payment_status,
    'settlement_discount_amount', v_invoice.settlement_discount_amount
  );
end;
$$;


ALTER FUNCTION "public"."collect_wholesale_invoice_payment"("p_invoice_id" bigint, "p_cash_amount" numeric, "p_cash_method" "text", "p_wallet_amount" numeric, "p_settlement_amount" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."compute_dropship_order_reseller_purchase"("p_order_id" bigint) RETURNS TABLE("reseller_unit_purchase_cost" numeric, "reseller_purchase_cost" numeric, "order_item_quantity" integer)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select
    case
      when coalesce(sum(soi.quantity), 0) > 0 then
        coalesce(sum(coalesce(soi.unit_sell_price_amount, 0) * soi.quantity), 0) / sum(soi.quantity)
      else 0::numeric
    end,
    coalesce(sum(coalesce(soi.unit_sell_price_amount, 0) * soi.quantity), 0),
    coalesce(sum(soi.quantity), 0)::integer
  from public.shop_order_items soi
  inner join public.shop_orders o on o.id = soi.order_id
  where soi.order_id = p_order_id;
$$;


ALTER FUNCTION "public"."compute_dropship_order_reseller_purchase"("p_order_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."compute_dropship_settlement_totals"("p_collected_cod" numeric, "p_reseller_purchase_cost" numeric, "p_discount_company_pay" numeric, "p_charge_lines" "jsonb") RETURNS TABLE("total_cost" numeric, "reseller_profit" numeric, "company_profit" numeric, "merchant_paid_charges" numeric)
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
declare
  v_charge_sum numeric := 0;
  v_merchant_paid numeric := 0;
  v_line jsonb;
begin
  if p_charge_lines is not null and jsonb_typeof(p_charge_lines) = 'array' then
    for v_line in select value from jsonb_array_elements(p_charge_lines)
    loop
      v_charge_sum := v_charge_sum + coalesce((v_line->>'amount')::numeric, 0);
      if coalesce(v_line->>'payer', '') = 'merchant' then
        v_merchant_paid := v_merchant_paid + coalesce((v_line->>'amount')::numeric, 0);
      end if;
    end loop;
  end if;

  total_cost := coalesce(p_reseller_purchase_cost, 0) + v_charge_sum;
  merchant_paid_charges := v_merchant_paid;
  reseller_profit := coalesce(p_collected_cod, 0) - coalesce(p_reseller_purchase_cost, 0) - v_merchant_paid;
  company_profit := reseller_profit - coalesce(p_discount_company_pay, 0);
  return next;
end;
$$;


ALTER FUNCTION "public"."compute_dropship_settlement_totals"("p_collected_cod" numeric, "p_reseller_purchase_cost" numeric, "p_discount_company_pay" numeric, "p_charge_lines" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."compute_dropship_settlement_totals"("p_items_resell_total" numeric, "p_order_discount_amount" numeric, "p_reseller_purchase_cost" numeric, "p_company_procurement_cost" numeric, "p_discount_company_pay" numeric, "p_charge_lines" "jsonb") RETURNS TABLE("total_cost" numeric, "reseller_profit" numeric, "company_profit" numeric, "merchant_paid_charges" numeric)
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
declare
  v_charge_sum numeric := 0;
  v_merchant_paid numeric := 0;
  v_line jsonb;
begin
  if p_charge_lines is not null and jsonb_typeof(p_charge_lines) = 'array' then
    for v_line in select value from jsonb_array_elements(p_charge_lines)
    loop
      v_charge_sum := v_charge_sum + coalesce((v_line->>'amount')::numeric, 0);
      if coalesce(v_line->>'payer', '') = 'merchant' then
        v_merchant_paid := v_merchant_paid + coalesce((v_line->>'amount')::numeric, 0);
      end if;
    end loop;
  end if;

  total_cost := coalesce(p_company_procurement_cost, 0) + v_charge_sum;
  merchant_paid_charges := v_merchant_paid;
  reseller_profit :=
    coalesce(p_items_resell_total, 0)
    - coalesce(p_order_discount_amount, 0)
    - coalesce(p_reseller_purchase_cost, 0)
    - v_merchant_paid;
  company_profit :=
    coalesce(p_reseller_purchase_cost, 0)
    - coalesce(p_company_procurement_cost, 0)
    - coalesce(p_discount_company_pay, 0);
  return next;
end;
$$;


ALTER FUNCTION "public"."compute_dropship_settlement_totals"("p_items_resell_total" numeric, "p_order_discount_amount" numeric, "p_reseller_purchase_cost" numeric, "p_company_procurement_cost" numeric, "p_discount_company_pay" numeric, "p_charge_lines" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."compute_thrift_landed_unit_cost"("p_stock_id" bigint) RETURNS numeric
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_stock public.thrift_stocks%ROWTYPE;
  v_shipment public.thrift_shipments%ROWTYPE;
  v_settings public.thrift_settings%ROWTYPE;
  v_sum_qty numeric;
  v_u numeric;
  v_total_weight_kg numeric;
  v_line_weight_kg numeric;
  v_costing_qty numeric;
  v_product_unit_cost numeric;
  v_shipment_cargo_cost numeric;
  v_shipment_ops_cost numeric;
  v_cargo_share_per_unit numeric;
  v_ops_share_per_unit numeric;
  v_landed_unit_cost numeric;
BEGIN
  SELECT * INTO v_stock
  FROM public.thrift_stocks
  WHERE id = p_stock_id;

  IF NOT FOUND THEN
    RETURN 0;
  END IF;

  SELECT * INTO v_shipment
  FROM public.thrift_shipments
  WHERE id = v_stock.shipment_id;

  SELECT * INTO v_settings
  FROM public.thrift_settings
  WHERE tenant_id = v_stock.tenant_id;

  -- Costing qty: SOLD with remaining 0 still counts as 1 unit for allocation.
  v_costing_qty := CASE
    WHEN v_stock.status = 'SOLD'::public.thrift_stock_status
         AND COALESCE(v_stock.quantity, 0) = 0 THEN 1::numeric
    ELSE GREATEST(COALESCE(v_stock.quantity, 0), 0)::numeric
  END;

  SELECT COALESCE(SUM(
    CASE
      WHEN s.status = 'SOLD'::public.thrift_stock_status
           AND COALESCE(s.quantity, 0) = 0 THEN 1::numeric
      ELSE GREATEST(COALESCE(s.quantity, 0), 0)::numeric
    END
  ), 0) INTO v_sum_qty
  FROM public.thrift_stocks s
  WHERE s.shipment_id = v_stock.shipment_id;

  v_u := GREATEST(v_sum_qty, 1.0);

  SELECT COALESCE(SUM(
    (
      (COALESCE(s.product_weight, 0.0) + COALESCE(s.extra_weight, 0.0))
      / 1000.0
    ) * CASE
      WHEN s.status = 'SOLD'::public.thrift_stock_status
           AND COALESCE(s.quantity, 0) = 0 THEN 1::numeric
      ELSE GREATEST(COALESCE(s.quantity, 0), 0)::numeric
    END
  ), 0.0) INTO v_total_weight_kg
  FROM public.thrift_stocks s
  WHERE s.shipment_id = v_stock.shipment_id;

  v_line_weight_kg :=
    (COALESCE(v_stock.product_weight, 0.0) + COALESCE(v_stock.extra_weight, 0.0))
    / 1000.0
    * v_costing_qty;

  v_product_unit_cost :=
    (COALESCE(v_stock.origin_unit_price, 0.0) + COALESCE(v_stock.extra_origin_unit_price, 0.0))
    * COALESCE(v_shipment.product_conversion_rate, 1.0);

  v_shipment_cargo_cost :=
    COALESCE(v_shipment.total_cargo_weight_kg, 0.0)
    * COALESCE(v_shipment.cargo_rate, 0.0)
    * COALESCE(v_shipment.cargo_conversion_rate, 0.0);

  v_shipment_ops_cost :=
    (COALESCE(v_settings.hand_tag_unit_cost, 0.0) * v_u)
    + (COALESCE(v_settings.sticker_unit_cost, 0.0) * v_u)
    + COALESCE(v_shipment.labor_total_cost, 0.0)
    + COALESCE(v_shipment.transportation_total_cost, 0.0)
    + COALESCE(v_shipment.washing_total_cost, 0.0);

  IF v_total_weight_kg > 0 AND v_costing_qty > 0 THEN
    v_cargo_share_per_unit :=
      ((v_line_weight_kg / v_total_weight_kg) * v_shipment_cargo_cost)
      / v_costing_qty;
  ELSE
    v_cargo_share_per_unit := v_shipment_cargo_cost / v_u;
  END IF;

  v_ops_share_per_unit := v_shipment_ops_cost / v_u;

  v_landed_unit_cost :=
    v_product_unit_cost
    + v_cargo_share_per_unit
    + v_ops_share_per_unit
    + COALESCE(v_stock.additional_charges_cost, 0.0);

  RETURN COALESCE(v_landed_unit_cost, 0.0);
END;
$$;


ALTER FUNCTION "public"."compute_thrift_landed_unit_cost"("p_stock_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_courier_remittance_to_tenant"("p_order_id" bigint, "p_courier_charge" numeric DEFAULT 0.00, "p_remittance_ref" "text" DEFAULT NULL::"text", "p_bank_trx_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_order record;
  v_invoice record;
  v_cod numeric(12,2) := 0.00;
  v_charge numeric(12,2) := 0.00;
  v_net_remitted numeric(12,2) := 0.00;
  v_ref text;
begin
  select * into v_order from public.shop_orders where id = p_order_id;
  if v_order.id is null then
    return jsonb_build_object('success', false, 'error', format('Shop order #%s not found', p_order_id));
  end if;

  if v_order.status <> 'delivered' then
    return jsonb_build_object(
      'success', false,
      'error', format('Order #%s status is "%s" (must be "delivered" to remit)', v_order.order_no, v_order.status)
    );
  end if;

  if v_order.global_invoice_id is null then
    perform public.create_dual_invoice_from_dropship_order(p_order_id);
    select * into v_order from public.shop_orders where id = p_order_id;
  end if;

  if v_order.global_invoice_id is not null then
    select * into v_invoice from public.global_invoices where id = v_order.global_invoice_id;
    if v_invoice.id is not null and v_invoice.invoice_status = 'draft'::public.global_invoice_status then
      perform public.post_global_invoice(v_order.global_invoice_id);
    end if;
  end if;

  v_cod := coalesce(v_order.cod_collect_amount, 0.00);
  v_charge := coalesce(p_courier_charge, 0.00);
  v_net_remitted := greatest(v_cod - v_charge, 0.00);
  v_ref := coalesce(nullif(trim(p_remittance_ref), ''), 'REMIT-' || v_order.order_no);

  return public.record_dropship_courier_remittance(
    p_order_id => p_order_id,
    p_net_amount => v_net_remitted,
    p_remittance_ref => v_ref,
    p_bank_trx_id => p_bank_trx_id,
    p_payment_date => current_date,
    p_method => 'cash',
    p_note => null,
    p_courier_charge => v_charge
  );
end;
$$;


ALTER FUNCTION "public"."confirm_courier_remittance_to_tenant"("p_order_id" bigint, "p_courier_charge" numeric, "p_remittance_ref" "text", "p_bank_trx_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_dropship_delivered_costing"("p_order_id" bigint, "p_cod_amount" numeric DEFAULT NULL::numeric, "p_delivery_charge" numeric DEFAULT NULL::numeric, "p_courier_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_order public.shop_orders;
  v_cod numeric(15,4) := 0.0000;
  v_delivery_charge numeric(15,4) := 0.0000;
begin
  select * into v_order
  from public.shop_orders
  where id = p_order_id for update;

  if v_order.id is null then
    return jsonb_build_object('success', false, 'error', format('Shop order #%s not found', p_order_id));
  end if;

  if not (
    public.is_superadmin()
    or exists (
      select 1 from public.memberships m
      where m.tenant_id = v_order.tenant_id
        and lower(trim(m.email)) = public.current_user_email()
        and m.is_active = true
        and m.role in ('admin', 'staff')
    )
  ) then
    return jsonb_build_object('success', false, 'error', format('Permission denied for tenant %s', v_order.tenant_id));
  end if;

  if v_order.status not in ('delivered', 'payment_received') then
    return jsonb_build_object(
      'success', false,
      'error', format('Order #%s status is "%s" (must be delivered or payment_received)', v_order.order_no, v_order.status)
    );
  end if;

  v_cod := coalesce(p_cod_amount, v_order.cod_collect_amount, 0.0000);
  v_delivery_charge := coalesce(p_delivery_charge, v_order.delivery_charge_amount, 0.0000);

  update public.shop_orders
  set
    cod_collect_amount = v_cod,
    delivery_charge_amount = v_delivery_charge,
    driver_notes = coalesce(nullif(trim(p_courier_notes), ''), driver_notes),
    updated_at = now()
  where id = p_order_id;

  return jsonb_build_object(
    'success', true,
    'message', 'Delivered costing fields saved (no cash posted)',
    'order_id', p_order_id,
    'cod_amount', v_cod,
    'delivery_charge', v_delivery_charge
  );
end;
$$;


ALTER FUNCTION "public"."confirm_dropship_delivered_costing"("p_order_id" bigint, "p_cod_amount" numeric, "p_delivery_charge" numeric, "p_courier_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_shop_order"("p_order_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_tenant_id bigint;
  v_is_negotiable boolean;
begin
  select tenant_id, is_negotiable_snapshot into v_tenant_id, v_is_negotiable from public.shop_orders where id = p_order_id;
  
  if v_tenant_id is null then
    raise exception 'order not found';
  end if;

  if not public.is_tenant_staff(v_tenant_id) then
    raise exception 'access denied';
  end if;

  -- Finalize pricing: set final price to staff offer or customer offer
  update public.shop_order_items
  set
    final_price_amount = coalesce(staff_offer_amount, customer_offer_amount, unit_sell_price_amount, unit_list_price_amount),
    final_price_currency_id = coalesce(staff_offer_currency_id, customer_offer_currency_id, unit_sell_price_currency_id, unit_list_price_currency_id)
  where order_id = p_order_id;

  update public.shop_orders
  set
    status = 'confirmed',
    updated_at = now()
  where id = p_order_id;
end;
$$;


ALTER FUNCTION "public"."confirm_shop_order"("p_order_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."convert_wholesale_draft_to_retail"("p_invoice_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_invoice public.global_invoices;
begin
  -- Fetch the invoice
  select * into v_invoice from public.global_invoices where id = p_invoice_id;
  if v_invoice.id is null then 
    raise exception 'Invoice not found'; 
  end if;

  -- Verify it is a wholesale invoice and in draft status
  if v_invoice.invoice_type <> 'wholesale'::public.global_invoice_type then
    raise exception 'Only wholesale invoices can be converted to retail';
  end if;
  
  if v_invoice.invoice_status <> 'draft'::public.global_invoice_status then
    raise exception 'Only draft invoices can be converted to retail';
  end if;

  -- Update invoice type to retail and mode to account
  update public.global_invoices
  set
    invoice_type = 'retail'::public.global_invoice_type,
    retail_billing_mode = 'account'::public.retail_billing_mode,
    updated_at = now()
  where id = p_invoice_id;
end;
$$;


ALTER FUNCTION "public"."convert_wholesale_draft_to_retail"("p_invoice_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."count_costing_files_for_actor"("p_tenant_id" bigint DEFAULT NULL::bigint, "p_customer_group_id" bigint DEFAULT NULL::bigint) RETURNS bigint
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select count(*)
  from public.costing_files cf
  where (
    p_tenant_id is not null
    and cf.tenant_id = p_tenant_id
    and (
      p_customer_group_id is null
      or cf.customer_group_id = p_customer_group_id
    )
    and (
      public.can_admin_manage_costing_file(cf.tenant_id)
      or public.can_staff_access_costing_file(cf.tenant_id)
    )
  )
  or (
    p_customer_group_id is not null
    and p_tenant_id is null
    and cf.customer_group_id = p_customer_group_id
    and public.can_customer_access_costing_file(cf.customer_group_id)
    and (
      cf.status = 'offered'
      or cf.created_by_email = public.current_user_email()
    )
  );
$$;


ALTER FUNCTION "public"."count_costing_files_for_actor"("p_tenant_id" bigint, "p_customer_group_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."count_search_stock_network"("p_context_tenant_id" bigint, "p_mode" "text" DEFAULT 'search'::"text", "p_search" "text" DEFAULT NULL::"text", "p_search_field" "text" DEFAULT NULL::"text", "p_product_id" bigint DEFAULT NULL::bigint, "p_status" "text" DEFAULT 'excellent'::"text", "p_shipment_id" bigint DEFAULT NULL::bigint, "p_exclude_zero_qty" boolean DEFAULT true) RETURNS bigint
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_count bigint;
begin
  select count(*)::bigint into v_count
  from public.search_stock_network(
    p_context_tenant_id := p_context_tenant_id,
    p_mode := p_mode,
    p_search := p_search,
    p_search_field := p_search_field,
    p_product_id := p_product_id,
    p_status := p_status,
    p_shipment_id := p_shipment_id,
    p_exclude_zero_qty := p_exclude_zero_qty,
    p_limit := 100000,
    p_offset := 0
  );
  return coalesce(v_count, 0);
end;
$$;


ALTER FUNCTION "public"."count_search_stock_network"("p_context_tenant_id" bigint, "p_mode" "text", "p_search" "text", "p_search_field" "text", "p_product_id" bigint, "p_status" "text", "p_shipment_id" bigint, "p_exclude_zero_qty" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_and_post_stock_movement"("p_tenant_id" bigint, "p_stock_id" bigint, "p_quantity" integer, "p_to_location_id" bigint DEFAULT NULL::bigint, "p_to_availability" "public"."stock_availability" DEFAULT NULL::"public"."stock_availability", "p_to_grade_tag_id" bigint DEFAULT NULL::bigint, "p_movement_type" "public"."stock_movement_type" DEFAULT 'grade_change'::"public"."stock_movement_type", "p_notes" "text" DEFAULT NULL::"text", "p_reference_type" "text" DEFAULT NULL::"text", "p_reference_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_stock public.global_stocks%rowtype;
  v_mov_id bigint;
  v_mov_no text;
  v_is_customer_return boolean;
begin
  if not public.can_act_on_stock_movement_context(p_tenant_id, p_reference_type, p_reference_id) then
    raise exception 'not authorized';
  end if;

  select * into v_stock
  from public.global_stocks
  where id = p_stock_id
    and parent_tenant_id = p_tenant_id
  for update;

  if not found then
    raise exception 'stock % not found', p_stock_id;
  end if;

  if p_quantity is null or p_quantity <= 0 then
    raise exception 'quantity must be > 0';
  end if;

  v_is_customer_return := (
    p_movement_type = 'return_inbound'::public.stock_movement_type
    and coalesce(p_reference_type, '') is distinct from 'shipment_return'
  );

  if not v_is_customer_return and v_stock.quantity < p_quantity then
    raise exception 'insufficient stock quantity (requested %, available %)', p_quantity, v_stock.quantity;
  end if;

  v_mov_no := 'MOV-' || to_char(now(), 'YYYYMMDD') || '-' || lpad(nextval('public.stock_movements_id_seq')::text, 6, '0');

  insert into public.stock_movements (
    tenant_id,
    movement_no,
    movement_type,
    reference_type,
    reference_id,
    notes,
    created_by_email,
    is_posted,
    posted_at
  ) values (
    p_tenant_id,
    v_mov_no,
    p_movement_type,
    coalesce(p_reference_type, 'global_stock'),
    coalesce(p_reference_id, p_stock_id::text),
    p_notes,
    public.current_user_email(),
    false,
    null
  )
  returning id into v_mov_id;

  insert into public.stock_movement_lines (
    movement_id,
    stock_id,
    quantity,
    from_location_id,
    to_location_id,
    from_availability,
    to_availability,
    from_grade_tag_id,
    to_grade_tag_id
  ) values (
    v_mov_id,
    p_stock_id,
    p_quantity,
    v_stock.location_id,
    case
      when v_is_customer_return then coalesce(
        p_to_location_id,
        public.default_returns_stock_location_id(p_tenant_id)
      )
      else coalesce(p_to_location_id, v_stock.location_id)
    end,
    v_stock.availability,
    case
      when v_is_customer_return then coalesce(p_to_availability, 'held'::public.stock_availability)
      else coalesce(p_to_availability, v_stock.availability)
    end,
    v_stock.grade_tag_id,
    coalesce(p_to_grade_tag_id, v_stock.grade_tag_id, public.default_stock_grade_tag_id())
  );

  perform public.post_stock_movement(v_mov_id);

  return jsonb_build_object(
    'success', true,
    'movement_id', v_mov_id,
    'movement_no', v_mov_no
  );
end;
$$;


ALTER FUNCTION "public"."create_and_post_stock_movement"("p_tenant_id" bigint, "p_stock_id" bigint, "p_quantity" integer, "p_to_location_id" bigint, "p_to_availability" "public"."stock_availability", "p_to_grade_tag_id" bigint, "p_movement_type" "public"."stock_movement_type", "p_notes" "text", "p_reference_type" "text", "p_reference_id" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."global_payments" (
    "id" bigint NOT NULL,
    "tenant_id" bigint NOT NULL,
    "billing_profile_id" bigint,
    "amount" numeric(12,2) NOT NULL,
    "payment_date" "date" DEFAULT CURRENT_DATE NOT NULL,
    "method" "text",
    "reference" "text",
    "note" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "unallocated_amount" numeric(12,2) DEFAULT 0.00 NOT NULL,
    "collection_source" "public"."collection_source_type" DEFAULT 'billing_profile'::"public"."collection_source_type" NOT NULL,
    "customer_group_id" bigint,
    CONSTRAINT "payments_amount_check" CHECK (("amount" > (0)::numeric)),
    CONSTRAINT "payments_method_check" CHECK ((("method" = ANY (ARRAY['cash'::"text", 'bank'::"text", 'bank_transfer'::"text", 'mobile_banking'::"text", 'bkash'::"text", 'nagad'::"text", 'other'::"text"])) OR ("method" IS NULL)))
);


ALTER TABLE "public"."global_payments" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_billing_profile_payment_with_allocations"("p_tenant_id" bigint, "p_billing_profile_id" bigint, "p_amount" numeric, "p_payment_date" "date", "p_method" "text", "p_reference" "text", "p_note" "text", "p_allocations" "jsonb") RETURNS "public"."global_payments"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_payment public.global_payments;
  v_alloc jsonb;
  v_global_invoice_id bigint;
  v_alloc_amount numeric(12,2);
  v_total_alloc numeric(12,2) := 0;
  v_invoice record;
begin
  if p_tenant_id is null or p_billing_profile_id is null then
    raise exception 'Tenant and billing profile are required.';
  end if;
  if coalesce(p_amount, 0) <= 0 then
    raise exception 'Payment amount must be greater than zero.';
  end if;

  insert into public.global_payments (
    tenant_id,
    billing_profile_id,
    amount,
    unallocated_amount,
    payment_date,
    method,
    reference,
    note
  )
  values (
    p_tenant_id,
    p_billing_profile_id,
    p_amount,
    p_amount,
    coalesce(p_payment_date, current_date),
    p_method,
    p_reference,
    p_note
  )
  returning * into v_payment;

  if jsonb_typeof(coalesce(p_allocations, '[]'::jsonb)) <> 'array' then
    raise exception 'Allocations must be an array.';
  end if;

  for v_alloc in select * from jsonb_array_elements(coalesce(p_allocations, '[]'::jsonb))
  loop
    v_global_invoice_id := nullif(v_alloc->>'global_invoice_id', '')::bigint;
    v_alloc_amount := coalesce((v_alloc->>'amount')::numeric, 0.00);

    if v_alloc_amount <= 0.00 then continue; end if;

    if v_global_invoice_id is not null then
      select id, tenant_id, billing_profile_id, total_amount, paid_amount, collection_source
      into v_invoice
      from public.global_invoices where id = v_global_invoice_id for update;

      if not found then raise exception 'Global invoice % not found.', v_global_invoice_id; end if;
      if v_invoice.tenant_id <> p_tenant_id then raise exception 'Invoice tenant mismatch.'; end if;
      if coalesce(v_invoice.billing_profile_id, 0) <> p_billing_profile_id then
        raise exception 'Invoice does not belong to billing profile.';
      end if;

      insert into public.invoice_payments (tenant_id, payment_id, global_invoice_id, amount)
      values (p_tenant_id, v_payment.id, v_global_invoice_id, v_alloc_amount);

      update public.global_invoices
      set paid_amount = coalesce(paid_amount, 0.00) + v_alloc_amount, updated_at = now()
      where id = v_global_invoice_id;

      perform public.recompute_global_invoice_payment_status(v_global_invoice_id);
    end if;

    v_total_alloc := v_total_alloc + v_alloc_amount;
  end loop;

  if v_total_alloc > p_amount then
    raise exception 'Total allocation exceeds payment amount.';
  end if;

  update public.global_payments
  set unallocated_amount = p_amount - v_total_alloc
  where id = v_payment.id
  returning * into v_payment;

  -- Universal Wallet 1: Credit Tenant Cash Available (money received)
  perform public.record_ledger_transaction(
    p_parent_tenant_id => public.resolve_parent_tenant_id(p_tenant_id),
    p_operating_tenant_id => p_tenant_id,
    p_entity_type => 'tenant',
    p_entity_id => public.resolve_parent_tenant_id(p_tenant_id),
    p_type => 'credit',
    p_amount => p_amount,
    p_currency_code => 'BDT',
    p_exchange_rate => 1.000000,
    p_source_type => 'sales_invoice',
    p_source_id => v_payment.id::text,
    p_metadata => jsonb_build_object(
      'section', 'payments',
      'purpose', 'tenant_payment_received',
      'transaction_type', 'payment_received',
      'label', 'Payment Received',
      'payment_id', v_payment.id,
      'billing_profile_id', p_billing_profile_id,
      'reference', p_reference
    )
  );

  -- Universal Wallet 2: Credit Customer Available (reduces Accounts Receivable)
  perform public.record_ledger_transaction(
    p_parent_tenant_id => public.resolve_parent_tenant_id(p_tenant_id),
    p_operating_tenant_id => p_tenant_id,
    p_entity_type => 'customer',
    p_entity_id => p_billing_profile_id,
    p_type => 'credit',
    p_amount => p_amount,
    p_currency_code => 'BDT',
    p_exchange_rate => 1.000000,
    p_source_type => 'sales_invoice',
    p_source_id => v_payment.id::text,
    p_metadata => jsonb_build_object(
      'section', 'payments',
      'purpose', 'customer_ar_reduction',
      'transaction_type', 'payment_received',
      'label', 'Payment Applied',
      'payment_id', v_payment.id,
      'reference', p_reference
    )
  );

  return v_payment;
end;
$$;


ALTER FUNCTION "public"."create_billing_profile_payment_with_allocations"("p_tenant_id" bigint, "p_billing_profile_id" bigint, "p_amount" numeric, "p_payment_date" "date", "p_method" "text", "p_reference" "text", "p_note" "text", "p_allocations" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_cargo_company_with_wallet"("p_tenant_id" bigint, "p_name" "text", "p_code" "text", "p_email" "text" DEFAULT NULL::"text", "p_phone" "text" DEFAULT NULL::"text", "p_address" "text" DEFAULT NULL::"text", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_row public.cargo_companies;
  v_wallet public.wallet_accounts;
  v_code text;
begin
  if p_tenant_id is null then
    raise exception 'p_tenant_id is required';
  end if;

  if not (
    public.is_superadmin()
    or public.user_can_manage_parent_tenant(p_tenant_id)
    or exists (
      select 1
      from public.memberships m
      where m.tenant_id = p_tenant_id
        and lower(trim(m.email)) = public.current_user_email()
        and m.role in ('admin', 'staff')
        and m.is_active = true
    )
  ) then
    raise exception 'not allowed';
  end if;

  if exists (
    select 1 from public.tenants t where t.id = p_tenant_id and t.parent_id is not null
  ) then
    raise exception 'cargo companies belong on parent tenants only';
  end if;

  v_code := upper(trim(p_code));
  if v_code is null or v_code = '' then
    raise exception 'code is required';
  end if;

  if v_code = 'DEFAULT' then
    raise exception 'code DEFAULT is reserved for the system default cargo company';
  end if;

  if nullif(trim(p_name), '') is null then
    raise exception 'name is required';
  end if;

  insert into public.cargo_companies (
    tenant_id,
    parent_tenant_id,
    name,
    code,
    email,
    phone,
    address,
    notes,
    is_default,
    is_active
  )
  values (
    p_tenant_id,
    p_tenant_id,
    trim(p_name),
    v_code,
    nullif(lower(trim(p_email)), ''),
    nullif(trim(p_phone), ''),
    nullif(trim(p_address), ''),
    nullif(trim(p_notes), ''),
    false,
    true
  )
  returning * into v_row;

  insert into public.wallet_accounts (
    tenant_id,
    parent_tenant_id,
    entity_type,
    entity_id,
    currency_code,
    available_balance,
    pending_balance,
    locked_balance
  )
  values (
    p_tenant_id,
    p_tenant_id,
    'cargo_company',
    v_row.id,
    'BDT',
    0.0000,
    0.0000,
    0.0000
  )
  on conflict (tenant_id, entity_type, entity_id, currency_code)
  do update set updated_at = now()
  returning * into v_wallet;

  return jsonb_build_object(
    'cargo_company', to_jsonb(v_row),
    'wallet', to_jsonb(v_wallet)
  );
end;
$$;


ALTER FUNCTION "public"."create_cargo_company_with_wallet"("p_tenant_id" bigint, "p_name" "text", "p_code" "text", "p_email" "text", "p_phone" "text", "p_address" "text", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_costing_file"("p_tenant_id" bigint, "p_customer_group_id" bigint, "p_name" "text", "p_market" "text") RETURNS TABLE("id" bigint, "name" "text", "market" "text", "status" "public"."costing_file_status", "customer_group_id" bigint, "tenant_id" bigint, "created_by_email" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if trim(coalesce(p_name, '')) = '' then
    raise exception 'Costing file name is required.';
  end if;

  if not (
    public.can_admin_manage_costing_file(p_tenant_id)
    or (
      public.can_customer_access_costing_file(p_customer_group_id)
      and exists (
        select 1
        from public.customer_groups cg
        where cg.id = p_customer_group_id
          and cg.tenant_id = p_tenant_id
      )
    )
  ) then
    raise exception 'You do not have permission to create this costing file.';
  end if;

  return query
    insert into public.costing_files (
      tenant_id,
      customer_group_id,
      name,
      market
    )
    values (
      p_tenant_id,
      p_customer_group_id,
      trim(p_name),
      nullif(trim(coalesce(p_market, '')), '')
    )
    returning
      id,
      name,
      market,
      status,
      customer_group_id,
      tenant_id,
      created_by_email,
      created_at,
      updated_at;
end;
$$;


ALTER FUNCTION "public"."create_costing_file"("p_tenant_id" bigint, "p_customer_group_id" bigint, "p_name" "text", "p_market" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_costing_file"("p_customer_group_id" bigint, "p_market" "text", "p_name" "text", "p_status" "public"."costing_file_status" DEFAULT 'draft'::"public"."costing_file_status", "p_tenant_id" bigint DEFAULT NULL::bigint) RETURNS TABLE("id" bigint, "name" "text", "market" "text", "status" "public"."costing_file_status", "customer_group_id" bigint, "tenant_id" bigint, "created_by_email" "text", "default_shipment_id" bigint, "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if p_tenant_id is null then
    raise exception 'Tenant is required.';
  end if;

  if trim(coalesce(p_name, '')) = '' then
    raise exception 'Costing file name is required.';
  end if;

  if not exists (
    select 1
    from public.customer_groups cg
    where cg.id = p_customer_group_id
      and cg.tenant_id = p_tenant_id
  ) then
    raise exception 'Customer group does not belong to this tenant.';
  end if;

  if not (
    public.can_admin_manage_costing_file(p_tenant_id)
    or public.can_staff_access_costing_file(p_tenant_id)
    or public.can_customer_access_costing_file(p_customer_group_id)
  ) then
    raise exception 'You do not have permission to create this costing file.';
  end if;

  return query
    insert into public.costing_files as cf (
      tenant_id,
      customer_group_id,
      name,
      market,
      status
    )
    values (
      p_tenant_id,
      p_customer_group_id,
      trim(p_name),
      nullif(trim(coalesce(p_market, '')), ''),
      coalesce(p_status, 'draft')
    )
    returning
      cf.id,
      cf.name,
      cf.market,
      cf.status,
      cf.customer_group_id,
      cf.tenant_id,
      cf.created_by_email,
      cf.default_shipment_id,
      cf.created_at,
      cf.updated_at;
end;
$$;


ALTER FUNCTION "public"."create_costing_file"("p_customer_group_id" bigint, "p_market" "text", "p_name" "text", "p_status" "public"."costing_file_status", "p_tenant_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_costing_file_item_request"("p_costing_file_id" bigint, "p_website_url" "text", "p_quantity" integer) RETURNS TABLE("id" bigint, "costing_file_id" bigint, "website_url" "text", "quantity" integer, "status" "public"."costing_file_item_status", "created_by_email" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with inserted as (
    insert into public.costing_file_items (
      costing_file_id,
      website_url,
      quantity
    )
    select
      cf.id,
      trim(p_website_url),
      p_quantity
    from public.costing_files cf
    where cf.id = p_costing_file_id
      and (
        public.can_admin_manage_costing_file(cf.tenant_id)
        or public.can_staff_access_costing_file(cf.tenant_id)
        or (
          cf.status = 'draft'
          and public.can_customer_access_costing_file(cf.customer_group_id)
          and lower(trim(cf.created_by_email)) = public.current_user_email()
        )
      )
    returning
      id,
      costing_file_id,
      website_url,
      quantity,
      status,
      created_by_email,
      created_at,
      updated_at
  )
  select *
  from inserted;
$$;


