CREATE OR REPLACE FUNCTION "public"."customer_confirm_shop_order"("p_order_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_order record;
BEGIN
  SELECT * INTO v_order FROM public.shop_orders WHERE id = p_order_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Order not found: %', p_order_id;
  END IF;

  IF v_order.shop_type_snapshot <> 'vendor_catalog' THEN
    RAISE EXCEPTION 'customer_confirm_shop_order is only valid for vendor_catalog orders.';
  END IF;

  IF v_order.status <> 'final_offered' AND v_order.status <> 'priced' THEN
    RAISE EXCEPTION 'Order % cannot be confirmed from status %', p_order_id, v_order.status;
  END IF;

  -- Set confirmed_quantity = quantity where confirmed_quantity is null
  UPDATE public.shop_order_items
  SET
    confirmed_quantity = COALESCE(confirmed_quantity, quantity),
    updated_at = now()
  WHERE order_id = p_order_id;

  -- Update order status to confirmed
  UPDATE public.shop_orders
  SET
    status = 'confirmed'::public.shop_order_status,
    updated_at = now()
  WHERE id = p_order_id;

  PERFORM public.notify_catalog_shop_order(
    p_order_id := p_order_id,
    p_notify_staff := true,
    p_notify_customer := false,
    p_event_type := 'catalog.order.confirmed',
    p_title := format('Order %s confirmed', v_order.order_no),
    p_body := 'Start buying when ready.'
  );
END;
$$;


ALTER FUNCTION "public"."customer_confirm_shop_order"("p_order_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."customer_counter_offer"("p_order_id" bigint, "p_items" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_order record;
  v_item record;
  v_has_counter boolean := false;
BEGIN
  SELECT * INTO v_order FROM public.shop_orders WHERE id = p_order_id;

  IF v_order.id IS NULL THEN
    RAISE EXCEPTION 'order not found';
  END IF;

  IF v_order.shop_type_snapshot = 'vendor_catalog' THEN
    IF NOT COALESCE(v_order.is_negotiable_snapshot, false) THEN
      RAISE EXCEPTION 'Order % is not negotiable', p_order_id;
    END IF;

    IF v_order.status <> 'priced'::public.shop_order_status THEN
      RAISE EXCEPTION 'Catalog order % cannot respond from status %', p_order_id, v_order.status;
    END IF;

    FOR v_item IN
      SELECT * FROM jsonb_to_recordset(p_items) AS x(
        id bigint,
        customer_offer_amount numeric,
        customer_offer_currency_id bigint
      )
    LOOP
      UPDATE public.shop_order_items
      SET
        customer_offer_amount = v_item.customer_offer_amount,
        customer_offer_currency_id = v_item.customer_offer_currency_id,
        customer_counter_at = now(),
        updated_at = now()
      WHERE id = v_item.id AND order_id = p_order_id;
    END LOOP;

    SELECT EXISTS (
      SELECT 1
      FROM public.shop_order_items soi
      WHERE soi.order_id = p_order_id
        AND soi.customer_offer_amount IS NOT NULL
        AND soi.staff_offer_amount IS NOT NULL
        AND soi.customer_offer_amount <> soi.staff_offer_amount
    )
    INTO v_has_counter;

    IF v_has_counter THEN
      UPDATE public.shop_orders
      SET
        status = 'countered'::public.shop_order_status,
        negotiate_round = negotiate_round + 1,
        updated_at = now()
      WHERE id = p_order_id;

      PERFORM public.notify_catalog_shop_order(
        p_order_id := p_order_id,
        p_notify_staff := true,
        p_notify_customer := false,
        p_event_type := 'catalog.offer.countered',
        p_title := format('%s needs a final price', v_order.order_no),
        p_body := 'Open the order and send the last offer.'
      );
    ELSE
      UPDATE public.shop_order_items
      SET
        confirmed_quantity = COALESCE(confirmed_quantity, quantity),
        updated_at = now()
      WHERE order_id = p_order_id;

      UPDATE public.shop_orders
      SET
        status = 'confirmed'::public.shop_order_status,
        updated_at = now()
      WHERE id = p_order_id;

      PERFORM public.notify_catalog_shop_order(
        p_order_id := p_order_id,
        p_notify_staff := true,
        p_notify_customer := false,
        p_event_type := 'catalog.order.confirmed',
        p_title := format('Order %s confirmed', v_order.order_no),
        p_body := 'Start buying when ready.'
      );
    END IF;
  ELSE
    IF NOT public.is_cart_owner(v_order.customer_group_id, v_order.tenant_id) THEN
      RAISE EXCEPTION 'access denied';
    END IF;

    FOR v_item IN
      SELECT * FROM jsonb_to_recordset(p_items) AS x(
        id bigint,
        customer_offer_amount numeric,
        customer_offer_currency_id bigint
      )
    LOOP
      UPDATE public.shop_order_items
      SET
        customer_offer_amount = v_item.customer_offer_amount,
        customer_offer_currency_id = v_item.customer_offer_currency_id,
        updated_at = now()
      WHERE id = v_item.id AND order_id = p_order_id;
    END LOOP;

    UPDATE public.shop_orders
    SET
      status = 'negotiating'::public.shop_order_status,
      negotiate_round = negotiate_round + 1,
      updated_at = now()
    WHERE id = p_order_id;
  END IF;
END;
$$;


ALTER FUNCTION "public"."customer_counter_offer"("p_order_id" bigint, "p_items" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."customer_shop_order_glance_bucket"("p_status" "public"."shop_order_status") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT CASE
    WHEN p_status = 'draft'::public.shop_order_status THEN NULL
    WHEN p_status IN (
      'priced'::public.shop_order_status,
      'negotiating'::public.shop_order_status,
      'countered'::public.shop_order_status,
      'final_offered'::public.shop_order_status
    ) THEN 'needs_you'
    WHEN p_status IN (
      'fulfilled'::public.shop_order_status,
      'delivered'::public.shop_order_status,
      'payment_received'::public.shop_order_status,
      'reseller_paid'::public.shop_order_status,
      'cancelled'::public.shop_order_status,
      'returned'::public.shop_order_status
    ) THEN 'done'
    ELSE 'in_progress'
  END;
$$;


ALTER FUNCTION "public"."customer_shop_order_glance_bucket"("p_status" "public"."shop_order_status") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."customer_shop_order_glance_segment"("p_status" "public"."shop_order_status") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT CASE
    WHEN p_status IN (
      'priced'::public.shop_order_status,
      'negotiating'::public.shop_order_status,
      'countered'::public.shop_order_status,
      'final_offered'::public.shop_order_status
    ) THEN 'needs_you'
    WHEN p_status IN (
      'submitted'::public.shop_order_status,
      'costing_pending'::public.shop_order_status,
      'confirmed'::public.shop_order_status,
      'placed'::public.shop_order_status,
      'procuring'::public.shop_order_status,
      'ordered'::public.shop_order_status,
      'processing'::public.shop_order_status,
      'shipped'::public.shop_order_status,
      'ready_for_shipment'::public.shop_order_status,
      'ready_for_pickup'::public.shop_order_status
    ) THEN 'in_progress'
    WHEN p_status = 'delivered'::public.shop_order_status THEN 'delivered'
    WHEN p_status IN (
      'payment_received'::public.shop_order_status,
      'reseller_paid'::public.shop_order_status
    ) THEN 'paid'
    ELSE NULL
  END;
$$;


ALTER FUNCTION "public"."customer_shop_order_glance_segment"("p_status" "public"."shop_order_status") OWNER TO "postgres";


