CREATE OR REPLACE FUNCTION "public"."enforce_costing_file_item_update_rules"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor_role text;
  v_file_status public.costing_file_status;
begin
  v_actor_role := public.current_costing_item_actor_role(old.costing_file_id);

  select cf.status
  into v_file_status
  from public.costing_files cf
  where cf.id = old.costing_file_id;

  if v_actor_role = 'admin' then
    return new;
  end if;

  if v_actor_role = 'staff' then
    if new.costing_file_id is distinct from old.costing_file_id
      or new.website_url is distinct from old.website_url
      or new.quantity is distinct from old.quantity
      or new.status is distinct from old.status
      or new.customer_profit_rate is distinct from old.customer_profit_rate
      or new.auxiliary_price_gbp is distinct from old.auxiliary_price_gbp
      or new.item_price_gbp is distinct from old.item_price_gbp
      or new.cargo_rate is distinct from old.cargo_rate
      or new.costing_price_gbp is distinct from old.costing_price_gbp
      or new.costing_price_bdt is distinct from old.costing_price_bdt
      or new.offer_price_bdt is distinct from old.offer_price_bdt
      or new.created_by_email is distinct from old.created_by_email
      or new.created_at is distinct from old.created_at
    then
      raise exception 'staff can update enrichment fields only';
    end if;

    return new;
  end if;

  if v_actor_role = 'customer' then
    if v_file_status = 'draft' then
      if new.costing_file_id is distinct from old.costing_file_id
        or new.status is distinct from old.status
        or new.name is distinct from old.name
        or new.image_url is distinct from old.image_url
        or new.product_weight is distinct from old.product_weight
        or new.package_weight is distinct from old.package_weight
        or new.price_in_web_gbp is distinct from old.price_in_web_gbp
        or new.delivery_price_gbp is distinct from old.delivery_price_gbp
        or new.auxiliary_price_gbp is distinct from old.auxiliary_price_gbp
        or new.item_price_gbp is distinct from old.item_price_gbp
        or new.cargo_rate is distinct from old.cargo_rate
        or new.costing_price_gbp is distinct from old.costing_price_gbp
        or new.costing_price_bdt is distinct from old.costing_price_bdt
        or new.offer_price_bdt is distinct from old.offer_price_bdt
        or new.offer_price_override_bdt is distinct from old.offer_price_override_bdt
        or new.customer_profit_rate is distinct from old.customer_profit_rate
        or new.created_by_email is distinct from old.created_by_email
        or new.created_at is distinct from old.created_at
      then
        raise exception 'customer can update website_url and quantity only while file is draft';
      end if;

      return new;
    end if;

    if v_file_status = 'offered' then
      if new.costing_file_id is distinct from old.costing_file_id
        or new.website_url is distinct from old.website_url
        or new.quantity is distinct from old.quantity
        or new.name is distinct from old.name
        or new.image_url is distinct from old.image_url
        or new.product_weight is distinct from old.product_weight
        or new.package_weight is distinct from old.package_weight
        or new.price_in_web_gbp is distinct from old.price_in_web_gbp
        or new.delivery_price_gbp is distinct from old.delivery_price_gbp
        or new.auxiliary_price_gbp is distinct from old.auxiliary_price_gbp
        or new.item_price_gbp is distinct from old.item_price_gbp
        or new.cargo_rate is distinct from old.cargo_rate
        or new.costing_price_gbp is distinct from old.costing_price_gbp
        or new.costing_price_bdt is distinct from old.costing_price_bdt
        or new.offer_price_bdt is distinct from old.offer_price_bdt
        or new.offer_price_override_bdt is distinct from old.offer_price_override_bdt
        or new.created_by_email is distinct from old.created_by_email
        or new.created_at is distinct from old.created_at
      then
        raise exception 'customer can update item status and customer_profit_rate only when file is offered';
      end if;

      return new;
    end if;

    raise exception 'customer cannot update costing file items in the current file status';
  end if;

  raise exception 'current user cannot update costing file items';
end;
$$;


ALTER FUNCTION "public"."enforce_costing_file_item_update_rules"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_customer_group_member_email_rules"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_normalized_email text;
begin
  v_normalized_email := lower(trim(new.email));
  new.email := v_normalized_email;

  if exists (
    select 1
    from public.customer_group_members cgm
    where cgm.customer_group_id = new.customer_group_id
      and lower(trim(cgm.email)) = v_normalized_email
      and cgm.id <> coalesce(new.id, -1)
  ) then
    raise exception 'This email is already used in this group';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."enforce_customer_group_member_email_rules"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_tenant_one_layer_hierarchy"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
declare
  v_parent_parent_id bigint;
begin
  if new.parent_id is not null then
    if new.parent_id = new.id then
      raise exception 'tenant cannot be its own parent';
    end if;

    select parent_id into v_parent_parent_id
    from public.tenants
    where id = new.parent_id;

    if v_parent_parent_id is not null then
      raise exception 'parent tenant must be a top-level company (one layer only)';
    end if;

    if exists (
      select 1
      from public.tenants c
      where c.parent_id = new.id
    ) then
      raise exception 'tenant with child companies cannot be assigned a parent';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."enforce_tenant_one_layer_hierarchy"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_notification"("p_tenant_id" bigint, "p_operating_tenant_id" bigint, "p_audience" "public"."notification_audience", "p_event_type" "text", "p_title" "text", "p_body" "text" DEFAULT NULL::"text", "p_link_path" "text" DEFAULT NULL::"text", "p_entity_type" "text" DEFAULT NULL::"text", "p_entity_id" "text" DEFAULT NULL::"text", "p_recipient_user_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_module_key" "text" DEFAULT NULL::"text", "p_action" "text" DEFAULT 'view'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_parent_tenant_id bigint;
  v_notification_id uuid;
  v_recipient_user_ids uuid[];
  v_title text := trim(coalesce(p_title, ''));
  v_event_type text := trim(coalesce(p_event_type, ''));
BEGIN
  IF p_tenant_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'p_tenant_id is required');
  END IF;

  IF v_title = '' THEN
    RETURN jsonb_build_object('success', false, 'error', 'p_title is required');
  END IF;

  IF v_event_type = '' THEN
    RETURN jsonb_build_object('success', false, 'error', 'p_event_type is required');
  END IF;

  IF p_audience = 'assignee_only'
     AND (p_recipient_user_ids IS NULL OR cardinality(p_recipient_user_ids) = 0) THEN
    RETURN jsonb_build_object('success', false, 'error', 'assignee_only requires p_recipient_user_ids');
  END IF;

  v_parent_tenant_id := public.resolve_parent_tenant_id(p_tenant_id);

  v_recipient_user_ids := public.resolve_notification_recipient_user_ids(
    v_parent_tenant_id,
    p_operating_tenant_id,
    p_audience,
    p_recipient_user_ids,
    p_module_key,
    p_action
  );

  IF v_recipient_user_ids IS NULL OR cardinality(v_recipient_user_ids) = 0 THEN
    RETURN jsonb_build_object(
      'success', true,
      'notification_id', NULL,
      'parent_tenant_id', v_parent_tenant_id,
      'operating_tenant_id', p_operating_tenant_id,
      'recipient_count', 0,
      'recipient_user_ids', '[]'::jsonb
    );
  END IF;

  INSERT INTO public.notifications (
    parent_tenant_id,
    operating_tenant_id,
    event_type,
    title,
    body,
    link_path,
    entity_type,
    entity_id
  )
  VALUES (
    v_parent_tenant_id,
    p_operating_tenant_id,
    v_event_type,
    v_title,
    nullif(trim(coalesce(p_body, '')), ''),
    nullif(trim(coalesce(p_link_path, '')), ''),
    nullif(trim(coalesce(p_entity_type, '')), ''),
    nullif(trim(coalesce(p_entity_id, '')), '')
  )
  RETURNING id INTO v_notification_id;

  INSERT INTO public.notification_recipients (notification_id, user_id)
  SELECT v_notification_id, recipient_user_id
  FROM unnest(v_recipient_user_ids) AS recipient_user_id
  ON CONFLICT (notification_id, user_id) DO NOTHING;

  RETURN jsonb_build_object(
    'success', true,
    'notification_id', v_notification_id,
    'parent_tenant_id', v_parent_tenant_id,
    'operating_tenant_id', p_operating_tenant_id,
    'recipient_count', cardinality(v_recipient_user_ids),
    'recipient_user_ids', to_jsonb(v_recipient_user_ids)
  );
END;
$$;


ALTER FUNCTION "public"."enqueue_notification"("p_tenant_id" bigint, "p_operating_tenant_id" bigint, "p_audience" "public"."notification_audience", "p_event_type" "text", "p_title" "text", "p_body" "text", "p_link_path" "text", "p_entity_type" "text", "p_entity_id" "text", "p_recipient_user_ids" "uuid"[], "p_module_key" "text", "p_action" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_default_cargo_company"("p_tenant_id" bigint) RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_tenant public.tenants%rowtype;
  v_id bigint;
begin
  if p_tenant_id is null then
    raise exception 'p_tenant_id is required';
  end if;

  select * into v_tenant
  from public.tenants
  where id = p_tenant_id;

  if not found then
    raise exception 'tenant % not found', p_tenant_id;
  end if;

  if v_tenant.parent_id is not null then
    raise exception 'ensure_default_cargo_company requires a parent tenant (got child %)', p_tenant_id;
  end if;

  if auth.uid() is not null then
    if not (
      public.is_superadmin()
      or public.user_can_manage_parent_tenant(p_tenant_id)
      or exists (
        select 1
        from public.memberships m
        where m.tenant_id = p_tenant_id
          and lower(trim(m.email)) = public.current_user_email()
          and m.role in ('admin', 'staff')
          and m.is_active = true
      )
    ) then
      raise exception 'not allowed';
    end if;
  end if;

  select id into v_id
  from public.cargo_companies
  where tenant_id = p_tenant_id
    and is_default = true
  limit 1;

  if v_id is not null then
    return v_id;
  end if;

  select id into v_id
  from public.cargo_companies
  where tenant_id = p_tenant_id
    and upper(trim(code)) = 'DEFAULT'
  limit 1;

  if v_id is not null then
    update public.cargo_companies
    set is_default = true,
        name = coalesce(nullif(trim(name), ''), 'Default Cargo Company'),
        parent_tenant_id = coalesce(parent_tenant_id, p_tenant_id),
        is_active = true,
        updated_at = now()
    where id = v_id;
    return v_id;
  end if;

  insert into public.cargo_companies (
    tenant_id,
    parent_tenant_id,
    name,
    code,
    is_default,
    is_active
  )
  values (
    p_tenant_id,
    p_tenant_id,
    'Default Cargo Company',
    'DEFAULT',
    true,
    true
  )
  returning id into v_id;

  insert into public.wallet_accounts (
    tenant_id,
    parent_tenant_id,
    entity_type,
    entity_id,
    currency_code,
    available_balance,
    pending_balance,
    locked_balance
  )
  values (
    p_tenant_id,
    p_tenant_id,
    'cargo_company',
    v_id,
    'BDT',
    0.0000,
    0.0000,
    0.0000
  )
  on conflict (tenant_id, entity_type, entity_id, currency_code)
  do update set updated_at = now();

  return v_id;
end;
$$;


ALTER FUNCTION "public"."ensure_default_cargo_company"("p_tenant_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_default_stock_location"("p_tenant_id" bigint) RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_tenant public.tenants%rowtype;
  v_loc_id bigint;
begin
  if p_tenant_id is null then
    raise exception 'p_tenant_id is required';
  end if;

  select * into v_tenant
  from public.tenants
  where id = p_tenant_id;

  if not found then
    raise exception 'tenant % not found', p_tenant_id;
  end if;

  -- Stock locations live on parent (stock-owning) tenants only
  if v_tenant.parent_id is not null then
    return public.ensure_default_stock_location(v_tenant.parent_id);
  end if;

  -- Check if an active leaf location already exists for this parent tenant
  select sl.id into v_loc_id
  from public.stock_locations sl
  where sl.parent_tenant_id = p_tenant_id
    and sl.is_active = true
    and public._stock_location_is_leaf(sl.id)
  order by sl.is_default desc, sl.is_pickable desc, sl.sort_order, sl.id
  limit 1;

  if v_loc_id is not null then
    return v_loc_id;
  end if;

  -- Create default leaf stock location for tenant
  insert into public.stock_locations (
    parent_tenant_id,
    name,
    code,
    kind,
    parent_location_id,
    is_pickable,
    is_default,
    is_active,
    sort_order
  ) values (
    p_tenant_id,
    'Main Warehouse',
    'MAIN',
    'shelf',
    null,
    true,
    true,
    true,
    10
  )
  returning id into v_loc_id;

  return v_loc_id;
end;
$$;


ALTER FUNCTION "public"."ensure_default_stock_location"("p_tenant_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_default_vendor"("p_tenant_id" bigint) RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_tenant public.tenants%rowtype;
  v_vendor_id bigint;
  v_market_code text;
begin
  if p_tenant_id is null then
    raise exception 'p_tenant_id is required';
  end if;

  select * into v_tenant
  from public.tenants
  where id = p_tenant_id;

  if not found then
    raise exception 'tenant % not found', p_tenant_id;
  end if;

  if v_tenant.parent_id is not null then
    raise exception 'ensure_default_vendor requires a parent tenant (got child %)', p_tenant_id;
  end if;

  if auth.uid() is not null then
    if not (
      public.is_superadmin()
      or public.user_can_manage_parent_tenant(p_tenant_id)
      or exists (
        select 1
        from public.memberships m
        where m.tenant_id = p_tenant_id
          and lower(trim(m.email)) = public.current_user_email()
          and m.role in ('admin', 'staff')
          and m.is_active = true
      )
    ) then
      raise exception 'not allowed';
    end if;
  end if;

  select id into v_vendor_id
  from public.vendors
  where tenant_id = p_tenant_id
    and is_default = true
  limit 1;

  if v_vendor_id is not null then
    return v_vendor_id;
  end if;

  select id into v_vendor_id
  from public.vendors
  where tenant_id = p_tenant_id
    and upper(trim(code)) = 'DEFAULT'
  limit 1;

  if v_vendor_id is not null then
    update public.vendors
    set is_default = true,
        name = coalesce(nullif(trim(name), ''), 'Default Vendor'),
        is_active = true,
        updated_at = now()
    where id = v_vendor_id;
    return v_vendor_id;
  end if;

  select upper(trim(code)) into v_market_code
  from public.global_markets
  where is_active = true
  order by id asc
  limit 1;

  if v_market_code is null or v_market_code = '' then
    v_market_code := 'BD';
  end if;

  insert into public.vendors (
    tenant_id,
    name,
    code,
    market_code,
    is_default
  )
  values (
    p_tenant_id,
    'Default Vendor',
    'DEFAULT',
    v_market_code,
    true
  )
  returning id into v_vendor_id;

  -- Mirror create_vendor_with_wallet: zero BDT wallet anchor
  insert into public.wallet_accounts (
    tenant_id,
    parent_tenant_id,
    entity_type,
    entity_id,
    currency_code,
    available_balance,
    pending_balance,
    locked_balance
  )
  values (
    p_tenant_id,
    p_tenant_id,
    'vendor',
    v_vendor_id,
    'BDT',
    0.0000,
    0.0000,
    0.0000
  )
  on conflict (tenant_id, entity_type, entity_id, currency_code)
  do update set updated_at = now();

  return v_vendor_id;
end;
$$;


ALTER FUNCTION "public"."ensure_default_vendor"("p_tenant_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_dropship_invoice_billed_entry"("p_invoice_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  -- Intentionally no-op. Dropship B2B invoice does not debit the billing profile wallet.
  -- Courier COD is credited in confirm_dropship_delivered_costing at mark-delivered.
  return;
end;
$$;


