CREATE OR REPLACE FUNCTION "public"."get_courier_unremitted_financial_summary"("p_tenant_id" bigint) RETURNS TABLE("courier_service_id" "uuid", "courier_name" "text", "gross_cod_total" numeric, "company_wholesale_total" numeric, "middleman_margin_total" numeric, "order_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if p_tenant_id is null then
    raise exception 'Tenant ID is required';
  end if;

  return query
  select
    so.courier_service_id,
    coalesce(cs.name, so.courier_name, 'Unassigned') as courier_name,
    coalesce(sum(coalesce(so.cod_collect_amount, gi.total_amount, 0)), 0.00)::numeric(12,2) as gross_cod_total,
    (
      coalesce(sum(coalesce(so.cod_collect_amount, gi.total_amount, 0)), 0.00) -
      coalesce(sum(coalesce(wl.amount, 0)), 0.00)
    )::numeric(12,2) as company_wholesale_total,
    coalesce(sum(coalesce(wl.amount, 0)), 0.00)::numeric(12,2) as middleman_margin_total,
    count(so.id)::bigint as order_count
  from public.shop_orders so
  left join public.courier_services cs on cs.id = so.courier_service_id
  left join public.global_invoices gi on gi.id = so.global_invoice_id
  left join public.billing_profile_wallet_ledger wl
    on wl.shop_order_id = so.id and wl.transaction_type = 'dropship_profit'
  where so.tenant_id = p_tenant_id
    and so.status = 'delivered'
  group by so.courier_service_id, coalesce(cs.name, so.courier_name, 'Unassigned');
end;
$$;


ALTER FUNCTION "public"."get_courier_unremitted_financial_summary"("p_tenant_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_customer_account_summary_for_staff"("p_tenant_id" bigint, "p_customer_group_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_books_id bigint;
  v_group_tenant_id bigint;
  v_billing_profile_id bigint;
  v_bp_ids bigint[];
  v_still_due numeric(12, 2) := 0;
  v_total_billed numeric(12, 2) := 0;
  v_settlement numeric(12, 2) := 0;
  v_collected_cash numeric(12, 2) := 0;
  v_wallet_applied numeric(12, 2) := 0;
  v_store_credit numeric(15, 4) := 0;
  v_unallocated numeric(12, 2) := 0;
  v_open_invoices jsonb := '[]'::jsonb;
  v_recent_payments jsonb := '[]'::jsonb;
  v_recent_ledger jsonb := '[]'::jsonb;
  v_shop_access jsonb := '[]'::jsonb;
begin
  if p_tenant_id is null or p_customer_group_id is null then
    return jsonb_build_object('success', false, 'error', 'tenant and customer group are required');
  end if;

  v_books_id := public.resolve_parent_tenant_id(p_tenant_id);

  if not (
    public.is_tenant_staff(p_tenant_id)
    or public.membership_has_module_action(v_books_id, 'customer', 'view')
  ) then
    return jsonb_build_object('success', false, 'error', 'access denied');
  end if;

  select cg.tenant_id
  into v_group_tenant_id
  from public.customer_groups cg
  where cg.id = p_customer_group_id;

  if v_group_tenant_id is null then
    return jsonb_build_object('success', false, 'error', 'customer group not found');
  end if;

  select
    coalesce(array_agg(bp.id order by
      case when bp.tenant_id = v_group_tenant_id then 0 else 1 end,
      bp.id
    ), '{}'::bigint[]),
    (array_agg(bp.id order by
      case when bp.tenant_id = v_group_tenant_id then 0 else 1 end,
      bp.id
    ))[1]
  into v_bp_ids, v_billing_profile_id
  from public.billing_profiles bp
  where bp.customer_group_id = p_customer_group_id
    and (
      bp.tenant_id = v_books_id
      or bp.tenant_id in (
        select t.id from public.tenants t where t.parent_id = v_books_id
      )
    );

  if v_billing_profile_id is null then
    return jsonb_build_object(
      'success', true,
      'books_tenant_id', v_books_id,
      'billing_profile_id', null,
      'still_due', 0,
      'total_billed', 0,
      'collected_cash', 0,
      'wallet_applied', 0,
      'settlement', 0,
      'store_credit_balance', 0,
      'unallocated_payments', 0,
      'open_invoices', '[]'::jsonb,
      'recent_payments', '[]'::jsonb,
      'recent_ledger', '[]'::jsonb,
      'shop_access', coalesce((
        select jsonb_agg(to_jsonb(r))
        from (
          select
            s.id as shop_id,
            s.name as shop_name,
            s.shop_type::text as shop_type,
            st.id as shop_tenant_id,
            st.name as shop_tenant_name,
            scga.status,
            scga.credit_limit_amount
          from public.shop_customer_group_access scga
          join public.shops s on s.id = scga.shop_id
          join public.tenants st on st.id = s.tenant_id
          where scga.customer_group_id = p_customer_group_id
          order by st.name, s.name
          limit 20
        ) r
      ), '[]'::jsonb)
    );
  end if;

  select
    coalesce(sum(si.due_amount), 0.00),
    coalesce(sum(si.total_amount), 0.00),
    coalesce(sum(si.settlement_discount_amount), 0.00)
  into v_still_due, v_total_billed, v_settlement
  from public.sales_invoices si
  where si.billing_profile_id = any(v_bp_ids)
    and si.invoice_status = 'issued'::public.global_invoice_status;

  select
    coalesce(sum(ip.amount) filter (where coalesce(gp.method, '') <> 'wallet_credit'), 0.00),
    coalesce(sum(ip.amount) filter (where gp.method = 'wallet_credit'), 0.00)
  into v_collected_cash, v_wallet_applied
  from public.invoice_payments ip
  join public.global_payments gp on gp.id = ip.payment_id
  join public.sales_invoices si on si.id = ip.global_invoice_id
  where si.billing_profile_id = any(v_bp_ids)
    and si.invoice_status = 'issued'::public.global_invoice_status;

  select coalesce(wa.available_balance, 0.0000)
  into v_store_credit
  from public.wallet_accounts wa
  where wa.parent_tenant_id = v_books_id
    and wa.entity_type = 'customer'
    and wa.entity_id = v_billing_profile_id
    and wa.currency_code = 'BDT';

  select coalesce(sum(gp.unallocated_amount), 0.00)
  into v_unallocated
  from public.global_payments gp
  where gp.billing_profile_id = any(v_bp_ids);

  select coalesce(jsonb_agg(to_jsonb(r)), '[]'::jsonb)
  into v_open_invoices
  from (
    select
      si.id,
      si.invoice_no,
      si.invoice_type::text as invoice_type,
      si.due_amount,
      si.paid_amount,
      si.total_amount,
      si.payment_status,
      si.invoice_date,
      si.due_date,
      si.issued_by_tenant_id,
      it.name as issued_by_tenant_name
    from public.sales_invoices si
    left join public.tenants it on it.id = si.issued_by_tenant_id
    where si.billing_profile_id = any(v_bp_ids)
      and si.invoice_status = 'issued'::public.global_invoice_status
      and si.due_amount > 0
    order by si.due_amount desc, si.invoice_date desc, si.id desc
    limit 50
  ) r;

  select coalesce(jsonb_agg(to_jsonb(r)), '[]'::jsonb)
  into v_recent_payments
  from (
    select
      gp.id as payment_id,
      gp.payment_date,
      gp.method,
      gp.amount,
      gp.unallocated_amount,
      gp.note,
      ip.global_invoice_id as invoice_id,
      ip.amount as allocated_amount
    from public.global_payments gp
    left join public.invoice_payments ip on ip.payment_id = gp.id
    where gp.billing_profile_id = any(v_bp_ids)
    order by gp.payment_date desc, gp.id desc
    limit 30
  ) r;

  select coalesce(jsonb_agg(to_jsonb(r)), '[]'::jsonb)
  into v_recent_ledger
  from (
    select
      l.id,
      l.type,
      l.amount,
      l.balance_after,
      l.operating_tenant_id,
      l.source_type,
      l.source_id,
      l.created_at,
      l.metadata->>'transaction_type' as transaction_type,
      coalesce(
        l.metadata->>'label',
        l.metadata->>'transaction_type',
        'Adjustment'
      ) as label
    from public.universal_wallet_ledger l
    where l.parent_tenant_id = v_books_id
      and l.entity_type = 'customer'
      and l.entity_id = any(v_bp_ids)
    order by l.created_at desc, l.id desc
    limit 30
  ) r;

  select coalesce(jsonb_agg(to_jsonb(r)), '[]'::jsonb)
  into v_shop_access
  from (
    select
      s.id as shop_id,
      s.name as shop_name,
      s.shop_type::text as shop_type,
      st.id as shop_tenant_id,
      st.name as shop_tenant_name,
      scga.status,
      scga.credit_limit_amount
    from public.shop_customer_group_access scga
    join public.shops s on s.id = scga.shop_id
    join public.tenants st on st.id = s.tenant_id
    where scga.customer_group_id = p_customer_group_id
    order by st.name, s.name
    limit 20
  ) r;

  return jsonb_build_object(
    'success', true,
    'books_tenant_id', v_books_id,
    'billing_profile_id', v_billing_profile_id,
    'still_due', v_still_due,
    'total_billed', v_total_billed,
    'collected_cash', v_collected_cash,
    'wallet_applied', v_wallet_applied,
    'settlement', v_settlement,
    'store_credit_balance', v_store_credit,
    'unallocated_payments', v_unallocated,
    'open_invoices', v_open_invoices,
    'recent_payments', v_recent_payments,
    'recent_ledger', v_recent_ledger,
    'shop_access', v_shop_access
  );
end;
$$;


ALTER FUNCTION "public"."get_customer_account_summary_for_staff"("p_tenant_id" bigint, "p_customer_group_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_customer_dashboard_summary"("p_tenant_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_group_id bigint;
  v_shops jsonb := '[]'::jsonb;
  v_categories jsonb := '[]'::jsonb;
  v_recent_orders jsonb := '[]'::jsonb;
  v_active_carts jsonb := '[]'::jsonb;
  v_buckets jsonb;
  v_catalog_glance jsonb := jsonb_build_object('total_products', 0, 'total_brands', 0);
BEGIN
  IF p_tenant_id IS NULL THEN
    RETURN jsonb_build_object(
      'tenant_id', NULL,
      'customer_group_id', NULL,
      'shops', '[]'::jsonb,
      'categories', '[]'::jsonb,
      'catalog_glance', v_catalog_glance,
      'order_glance', jsonb_build_object(
        'buckets', jsonb_build_object('needs_you', 0, 'in_progress', 0, 'done', 0, 'total', 0),
        'segments', jsonb_build_object(
          'needs_you', 0,
          'in_progress', 0,
          'delivered', 0,
          'paid', 0,
          'payment_needed', 0,
          'total', 0
        )
      ),
      'recent_orders', '[]'::jsonb,
      'active_carts', '[]'::jsonb
    );
  END IF;

  v_group_id := public.current_customer_group_id(p_tenant_id);
  IF v_group_id IS NULL THEN
    RETURN jsonb_build_object(
      'tenant_id', p_tenant_id,
      'customer_group_id', NULL,
      'shops', '[]'::jsonb,
      'categories', '[]'::jsonb,
      'catalog_glance', v_catalog_glance,
      'order_glance', jsonb_build_object(
        'buckets', jsonb_build_object('needs_you', 0, 'in_progress', 0, 'done', 0, 'total', 0),
        'segments', jsonb_build_object(
          'needs_you', 0,
          'in_progress', 0,
          'delivered', 0,
          'paid', 0,
          'payment_needed', 0,
          'total', 0
        )
      ),
      'recent_orders', '[]'::jsonb,
      'active_carts', '[]'::jsonb
    );
  END IF;

  v_catalog_glance := public.customer_accessible_catalog_glance(p_tenant_id, v_group_id);

  SELECT coalesce(jsonb_agg(row_to_json(shop_row) ORDER BY shop_row.name), '[]'::jsonb)
  INTO v_shops
  FROM (
    SELECT
      s.id,
      s.tenant_id,
      s.name,
      s.slug,
      s.shop_type,
      s.order_mode,
      s.is_negotiable,
      bool_or(
        CASE
          WHEN access.status = false OR coalesce(profile.is_active, true) = false THEN false
          ELSE public.resolve_shop_can_see_buy_price(
            s.shop_type,
            access.can_see_buy_price,
            access.can_see_sell_price,
            profile.default_can_see_buy_price,
            profile.default_can_see_sell_price
          )
        END
      ) AS can_see_buy_price,
      bool_or(
        CASE
          WHEN access.status = false OR coalesce(profile.is_active, true) = false THEN false
          WHEN s.shop_type = 'dropship' THEN true
          ELSE coalesce(access.can_see_sell_price, profile.default_can_see_sell_price, false)
        END
      ) AS can_see_sell_price,
      s.description,
      s.category_ids,
      coalesce(
        (
          SELECT jsonb_agg(
            jsonb_build_object(
              'id', c.id,
              'name', c.name,
              'slug', c.slug,
              'icon', c.icon
            )
            ORDER BY c.name
          )
          FROM public.shop_categories c
          WHERE c.id = ANY(s.category_ids)
            AND c.is_active = true
        ),
        '[]'::jsonb
      ) AS categories,
      s.sell_currency_id,
      gc.code AS sell_currency_code,
      gc.symbol AS sell_currency_symbol
    FROM public.shops s
    JOIN public.shop_customer_group_access access ON access.shop_id = s.id
    JOIN public.customer_groups cg ON cg.id = access.customer_group_id
    LEFT JOIN public.customer_group_shop_profiles profile
      ON profile.customer_group_id = cg.id AND profile.tenant_id = s.tenant_id
    LEFT JOIN public.global_currencies gc ON gc.id = s.sell_currency_id
    WHERE s.is_active = true
      AND s.deleted_at IS NULL
      AND s.tenant_id = p_tenant_id
      AND cg.id = v_group_id
      AND cg.is_active = true
      AND access.status = true
      AND coalesce(profile.is_active, true) = true
      AND coalesce(access.can_browse, profile.default_can_browse, false) = true
    GROUP BY
      s.id,
      s.tenant_id,
      s.name,
      s.slug,
      s.shop_type,
      s.order_mode,
      s.is_negotiable,
      s.description,
      s.category_ids,
      s.sell_currency_id,
      gc.code,
      gc.symbol
  ) shop_row;

  SELECT coalesce(jsonb_agg(cat ORDER BY cat ->> 'name'), '[]'::jsonb)
  INTO v_categories
  FROM (
    SELECT DISTINCT ON ((cat ->> 'id')::bigint) cat
    FROM (
      SELECT jsonb_array_elements(coalesce(shop_elem -> 'categories', '[]'::jsonb)) AS cat
      FROM jsonb_array_elements(v_shops) shop_elem
    ) cats
    ORDER BY (cat ->> 'id')::bigint
  ) deduped;

  SELECT jsonb_build_object(
    'buckets', jsonb_build_object(
      'needs_you', coalesce(count(*) FILTER (
        WHERE public.customer_shop_order_glance_bucket(o.status) = 'needs_you'
      ), 0),
      'in_progress', coalesce(count(*) FILTER (
        WHERE public.customer_shop_order_glance_bucket(o.status) = 'in_progress'
      ), 0),
      'done', coalesce(count(*) FILTER (
        WHERE public.customer_shop_order_glance_bucket(o.status) = 'done'
      ), 0),
      'total', coalesce(count(*) FILTER (WHERE o.status IS DISTINCT FROM 'draft'), 0)
    ),
    'segments', jsonb_build_object(
      'needs_you', coalesce(count(*) FILTER (
        WHERE public.customer_shop_order_glance_segment(o.status) = 'needs_you'
      ), 0),
      'in_progress', coalesce(count(*) FILTER (
        WHERE public.customer_shop_order_glance_segment(o.status) = 'in_progress'
      ), 0),
      'delivered', coalesce(count(*) FILTER (
        WHERE public.customer_shop_order_glance_segment(o.status) = 'delivered'
      ), 0),
      'paid', coalesce(count(*) FILTER (
        WHERE public.customer_shop_order_glance_segment(o.status) = 'paid'
      ), 0),
      'payment_needed', coalesce(count(*) FILTER (
        WHERE public.customer_shop_order_glance_segment(o.status) = 'payment_needed'
      ), 0),
      'total', coalesce(count(*) FILTER (
        WHERE public.customer_shop_order_glance_segment(o.status) IS NOT NULL
      ), 0)
    )
  )
  INTO v_buckets
  FROM public.shop_orders o
  WHERE o.tenant_id = p_tenant_id
    AND o.customer_group_id = v_group_id
    AND o.status IS DISTINCT FROM 'draft';

  SELECT coalesce(jsonb_agg(row_to_json(order_row) ORDER BY order_row.created_at DESC), '[]'::jsonb)
  INTO v_recent_orders
  FROM (
    SELECT
      o.id,
      o.shop_id,
      s.name AS shop_name,
      s.slug AS shop_slug,
      o.order_no,
      o.status,
      gc.symbol AS currency_symbol,
      o.created_at
    FROM public.shop_orders o
    JOIN public.shops s ON s.id = o.shop_id
    LEFT JOIN public.global_currencies gc ON gc.id = s.sell_currency_id
    WHERE o.tenant_id = p_tenant_id
      AND o.customer_group_id = v_group_id
      AND o.status IS DISTINCT FROM 'draft'
    ORDER BY o.created_at DESC
    LIMIT 5
  ) order_row;

  SELECT coalesce(jsonb_agg(row_to_json(cart_row) ORDER BY cart_row.updated_at DESC), '[]'::jsonb)
  INTO v_active_carts
  FROM (
    SELECT
      c.id AS cart_id,
      s.id AS shop_id,
      s.name AS shop_name,
      s.slug AS shop_slug,
      NULL::text AS shop_logo_url,
      s.shop_type::text AS shop_type,
      c.can_see_buy_price_snapshot AS can_see_buy_price,
      c.can_see_sell_price_snapshot AS can_see_sell_price,
      s.sell_currency_id AS currency_id,
      gc.code AS currency_code,
      gc.symbol AS currency_symbol,
      coalesce(sum(ci.quantity), 0)::bigint AS item_count,
      CASE
        WHEN c.can_see_sell_price_snapshot THEN
          sum(
            ci.quantity * coalesce(
              ci.customer_sell_price_amount,
              ci.unit_sell_price_amount,
              ci.unit_list_price_amount,
              0
            )
          )::numeric
        ELSE NULL
      END AS cart_total,
      c.updated_at
    FROM public.shop_carts c
    JOIN public.shops s ON s.id = c.shop_id
    JOIN public.shop_cart_items ci ON ci.cart_id = c.id
    LEFT JOIN public.global_currencies gc ON gc.id = s.sell_currency_id
    WHERE c.status = 'active'
      AND c.tenant_id = p_tenant_id
      AND c.customer_group_id = v_group_id
    GROUP BY c.id, s.id, gc.code, gc.symbol
  ) cart_row;

  RETURN jsonb_build_object(
    'tenant_id', p_tenant_id,
    'customer_group_id', v_group_id,
    'shops', v_shops,
    'categories', v_categories,
    'catalog_glance', v_catalog_glance,
    'order_glance', v_buckets,
    'recent_orders', v_recent_orders,
    'active_carts', v_active_carts
  );
END;
$$;


ALTER FUNCTION "public"."get_customer_dashboard_summary"("p_tenant_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_customer_dues_report"("p_tenant_id" bigint, "p_issued_by_tenant_id" bigint DEFAULT NULL::bigint, "p_search" "text" DEFAULT NULL::"text", "p_aging_bucket" "text" DEFAULT NULL::"text", "p_min_due" numeric DEFAULT 0, "p_over_limit_only" boolean DEFAULT false, "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 50, "p_skip_count" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_books_id bigint;
  v_today date;
  v_totals jsonb;
  v_rows jsonb;
  v_total_count bigint;
  v_page integer := greatest(coalesce(p_page, 1), 1);
  v_page_size integer := greatest(least(coalesce(p_page_size, 50), 200), 1);
  v_offset integer;
BEGIN
  IF p_tenant_id IS NULL THEN
    RAISE EXCEPTION 'Tenant ID is required';
  END IF;

  v_books_id := public.resolve_parent_tenant_id(p_tenant_id);
  v_today := (timezone('Asia/Dhaka', now()))::date;
  v_offset := (v_page - 1) * v_page_size;

  IF NOT (
    public.membership_has_module_action(p_tenant_id, 'reporting_treasury', 'view')
    OR public.membership_has_module_action(v_books_id, 'reporting_treasury', 'view')
  ) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  WITH invoice_returned AS (
    SELECT
      sii.invoice_id,
      coalesce(sum(sii.return_quantity * sii.sell_price_amount), 0)::numeric(12,2) AS returned
    FROM public.sales_invoice_items sii
    GROUP BY sii.invoice_id
  ),
  invoice_payments_agg AS (
    SELECT
      ip.global_invoice_id AS invoice_id,
      coalesce(sum(CASE WHEN coalesce(gp.method, '') <> 'wallet_credit' THEN ip.amount ELSE 0 END), 0)::numeric(12,2) AS collected_cash,
      coalesce(sum(CASE WHEN gp.method = 'wallet_credit' THEN ip.amount ELSE 0 END), 0)::numeric(12,2) AS wallet_applied
    FROM public.invoice_payments ip
    JOIN public.global_payments gp ON gp.id = ip.payment_id
    WHERE ip.global_invoice_id IS NOT NULL
    GROUP BY ip.global_invoice_id
  ),
  per_invoice AS (
    SELECT
      si.billing_profile_id,
      si.due_amount,
      (si.total_amount + coalesce(ir.returned, 0))::numeric(12,2) AS billed,
      coalesce(ir.returned, 0)::numeric(12,2) AS returned,
      coalesce(ipa.collected_cash, 0)::numeric(12,2) AS collected_cash,
      coalesce(ipa.wallet_applied, 0)::numeric(12,2) AS wallet_applied,
      coalesce(si.settlement_discount_amount, 0)::numeric(12,2) AS settlement,
      coalesce(si.due_date, si.invoice_date) AS aging_date,
      CASE
        WHEN si.due_amount <= 0 THEN NULL
        WHEN (v_today - coalesce(si.due_date, si.invoice_date)) <= 0 THEN 'current'
        WHEN (v_today - coalesce(si.due_date, si.invoice_date)) BETWEEN 1 AND 30 THEN '1_30'
        WHEN (v_today - coalesce(si.due_date, si.invoice_date)) BETWEEN 31 AND 60 THEN '31_60'
        WHEN (v_today - coalesce(si.due_date, si.invoice_date)) BETWEEN 61 AND 90 THEN '61_90'
        ELSE '90_plus'
      END AS aging_bucket
    FROM public.sales_invoices si
    LEFT JOIN invoice_returned ir ON ir.invoice_id = si.id
    LEFT JOIN invoice_payments_agg ipa ON ipa.invoice_id = si.id
    WHERE si.parent_tenant_id = v_books_id
      AND si.invoice_status = 'issued'::public.global_invoice_status
      AND si.invoice_type = 'wholesale'::public.global_invoice_type
      AND si.billing_profile_id IS NOT NULL
      AND (p_issued_by_tenant_id IS NULL OR si.issued_by_tenant_id = p_issued_by_tenant_id)
  ),
  customer_base AS (
    SELECT
      pi.billing_profile_id,
      round(sum(pi.billed), 2) AS billed,
      round(sum(pi.returned), 2) AS returned,
      round(sum(pi.collected_cash), 2) AS collected_cash,
      round(sum(pi.wallet_applied), 2) AS wallet_applied,
      round(sum(pi.settlement), 2) AS settlement,
      round(sum(pi.due_amount), 2) AS still_due,
      min(pi.aging_date) FILTER (WHERE pi.due_amount > 0) AS oldest_due_date,
      count(*) FILTER (WHERE pi.due_amount > 0)::bigint AS open_invoice_count,
      round(coalesce(sum(pi.due_amount) FILTER (WHERE pi.aging_bucket = 'current'), 0), 2) AS aging_current,
      round(coalesce(sum(pi.due_amount) FILTER (WHERE pi.aging_bucket = '1_30'), 0), 2) AS aging_d1_30,
      round(coalesce(sum(pi.due_amount) FILTER (WHERE pi.aging_bucket = '31_60'), 0), 2) AS aging_d31_60,
      round(coalesce(sum(pi.due_amount) FILTER (WHERE pi.aging_bucket = '61_90'), 0), 2) AS aging_d61_90,
      round(coalesce(sum(pi.due_amount) FILTER (WHERE pi.aging_bucket = '90_plus'), 0), 2) AS aging_d90_plus
    FROM per_invoice pi
    GROUP BY pi.billing_profile_id
    HAVING sum(pi.due_amount) > 0
  ),
  customer_rows AS (
    SELECT
      cb.*,
      bp.name,
      bp.phone,
      cl.credit_limit
    FROM customer_base cb
    JOIN public.billing_profiles bp ON bp.id = cb.billing_profile_id
    LEFT JOIN LATERAL (
      SELECT max(scga.credit_limit_amount)::numeric(12,2) AS credit_limit
      FROM public.shop_customer_group_access scga
      JOIN public.shops sh ON sh.id = scga.shop_id
      WHERE scga.customer_group_id = bp.customer_group_id
        AND public.resolve_parent_tenant_id(sh.tenant_id) = v_books_id
    ) cl ON true
    WHERE cb.still_due >= coalesce(p_min_due, 0)
      AND (
        p_search IS NULL
        OR btrim(p_search) = ''
        OR bp.name ILIKE ('%' || btrim(p_search) || '%')
        OR bp.phone ILIKE ('%' || btrim(p_search) || '%')
      )
      AND (
        p_aging_bucket IS NULL
        OR btrim(p_aging_bucket) = ''
        OR (p_aging_bucket = 'current' AND cb.aging_current > 0)
        OR (p_aging_bucket = '1_30' AND cb.aging_d1_30 > 0)
        OR (p_aging_bucket = '31_60' AND cb.aging_d31_60 > 0)
        OR (p_aging_bucket = '61_90' AND cb.aging_d61_90 > 0)
        OR (p_aging_bucket = '90_plus' AND cb.aging_d90_plus > 0)
      )
      AND (
        NOT coalesce(p_over_limit_only, false)
        OR (cl.credit_limit IS NOT NULL AND cb.still_due > cl.credit_limit)
      )
  ),
  totals_calc AS (
    SELECT
      round(coalesce(sum(billed), 0), 2) AS billed,
      round(coalesce(sum(returned), 0), 2) AS returned,
      round(coalesce(sum(collected_cash), 0), 2) AS collected_cash,
      round(coalesce(sum(wallet_applied), 0), 2) AS wallet_applied,
      round(coalesce(sum(settlement), 0), 2) AS settlement,
      round(coalesce(sum(still_due), 0), 2) AS still_due,
      count(*)::bigint AS customer_count
    FROM customer_rows
  ),
  paged AS (
    SELECT *
    FROM customer_rows
    ORDER BY still_due DESC, name ASC
    OFFSET v_offset
    LIMIT v_page_size
  )
  SELECT
    (SELECT count(*) FROM customer_rows),
    (SELECT jsonb_build_object(
      'billed', billed,
      'returned', returned,
      'collected_cash', collected_cash,
      'wallet_applied', wallet_applied,
      'settlement', settlement,
      'still_due', still_due,
      'customer_count', customer_count
    ) FROM totals_calc),
    coalesce(
      (SELECT jsonb_agg(jsonb_build_object(
        'billing_profile_id', billing_profile_id,
        'name', name,
        'phone', phone,
        'credit_limit', credit_limit,
        'billed', billed,
        'returned', returned,
        'collected_cash', collected_cash,
        'wallet_applied', wallet_applied,
        'settlement', settlement,
        'still_due', still_due,
        'oldest_due_date', oldest_due_date,
        'aging', jsonb_build_object(
          'current', aging_current,
          'd1_30', aging_d1_30,
          'd31_60', aging_d31_60,
          'd61_90', aging_d61_90,
          'd90_plus', aging_d90_plus
        ),
        'open_invoice_count', open_invoice_count
      ) ORDER BY still_due DESC, name ASC) FROM paged),
      '[]'::jsonb
    )
  INTO v_total_count, v_totals, v_rows;

  RETURN jsonb_build_object(
    'totals', coalesce(v_totals, jsonb_build_object(
      'billed', 0, 'returned', 0, 'collected_cash', 0, 'wallet_applied', 0,
      'settlement', 0, 'still_due', 0, 'customer_count', 0
    )),
    'rows', coalesce(v_rows, '[]'::jsonb),
    'page', v_page,
    'page_size', v_page_size,
    'total_count', CASE WHEN coalesce(p_skip_count, true) THEN NULL ELSE v_total_count END
  );
END;
$$;


ALTER FUNCTION "public"."get_customer_dues_report"("p_tenant_id" bigint, "p_issued_by_tenant_id" bigint, "p_search" "text", "p_aging_bucket" "text", "p_min_due" numeric, "p_over_limit_only" boolean, "p_page" integer, "p_page_size" integer, "p_skip_count" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_customer_shop_order"("p_tenant_id" bigint, "p_order_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_group_id bigint;
  v_order public.shop_orders%rowtype;
  v_shop_name text;
  v_shop_slug text;
  v_sell_currency_id bigint;
  v_buy_currency_id bigint;
  v_sell_symbol text;
  v_buy_symbol text;
  v_item_count bigint;
  v_total_amount numeric;
  v_items jsonb;
  v_order_json jsonb;
  v_can_see_buy_price boolean;
  v_can_see_sell_price boolean;
begin
  if p_tenant_id is null or p_order_id is null then
    raise exception 'tenant required';
  end if;

  v_group_id := public.current_customer_group_id(p_tenant_id);
  if v_group_id is null then
    raise exception 'access denied';
  end if;

  select *
  into v_order
  from public.shop_orders o
  where o.id = p_order_id;

  if not found then
    raise exception 'order not found';
  end if;

  if v_order.tenant_id is distinct from p_tenant_id then
    raise exception 'tenant mismatch';
  end if;

  if v_order.customer_group_id is distinct from v_group_id then
    raise exception 'order not found';
  end if;

  select
    s.name,
    s.slug,
    s.sell_currency_id,
    s.buy_currency_id,
    sell_gc.symbol,
    buy_gc.symbol
  into
    v_shop_name,
    v_shop_slug,
    v_sell_currency_id,
    v_buy_currency_id,
    v_sell_symbol,
    v_buy_symbol
  from public.shops s
  left join public.global_currencies sell_gc on sell_gc.id = s.sell_currency_id
  left join public.global_currencies buy_gc on buy_gc.id = s.buy_currency_id
  where s.id = v_order.shop_id;

  select
    case
      when v_order.cart_id is not null then coalesce(c.can_see_buy_price_snapshot, perm.can_see_buy_price, false)
      else coalesce(perm.can_see_buy_price, false)
    end,
    case
      when v_order.cart_id is not null then coalesce(c.can_see_sell_price_snapshot, perm.can_see_sell_price, false)
      else coalesce(perm.can_see_sell_price, false)
    end
  into v_can_see_buy_price, v_can_see_sell_price
  from public.get_shop_permissions_for_customer(v_order.shop_id) perm
  left join public.shop_carts c on c.id = v_order.cart_id;

  select count(*)::bigint
  into v_item_count
  from public.shop_order_items soi
  where soi.order_id = v_order.id;

  select coalesce(
    sum(
      coalesce(
        soi.final_price_amount,
        soi.customer_offer_amount,
        soi.unit_sell_price_amount,
        case
          when v_order.shop_type_snapshot = 'vendor_catalog'::public.shop_type_enum and not v_can_see_buy_price then null
          else soi.unit_list_price_amount
        end
      ) * soi.quantity
    ),
    0
  )
  into v_total_amount
  from public.shop_order_items soi
  where soi.order_id = v_order.id;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', soi.id,
        'order_id', soi.order_id,
        'product_id', soi.product_id,
        'global_stock_id', soi.global_stock_id,
        'global_stock_allocation_id', soi.global_stock_allocation_id,
        'name', soi.name,
        'image_url', soi.image_url,
        'quantity', soi.quantity,
        'unit_list_price_amount', case when v_order.shop_type_snapshot = 'vendor_catalog'::public.shop_type_enum and not v_can_see_buy_price then null else soi.unit_list_price_amount end,
        'unit_list_price_currency_id', case when v_order.shop_type_snapshot = 'vendor_catalog'::public.shop_type_enum and not v_can_see_buy_price then null else soi.unit_list_price_currency_id end,
        'unit_sell_price_amount', soi.unit_sell_price_amount,
        'unit_sell_price_currency_id', soi.unit_sell_price_currency_id,
        'unit_minimum_sell_price_amount', soi.unit_minimum_sell_price_amount,
        'unit_minimum_sell_price_currency_id', soi.unit_minimum_sell_price_currency_id,
        'customer_sell_price_amount', soi.customer_sell_price_amount,
        'customer_sell_price_currency_id', soi.customer_sell_price_currency_id,
        'customer_offer_amount', soi.customer_offer_amount,
        'customer_offer_currency_id', soi.customer_offer_currency_id,
        'staff_offer_amount', soi.staff_offer_amount,
        'staff_offer_currency_id', soi.staff_offer_currency_id,
        'is_first_offer_manual', soi.is_first_offer_manual,
        'final_price_amount', soi.final_price_amount,
        'final_price_currency_id', soi.final_price_currency_id,
        'is_final_offer_manual', soi.is_final_offer_manual,
        'confirmed_quantity', soi.confirmed_quantity,
        'weight_kg', soi.weight_kg,
        'customer_decision_status', soi.customer_decision_status,
        'customer_decision_at', soi.customer_decision_at,
        'negotiation_status', soi.negotiation_status,
        'staff_offer_at', soi.staff_offer_at,
        'customer_counter_at', soi.customer_counter_at,
        'final_offer_at', soi.final_offer_at,
        'returned_quantity', soi.returned_quantity,
        'sku', p.product_code,
        'brand', p.brand,
        'barcode', p.barcode,
        'minimum_order_quantity', p.minimum_order_quantity,
        'created_at', soi.created_at,
        'updated_at', soi.updated_at
      )
      order by soi.created_at, soi.id
    ),
    '[]'::jsonb
  )
  into v_items
  from public.shop_order_items soi
  left join public.products p on p.id = soi.product_id
  where soi.order_id = v_order.id;

  v_order_json :=
    jsonb_build_object(
      'id', v_order.id,
      'tenant_id', v_order.tenant_id,
      'shop_id', v_order.shop_id,
      'shop_name', v_shop_name,
      'shop_slug', v_shop_slug,
      'customer_group_id', v_order.customer_group_id,
      'cart_id', v_order.cart_id,
      'order_no', v_order.order_no,
      'name', v_order.name,
      'shop_type_snapshot', v_order.shop_type_snapshot,
      'order_mode_snapshot', v_order.order_mode_snapshot,
      'is_negotiable_snapshot', v_order.is_negotiable_snapshot,
      'status', v_order.status,
      'negotiate_round', v_order.negotiate_round,
      'cargo_rate', v_order.cargo_rate,
      'conversion_rate', v_order.conversion_rate,
      'profit_rate', v_order.profit_rate,
      'first_offer_rate', v_order.first_offer_rate,
      'final_offer_rate', v_order.final_offer_rate,
      'profit_basis', v_order.profit_basis,
      'package_weight_kg', v_order.package_weight_kg,
      'recipient_name', v_order.recipient_name,
      'recipient_phone', v_order.recipient_phone,
      'recipient_phone_secondary', v_order.recipient_phone_secondary,
      'shipping_address', v_order.shipping_address,
      'shipping_district', v_order.shipping_district,
      'shipping_thana', v_order.shipping_thana,
      'recipient_profile_id', v_order.recipient_profile_id,
      'billing_profile_id', v_order.billing_profile_id,
      'placed_at', v_order.placed_at,
      'fulfilled_at', v_order.fulfilled_at,
      'shop_sell_currency_id', v_sell_currency_id,
      'shop_buy_currency_id', v_buy_currency_id,
      'shop_sell_currency_symbol', v_sell_symbol,
      'shop_buy_currency_symbol', v_buy_symbol,
      'can_see_buy_price', v_can_see_buy_price,
      'can_see_sell_price', v_can_see_sell_price
    )
    || jsonb_build_object(
      'created_at', v_order.created_at,
      'updated_at', v_order.updated_at,
      'cod_charge_amount', v_order.cod_charge_amount,
      'delivery_charge_amount', v_order.delivery_charge_amount,
      'print_charge_amount', v_order.print_charge_amount,
      'packing_charge_amount', v_order.packing_charge_amount,
      'discount_amount', v_order.discount_amount,
      'is_prepaid_snapshot', v_order.is_prepaid_snapshot,
      'delivery_instructions', v_order.delivery_instructions,
      'deduct_charges_from_margin', v_order.deduct_charges_from_margin,
      'deduct_cod_from_margin', v_order.deduct_cod_from_margin,
      'deduct_delivery_from_margin', v_order.deduct_delivery_from_margin,
      'deduct_print_from_margin', v_order.deduct_print_from_margin,
      'deduct_packing_from_margin', v_order.deduct_packing_from_margin,
      'item_count', v_item_count,
      'total_amount', case
        when v_order.shop_type_snapshot = 'vendor_catalog'::public.shop_type_enum
          and not v_can_see_buy_price
          and not v_can_see_sell_price then null
        when v_order.shop_type_snapshot = 'vendor_catalog'::public.shop_type_enum
          and not v_can_see_buy_price
          and v_total_amount = 0 then null
        else v_total_amount
      end,
      'cod_collect_amount', v_order.cod_collect_amount,
      'courier_name', v_order.courier_name,
      'courier_awb_number', v_order.courier_awb_number,
      'tracking_url', v_order.tracking_url,
      'payout_settlement_status', v_order.payout_settlement_status
    );

  return jsonb_build_object(
    'order', v_order_json,
    'items', v_items
  );
end;
$$;


ALTER FUNCTION "public"."get_customer_shop_order"("p_tenant_id" bigint, "p_order_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dropship_finance_hub_data"("p_tenant_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_summary jsonb;
  v_orders jsonb;
  v_merchants jsonb;
begin
  if not public.is_tenant_staff(p_tenant_id) then
    raise exception 'access denied';
  end if;

  v_summary := public.get_wallet_dashboard_summary(p_tenant_id);

  with finance_orders as (
    select
      o.id,
      o.order_no,
      o.recipient_name,
      o.status,
      o.cod_collect_amount,
      o.delivery_charge_amount,
      o.cod_charge_amount,
      o.driver_notes,
      o.courier_name,
      o.courier_remittance_ref,
      o.courier_bank_trx_id,
      o.billing_profile_id,
      o.created_at,
      o.collection_source,
      o.payout_settlement_status,
      o.is_prepaid_snapshot,
      o.global_invoice_id,
      s.name as shop_name,
      bp.name as billing_profile_name,
      inv.collection_source as invoice_collection_source,
      inv.total_amount as invoice_total_amount,
      inv.paid_amount as invoice_paid_amount
    from public.shop_orders o
    left join public.shops s on s.id = o.shop_id
    left join public.billing_profiles bp on bp.id = o.billing_profile_id
    left join public.sales_invoices inv on inv.id = o.global_invoice_id
    where o.tenant_id = p_tenant_id
      and o.shop_type_snapshot = 'dropship'
      and o.status in ('delivered', 'payment_received')
  ),
  ledger_flags as (
    select
      l.source_id,
      max(case when coalesce(l.metadata->>'purpose', '') = 'delivered_costing' then 1 else 0 end) as has_delivered_costing,
      max(case when coalesce(l.metadata->>'purpose', '') = 'courier_remittance' then 1 else 0 end) as has_remittance
    from public.universal_wallet_ledger l
    where l.parent_tenant_id = public.resolve_parent_tenant_id(p_tenant_id)
      and l.source_type = 'shop_order'
      and l.source_id in (select fo.id::text from finance_orders fo)
    group by l.source_id
  ),
  order_rows as (
    select
      fo.id,
      fo.order_no as "orderNo",
      fo.recipient_name as "customerName",
      fo.shop_name as "shopName",
      fo.courier_name as "courierName",
      fo.status::text as status,
      case
        when fo.global_invoice_id is not null then coalesce(fo.invoice_total_amount, 0)
        else coalesce(fo.cod_collect_amount, 0)
      end as "totalAmount",
      coalesce(fo.cod_collect_amount, 0) as "codCollectAmount",
      coalesce(fo.delivery_charge_amount, 0) as "deliveryChargeAmount",
      coalesce(fo.cod_charge_amount, 0) as "codChargeAmount",
      fo.driver_notes as "courierNotes",
      fo.courier_remittance_ref as "courierRemittanceRef",
      fo.courier_bank_trx_id as "courierBankTrxId",
      fo.billing_profile_id as "billingProfileId",
      fo.billing_profile_name as "billingProfileName",
      fo.created_at as "createdAt",
      case
        when coalesce(lf.has_delivered_costing, 0) = 0 and fo.status::text = 'delivered' then 'delivered_costing'
        when fo.status::text = 'delivered'
          or (coalesce(lf.has_remittance, 0) = 0 and fo.status::text <> 'payment_received')
          then 'courier_remittance'
        else 'completed'
      end as "nextStep",
      coalesce(
        fo.collection_source,
        fo.invoice_collection_source,
        case when fo.is_prepaid_snapshot then 'billing_profile' else null end
      ) as "collectionSource",
      coalesce(fo.payout_settlement_status, 'unpaid') as "payoutSettlementStatus",
      case
        when fo.global_invoice_id is not null then greatest(coalesce(fo.invoice_total_amount, 0) - coalesce(fo.invoice_paid_amount, 0), 0)
        else null
      end as "invoiceOutstanding"
    from finance_orders fo
    left join ledger_flags lf on lf.source_id = fo.id::text
    order by fo.created_at desc
  )
  select coalesce(jsonb_agg(to_jsonb(order_rows)), '[]'::jsonb)
  into v_orders
  from order_rows;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', bp.id,
        'name', bp.name,
        'payableBalance', coalesce(wa.available_balance, 0)
      )
      order by bp.name
    ),
    '[]'::jsonb
  )
  into v_merchants
  from public.billing_profiles bp
  left join public.wallet_accounts wa
    on wa.tenant_id = p_tenant_id
   and wa.entity_type = 'customer'
   and wa.entity_id = bp.id
  where bp.tenant_id = p_tenant_id;

  return jsonb_build_object(
    'kpis', jsonb_build_object(
      'courierOwedTotal', coalesce((v_summary->>'courier_cod_holding_total')::numeric, 0),
      'tenantCashTotal', coalesce((v_summary->>'tenant_cash_total')::numeric, 0),
      'middlemanPayableTotal', coalesce((v_summary->>'merchant_available_total')::numeric, 0)
    ),
    'orders', coalesce(v_orders, '[]'::jsonb),
    'merchants', coalesce(v_merchants, '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."get_dropship_finance_hub_data"("p_tenant_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dropship_management_order"("p_tenant_id" bigint, "p_order_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_detail jsonb;
  v_order public.shop_orders;
  v_settlement public.dropship_order_settlements;
  v_charge_lines jsonb;
  v_reseller_purchase_cost numeric(15,2);
  v_reseller_unit_purchase_cost numeric(15,2);
  v_order_item_quantity integer;
  v_company_procurement_cost numeric(15,2);
  v_calculated_cod numeric(15,2);
  v_collected_cod numeric(15,2);
  v_courier_name text;
  v_has_settlement boolean := false;
  v_invoice jsonb;
  v_is_returned boolean := false;
begin
  if not public.is_tenant_staff(p_tenant_id) then
    raise exception 'access denied';
  end if;

  select * into v_order
  from public.shop_orders
  where id = p_order_id and (tenant_id = p_tenant_id or parent_tenant_id = p_tenant_id);

  if v_order.id is null then
    raise exception 'order not found';
  end if;

  v_is_returned := v_order.status = 'returned'::public.shop_order_status;

  if v_order.status not in ('shipped', 'delivered', 'payment_received', 'reseller_paid', 'returned') then
    raise exception 'order status % is not eligible for dropship management desk', v_order.status;
  end if;

  v_detail := public.get_dropship_order_detail_v2(p_tenant_id, p_order_id);

  select coalesce(cs.name, v_order.courier_name)
  into v_courier_name
  from public.courier_services cs
  where cs.id::text = v_order.courier_service_id::text;

  select * into v_settlement
  from public.dropship_order_settlements
  where order_id = p_order_id;

  if v_settlement.id is not null then
    v_has_settlement := true;
    v_reseller_purchase_cost := v_settlement.reseller_purchase_cost;
    v_company_procurement_cost := v_settlement.company_procurement_cost;
    v_calculated_cod := v_settlement.calculated_cod_amount;
    v_collected_cod := v_settlement.actual_cod_collected;
  else
    select
      coalesce(sum(coalesce(soi.unit_buy_price_amount, 0) * soi.quantity), 0),
      coalesce(sum(soi.quantity), 0)
    into v_reseller_purchase_cost, v_order_item_quantity
    from public.shop_order_items soi
    where soi.order_id = p_order_id;

    if v_order_item_quantity > 0 then
      v_reseller_unit_purchase_cost := round(v_reseller_purchase_cost / v_order_item_quantity, 2);
    else
      v_reseller_unit_purchase_cost := 0;
    end if;

    select coalesce(sum(coalesce(gsa.cost_bdt, 0) * soisp.quantity), 0)
    into v_company_procurement_cost
    from public.shop_order_item_stock_picks soisp
    join public.global_stock_allocations gsa on gsa.id = soisp.global_stock_allocation_id
    where soisp.order_id = p_order_id;

    v_calculated_cod := coalesce(v_order.cod_collect_amount, (v_detail->'order'->>'recipient_grand_total')::numeric, 0);
    v_collected_cod := v_calculated_cod;
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', cl.id,
        'charge_type', cl.charge_type,
        'amount', cl.amount,
        'deduct_from_reseller', cl.deduct_from_reseller,
        'order_id', cl.order_id,
        'description', cl.description
      )
      order by cl.id
    ),
    '[]'::jsonb
  )
  into v_charge_lines
  from public.dropship_settlement_charge_lines cl
  where cl.order_id = p_order_id;

  if v_order.global_invoice_id is not null then
    select jsonb_build_object(
      'id', inv.id,
      'invoice_no', inv.invoice_number,
      'status', inv.status,
      'total_amount', inv.total_amount,
      'issued_at', inv.issued_at
    )
    into v_invoice
    from public.sales_invoices inv
    where inv.id = v_order.global_invoice_id;
  end if;

  return jsonb_build_object(
    'order_id', p_order_id,
    'order_no', v_order.order_no,
    'order_status', v_order.status,
    'created_at', v_order.created_at,
    'recipient_name', v_order.recipient_name,
    'recipient_phone', v_order.recipient_phone,
    'recipient_address', v_order.recipient_address,
    'courier_name', v_courier_name,
    'courier_awb_number', v_order.courier_awb_number,
    'reseller_name', v_detail->'order'->>'customer_group_name',
    'reseller_email', v_order.created_by_email,
    'items', v_detail->'items',
    'recipient_grand_total', (v_detail->'order'->>'recipient_grand_total')::numeric,
    'cod_collect_amount', coalesce(v_order.cod_collect_amount, (v_detail->'order'->>'recipient_grand_total')::numeric),
    'reseller_purchase_cost', v_reseller_purchase_cost,
    'reseller_unit_purchase_cost', coalesce(v_reseller_unit_purchase_cost, 0),
    'company_procurement_cost', v_company_procurement_cost,
    'calculated_cod_amount', v_calculated_cod,
    'actual_cod_collected', v_collected_cod,
    'charge_lines', v_charge_lines,
    'has_settlement', v_has_settlement,
    'invoice', v_invoice,
    'courier_remittance_ref', v_order.courier_remittance_ref,
    'collection_source', v_order.collection_source,
    'payout_settlement_status', v_order.payout_settlement_status,
    'is_returned', v_is_returned
  );
end;
$$;


ALTER FUNCTION "public"."get_dropship_management_order"("p_tenant_id" bigint, "p_order_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dropship_merchant_billable_charges"("p_order_id" bigint) RETURNS TABLE("delivery" numeric, "print" numeric, "packing" numeric, "cod" numeric)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
declare
  v_order public.shop_orders;
  v_settlement_id bigint;
  v_lines jsonb;
  v_line jsonb;
  v_delivery numeric := 0;
  v_print numeric := 0;
  v_packing numeric := 0;
  v_cod numeric := 0;
begin
  select * into v_order from public.shop_orders where id = p_order_id;
  if v_order.id is null then
    delivery := 0;
    print := 0;
    packing := 0;
    cod := 0;
    return next;
    return;
  end if;

  select s.id into v_settlement_id
  from public.dropship_order_settlements s
  where s.shop_order_id = p_order_id;

  if v_settlement_id is not null then
    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'charge_type', cl.charge_type,
          'amount', cl.amount,
          'payer', cl.payer
        )
      ),
      '[]'::jsonb
    )
    into v_lines
    from public.dropship_settlement_charge_lines cl
    where cl.settlement_id = v_settlement_id
      and cl.charge_type in ('delivery', 'print', 'packing', 'cod');
  else
    v_lines := public.build_default_dropship_settlement_charge_lines(v_order);
  end if;

  for v_line in
    select value from jsonb_array_elements(coalesce(v_lines, '[]'::jsonb))
  loop
    if coalesce(v_line->>'payer', '') = 'merchant' then
      case v_line->>'charge_type'
        when 'delivery' then
          v_delivery := coalesce((v_line->>'amount')::numeric, 0);
        when 'print' then
          v_print := coalesce((v_line->>'amount')::numeric, 0);
        when 'packing' then
          v_packing := coalesce((v_line->>'amount')::numeric, 0);
        when 'cod' then
          v_cod := coalesce((v_line->>'amount')::numeric, 0);
        else
          null;
      end case;
    end if;
  end loop;

  delivery := v_delivery;
  print := v_print;
  packing := v_packing;
  cod := v_cod;
  return next;
end;
$$;


ALTER FUNCTION "public"."get_dropship_merchant_billable_charges"("p_order_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dropship_order_detail_v2"("p_tenant_id" bigint, "p_order_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_order public.shop_orders%rowtype;
  v_shop_name text;
  v_customer_group_name text;
  v_sell_symbol text;
  v_buy_currency_id bigint;
  v_items jsonb;
  v_courier_services jsonb;
  v_items_resell_total numeric := 0;
  v_recipient_charge_total numeric := 0;
  v_recipient_grand_total numeric := 0;
  v_all_lines_resolved boolean := false;
  v_total_delivered_qty numeric := 0;
begin
  if p_tenant_id is null or p_order_id is null then
    raise exception 'tenant required';
  end if;

  if not public.is_tenant_staff(p_tenant_id) then
    raise exception 'access denied';
  end if;

  select o.*
  into v_order
  from public.shop_orders o
  where o.id = p_order_id;

  if not found then
    raise exception 'order not found';
  end if;

  if v_order.tenant_id is distinct from p_tenant_id and v_order.parent_tenant_id is distinct from p_tenant_id then
    raise exception 'tenant mismatch';
  end if;

  if v_order.shop_type_snapshot <> 'dropship' then
    raise exception 'not a dropship order';
  end if;

  select s.name, gc.symbol, s.buy_currency_id
  into v_shop_name, v_sell_symbol, v_buy_currency_id
  from public.shops s
  left join public.global_currencies gc on gc.id = s.sell_currency_id
  where s.id = v_order.shop_id;

  select cg.name
  into v_customer_group_name
  from public.customer_groups cg
  where cg.id = v_order.customer_group_id;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', soi.id,
        'order_id', soi.order_id,
        'product_id', soi.product_id,
        'global_stock_id', soi.global_stock_id,
        'global_stock_allocation_id', soi.global_stock_allocation_id,
        'name', soi.name,
        'image_url', soi.image_url,
        'quantity', soi.quantity,
        'cost_price_amount', public.resolve_shop_order_item_landed_cost(soi.global_stock_id, soi.cost_price_amount, soi.unit_list_price_amount),
        'cost_price_currency_id', coalesce(soi.cost_price_currency_id, v_buy_currency_id, soi.unit_list_price_currency_id),
        'unit_list_price_amount', public.resolve_shop_order_item_landed_cost(soi.global_stock_id, soi.cost_price_amount, soi.unit_list_price_amount),
        'unit_list_price_currency_id', coalesce(soi.cost_price_currency_id, v_buy_currency_id, soi.unit_list_price_currency_id),
        'unit_sell_price_amount', soi.unit_sell_price_amount,
        'unit_sell_price_currency_id', soi.unit_sell_price_currency_id,
        'unit_minimum_sell_price_amount', soi.unit_minimum_sell_price_amount,
        'unit_minimum_sell_price_currency_id', soi.unit_minimum_sell_price_currency_id,
        'customer_sell_price_amount',
          coalesce(soi.customer_sell_price_amount, soi.final_price_amount, soi.unit_sell_price_amount),
        'customer_sell_price_currency_id',
          coalesce(soi.customer_sell_price_currency_id, soi.final_price_currency_id, soi.unit_sell_price_currency_id),
        'final_price_amount', soi.final_price_amount,
        'final_price_currency_id', soi.final_price_currency_id,
        'returned_quantity', coalesce(soi.returned_quantity, 0),
        'confirmed_quantity', soi.confirmed_quantity,
        'is_fulfillment_unavailable', coalesce(soi.is_fulfillment_unavailable, false),
        'unavailable_reason', soi.unavailable_reason,
        'fulfillment_resolved', (
          coalesce(soi.is_fulfillment_unavailable, false)
          or coalesce(soi.confirmed_quantity, 0) > 0
        ),
        'sku', p.product_code,
        'barcode', p.barcode,
        'brand', p.brand,
        'created_at', soi.created_at,
        'updated_at', soi.updated_at
      )
      order by soi.created_at, soi.id
    ),
    '[]'::jsonb
  )
  into v_items
  from public.shop_order_items soi
  left join public.products p on p.id = soi.product_id
  where soi.order_id = v_order.id;

  select coalesce(
    sum(
      coalesce(soi.customer_sell_price_amount, soi.final_price_amount, soi.unit_sell_price_amount, 0)
      * soi.quantity
    ),
    0
  )
  into v_items_resell_total
  from public.shop_order_items soi
  where soi.order_id = v_order.id;

  v_recipient_charge_total :=
    case when not coalesce(v_order.deduct_delivery_from_margin, false)
      then coalesce(v_order.delivery_charge_amount, 0) else 0 end +
    case when not coalesce(v_order.deduct_cod_from_margin, false)
      then coalesce(v_order.cod_charge_amount, 0) else 0 end +
    case when not coalesce(v_order.deduct_print_from_margin, false)
      then coalesce(v_order.print_charge_amount, 0) else 0 end +
    case when not coalesce(v_order.deduct_packing_from_margin, false)
      then coalesce(v_order.packing_charge_amount, 0) else 0 end;

  v_recipient_grand_total :=
    v_items_resell_total + v_recipient_charge_total - coalesce(v_order.discount_amount, 0);

  select coalesce(bool_and(
    coalesce(soi.is_fulfillment_unavailable, false)
    or coalesce(soi.confirmed_quantity, 0) > 0
  ), true)
  into v_all_lines_resolved
  from public.shop_order_items soi
  where soi.order_id = v_order.id and soi.quantity > 0;

  select coalesce(sum(coalesce(soi.confirmed_quantity, 0)), 0)
  into v_total_delivered_qty
  from public.shop_order_items soi
  where soi.order_id = v_order.id;

  select coalesce(
    jsonb_agg(
      to_jsonb(cs.*)
      order by cs.created_at, cs.id
    ),
    '[]'::jsonb
  )
  into v_courier_services
  from public.courier_services cs
  where cs.is_active = true
    and (cs.tenant_id is null or cs.tenant_id = v_order.tenant_id);

  return jsonb_build_object(
    'success', true,
    'order', jsonb_build_object(
      'id', v_order.id,
      'tenant_id', v_order.tenant_id,
      'shop_id', v_order.shop_id,
      'shop_name', v_shop_name,
      'customer_group_id', v_order.customer_group_id,
      'customer_group_name', v_customer_group_name,
      'cart_id', v_order.cart_id,
      'order_no', v_order.order_no,
      'name', v_order.name,
      'shop_type_snapshot', v_order.shop_type_snapshot,
      'order_mode_snapshot', v_order.order_mode_snapshot,
      'is_negotiable_snapshot', v_order.is_negotiable_snapshot,
      'status', v_order.status,
      'negotiate_round', v_order.negotiate_round,
      'placed_at', v_order.placed_at,
      'fulfilled_at', v_order.fulfilled_at,
      'global_invoice_id', v_order.global_invoice_id,
      'created_by_email', v_order.created_by_email,
      'created_at', v_order.created_at,
      'updated_at', v_order.updated_at,
      'shop_sell_currency_symbol', v_sell_symbol,
      'recipient_name', v_order.recipient_name,
      'recipient_phone', v_order.recipient_phone,
      'recipient_phone_secondary', v_order.recipient_phone_secondary,
      'shipping_address', v_order.shipping_address,
      'shipping_thana', v_order.shipping_thana,
      'shipping_district', v_order.shipping_district,
      'shipping_post_code', null,
      'recipient_profile_id', v_order.recipient_profile_id,
      'billing_profile_id', v_order.billing_profile_id,
      'delivery_instructions', v_order.delivery_instructions,
      'is_prepaid_snapshot', v_order.is_prepaid_snapshot,
      'cod_charge_amount', v_order.cod_charge_amount,
      'delivery_charge_amount', v_order.delivery_charge_amount,
      'print_charge_amount', v_order.print_charge_amount,
      'packing_charge_amount', v_order.packing_charge_amount,
      'discount_amount', v_order.discount_amount,
      'deduct_cod_from_margin', v_order.deduct_cod_from_margin,
      'deduct_delivery_from_margin', v_order.deduct_delivery_from_margin,
      'deduct_print_from_margin', v_order.deduct_print_from_margin,
      'deduct_packing_from_margin', v_order.deduct_packing_from_margin,
      'cod_collect_amount', coalesce(v_order.cod_collect_amount, v_recipient_grand_total),
      'item_count', jsonb_array_length(v_items),
      'delivery_zone', v_order.delivery_zone,
      'courier_name', v_order.courier_name,
      'courier_awb_number', v_order.courier_awb_number,
      'tracking_url', v_order.tracking_url
    ),
    'items', v_items,
    'summary', jsonb_build_object(
      'delivery_charge_amount', v_order.delivery_charge_amount,
      'deduct_delivery_from_margin', v_order.deduct_delivery_from_margin,
      'cod_charge_amount', v_order.cod_charge_amount,
      'deduct_cod_from_margin', v_order.deduct_cod_from_margin,
      'print_charge_amount', v_order.print_charge_amount,
      'deduct_print_from_margin', v_order.deduct_print_from_margin,
      'packing_charge_amount', v_order.packing_charge_amount,
      'deduct_packing_from_margin', v_order.deduct_packing_from_margin,
      'discount_amount', v_order.discount_amount,
      'cod_collect_amount', coalesce(v_order.cod_collect_amount, v_recipient_grand_total)
    ),
    'computed', jsonb_build_object(
      'items_resell_total', v_items_resell_total,
      'recipient_charge_total', v_recipient_charge_total,
      'recipient_grand_total', v_recipient_grand_total,
      'all_lines_resolved', v_all_lines_resolved,
      'total_delivered_qty', v_total_delivered_qty,
      'delivery_zone_label',
        case v_order.delivery_zone
          when 'inside_dhaka' then 'Inside Dhaka'
          when 'outside_dhaka' then 'Outside Dhaka'
          else null
        end
    ),
    'fulfillment', jsonb_build_object(
      'pickup', jsonb_build_object(
        'merchant_id', null,
        'sender_name', coalesce(v_order.sender_name, v_order.default_sender_name),
        'pickup_phone', coalesce(v_order.pickup_phone, v_order.default_pickup_phone),
        'pickup_address', coalesce(v_order.pickup_address, v_order.default_pickup_address)
      ),
      'courier', jsonb_build_object(
        'courier_service_id', v_order.courier_service_id,
        'courier_awb_number', v_order.courier_awb_number,
        'tracking_url', v_order.tracking_url,
        'allow_open_box', coalesce(v_order.allow_open_box, false),
        'cod_charge', v_order.cod_charge_amount
      )
    ),
    'lookups', jsonb_build_object(
      'courier_services', v_courier_services
    ),
    'permissions', jsonb_build_object(
      'can_show_invoice_paper', v_order.status = 'confirmed',
      'can_start_processing', v_order.status = 'confirmed',
      'can_mark_ready_for_pickup', v_order.status = 'processing',
      'can_mark_shipped', v_order.status = 'ready_for_pickup',
      'can_print_customer_invoice', v_order.status in ('ready_for_pickup', 'shipped', 'delivered')
    )
  );
end;
$$;


ALTER FUNCTION "public"."get_dropship_order_detail_v2"("p_tenant_id" bigint, "p_order_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dropship_review_cart"("p_shop_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_shop_type public.shop_type_enum;
  v_tenant_id bigint;
  v_customer_group_id bigint;
  v_cart_id bigint;
  v_result jsonb;
  v_resell_subtotal numeric := 0;
  v_has_floor_violation boolean := false;
  v_delivery_min numeric := 60;
  v_delivery_max numeric := 130;
  v_cod_percent_min numeric := 1;
  v_cod_percent_max numeric := 1;
  v_delivery_mid numeric;
  v_cod_charge_preview numeric;
  v_recipient_grand_total numeric;
begin
  select tenant_id, shop_type into v_tenant_id, v_shop_type
  from public.shops
  where id = p_shop_id
    and is_active = true;

  if v_tenant_id is null then
    raise exception 'shop not found or inactive';
  end if;

  if v_shop_type <> 'dropship' then
    raise exception 'shop is not dropship';
  end if;

  if not public.can_customer_access_shop(p_shop_id) then
    raise exception 'access denied';
  end if;

  select access.customer_group_id into v_customer_group_id
  from public.shop_customer_group_access access
  join public.customer_groups cg on cg.id = access.customer_group_id
  join public.customer_group_members cgm on cgm.customer_group_id = cg.id
  where access.shop_id = p_shop_id
    and access.status = true
    and cg.is_active = true
    and cgm.is_active = true
    and lower(trim(cgm.email)) = public.current_user_email()
  order by access.created_at asc
  limit 1;

  if v_customer_group_id is null then
    raise exception 'no customer group access found';
  end if;

  select c.id into v_cart_id
  from public.shop_carts c
  where c.tenant_id = v_tenant_id
    and c.shop_id = p_shop_id
    and c.customer_group_id = v_customer_group_id
    and c.status = 'active'
  order by c.id desc
  limit 1;

  if v_cart_id is null then
    raise exception 'cart not found';
  end if;

  select jsonb_build_object(
    'cart', jsonb_build_object(
      'id', c.id,
      'tenant_id', c.tenant_id,
      'shop_id', c.shop_id,
      'shop_name', s.name,
      'shop_slug', s.slug,
      'customer_group_id', c.customer_group_id,
      'status', c.status,
      'allow_delivery', s.allow_delivery,
      'currency', jsonb_build_object(
        'id', s.sell_currency_id,
        'code', gc.code,
        'symbol', gc.symbol
      ),
      'charges', jsonb_build_object(
        'cod_charge_amount', c.cod_charge_amount,
        'delivery_charge_amount', c.delivery_charge_amount,
        'print_charge_amount', coalesce(nullif(c.print_charge_amount, 0), s.default_print_charge_amount),
        'packing_charge_amount', coalesce(nullif(c.packing_charge_amount, 0), s.default_packing_charge_amount),
        'discount_amount', c.discount_amount,
        'is_prepaid', c.is_prepaid,
        'delivery_instructions', c.delivery_instructions
      ),
      'margin_deductions', jsonb_build_object(
        'deduct_charges_from_margin', c.deduct_charges_from_margin,
        'deduct_print_from_margin', c.deduct_print_from_margin,
        'deduct_packing_from_margin', c.deduct_packing_from_margin
      ),
      'created_at', c.created_at,
      'updated_at', c.updated_at
    ),
    'permissions', (
      select jsonb_build_object(
        'can_browse', p.can_browse,
        'can_see_buy_price', p.can_see_buy_price,
        'can_see_sell_price', p.can_see_sell_price,
        'can_see_resell_minimum_price', p.can_see_resell_minimum_price,
        'can_add_to_cart', p.can_add_to_cart,
        'can_place_order', p.can_place_order,
        'can_negotiate', p.can_negotiate,
        'can_view_quantity', p.can_view_quantity,
        'can_set_dropship_price', p.can_set_dropship_price
      )
      from public.get_shop_permissions_for_customer(p_shop_id) p
      limit 1
    ),
    'items', coalesce(items.items, '[]'::jsonb),
    'totals', coalesce(items.totals, jsonb_build_object(
      'item_count', 0,
      'line_count', 0,
      'purchase_subtotal', 0,
      'resell_subtotal', 0,
      'estimated_profit', 0
    ))
  )
  into v_result
  from public.shop_carts c
  join public.shops s on s.id = c.shop_id
  left join public.global_currencies gc on gc.id = s.sell_currency_id
  left join lateral (
    select
      jsonb_agg(
        jsonb_build_object(
          'id', ci.id,
          'product_id', ci.product_id,
          'global_stock_id', ci.global_stock_id,
          'name', ci.name,
          'image_url', ci.image_url,
          'quantity', ci.quantity,
          'minimum_quantity', ci.minimum_quantity,
          'minimum_order_quantity', p.minimum_order_quantity,
          'purchase_price', jsonb_build_object(
            'amount', ci.unit_sell_price_amount,
            'currency_id', ci.unit_sell_price_currency_id,
            'code', sell_gc.code,
            'symbol', sell_gc.symbol
          ),
          'listing_sell_price', jsonb_build_object(
            'amount', ci.unit_sell_price_amount,
            'currency_id', ci.unit_sell_price_currency_id,
            'code', sell_gc.code,
            'symbol', sell_gc.symbol
          ),
          'resell_price', jsonb_build_object(
            'amount', coalesce(ci.customer_sell_price_amount, ci.unit_sell_price_amount),
            'currency_id', coalesce(ci.customer_sell_price_currency_id, ci.unit_sell_price_currency_id),
            'code', coalesce(cust_gc.code, sell_gc.code),
            'symbol', coalesce(cust_gc.symbol, sell_gc.symbol)
          ),
          'min_resell_price', jsonb_build_object(
            'amount', ci.unit_minimum_sell_price_amount,
            'currency_id', ci.unit_minimum_sell_price_currency_id,
            'code', min_gc.code,
            'symbol', min_gc.symbol
          ),
          'line_totals', jsonb_build_object(
            'purchase_subtotal', ci.quantity * coalesce(ci.unit_sell_price_amount, 0),
            'resell_subtotal', ci.quantity * coalesce(ci.customer_sell_price_amount, ci.unit_sell_price_amount, 0)
          ),
          'is_resell_below_floor', (
            coalesce(ci.unit_minimum_sell_price_amount, 0) > 0
            and coalesce(ci.customer_sell_price_amount, ci.unit_sell_price_amount, 0)
              < ci.unit_minimum_sell_price_amount
          )
        )
        order by ci.id
      ) as items,
      jsonb_build_object(
        'item_count', coalesce(sum(ci.quantity), 0),
        'line_count', count(ci.id),
        'purchase_subtotal', coalesce(sum(ci.quantity * coalesce(ci.unit_sell_price_amount, 0)), 0),
        'resell_subtotal', coalesce(sum(
          ci.quantity * coalesce(ci.customer_sell_price_amount, ci.unit_sell_price_amount, 0)
        ), 0),
        'estimated_profit', coalesce(sum(
          ci.quantity * (
            coalesce(ci.customer_sell_price_amount, ci.unit_sell_price_amount, 0)
            - coalesce(ci.unit_sell_price_amount, 0)
          )
        ), 0)
      ) as totals
    from public.shop_cart_items ci
    left join public.products p on p.id = ci.product_id
    left join public.global_currencies sell_gc on sell_gc.id = ci.unit_sell_price_currency_id
    left join public.global_currencies cust_gc on cust_gc.id = ci.customer_sell_price_currency_id
    left join public.global_currencies min_gc on min_gc.id = ci.unit_minimum_sell_price_currency_id
    where ci.cart_id = c.id
  ) items on true
  where c.id = v_cart_id;

  if coalesce(jsonb_array_length(v_result->'items'), 0) = 0 then
    raise exception 'cart is empty';
  end if;

  v_resell_subtotal := coalesce((v_result->'totals'->>'resell_subtotal')::numeric, 0);

  select bool_or((item->>'is_resell_below_floor')::boolean)
  into v_has_floor_violation
  from jsonb_array_elements(v_result->'items') item;

  select
    coalesce(min(least(cs.inside_dhaka_fee, cs.outside_dhaka_fee)), 60),
    coalesce(max(greatest(cs.inside_dhaka_fee, cs.outside_dhaka_fee)), 130),
    coalesce(min(cs.cod_fee_percent) filter (where cs.cod_fee_mode = 'percent_of_collect'), 1),
    coalesce(max(cs.cod_fee_percent) filter (where cs.cod_fee_mode = 'percent_of_collect'), 1)
  into v_delivery_min, v_delivery_max, v_cod_percent_min, v_cod_percent_max
  from public.courier_services cs
  where cs.tenant_id = v_tenant_id
    and cs.is_active = true;

  v_delivery_mid := (v_delivery_min + v_delivery_max) / 2;
  v_cod_charge_preview := round(v_resell_subtotal * coalesce(v_cod_percent_min, 1) / 100, 2);
  v_recipient_grand_total := v_resell_subtotal + v_delivery_mid + v_cod_charge_preview;

  return v_result || jsonb_build_object(
    'charge_estimates', jsonb_build_object(
      'delivery_min', v_delivery_min,
      'delivery_max', v_delivery_max,
      'delivery_mid', v_delivery_mid,
      'cod_percent_min', v_cod_percent_min,
      'cod_percent_max', v_cod_percent_max,
      'cod_charge_preview', v_cod_charge_preview
    ),
    'review_summary', jsonb_build_object(
      'total_units', coalesce((v_result->'totals'->>'item_count')::int, 0),
      'has_floor_violation', coalesce(v_has_floor_violation, false),
      'recipient_grand_total', v_recipient_grand_total,
      'can_continue', not coalesce(v_has_floor_violation, false)
    )
  );
end;
$$;


ALTER FUNCTION "public"."get_dropship_review_cart"("p_shop_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dropship_shop_cart"("p_shop_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_shop_type public.shop_type_enum;
  v_cart_id bigint;
  v_result jsonb;
begin
  select shop_type into v_shop_type
  from public.shops
  where id = p_shop_id
    and is_active = true;

  if v_shop_type is null then
    raise exception 'shop not found or inactive';
  end if;

  if v_shop_type <> 'dropship' then
    raise exception 'shop is not dropship';
  end if;

  v_cart_id := (public.get_or_create_shop_cart(p_shop_id)->'cart'->>'id')::bigint;

  select jsonb_build_object(
    'cart', jsonb_build_object(
      'id', c.id,
      'tenant_id', c.tenant_id,
      'shop_id', c.shop_id,
      'shop_name', s.name,
      'shop_slug', s.slug,
      'customer_group_id', c.customer_group_id,
      'status', c.status,
      'allow_delivery', s.allow_delivery,
      'currency', jsonb_build_object(
        'id', s.sell_currency_id,
        'code', gc.code,
        'symbol', gc.symbol
      ),
      'charges', jsonb_build_object(
        'cod_charge_amount', c.cod_charge_amount,
        'delivery_charge_amount', c.delivery_charge_amount,
        'print_charge_amount', coalesce(nullif(c.print_charge_amount, 0), s.default_print_charge_amount),
        'packing_charge_amount', coalesce(nullif(c.packing_charge_amount, 0), s.default_packing_charge_amount),
        'discount_amount', c.discount_amount,
        'is_prepaid', c.is_prepaid,
        'delivery_instructions', c.delivery_instructions
      ),
      'margin_deductions', jsonb_build_object(
        'deduct_charges_from_margin', c.deduct_charges_from_margin,
        'deduct_print_from_margin', c.deduct_print_from_margin,
        'deduct_packing_from_margin', c.deduct_packing_from_margin
      ),
      'created_at', c.created_at,
      'updated_at', c.updated_at
    ),
    'permissions', (
      select jsonb_build_object(
        'can_browse', p.can_browse,
        'can_see_buy_price', p.can_see_buy_price,
        'can_see_sell_price', p.can_see_sell_price,
        'can_see_resell_minimum_price', p.can_see_resell_minimum_price,
        'can_add_to_cart', p.can_add_to_cart,
        'can_place_order', p.can_place_order,
        'can_negotiate', p.can_negotiate,
        'can_view_quantity', p.can_view_quantity,
        'can_set_dropship_price', p.can_set_dropship_price
      )
      from public.get_shop_permissions_for_customer(p_shop_id) p
      limit 1
    ),
    'items', coalesce(items.items, '[]'::jsonb),
    'totals', coalesce(items.totals, jsonb_build_object(
      'item_count', 0,
      'line_count', 0,
      'purchase_subtotal', 0,
      'resell_subtotal', 0,
      'estimated_profit', 0
    ))
  )
  into v_result
  from public.shop_carts c
  join public.shops s on s.id = c.shop_id
  left join public.global_currencies gc on gc.id = s.sell_currency_id
  left join lateral (
    select
      jsonb_agg(
        jsonb_build_object(
          'id', ci.id,
          'product_id', ci.product_id,
          'global_stock_id', ci.global_stock_id,
          'name', ci.name,
          'image_url', ci.image_url,
          'quantity', ci.quantity,
          'minimum_quantity', ci.minimum_quantity,
          'minimum_order_quantity', p.minimum_order_quantity,
          'purchase_price', jsonb_build_object(
            'amount', ci.unit_sell_price_amount,
            'currency_id', ci.unit_sell_price_currency_id,
            'code', sell_gc.code,
            'symbol', sell_gc.symbol
          ),
          'listing_sell_price', jsonb_build_object(
            'amount', ci.unit_sell_price_amount,
            'currency_id', ci.unit_sell_price_currency_id,
            'code', sell_gc.code,
            'symbol', sell_gc.symbol
          ),
          'resell_price', jsonb_build_object(
            'amount', coalesce(ci.customer_sell_price_amount, ci.unit_sell_price_amount),
            'currency_id', coalesce(ci.customer_sell_price_currency_id, ci.unit_sell_price_currency_id),
            'code', coalesce(cust_gc.code, sell_gc.code),
            'symbol', coalesce(cust_gc.symbol, sell_gc.symbol)
          ),
          'min_resell_price', jsonb_build_object(
            'amount', ci.unit_minimum_sell_price_amount,
            'currency_id', ci.unit_minimum_sell_price_currency_id,
            'code', min_gc.code,
            'symbol', min_gc.symbol
          ),
          'line_totals', jsonb_build_object(
            'purchase_subtotal', ci.quantity * coalesce(ci.unit_sell_price_amount, 0),
            'resell_subtotal', ci.quantity * coalesce(ci.customer_sell_price_amount, ci.unit_sell_price_amount, 0)
          ),
          'is_resell_below_floor', (
            coalesce(ci.unit_minimum_sell_price_amount, 0) > 0
            and coalesce(ci.customer_sell_price_amount, ci.unit_sell_price_amount, 0)
              < ci.unit_minimum_sell_price_amount
          )
        )
        order by ci.id
      ) as items,
      jsonb_build_object(
        'item_count', coalesce(sum(ci.quantity), 0),
        'line_count', count(ci.id),
        'purchase_subtotal', coalesce(sum(ci.quantity * coalesce(ci.unit_sell_price_amount, 0)), 0),
        'resell_subtotal', coalesce(sum(
          ci.quantity * coalesce(ci.customer_sell_price_amount, ci.unit_sell_price_amount, 0)
        ), 0),
        'estimated_profit', coalesce(sum(
          ci.quantity * (
            coalesce(ci.customer_sell_price_amount, ci.unit_sell_price_amount, 0)
            - coalesce(ci.unit_sell_price_amount, 0)
          )
        ), 0)
      ) as totals
    from public.shop_cart_items ci
    left join public.products p on p.id = ci.product_id
    left join public.global_currencies sell_gc on sell_gc.id = ci.unit_sell_price_currency_id
    left join public.global_currencies cust_gc on cust_gc.id = ci.customer_sell_price_currency_id
    left join public.global_currencies min_gc on min_gc.id = ci.unit_minimum_sell_price_currency_id
    where ci.cart_id = c.id
  ) items on true
  where c.id = v_cart_id;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."get_dropship_shop_cart"("p_shop_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dropship_shop_readiness"("p_shop_id" bigint) RETURNS TABLE("shop_id" bigint, "has_access_group_with_price" boolean, "has_customer_group_with_members" boolean, "has_billing_profile_linked" boolean, "has_listing_with_floor" boolean, "has_active_courier" boolean, "ready" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_tenant_id bigint;
  v_shop_type public.shop_type_enum;

  v_has_access_group_with_price boolean := false;
  v_has_customer_group_with_members boolean := false;
  v_has_billing_profile_linked boolean := false;
  v_has_listing_with_floor boolean := false;
  v_has_active_courier boolean := false;
  v_ready boolean := false;
begin
  select tenant_id, shop_type
  into v_tenant_id, v_shop_type
  from public.shops
  where id = p_shop_id;

  if v_tenant_id is null then
    return;
  end if;

  -- 1. Access group with can_set_dropship_price
  select coalesce(bool_or(
    access.status = true and coalesce(access.can_set_dropship_price, profile.default_can_set_dropship_price, false) = true
  ), false)
  into v_has_access_group_with_price
  from public.shop_customer_group_access access
  left join public.customer_group_shop_profiles profile
    on profile.customer_group_id = access.customer_group_id and profile.tenant_id = v_tenant_id
  where access.shop_id = p_shop_id;

  -- 2. Customer group with active members attached to shop access
  select exists (
    select 1
    from public.shop_customer_group_access access
    join public.customer_group_members cgm on cgm.customer_group_id = access.customer_group_id
    where access.shop_id = p_shop_id
      and access.status = true
  )
  into v_has_customer_group_with_members;

  -- 3. Billing profile linked (resolve_billing_profile_for_customer_group returns non-null for at least one linked group)
  select exists (
    select 1
    from public.shop_customer_group_access access
    where access.shop_id = p_shop_id
      and access.status = true
      and public.resolve_billing_profile_for_customer_group(v_tenant_id, access.customer_group_id) is not null
  )
  into v_has_billing_profile_linked;

  -- 4. Active listing with floor price set (minimum_sell_price_amount is not null and > 0)
  select exists (
    select 1
    from public.shop_product_listings
    where shop_id = p_shop_id
      and is_active = true
      and minimum_sell_price_amount is not null
      and minimum_sell_price_amount > 0
  )
  into v_has_listing_with_floor;

  -- 5. Active courier service available for tenant
  select exists (
    select 1
    from public.courier_services
    where tenant_id = v_tenant_id
      and is_active = true
  )
  into v_has_active_courier;

  v_ready := (
    v_has_access_group_with_price and
    v_has_customer_group_with_members and
    v_has_billing_profile_linked and
    v_has_listing_with_floor and
    v_has_active_courier
  );

  return query select
    p_shop_id,
    v_has_access_group_with_price,
    v_has_customer_group_with_members,
    v_has_billing_profile_linked,
    v_has_listing_with_floor,
    v_has_active_courier,
    v_ready;
end;
$$;


ALTER FUNCTION "public"."get_dropship_shop_readiness"("p_shop_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dropship_wallet_reconciliation_report"("p_tenant_id" bigint DEFAULT NULL::bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_target_tenant_id bigint;
  v_missing_invoice_billed bigint := 0;
  v_missing_courier_remittance bigint := 0;
  v_missing_return_compensation bigint := 0;
  v_mixed_customer_profit bigint := 0;
  v_uncanonicalized_source_ids bigint := 0;
  v_conflicting_active_offers bigint := 0;
  v_missing_or_duplicate_gifts bigint := 0;
begin
  if p_tenant_id is not null then
    v_target_tenant_id := p_tenant_id;
  else
    v_target_tenant_id := public.current_tenant_id();
  end if;

  if not (
    public.is_superadmin()
    or exists (
      select 1 from public.memberships m
      where (v_target_tenant_id is null or m.tenant_id = v_target_tenant_id)
        and lower(trim(m.email)) = public.current_user_email()
        and m.is_active = true
        and m.role in ('admin', 'staff')
    )
  ) then
    raise exception 'Permission denied: Admin or Staff role required for reconciliation report';
  end if;

  -- 1. Posted dropship invoices missing invoice_billed (P0A contract)
  select count(*) into v_missing_invoice_billed
  from public.global_invoices i
  where i.invoice_type = 'dropship'
    and i.invoice_status = 'posted'
    and i.billing_profile_id is not null
    and i.total_amount > 0
    and (v_target_tenant_id is null or i.tenant_id = v_target_tenant_id)
    and not exists (
      select 1 from public.universal_wallet_ledger u
      where u.tenant_id = i.tenant_id
        and u.entity_type = 'customer'
        and u.entity_id = i.billing_profile_id
        and u.source_type = 'shop_order'
        and u.metadata->>'transaction_type' = 'invoice_billed'
        and (u.metadata->>'invoice_id' = i.id::text or u.source_id = i.invoice_no)
    );

  -- 2. Remitted shop orders missing courier remittance UWL entry
  select count(*) into v_missing_courier_remittance
  from public.shop_orders o
  where o.shop_type_snapshot = 'dropship'
    and o.status = 'payment_received'
    and o.courier_remittance_ref is not null
    and (v_target_tenant_id is null or o.tenant_id = v_target_tenant_id)
    and not exists (
      select 1 from public.universal_wallet_ledger u
      where u.tenant_id = o.tenant_id
        and u.entity_type = 'courier'
        and u.source_type = 'shop_order'
        and u.source_id = o.id::text
        and u.metadata->>'purpose' = 'courier_remittance'
    );

  -- 3. Finalized returns missing return compensating UWL entry
  select count(*) into v_missing_return_compensation
  from public.shop_orders o
  where o.shop_type_snapshot = 'dropship'
    and o.status = 'returned'
    and (v_target_tenant_id is null or o.tenant_id = v_target_tenant_id)
    and not exists (
      select 1 from public.universal_wallet_ledger u
      where u.tenant_id = o.tenant_id
        and u.source_type = 'shop_order'
        and u.source_id = o.id::text
        and (
          u.metadata->>'purpose' = 'dropship_return_finalize'
          or u.metadata->>'transaction_type' in (
            'return_reversal',
            'return_profit_clawback',
            'return_revenue_reversal'
          )
        )
    );

  -- 4. Mixed customer vs middleman profit rows
  select count(*) into v_mixed_customer_profit
  from public.universal_wallet_ledger u
  where u.entity_type = 'customer'
    and u.source_type = 'shop_order'
    and u.metadata->>'transaction_type' = 'dropship_profit'
    and (v_target_tenant_id is null or u.tenant_id = v_target_tenant_id);

  -- 5. Uncanonicalized source_ids (order_no instead of order_id string), exclude invoice_billed
  select count(*) into v_uncanonicalized_source_ids
  from public.universal_wallet_ledger u
  join public.shop_orders o on o.tenant_id = u.tenant_id and o.order_no = u.source_id
  where u.source_type = 'shop_order'
    and coalesce(u.metadata->>'transaction_type', '') <> 'invoice_billed'
    and (v_target_tenant_id is null or u.tenant_id = v_target_tenant_id);

  -- 6. Conflicting active offer prices (P2 shop_product_offers)
  select count(*) into v_conflicting_active_offers
  from (
    select shop_id, product_id, condition_bucket
    from public.shop_product_offers
    where is_active = true
    group by shop_id, product_id, condition_bucket
    having count(*) > 1
  ) t;

  -- 7. Legacy gift rules removed - drift is 0
  v_missing_or_duplicate_gifts := 0;

  return jsonb_build_object(
    'reconciliation_time', now(),
    'tenant_id', v_target_tenant_id,
    'healthy', (
      v_missing_invoice_billed = 0 and
      v_missing_courier_remittance = 0 and
      v_missing_return_compensation = 0 and
      v_mixed_customer_profit = 0 and
      v_uncanonicalized_source_ids = 0 and
      v_conflicting_active_offers = 0 and
      v_missing_or_duplicate_gifts = 0
    ),
    'drift_counts', jsonb_build_object(
      'missing_invoice_billed', v_missing_invoice_billed,
      'missing_courier_remittance', v_missing_courier_remittance,
      'missing_return_compensation', v_missing_return_compensation,
      'mixed_customer_profit', v_mixed_customer_profit,
      'uncanonicalized_source_ids', v_uncanonicalized_source_ids,
      'conflicting_active_offers', v_conflicting_active_offers,
      'missing_or_duplicate_gifts', v_missing_or_duplicate_gifts
    )
  );
end;
$$;


ALTER FUNCTION "public"."get_dropship_wallet_reconciliation_report"("p_tenant_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_effective_grants"("p_tenant_id" bigint) RETURNS TABLE("module_key" "text", "action" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_member_id bigint;
  v_tenant_role_id bigint;
  v_role_is_admin boolean;
  v_member_role public.app_role;
begin
  select m.id, m.tenant_role_id, tr.is_admin, m.role
  into v_member_id, v_tenant_role_id, v_role_is_admin, v_member_role
  from public.memberships m
  left join public.tenant_roles tr on tr.id = m.tenant_role_id
  where m.tenant_id = p_tenant_id
    and lower(trim(m.email)) = public.current_user_email()
    and m.is_active = true;

  if public.is_superadmin()
     or public.is_network_owner(p_tenant_id)
     or v_member_role = 'manager'::public.app_role
     or coalesce(v_role_is_admin, false) = true then
    return query
    select ma.module_key, ma.action
    from public.module_actions ma
    join public.tenant_modules tm on tm.module_key = ma.module_key
    where tm.tenant_id = p_tenant_id
      and tm.is_active = true
      and ma.is_active = true
      and (ma.scope <> 'platform' or public.is_superadmin())
      and not (
        exists (
          select 1
          from public.tenants
          where id = p_tenant_id
            and parent_id is not null
        ) and ma.module_key in (
          'global_shipment', 'global_stock', 'global_stock_type', 'procurement_stock',
          'shipment_reports', 'parent_dashboard', 'investor_reports',
          'investor_profiles', 'investor_capital_ledger', 'investor_shipment_share', 'investor_portal'
        )
      );
    return;
  end if;

  return query
  with role_allowed as (
    select rg.module_key, rg.action
    from public.tenant_role_grants rg
    where rg.tenant_role_id = v_tenant_role_id
      and rg.allowed = true
  ),
  with_overrides as (
    select ra.module_key, ra.action from role_allowed ra
    union
    select mg.module_key, mg.action
    from public.membership_grants mg
    where mg.membership_id = v_member_id
      and mg.effect = 'allow'
  ),
  effective as (
    select wo.module_key, wo.action from with_overrides wo
    except
    select mg.module_key, mg.action
    from public.membership_grants mg
    where mg.membership_id = v_member_id
      and mg.effect = 'deny'
  )
  select e.module_key, e.action
  from effective e
  join public.module_actions ma on ma.module_key = e.module_key and ma.action = e.action
  join public.tenant_modules tm on tm.module_key = e.module_key
  where tm.tenant_id = p_tenant_id
    and tm.is_active = true
    and ma.is_active = true
    and (ma.scope <> 'platform' or public.is_superadmin())
    and not (
      exists (
        select 1
        from public.tenants
        where id = p_tenant_id
          and parent_id is not null
      ) and ma.module_key in (
        'global_shipment', 'global_stock', 'global_stock_type', 'procurement_stock',
        'shipment_reports', 'parent_dashboard', 'investor_reports',
        'investor_profiles', 'investor_capital_ledger', 'investor_shipment_share', 'investor_portal'
      )
    );
end;
$$;


ALTER FUNCTION "public"."get_effective_grants"("p_tenant_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_effective_item_role"("p_item_id" bigint, "p_user_email" "text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_role text;
  v_parent_id bigint;
  v_tenant_id bigint;
  v_created_by_email text;
  v_user_role_in_tenant text;
  v_is_superadmin boolean;
  v_email text;
  v_accessibility text;
  v_type text;
begin
  v_email := lower(trim(p_user_email));

  -- 1. Check if user is superadmin
  select exists (
    select 1 from public.memberships m
    where lower(trim(m.email)) = v_email
      and m.role = 'superadmin'
      and m.is_active = true
  ) into v_is_superadmin;

  if v_is_superadmin then
    return 'owner';
  end if;

  -- Get item info
  select parent_id, tenant_id, created_by_email, accessibility, type
  into v_parent_id, v_tenant_id, v_created_by_email, v_accessibility, v_type
  from public.items
  where id = p_item_id;

  if not found then
    return null;
  end if;

  -- PRIVATE accessibility checks (ONLY creator/superadmin)
  if v_accessibility = 'private' then
    if lower(trim(v_created_by_email)) = v_email then
      return 'owner';
    else
      return null;
    end if;
  end if;

  -- RESTRICTED accessibility checks (ONLY creator/superadmin, explicit permissions, or assignees)
  if v_accessibility = 'restricted' then
    -- Check creator
    if lower(trim(v_created_by_email)) = v_email then
      return 'owner';
    end if;

    -- Check explicit permissions on this specific item
    select role into v_role
    from public.item_permissions
    where item_id = p_item_id and lower(trim(user_email)) = v_email;

    if v_role is not null then
      return v_role;
    end if;

    -- Check if user is an assignee
    if exists (
      select 1 from public.item_assignees
      where item_id = p_item_id and lower(trim(user_email)) = v_email
    ) then
      return 'viewer';
    end if;

    -- Restricted notes do not inherit parent visibility nor do they fallback to tenant memberships
    return null;
  end if;

  -- STANDARD PUBLIC accessibility checks
  -- Check creator
  if lower(trim(v_created_by_email)) = v_email then
    return 'owner';
  end if;

  -- Check explicit permissions on this item
  select role into v_role
  from public.item_permissions
  where item_id = p_item_id and lower(trim(user_email)) = v_email;

  if v_role is not null then
    return v_role;
  end if;

  -- Check recursive parent permissions
  if v_parent_id is not null then
    v_role := public.get_effective_item_role(v_parent_id, v_email);
    if v_role is not null then
      return v_role;
    end if;
  end if;

  -- Fallback to tenant memberships
  if v_tenant_id is not null then
    select m.role::text into v_user_role_in_tenant
    from public.memberships m
    where lower(trim(m.email)) = v_email
      and m.tenant_id = v_tenant_id
      and m.is_active = true;

    if v_user_role_in_tenant = 'admin' then
      return 'owner';
    elsif v_user_role_in_tenant = 'staff' then
      return 'editor';
    elsif v_user_role_in_tenant = 'viewer' then
      return 'viewer';
    end if;
  end if;

  return null;
end;
$$;


ALTER FUNCTION "public"."get_effective_item_role"("p_item_id" bigint, "p_user_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_investor_allocation_detail"("p_tenant_id" bigint, "p_investor_id" bigint, "p_global_shipment_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_shipment record;
  v_investment record;
  v_pnl jsonb;
begin
  if not (
    public.user_can_manage_parent_tenant(p_tenant_id)
    or (public.auth_investor_id() = p_investor_id)
  ) then
    raise exception 'not allowed';
  end if;

  select * into v_shipment
  from public.global_shipments
  where id = p_global_shipment_id;

  if not found then
    return null;
  end if;

  select * into v_investment
  from public.shipment_investments
  where investor_id = p_investor_id
    and global_shipment_id = p_global_shipment_id
    and status = 'active';

  if not found then
    return null;
  end if;

  v_pnl := public.get_shipment_pnl(p_tenant_id, p_global_shipment_id);

  return jsonb_build_object(
    'id', v_investment.id,
    'global_shipment_id', v_investment.global_shipment_id,
    'shipment_name', v_shipment.name,
    'shipment_status', v_shipment.status,
    'cost_share_pct', v_investment.cost_share_pct,
    'allocated_cost', v_investment.allocated_cost,
    'computed_profit', v_investment.computed_profit,
    'profit_status', v_investment.profit_status,
    'created_at', v_investment.created_at,
    'invested_amount', v_investment.invested_amount,
    'total_landed_cost', coalesce((v_pnl -> 'totals' ->> 'landed_cost')::numeric, 0.00),
    'realized_revenue', coalesce((v_pnl -> 'totals' ->> 'revenue')::numeric, 0.00),
    'gross_profit', coalesce((v_pnl -> 'totals' ->> 'gross_profit')::numeric, 0.00),
    'unsold_value', coalesce((v_pnl -> 'totals' ->> 'unsold_value')::numeric, 0.00),
    'shrinkage_value', coalesce((v_pnl -> 'totals' ->> 'shrinkage_value')::numeric, 0.00)
  );
end;
$$;


ALTER FUNCTION "public"."get_investor_allocation_detail"("p_tenant_id" bigint, "p_investor_id" bigint, "p_global_shipment_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_investor_bootstrap_context"("p_tenant_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_membership public.memberships;
  v_tenant public.tenants;
  v_perm_version bigint;
begin
  select * into v_tenant from public.tenants where id = p_tenant_id;
  if v_tenant.id is null then raise exception 'tenant not found'; end if;

  select * into v_membership
  from public.memberships m
  where m.tenant_id = p_tenant_id
    and lower(trim(m.email)) = public.current_user_email()
    and m.is_active = true
    and m.role = 'investor'::public.app_role
  limit 1;

  if v_membership.id is null then
    return jsonb_build_object('authenticated', false, 'tenant', row_to_json(v_tenant));
  end if;

  select version into v_perm_version
  from public.tenant_permission_versions
  where tenant_id = p_tenant_id;

  if v_perm_version is null then
    perform public.bump_tenant_permission_version(p_tenant_id);
    v_perm_version := 1;
  end if;

  return jsonb_build_object(
    'authenticated', true,
    'tenant', row_to_json(v_tenant),
    'investor_account', row_to_json(v_membership),
    'portfolio', public.get_investor_portfolio_summary(v_membership.investor_id),
    'module_keys', (
      select coalesce(jsonb_agg(tm.module_key), '[]'::jsonb)
      from public.tenant_modules tm
      where tm.tenant_id = p_tenant_id
        and tm.is_active = true
        and tm.module_key = 'investor_portal'
    ),
    'permission_version', v_perm_version
  );
end;
$$;


ALTER FUNCTION "public"."get_investor_bootstrap_context"("p_tenant_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_investor_capital_report"("p_tenant_id" bigint, "p_investor_id" bigint, "p_start_date" "date", "p_end_date" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_deposits numeric(12,2);
  v_withdrawals numeric(12,2);
  v_profit numeric(12,2);
  v_starting_balance numeric(12,2);
  v_ending_balance numeric(12,2);
  v_starting_deposits numeric(12,2);
  v_starting_withdrawals numeric(12,2);
  v_starting_profit numeric(12,2);
begin
  if not (
    public.membership_has_module_action(p_tenant_id, 'investor_reports', 'view')
    or (public.auth_investor_id() = p_investor_id)
  ) then
    raise exception 'not allowed';
  end if;

  select coalesce(sum(amount), 0) into v_deposits
  from public.investor_transactions
  where investor_id = p_investor_id
    and type in ('deposit', 'capital_in', 'capital_adjustment', 'manual_adjustment')
    and date >= p_start_date and date <= p_end_date;

  select coalesce(sum(amount), 0) into v_withdrawals
  from public.investor_transactions
  where investor_id = p_investor_id
    and type in ('withdrawal', 'withdrawal_paid', 'profit_payout')
    and date >= p_start_date and date <= p_end_date;

  select coalesce(sum(computed_profit), 0) into v_profit
  from public.shipment_investments
  where investor_id = p_investor_id
    and status = 'active'
    and profit_status = 'realized'
    and updated_at::date >= p_start_date and updated_at::date <= p_end_date;

  select coalesce(sum(amount), 0) into v_starting_deposits
  from public.investor_transactions
  where investor_id = p_investor_id
    and type in ('deposit', 'capital_in', 'capital_adjustment', 'manual_adjustment')
    and date < p_start_date;

  select coalesce(sum(amount), 0) into v_starting_withdrawals
  from public.investor_transactions
  where investor_id = p_investor_id
    and type in ('withdrawal', 'withdrawal_paid', 'profit_payout')
    and date < p_start_date;

  select coalesce(sum(computed_profit), 0) into v_starting_profit
  from public.shipment_investments
  where investor_id = p_investor_id
    and status = 'active'
    and profit_status = 'realized'
    and updated_at::date < p_start_date;

  v_starting_balance := v_starting_deposits + v_starting_profit - v_starting_withdrawals;
  v_ending_balance := v_starting_balance + v_deposits + v_profit - v_withdrawals;

  return jsonb_build_object(
    'investor_id', p_investor_id,
    'start_date', p_start_date,
    'end_date', p_end_date,
    'starting_balance', v_starting_balance,
    'deposits_sum', v_deposits,
    'withdrawals_sum', v_withdrawals,
    'profit_earned_sum', v_profit,
    'ending_balance', v_ending_balance
  );
end;
$$;


ALTER FUNCTION "public"."get_investor_capital_report"("p_tenant_id" bigint, "p_investor_id" bigint, "p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_investor_dashboard_summary"("p_tenant_id" bigint, "p_investor_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_total_capital_in numeric(12,2) := 0;
  v_total_withdrawn numeric(12,2) := 0;
  v_deployed_capital numeric(12,2) := 0;
  v_realized_profit numeric(12,2) := 0;
  v_unrealized_profit numeric(12,2) := 0;
  v_withdrawable_balance numeric(12,2) := 0;
begin
  if not (
    public.user_can_manage_parent_tenant(p_tenant_id)
    or (public.auth_investor_id() = p_investor_id)
  ) then
    raise exception 'not allowed';
  end if;

  select coalesce(sum(amount), 0) into v_total_capital_in
  from public.investor_transactions
  where investor_id = p_investor_id
    and type in ('deposit', 'capital_in', 'capital_adjustment', 'manual_adjustment');

  select coalesce(sum(amount), 0) into v_total_withdrawn
  from public.investor_transactions
  where investor_id = p_investor_id
    and type in ('withdrawal', 'withdrawal_paid', 'profit_payout');

  select coalesce(sum(allocated_cost), 0) into v_deployed_capital
  from public.shipment_investments
  where investor_id = p_investor_id
    and status = 'active';

  select
    coalesce(sum(case when profit_status = 'realized' then computed_profit else 0 end), 0),
    coalesce(sum(case when profit_status in ('open', 'partial') then computed_profit else 0 end), 0)
  into v_realized_profit, v_unrealized_profit
  from public.shipment_investments
  where investor_id = p_investor_id
    and status = 'active';

  v_withdrawable_balance := v_realized_profit - v_total_withdrawn;

  return jsonb_build_object(
    'total_capital_in', v_total_capital_in,
    'deployed_capital', v_deployed_capital,
    'unallocated_cash', v_total_capital_in - v_total_withdrawn - v_deployed_capital,
    'realized_profit', v_realized_profit,
    'unrealized_profit', v_unrealized_profit,
    'withdrawable_balance', v_withdrawable_balance,
    'total_withdrawn', v_total_withdrawn
  );
end;
$$;


ALTER FUNCTION "public"."get_investor_dashboard_summary"("p_tenant_id" bigint, "p_investor_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_investor_portfolio_summary"("p_investor_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_investor public.investors;
  v_deposits numeric(12,2);
  v_withdrawals numeric(12,2);
  v_deployed numeric(12,2);
  v_payouts numeric(12,2);
  v_realized_profit numeric(12,2);
  v_unrealized_profit numeric(12,2);
begin
  select * into v_investor from public.investors where id = p_investor_id;
  if v_investor.id is null then raise exception 'investor not found'; end if;

  if not (
    public.user_can_manage_parent_tenant(v_investor.tenant_id)
    or (public.auth_investor_id() = p_investor_id)
  ) then
    raise exception 'not allowed';
  end if;

  -- Total capital in including adjustments
  select coalesce(sum(amount), 0) into v_deposits
  from public.investor_transactions
  where investor_id = p_investor_id
    and type in ('deposit', 'capital_in', 'capital_adjustment', 'manual_adjustment');

  -- Total withdrawals
  select coalesce(sum(amount), 0) into v_withdrawals
  from public.investor_transactions
  where investor_id = p_investor_id
    and type in ('withdrawal', 'withdrawal_paid', 'profit_payout');

  -- Legacy payouts field (for compatibility if needed)
  select coalesce(sum(amount), 0) into v_payouts
  from public.investor_transactions
  where investor_id = p_investor_id
    and type = 'profit_payout';

  -- Deployed capital
  select coalesce(sum(allocated_cost), 0) into v_deployed
  from public.shipment_investments
  where investor_id = p_investor_id and status = 'active';

  -- Realized & Unrealized profits
  select
    coalesce(sum(case when profit_status = 'realized' then computed_profit else 0 end), 0),
    coalesce(sum(case when profit_status in ('open', 'partial') then computed_profit else 0 end), 0)
  into v_realized_profit, v_unrealized_profit
  from public.shipment_investments
  where investor_id = p_investor_id and status = 'active';

  return jsonb_build_object(
    'investor', row_to_json(v_investor),
    'balances', jsonb_build_object(
      'deposits', v_deposits,
      'withdrawals', v_withdrawals,
      'deployed', v_deployed,
      'available', v_deposits - v_withdrawals - v_deployed,
      'payouts', v_payouts,
      'realized_profit', v_realized_profit,
      'unrealized_profit', v_unrealized_profit,
      'withdrawable_balance', v_realized_profit - v_withdrawals
    ),
    'active_investments', (
      select coalesce(jsonb_agg(to_jsonb(si.*)), '[]'::jsonb)
      from public.shipment_investments si
      where si.investor_id = p_investor_id and si.status = 'active'
    )
  );
end;
$$;


ALTER FUNCTION "public"."get_investor_portfolio_summary"("p_investor_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_item_details"("p_item_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_email text;
  v_item jsonb;
  v_assignees jsonb;
  v_tags jsonb;
  v_comments jsonb;
  v_permissions jsonb;
  v_activity_logs jsonb;
begin
  v_email := public.current_user_email();

  -- Check item exists and permissions allow reading it
  if public.get_effective_item_role(p_item_id, v_email) is null then
    return null;
  end if;

  -- 1. Fetch item details
  select row_to_json(i)
  into v_item
  from public.items i
  where i.id = p_item_id;

  -- 2. Fetch assignees
  select coalesce(json_agg(row_to_json(ia)), '[]'::json)
  into v_assignees
  from (
    select * from public.item_assignees
    where item_id = p_item_id
  ) ia;

  -- 3. Fetch tags
  select coalesce(json_agg(row_to_json(t)), '[]'::json)
  into v_tags
  from (
    select t.* from public.item_tags it
    join public.tags t on t.id = it.tag_id
    where it.item_id = p_item_id
  ) t;

  -- 4. Fetch comments (ordered by created_at asc)
  select coalesce(json_agg(row_to_json(c)), '[]'::json)
  into v_comments
  from (
    select * from public.comments
    where item_id = p_item_id
    order by created_at asc
  ) c;

  -- 5. Fetch permissions
  select coalesce(json_agg(row_to_json(ip)), '[]'::json)
  into v_permissions
  from (
    select * from public.item_permissions
    where item_id = p_item_id
  ) ip;

  -- 6. Fetch activity logs (ordered by created_at desc)
  select coalesce(json_agg(row_to_json(al)), '[]'::json)
  into v_activity_logs
  from (
    select * from public.activity_logs
    where item_id = p_item_id
    order by created_at desc
  ) al;

  -- Return combined result
  return jsonb_build_object(
    'item', v_item,
    'assignees', v_assignees,
    'tags', v_tags,
    'comments', v_comments,
    'permissions', v_permissions,
    'activity_logs', v_activity_logs
  );
end;
$$;


ALTER FUNCTION "public"."get_item_details"("p_item_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_koba_cart"("p_tenant_id" bigint, "p_customer_group_id" bigint DEFAULT NULL::bigint) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select jsonb_build_object(
    'cart',
    to_jsonb(c),
    'items',
    coalesce(
      (
        select jsonb_agg(to_jsonb(ci) order by ci.id)
        from public.koba_cart_items ci
        where ci.cart_id = c.id
      ),
      '[]'::jsonb
    )
  )
  from public.koba_carts c
  where c.tenant_id = p_tenant_id
    and c.customer_group_id is not distinct from p_customer_group_id
  limit 1;
$$;


