CREATE OR REPLACE FUNCTION "public"."get_koba_customer_profile"("p_tenant_id" bigint, "p_phone" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_latest_order_id bigint;
  v_latest_name text;
  v_latest_district text;
  v_latest_thana text;
  v_latest_address text;
  
  v_total_orders bigint;
  v_total_spent numeric(12,2);
  v_first_order_date timestamptz;
  v_last_order_date timestamptz;
  v_avg_days_between_orders numeric(10,2);
  
  v_brand_demand jsonb;
  v_top_products jsonb;
  v_order_history jsonb;
begin
  -- Access Control Check: Only tenant admin, staff, or superadmin can view analytics
  if not (
    public.is_superadmin()
    or exists (
      select 1
      from public.memberships m
      where lower(trim(m.email)) = public.current_user_email()
        and m.tenant_id = p_tenant_id
        and m.role in ('admin', 'staff')
        and m.is_active = true
    )
  ) then
    raise exception 'access denied';
  end if;

  -- Get overview stats
  select
    max(id) as last_order_id,
    count(id) as total_orders,
    coalesce(sum(subtotal_gbp), 0) as total_spent,
    min(created_at) as first_order_date,
    max(created_at) as last_order_date
  into
    v_latest_order_id,
    v_total_orders,
    v_total_spent,
    v_first_order_date,
    v_last_order_date
  from public.koba_orders
  where tenant_id = p_tenant_id
    and shipping_phone = p_phone;
    
  if v_total_orders = 0 or v_total_orders is null then
    return null;
  end if;
  
  -- Calculate average frequency (days between orders)
  if v_total_orders > 1 then
    v_avg_days_between_orders := (extract(epoch from (v_last_order_date - v_first_order_date)) / 86400.0) / (v_total_orders - 1);
  else
    v_avg_days_between_orders := null;
  end if;
  
  -- Get contact details from latest order
  select
    shipping_name,
    shipping_district,
    shipping_thana,
    shipping_address
  into
    v_latest_name,
    v_latest_district,
    v_latest_thana,
    v_latest_address
  from public.koba_orders
  where id = v_latest_order_id;
  
  -- Aggregate brand demand (Top 5 ordered brands)
  select coalesce(jsonb_agg(x), '[]'::jsonb)
  into v_brand_demand
  from (
    select
      coalesce(nullif(trim(oi.brand), ''), 'Unknown') as brand,
      count(distinct o.id) as order_count,
      sum(oi.quantity) as item_count
    from public.koba_orders o
    join public.koba_order_items oi on oi.order_id = o.id
    where o.tenant_id = p_tenant_id
      and o.shipping_phone = p_phone
    group by coalesce(nullif(trim(oi.brand), ''), 'Unknown')
    order by order_count desc, item_count desc
    limit 5
  ) x;
  
  -- Aggregate top products (Top 5 ordered products)
  select coalesce(jsonb_agg(y), '[]'::jsonb)
  into v_top_products
  from (
    select
      oi.product_id,
      oi.name,
      coalesce(nullif(trim(oi.brand), ''), 'Unknown') as brand,
      sum(oi.quantity) as total_quantity
    from public.koba_orders o
    join public.koba_order_items oi on oi.order_id = o.id
    where o.tenant_id = p_tenant_id
      and o.shipping_phone = p_phone
    group by oi.product_id, oi.name, oi.brand
    order by total_quantity desc
    limit 5
  ) y;
  
  -- Aggregate order history timeline
  select coalesce(jsonb_agg(z), '[]'::jsonb)
  into v_order_history
  from (
    select
      o.id as order_id,
      o.subtotal_gbp,
      o.net_order_commission,
      o.status,
      o.created_at
    from public.koba_orders o
    where o.tenant_id = p_tenant_id
      and o.shipping_phone = p_phone
    order by o.created_at desc
    limit 15
  ) z;
  
  -- Return consolidated JSON response
  return jsonb_build_object(
    'phone', p_phone,
    'name', v_latest_name,
    'district', v_latest_district,
    'thana', v_latest_thana,
    'address', v_latest_address,
    'total_orders', v_total_orders,
    'total_spent', v_total_spent,
    'first_order_date', v_first_order_date,
    'last_order_date', v_last_order_date,
    'avg_days_between_orders', v_avg_days_between_orders,
    'brand_demand', v_brand_demand,
    'top_products', v_top_products,
    'order_history', v_order_history
  );
end;
$$;


ALTER FUNCTION "public"."get_koba_customer_profile"("p_tenant_id" bigint, "p_phone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_koba_customers_list"("p_tenant_id" bigint, "p_search" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS TABLE("phone" "text", "name" "text", "district" "text", "thana" "text", "address" "text", "total_orders" bigint, "total_spent" numeric, "last_order_date" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  -- Access Control Check: Only tenant admin, staff, or superadmin can view analytics
  if not (
    public.is_superadmin()
    or exists (
      select 1
      from public.memberships m
      where lower(trim(m.email)) = public.current_user_email()
        and m.tenant_id = p_tenant_id
        and m.role in ('admin', 'staff')
        and m.is_active = true
    )
  ) then
    raise exception 'access denied';
  end if;

  return query
  with customer_phones as (
    select
      o.shipping_phone as cp_phone,
      count(o.id) as cp_total_orders,
      coalesce(sum(o.subtotal_gbp), 0) as cp_total_spent,
      max(o.created_at) as cp_last_order_date,
      max(o.id) as cp_last_order_id
    from public.koba_orders o
    where o.tenant_id = p_tenant_id
      and o.shipping_phone is not null
      and o.shipping_phone <> ''
      and (
        p_search is null 
        or p_search = '' 
        or o.shipping_phone iLike '%' || trim(p_search) || '%' 
        or o.shipping_name iLike '%' || trim(p_search) || '%'
      )
    group by o.shipping_phone
  )
  select
    cp.cp_phone as phone,
    o.shipping_name as name,
    o.shipping_district as district,
    o.shipping_thana as thana,
    o.shipping_address as address,
    cp.cp_total_orders as total_orders,
    cp.cp_total_spent::numeric(12,2) as total_spent,
    cp.cp_last_order_date as last_order_date
  from customer_phones cp
  join public.koba_orders o on o.id = cp.cp_last_order_id
  order by cp.cp_last_order_date desc
  limit p_limit offset p_offset;
end;
$$;


ALTER FUNCTION "public"."get_koba_customers_list"("p_tenant_id" bigint, "p_search" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_dropship_wallet_summary"() RETURNS TABLE("billing_profile_id" bigint, "available_balance" numeric, "pending_balance" numeric, "locked_balance" numeric, "currency" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_email text := public.current_user_email();
  v_tenant_id bigint;
  v_group_id bigint;
  v_bp_id bigint;
  v_available numeric := 0;
  v_pending numeric := 0;
  v_locked numeric := 0;
begin
  if v_email is null or length(trim(v_email)) = 0 then
    raise exception 'Not authenticated';
  end if;

  select cg.tenant_id, cgm.customer_group_id
  into v_tenant_id, v_group_id
  from public.customer_group_members cgm
  join public.customer_groups cg on cg.id = cgm.customer_group_id
  where lower(trim(cgm.email)) = lower(trim(v_email))
    and cgm.is_active = true
    and cg.is_active = true
  order by cgm.id
  limit 1;

  if v_tenant_id is null or v_group_id is null then
    raise exception 'No active customer group membership';
  end if;

  v_bp_id := public.resolve_billing_profile_for_customer_group(v_tenant_id, v_group_id);
  if v_bp_id is null then
    raise exception 'No billing profile linked for your customer group';
  end if;

  select coalesce(w.available_balance, 0)
  into v_available
  from public.wallet_accounts w
  where w.parent_tenant_id = public.resolve_parent_tenant_id(v_tenant_id)
    and w.entity_type = 'customer'
    and w.entity_id = v_bp_id
    and w.currency_code = 'BDT';

  select coalesce(sum(s.reseller_profit), 0)
  into v_pending
  from public.shop_orders o
  join public.dropship_order_settlements s on s.shop_order_id = o.id
  where o.tenant_id = v_tenant_id
    and o.billing_profile_id = v_bp_id
    and o.shop_type_snapshot = 'dropship'
    and o.status = 'payment_received'::public.shop_order_status
    and coalesce(s.reseller_profit, 0) > 0
    and s.merchant_payout_at is null;

  select coalesce(sum(greatest(coalesce(o.cod_collect_amount, 0), 0)), 0)
  into v_locked
  from public.shop_orders o
  where o.tenant_id = v_tenant_id
    and o.billing_profile_id = v_bp_id
    and o.shop_type_snapshot = 'dropship'
    and o.status = 'delivered'
    and o.courier_remittance_ref is null
    and coalesce(o.collection_source, 'recipient') = 'recipient';

  return query select
    v_bp_id,
    v_available,
    v_pending,
    v_locked,
    'BDT'::text;
end;
$$;


ALTER FUNCTION "public"."get_my_dropship_wallet_summary"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_notification_preferences"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_row public.user_notification_preferences;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT p.*
  INTO v_row
  FROM public.user_notification_preferences p
  WHERE p.user_id = v_user_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'user_id', v_user_id,
      'channel_telegram', false,
      'channel_push', false,
      'channel_email', false,
      'event_preferences', '{}'::jsonb,
      'updated_at', NULL
    );
  END IF;

  RETURN jsonb_build_object(
    'user_id', v_row.user_id,
    'channel_telegram', v_row.channel_telegram,
    'channel_push', v_row.channel_push,
    'channel_email', v_row.channel_email,
    'event_preferences', v_row.event_preferences,
    'updated_at', v_row.updated_at
  );
END;
$$;


ALTER FUNCTION "public"."get_my_notification_preferences"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_notification_unread_count"("p_tenant_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_unread_count bigint;
begin
  if v_user_id is null then
    raise exception 'Authentication required';
  end if;

  if p_tenant_id is null then
    raise exception 'p_tenant_id is required';
  end if;

  if not (
    public.is_superadmin()
    or public.has_active_tenant_membership(p_tenant_id)
    or public.user_can_manage_parent_tenant(public.resolve_parent_tenant_id(p_tenant_id))
    or public.has_shop_notification_access(p_tenant_id)
  ) then
    raise exception 'Permission denied for tenant %', p_tenant_id;
  end if;

  select count(*)
  into v_unread_count
  from public.notification_recipients r
  join public.notifications n on n.id = r.notification_id
  where r.user_id = v_user_id
    and r.read_at is null
    and public.notification_inbox_scope_matches(p_tenant_id, n.parent_tenant_id, n.operating_tenant_id);

  return jsonb_build_object('unread_count', coalesce(v_unread_count, 0));
end;
$$;


ALTER FUNCTION "public"."get_my_notification_unread_count"("p_tenant_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_or_create_shop_cart"("p_shop_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_tenant_id bigint;
  v_customer_group_id bigint;
  v_can_see_buy_price_snapshot boolean;
  v_can_see_sell_price_snapshot boolean;
  v_cart_id bigint;
  v_result jsonb;
  v_perm record;
begin
  select tenant_id into v_tenant_id
  from public.shops
  where id = p_shop_id
    and is_active = true;

  if v_tenant_id is null then
    raise exception 'shop not found or inactive';
  end if;

  select access.customer_group_id into v_customer_group_id
  from public.shop_customer_group_access access
  join public.customer_groups cg on cg.id = access.customer_group_id
  join public.customer_group_members cgm on cgm.customer_group_id = cg.id
  where access.shop_id = p_shop_id
    and access.status = true
    and cg.is_active = true
    and cgm.is_active = true
    and lower(trim(cgm.email)) = public.current_user_email()
  order by access.created_at asc
  limit 1;

  if v_customer_group_id is null then
    raise exception 'no customer group access found';
  end if;

  if not public.can_customer_access_shop(p_shop_id) then
    raise exception 'access denied';
  end if;

  select *
  into v_perm
  from public.get_shop_permissions_for_customer(p_shop_id)
  limit 1;

  v_can_see_buy_price_snapshot := coalesce(v_perm.can_see_buy_price, false);
  v_can_see_sell_price_snapshot := coalesce(v_perm.can_see_sell_price, false);

  select id into v_cart_id
  from public.shop_carts
  where tenant_id = v_tenant_id
    and shop_id = p_shop_id
    and customer_group_id = v_customer_group_id
    and status = 'active'
  order by id desc
  limit 1;

  if v_cart_id is null then
    insert into public.shop_carts (
      tenant_id, shop_id, customer_group_id,
      can_see_buy_price_snapshot, can_see_sell_price_snapshot, status,
      deduct_charges_from_margin, deduct_print_from_margin, deduct_packing_from_margin
    )
    values (
      v_tenant_id, p_shop_id, v_customer_group_id,
      v_can_see_buy_price_snapshot, v_can_see_sell_price_snapshot, 'active',
      (select deduct_charges_from_margin from public.shops where id = p_shop_id),
      (select deduct_print_from_margin from public.shops where id = p_shop_id),
      (select deduct_packing_from_margin from public.shops where id = p_shop_id)
    )
    returning id into v_cart_id;
  else
    update public.shop_carts
    set
      deduct_charges_from_margin = (select deduct_charges_from_margin from public.shops where id = p_shop_id),
      deduct_print_from_margin = (select deduct_print_from_margin from public.shops where id = p_shop_id),
      deduct_packing_from_margin = (select deduct_packing_from_margin from public.shops where id = p_shop_id),
      can_see_buy_price_snapshot = v_can_see_buy_price_snapshot,
      can_see_sell_price_snapshot = v_can_see_sell_price_snapshot
    where id = v_cart_id;
  end if;

  select jsonb_build_object(
    'cart', jsonb_build_object(
      'id', c.id,
      'tenant_id', c.tenant_id,
      'shop_id', c.shop_id,
      'customer_group_id', c.customer_group_id,
      'can_see_buy_price_snapshot', v_can_see_buy_price_snapshot,
      'can_see_sell_price_snapshot', v_can_see_sell_price_snapshot,
      'status', c.status,
      'created_at', c.created_at,
      'updated_at', c.updated_at,
      'shop_type', s.shop_type,
      'allow_delivery', s.allow_delivery,
      'default_print_charge_amount', s.default_print_charge_amount,
      'default_packing_charge_amount', s.default_packing_charge_amount,
      'deduct_charges_from_margin', s.deduct_charges_from_margin,
      'deduct_print_from_margin', s.deduct_print_from_margin,
      'deduct_packing_from_margin', s.deduct_packing_from_margin
    ),
    'items', coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'id', ci.id,
            'cart_id', ci.cart_id,
            'product_id', ci.product_id,
            'listing_id', ci.listing_id,
            'grade_tag_id', ci.grade_tag_id,
            'global_stock_id', ci.global_stock_id,
            'global_stock_allocation_id', ci.global_stock_allocation_id,
            'quantity', ci.quantity,
            'minimum_quantity', ci.minimum_quantity,
            'minimum_order_quantity', p.minimum_order_quantity,
            'unit_list_price_amount', case when v_can_see_buy_price_snapshot then ci.unit_list_price_amount else null end,
            'unit_list_price_currency_id', case when v_can_see_buy_price_snapshot then ci.unit_list_price_currency_id else null end,
            'unit_sell_price_amount', case when v_can_see_sell_price_snapshot then ci.unit_sell_price_amount else null end,
            'unit_sell_price_currency_id', case when v_can_see_sell_price_snapshot then ci.unit_sell_price_currency_id else null end,
            'unit_minimum_sell_price_amount', case when v_can_see_sell_price_snapshot then ci.unit_minimum_sell_price_amount else null end,
            'unit_minimum_sell_price_currency_id', case when v_can_see_sell_price_snapshot then ci.unit_minimum_sell_price_currency_id else null end,
            'customer_sell_price_amount', case when v_can_see_sell_price_snapshot then ci.customer_sell_price_amount else null end,
            'customer_sell_price_currency_id', case when v_can_see_sell_price_snapshot then ci.customer_sell_price_currency_id else null end,
            'name', ci.name,
            'image_url', ci.image_url
          )
        )
        from public.shop_cart_items ci
        left join public.products p on p.id = ci.product_id
        where ci.cart_id = c.id
      ),
      '[]'::jsonb
    ),
    'permissions', jsonb_build_object(
      'can_browse', coalesce(v_perm.can_browse, false),
      'can_see_buy_price', coalesce(v_perm.can_see_buy_price, false),
      'can_see_sell_price', coalesce(v_perm.can_see_sell_price, false),
      'can_see_resell_minimum_price', coalesce(v_perm.can_see_resell_minimum_price, false),
      'can_add_to_cart', coalesce(v_perm.can_add_to_cart, false),
      'can_place_order', coalesce(v_perm.can_place_order, false),
      'can_negotiate', coalesce(v_perm.can_negotiate, false),
      'can_view_quantity', coalesce(v_perm.can_view_quantity, false),
      'can_set_dropship_price', coalesce(v_perm.can_set_dropship_price, false)
    ),
    'currency', case
      when gc.id is not null then jsonb_build_object(
        'id', gc.id,
        'code', gc.code,
        'symbol', gc.symbol
      )
      else null
    end
  )
  into v_result
  from public.shop_carts c
  join public.shops s on s.id = c.shop_id
  left join public.global_currencies gc on gc.id = s.sell_currency_id
  where c.id = v_cart_id;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."get_or_create_shop_cart"("p_shop_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_parent_cash_circulation"("p_parent_tenant_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_deposits numeric(12,2);
  v_withdrawals numeric(12,2);
  v_deployed numeric(12,2);
  v_ar_due numeric(12,2);
  v_ar_paid numeric(12,2);
  v_stock_cost numeric(12,2);
  v_profit_mtd numeric(12,2);
  v_payouts numeric(12,2);
begin
  if not public.user_can_manage_parent_tenant(p_parent_tenant_id) then
    raise exception 'not allowed';
  end if;

  select
    coalesce(sum(case when type in ('deposit', 'capital_in', 'capital_adjustment', 'manual_adjustment') then amount else 0 end), 0),
    coalesce(sum(case when type in ('withdrawal', 'withdrawal_paid') then amount else 0 end), 0)
  into v_deposits, v_withdrawals
  from public.investor_transactions it
  where it.tenant_id = p_parent_tenant_id;

  select coalesce(sum(coalesce(allocated_cost, invested_amount)), 0) into v_deployed
  from public.shipment_investments
  where tenant_id = p_parent_tenant_id and status = 'active';

  select
    coalesce(sum(due_amount), 0),
    coalesce(sum(paid_amount), 0)
  into v_ar_due, v_ar_paid
  from public.global_invoices
  where parent_tenant_id = p_parent_tenant_id;

  select coalesce(sum(
    public.calculate_landed_unit_cost(gs.shipment_item_id) * gs.quantity
  ), 0) into v_stock_cost
  from public.global_stocks gs
  inner join public.global_stock_types gst on gst.id = gs.stock_type_id
  where gs.parent_tenant_id = p_parent_tenant_id
    and gst.is_sellable = true
    and gs.quantity > 0;

  with invoice_line_margin as (
    select
      ii.invoice_id,
      sum((ii.sell_price_amount - ii.unit_cost_price) * ii.quantity - ii.line_discount_amount) as lines_margin
    from public.global_invoice_items ii
    join public.global_invoices i on i.id = ii.invoice_id
    where i.parent_tenant_id = p_parent_tenant_id
      and i.invoice_status = 'posted'::public.global_invoice_status
      and i.invoice_date >= date_trunc('month', current_date)::date
    group by ii.invoice_id
  ),
  invoice_return_margin as (
    select
      ri.invoice_id,
      sum(ri.return_accounting_amount - (ii.unit_cost_price * ri.quantity)) as returns_margin
    from public.global_return_items ri
    join public.global_invoice_items ii on ii.id = ri.invoice_item_id
    join public.global_invoices i on i.id = ri.invoice_id
    where i.parent_tenant_id = p_parent_tenant_id
      and i.invoice_status = 'posted'::public.global_invoice_status
      and i.invoice_date >= date_trunc('month', current_date)::date
    group by ri.invoice_id
  )
  select coalesce(sum(
    coalesce(lm.lines_margin, 0.00)
      - i.discount_amount
      + (case
           when i.invoice_type = 'wholesale' or i.invoice_type = 'dropship' then i.shipping_charge
           when i.invoice_type = 'retail' then i.shipping_charge + i.cod_charge + i.print_charge + i.wrapping_charge
           else 0.00
         end)
      - coalesce(rm.returns_margin, 0.00)
  ), 0) into v_profit_mtd
  from public.global_invoices i
  left join invoice_line_margin lm on lm.invoice_id = i.id
  left join invoice_return_margin rm on rm.invoice_id = i.id
  where i.parent_tenant_id = p_parent_tenant_id
    and i.invoice_status = 'posted'::public.global_invoice_status
    and i.invoice_date >= date_trunc('month', current_date)::date;

  select coalesce(sum(amount), 0) into v_payouts
  from public.investor_transactions
  where tenant_id = p_parent_tenant_id
    and type in ('profit_payout', 'profit_reinvest');

  return jsonb_build_object(
    'investor_capital_in', v_deposits,
    'investor_capital_withdrawn', v_withdrawals,
    'investor_capital_deployed', v_deployed,
    'investor_capital_available', v_deposits - v_withdrawals - v_deployed,
    'customer_ar_due', v_ar_due,
    'customer_ar_paid', v_ar_paid,
    'stock_cost_in_circulation', v_stock_cost,
    'realized_profit_mtd', v_profit_mtd,
    'profit_distributed', v_payouts
  );
end;
$$;


ALTER FUNCTION "public"."get_parent_cash_circulation"("p_parent_tenant_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_payee_settlement_summary"("p_tenant_id" bigint, "p_shipment_id" bigint, "p_entity_type" "text", "p_entity_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_avail NUMERIC(18,4) := 0;
  v_paid NUMERIC(18,4) := 0;
  v_credited NUMERIC(18,4) := 0;
  v_used NUMERIC(18,4) := 0;
  v_events JSONB := '[]'::jsonb;
BEGIN
  IF p_entity_id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT COALESCE(available_balance, 0) INTO v_avail
  FROM public.wallet_accounts
  WHERE tenant_id = p_tenant_id
    AND entity_type = p_entity_type
    AND entity_id = p_entity_id
    AND currency_code = 'BDT';

  SELECT COALESCE(SUM(base_amount), 0) INTO v_paid
  FROM public.universal_wallet_ledger
  WHERE tenant_id = p_tenant_id
    AND source_type = 'shipment'
    AND source_id = p_shipment_id::text
    AND metadata->>'action' = 'pay'
    AND metadata->>'payee_type' = p_entity_type
    AND (metadata->>'payee_id')::bigint = p_entity_id;

  SELECT COALESCE(SUM(base_amount), 0) INTO v_credited
  FROM public.universal_wallet_ledger
  WHERE tenant_id = p_tenant_id
    AND source_type = 'shipment'
    AND source_id = p_shipment_id::text
    AND metadata->>'action' = 'record_credit'
    AND entity_type = p_entity_type
    AND entity_id = p_entity_id;

  SELECT COALESCE(SUM(base_amount), 0) INTO v_used
  FROM public.universal_wallet_ledger
  WHERE tenant_id = p_tenant_id
    AND source_type = 'shipment'
    AND source_id = p_shipment_id::text
    AND metadata->>'action' = 'use_credit'
    AND entity_type = p_entity_type
    AND entity_id = p_entity_id;

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', id,
      'created_at', created_at,
      'type', type,
      'action', metadata->>'action',
      'amount_input', COALESCE((metadata->>'amount_input')::numeric, amount),
      'exchange_rate', COALESCE((metadata->>'exchange_rate')::numeric, exchange_rate),
      'base_amount', base_amount
    ) ORDER BY created_at DESC
  ), '[]'::jsonb) INTO v_events
  FROM public.universal_wallet_ledger
  WHERE tenant_id = p_tenant_id
    AND source_type = 'shipment'
    AND source_id = p_shipment_id::text
    AND (
      (entity_type = p_entity_type AND entity_id = p_entity_id)
      OR
      (metadata->>'payee_type' = p_entity_type AND (metadata->>'payee_id')::bigint = p_entity_id)
    );

  RETURN jsonb_build_object(
    'entity_type', p_entity_type,
    'entity_id', p_entity_id,
    'available_bdt', v_avail,
    'paid_bdt', v_paid,
    'credited_bdt', v_credited,
    'used_bdt', v_used,
    'recent_events', v_events
  );
END;
$$;


ALTER FUNCTION "public"."get_payee_settlement_summary"("p_tenant_id" bigint, "p_shipment_id" bigint, "p_entity_type" "text", "p_entity_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_pending_order_qty"("p_allocation_id" bigint) RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select coalesce(sum(oi.quantity)::integer, 0)
  from public.shop_order_items oi
  join public.shop_orders o on o.id = oi.order_id
  where oi.global_stock_allocation_id = p_allocation_id
    and o.status not in ('cancelled', 'fulfilled');
$$;


ALTER FUNCTION "public"."get_pending_order_qty"("p_allocation_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_procurement_dashboard_metrics"("p_tenant_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_books_id bigint;
  v_sellable bigint := 0;
  v_held bigint := 0;
  v_unsellable bigint := 0;
  v_total bigint := 0;
  v_value numeric := 0;
  v_in_transit bigint := 0;
  v_draft bigint := 0;
  v_received bigint := 0;
  v_grades jsonb := '[]'::jsonb;
  v_pipeline jsonb := '[]'::jsonb;
  v_locations jsonb := '[]'::jsonb;
BEGIN
  IF NOT public.membership_has_module_action(p_tenant_id, 'global_stock', 'view') THEN
    RAISE EXCEPTION 'not allowed';
  END IF;

  v_books_id := public.resolve_parent_tenant_id(p_tenant_id);

  SELECT
    coalesce(sum(gs.quantity) FILTER (WHERE gs.availability = 'sellable'::public.stock_availability), 0),
    coalesce(sum(gs.quantity) FILTER (WHERE gs.availability = 'held'::public.stock_availability), 0),
    coalesce(sum(gs.quantity) FILTER (WHERE gs.availability = 'unsellable'::public.stock_availability), 0),
    coalesce(sum(gs.quantity), 0),
    coalesce(
      sum(gs.quantity * coalesce(gsi.landed_cost_bdt, 0))
        FILTER (WHERE gs.availability = 'sellable'::public.stock_availability),
      0
    )
  INTO v_sellable, v_held, v_unsellable, v_total, v_value
  FROM public.global_stocks gs
  JOIN public.global_shipment_items gsi ON gsi.id = gs.shipment_item_id
  WHERE gs.parent_tenant_id = v_books_id;

  SELECT
    coalesce(count(*) FILTER (WHERE s.status = 'in_transit'), 0),
    coalesce(count(*) FILTER (WHERE s.status = 'draft'), 0),
    coalesce(count(*) FILTER (WHERE s.status = 'received'), 0)
  INTO v_in_transit, v_draft, v_received
  FROM public.global_shipments s
  WHERE s.parent_tenant_id = v_books_id
    AND s.is_archived = false;

  SELECT coalesce(jsonb_agg(row_to_json(g) ORDER BY g.qty DESC), '[]'::jsonb)
  INTO v_grades
  FROM (
    SELECT coalesce(t.name, 'Ungraded') AS name, sum(gs.quantity)::bigint AS qty
    FROM public.global_stocks gs
    LEFT JOIN public.tags t ON t.id = gs.grade_tag_id
    WHERE gs.parent_tenant_id = v_books_id
      AND gs.quantity > 0
    GROUP BY coalesce(t.name, 'Ungraded')
  ) g;

  SELECT coalesce(jsonb_agg(row_to_json(p) ORDER BY p.sort_key), '[]'::jsonb)
  INTO v_pipeline
  FROM (
    SELECT
      s.status,
      count(*)::bigint AS count,
      CASE s.status
        WHEN 'draft' THEN 1
        WHEN 'in_transit' THEN 2
        WHEN 'received' THEN 3
        ELSE 4
      END AS sort_key
    FROM public.global_shipments s
    WHERE s.parent_tenant_id = v_books_id
      AND s.is_archived = false
      AND s.status <> 'cancelled'
    GROUP BY s.status
  ) p;

  SELECT coalesce(jsonb_agg(row_to_json(l) ORDER BY l.qty DESC), '[]'::jsonb)
  INTO v_locations
  FROM (
    SELECT
      coalesce(sl.name, 'Unlocated') AS name,
      sum(gs.quantity)::bigint AS qty
    FROM public.global_stocks gs
    LEFT JOIN public.stock_locations sl ON sl.id = gs.location_id
    WHERE gs.parent_tenant_id = v_books_id
      AND gs.quantity > 0
    GROUP BY coalesce(sl.name, 'Unlocated')
  ) l;

  RETURN jsonb_build_object(
    'tenant_id', v_books_id,
    'sellable_qty', v_sellable,
    'held_qty', v_held,
    'unsellable_qty', v_unsellable,
    'total_qty', v_total,
    'sellable_pct', CASE WHEN v_total > 0 THEN round((v_sellable::numeric / v_total) * 100, 1) ELSE 0 END,
    'sellable_value_bdt', round(v_value, 2),
    'in_transit_count', v_in_transit,
    'draft_count', v_draft,
    'received_count', v_received,
    'grades', v_grades,
    'pipeline', v_pipeline,
    'locations', v_locations
  );
END;
$$;


ALTER FUNCTION "public"."get_procurement_dashboard_metrics"("p_tenant_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_procurement_demand_open_qty"("p_source_type" "public"."preorder_demand_source_type", "p_source_id" bigint) RETURNS TABLE("tenant_id" bigint, "open_qty" integer, "document_status" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if p_source_type = 'shop_order_item' then
    return query
    select
      o.tenant_id,
      greatest(coalesce(oi.confirmed_quantity, oi.quantity, 0), 0)::integer,
      public.normalize_shop_order_procurement_status(o.status)
    from public.shop_order_items oi
    inner join public.shop_orders o on o.id = oi.order_id
    where oi.id = p_source_id
      and o.shop_type_snapshot = 'vendor_catalog';
  elsif p_source_type = 'pbc_costing_item' then
    return query
    select
      f.tenant_id,
      greatest(
        case when pci.assigned_shipment_id is not null then 0
          else coalesce(pci.confirmed_quantity, pci.quantity::integer, 0)
        end,
        0
      )::integer,
      public.normalize_pbc_procurement_status(f.status)
    from public.product_based_costing_items pci
    inner join public.product_based_costing_files f on f.id = pci.product_based_costing_file_id
    where pci.id = p_source_id
      and f.billing_profile_id is not null;
  end if;
end;
$$;


ALTER FUNCTION "public"."get_procurement_demand_open_qty"("p_source_type" "public"."preorder_demand_source_type", "p_source_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_product_based_costing_file_summary"("p_file_id" bigint, "p_conversion_rate" numeric DEFAULT NULL::numeric, "p_cargo_rate_kg_gbp" numeric DEFAULT NULL::numeric, "p_profit_rate" numeric DEFAULT NULL::numeric) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with file_ctx as (
    select
      f.id,
      coalesce(p_conversion_rate, f.conversion_rate, 140)::numeric as conversion_rate,
      coalesce(p_cargo_rate_kg_gbp, f.cargo_rate_kg_gbp, 0)::numeric as cargo_rate,
      coalesce(p_profit_rate, f.profit_rate, 25)::numeric as profit_rate
    from public.product_based_costing_files f
    where f.id = p_file_id
      and public.can_view_costing_item(p_file_id)
  ),
  lines as (
    select
      i.id,
      greatest(coalesce(i.quantity, 0), 0)::numeric as qty,
      coalesce(i.price_gbp, 0)::numeric as price_gbp_n,
      coalesce(i.product_weight, 0)::numeric as product_weight_n,
      coalesce(i.package_weight, 0)::numeric as package_weight_n,
      coalesce(i.product_weight, 0) + coalesce(i.package_weight, 0) as weight_g,
      coalesce(i.is_offer_price_manual, false) as is_offer_price_manual,
      i.offer_price,
      fc.conversion_rate,
      fc.cargo_rate,
      fc.profit_rate
    from public.product_based_costing_items i
    inner join file_ctx fc on true
    where i.product_based_costing_file_id = p_file_id
  ),
  line_metrics as (
    select
      l.*,
      round((l.price_gbp_n + (l.weight_g / 1000.0) * l.cargo_rate)::numeric, 2) as unit_cost_gbp,
      ceil(
        round((l.price_gbp_n + (l.weight_g / 1000.0) * l.cargo_rate)::numeric, 2) * l.conversion_rate - 1e-9
      )::numeric as unit_cost_bdt,
      public.round_bdt_up_to_zero_or_five(
        ceil(
          round((l.price_gbp_n + (l.weight_g / 1000.0) * l.cargo_rate)::numeric, 2) * l.conversion_rate - 1e-9
        )
        + (
          ceil(
            round((l.price_gbp_n + (l.weight_g / 1000.0) * l.cargo_rate)::numeric, 2) * l.conversion_rate - 1e-9
          ) * l.profit_rate / 100.0
        )
      )::numeric as calculated_offer_bdt
    from lines l
  ),
  line_final as (
    select
      lm.*,
      case
        when lm.is_offer_price_manual and coalesce(lm.offer_price, 0) > 0 then
          public.round_bdt_up_to_zero_or_five(lm.offer_price)::numeric
        when coalesce(lm.offer_price, 0) > 0
          and public.round_bdt_up_to_zero_or_five(lm.offer_price) is distinct from lm.calculated_offer_bdt then
          public.round_bdt_up_to_zero_or_five(lm.offer_price)::numeric
        else lm.calculated_offer_bdt
      end as effective_offer_bdt,
      (
        lm.qty > 0
        and (
          lm.price_gbp_n <= 0
          or (lm.product_weight_n <= 0 and lm.package_weight_n <= 0)
        )
      ) as is_incomplete
    from line_metrics lm
  ),
  agg as (
    select
      (select count(*)::int from lines) as line_count,
      coalesce(sum(lf.qty) filter (where lf.qty > 0), 0)::numeric as total_quantity,
      coalesce(sum(lf.price_gbp_n * lf.qty) filter (where lf.qty > 0), 0)::numeric as goods_cost_gbp,
      coalesce(sum((lf.weight_g / 1000.0) * lf.cargo_rate * lf.qty) filter (where lf.qty > 0), 0)::numeric as cargo_cost_gbp,
      coalesce(sum(lf.weight_g * lf.qty) filter (where lf.qty > 0), 0)::numeric as cargo_weight_grams,
      coalesce(sum(lf.unit_cost_bdt * lf.qty) filter (where lf.qty > 0), 0)::numeric as total_cost_bdt,
      coalesce(sum(lf.effective_offer_bdt * lf.qty) filter (where lf.qty > 0), 0)::numeric as total_offer_price_bdt,
      count(*) filter (where lf.is_incomplete)::int as incomplete_line_count,
      (select conversion_rate from file_ctx limit 1) as conversion_rate
    from line_final lf
  )
  select coalesce(
    jsonb_build_object(
      'line_count', a.line_count,
      'total_quantity', a.total_quantity,
      'goods_cost_gbp', a.goods_cost_gbp,
      'goods_cost_bdt', a.goods_cost_gbp * a.conversion_rate,
      'cargo_weight_kg', a.cargo_weight_grams / 1000.0,
      'cargo_cost_gbp', a.cargo_cost_gbp,
      'cargo_cost_bdt', a.cargo_cost_gbp * a.conversion_rate,
      'total_cost_gbp', a.goods_cost_gbp + a.cargo_cost_gbp,
      'total_cost_bdt', a.total_cost_bdt,
      'total_offer_price_bdt', a.total_offer_price_bdt,
      'total_profit_bdt', a.total_offer_price_bdt - a.total_cost_bdt,
      'profit_margin_percent',
        case
          when a.total_offer_price_bdt > 0 then
            ((a.total_offer_price_bdt - a.total_cost_bdt) / a.total_offer_price_bdt) * 100.0
          else 0
        end,
      'avg_offer_per_unit_bdt',
        case
          when a.total_quantity > 0 then a.total_offer_price_bdt / a.total_quantity
          else 0
        end,
      'avg_cost_per_unit_bdt',
        case
          when a.total_quantity > 0 then a.total_cost_bdt / a.total_quantity
          else 0
        end,
      'incomplete_line_count', a.incomplete_line_count
    ),
    jsonb_build_object(
      'line_count', 0,
      'total_quantity', 0,
      'goods_cost_gbp', 0,
      'goods_cost_bdt', 0,
      'cargo_weight_kg', 0,
      'cargo_cost_gbp', 0,
      'cargo_cost_bdt', 0,
      'total_cost_gbp', 0,
      'total_cost_bdt', 0,
      'total_offer_price_bdt', 0,
      'total_profit_bdt', 0,
      'profit_margin_percent', 0,
      'avg_offer_per_unit_bdt', 0,
      'avg_cost_per_unit_bdt', 0,
      'incomplete_line_count', 0
    )
  )
  from agg a;
$$;


ALTER FUNCTION "public"."get_product_based_costing_file_summary"("p_file_id" bigint, "p_conversion_rate" numeric, "p_cargo_rate_kg_gbp" numeric, "p_profit_rate" numeric) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."products" (
    "id" bigint NOT NULL,
    "product_code" "text",
    "barcode" "text",
    "name" "text",
    "country_of_origin" "text",
    "brand" "text",
    "category" "text",
    "available_units" integer,
    "languages" "text",
    "batch_code_manufacture_date" "text",
    "image_url" "text",
    "expire_date" "text",
    "minimum_order_quantity" integer,
    "product_weight" numeric(12,3),
    "package_weight" numeric(12,3),
    "is_available" boolean,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "vendor_code" "text",
    "market_code" "text",
    "vendor_id" bigint,
    "source" "text",
    "hazardous" boolean,
    "parent_tenant_id" bigint,
    "list_price_amount" numeric(12,4),
    "list_price_currency_id" bigint,
    "reference_cost_amount" numeric(12,4),
    "reference_cost_currency_id" bigint,
    "inserted_by_tenant_id" bigint,
    CONSTRAINT "products_list_price_currency_check" CHECK ((("list_price_amount" IS NULL) = ("list_price_currency_id" IS NULL))),
    CONSTRAINT "products_reference_cost_currency_check" CHECK ((("reference_cost_amount" IS NULL) = ("reference_cost_currency_id" IS NULL))),
    CONSTRAINT "products_source_check" CHECK (("source" = ANY (ARRAY['website'::"text", 'excel'::"text"])))
);


ALTER TABLE "public"."products" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_product_for_tenant"("p_id" bigint, "p_tenant_id" bigint) RETURNS "public"."products"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_row public.products;
  v_scope_tenant_id bigint;
begin
  if p_tenant_id is null then
    raise exception 'tenant_id is required';
  end if;

  if not public.user_can_access_tenant_fetch(p_tenant_id) then
    raise exception 'not allowed';
  end if;

  v_scope_tenant_id := public.resolve_parent_tenant_id(p_tenant_id);

  select * into v_row
  from public.products
  where id = p_id
    and parent_tenant_id = v_scope_tenant_id;

  return v_row;
end;
$$;


ALTER FUNCTION "public"."get_product_for_tenant"("p_id" bigint, "p_tenant_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_recipient_profile_by_phone"("p_tenant_id" bigint, "p_phone" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_phone text;
  v_row public.recipient_profiles%rowtype;
  v_can_access boolean;
  v_parent_id bigint;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  v_can_access := public.is_tenant_staff(p_tenant_id)
    or public.current_customer_group_id(p_tenant_id) is not null
    or public.user_can_manage_parent_tenant(p_tenant_id)
    or public.has_active_tenant_membership(p_tenant_id);

  if not v_can_access then
    raise exception 'access denied';
  end if;

  begin
    v_phone := public.normalize_bd_mobile(p_phone);
  exception when others then
    return null;
  end;

  v_parent_id := public.resolve_parent_tenant_id(p_tenant_id);

  select * into v_row
  from public.recipient_profiles
  where (parent_tenant_id = v_parent_id or (parent_tenant_id is null and tenant_id = v_parent_id) or tenant_id = p_tenant_id)
    and phone = v_phone
  order by (parent_tenant_id = v_parent_id) desc, updated_at desc
  limit 1;

  if v_row.id is null then
    return null;
  end if;

  return jsonb_build_object(
    'id', v_row.id,
    'name', v_row.name,
    'phone', v_row.phone,
    'secondary_phone', v_row.secondary_phone,
    'address', v_row.address,
    'district', v_row.district,
    'thana', v_row.thana,
    'addresses', v_row.addresses,
    'tenant_id', v_row.tenant_id,
    'parent_tenant_id', v_row.parent_tenant_id,
    'created_at', v_row.created_at,
    'updated_at', v_row.updated_at
  );
end;
$$;


ALTER FUNCTION "public"."get_recipient_profile_by_phone"("p_tenant_id" bigint, "p_phone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_sales_invoice_dashboard_metrics"("p_tenant_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_today date;
  v_today_billed numeric := 0;
  v_unpaid_count bigint := 0;
  v_overdue_count bigint := 0;
  v_draft_count bigint := 0;
  v_paid numeric := 0;
  v_due numeric := 0;
  v_overdue numeric := 0;
  v_customers jsonb := '[]'::jsonb;
BEGIN
  IF NOT public.membership_has_module_action(p_tenant_id, 'global_invoice', 'view') THEN
    RAISE EXCEPTION 'not allowed';
  END IF;

  v_today := (timezone('Asia/Dhaka', now()))::date;

  SELECT
    coalesce(sum(si.total_amount) FILTER (
      WHERE si.invoice_status = 'issued'::public.global_invoice_status
        AND si.invoice_date = v_today
    ), 0),
    count(*) FILTER (
      WHERE si.invoice_status = 'issued'::public.global_invoice_status
        AND si.due_amount > 0
    ),
    count(*) FILTER (
      WHERE si.invoice_status = 'issued'::public.global_invoice_status
        AND si.due_amount > 0
        AND si.due_date IS NOT NULL
        AND si.due_date < v_today
    ),
    count(*) FILTER (WHERE si.invoice_status = 'draft'::public.global_invoice_status),
    coalesce(sum(si.paid_amount) FILTER (
      WHERE si.invoice_status = 'issued'::public.global_invoice_status
    ), 0),
    coalesce(sum(si.due_amount) FILTER (
      WHERE si.invoice_status = 'issued'::public.global_invoice_status
        AND (si.due_date IS NULL OR si.due_date >= v_today)
        AND si.due_amount > 0
    ), 0),
    coalesce(sum(si.due_amount) FILTER (
      WHERE si.invoice_status = 'issued'::public.global_invoice_status
        AND si.due_amount > 0
        AND si.due_date IS NOT NULL
        AND si.due_date < v_today
    ), 0)
  INTO v_today_billed, v_unpaid_count, v_overdue_count, v_draft_count, v_paid, v_due, v_overdue
  FROM public.sales_invoices si
  WHERE si.issued_by_tenant_id = p_tenant_id;

  SELECT coalesce(jsonb_agg(row_to_json(r)), '[]'::jsonb)
  INTO v_customers
  FROM (
    SELECT
      coalesce(nullif(trim(bp.name), ''), nullif(trim(si.recipient_name), ''), 'Unknown') AS name,
      round(sum(si.due_amount), 2) AS due_amount,
      count(*)::bigint AS invoice_count
    FROM public.sales_invoices si
    LEFT JOIN public.billing_profiles bp ON bp.id = si.billing_profile_id
    WHERE si.issued_by_tenant_id = p_tenant_id
      AND si.invoice_status = 'issued'::public.global_invoice_status
      AND si.due_amount > 0
      AND si.due_date IS NOT NULL
      AND si.due_date < v_today
    GROUP BY 1
    ORDER BY sum(si.due_amount) DESC
    LIMIT 5
  ) r;

  RETURN jsonb_build_object(
    'tenant_id', p_tenant_id,
    'today_billed_amount', round(v_today_billed, 2),
    'unpaid_count', v_unpaid_count,
    'overdue_count', v_overdue_count,
    'draft_count', v_draft_count,
    'paid_amount', round(v_paid, 2),
    'due_amount', round(v_due, 2),
    'overdue_amount', round(v_overdue, 2),
    'overdue_customers', v_customers
  );
END;
$$;


ALTER FUNCTION "public"."get_sales_invoice_dashboard_metrics"("p_tenant_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_shipment_overview_details"("p_shipment_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_parent bigint;
  v_ship jsonb;
  v_sections jsonb;
  v_items jsonb;
  v_boxes jsonb;
  v_cost_entries jsonb;
  v_flow_stages jsonb;
  v_progress_flow_id bigint;
begin
  select parent_tenant_id, progress_flow_id, to_jsonb(s.*)
  into v_parent, v_progress_flow_id, v_ship
  from public.global_shipments s
  where s.id = p_shipment_id;

  if v_ship is null then
    raise exception 'shipment not found';
  end if;

  if not (
    public.user_can_manage_parent_tenant(v_parent)
    or exists (
      select 1 from public.memberships m
      where m.tenant_id = v_parent
        and lower(trim(m.email)) = public.current_user_email()
        and m.is_active = true
    )
  ) then
    raise exception 'not allowed';
  end if;

  perform public.ensure_global_shipment_cost_entries_from_header(p_shipment_id);

  select coalesce(
    jsonb_agg(
      to_jsonb(sec.*) || jsonb_build_object('vendor', to_jsonb(v.*))
      order by sec.sort_order asc, sec.id asc
    ),
    '[]'::jsonb
  )
  into v_sections
  from public.global_shipment_sections sec
  left join public.vendors v on v.id = sec.vendor_id
  where sec.shipment_id = p_shipment_id;

  select coalesce(
    jsonb_agg(
      to_jsonb(i.*)
      order by coalesce(i.sort_order, 0) asc, i.id asc
    ),
    '[]'::jsonb
  )
  into v_items
  from public.global_shipment_items i
  where i.shipment_id = p_shipment_id;

  select coalesce(
    jsonb_agg(
      to_jsonb(b.*)
      order by b.box_number asc, b.id asc
    ),
    '[]'::jsonb
  )
  into v_boxes
  from public.global_shipment_boxes b
  where b.shipment_id = p_shipment_id;

  select coalesce(
    jsonb_agg(
      to_jsonb(ce.*)
      order by ce.cost_type asc, ce.id asc
    ),
    '[]'::jsonb
  )
  into v_cost_entries
  from public.global_shipment_cost_entries ce
  where ce.shipment_id = p_shipment_id;

  if v_progress_flow_id is not null then
    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'flow_stage_id', st.id,
          'flow_id', st.flow_id,
          'tag_id', st.tag_id,
          'sort_order', st.sort_order,
          'name', coalesce(t.name, ''),
          'slug', coalesce(t.slug, ''),
          'color', t.color,
          'is_active', coalesce(t.is_active, true)
        )
        order by st.sort_order asc
      ),
      '[]'::jsonb
    )
    into v_flow_stages
    from public.shipment_progress_flow_stages st
    join public.tags t on t.id = st.tag_id
    where st.flow_id = v_progress_flow_id and t.is_active = true;
  else
    v_flow_stages := '[]'::jsonb;
  end if;

  return jsonb_build_object(
    'shipment', v_ship,
    'sections', v_sections,
    'items', v_items,
    'boxes', v_boxes,
    'cost_entries', v_cost_entries,
    'flow_stages', v_flow_stages
  );
end;
$$;


ALTER FUNCTION "public"."get_shipment_overview_details"("p_shipment_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_shipment_pnl"("p_tenant_id" bigint, "p_shipment_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_shipment jsonb;
  v_items jsonb;
  v_total_landed_cost numeric(12,2) := 0;
  v_total_sold_cost numeric(12,2) := 0;
  v_total_revenue numeric(12,2) := 0;
  v_total_gross_profit numeric(12,2) := 0;
  v_total_sellable_on_hand_value numeric(12,2) := 0;
  v_total_shrinkage_value numeric(12,2) := 0;
  v_total_stolen_value numeric(12,2) := 0;
  v_total_box_damage_value numeric(12,2) := 0;
  v_total_expired_value numeric(12,2) := 0;
  v_total_reconciliation_gap bigint := 0;
  v_disposition_available boolean := false;
begin
  -- Resolve parent tenant to enforce access
  if public.resolve_parent_tenant_id(p_tenant_id) <> (select parent_tenant_id from public.global_shipments where id = p_shipment_id) then
    raise exception 'unauthorized tenant access to shipment';
  end if;

  -- 1. Get shipment header
  select row_to_json(s)::jsonb
  into v_shipment
  from public.global_shipments s
  where s.id = p_shipment_id;

  -- Check if disposition is available (i.e. global_stocks rows exist for shipment items)
  select exists (
    select 1
    from public.global_stocks gs
    inner join public.global_shipment_items gsi on gs.shipment_item_id = gsi.id
    where gsi.shipment_id = p_shipment_id
  ) into v_disposition_available;

  -- 2. Get shipment items details with on-the-fly margins and stock disposition
  select coalesce(jsonb_agg(row_to_json(r)), '[]'::jsonb)
  into v_items
  from (
    select
      si.*,
      public.calculate_landed_unit_cost(si.id) as landed_unit_cost,
      coalesce(sum(ii.quantity - ii.return_quantity), 0) as sold_qty,
      coalesce(sum(ii.unit_cost_price * (ii.quantity - ii.return_quantity)), 0) as sold_cost,
      coalesce(sum(ii.sell_price_amount * ii.quantity - coalesce((
        select sum(ri.return_accounting_amount)
        from public.global_return_items ri
        where ri.invoice_item_id = ii.id
      ), 0.00) - case
        when inv.invoice_type = 'dropship'::public.global_invoice_type then 0.00
        else (coalesce(inv.discount_amount, 0.00) + coalesce(inv.settlement_discount_amount, 0.00))
          * (ii.line_total_amount / nullif(invagg.inv_line_subtotal, 0.00))
      end), 0) as revenue,
      coalesce(disp.sellable_qty, 0) as sellable_qty,
      coalesce(disp.stolen_qty, 0) as stolen_qty,
      coalesce(disp.box_damage_qty, 0) as box_damage_qty,
      coalesce(disp.expired_qty, 0) as expired_qty,
      coalesce(disp.reserved_qty, 0) as reserved_qty,
      (coalesce(disp.sellable_qty, 0) * public.calculate_landed_unit_cost(si.id))::numeric(12,2) as sellable_value,
      ((coalesce(disp.stolen_qty, 0) + coalesce(disp.box_damage_qty, 0) + coalesce(disp.expired_qty, 0)) * public.calculate_landed_unit_cost(si.id))::numeric(12,2) as shrinkage_value,
      (coalesce(disp.stolen_qty, 0) * public.calculate_landed_unit_cost(si.id))::numeric(12,2) as stolen_value,
      (coalesce(disp.box_damage_qty, 0) * public.calculate_landed_unit_cost(si.id))::numeric(12,2) as box_damage_value,
      (coalesce(disp.expired_qty, 0) * public.calculate_landed_unit_cost(si.id))::numeric(12,2) as expired_value,
      (si.ordered_quantity - coalesce(sum(ii.quantity - ii.return_quantity), 0) - coalesce(disp.sellable_qty, 0) - coalesce(disp.stolen_qty, 0) - coalesce(disp.box_damage_qty, 0) - coalesce(disp.expired_qty, 0) - coalesce(disp.reserved_qty, 0)) as reconciliation_gap
    from public.global_shipment_items si
    left join public.global_invoice_items ii on ii.shipment_item_id = si.id
    left join public.global_invoices inv on inv.id = ii.invoice_id and inv.invoice_status = 'posted'::public.global_invoice_status
    left join lateral (
      select coalesce(sum(x.line_total_amount), 0.00) as inv_line_subtotal
      from public.global_invoice_items x
      where x.invoice_id = ii.invoice_id
    ) invagg on true
    left join lateral (
      select
        coalesce(sum(gs.quantity) filter (where gst.is_sellable = true), 0) as sellable_qty,
        coalesce(sum(gs.quantity) filter (where lower(trim(gst.description)) = 'stolen'), 0) as stolen_qty,
        coalesce(sum(gs.quantity) filter (where lower(trim(gst.description)) = 'box damage'), 0) as box_damage_qty,
        coalesce(sum(gs.quantity) filter (where lower(trim(gst.description)) = 'expired'), 0) as expired_qty,
        coalesce(sum(gs.quantity) filter (where lower(trim(gst.description)) = 'reserved'), 0) as reserved_qty
      from public.global_stocks gs
      inner join public.global_stock_types gst on gst.id = gs.stock_type_id
      where gs.shipment_item_id = si.id
    ) disp on true
    where si.shipment_id = p_shipment_id
    group by si.id, disp.sellable_qty, disp.stolen_qty, disp.box_damage_qty, disp.expired_qty, disp.reserved_qty
  ) r;

  -- 3. Sum total metrics
  select
    coalesce(sum(landed_unit_cost * received_qty), 0),
    coalesce(sum(sold_cost), 0),
    coalesce(sum(revenue), 0),
    coalesce(sum(sellable_qty * landed_unit_cost), 0),
    coalesce(sum((stolen_qty + box_damage_qty + expired_qty) * landed_unit_cost), 0),
    coalesce(sum(stolen_qty * landed_unit_cost), 0),
    coalesce(sum(box_damage_qty * landed_unit_cost), 0),
    coalesce(sum(expired_qty * landed_unit_cost), 0),
    coalesce(sum(reconciliation_gap), 0)
  into
    v_total_landed_cost,
    v_total_sold_cost,
    v_total_revenue,
    v_total_sellable_on_hand_value,
    v_total_shrinkage_value,
    v_total_stolen_value,
    v_total_box_damage_value,
    v_total_expired_value,
    v_total_reconciliation_gap
  from (
    select
      public.calculate_landed_unit_cost(si.id) as landed_unit_cost,
      si.ordered_quantity as received_qty,
      coalesce(sum(ii.quantity - ii.return_quantity), 0) as sold_qty,
      coalesce(sum(ii.unit_cost_price * (ii.quantity - ii.return_quantity)), 0) as sold_cost,
      coalesce(sum(ii.sell_price_amount * ii.quantity - coalesce((
        select sum(ri.return_accounting_amount)
        from public.global_return_items ri
        where ri.invoice_item_id = ii.id
      ), 0.00) - case
        when inv.invoice_type = 'dropship'::public.global_invoice_type then 0.00
        else (coalesce(inv.discount_amount, 0.00) + coalesce(inv.settlement_discount_amount, 0.00))
          * (ii.line_total_amount / nullif(invagg.inv_line_subtotal, 0.00))
      end), 0) as revenue,
      coalesce(disp.sellable_qty, 0) as sellable_qty,
      coalesce(disp.stolen_qty, 0) as stolen_qty,
      coalesce(disp.box_damage_qty, 0) as box_damage_qty,
      coalesce(disp.expired_qty, 0) as expired_qty,
      (si.ordered_quantity - coalesce(sum(ii.quantity - ii.return_quantity), 0) - coalesce(disp.sellable_qty, 0) - coalesce(disp.stolen_qty, 0) - coalesce(disp.box_damage_qty, 0) - coalesce(disp.expired_qty, 0) - coalesce(disp.reserved_qty, 0)) as reconciliation_gap
    from public.global_shipment_items si
    left join public.global_invoice_items ii on ii.shipment_item_id = si.id
    left join public.global_invoices inv on inv.id = ii.invoice_id and inv.invoice_status = 'posted'::public.global_invoice_status
    left join lateral (
      select coalesce(sum(x.line_total_amount), 0.00) as inv_line_subtotal
      from public.global_invoice_items x
      where x.invoice_id = ii.invoice_id
    ) invagg on true
    left join lateral (
      select
        coalesce(sum(gs.quantity) filter (where gst.is_sellable = true), 0) as sellable_qty,
        coalesce(sum(gs.quantity) filter (where lower(trim(gst.description)) = 'stolen'), 0) as stolen_qty,
        coalesce(sum(gs.quantity) filter (where lower(trim(gst.description)) = 'box damage'), 0) as box_damage_qty,
        coalesce(sum(gs.quantity) filter (where lower(trim(gst.description)) = 'expired'), 0) as expired_qty,
        coalesce(sum(gs.quantity) filter (where lower(trim(gst.description)) = 'reserved'), 0) as reserved_qty
      from public.global_stocks gs
      inner join public.global_stock_types gst on gst.id = gs.stock_type_id
      where gs.shipment_item_id = si.id
    ) disp on true
    where si.shipment_id = p_shipment_id
    group by si.id, disp.sellable_qty, disp.stolen_qty, disp.box_damage_qty, disp.expired_qty, disp.reserved_qty
  ) rollup;

  v_total_gross_profit := v_total_revenue - v_total_sold_cost;

  return jsonb_build_object(
    'shipment', v_shipment,
    'items', v_items,
    'totals', jsonb_build_object(
      'landed_cost', v_total_landed_cost,
      'sold_cost', v_total_sold_cost,
      'revenue', v_total_revenue,
      'gross_profit', v_total_gross_profit,
      'sellable_on_hand_value', v_total_sellable_on_hand_value,
      'shrinkage_value', v_total_shrinkage_value,
      'stolen_value', v_total_stolen_value,
      'box_damage_value', v_total_box_damage_value,
      'expired_value', v_total_expired_value,
      'unsold_value', v_total_sellable_on_hand_value, -- alias for backward compat
      'disposition_available', v_disposition_available,
      'reconciliation_gap', v_total_reconciliation_gap
    )
  );
end;
$$;


ALTER FUNCTION "public"."get_shipment_pnl"("p_tenant_id" bigint, "p_shipment_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_shipment_public_status"("p_token" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_ship public.global_shipments%rowtype;
  v_progress_tag jsonb := null;
  v_progress_list jsonb := '[]'::jsonb;
  v_flow jsonb := null;
  v_tag public.tags%rowtype;
begin
  if p_token is null or trim(p_token) = '' then
    return null;
  end if;

  select * into v_ship
  from public.global_shipments
  where public_tracking_token = p_token
  limit 1;

  if not found then
    return null;
  end if;

  select jsonb_build_object(
    'id', f.id,
    'name', f.name,
    'slug', f.slug,
    'is_default', f.is_default
  )
  into v_flow
  from public.shipment_progress_flows f
  where f.id = v_ship.progress_flow_id;

  if v_ship.progress_tag_id is not null then
    select * into v_tag
    from public.tags
    where id = v_ship.progress_tag_id
      and is_active = true
    limit 1;

    if found then
      v_progress_tag := jsonb_build_object(
        'id', v_tag.id,
        'name', v_tag.name,
        'color', v_tag.color,
        'sort_order', v_tag.sort_order
      );
    end if;
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', t.id,
        'name', t.name,
        'color', t.color,
        'sort_order', s.sort_order
      )
      order by s.sort_order asc
    ),
    '[]'::jsonb
  )
  into v_progress_list
  from public.shipment_progress_flow_stages s
  join public.tags t on t.id = s.tag_id
  where s.flow_id = v_ship.progress_flow_id
    and t.is_active = true;

  return jsonb_build_object(
    'id', v_ship.id,
    'name', v_ship.name,
    'status', v_ship.status,
    'progress_flow', v_flow,
    'progress_tag', v_progress_tag,
    'progress_tags', v_progress_list,
    'updated_at', v_ship.updated_at
  );
end;
$$;


ALTER FUNCTION "public"."get_shipment_public_status"("p_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_shop_bootstrap_context"("p_email" "text" DEFAULT NULL::"text", "p_tenant_id" bigint DEFAULT NULL::bigint, "p_customer_group_member_id" bigint DEFAULT NULL::bigint) RETURNS TABLE("member_id" bigint, "member_name" "text", "member_email" "text", "member_role" "public"."customer_group_role", "member_is_active" boolean, "customer_group_id" bigint, "customer_group_name" "text", "customer_group_is_active" boolean, "customer_group_accent_color" "text", "tenant_id" bigint, "tenant_name" "text", "tenant_slug" "text", "tenant_is_active" boolean, "active_module_keys" "text"[], "tenant_role_id" bigint, "is_admin" boolean, "effective_grants" "jsonb", "permission_version" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_email text;
  v_member record;
  v_grants jsonb;
  v_perm_version bigint;
begin
  v_email := lower(trim(coalesce(p_email, public.current_user_email())));

  if p_tenant_id is null or p_customer_group_member_id is null then
    return;
  end if;

  select
    cgm.id,
    coalesce(
      nullif(trim(cgm.name), ''),
      (select coalesce(u.raw_user_meta_data->>'full_name', u.raw_user_meta_data->>'name') from auth.users u where u.email = v_email limit 1)
    ) as name,
    lower(trim(cgm.email)) as email,
    cgm.role,
    cgm.is_active,
    cgm.tenant_role_id,
    cg.id as customer_group_id,
    cg.name as customer_group_name,
    cg.is_active as customer_group_is_active,
    cg.accent_color as customer_group_accent_color,
    t.id as tenant_id,
    t.name as tenant_name,
    t.slug as tenant_slug,
    t.is_active as tenant_is_active,
    coalesce(tr.is_admin, cgm.role = 'admin', false) as is_admin
  into v_member
  from public.customer_group_members cgm
  inner join public.customer_groups cg on cg.id = cgm.customer_group_id
  inner join public.tenants t on t.id = p_tenant_id
  left join public.tenant_roles tr on tr.id = cgm.tenant_role_id
  where p_tenant_id is not null
    and lower(trim(cgm.email)) = v_email
    and cgm.is_active = true
    and cg.is_active = true
    and cg.deleted_at is null
    and t.is_active = true
    and cgm.id = p_customer_group_member_id
    and coalesce(cg.parent_tenant_id, cg.tenant_id) = public.resolve_parent_tenant_id(p_tenant_id)
    and exists (
      select 1
      from public.shop_customer_group_access scga
      inner join public.shops s on s.id = scga.shop_id
      where scga.customer_group_id = cg.id
        and scga.status = true
        and s.tenant_id = p_tenant_id
        and s.is_active = true
        and s.deleted_at is null
    )
  order by
    case cgm.role
      when 'admin' then 1
      when 'manager' then 2
      when 'staff' then 3
      else 99
    end,
    cgm.id asc
  limit 1;

  if v_member.id is null then
    return;
  end if;

  select coalesce(
    jsonb_agg(jsonb_build_object('module_key', module_key, 'action', action)),
    '[]'::jsonb
  )
  into v_grants
  from public.get_shop_effective_grants(v_member.tenant_id, v_member.id);

  select tpv.version into v_perm_version
  from public.tenant_permission_versions tpv
  where tpv.tenant_id = v_member.tenant_id;

  if v_perm_version is null then
    perform public.bump_tenant_permission_version(v_member.tenant_id);
    v_perm_version := 1;
  end if;

  return query
  select
    v_member.id as member_id,
    v_member.name as member_name,
    v_member.email as member_email,
    v_member.role as member_role,
    v_member.is_active as member_is_active,
    v_member.customer_group_id,
    v_member.customer_group_name,
    v_member.customer_group_is_active,
    v_member.customer_group_accent_color,
    v_member.tenant_id,
    v_member.tenant_name,
    v_member.tenant_slug,
    v_member.tenant_is_active,
    coalesce(public.get_active_module_keys_for_tenant(v_member.tenant_id), array[]::text[]) as active_module_keys,
    v_member.tenant_role_id,
    v_member.is_admin,
    v_grants as effective_grants,
    v_perm_version as permission_version;
end;
$$;


ALTER FUNCTION "public"."get_shop_bootstrap_context"("p_email" "text", "p_tenant_id" bigint, "p_customer_group_member_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_shop_catalog_product_for_customer"("p_tenant_id" bigint, "p_shop_slug" "text", "p_product_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_shop_id bigint;
  v_shop_tenant_id bigint;
  v_parent_tenant_id bigint;
  v_shop_name text;
  v_shop_type public.shop_type_enum;
  v_vendor_code text;
  v_order_mode public.shop_order_mode_enum;
  v_is_negotiable boolean;
  v_show_stock_quantity boolean;
  v_default_currency_id bigint;
  v_is_active boolean;
  v_buy_currency_id bigint;
  v_sell_currency_id bigint;
  v_pricing_method text;
  v_markup_percentage numeric;
  v_quantity_display_mode text;
  v_vendor_filters jsonb;
  v_can_browse boolean;
  v_can_see_buy_price boolean;
  v_can_see_sell_price boolean;
  v_can_see_resell_minimum_price boolean;
  v_can_add_to_cart boolean;
  v_can_place_order boolean;
  v_can_negotiate boolean;
  v_can_view_quantity boolean;
  v_can_set_dropship_price boolean;
  v_can_see_catalog_price boolean;
  v_min_available_units integer;
  v_product jsonb;
begin
  if p_tenant_id is null then
    raise exception 'tenant required';
  end if;
  if p_product_id is null then
    raise exception 'product required';
  end if;
  if public.current_customer_group_id(p_tenant_id) is null then
    raise exception 'access denied';
  end if;

  select
    id, tenant_id, name, shop_type, vendor_code, order_mode,
    is_negotiable, show_stock_quantity, default_currency_id, is_active,
    buy_currency_id, sell_currency_id, pricing_method, markup_percentage, quantity_display_mode,
    vendor_filters, min_available_units
  into
    v_shop_id, v_shop_tenant_id, v_shop_name, v_shop_type, v_vendor_code, v_order_mode,
    v_is_negotiable, v_show_stock_quantity, v_default_currency_id, v_is_active,
    v_buy_currency_id, v_sell_currency_id, v_pricing_method, v_markup_percentage, v_quantity_display_mode,
    v_vendor_filters, v_min_available_units
  from public.shops
  where slug = p_shop_slug
    and tenant_id = p_tenant_id
    and deleted_at is null;

  if v_shop_id is null or v_is_active is not true then
    raise exception 'shop not found or inactive';
  end if;

  select
    can_browse, can_see_buy_price, can_see_sell_price, can_see_resell_minimum_price,
    can_add_to_cart, can_place_order,
    can_negotiate, can_view_quantity, can_set_dropship_price
  into
    v_can_browse, v_can_see_buy_price, v_can_see_sell_price, v_can_see_resell_minimum_price,
    v_can_add_to_cart, v_can_place_order,
    v_can_negotiate, v_can_view_quantity, v_can_set_dropship_price
  from public.get_shop_permissions_for_customer(v_shop_id);

  if coalesce(v_can_browse, false) is not true then
    raise exception 'access denied';
  end if;

  v_parent_tenant_id := public.resolve_parent_tenant_id(v_shop_tenant_id);
  v_can_see_catalog_price := coalesce(v_can_see_buy_price, false);

  if v_shop_type = 'vendor_catalog' then
    select jsonb_build_object(
      'product_id', p.id,
      'product_name', p.name,
      'product_image_url', p.image_url,
      'product_barcode', p.barcode,
      'product_code', p.product_code,
      'product_brand', p.brand,
      'product_category', p.category,
      'vendor_code', p.vendor_code,
      'is_available', p.is_available,
      'country_of_origin', p.country_of_origin,
      'expire_date', p.expire_date,
      'unit_price_amount', case when v_can_see_catalog_price then p.list_price_amount else null end,
      'unit_price_currency_id', case when v_can_see_catalog_price then p.list_price_currency_id else null end,
      'unit_price_currency_code', case when v_can_see_catalog_price then (select code from public.global_currencies where id = p.list_price_currency_id) else null end,
      'unit_price_currency_symbol', case when v_can_see_catalog_price then (select symbol from public.global_currencies where id = p.list_price_currency_id) else null end,
      'minimum_sell_price_amount', null,
      'minimum_sell_price_currency_id', null,
      'minimum_sell_price_currency_code', null,
      'minimum_sell_price_currency_symbol', null,
      'available_units', null,
      'global_stock_allocation_id', null,
      'global_stock_id', null,
      'minimum_order_quantity', p.minimum_order_quantity
    )
    into v_product
    from public.products p
    where p.id = p_product_id
      and p.is_available = true
      and coalesce(p.hazardous, false) = false
      and p.parent_tenant_id = v_parent_tenant_id
      and (
        ((v_vendor_filters is null or jsonb_array_length(v_vendor_filters) = 0) and p.vendor_code = v_vendor_code)
        or
        (v_vendor_filters is not null and jsonb_array_length(v_vendor_filters) > 0 and exists (
          select 1
          from jsonb_to_recordset(v_vendor_filters) as vf(vendor_code text, brands text[])
          where vf.vendor_code = p.vendor_code
            and (vf.brands is null or array_length(vf.brands, 1) is null or p.brand = any(vf.brands))
        ))
      )
      and public.shop_catalog_meets_min_available_units(v_min_available_units, p.available_units)
    limit 1;
  else
    select jsonb_build_object(
      'product_id', row.product_id,
      'product_name', row.product_name,
      'product_image_url', row.product_image_url,
      'product_barcode', row.product_barcode,
      'product_code', row.product_code,
      'product_brand', row.product_brand,
      'product_category', row.product_category,
      'vendor_code', row.product_vendor_code,
      'is_available', row.product_is_available,
      'country_of_origin', row.country_of_origin,
      'expire_date', row.expire_date,
      'unit_price_amount', case
        when v_shop_type = 'dropship' and v_can_see_buy_price then row.computed_sell_price
        when v_shop_type = 'fixed_price' and v_can_see_sell_price then row.computed_sell_price
        else null
      end,
      'unit_price_currency_id', case
        when v_shop_type = 'dropship' and v_can_see_buy_price then row.sell_price_currency_id
        when v_shop_type = 'fixed_price' and v_can_see_sell_price then row.sell_price_currency_id
        else null
      end,
      'unit_price_currency_code', case
        when v_shop_type = 'dropship' and v_can_see_buy_price then (select code from public.global_currencies where id = row.sell_price_currency_id)
        when v_shop_type = 'fixed_price' and v_can_see_sell_price then (select code from public.global_currencies where id = row.sell_price_currency_id)
        else null
      end,
      'unit_price_currency_symbol', case
        when v_shop_type = 'dropship' and v_can_see_buy_price then (select symbol from public.global_currencies where id = row.sell_price_currency_id)
        when v_shop_type = 'fixed_price' and v_can_see_sell_price then (select symbol from public.global_currencies where id = row.sell_price_currency_id)
        else null
      end,
      'minimum_sell_price_amount', case when v_can_see_sell_price and v_shop_type = 'dropship' then row.minimum_sell_price_amount else null end,
      'minimum_sell_price_currency_id', case when v_can_see_sell_price and v_shop_type = 'dropship' then row.minimum_sell_price_currency_id else null end,
      'minimum_sell_price_currency_code', case when v_can_see_sell_price and v_shop_type = 'dropship' then (select code from public.global_currencies where id = row.minimum_sell_price_currency_id) else null end,
      'minimum_sell_price_currency_symbol', case when v_can_see_sell_price and v_shop_type = 'dropship' then (select symbol from public.global_currencies where id = row.minimum_sell_price_currency_id) else null end,
      'available_units', case
        when not v_can_view_quantity or not coalesce(row.listing_show_quantity, v_show_stock_quantity) then null
        when v_quantity_display_mode = 'original' then greatest(0, row.available_qty)
        when row.display_quantity_override is not null then row.display_quantity_override
        else greatest(0, row.available_qty)
      end,
      'listing_id', row.listing_id,
      'stock_grade', case
        when row.grade_slug is not null then jsonb_build_object(
          'slug', row.grade_slug,
          'label', row.grade_label,
          'color', row.grade_color
        )
        else null
      end,
      'global_stock_allocation_id', row.global_stock_id,
      'global_stock_id', row.global_stock_id,
      'minimum_order_quantity', row.product_moq
    )
    into v_product
    from (
      select
        l.id as listing_id,
        l.global_stock_id,
        case
          when v_shop_type = 'fixed_price' and v_pricing_method = 'markup' then
            coalesce(gsi.landed_cost_bdt, public.calculate_landed_unit_cost(gsi.id)) * (1 + v_markup_percentage / 100.0)
          when v_shop_type = 'fixed_price' and v_pricing_method = 'direct_cost' then
            coalesce(gsi.landed_cost_bdt, public.calculate_landed_unit_cost(gsi.id))
          else
            l.sell_price_amount
        end as computed_sell_price,
        l.sell_price_currency_id,
        l.minimum_sell_price_amount,
        l.minimum_sell_price_currency_id,
        l.show_quantity as listing_show_quantity,
        l.display_quantity_override,
        p.id as product_id,
        p.name as product_name,
        p.image_url as product_image_url,
        p.barcode as product_barcode,
        p.product_code as product_code,
        p.brand as product_brand,
        p.category as product_category,
        p.vendor_code as product_vendor_code,
        p.is_available as product_is_available,
        p.country_of_origin,
        p.expire_date,
        p.minimum_order_quantity as product_moq,
        public.shop_product_grade_available_units(
          v_shop_tenant_id,
          p.id,
          coalesce(l.grade_tag_id, gs.grade_tag_id)
        ) as available_qty,
        tg.slug as grade_slug,
        tg.name as grade_label,
        tg.color as grade_color
      from public.shop_product_listings l
      join public.products p on p.id = l.product_id
      left join public.global_stocks gs on gs.id = l.global_stock_id
      left join public.global_shipment_items gsi on gsi.id = gs.shipment_item_id
      left join public.tags tg on tg.id = coalesce(l.grade_tag_id, gs.grade_tag_id)
      where l.shop_id = v_shop_id
        and l.product_id = p_product_id
        and l.is_active = true
        and p.is_available = true
        and coalesce(p.hazardous, false) = false
      order by l.id asc
      limit 1
    ) row;
  end if;

  if v_product is null then
    raise exception 'product not found';
  end if;

  return jsonb_build_object(
    'data', v_product,
    'meta', jsonb_build_object(
      'shop', jsonb_build_object(
        'id', v_shop_id,
        'name', v_shop_name,
        'slug', p_shop_slug,
        'shop_type', v_shop_type,
        'vendor_code', v_vendor_code,
        'order_mode', v_order_mode,
        'is_negotiable', v_is_negotiable,
        'show_stock_quantity', v_show_stock_quantity,
        'default_currency_id', v_default_currency_id,
        'is_active', v_is_active,
        'buy_currency_id', v_buy_currency_id,
        'sell_currency_id', v_sell_currency_id,
        'pricing_method', v_pricing_method,
        'markup_percentage', v_markup_percentage,
        'quantity_display_mode', v_quantity_display_mode,
        'vendor_filters', v_vendor_filters
      ),
      'permissions', jsonb_build_object(
        'can_browse', v_can_browse,
        'can_see_buy_price', v_can_see_buy_price,
    'can_see_sell_price', v_can_see_sell_price,
        'can_add_to_cart', v_can_add_to_cart,
        'can_place_order', v_can_place_order,
        'can_negotiate', v_can_negotiate,
        'can_view_quantity', v_can_view_quantity,
        'can_set_dropship_price', v_can_set_dropship_price
      )
    )
  );
end;
$$;


ALTER FUNCTION "public"."get_shop_catalog_product_for_customer"("p_tenant_id" bigint, "p_shop_slug" "text", "p_product_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_shop_catalog_product_for_customer"("p_tenant_id" bigint, "p_shop_slug" "text", "p_product_id" bigint, "p_listing_id" bigint DEFAULT NULL::bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_shop_id bigint;
  v_shop_tenant_id bigint;
  v_parent_tenant_id bigint;
  v_shop_name text;
  v_shop_type public.shop_type_enum;
  v_vendor_code text;
  v_order_mode public.shop_order_mode_enum;
  v_is_negotiable boolean;
  v_show_stock_quantity boolean;
  v_default_currency_id bigint;
  v_is_active boolean;
  v_buy_currency_id bigint;
  v_sell_currency_id bigint;
  v_pricing_method text;
  v_markup_percentage numeric;
  v_quantity_display_mode text;
  v_vendor_filters jsonb;
  v_can_browse boolean;
  v_can_see_buy_price boolean;
  v_can_see_sell_price boolean;
  v_can_see_resell_minimum_price boolean;
  v_can_add_to_cart boolean;
  v_can_place_order boolean;
  v_can_negotiate boolean;
  v_can_view_quantity boolean;
  v_can_set_dropship_price boolean;
  v_product jsonb;
begin
  if p_tenant_id is null then
    raise exception 'tenant required';
  end if;
  if p_product_id is null then
    raise exception 'product required';
  end if;
  if public.current_customer_group_id(p_tenant_id) is null then
    raise exception 'access denied';
  end if;

  select
    id, tenant_id, name, shop_type, vendor_code, order_mode,
    is_negotiable, show_stock_quantity, default_currency_id, is_active,
    buy_currency_id, sell_currency_id, pricing_method, markup_percentage, quantity_display_mode,
    vendor_filters
  into
    v_shop_id, v_shop_tenant_id, v_shop_name, v_shop_type, v_vendor_code, v_order_mode,
    v_is_negotiable, v_show_stock_quantity, v_default_currency_id, v_is_active,
    v_buy_currency_id, v_sell_currency_id, v_pricing_method, v_markup_percentage, v_quantity_display_mode,
    v_vendor_filters
  from public.shops
  where slug = p_shop_slug
    and tenant_id = p_tenant_id
    and deleted_at is null;

  if v_shop_id is null or v_is_active is not true then
    raise exception 'shop not found or inactive';
  end if;

  select
    can_browse, can_see_buy_price, can_see_sell_price, can_see_resell_minimum_price,
    can_add_to_cart, can_place_order,
    can_negotiate, can_view_quantity, can_set_dropship_price
  into
    v_can_browse, v_can_see_buy_price, v_can_see_sell_price, v_can_see_resell_minimum_price,
    v_can_add_to_cart, v_can_place_order,
    v_can_negotiate, v_can_view_quantity, v_can_set_dropship_price
  from public.get_shop_permissions_for_customer(v_shop_id);

  if coalesce(v_can_browse, false) is not true then
    raise exception 'access denied';
  end if;

  v_parent_tenant_id := public.resolve_parent_tenant_id(v_shop_tenant_id);

  if v_shop_type = 'vendor_catalog' then
    select jsonb_build_object(
      'product_id', p.id,
      'product_name', p.name,
      'product_image_url', p.image_url,
      'product_barcode', p.barcode,
      'product_code', p.product_code,
      'product_brand', p.brand,
      'product_category', p.category,
      'vendor_code', p.vendor_code,
      'is_available', p.is_available,
      'country_of_origin', p.country_of_origin,
      'expire_date', p.expire_date,
      'unit_price_amount', case when v_can_see_buy_price then p.list_price_amount else null end,
      'unit_price_currency_id', case when v_can_see_buy_price then p.list_price_currency_id else null end,
      'unit_price_currency_code', case when v_can_see_buy_price then (select code from public.global_currencies where id = p.list_price_currency_id) else null end,
      'unit_price_currency_symbol', case when v_can_see_buy_price then (select symbol from public.global_currencies where id = p.list_price_currency_id) else null end,
      'minimum_sell_price_amount', null,
      'minimum_sell_price_currency_id', null,
      'minimum_sell_price_currency_code', null,
      'minimum_sell_price_currency_symbol', null,
      'available_units', null,
      'global_stock_allocation_id', null,
      'global_stock_id', null,
      'minimum_order_quantity', p.minimum_order_quantity
    )
    into v_product
    from public.products p
    where p.id = p_product_id
      and p.is_available = true
      and coalesce(p.hazardous, false) = false
      and p.parent_tenant_id = v_parent_tenant_id
      and (
        ((v_vendor_filters is null or jsonb_array_length(v_vendor_filters) = 0) and p.vendor_code = v_vendor_code)
        or
        (v_vendor_filters is not null and jsonb_array_length(v_vendor_filters) > 0 and exists (
          select 1
          from jsonb_to_recordset(v_vendor_filters) as vf(vendor_code text, brands text[])
          where vf.vendor_code = p.vendor_code
            and (vf.brands is null or array_length(vf.brands, 1) is null or p.brand = any(vf.brands))
        ))
      )
    limit 1;
  else
    select jsonb_build_object(
      'product_id', row.product_id,
      'product_name', row.product_name,
      'product_image_url', row.product_image_url,
      'product_barcode', row.product_barcode,
      'product_code', row.product_code,
      'product_brand', row.product_brand,
      'product_category', row.product_category,
      'vendor_code', row.product_vendor_code,
      'is_available', row.product_is_available,
      'country_of_origin', row.country_of_origin,
      'expire_date', row.expire_date,
      'unit_price_amount', case
        when v_shop_type = 'dropship' and v_can_see_buy_price then row.computed_sell_price
        when v_shop_type = 'fixed_price' and v_can_see_sell_price then row.computed_sell_price
        else null
      end,
      'unit_price_currency_id', case
        when v_shop_type = 'dropship' and v_can_see_buy_price then row.sell_price_currency_id
        when v_shop_type = 'fixed_price' and v_can_see_sell_price then row.sell_price_currency_id
        else null
      end,
      'unit_price_currency_code', case
        when v_shop_type = 'dropship' and v_can_see_buy_price then (select code from public.global_currencies where id = row.sell_price_currency_id)
        when v_shop_type = 'fixed_price' and v_can_see_sell_price then (select code from public.global_currencies where id = row.sell_price_currency_id)
        else null
      end,
      'unit_price_currency_symbol', case
        when v_shop_type = 'dropship' and v_can_see_buy_price then (select symbol from public.global_currencies where id = row.sell_price_currency_id)
        when v_shop_type = 'fixed_price' and v_can_see_sell_price then (select symbol from public.global_currencies where id = row.sell_price_currency_id)
        else null
      end,
      'minimum_sell_price_amount', case when v_can_see_sell_price and v_shop_type = 'dropship' then row.minimum_sell_price_amount else null end,
      'minimum_sell_price_currency_id', case when v_can_see_sell_price and v_shop_type = 'dropship' then row.minimum_sell_price_currency_id else null end,
      'minimum_sell_price_currency_code', case when v_can_see_sell_price and v_shop_type = 'dropship' then (select code from public.global_currencies where id = row.minimum_sell_price_currency_id) else null end,
      'minimum_sell_price_currency_symbol', case when v_can_see_sell_price and v_shop_type = 'dropship' then (select symbol from public.global_currencies where id = row.minimum_sell_price_currency_id) else null end,
      'available_units', case
        when not v_can_view_quantity or not coalesce(row.listing_show_quantity, v_show_stock_quantity) then null
        when v_quantity_display_mode = 'original' then greatest(0, row.available_qty)
        when row.display_quantity_override is not null then row.display_quantity_override
        else greatest(0, row.available_qty)
      end,
      'listing_id', row.listing_id,      'stock_grade', case        when row.grade_slug is not null then jsonb_build_object(          'slug', row.grade_slug,          'label', row.grade_label,          'color', row.grade_color        )        else null      end,      'global_stock_allocation_id', row.global_stock_id,
      'global_stock_id', row.global_stock_id,
      'minimum_order_quantity', row.product_moq
    )
    into v_product
    from (
      select
        l.id as listing_id,
        l.global_stock_id,
        case
          when v_shop_type = 'fixed_price' and v_pricing_method = 'markup' then
            public.shop_product_grade_avg_landed_cost(v_shop_tenant_id, p.id, coalesce(l.grade_tag_id, gs.grade_tag_id)) * (1 + v_markup_percentage / 100.0)
          when v_shop_type = 'fixed_price' and v_pricing_method = 'direct_cost' then
            public.shop_product_grade_avg_landed_cost(v_shop_tenant_id, p.id, coalesce(l.grade_tag_id, gs.grade_tag_id))
          else
            l.sell_price_amount
        end as computed_sell_price,
        l.sell_price_currency_id,
        l.minimum_sell_price_amount,
        l.minimum_sell_price_currency_id,
        l.show_quantity as listing_show_quantity,
        l.display_quantity_override,
        p.id as product_id,
        p.name as product_name,
        p.image_url as product_image_url,
        p.barcode as product_barcode,
        p.product_code as product_code,
        p.brand as product_brand,
        p.category as product_category,
        p.vendor_code as product_vendor_code,
        p.is_available as product_is_available,
        p.country_of_origin,
        p.expire_date,
        p.minimum_order_quantity as product_moq,
        public.shop_product_grade_available_units(v_shop_tenant_id, p.id, coalesce(l.grade_tag_id, gs.grade_tag_id)) as available_qty,
        tg.slug as grade_slug,
        tg.name as grade_label,
        tg.color as grade_color
      from public.shop_product_listings l
      join public.products p on p.id = l.product_id
      left join public.global_stocks gs on gs.id = l.global_stock_id
      left join public.global_shipment_items gsi on gsi.id = gs.shipment_item_id
      left join public.tags tg on tg.id = coalesce(l.grade_tag_id, gs.grade_tag_id)
      where l.shop_id = v_shop_id
        and l.product_id = p_product_id
        and l.is_active = true
        and p.is_available = true
        and coalesce(p.hazardous, false) = false
        and (p_listing_id is null or l.id = p_listing_id)
        and coalesce(l.grade_tag_id, gs.grade_tag_id) is not null
      order by l.id asc
      limit 1
    ) row;
  end if;

  if v_product is null then
    raise exception 'product not found';
  end if;

  return jsonb_build_object(
    'data', v_product,
    'meta', jsonb_build_object(
      'shop', jsonb_build_object(
        'id', v_shop_id,
        'name', v_shop_name,
        'slug', p_shop_slug,
        'shop_type', v_shop_type,
        'vendor_code', v_vendor_code,
        'order_mode', v_order_mode,
        'is_negotiable', v_is_negotiable,
        'show_stock_quantity', v_show_stock_quantity,
        'default_currency_id', v_default_currency_id,
        'is_active', v_is_active,
        'buy_currency_id', v_buy_currency_id,
        'sell_currency_id', v_sell_currency_id,
        'pricing_method', v_pricing_method,
        'markup_percentage', v_markup_percentage,
        'quantity_display_mode', v_quantity_display_mode,
        'vendor_filters', v_vendor_filters
      ),
      'permissions', jsonb_build_object(
        'can_browse', v_can_browse,
        'can_see_buy_price', v_can_see_buy_price,
    'can_see_sell_price', v_can_see_sell_price,
        'can_add_to_cart', v_can_add_to_cart,
        'can_place_order', v_can_place_order,
        'can_negotiate', v_can_negotiate,
        'can_view_quantity', v_can_view_quantity,
        'can_set_dropship_price', v_can_set_dropship_price
      )
    )
  );
end;
$$;


ALTER FUNCTION "public"."get_shop_catalog_product_for_customer"("p_tenant_id" bigint, "p_shop_slug" "text", "p_product_id" bigint, "p_listing_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_shop_effective_grants"("p_tenant_id" bigint, "p_customer_group_member_id" bigint) RETURNS TABLE("module_key" "text", "action" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_tenant_role_id bigint;
  v_role_is_admin boolean;
  v_cgm_role public.customer_group_role;
begin
  select cgm.tenant_role_id, tr.is_admin, cgm.role
  into v_tenant_role_id, v_role_is_admin, v_cgm_role
  from public.customer_group_members cgm
  left join public.tenant_roles tr on tr.id = cgm.tenant_role_id
  where cgm.id = p_customer_group_member_id
    and cgm.is_active = true;

  if coalesce(v_role_is_admin, v_cgm_role = 'admin', false) = true then
    return query
    select ma.module_key, ma.action
    from public.module_actions ma
    join public.tenant_modules tm on tm.module_key = ma.module_key or tm.module_key = (
      select mo.parent_module_key from public.modules mo where mo.key = ma.module_key limit 1
    )
    where tm.tenant_id = p_tenant_id
      and tm.is_active = true
      and ma.is_active = true
      and ma.scope = 'shop';
    return;
  end if;

  return query
  with role_allowed as (
    select rg.module_key, rg.action
    from public.tenant_role_grants rg
    where rg.tenant_role_id = v_tenant_role_id
      and rg.allowed = true
  ),
  with_overrides as (
    select ra.module_key, ra.action from role_allowed ra
    union
    select g.module_key, g.action
    from public.customer_group_member_grants g
    where g.customer_group_member_id = p_customer_group_member_id
      and g.effect = 'allow'
  ),
  effective as (
    select wo.module_key, wo.action from with_overrides wo
    except
    select g.module_key, g.action
    from public.customer_group_member_grants g
    where g.customer_group_member_id = p_customer_group_member_id
      and g.effect = 'deny'
  )
  select e.module_key, e.action
  from effective e
  join public.module_actions ma on ma.module_key = e.module_key and ma.action = e.action
  join public.tenant_modules tm on tm.module_key = e.module_key or tm.module_key = (
    select mo.parent_module_key from public.modules mo where mo.key = e.module_key limit 1
  )
  where tm.tenant_id = p_tenant_id
    and tm.is_active = true
    and ma.is_active = true
    and ma.scope = 'shop';
end;
$$;


ALTER FUNCTION "public"."get_shop_effective_grants"("p_tenant_id" bigint, "p_customer_group_member_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_shop_order_dashboard_metrics"("p_tenant_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_today date;
  v_sales numeric := 0;
  v_invoice_count bigint := 0;
  v_shipped bigint := 0;
  v_ready bigint := 0;
  v_needs_quote bigint := 0;
  v_processing bigint := 0;
  v_dropship_submitted bigint := 0;
  v_dropship_processing bigint := 0;
  v_dropship_ready bigint := 0;
  v_hourly jsonb := '[]'::jsonb;
  v_couriers jsonb := '[]'::jsonb;
  v_pipeline jsonb := '[]'::jsonb;
BEGIN
  IF NOT public.membership_has_module_action(p_tenant_id, 'shop_order', 'view') THEN
    RAISE EXCEPTION 'not allowed';
  END IF;

  v_today := (timezone('Asia/Dhaka', now()))::date;

  SELECT
    coalesce(sum(si.total_amount), 0),
    count(*)
  INTO v_sales, v_invoice_count
  FROM public.sales_invoices si
  WHERE si.issued_by_tenant_id = p_tenant_id
    AND si.invoice_status = 'issued'::public.global_invoice_status
    AND si.invoice_date = v_today;

  SELECT
    coalesce(count(*) FILTER (WHERE o.status = 'shipped'::public.shop_order_status), 0),
    coalesce(count(*) FILTER (WHERE o.status = 'ready_for_pickup'::public.shop_order_status), 0)
  INTO v_shipped, v_ready
  FROM public.shop_orders o
  WHERE o.tenant_id = p_tenant_id
    AND o.status IN (
      'shipped'::public.shop_order_status,
      'ready_for_pickup'::public.shop_order_status
    );

  SELECT
    coalesce(count(*) FILTER (
      WHERE o.status IN (
        'submitted'::public.shop_order_status,
        'costing_pending'::public.shop_order_status,
        'countered'::public.shop_order_status
      )
    ), 0),
    coalesce(count(*) FILTER (
      WHERE o.status IN (
        'processing'::public.shop_order_status,
        'confirmed'::public.shop_order_status,
        'procuring'::public.shop_order_status,
        'ready_for_shipment'::public.shop_order_status,
        'placed'::public.shop_order_status,
        'ordered'::public.shop_order_status
      )
    ), 0)
  INTO v_needs_quote, v_processing
  FROM public.shop_orders o
  WHERE o.tenant_id = p_tenant_id;

  SELECT
    coalesce(count(*) FILTER (
      WHERE o.shop_type_snapshot = 'dropship'::public.shop_type_enum
        AND o.status = 'submitted'::public.shop_order_status
    ), 0),
    coalesce(count(*) FILTER (
      WHERE o.shop_type_snapshot = 'dropship'::public.shop_type_enum
        AND o.status = 'processing'::public.shop_order_status
    ), 0),
    coalesce(count(*) FILTER (
      WHERE o.shop_type_snapshot = 'dropship'::public.shop_type_enum
        AND o.status = 'ready_for_pickup'::public.shop_order_status
    ), 0)
  INTO v_dropship_submitted, v_dropship_processing, v_dropship_ready
  FROM public.shop_orders o
  WHERE o.tenant_id = p_tenant_id;

  SELECT coalesce(jsonb_agg(row_to_json(p) ORDER BY p.sort_key), '[]'::jsonb)
  INTO v_pipeline
  FROM (
    SELECT
      bucket.status,
      count(*)::bigint AS count,
      bucket.sort_key
    FROM (
      SELECT
        CASE
          WHEN o.status IN (
            'submitted'::public.shop_order_status,
            'costing_pending'::public.shop_order_status,
            'countered'::public.shop_order_status
          ) THEN 'needs_quote'
          WHEN o.status IN (
            'priced'::public.shop_order_status,
            'final_offered'::public.shop_order_status,
            'negotiating'::public.shop_order_status
          ) THEN 'awaiting_customer'
          WHEN o.status IN (
            'processing'::public.shop_order_status,
            'confirmed'::public.shop_order_status,
            'procuring'::public.shop_order_status,
            'ready_for_shipment'::public.shop_order_status,
            'placed'::public.shop_order_status,
            'ordered'::public.shop_order_status
          ) THEN 'processing'
          WHEN o.status = 'ready_for_pickup'::public.shop_order_status THEN 'ready_for_pickup'
          WHEN o.status = 'shipped'::public.shop_order_status THEN 'shipped'
        END AS status,
        CASE
          WHEN o.status IN (
            'submitted'::public.shop_order_status,
            'costing_pending'::public.shop_order_status,
            'countered'::public.shop_order_status
          ) THEN 1
          WHEN o.status IN (
            'priced'::public.shop_order_status,
            'final_offered'::public.shop_order_status,
            'negotiating'::public.shop_order_status
          ) THEN 2
          WHEN o.status IN (
            'processing'::public.shop_order_status,
            'confirmed'::public.shop_order_status,
            'procuring'::public.shop_order_status,
            'ready_for_shipment'::public.shop_order_status,
            'placed'::public.shop_order_status,
            'ordered'::public.shop_order_status
          ) THEN 3
          WHEN o.status = 'ready_for_pickup'::public.shop_order_status THEN 4
          WHEN o.status = 'shipped'::public.shop_order_status THEN 5
        END AS sort_key
      FROM public.shop_orders o
      WHERE o.tenant_id = p_tenant_id
    ) bucket
    WHERE bucket.status IS NOT NULL
    GROUP BY bucket.status, bucket.sort_key
  ) p;

  SELECT coalesce(jsonb_agg(row_to_json(h) ORDER BY h.hour_at), '[]'::jsonb)
  INTO v_hourly
  FROM (
    SELECT
      date_trunc('hour', timezone('Asia/Dhaka', si.created_at)) AS hour_at,
      to_char(timezone('Asia/Dhaka', si.created_at), 'HH12 AM') AS label,
      round(sum(si.total_amount), 2) AS amount
    FROM public.sales_invoices si
    WHERE si.issued_by_tenant_id = p_tenant_id
      AND si.invoice_status = 'issued'::public.global_invoice_status
      AND si.invoice_date = v_today
    GROUP BY 1, 2
  ) h;

  SELECT coalesce(jsonb_agg(row_to_json(c) ORDER BY c.count DESC), '[]'::jsonb)
  INTO v_couriers
  FROM (
    SELECT
      coalesce(nullif(trim(o.courier_name), ''), 'Store pickup') AS name,
      count(*)::bigint AS count,
      count(*) FILTER (WHERE o.status = 'shipped'::public.shop_order_status)::bigint AS shipped_count,
      count(*) FILTER (WHERE o.status = 'ready_for_pickup'::public.shop_order_status)::bigint AS ready_count
    FROM public.shop_orders o
    WHERE o.tenant_id = p_tenant_id
      AND o.status IN (
        'shipped'::public.shop_order_status,
        'ready_for_pickup'::public.shop_order_status
      )
    GROUP BY 1
  ) c;

  RETURN jsonb_build_object(
    'tenant_id', p_tenant_id,
    'today_sales_amount', round(v_sales, 2),
    'today_invoice_count', v_invoice_count,
    'shipped_count', v_shipped,
    'ready_for_pickup_count', v_ready,
    'needs_quote_count', v_needs_quote,
    'processing_count', v_processing,
    'dropship_submitted', v_dropship_submitted,
    'dropship_processing', v_dropship_processing,
    'dropship_ready', v_dropship_ready,
    'hourly', v_hourly,
    'couriers', v_couriers,
    'pipeline', v_pipeline
  );
END;
$$;


ALTER FUNCTION "public"."get_shop_order_dashboard_metrics"("p_tenant_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_shop_order_for_staff"("p_tenant_id" bigint, "p_order_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_order public.shop_orders%rowtype;
  v_shop_name text;
  v_sell_currency_id bigint;
  v_buy_currency_id bigint;
  v_sell_code text;
  v_sell_symbol text;
  v_buy_code text;
  v_buy_symbol text;
  v_customer_group_name text;
  v_item_count bigint;
  v_total_amount numeric;
  v_collection_source public.collection_source_type;
  v_items jsonb;
  v_invoices jsonb;
  v_shipments jsonb;
  v_order_json jsonb;
begin
  if p_tenant_id is null or p_order_id is null then
    raise exception 'tenant required';
  end if;

  if not public.is_tenant_staff(p_tenant_id) then
    raise exception 'access denied';
  end if;

  select *
  into v_order
  from public.shop_orders o
  where o.id = p_order_id;

  if not found then
    raise exception 'order not found';
  end if;

  if v_order.tenant_id is distinct from p_tenant_id and v_order.parent_tenant_id is distinct from p_tenant_id then
    raise exception 'tenant mismatch';
  end if;

  select
    s.name,
    s.sell_currency_id,
    s.buy_currency_id,
    sell_gc.code,
    sell_gc.symbol,
    buy_gc.code,
    buy_gc.symbol
  into
    v_shop_name,
    v_sell_currency_id,
    v_buy_currency_id,
    v_sell_code,
    v_sell_symbol,
    v_buy_code,
    v_buy_symbol
  from public.shops s
  left join public.global_currencies sell_gc on sell_gc.id = s.sell_currency_id
  left join public.global_currencies buy_gc on buy_gc.id = s.buy_currency_id
  where s.id = v_order.shop_id;

  select cg.name
  into v_customer_group_name
  from public.customer_groups cg
  where cg.id = v_order.customer_group_id;

  v_collection_source := v_order.collection_source;
  if v_collection_source is null and v_order.global_invoice_id is not null then
    select inv.collection_source
    into v_collection_source
    from public.sales_invoices inv
    where inv.id = v_order.global_invoice_id;
  end if;
  if v_collection_source is null and v_order.is_prepaid_snapshot then
    v_collection_source := 'billing_profile'::public.collection_source_type;
  end if;

  select count(*)::bigint
  into v_item_count
  from public.shop_order_items soi
  where soi.order_id = v_order.id;

  select coalesce(
    sum(
      coalesce(
        soi.final_price_amount,
        soi.staff_offer_amount,
        soi.customer_offer_amount,
        soi.unit_sell_price_amount,
        soi.unit_list_price_amount
      ) * soi.quantity
    ),
    0
  )
  into v_total_amount
  from public.shop_order_items soi
  where soi.order_id = v_order.id;

  if v_order.global_invoice_id is not null then
    v_invoices := jsonb_build_array(jsonb_build_object('id', v_order.global_invoice_id));
  else
    v_invoices := '[]'::jsonb;
  end if;

  select coalesce(
    jsonb_agg(jsonb_build_object('id', x.shipment_id) order by x.shipment_id),
    '[]'::jsonb
  )
  into v_shipments
  from (
    select distinct gship.id as shipment_id
    from public.shop_order_items soi
    join public.global_stocks gs on gs.id = soi.global_stock_id
    join public.global_shipment_items gsi on gsi.id = gs.shipment_item_id
    join public.global_shipments gship on gship.id = gsi.shipment_id
    where soi.order_id = v_order.id
  ) x;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', soi.id,
        'order_id', soi.order_id,
        'name', soi.name,
        'image_url', soi.image_url,
        'quantity', soi.quantity,
        'created_at', soi.created_at,
        'updated_at', soi.updated_at,
        'product', jsonb_build_object(
          'id', soi.product_id,
          'sku', p.product_code,
          'brand', p.brand,
          'barcode', p.barcode,
          'weight_gm', p.product_weight,
          'package_weight_gm', p.package_weight,
          'minimum_order_quantity', coalesce(p.minimum_order_quantity, 1)
        ),
        'pricing', jsonb_build_object(
          'cost', jsonb_build_object(
            'amount', coalesce(soi.cost_price_amount, soi.unit_list_price_amount, p.reference_cost_amount),
            'currency', (
              select jsonb_build_object('id', gc.id, 'code', gc.code, 'symbol', gc.symbol)
              from public.global_currencies gc
              where gc.id = coalesce(
                soi.cost_price_currency_id,
                soi.unit_list_price_currency_id
              )
              limit 1
            )
          ),
          'list', jsonb_build_object(
            'amount', soi.unit_list_price_amount,
            'currency', (
              select jsonb_build_object('id', gc.id, 'code', gc.code, 'symbol', gc.symbol)
              from public.global_currencies gc
              where gc.id = soi.unit_list_price_currency_id
              limit 1
            )
          ),
          'sell', jsonb_build_object(
            'amount', soi.unit_sell_price_amount,
            'currency', (
              select jsonb_build_object('id', gc.id, 'code', gc.code, 'symbol', gc.symbol)
              from public.global_currencies gc
              where gc.id = soi.unit_sell_price_currency_id
              limit 1
            )
          ),
          'minimum_sell', jsonb_build_object(
            'amount', soi.unit_minimum_sell_price_amount,
            'currency', (
              select jsonb_build_object('id', gc.id, 'code', gc.code, 'symbol', gc.symbol)
              from public.global_currencies gc
              where gc.id = soi.unit_minimum_sell_price_currency_id
              limit 1
            )
          )
        ),
        'negotiation', jsonb_build_object(
          'status', soi.negotiation_status,
          'customer_decision', soi.customer_decision_status,
          'staff_offer', case
            when soi.staff_offer_amount is not null then jsonb_build_object(
              'amount', soi.staff_offer_amount,
              'currency', (
                select jsonb_build_object('id', gc.id, 'code', gc.code, 'symbol', gc.symbol)
                from public.global_currencies gc
                where gc.id = soi.staff_offer_currency_id
                limit 1
              ),
              'at', soi.staff_offer_at,
              'is_manual', soi.is_first_offer_manual
            )
            else null
          end,
          'customer_offer', case
            when soi.customer_offer_amount is not null then jsonb_build_object(
              'amount', soi.customer_offer_amount,
              'currency', (
                select jsonb_build_object('id', gc.id, 'code', gc.code, 'symbol', gc.symbol)
                from public.global_currencies gc
                where gc.id = soi.customer_offer_currency_id
                limit 1
              ),
              'at', soi.customer_counter_at
            )
            else null
          end,
          'final_offer', case
            when soi.final_price_amount is not null then jsonb_build_object(
              'amount', soi.final_price_amount,
              'currency', (
                select jsonb_build_object('id', gc.id, 'code', gc.code, 'symbol', gc.symbol)
                from public.global_currencies gc
                where gc.id = soi.final_price_currency_id
                limit 1
              ),
              'at', soi.final_offer_at,
              'is_manual', soi.is_final_offer_manual
            )
            else null
          end,
          'weight_kg', soi.weight_kg,
          'confirmed_quantity', soi.confirmed_quantity
        ),
        'fulfillment', jsonb_build_object(
          'returned', soi.returned_quantity,
          'procurement_pulled', soi.procurement_pulled
        ),
        'stock', case
          when soi.global_stock_id is not null then jsonb_build_object(
            'global_stock_id', soi.global_stock_id,
            'global_stock_allocation_id', soi.global_stock_allocation_id,
            'shipment_item_id', gsi.id,
            'shipment_id', gship.id
          )
          else null
        end
      )
      order by soi.created_at, soi.id
    ),
    '[]'::jsonb
  )
  into v_items
  from public.shop_order_items soi
  left join public.products p on p.id = soi.product_id
  left join public.global_stocks gs on gs.id = soi.global_stock_id
  left join public.global_shipment_items gsi on gsi.id = gs.shipment_item_id
  left join public.global_shipments gship on gship.id = gsi.shipment_id
  where soi.order_id = v_order.id;

  v_order_json := jsonb_build_object(
    'id', v_order.id,
    'tenant_id', v_order.tenant_id,
    'order_no', v_order.order_no,
    'name', v_order.name,
    'cart_id', v_order.cart_id,
    'created_by_email', v_order.created_by_email,
    'created_at', v_order.created_at,
    'updated_at', v_order.updated_at,
    'placed_at', v_order.placed_at,
    'fulfilled_at', v_order.fulfilled_at,
    'global_invoice_id', v_order.global_invoice_id,
    'collection_source', v_collection_source,
    'shop', jsonb_build_object(
      'id', v_order.shop_id,
      'name', v_shop_name,
      'type', v_order.shop_type_snapshot,
      'order_mode', v_order.order_mode_snapshot,
      'is_negotiable', v_order.is_negotiable_snapshot,
      'sell_currency', case
        when v_sell_currency_id is not null then jsonb_build_object(
          'id', v_sell_currency_id,
          'code', v_sell_code,
          'symbol', v_sell_symbol
        )
        else null
      end,
      'buy_currency', case
        when v_buy_currency_id is not null then jsonb_build_object(
          'id', v_buy_currency_id,
          'code', v_buy_code,
          'symbol', v_buy_symbol
        )
        else null
      end
    ),
    'customer', jsonb_build_object(
      'group_id', v_order.customer_group_id,
      'group_name', v_customer_group_name
    ),
    'status', jsonb_build_object(
      'value', v_order.status,
      'negotiate_round', v_order.negotiate_round
    ),
    'rates', jsonb_build_object(
      'cargo', v_order.cargo_rate,
      'conversion', v_order.conversion_rate,
      'profit', v_order.profit_rate,
      'first_offer', v_order.first_offer_rate,
      'final_offer', v_order.final_offer_rate,
      'profit_basis', v_order.profit_basis,
      'package_weight_kg', v_order.package_weight_kg
    ),
    'recipient', jsonb_build_object(
      'name', v_order.recipient_name,
      'phone', v_order.recipient_phone,
      'phone_secondary', v_order.recipient_phone_secondary,
      'address', v_order.shipping_address,
      'district', v_order.shipping_district,
      'thana', v_order.shipping_thana,
      'profile_id', v_order.recipient_profile_id,
      'billing_profile_id', v_order.billing_profile_id,
      'delivery_instructions', v_order.delivery_instructions,
      'is_prepaid', v_order.is_prepaid_snapshot
    ),
    'charges', jsonb_build_object(
      'cod', v_order.cod_charge_amount,
      'delivery', v_order.delivery_charge_amount,
      'print', v_order.print_charge_amount,
      'packing', v_order.packing_charge_amount,
      'discount', v_order.discount_amount,
      'deduct_from_margin', jsonb_build_object(
        'charges', v_order.deduct_charges_from_margin,
        'cod', v_order.deduct_cod_from_margin,
        'delivery', v_order.deduct_delivery_from_margin,
        'print', v_order.deduct_print_from_margin,
        'packing', v_order.deduct_packing_from_margin
      )
    ),
    'totals', jsonb_build_object(
      'item_count', v_item_count,
      'amount', v_total_amount,
      'currency', case
        when v_sell_currency_id is not null then jsonb_build_object(
          'id', v_sell_currency_id,
          'code', v_sell_code,
          'symbol', v_sell_symbol
        )
        else null
      end
    ),
    'courier', jsonb_build_object(
      'service_id', v_order.courier_service_id,
      'name', v_order.courier_name,
      'awb_number', v_order.courier_awb_number,
      'tracking_url', v_order.tracking_url,
      'order_ref', v_order.courier_order_ref,
      'tracking_number', v_order.courier_tracking_number,
      'consignment_id', v_order.courier_consignment_id,
      'cost_amount', v_order.courier_cost_amount,
      'delivered_at', v_order.delivered_at,
      'returned_at', v_order.returned_at
    ),
    'pickup', jsonb_build_object(
      'sender_name', v_order.sender_name,
      'phone', v_order.pickup_phone,
      'address', v_order.pickup_address,
      'default_sender_name', v_order.default_sender_name,
      'default_phone', v_order.default_pickup_phone,
      'default_address', v_order.default_pickup_address
    ),
    'payout', jsonb_build_object(
      'account_type', v_order.payout_account_type,
      'account_info', v_order.payout_account_info,
      'default_account_type', v_order.default_payout_account_type,
      'default_account_info', v_order.default_payout_account_info,
      'settlement_status', v_order.payout_settlement_status,
      'cod_collect_amount', v_order.cod_collect_amount,
      'courier_remittance_ref', v_order.courier_remittance_ref,
      'courier_bank_trx_id', v_order.courier_bank_trx_id
    ),
    'parcel', jsonb_build_object(
      'weight_band', v_order.package_weight_band,
      'item_category', v_order.item_category,
      'description', v_order.parcel_description,
      'delivery_zone', v_order.delivery_zone,
      'allow_open_box', v_order.allow_open_box,
      'driver_notes', v_order.driver_notes,
      'delivery_instruction_notes', v_order.delivery_instruction_notes
    ),
    'return_info', jsonb_build_object(
      'sub_state', v_order.return_sub_state,
      'override_reason', v_order.return_override_reason,
      'ref', v_order.return_ref,
      'charge_amount', v_order.return_charge_amount,
      'deduct_charge_from_middle_man', v_order.deduct_return_charge_from_middle_man,
      'replacement_of_order_id', v_order.replacement_of_order_id,
      'middle_man_reference', v_order.middle_man_reference
    ),
    'links', jsonb_build_object(
      'invoices', v_invoices,
      'shipments', v_shipments
    )
  );

  return jsonb_build_object(
    'order', v_order_json,
    'items', v_items
  );
end;
$$;


ALTER FUNCTION "public"."get_shop_order_for_staff"("p_tenant_id" bigint, "p_order_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_shop_permissions_for_customer"("p_shop_id" bigint) RETURNS TABLE("can_browse" boolean, "can_see_buy_price" boolean, "can_see_sell_price" boolean, "can_see_resell_minimum_price" boolean, "can_add_to_cart" boolean, "can_place_order" boolean, "can_negotiate" boolean, "can_view_quantity" boolean, "can_set_dropship_price" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_shop_active boolean;
  v_tenant_id bigint;
  v_shop_type public.shop_type_enum;
  v_shop_allows_negotiate boolean;
begin
  select is_active, tenant_id, shop_type
  into v_shop_active, v_tenant_id, v_shop_type
  from public.shops
  where id = p_shop_id;

  if v_shop_active is not true then
    return query select false, false, false, false, false, false, false, false, false;
    return;
  end if;
  v_shop_allows_negotiate := v_shop_type = 'vendor_catalog';

  return query
  select
    coalesce(bool_or(
      case when access.status = false or coalesce(profile.is_active, true) = false then false
      else coalesce(access.can_browse, profile.default_can_browse, false)
      end
    ), false) as can_browse,

    coalesce(bool_or(
      case when access.status = false or coalesce(profile.is_active, true) = false then false
      else public.resolve_shop_can_see_buy_price(
        v_shop_type,
        access.can_see_buy_price,
        access.can_see_sell_price,
        profile.default_can_see_buy_price,
        profile.default_can_see_sell_price
      )
      end
    ), false) as can_see_buy_price,

    coalesce(bool_or(
      case when access.status = false or coalesce(profile.is_active, true) = false then false
      else
        case when v_shop_type = 'dropship' then true
        else coalesce(access.can_see_sell_price, profile.default_can_see_sell_price, false)
        end
      end
    ), false) as can_see_sell_price,

    coalesce(bool_or(
      case when access.status = false or coalesce(profile.is_active, true) = false then false
      else coalesce(access.can_see_resell_minimum_price, profile.default_can_see_resell_minimum_price, false)
      end
    ), false) as can_see_resell_minimum_price,

    coalesce(bool_or(
      case when access.status = false or coalesce(profile.is_active, true) = false then false
      else coalesce(access.can_add_to_cart, profile.default_can_add_to_cart, false)
      end
    ), false) as can_add_to_cart,

    coalesce(bool_or(
      case when access.status = false or coalesce(profile.is_active, true) = false then false
      else coalesce(access.can_place_order, profile.default_can_place_order, false)
      end
    ), false) as can_place_order,

    coalesce(bool_or(
      case when access.status = false or coalesce(profile.is_active, true) = false then false
      else coalesce(access.can_negotiate, profile.default_can_negotiate, false)
      end
    ) and v_shop_allows_negotiate, false) as can_negotiate,

    coalesce(bool_or(
      case when access.status = false or coalesce(profile.is_active, true) = false then false
      else coalesce(access.can_view_quantity, profile.default_can_view_quantity, false)
      end
    ), false) as can_view_quantity,

    coalesce(bool_or(
      case when access.status = false or coalesce(profile.is_active, true) = false then false
      else
        case when v_shop_type = 'dropship' then true
        else coalesce(access.can_set_dropship_price, profile.default_can_set_dropship_price, false)
        end
      end
    ), false) as can_set_dropship_price
  from public.customer_group_members cgm
  join public.customer_groups cg on cg.id = cgm.customer_group_id
  join public.shop_customer_group_access access on access.customer_group_id = cg.id
  left join public.customer_group_shop_profiles profile
    on profile.customer_group_id = cg.id and profile.tenant_id = v_tenant_id
  where access.shop_id = p_shop_id
    and cg.id = public.current_customer_group_id(v_tenant_id)
    and cg.is_active = true
    and cg.deleted_at is null
    and cgm.is_active = true
    and lower(trim(cgm.email)) = public.current_user_email()
    and coalesce(cg.parent_tenant_id, cg.tenant_id) = public.resolve_parent_tenant_id(v_tenant_id);
end;
$$;


ALTER FUNCTION "public"."get_shop_permissions_for_customer"("p_shop_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_shop_storefront_listing_price_calculation"("p_shop_id" bigint, "p_listing_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_tenant_id bigint;
  v_shop_type public.shop_type_enum;
  v_buy_currency_id bigint;
  v_sell_currency_id bigint;
  v_pricing_method text;
  v_markup_percentage numeric;
  v_listing record;
  v_product_id bigint;
  v_grade_tag_id bigint;
  v_cost_currency_id bigint;
  v_result jsonb;
BEGIN
  SELECT
    s.tenant_id,
    s.shop_type,
    s.buy_currency_id,
    s.sell_currency_id,
    s.pricing_method,
    s.markup_percentage
  INTO
    v_tenant_id,
    v_shop_type,
    v_buy_currency_id,
    v_sell_currency_id,
    v_pricing_method,
    v_markup_percentage
  FROM public.shops s
  WHERE s.id = p_shop_id
    AND s.deleted_at IS NULL;

  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'shop not found';
  END IF;

  IF NOT public.has_active_tenant_membership(v_tenant_id)
     AND NOT public.has_active_tenant_membership(public.resolve_parent_tenant_id(v_tenant_id))
     AND NOT public.is_superadmin() THEN
    RAISE EXCEPTION 'not allowed';
  END IF;

  SELECT
    l.id,
    l.shop_id,
    l.product_id,
    l.global_stock_id,
    l.sell_price_amount,
    l.sell_price_currency_id,
    l.minimum_sell_price_amount,
    l.minimum_sell_price_currency_id,
    l.display_quantity_override,
    l.is_active,
    l.is_price_locked,
    l.show_quantity,
    p.name AS product_name,
    p.product_code,
    p.image_url AS product_image_url,
    tg.slug AS grade_slug,
    tg.name AS grade_label,
    tg.color AS grade_color,
    gs.grade_tag_id
  INTO v_listing
  FROM public.shop_product_listings l
  JOIN public.products p ON p.id = l.product_id
  LEFT JOIN public.global_stocks gs ON gs.id = l.global_stock_id
  LEFT JOIN public.tags tg ON tg.id = gs.grade_tag_id
  WHERE l.id = p_listing_id
    AND l.shop_id = p_shop_id;

  IF v_listing.id IS NULL THEN
    RAISE EXCEPTION 'listing not found';
  END IF;

  v_product_id := v_listing.product_id;
  v_grade_tag_id := coalesce(v_listing.grade_tag_id, public.default_stock_grade_tag_id());
  v_cost_currency_id := CASE
    WHEN v_shop_type = 'dropship'::public.shop_type_enum THEN v_buy_currency_id
    ELSE v_sell_currency_id
  END;

  WITH stock_lines AS (
    SELECT
      gship.id AS shipment_id,
      gship.name AS shipment_name,
      greatest(0, floor(public.global_stock_atp_qty(gs.id)))::integer AS quantity,
      coalesce(gsi.landed_cost_bdt, public.calculate_landed_unit_cost(gsi.id), 0)::numeric AS unit_cost_amount
    FROM public.global_stocks gs
    JOIN public.global_shipment_items gsi ON gsi.id = gs.shipment_item_id
    JOIN public.global_shipments gship ON gship.id = gsi.shipment_id
    LEFT JOIN public.stock_locations sl ON sl.id = gs.location_id
    WHERE gsi.product_id = v_product_id
      AND coalesce(gs.grade_tag_id, public.default_stock_grade_tag_id()) = v_grade_tag_id
      AND gs.parent_tenant_id = public.resolve_parent_tenant_id(v_tenant_id)
      AND public.shop_shipment_alloc_visible_to_tenant(gship.assigned_child_tenant_id, v_tenant_id)
      AND gship.status = 'received'
      AND gs.availability = 'sellable'::public.stock_availability
      AND (gs.location_id IS NULL OR sl.is_pickable = true)
      AND public.global_stock_atp_qty(gs.id) > 0
  ),
  shipment_agg AS (
    SELECT
      sl.shipment_id,
      sl.shipment_name,
      sum(sl.quantity)::integer AS quantity,
      CASE
        WHEN sum(sl.quantity) > 0 THEN round(sum(sl.quantity * sl.unit_cost_amount) / sum(sl.quantity), 4)
        ELSE 0::numeric
      END AS unit_cost_amount
    FROM stock_lines sl
    GROUP BY sl.shipment_id, sl.shipment_name
  ),
  totals AS (
    SELECT
      coalesce(sum(sa.quantity), 0)::integer AS total_quantity,
      CASE
        WHEN coalesce(sum(sa.quantity), 0) > 0 THEN round(
          (
            SELECT sum(sl.quantity * sl.unit_cost_amount)
            FROM stock_lines sl
          ) / sum(sa.quantity),
          4
        )
        ELSE 0::numeric
      END AS weighted_avg_cost
    FROM shipment_agg sa
  )
  SELECT
    jsonb_build_object(
      'listing',
      jsonb_build_object(
        'listing_id', v_listing.id,
        'shop_id', v_listing.shop_id,
        'product_id', v_product_id,
        'product_name', v_listing.product_name,
        'product_code', v_listing.product_code,
        'product_image_url', v_listing.product_image_url,
        'global_stock_id', v_listing.global_stock_id,
        'grade_tag_id', v_grade_tag_id,
        'stock_grade',
        CASE
          WHEN v_listing.grade_slug IS NOT NULL THEN jsonb_build_object(
            'slug', v_listing.grade_slug,
            'label', v_listing.grade_label,
            'color', v_listing.grade_color
          )
          ELSE NULL
        END,
        'is_active', v_listing.is_active,
        'is_price_locked', v_listing.is_price_locked
      ),
      'shipment_costs',
      coalesce(
        (
          SELECT jsonb_agg(
            jsonb_build_object(
              'shipment_id', sa.shipment_id,
              'shipment_no', 'SHP-' || sa.shipment_id::text,
              'shipment_name', sa.shipment_name,
              'quantity', sa.quantity,
              'unit_cost_amount', sa.unit_cost_amount
            )
            ORDER BY sa.shipment_name ASC, sa.shipment_id ASC
          )
          FROM shipment_agg sa
        ),
        '[]'::jsonb
      ),
      'totals',
      (
        SELECT jsonb_build_object(
          'total_quantity', t.total_quantity,
          'real_available_units', t.total_quantity,
          'weighted_avg_cost',
          jsonb_build_object(
            'amount', t.weighted_avg_cost,
            'currency_id', v_cost_currency_id,
            'code', (SELECT gc.code FROM public.global_currencies gc WHERE gc.id = v_cost_currency_id),
            'symbol', (SELECT gc.symbol FROM public.global_currencies gc WHERE gc.id = v_cost_currency_id)
          )
        )
        FROM totals t
      ),
      'pricing',
      jsonb_build_object(
        'display_quantity_override', v_listing.display_quantity_override,
        'suggested_display_quantity', coalesce((SELECT t.total_quantity FROM totals t), 0),
        'sell_price',
        jsonb_build_object(
          'amount', v_listing.sell_price_amount,
          'currency_id', v_listing.sell_price_currency_id,
          'code', (SELECT gc.code FROM public.global_currencies gc WHERE gc.id = v_listing.sell_price_currency_id),
          'symbol', (SELECT gc.symbol FROM public.global_currencies gc WHERE gc.id = v_listing.sell_price_currency_id)
        ),
        'suggested_sell_price',
        CASE
          WHEN v_shop_type = 'fixed_price'::public.shop_type_enum
            AND v_pricing_method = 'markup'
            AND (SELECT t.weighted_avg_cost FROM totals t) IS NOT NULL THEN jsonb_build_object(
            'amount',
            round((SELECT t.weighted_avg_cost FROM totals t) * (1 + coalesce(v_markup_percentage, 0) / 100.0), 4),
            'currency_id', v_listing.sell_price_currency_id,
            'code', (SELECT gc.code FROM public.global_currencies gc WHERE gc.id = v_listing.sell_price_currency_id),
            'symbol', (SELECT gc.symbol FROM public.global_currencies gc WHERE gc.id = v_listing.sell_price_currency_id)
          )
          ELSE NULL
        END,
        'resell_minimum_price',
        CASE
          WHEN v_shop_type = 'dropship'::public.shop_type_enum
            AND v_listing.minimum_sell_price_amount IS NOT NULL THEN jsonb_build_object(
            'amount', v_listing.minimum_sell_price_amount,
            'currency_id', v_listing.minimum_sell_price_currency_id,
            'code', (SELECT gc.code FROM public.global_currencies gc WHERE gc.id = v_listing.minimum_sell_price_currency_id),
            'symbol', (SELECT gc.symbol FROM public.global_currencies gc WHERE gc.id = v_listing.minimum_sell_price_currency_id)
          )
          ELSE NULL
        END
      ),
      'shop',
      jsonb_build_object(
        'id', p_shop_id,
        'shop_type', v_shop_type,
        'pricing_method', v_pricing_method,
        'markup_percentage', v_markup_percentage,
        'sell_currency_id', v_sell_currency_id,
        'buy_currency_id', v_buy_currency_id
      )
    )
  INTO v_result;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_shop_storefront_listing_price_calculation"("p_shop_id" bigint, "p_listing_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_staff_investor_capital_metrics"("p_tenant_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_books_id bigint;
  v_month_start timestamptz;
  v_capital_in numeric := 0;
  v_withdrawn numeric := 0;
  v_deployed numeric := 0;
  v_deployed_month numeric := 0;
  v_realized numeric := 0;
  v_open_count bigint := 0;
  v_containers jsonb := '[]'::jsonb;
BEGIN
  IF NOT public.membership_has_module_action(p_tenant_id, 'investor_capital_ledger', 'view') THEN
    RAISE EXCEPTION 'not allowed';
  END IF;

  v_books_id := public.resolve_parent_tenant_id(p_tenant_id);
  v_month_start := date_trunc('month', timezone('Asia/Dhaka', now()));

  SELECT coalesce(sum(tx.amount), 0)
  INTO v_capital_in
  FROM public.investor_transactions tx
  JOIN public.investors i ON i.id = tx.investor_id
  WHERE i.tenant_id = v_books_id
    AND tx.type IN ('deposit', 'capital_in', 'capital_adjustment', 'manual_adjustment');

  SELECT coalesce(sum(tx.amount), 0)
  INTO v_withdrawn
  FROM public.investor_transactions tx
  JOIN public.investors i ON i.id = tx.investor_id
  WHERE i.tenant_id = v_books_id
    AND tx.type IN ('withdrawal', 'withdrawal_paid', 'profit_payout');

  SELECT
    coalesce(sum(si.allocated_cost), 0),
    coalesce(sum(si.allocated_cost) FILTER (WHERE si.created_at >= v_month_start), 0),
    coalesce(sum(si.computed_profit) FILTER (WHERE si.profit_status = 'realized'), 0),
    count(DISTINCT coalesce(si.global_shipment_id, si.shipment_id))
      FILTER (WHERE si.status = 'active'::public.shipment_investment_status)
  INTO v_deployed, v_deployed_month, v_realized, v_open_count
  FROM public.shipment_investments si
  WHERE si.tenant_id = v_books_id
    AND si.status = 'active'::public.shipment_investment_status;

  SELECT coalesce(jsonb_agg(row_to_json(c)), '[]'::jsonb)
  INTO v_containers
  FROM (
    SELECT
      coalesce(gs.name, 'Unnamed batch') AS name,
      round(sum(si.allocated_cost), 2) AS allocated_cost
    FROM public.shipment_investments si
    LEFT JOIN public.global_shipments gs ON gs.id = coalesce(si.global_shipment_id, si.shipment_id)
    WHERE si.tenant_id = v_books_id
      AND si.status = 'active'::public.shipment_investment_status
    GROUP BY coalesce(gs.name, 'Unnamed batch')
    ORDER BY sum(si.allocated_cost) DESC
    LIMIT 5
  ) c;

  RETURN jsonb_build_object(
    'tenant_id', v_books_id,
    'active_pool_amount', round(v_capital_in - v_withdrawn, 2),
    'deployed_amount', round(v_deployed, 2),
    'deployed_this_month', round(v_deployed_month, 2),
    'due_to_investors', round(greatest(v_realized - v_withdrawn, 0), 2),
    'returned_amount', round(v_withdrawn, 2),
    'open_container_count', v_open_count,
    'open_containers', v_containers
  );
END;
$$;


ALTER FUNCTION "public"."get_staff_investor_capital_metrics"("p_tenant_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_tag_by_slug"("p_category_id" bigint DEFAULT NULL::bigint, "p_module_key" "text" DEFAULT NULL::"text", "p_code" "text" DEFAULT NULL::"text", "p_slug" "text" DEFAULT NULL::"text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_category_id bigint;
  v_res json;
begin
  if p_slug is null then
    return null;
  end if;

  if p_category_id is not null then
    select tc.id into v_category_id
    from public.tag_categories tc
    where tc.id = p_category_id
      and tc.is_active = true
      and (
        tc.is_system = true
        or tc.tenant_id is null
        or public.has_active_tenant_membership(tc.tenant_id)
      );
  elsif p_module_key is not null and p_code is not null then
    select tc.id into v_category_id
    from public.tag_categories tc
    where tc.module_key = p_module_key
      and tc.code = p_code
      and tc.is_active = true
      and (
        tc.is_system = true
        or tc.tenant_id is null
        or public.has_active_tenant_membership(tc.tenant_id)
      )
    order by tc.is_system desc, tc.id asc
    limit 1;
  end if;

  if v_category_id is null then
    return null;
  end if;

  select row_to_json(t)
  into v_res
  from (
    select
      tg.id,
      tg.category_id,
      tg.slug,
      tg.name,
      tg.color,
      tg.metadata,
      tg.sort_order,
      tg.is_system,
      tg.is_active,
      tg.tenant_id,
      tg.group_name,
      tg.type
    from public.tags tg
    where tg.category_id = v_category_id
      and tg.slug = p_slug
      and tg.is_active = true
    limit 1
  ) t;

  return v_res;
end;
$$;


ALTER FUNCTION "public"."get_tag_by_slug"("p_category_id" bigint, "p_module_key" "text", "p_code" "text", "p_slug" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_tasks_dashboard_metrics"("p_tenant_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_email text;
  v_today date;
  v_assigned bigint := 0;
  v_overdue bigint := 0;
  v_due_today bigint := 0;
  v_unassigned bigint := 0;
  v_todo bigint := 0;
  v_doing bigint := 0;
  v_stuck bigint := 0;
  v_done bigint := 0;
BEGIN
  IF NOT public.membership_has_module_action(p_tenant_id, 'tasks', 'view') THEN
    RAISE EXCEPTION 'not allowed';
  END IF;

  v_email := public.current_user_email();
  v_today := (timezone('Asia/Dhaka', now()))::date;

  SELECT
    count(*) FILTER (
      WHERE EXISTS (
        SELECT 1 FROM public.item_assignees ia
        WHERE ia.item_id = i.id AND ia.user_email = v_email
      )
      AND i.status NOT IN ('done', 'archived')
    ),
    count(*) FILTER (
      WHERE i.due_date IS NOT NULL
        AND i.due_date < now()
        AND i.status NOT IN ('done', 'archived')
    ),
    count(*) FILTER (
      WHERE i.due_date IS NOT NULL
        AND (timezone('Asia/Dhaka', i.due_date))::date = v_today
        AND i.status NOT IN ('done', 'archived')
    ),
    count(*) FILTER (
      WHERE NOT EXISTS (SELECT 1 FROM public.item_assignees ia WHERE ia.item_id = i.id)
        AND i.status NOT IN ('done', 'archived')
    ),
    count(*) FILTER (
      WHERE EXISTS (
        SELECT 1 FROM public.item_assignees ia
        WHERE ia.item_id = i.id AND ia.user_email = v_email
      )
      AND i.status = 'todo'
    ),
    count(*) FILTER (
      WHERE EXISTS (
        SELECT 1 FROM public.item_assignees ia
        WHERE ia.item_id = i.id AND ia.user_email = v_email
      )
      AND i.status = 'in_progress'
    ),
    count(*) FILTER (
      WHERE EXISTS (
        SELECT 1 FROM public.item_assignees ia
        WHERE ia.item_id = i.id AND ia.user_email = v_email
      )
      AND i.status IN ('blocked', 'review')
    ),
    count(*) FILTER (
      WHERE EXISTS (
        SELECT 1 FROM public.item_assignees ia
        WHERE ia.item_id = i.id AND ia.user_email = v_email
      )
      AND i.status = 'done'
    )
  INTO v_assigned, v_overdue, v_due_today, v_unassigned, v_todo, v_doing, v_stuck, v_done
  FROM public.items i
  WHERE i.tenant_id = p_tenant_id
    AND i.type = 'task'
    AND i.archived_at IS NULL;

  RETURN jsonb_build_object(
    'tenant_id', p_tenant_id,
    'assigned_to_me', v_assigned,
    'overdue_count', v_overdue,
    'due_today_count', v_due_today,
    'unassigned_count', v_unassigned,
    'my_todo', v_todo,
    'my_doing', v_doing,
    'my_stuck', v_stuck,
    'my_done', v_done
  );
END;
$$;


ALTER FUNCTION "public"."get_tasks_dashboard_metrics"("p_tenant_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_tenant_cash_in_report"("p_tenant_id" bigint, "p_start_date" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_end_date" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  v_books_id bigint;
  v_cash_in numeric(18,4) := 0.0000;
  v_count integer := 0;
  v_by_method jsonb;
  v_entries jsonb;
begin
  if p_tenant_id is null then
    raise exception 'Tenant ID is required';
  end if;

  select coalesce(t.parent_id, t.id)
  into v_books_id
  from public.tenants t
  where t.id = p_tenant_id;

  if v_books_id is null then
    raise exception 'Tenant not found';
  end if;

  if not (
    public.membership_has_module_action(p_tenant_id, 'universal_wallet', 'view')
    or public.membership_has_module_action(v_books_id, 'universal_wallet', 'view')
  ) then
    raise exception 'Not authorized';
  end if;

  with lined as (
    select
      l.id,
      l.amount,
      l.source_type,
      l.source_id,
      l.metadata,
      l.created_at,
      coalesce(
        nullif(trim(l.metadata->>'method'), ''),
        nullif(trim(gp.method), ''),
        'other'
      ) as method,
      nullif(l.metadata->>'label', '') as label,
      case
        when (l.metadata->>'invoice_id') ~ '^[0-9]+$' then (l.metadata->>'invoice_id')::bigint
        else null
      end as invoice_id
    from public.universal_wallet_ledger l
    left join public.global_payments gp
      on l.source_id ~ '^[0-9]+$'
     and gp.id = l.source_id::bigint
     and gp.tenant_id = v_books_id
    where l.tenant_id = v_books_id
      and l.entity_type = 'tenant'
      and l.entity_id = v_books_id
      and l.type = 'credit'
      and coalesce(l.metadata->>'purpose', '') <> 'apply_store_credit'
      and (p_start_date is null or l.created_at >= p_start_date)
      and (p_end_date is null or l.created_at <= p_end_date)
  )
  select
    coalesce(sum(amount), 0.0000),
    count(*)::integer,
    coalesce(
      (
        select jsonb_agg(jsonb_build_object(
          'method', m.method,
          'amount', m.amt,
          'count', m.cnt
        ) order by m.amt desc)
        from (
          select method, sum(amount) as amt, count(*)::integer as cnt
          from lined
          group by method
        ) m
      ),
      '[]'::jsonb
    ),
    coalesce(
      (
        select jsonb_agg(jsonb_build_object(
          'id', e.id,
          'amount', e.amount,
          'method', e.method,
          'source_type', e.source_type,
          'source_id', e.source_id,
          'label', e.label,
          'invoice_id', e.invoice_id,
          'created_at', e.created_at
        ) order by e.created_at desc, e.id desc)
        from lined e
      ),
      '[]'::jsonb
    )
  into v_cash_in, v_count, v_by_method, v_entries
  from lined;

  return jsonb_build_object(
    'tenant_id', v_books_id,
    'start_date', p_start_date,
    'end_date', p_end_date,
    'cash_in_total', v_cash_in,
    'entry_count', v_count,
    'by_method', v_by_method,
    'entries', v_entries
  );
end;
$_$;


ALTER FUNCTION "public"."get_tenant_cash_in_report"("p_tenant_id" bigint, "p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_tenant_courier_cod_report"("p_tenant_id" bigint, "p_start_date" "date" DEFAULT NULL::"date", "p_end_date" "date" DEFAULT NULL::"date", "p_courier_service_id" "uuid" DEFAULT NULL::"uuid", "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 50, "p_skip_count" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_books_id bigint;
  v_totals jsonb;
  v_rows jsonb;
  v_orders jsonb := NULL;
  v_total_count bigint;
  v_page integer := greatest(coalesce(p_page, 1), 1);
  v_page_size integer := greatest(least(coalesce(p_page_size, 50), 200), 1);
  v_offset integer := (greatest(coalesce(p_page, 1), 1) - 1) * greatest(least(coalesce(p_page_size, 50), 200), 1);
  v_start_ts timestamptz := CASE WHEN p_start_date IS NULL THEN NULL ELSE p_start_date::timestamptz END;
  v_end_ts timestamptz := CASE WHEN p_end_date IS NULL THEN NULL ELSE (p_end_date + interval '1 day' - interval '1 microsecond') END;
BEGIN
  IF p_tenant_id IS NULL THEN RAISE EXCEPTION 'Tenant ID is required'; END IF;
  v_books_id := public.resolve_parent_tenant_id(p_tenant_id);
  IF NOT (
    public.membership_has_module_action(p_tenant_id, 'reporting_treasury', 'view')
    OR public.membership_has_module_action(v_books_id, 'reporting_treasury', 'view')
  ) THEN RAISE EXCEPTION 'Not authorized'; END IF;

  WITH delivered_orders AS (
    SELECT
      so.id AS order_id,
      so.order_no,
      coalesce(so.courier_awb_number, so.courier_tracking_number) AS awb,
      coalesce(so.cod_collect_amount, 0)::numeric(12,2) AS cod_collect_amount,
      so.courier_remittance_ref AS remittance_ref,
      so.delivered_at,
      so.courier_service_id,
      coalesce(cs.name, so.courier_name, 'Unassigned') AS courier_name,
      CASE WHEN so.courier_remittance_ref IS NOT NULL THEN coalesce(so.cod_collect_amount, 0) ELSE 0 END::numeric(12,2) AS remitted_amount,
      CASE WHEN so.courier_remittance_ref IS NULL THEN coalesce(so.cod_collect_amount, 0) ELSE 0 END::numeric(12,2) AS unremitted_amount
    FROM public.shop_orders so
    LEFT JOIN public.courier_services cs ON cs.id = so.courier_service_id
    WHERE public.resolve_parent_tenant_id(so.tenant_id) = v_books_id
      AND so.status = 'delivered'::public.shop_order_status
      AND so.shop_type_snapshot = 'dropship'::public.shop_type_enum
      AND coalesce(so.cod_collect_amount, 0) > 0
      AND (v_start_ts IS NULL OR so.delivered_at >= v_start_ts)
      AND (v_end_ts IS NULL OR so.delivered_at <= v_end_ts)
      AND (p_courier_service_id IS NULL OR so.courier_service_id = p_courier_service_id)
  ),
  courier_rows AS (
    SELECT
      courier_service_id,
      courier_name,
      round(coalesce(sum(cod_collect_amount), 0), 2) AS delivered_cod,
      round(coalesce(sum(remitted_amount), 0), 2) AS remitted,
      round(coalesce(sum(unremitted_amount), 0), 2) AS unremitted,
      round(coalesce(sum(remitted_amount), 0) - coalesce(sum(cod_collect_amount), 0), 2) AS short_over,
      count(*)::bigint AS order_count
    FROM delivered_orders
    GROUP BY courier_service_id, courier_name
  ),
  totals_calc AS (
    SELECT round(coalesce(sum(delivered_cod), 0), 2) AS delivered_cod,
      round(coalesce(sum(remitted), 0), 2) AS remitted,
      round(coalesce(sum(unremitted), 0), 2) AS unremitted,
      round(coalesce(sum(short_over), 0), 2) AS short_over,
      coalesce(sum(order_count), 0)::bigint AS order_count
    FROM courier_rows
  ),
  paged AS (
    SELECT * FROM courier_rows ORDER BY delivered_cod DESC, courier_name ASC OFFSET v_offset LIMIT v_page_size
  )
  SELECT (SELECT count(*) FROM courier_rows),
    (SELECT jsonb_build_object('delivered_cod', delivered_cod, 'remitted', remitted, 'unremitted', unremitted,
      'short_over', short_over, 'order_count', order_count) FROM totals_calc),
    coalesce((SELECT jsonb_agg(jsonb_build_object(
      'courier_service_id', courier_service_id, 'courier_name', courier_name,
      'delivered_cod', delivered_cod, 'remitted', remitted, 'unremitted', unremitted,
      'short_over', short_over, 'order_count', order_count
    ) ORDER BY delivered_cod DESC, courier_name ASC) FROM paged), '[]'::jsonb)
  INTO v_total_count, v_totals, v_rows;

  IF p_courier_service_id IS NOT NULL THEN
    SELECT coalesce(jsonb_agg(jsonb_build_object(
      'order_id', order_id, 'order_no', order_no, 'awb', awb,
      'cod_collect_amount', cod_collect_amount, 'remittance_ref', remittance_ref, 'delivered_at', delivered_at
    ) ORDER BY delivered_at DESC NULLS LAST, order_id DESC), '[]'::jsonb)
    INTO v_orders
    FROM delivered_orders;
  END IF;

  RETURN jsonb_build_object('totals', coalesce(v_totals, '{}'::jsonb), 'rows', coalesce(v_rows, '[]'::jsonb),
    'orders', v_orders, 'page', v_page, 'page_size', v_page_size,
    'total_count', CASE WHEN coalesce(p_skip_count, true) THEN NULL ELSE v_total_count END);
END;
$$;


ALTER FUNCTION "public"."get_tenant_courier_cod_report"("p_tenant_id" bigint, "p_start_date" "date", "p_end_date" "date", "p_courier_service_id" "uuid", "p_page" integer, "p_page_size" integer, "p_skip_count" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_tenant_details_by_membership"("p_tenant_id" bigint, "p_email" "text" DEFAULT NULL::"text", "p_role" "public"."app_role" DEFAULT NULL::"public"."app_role") RETURNS TABLE("id" bigint, "name" "text", "slug" "text", "public_domain" "text", "is_active" boolean, "parent_id" bigint, "preference" "jsonb", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select distinct
    t.id,
    t.name,
    t.slug,
    t.public_domain,
    t.is_active,
    t.parent_id,
    t.preference,
    t.created_at,
    t.updated_at
  from public.tenants t
  inner join public.memberships m
    on m.tenant_id = t.id
  where t.id = p_tenant_id
    and m.is_active = true
    and (
      p_email is null
      or lower(trim(m.email)) = lower(trim(p_email))
    )
    and (p_role is null or m.role = p_role)
  limit 1;
$$;


ALTER FUNCTION "public"."get_tenant_details_by_membership"("p_tenant_id" bigint, "p_email" "text", "p_role" "public"."app_role") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_tenant_invoice_book_report"("p_tenant_id" bigint, "p_start_date" "date" DEFAULT NULL::"date", "p_end_date" "date" DEFAULT NULL::"date", "p_search" "text" DEFAULT NULL::"text", "p_invoice_type" "text" DEFAULT NULL::"text", "p_payment_status" "text" DEFAULT NULL::"text", "p_issued_by_tenant_id" bigint DEFAULT NULL::bigint, "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 50, "p_skip_count" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_books_id bigint;
  v_totals jsonb;
  v_rows jsonb;
  v_total_count bigint;
  v_page integer := greatest(coalesce(p_page, 1), 1);
  v_page_size integer := greatest(least(coalesce(p_page_size, 50), 200), 1);
  v_offset integer := (greatest(coalesce(p_page, 1), 1) - 1) * greatest(least(coalesce(p_page_size, 50), 200), 1);
BEGIN
  IF p_tenant_id IS NULL THEN RAISE EXCEPTION 'Tenant ID is required'; END IF;
  v_books_id := public.resolve_parent_tenant_id(p_tenant_id);
  IF NOT (
    public.membership_has_module_action(p_tenant_id, 'reporting_treasury', 'view')
    OR public.membership_has_module_action(v_books_id, 'reporting_treasury', 'view')
  ) THEN RAISE EXCEPTION 'Not authorized'; END IF;

  WITH invoice_returned AS (
    SELECT sii.invoice_id, coalesce(sum(sii.return_quantity * sii.sell_price_amount), 0)::numeric(12,2) AS returned
    FROM public.sales_invoice_items sii GROUP BY sii.invoice_id
  ),
  invoice_payments_agg AS (
    SELECT ip.global_invoice_id AS invoice_id,
      coalesce(sum(CASE WHEN coalesce(gp.method, '') <> 'wallet_credit' THEN ip.amount ELSE 0 END), 0)::numeric(12,2) AS collected_cash,
      coalesce(sum(CASE WHEN gp.method = 'wallet_credit' THEN ip.amount ELSE 0 END), 0)::numeric(12,2) AS wallet_applied
    FROM public.invoice_payments ip
    JOIN public.global_payments gp ON gp.id = ip.payment_id
    WHERE ip.global_invoice_id IS NOT NULL GROUP BY ip.global_invoice_id
  ),
  base AS (
    SELECT
      si.id, si.invoice_no, si.invoice_date, si.invoice_type::text AS invoice_type,
      si.payment_status, si.billing_profile_id, si.due_amount,
      coalesce(nullif(trim(bp.name), ''), nullif(trim(si.recipient_name), ''), 'Unknown') AS customer_name,
      coalesce(child.name, parent.name) AS issued_by_name,
      round((si.total_amount + coalesce(ir.returned, 0)), 2) AS billed,
      round(coalesce(ir.returned, 0), 2) AS returned,
      round(coalesce(ipa.collected_cash, 0), 2) AS collected_cash,
      round(coalesce(ipa.wallet_applied, 0), 2) AS wallet_applied,
      round(coalesce(si.settlement_discount_amount, 0), 2) AS settlement,
      round(coalesce(si.due_amount, 0), 2) AS still_due
    FROM public.sales_invoices si
    LEFT JOIN public.billing_profiles bp ON bp.id = si.billing_profile_id
    LEFT JOIN public.tenants child ON child.id = si.issued_by_tenant_id
    LEFT JOIN public.tenants parent ON parent.id = si.parent_tenant_id
    LEFT JOIN invoice_returned ir ON ir.invoice_id = si.id
    LEFT JOIN invoice_payments_agg ipa ON ipa.invoice_id = si.id
    WHERE si.parent_tenant_id = v_books_id
      AND si.invoice_status = 'issued'::public.global_invoice_status
      AND (p_start_date IS NULL OR si.invoice_date >= p_start_date)
      AND (p_end_date IS NULL OR si.invoice_date <= p_end_date)
      AND (p_invoice_type IS NULL OR btrim(p_invoice_type) = '' OR si.invoice_type::text = p_invoice_type)
      AND (p_payment_status IS NULL OR btrim(p_payment_status) = '' OR si.payment_status = p_payment_status)
      AND (p_issued_by_tenant_id IS NULL OR si.issued_by_tenant_id = p_issued_by_tenant_id)
      AND (
        p_search IS NULL OR btrim(p_search) = ''
        OR si.invoice_no ILIKE ('%' || btrim(p_search) || '%')
        OR bp.name ILIKE ('%' || btrim(p_search) || '%')
        OR si.recipient_name ILIKE ('%' || btrim(p_search) || '%')
      )
  ),
  totals_calc AS (
    SELECT round(coalesce(sum(billed), 0), 2) AS billed, round(coalesce(sum(returned), 0), 2) AS returned,
      round(coalesce(sum(collected_cash), 0), 2) AS collected_cash, round(coalesce(sum(wallet_applied), 0), 2) AS wallet_applied,
      round(coalesce(sum(settlement), 0), 2) AS settlement, round(coalesce(sum(still_due), 0), 2) AS still_due,
      count(*)::bigint AS invoice_count FROM base
  ),
  paged AS (
    SELECT * FROM base ORDER BY invoice_date DESC, id DESC OFFSET v_offset LIMIT v_page_size
  )
  SELECT (SELECT count(*) FROM base),
    (SELECT jsonb_build_object('billed', billed, 'returned', returned, 'collected_cash', collected_cash,
      'wallet_applied', wallet_applied, 'settlement', settlement, 'still_due', still_due, 'invoice_count', invoice_count) FROM totals_calc),
    coalesce((SELECT jsonb_agg(jsonb_build_object(
      'id', id, 'invoice_no', invoice_no, 'invoice_date', invoice_date, 'invoice_type', invoice_type,
      'payment_status', payment_status, 'customer_name', customer_name, 'billing_profile_id', billing_profile_id,
      'issued_by_name', issued_by_name, 'billed', billed, 'returned', returned, 'collected_cash', collected_cash,
      'wallet_applied', wallet_applied, 'settlement', settlement, 'still_due', still_due
    ) ORDER BY invoice_date DESC, id DESC) FROM paged), '[]'::jsonb)
  INTO v_total_count, v_totals, v_rows;

  RETURN jsonb_build_object('totals', coalesce(v_totals, '{}'::jsonb), 'rows', coalesce(v_rows, '[]'::jsonb),
    'page', v_page, 'page_size', v_page_size,
    'total_count', CASE WHEN coalesce(p_skip_count, true) THEN NULL ELSE v_total_count END);
END;
$$;


ALTER FUNCTION "public"."get_tenant_invoice_book_report"("p_tenant_id" bigint, "p_start_date" "date", "p_end_date" "date", "p_search" "text", "p_invoice_type" "text", "p_payment_status" "text", "p_issued_by_tenant_id" bigint, "p_page" integer, "p_page_size" integer, "p_skip_count" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_tenant_invoice_profit_report"("p_tenant_id" bigint, "p_start_date" "date" DEFAULT NULL::"date", "p_end_date" "date" DEFAULT NULL::"date", "p_search" "text" DEFAULT NULL::"text", "p_issued_by_tenant_id" bigint DEFAULT NULL::bigint, "p_invoice_id" bigint DEFAULT NULL::bigint, "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 50, "p_skip_count" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_books_id bigint;
  v_totals jsonb;
  v_rows jsonb;
  v_lines jsonb := NULL;
  v_total_count bigint;
  v_page integer := greatest(coalesce(p_page, 1), 1);
  v_page_size integer := greatest(least(coalesce(p_page_size, 50), 200), 1);
  v_offset integer := (greatest(coalesce(p_page, 1), 1) - 1) * greatest(least(coalesce(p_page_size, 50), 200), 1);
BEGIN
  IF p_tenant_id IS NULL THEN RAISE EXCEPTION 'Tenant ID is required'; END IF;
  v_books_id := public.resolve_parent_tenant_id(p_tenant_id);
  IF NOT (
    public.membership_has_module_action(p_tenant_id, 'reporting_treasury', 'view')
    OR public.membership_has_module_action(v_books_id, 'reporting_treasury', 'view')
  ) THEN RAISE EXCEPTION 'Not authorized'; END IF;

  WITH line_metrics AS (
    SELECT
      sii.invoice_id,
      sii.id AS item_id,
      sii.name_snapshot AS name,
      sii.barcode_snapshot AS barcode,
      sii.quantity,
      sii.return_quantity,
      greatest(sii.quantity - sii.return_quantity, 0) AS net_qty,
      round(
        greatest(sii.quantity - sii.return_quantity, 0) * sii.sell_price_amount
        - coalesce(sii.line_discount_amount, 0) * (greatest(sii.quantity - sii.return_quantity, 0) / nullif(sii.quantity, 0)),
        2
      ) AS net_revenue,
      round(greatest(sii.quantity - sii.return_quantity, 0) * coalesce(sii.unit_cost_price, 0), 2) AS cogs
    FROM public.sales_invoice_items sii
    JOIN public.sales_invoices si ON si.id = sii.invoice_id
    WHERE si.parent_tenant_id = v_books_id
      AND si.invoice_status = 'issued'::public.global_invoice_status
      AND (p_invoice_id IS NULL OR si.id = p_invoice_id)
      AND (p_start_date IS NULL OR si.invoice_date >= p_start_date)
      AND (p_end_date IS NULL OR si.invoice_date <= p_end_date)
      AND (p_issued_by_tenant_id IS NULL OR si.issued_by_tenant_id = p_issued_by_tenant_id)
  ),
  invoice_metrics AS (
    SELECT
      si.id,
      si.invoice_no,
      si.invoice_date,
      coalesce(nullif(trim(bp.name), ''), nullif(trim(si.recipient_name), ''), 'Unknown') AS customer_name,
      round(coalesce(sum(lm.net_qty), 0), 3) AS net_qty,
      round(coalesce(sum(lm.net_revenue), 0), 2) AS net_revenue,
      round(coalesce(sum(lm.cogs), 0), 2) AS cogs,
      round(coalesce(sum(lm.net_revenue - lm.cogs), 0), 2) AS realized_gp
    FROM public.sales_invoices si
    LEFT JOIN public.billing_profiles bp ON bp.id = si.billing_profile_id
    LEFT JOIN line_metrics lm ON lm.invoice_id = si.id
    WHERE si.parent_tenant_id = v_books_id
      AND si.invoice_status = 'issued'::public.global_invoice_status
      AND (p_invoice_id IS NULL OR si.id = p_invoice_id)
      AND (p_start_date IS NULL OR si.invoice_date >= p_start_date)
      AND (p_end_date IS NULL OR si.invoice_date <= p_end_date)
      AND (p_issued_by_tenant_id IS NULL OR si.issued_by_tenant_id = p_issued_by_tenant_id)
      AND (
        p_search IS NULL OR btrim(p_search) = ''
        OR si.invoice_no ILIKE ('%' || btrim(p_search) || '%')
        OR bp.name ILIKE ('%' || btrim(p_search) || '%')
        OR si.recipient_name ILIKE ('%' || btrim(p_search) || '%')
      )
    GROUP BY si.id, si.invoice_no, si.invoice_date, bp.name, si.recipient_name
  ),
  enriched AS (
    SELECT *,
      CASE WHEN net_revenue > 0 THEN round((realized_gp / net_revenue) * 100, 2) ELSE 0 END AS gp_margin_pct
    FROM invoice_metrics
  ),
  totals_calc AS (
    SELECT round(coalesce(sum(net_qty), 0), 3) AS net_sold_qty,
      round(coalesce(sum(net_revenue), 0), 2) AS net_revenue,
      round(coalesce(sum(cogs), 0), 2) AS cogs,
      round(coalesce(sum(realized_gp), 0), 2) AS realized_gp,
      CASE WHEN coalesce(sum(net_revenue), 0) > 0
        THEN round((coalesce(sum(realized_gp), 0) / coalesce(sum(net_revenue), 0)) * 100, 2) ELSE 0 END AS gp_margin_pct,
      count(*)::bigint AS invoice_count
    FROM enriched
  ),
  paged AS (
    SELECT * FROM enriched ORDER BY invoice_date DESC, id DESC OFFSET v_offset LIMIT v_page_size
  )
  SELECT (SELECT count(*) FROM enriched),
    (SELECT jsonb_build_object('net_sold_qty', net_sold_qty, 'net_revenue', net_revenue, 'cogs', cogs,
      'realized_gp', realized_gp, 'gp_margin_pct', gp_margin_pct, 'invoice_count', invoice_count) FROM totals_calc),
    coalesce((SELECT jsonb_agg(jsonb_build_object(
      'id', id, 'invoice_no', invoice_no, 'invoice_date', invoice_date, 'customer_name', customer_name,
      'net_qty', net_qty, 'net_revenue', net_revenue, 'cogs', cogs, 'realized_gp', realized_gp, 'gp_margin_pct', gp_margin_pct
    ) ORDER BY invoice_date DESC, id DESC) FROM paged), '[]'::jsonb)
  INTO v_total_count, v_totals, v_rows;

  IF p_invoice_id IS NOT NULL THEN
    SELECT coalesce(jsonb_agg(jsonb_build_object(
      'item_id', lm.item_id, 'name', lm.name, 'barcode', lm.barcode,
      'quantity', lm.quantity, 'return_quantity', lm.return_quantity, 'net_qty', lm.net_qty,
      'sell_price_amount', round(lm.net_revenue / nullif(lm.net_qty, 0), 2),
      'unit_cost_price', round(lm.cogs / nullif(lm.net_qty, 0), 2),
      'net_revenue', lm.net_revenue, 'cogs', lm.cogs, 'line_gp', round(lm.net_revenue - lm.cogs, 2)
    ) ORDER BY lm.item_id), '[]'::jsonb)
    INTO v_lines
    FROM line_metrics lm
    WHERE lm.invoice_id = p_invoice_id;
  END IF;

  RETURN jsonb_build_object(
    'totals', coalesce(v_totals, '{}'::jsonb),
    'rows', coalesce(v_rows, '[]'::jsonb),
    'lines', v_lines,
    'page', v_page,
    'page_size', v_page_size,
    'total_count', CASE WHEN coalesce(p_skip_count, true) THEN NULL ELSE v_total_count END
  );
END;
$$;


ALTER FUNCTION "public"."get_tenant_invoice_profit_report"("p_tenant_id" bigint, "p_start_date" "date", "p_end_date" "date", "p_search" "text", "p_issued_by_tenant_id" bigint, "p_invoice_id" bigint, "p_page" integer, "p_page_size" integer, "p_skip_count" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_tenant_module_by_id"("p_id" bigint) RETURNS TABLE("id" bigint, "tenant_id" bigint, "module_key" "text", "is_active" boolean, "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    tm.id,
    tm.tenant_id,
    tm.module_key,
    tm.is_active,
    tm.created_at,
    tm.updated_at
  from public.tenant_modules tm
  where tm.id = p_id
    and public.can_view_tenant_modules(tm.tenant_id)
  limit 1;
$$;


ALTER FUNCTION "public"."get_tenant_module_by_id"("p_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_tenant_month_snapshot_report"("p_tenant_id" bigint, "p_month" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_books_id bigint;
  v_start date;
  v_end date;
  v_start_ts timestamptz;
  v_end_ts timestamptz;
  v_net_sales numeric(18,4) := 0;
  v_cogs numeric(18,4) := 0;
  v_gross_profit numeric(18,4) := 0;
  v_cash_collected numeric(18,4) := 0;
  v_ar_outstanding numeric(18,4) := 0;
  v_wallet_liability numeric(18,4) := 0;
  v_unsold_stock_value numeric(18,4) := 0;
BEGIN
  IF p_tenant_id IS NULL OR p_month IS NULL THEN
    RAISE EXCEPTION 'Tenant ID and month are required';
  END IF;

  v_books_id := public.resolve_parent_tenant_id(p_tenant_id);
  v_start := date_trunc('month', p_month)::date;
  v_end := (date_trunc('month', p_month) + interval '1 month' - interval '1 day')::date;
  v_start_ts := v_start::timestamptz;
  v_end_ts := (v_end + interval '1 day' - interval '1 microsecond');

  IF NOT (
    public.membership_has_module_action(p_tenant_id, 'reporting_treasury', 'view')
    OR public.membership_has_module_action(v_books_id, 'reporting_treasury', 'view')
  ) THEN RAISE EXCEPTION 'Not authorized'; END IF;

  WITH invoice_returned AS (
    SELECT sii.invoice_id, coalesce(sum(sii.return_quantity * sii.sell_price_amount), 0)::numeric(12,2) AS returned
    FROM public.sales_invoice_items sii GROUP BY sii.invoice_id
  ),
  month_invoices AS (
    SELECT si.id, si.total_amount, coalesce(ir.returned, 0) AS returned
    FROM public.sales_invoices si
    LEFT JOIN invoice_returned ir ON ir.invoice_id = si.id
    WHERE si.parent_tenant_id = v_books_id
      AND si.invoice_status = 'issued'::public.global_invoice_status
      AND si.invoice_date BETWEEN v_start AND v_end
  ),
  line_metrics AS (
    SELECT
      round(coalesce(sum(
        greatest(sii.quantity - sii.return_quantity, 0) * sii.sell_price_amount
        - coalesce(sii.line_discount_amount, 0) * (greatest(sii.quantity - sii.return_quantity, 0) / nullif(sii.quantity, 0))
      ), 0), 2) AS net_revenue,
      round(coalesce(sum(greatest(sii.quantity - sii.return_quantity, 0) * coalesce(sii.unit_cost_price, 0)), 0), 2) AS cogs
    FROM public.sales_invoice_items sii
    JOIN public.sales_invoices si ON si.id = sii.invoice_id
    WHERE si.parent_tenant_id = v_books_id
      AND si.invoice_status = 'issued'::public.global_invoice_status
      AND si.invoice_date BETWEEN v_start AND v_end
  )
  SELECT
    round(coalesce((SELECT sum(total_amount + returned) FROM month_invoices), 0)
      - coalesce((SELECT sum(returned) FROM month_invoices), 0), 2),
    round(coalesce((SELECT cogs FROM line_metrics), 0), 2)
  INTO v_net_sales, v_cogs;

  v_gross_profit := round(v_net_sales - v_cogs, 2);

  SELECT round(coalesce(sum(l.amount), 0), 2)
  INTO v_cash_collected
  FROM public.universal_wallet_ledger l
  WHERE l.tenant_id = v_books_id
    AND l.entity_type = 'tenant'
    AND l.entity_id = v_books_id
    AND l.type = 'credit'
    AND coalesce(l.metadata->>'purpose', '') <> 'apply_store_credit'
    AND l.created_at BETWEEN v_start_ts AND v_end_ts;

  SELECT round(coalesce(sum(si.due_amount), 0), 2)
  INTO v_ar_outstanding
  FROM public.sales_invoices si
  WHERE si.parent_tenant_id = v_books_id
    AND si.invoice_status = 'issued'::public.global_invoice_status
    AND si.invoice_type = 'wholesale'::public.global_invoice_type
    AND si.due_amount > 0;

  SELECT round(coalesce(sum(wa.available_balance), 0), 2)
  INTO v_wallet_liability
  FROM public.wallet_accounts wa
  WHERE wa.parent_tenant_id = v_books_id
    AND wa.entity_type = 'customer';

  SELECT round(coalesce(sum(inv.sellable_qty * coalesce(gsi.landed_cost_bdt, 0)), 0), 2)
  INTO v_unsold_stock_value
  FROM public.global_shipments s
  JOIN public.global_shipment_items gsi ON gsi.shipment_id = s.id
  LEFT JOIN LATERAL (
    SELECT coalesce(sum(CASE WHEN gs.availability = 'sellable' THEN gs.quantity ELSE 0 END), 0) AS sellable_qty
    FROM public.global_stocks gs
    WHERE gs.shipment_item_id = gsi.id
  ) inv ON true
  WHERE s.parent_tenant_id = v_books_id;

  RETURN jsonb_build_object(
    'tenant_id', v_books_id,
    'month', v_start,
    'start_date', v_start,
    'end_date', v_end,
    'kpis', jsonb_build_object(
      'net_sales', v_net_sales,
      'cogs', v_cogs,
      'gross_profit', v_gross_profit,
      'cash_collected', v_cash_collected,
      'ar_outstanding', v_ar_outstanding,
      'wallet_liability', v_wallet_liability,
      'unsold_stock_value', v_unsold_stock_value
    )
  );
END;
$$;


ALTER FUNCTION "public"."get_tenant_month_snapshot_report"("p_tenant_id" bigint, "p_month" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_tenant_permission_version"("p_tenant_id" bigint) RETURNS bigint
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_version bigint;
begin
  select version into v_version
  from public.tenant_permission_versions
  where tenant_id = p_tenant_id;
  
  return coalesce(v_version, 1);
end;
$$;


ALTER FUNCTION "public"."get_tenant_permission_version"("p_tenant_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_tenant_role_detail"("p_role_id" bigint) RETURNS json
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_role json;
begin
  select row_to_json(r) into v_role
  from (
    select id, tenant_id, scope, name, slug, is_system, is_admin, source_app_role, is_active, created_at, updated_at
    from public.tenant_roles
    where id = p_role_id
  ) r;
  
  if v_role is null then
    raise exception 'Role not found';
  end if;
  
  return v_role;
end;
$$;


ALTER FUNCTION "public"."get_tenant_role_detail"("p_role_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_tenant_shipment_profit_report"("p_tenant_id" bigint, "p_shipment_id" bigint DEFAULT NULL::bigint, "p_search" "text" DEFAULT NULL::"text", "p_start_date" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_end_date" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 20) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_books_id bigint;
  v_summary jsonb;
  v_rows jsonb;
  v_total_count integer := 0;
  v_page integer := greatest(coalesce(p_page, 1), 1);
  v_page_size integer := greatest(coalesce(p_page_size, 20), 1);
BEGIN
  IF p_tenant_id IS NULL THEN
    RAISE EXCEPTION 'Tenant ID is required';
  END IF;

  SELECT coalesce(t.parent_id, t.id)
  INTO v_books_id
  FROM public.tenants t
  WHERE t.id = p_tenant_id;

  IF v_books_id IS NULL THEN
    RAISE EXCEPTION 'Tenant not found';
  END IF;

  IF NOT (
    public.membership_has_module_action(p_tenant_id, 'reporting_treasury', 'view')
    OR public.membership_has_module_action(v_books_id, 'reporting_treasury', 'view')
    OR public.membership_has_module_action(p_tenant_id, 'global_shipment', 'view')
    OR public.membership_has_module_action(v_books_id, 'global_shipment', 'view')
  ) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  WITH shipment_metrics AS (
    SELECT
      s.id AS shipment_id,
      s.name AS shipment_name,
      s.tenant_shipment_id::text AS shipment_code,
      s.status AS shipment_status,
      s.created_at,
      s.shipment_cost_currency_id AS currency_id,
      
      -- Inbound Quantities & Landed Cost
      coalesce(sum(coalesce(gsi.received_quantity, gsi.ordered_quantity, 0)), 0)::int AS inbound_quantity,
      coalesce(sum(coalesce(gsi.received_quantity, gsi.ordered_quantity, 0) * coalesce(gsi.landed_cost_bdt, 0)), 0)::numeric(18,4) AS total_landed_cost,
      
      -- Sales & Returns from Issued Sales Invoices (invoice_status = 'issued')
      coalesce(sum(sales.sold_qty), 0)::int AS sold_quantity,
      coalesce(sum(sales.returned_qty), 0)::int AS returned_quantity,
      coalesce(sum(sales.net_sold_qty), 0)::int AS net_sold_quantity,
      coalesce(sum(sales.sold_revenue), 0)::numeric(18,4) AS gross_sold_revenue,
      coalesce(sum(sales.cogs), 0)::numeric(18,4) AS cogs_amount,
      coalesce(sum(sales.sold_revenue - sales.cogs), 0)::numeric(18,4) AS realized_gross_profit,
      
      -- Inventory Valuation & Damage
      coalesce(sum(inv.sellable_qty), 0)::int AS sellable_stock_qty,
      coalesce(sum(inv.held_qty), 0)::int AS held_stock_qty,
      coalesce(sum(inv.unsellable_qty), 0)::int AS damaged_stock_qty,
      coalesce(sum(inv.sellable_qty * coalesce(gsi.landed_cost_bdt, 0)), 0)::numeric(18,4) AS unsold_stock_value,
      coalesce(sum(inv.unsellable_qty * coalesce(gsi.landed_cost_bdt, 0)), 0)::numeric(18,4) AS damage_loss_value,

      -- Item details array if single shipment requested
      CASE WHEN p_shipment_id IS NOT NULL THEN
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'item_id', gsi.id,
              'product_name', coalesce(gsi.name, 'Item #' || gsi.id),
              'barcode', gsi.barcode,
              'inbound_qty', coalesce(gsi.received_quantity, gsi.ordered_quantity, 0),
              'unit_cost_bdt', gsi.landed_cost_bdt,
              'total_cost_bdt', (coalesce(gsi.received_quantity, gsi.ordered_quantity, 0) * coalesce(gsi.landed_cost_bdt, 0)),
              'sold_qty', coalesce(sales.net_sold_qty, 0),
              'sold_revenue', coalesce(sales.sold_revenue, 0),
              'cogs', coalesce(sales.cogs, 0),
              'gross_profit', coalesce(sales.sold_revenue - sales.cogs, 0),
              'sellable_qty', coalesce(inv.sellable_qty, 0),
              'unsold_stock_value', coalesce(inv.sellable_qty * coalesce(gsi.landed_cost_bdt, 0), 0),
              'damaged_qty', coalesce(inv.unsellable_qty, 0),
              'damage_loss_value', coalesce(inv.unsellable_qty * coalesce(gsi.landed_cost_bdt, 0), 0)
            )
          ) FILTER (WHERE gsi.id IS NOT NULL),
          '[]'::jsonb
        )
      ELSE NULL END AS items

    FROM public.global_shipments s
    LEFT JOIN public.global_shipment_items gsi ON gsi.shipment_id = s.id
    
    -- Subquery for aggregated sales per shipment item
    LEFT JOIN LATERAL (
      SELECT
        coalesce(sum(gii.quantity), 0) AS sold_qty,
        coalesce(sum(gii.return_quantity), 0) AS returned_qty,
        coalesce(sum(gii.quantity - gii.return_quantity), 0) AS net_sold_qty,
        coalesce(sum((gii.quantity - gii.return_quantity) * gii.sell_price_amount - coalesce(gii.line_discount_amount, 0)), 0) AS sold_revenue,
        coalesce(sum((gii.quantity - gii.return_quantity) * coalesce(gii.unit_cost_price, gsi.landed_cost_bdt, 0)), 0) AS cogs
      FROM public.global_invoice_items gii
      JOIN public.sales_invoices si ON si.id = gii.invoice_id
      WHERE gii.shipment_item_id = gsi.id
        AND si.invoice_status = 'issued'
    ) sales ON true

    -- Subquery for inventory breakdown per shipment item
    LEFT JOIN LATERAL (
      SELECT
        coalesce(sum(CASE WHEN gs.availability = 'sellable' THEN gs.quantity ELSE 0 END), 0) AS sellable_qty,
        coalesce(sum(CASE WHEN gs.availability = 'held' THEN gs.quantity ELSE 0 END), 0) AS held_qty,
        coalesce(sum(CASE WHEN gs.availability = 'unsellable' THEN gs.quantity ELSE 0 END), 0) AS unsellable_qty
      FROM public.global_stocks gs
      WHERE gs.shipment_item_id = gsi.id
    ) inv ON true

    WHERE s.parent_tenant_id = v_books_id
      AND (p_shipment_id IS NULL OR s.id = p_shipment_id)
      AND (p_start_date IS NULL OR s.created_at >= p_start_date)
      AND (p_end_date IS NULL OR s.created_at <= p_end_date)
      AND (
        p_search IS NULL 
        OR btrim(p_search) = ''
        OR s.name ILIKE ('%' || btrim(p_search) || '%')
        OR (s.tenant_shipment_id IS NOT NULL AND s.tenant_shipment_id::text ILIKE ('%' || btrim(p_search) || '%'))
      )
    GROUP BY s.id, s.name, s.tenant_shipment_id, s.status, s.created_at, s.shipment_cost_currency_id
  ),
  counted AS (
    SELECT count(*) AS total_count FROM shipment_metrics
  ),
  summary_calc AS (
    SELECT
      coalesce(sum(inbound_quantity), 0)::int AS total_inbound_units,
      coalesce(sum(total_landed_cost), 0)::numeric(18,4) AS total_landed_cost,
      coalesce(sum(net_sold_quantity), 0)::int AS total_net_sold_units,
      coalesce(sum(gross_sold_revenue), 0)::numeric(18,4) AS total_gross_sold_revenue,
      coalesce(sum(cogs_amount), 0)::numeric(18,4) AS total_cogs,
      coalesce(sum(realized_gross_profit), 0)::numeric(18,4) AS total_realized_gross_profit,
      CASE
        WHEN coalesce(sum(gross_sold_revenue), 0) > 0
        THEN round((coalesce(sum(realized_gross_profit), 0) / sum(gross_sold_revenue) * 100)::numeric, 2)
        ELSE 0.00
      END AS overall_realized_gp_margin_pct,
      coalesce(sum(unsold_stock_value), 0)::numeric(18,4) AS total_unsold_stock_value,
      coalesce(sum(damage_loss_value), 0)::numeric(18,4) AS total_damage_loss_value,
      count(*)::int AS total_shipments_count
    FROM shipment_metrics
  ),
  paginated_rows AS (
    SELECT
      sm.*,
      CASE
        WHEN sm.gross_sold_revenue > 0
        THEN round((sm.realized_gross_profit / sm.gross_sold_revenue * 100)::numeric, 2)
        ELSE 0.00
      END AS realized_gp_margin_pct,
      CASE
        WHEN sm.inbound_quantity > 0
        THEN round((sm.net_sold_quantity::numeric / sm.inbound_quantity::numeric * 100)::numeric, 1)
        ELSE 0.0
      END AS batch_sold_pct
    FROM shipment_metrics sm
    ORDER BY sm.created_at DESC, sm.shipment_id DESC
    OFFSET (v_page - 1) * v_page_size
    LIMIT v_page_size
  )
  SELECT
    to_jsonb(s),
    coalesce((SELECT total_count FROM counted), 0),
    coalesce(jsonb_agg(to_jsonb(r)), '[]'::jsonb)
  INTO v_summary, v_total_count, v_rows
  FROM summary_calc s
  CROSS JOIN paginated_rows r
  GROUP BY to_jsonb(s);

  RETURN jsonb_build_object(
    'summary', coalesce(v_summary, jsonb_build_object(
      'total_inbound_units', 0,
      'total_landed_cost', 0,
      'total_net_sold_units', 0,
      'total_gross_sold_revenue', 0,
      'total_cogs', 0,
      'total_realized_gross_profit', 0,
      'overall_realized_gp_margin_pct', 0,
      'total_unsold_stock_value', 0,
      'total_damage_loss_value', 0,
      'total_shipments_count', 0
    )),
    'shipments', coalesce(v_rows, '[]'::jsonb),
    'meta', jsonb_build_object(
      'total', v_total_count,
      'page', v_page,
      'page_size', v_page_size,
      'total_pages', CASE WHEN v_total_count = 0 THEN 1 ELSE ceil(v_total_count::numeric / v_page_size::numeric)::int END
    )
  );
END;
$$;


ALTER FUNCTION "public"."get_tenant_shipment_profit_report"("p_tenant_id" bigint, "p_shipment_id" bigint, "p_search" "text", "p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone, "p_page" integer, "p_page_size" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_tenant_shipment_profit_report"("p_tenant_id" bigint, "p_shipment_id" bigint, "p_search" "text", "p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone, "p_page" integer, "p_page_size" integer) IS 'Consolidated batch shipment profit, landed cost, COGS, realized gross profit, remaining stock valuation and damage reporting.';



CREATE OR REPLACE FUNCTION "public"."get_tenant_wallet_liability_report"("p_tenant_id" bigint, "p_start_date" "date" DEFAULT NULL::"date", "p_end_date" "date" DEFAULT NULL::"date", "p_search" "text" DEFAULT NULL::"text", "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 50, "p_skip_count" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_books_id bigint;
  v_totals jsonb;
  v_rows jsonb;
  v_total_count bigint;
  v_page integer := greatest(coalesce(p_page, 1), 1);
  v_page_size integer := greatest(least(coalesce(p_page_size, 50), 200), 1);
  v_offset integer := (greatest(coalesce(p_page, 1), 1) - 1) * greatest(least(coalesce(p_page_size, 50), 200), 1);
  v_start_ts timestamptz := CASE WHEN p_start_date IS NULL THEN NULL ELSE p_start_date::timestamptz END;
  v_end_ts timestamptz := CASE WHEN p_end_date IS NULL THEN NULL ELSE (p_end_date + interval '1 day' - interval '1 microsecond') END;
BEGIN
  IF p_tenant_id IS NULL THEN RAISE EXCEPTION 'Tenant ID is required'; END IF;
  v_books_id := public.resolve_parent_tenant_id(p_tenant_id);
  IF NOT (
    public.membership_has_module_action(p_tenant_id, 'reporting_treasury', 'view')
    OR public.membership_has_module_action(v_books_id, 'reporting_treasury', 'view')
  ) THEN RAISE EXCEPTION 'Not authorized'; END IF;

  WITH ledger_agg AS (
    SELECT
      l.entity_id AS billing_profile_id,
      round(coalesce(sum(CASE WHEN l.type = 'credit' THEN l.amount ELSE 0 END), 0), 4) AS credit_issued,
      round(coalesce(sum(CASE
        WHEN l.type = 'debit' AND coalesce(l.metadata->>'purpose', '') = 'apply_store_credit' THEN l.amount
        ELSE 0 END), 0), 4) AS credit_applied
    FROM public.universal_wallet_ledger l
    WHERE l.parent_tenant_id = v_books_id
      AND l.entity_type = 'customer'
      AND (v_start_ts IS NULL OR l.created_at >= v_start_ts)
      AND (v_end_ts IS NULL OR l.created_at <= v_end_ts)
    GROUP BY l.entity_id
  ),
  base AS (
    SELECT
      wa.entity_id AS billing_profile_id,
      bp.name,
      bp.phone,
      round(coalesce(la.credit_issued, 0), 2) AS credit_issued,
      round(coalesce(la.credit_applied, 0), 2) AS credit_applied,
      round(coalesce(wa.available_balance, 0), 2) AS outstanding
    FROM public.wallet_accounts wa
    JOIN public.billing_profiles bp ON bp.id = wa.entity_id
    LEFT JOIN ledger_agg la ON la.billing_profile_id = wa.entity_id
    WHERE wa.parent_tenant_id = v_books_id
      AND wa.entity_type = 'customer'
      AND (
        coalesce(wa.available_balance, 0) > 0
        OR coalesce(la.credit_issued, 0) > 0
        OR coalesce(la.credit_applied, 0) > 0
      )
      AND (
        p_search IS NULL OR btrim(p_search) = ''
        OR bp.name ILIKE ('%' || btrim(p_search) || '%')
        OR bp.phone ILIKE ('%' || btrim(p_search) || '%')
      )
  ),
  totals_calc AS (
    SELECT round(coalesce(sum(credit_issued), 0), 2) AS credit_issued,
      round(coalesce(sum(credit_applied), 0), 2) AS credit_applied,
      round(coalesce(sum(outstanding), 0), 2) AS outstanding,
      count(*)::bigint AS customer_count
    FROM base
  ),
  paged AS (
    SELECT * FROM base ORDER BY outstanding DESC, name ASC OFFSET v_offset LIMIT v_page_size
  )
  SELECT (SELECT count(*) FROM base),
    (SELECT jsonb_build_object('credit_issued', credit_issued, 'credit_applied', credit_applied,
      'outstanding', outstanding, 'customer_count', customer_count) FROM totals_calc),
    coalesce((SELECT jsonb_agg(jsonb_build_object(
      'billing_profile_id', billing_profile_id, 'name', name, 'phone', phone,
      'credit_issued', credit_issued, 'credit_applied', credit_applied, 'outstanding', outstanding
    ) ORDER BY outstanding DESC, name ASC) FROM paged), '[]'::jsonb)
  INTO v_total_count, v_totals, v_rows;

  RETURN jsonb_build_object('totals', coalesce(v_totals, '{}'::jsonb), 'rows', coalesce(v_rows, '[]'::jsonb),
    'page', v_page, 'page_size', v_page_size,
    'total_count', CASE WHEN coalesce(p_skip_count, true) THEN NULL ELSE v_total_count END);
END;
$$;


ALTER FUNCTION "public"."get_tenant_wallet_liability_report"("p_tenant_id" bigint, "p_start_date" "date", "p_end_date" "date", "p_search" "text", "p_page" integer, "p_page_size" integer, "p_skip_count" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_thrift_customer_sales_risk"("p_tenant_id" bigint, "p_phone" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_phone TEXT := public.normalize_thrift_phone(p_phone);
  v_customer_id BIGINT;
  v_rto_count BIGINT := 0;
  v_return_count BIGINT := 0;
  v_rtos JSONB := '[]'::jsonb;
  v_returns JSONB := '[]'::jsonb;
BEGIN
  IF NOT public.membership_has_module_action(p_tenant_id, 'thrift_sales', 'view') THEN
    RAISE EXCEPTION 'Get thrift customer sales risk requires thrift_sales view permission';
  END IF;

  IF v_phone = '' THEN
    RETURN jsonb_build_object(
      'customer_id', NULL,
      'rto_count', 0,
      'return_count', 0,
      'rtos', '[]'::jsonb,
      'returns', '[]'::jsonb
    );
  END IF;

  SELECT c.id
  INTO v_customer_id
  FROM public.thrift_customers c
  WHERE c.tenant_id = p_tenant_id
    AND c.phone_normalized = v_phone
  LIMIT 1;

  SELECT count(*)
  INTO v_rto_count
  FROM public.thrift_sales_invoices inv
  WHERE inv.tenant_id = p_tenant_id
    AND inv.close_reason = 'RTO'
    AND (
      (v_customer_id IS NOT NULL AND inv.customer_id = v_customer_id)
      OR public.normalize_thrift_phone(inv.customer_phone) = v_phone
    );

  SELECT coalesce(jsonb_agg(row_data ORDER BY sort_at DESC, sort_id DESC), '[]'::jsonb)
  INTO v_rtos
  FROM (
    SELECT
      jsonb_build_object(
        'kind', 'RTO',
        'invoice_id', inv.id,
        'invoice_number', inv.invoice_number,
        'at', COALESCE(inv.reverted_at, inv.economics_closed_at, inv.updated_at),
        'total_invoice_amount', inv.total_invoice_amount
      ) AS row_data,
      COALESCE(inv.reverted_at, inv.economics_closed_at, inv.updated_at) AS sort_at,
      inv.id AS sort_id
    FROM public.thrift_sales_invoices inv
    WHERE inv.tenant_id = p_tenant_id
      AND inv.close_reason = 'RTO'
      AND (
        (v_customer_id IS NOT NULL AND inv.customer_id = v_customer_id)
        OR public.normalize_thrift_phone(inv.customer_phone) = v_phone
      )
    ORDER BY sort_at DESC, sort_id DESC
    LIMIT 20
  ) t;

  SELECT count(*)
  INTO v_return_count
  FROM public.thrift_sales_returns r
  JOIN public.thrift_sales_invoices inv
    ON inv.id = r.invoice_id
   AND inv.tenant_id = r.tenant_id
  WHERE r.tenant_id = p_tenant_id
    AND (
      (v_customer_id IS NOT NULL AND inv.customer_id = v_customer_id)
      OR public.normalize_thrift_phone(inv.customer_phone) = v_phone
    );

  SELECT coalesce(jsonb_agg(row_data ORDER BY sort_at DESC, sort_id DESC), '[]'::jsonb)
  INTO v_returns
  FROM (
    SELECT
      jsonb_build_object(
        'kind', 'CUSTOMER_RETURN',
        'return_id', r.id,
        'return_number', r.return_number,
        'invoice_id', r.invoice_id,
        'invoice_number', inv.invoice_number,
        'at', r.created_at,
        'refund_amount', r.refund_amount,
        'line_count', (
          SELECT count(*)::INT
          FROM public.thrift_sales_return_items ri
          WHERE ri.return_id = r.id
        ),
        'has_damaged', EXISTS (
          SELECT 1
          FROM public.thrift_sales_return_items ri
          WHERE ri.return_id = r.id
            AND ri.condition = 'DAMAGED'
        )
      ) AS row_data,
      r.created_at AS sort_at,
      r.id AS sort_id
    FROM public.thrift_sales_returns r
    JOIN public.thrift_sales_invoices inv
      ON inv.id = r.invoice_id
     AND inv.tenant_id = r.tenant_id
    WHERE r.tenant_id = p_tenant_id
      AND (
        (v_customer_id IS NOT NULL AND inv.customer_id = v_customer_id)
        OR public.normalize_thrift_phone(inv.customer_phone) = v_phone
      )
    ORDER BY sort_at DESC, sort_id DESC
    LIMIT 20
  ) t;

  RETURN jsonb_build_object(
    'customer_id', v_customer_id,
    'rto_count', v_rto_count,
    'return_count', v_return_count,
    'rtos', v_rtos,
    'returns', v_returns
  );
END;
$$;


ALTER FUNCTION "public"."get_thrift_customer_sales_risk"("p_tenant_id" bigint, "p_phone" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_thrift_customer_sales_risk"("p_tenant_id" bigint, "p_phone" "text") IS 'Customer RTO + post-pay return history by phone for create-sale risk panel. Separate lists, dated DESC, max 20 each.';



CREATE OR REPLACE FUNCTION "public"."get_thrift_dashboard_metrics"("p_tenant_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_items_added_today BIGINT;
  v_total_items BIGINT;
  v_available_items BIGINT;
  v_sold_items BIGINT;
  v_cod_pending_count BIGINT;
  v_cod_expected_total NUMERIC(14,2);
  v_active_invoices_today BIGINT;
BEGIN
  IF NOT public.membership_has_module_action(p_tenant_id, 'thrift_reports', 'view') THEN
    RAISE EXCEPTION 'Thrift dashboard metrics require thrift_reports view permission';
  END IF;

  SELECT COUNT(*)
  INTO v_items_added_today
  FROM public.thrift_stocks
  WHERE tenant_id = p_tenant_id
    AND deleted_at IS NULL
    AND created_at >= date_trunc('day', NOW());

  SELECT COUNT(*)
  INTO v_total_items
  FROM public.thrift_stocks
  WHERE tenant_id = p_tenant_id
    AND deleted_at IS NULL;

  SELECT COUNT(*)
  INTO v_available_items
  FROM public.thrift_stocks
  WHERE tenant_id = p_tenant_id
    AND deleted_at IS NULL
    AND status = 'AVAILABLE'::public.thrift_stock_status;

  SELECT COUNT(*)
  INTO v_sold_items
  FROM public.thrift_stocks
  WHERE tenant_id = p_tenant_id
    AND deleted_at IS NULL
    AND status = 'SOLD'::public.thrift_stock_status;

  SELECT
    COUNT(*)::BIGINT,
    COALESCE(SUM(COALESCE(inv.cod_expected, 0)), 0)::NUMERIC(14,2)
  INTO v_cod_pending_count, v_cod_expected_total
  FROM public.thrift_sales_invoices inv
  WHERE inv.tenant_id = p_tenant_id
    AND COALESCE(inv.status, 'ACTIVE') = 'ACTIVE'
    AND inv.payment_status = 'COD_PENDING';

  SELECT COUNT(*)
  INTO v_active_invoices_today
  FROM public.thrift_sales_invoices inv
  WHERE inv.tenant_id = p_tenant_id
    AND COALESCE(inv.status, 'ACTIVE') = 'ACTIVE'
    AND inv.date >= date_trunc('day', NOW());

  RETURN jsonb_build_object(
    'items_added_today', v_items_added_today,
    'total_items', v_total_items,
    'available_items', v_available_items,
    'sold_items', v_sold_items,
    'cod_pending_count', v_cod_pending_count,
    'cod_expected_total', v_cod_expected_total,
    'active_invoices_today', v_active_invoices_today
  );
END;
$$;


ALTER FUNCTION "public"."get_thrift_dashboard_metrics"("p_tenant_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_thrift_sales_report"("p_tenant_id" bigint, "p_date_from" timestamp with time zone, "p_date_to" timestamp with time zone, "p_sale_channel" "text" DEFAULT NULL::"text", "p_outcome" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_channel TEXT;
  v_outcome TEXT;
  v_date_from DATE;
  v_date_to DATE;
  v_summary JSONB;
  v_by_channel JSONB;
  v_by_outcome JSONB;
  v_cod_outstanding JSONB;
BEGIN
  IF NOT public.membership_has_module_action(p_tenant_id, 'thrift_reports', 'view') THEN
    RAISE EXCEPTION 'Thrift sales report requires thrift_reports view permission';
  END IF;

  IF p_date_from IS NULL OR p_date_to IS NULL THEN
    RAISE EXCEPTION 'p_date_from and p_date_to are required';
  END IF;

  IF p_date_from > p_date_to THEN
    RAISE EXCEPTION 'p_date_from must be <= p_date_to';
  END IF;

  v_date_from := (p_date_from AT TIME ZONE 'UTC')::DATE;
  v_date_to := (p_date_to AT TIME ZONE 'UTC')::DATE;

  v_channel := NULLIF(trim(COALESCE(p_sale_channel, '')), '');
  IF v_channel IS NOT NULL AND v_channel NOT IN ('IN_STORE', 'ONLINE') THEN
    RAISE EXCEPTION 'Invalid sale_channel: % (expected IN_STORE, ONLINE, or null)', v_channel;
  END IF;

  v_outcome := NULLIF(upper(trim(COALESCE(p_outcome, ''))), '');
  IF v_outcome IS NOT NULL AND v_outcome NOT IN ('DELIVERED', 'RTO', 'CUSTOMER_RETURN') THEN
    RAISE EXCEPTION 'Invalid outcome: % (expected DELIVERED, RTO, CUSTOMER_RETURN, or null)', p_outcome;
  END IF;

  WITH pnl AS (
    SELECT
      p.invoice_id,
      p.outcome,
      p.quantity,
      p.sell_amount,
      p.allocated_shop_delivery,
      p.allocated_shop_cod_fee,
      p.allocated_shop_packing,
      p.allocated_return_courier,
      p.allocated_fees_total,
      p.cogs_is_loss,
      COALESCE(inv.sale_channel, 'IN_STORE') AS sale_channel,
      CASE
        WHEN p.sell_amount > 0 OR p.cogs_is_loss THEN
          ROUND(
            ROUND(COALESCE(public.compute_thrift_landed_unit_cost(p.stock_id), 0.00), 2)
            * p.quantity,
            2
          )
        ELSE 0.00
      END AS cogs
    FROM public.thrift_sales_pnl_lines p
    JOIN public.thrift_sales_invoices inv
      ON inv.id = p.invoice_id
     AND inv.tenant_id = p.tenant_id
    WHERE p.tenant_id = p_tenant_id
      AND p.event_date >= v_date_from
      AND p.event_date <= v_date_to
      AND (v_channel IS NULL OR COALESCE(inv.sale_channel, 'IN_STORE') = v_channel)
      AND (v_outcome IS NULL OR p.outcome = v_outcome)
  ),
  summary_agg AS (
    SELECT
      COUNT(DISTINCT invoice_id)::BIGINT AS invoice_count,
      COALESCE(SUM(quantity), 0)::BIGINT AS units_sold,
      COALESCE(SUM(sell_amount), 0)::NUMERIC(14,2) AS net_revenue,
      COALESCE(SUM(cogs), 0)::NUMERIC(14,2) AS cogs,
      COALESCE(SUM(allocated_shop_delivery), 0)::NUMERIC(14,2) AS allocated_shop_delivery,
      COALESCE(SUM(allocated_shop_cod_fee), 0)::NUMERIC(14,2) AS allocated_shop_cod_fee,
      COALESCE(SUM(allocated_shop_packing), 0)::NUMERIC(14,2) AS allocated_shop_packing,
      COALESCE(SUM(allocated_return_courier), 0)::NUMERIC(14,2) AS allocated_return_courier,
      COALESCE(SUM(allocated_fees_total), 0)::NUMERIC(14,2) AS allocated_fees_total,
      COALESCE(SUM(sell_amount - cogs - allocated_fees_total), 0)::NUMERIC(14,2) AS net_profit,
      COUNT(*) FILTER (WHERE outcome = 'RTO')::BIGINT AS rto_count,
      COALESCE(SUM(allocated_fees_total) FILTER (WHERE outcome = 'RTO'), 0)::NUMERIC(14,2)
        AS rto_amount,
      COUNT(*) FILTER (WHERE outcome = 'CUSTOMER_RETURN')::BIGINT AS customer_return_count,
      COALESCE(
        SUM(allocated_fees_total) FILTER (WHERE outcome = 'CUSTOMER_RETURN'),
        0
      )::NUMERIC(14,2) AS customer_return_amount,
      -- BC aliases used by existing UI
      COALESCE(SUM(sell_amount - cogs), 0)::NUMERIC(14,2) AS line_profit,
      COALESCE(SUM(allocated_fees_total), 0)::NUMERIC(14,2) AS total_fees,
      COALESCE(SUM(sell_amount - cogs - allocated_fees_total), 0)::NUMERIC(14,2)
        AS net_after_fees,
      COUNT(*) FILTER (WHERE outcome IN ('RTO', 'CUSTOMER_RETURN'))::BIGINT AS refund_count,
      COALESCE(
        SUM(allocated_fees_total) FILTER (WHERE outcome IN ('RTO', 'CUSTOMER_RETURN')),
        0
      )::NUMERIC(14,2) AS refund_amount
    FROM pnl
  ),
  channel_rows AS (
    SELECT
      sale_channel,
      COUNT(DISTINCT invoice_id)::BIGINT AS invoice_count,
      COALESCE(SUM(quantity), 0)::BIGINT AS units_sold,
      COALESCE(SUM(sell_amount), 0)::NUMERIC(14,2) AS net_revenue,
      COALESCE(SUM(cogs), 0)::NUMERIC(14,2) AS cogs,
      COALESCE(SUM(allocated_fees_total), 0)::NUMERIC(14,2) AS total_fees,
      COALESCE(SUM(sell_amount - cogs), 0)::NUMERIC(14,2) AS line_profit,
      COALESCE(SUM(sell_amount - cogs - allocated_fees_total), 0)::NUMERIC(14,2)
        AS net_after_fees,
      COUNT(*) FILTER (WHERE outcome = 'RTO')::BIGINT AS rto_count,
      COALESCE(SUM(allocated_fees_total) FILTER (WHERE outcome = 'RTO'), 0)::NUMERIC(14,2)
        AS rto_amount,
      COUNT(*) FILTER (WHERE outcome = 'CUSTOMER_RETURN')::BIGINT AS customer_return_count,
      COALESCE(
        SUM(allocated_fees_total) FILTER (WHERE outcome = 'CUSTOMER_RETURN'),
        0
      )::NUMERIC(14,2) AS customer_return_amount,
      COUNT(*) FILTER (WHERE outcome IN ('RTO', 'CUSTOMER_RETURN'))::BIGINT AS refund_count,
      COALESCE(
        SUM(allocated_fees_total) FILTER (WHERE outcome IN ('RTO', 'CUSTOMER_RETURN')),
        0
      )::NUMERIC(14,2) AS refund_amount
    FROM pnl
    GROUP BY sale_channel
  ),
  outcome_rows AS (
    SELECT
      outcome,
      COUNT(DISTINCT invoice_id)::BIGINT AS invoice_count,
      COALESCE(SUM(quantity), 0)::BIGINT AS units,
      COALESCE(SUM(sell_amount), 0)::NUMERIC(14,2) AS net_revenue,
      COALESCE(SUM(cogs), 0)::NUMERIC(14,2) AS cogs,
      COALESCE(SUM(allocated_fees_total), 0)::NUMERIC(14,2) AS allocated_fees_total,
      COALESCE(SUM(sell_amount - cogs - allocated_fees_total), 0)::NUMERIC(14,2) AS net_profit
    FROM pnl
    GROUP BY outcome
  )
  SELECT
    jsonb_build_object(
      'invoice_count', s.invoice_count,
      'units_sold', s.units_sold,
      'units', s.units_sold,
      'net_revenue', s.net_revenue,
      'cogs', s.cogs,
      'line_profit', s.line_profit,
      'allocated_shop_delivery', s.allocated_shop_delivery,
      'allocated_shop_cod_fee', s.allocated_shop_cod_fee,
      'allocated_shop_packing', s.allocated_shop_packing,
      'allocated_return_courier', s.allocated_return_courier,
      'allocated_fees_total', s.allocated_fees_total,
      'net_profit', s.net_profit,
      'courier_cod_amount', s.allocated_shop_delivery + s.allocated_shop_cod_fee,
      'other_expense_amount', s.allocated_shop_packing + s.allocated_return_courier,
      'total_fees', s.total_fees,
      'net_after_fees', s.net_after_fees,
      'refund_count', s.refund_count,
      'refund_amount', s.refund_amount,
      'rto_count', s.rto_count,
      'rto_amount', s.rto_amount,
      'customer_return_count', s.customer_return_count,
      'customer_return_amount', s.customer_return_amount
    ),
    COALESCE(
      (
        SELECT jsonb_agg(
          jsonb_build_object(
            'sale_channel', c.sale_channel,
            'invoice_count', c.invoice_count,
            'units_sold', c.units_sold,
            'net_revenue', c.net_revenue,
            'cogs', c.cogs,
            'line_profit', c.line_profit,
            'courier_cod_amount', c.total_fees,
            'other_expense_amount', 0::NUMERIC(14,2),
            'total_fees', c.total_fees,
            'net_after_fees', c.net_after_fees,
            'refund_count', c.refund_count,
            'refund_amount', c.refund_amount,
            'rto_count', c.rto_count,
            'rto_amount', c.rto_amount,
            'customer_return_count', c.customer_return_count,
            'customer_return_amount', c.customer_return_amount
          )
          ORDER BY c.sale_channel
        )
        FROM channel_rows c
      ),
      '[]'::jsonb
    ),
    COALESCE(
      (
        SELECT jsonb_agg(
          jsonb_build_object(
            'outcome', o.outcome,
            'invoice_count', o.invoice_count,
            'units', o.units,
            'net_revenue', o.net_revenue,
            'cogs', o.cogs,
            'allocated_fees_total', o.allocated_fees_total,
            'net_profit', o.net_profit
          )
          ORDER BY o.outcome
        )
        FROM outcome_rows o
      ),
      '[]'::jsonb
    )
  INTO v_summary, v_by_channel, v_by_outcome
  FROM summary_agg s;

  SELECT jsonb_build_object(
    'invoice_count', COUNT(*)::BIGINT,
    'cod_expected_total', COALESCE(SUM(COALESCE(inv.cod_expected, 0)), 0)::NUMERIC(14,2),
    'cod_remitted_total', COALESCE(SUM(COALESCE(inv.cod_remitted_amount, 0)), 0)::NUMERIC(14,2)
  )
  INTO v_cod_outstanding
  FROM public.thrift_sales_invoices inv
  WHERE inv.tenant_id = p_tenant_id
    AND COALESCE(inv.status, 'ACTIVE') IN ('ACTIVE', 'PARTIALLY_RETURNED')
    AND inv.payment_status = 'COD_PENDING';

  RETURN jsonb_build_object(
    'date_from', p_date_from,
    'date_to', p_date_to,
    'sale_channel', v_channel,
    'outcome', v_outcome,
    'summary', COALESCE(v_summary, '{}'::jsonb),
    'by_channel', COALESCE(v_by_channel, '[]'::jsonb),
    'by_outcome', COALESCE(v_by_outcome, '[]'::jsonb),
    'cod_outstanding', COALESCE(v_cod_outstanding, jsonb_build_object(
      'invoice_count', 0,
      'cod_expected_total', 0,
      'cod_remitted_total', 0
    ))
  );
END;
$$;


ALTER FUNCTION "public"."get_thrift_sales_report"("p_tenant_id" bigint, "p_date_from" timestamp with time zone, "p_date_to" timestamp with time zone, "p_sale_channel" "text", "p_outcome" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_thrift_sales_report"("p_tenant_id" bigint, "p_date_from" timestamp with time zone, "p_date_to" timestamp with time zone, "p_sale_channel" "text", "p_outcome" "text") IS 'Period P&L from thrift_sales_pnl_lines + live COGS (cogs_is_loss). Includes RTO and customer-return cards.';



CREATE OR REPLACE FUNCTION "public"."get_thrift_shipment_sales_report"("p_tenant_id" bigint, "p_shipment_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_shipment JSONB;
  v_summary JSONB;
  v_lines JSONB;
  v_by_outcome JSONB;
BEGIN
  IF NOT public.membership_has_module_action(p_tenant_id, 'thrift_reports', 'view') THEN
    RAISE EXCEPTION 'Thrift shipment report requires thrift_reports view permission';
  END IF;

  SELECT jsonb_build_object(
    'id', s.id,
    'name', s.name,
    'created_at', s.created_at,
    'updated_at', s.updated_at
  )
  INTO v_shipment
  FROM public.thrift_shipments s
  WHERE s.id = p_shipment_id
    AND s.tenant_id = p_tenant_id;

  IF v_shipment IS NULL THEN
    RAISE EXCEPTION 'Shipment % not found for tenant %', p_shipment_id, p_tenant_id;
  END IF;

  WITH pnl AS (
    SELECT
      p.id,
      p.invoice_id,
      p.invoice_item_id,
      p.stock_id,
      p.outcome,
      p.quantity,
      p.sell_amount,
      p.allocated_shop_delivery,
      p.allocated_shop_cod_fee,
      p.allocated_shop_packing,
      p.allocated_return_courier,
      p.allocated_fees_total,
      p.cogs_is_loss,
      p.event_at,
      p.event_date,
      ROUND(COALESCE(public.compute_thrift_landed_unit_cost(p.stock_id), 0.00), 2) AS landed_unit_cost,
      CASE
        WHEN p.sell_amount > 0 OR p.cogs_is_loss THEN
          ROUND(
            ROUND(COALESCE(public.compute_thrift_landed_unit_cost(p.stock_id), 0.00), 2)
            * p.quantity,
            2
          )
        ELSE 0.00
      END AS cogs,
      ROUND(
        p.sell_amount
        - CASE
            WHEN p.sell_amount > 0 OR p.cogs_is_loss THEN
              ROUND(
                ROUND(COALESCE(public.compute_thrift_landed_unit_cost(p.stock_id), 0.00), 2)
                * p.quantity,
                2
              )
            ELSE 0.00
          END
        - p.allocated_fees_total,
        2
      ) AS net_profit,
      inv.invoice_number,
      inv.date AS invoice_date,
      i.sell_price,
      i.discount_amount,
      i.final_price,
      st.name AS stock_name,
      st.barcode
    FROM public.thrift_sales_pnl_lines p
    JOIN public.thrift_sales_invoices inv
      ON inv.id = p.invoice_id
     AND inv.tenant_id = p.tenant_id
    LEFT JOIN public.thrift_sales_invoice_items i
      ON i.id = p.invoice_item_id
     AND i.tenant_id = p.tenant_id
    LEFT JOIN public.thrift_stocks st
      ON st.id = p.stock_id
     AND st.tenant_id = p.tenant_id
    WHERE p.tenant_id = p_tenant_id
      AND p.inbound_shipment_id = p_shipment_id
  ),
  summary AS (
    SELECT
      COALESCE(SUM(quantity) FILTER (WHERE outcome = 'DELIVERED'), 0)::BIGINT AS units_sold,
      COALESCE(SUM(quantity) FILTER (WHERE outcome = 'RTO'), 0)::BIGINT AS units_rto,
      COALESCE(SUM(quantity) FILTER (WHERE outcome = 'CUSTOMER_RETURN'), 0)::BIGINT AS units_returned,
      COALESCE(SUM(sell_amount), 0)::NUMERIC(14,2) AS net_revenue,
      COALESCE(SUM(sell_amount) FILTER (WHERE outcome = 'DELIVERED'), 0)::NUMERIC(14,2)
        AS delivered_revenue,
      COALESCE(SUM(cogs), 0)::NUMERIC(14,2) AS cogs,
      COALESCE(SUM(allocated_fees_total), 0)::NUMERIC(14,2) AS allocated_fees_total,
      COALESCE(SUM(net_profit), 0)::NUMERIC(14,2) AS net_profit,
      COALESCE(SUM(net_profit) FILTER (WHERE outcome = 'DELIVERED'), 0)::NUMERIC(14,2)
        AS delivered_net,
      COALESCE(
        SUM(allocated_fees_total) FILTER (WHERE outcome = 'RTO'),
        0
      )::NUMERIC(14,2) AS rto_fee_loss,
      COALESCE(
        SUM(allocated_fees_total) FILTER (WHERE outcome = 'CUSTOMER_RETURN'),
        0
      )::NUMERIC(14,2) AS return_fee_loss,
      COUNT(*) FILTER (WHERE outcome = 'DELIVERED')::BIGINT AS delivered_line_count,
      COUNT(*) FILTER (WHERE outcome = 'RTO')::BIGINT AS rto_line_count,
      COUNT(*) FILTER (WHERE outcome = 'CUSTOMER_RETURN')::BIGINT AS return_line_count,
      COALESCE(SUM(sell_price * quantity) FILTER (WHERE outcome = 'DELIVERED'), 0)::NUMERIC(14,2)
        AS gross_sales,
      COALESCE(SUM(discount_amount * quantity) FILTER (WHERE outcome = 'DELIVERED'), 0)::NUMERIC(14,2)
        AS discounts
    FROM pnl
  )
  SELECT jsonb_build_object(
    'units_sold', s.units_sold,
    'units_rto', s.units_rto,
    'units_returned', s.units_returned,
    'gross_sales', s.gross_sales,
    'discounts', s.discounts,
    'net_revenue', s.net_revenue,
    'delivered_revenue', s.delivered_revenue,
    'cogs', s.cogs,
    'allocated_fees_total', s.allocated_fees_total,
    'net_profit', s.net_profit,
    'delivered_net', s.delivered_net,
    'rto_fee_loss', s.rto_fee_loss,
    'return_fee_loss', s.return_fee_loss,
    'delivered_line_count', s.delivered_line_count,
    'rto_line_count', s.rto_line_count,
    'return_line_count', s.return_line_count,
    'margin_pct', CASE
      WHEN s.net_revenue > 0 THEN ROUND((s.net_profit / s.net_revenue) * 100, 2)
      ELSE 0::NUMERIC(8,2)
    END
  )
  INTO v_summary
  FROM summary s;

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'outcome', o.outcome,
        'line_count', o.line_count,
        'units', o.units,
        'net_revenue', o.net_revenue,
        'cogs', o.cogs,
        'allocated_fees_total', o.allocated_fees_total,
        'net_profit', o.net_profit
      )
      ORDER BY o.outcome
    ),
    '[]'::jsonb
  )
  INTO v_by_outcome
  FROM (
    SELECT
      p.outcome,
      COUNT(*)::BIGINT AS line_count,
      COALESCE(SUM(p.quantity), 0)::BIGINT AS units,
      COALESCE(SUM(p.sell_amount), 0)::NUMERIC(14,2) AS net_revenue,
      COALESCE(SUM(p.cogs), 0)::NUMERIC(14,2) AS cogs,
      COALESCE(SUM(p.allocated_fees_total), 0)::NUMERIC(14,2) AS allocated_fees_total,
      COALESCE(SUM(p.net_profit), 0)::NUMERIC(14,2) AS net_profit
    FROM (
      SELECT
        p2.outcome,
        p2.quantity,
        p2.sell_amount,
        p2.allocated_fees_total,
        CASE
          WHEN p2.sell_amount > 0 OR p2.cogs_is_loss THEN
            ROUND(
              ROUND(COALESCE(public.compute_thrift_landed_unit_cost(p2.stock_id), 0.00), 2)
              * p2.quantity,
              2
            )
          ELSE 0.00
        END AS cogs,
        ROUND(
          p2.sell_amount
          - CASE
              WHEN p2.sell_amount > 0 OR p2.cogs_is_loss THEN
                ROUND(
                  ROUND(COALESCE(public.compute_thrift_landed_unit_cost(p2.stock_id), 0.00), 2)
                  * p2.quantity,
                  2
                )
              ELSE 0.00
            END
          - p2.allocated_fees_total,
          2
        ) AS net_profit
      FROM public.thrift_sales_pnl_lines p2
      WHERE p2.tenant_id = p_tenant_id
        AND p2.inbound_shipment_id = p_shipment_id
    ) p
    GROUP BY p.outcome
  ) o;

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'id', x.id,
        'invoice_id', x.invoice_id,
        'invoice_item_id', x.invoice_item_id,
        'invoice_number', x.invoice_number,
        'invoice_date', x.invoice_date,
        'event_date', x.event_date,
        'outcome', x.outcome,
        'stock_id', x.stock_id,
        'stock_name', x.stock_name,
        'barcode', x.barcode,
        'quantity', x.quantity,
        'sell_price', COALESCE(x.sell_price, 0),
        'discount_amount', COALESCE(x.discount_amount, 0),
        'final_price', COALESCE(x.final_price, x.sell_amount),
        'sell_amount', x.sell_amount,
        'landed_unit_cost_at_sale', x.landed_unit_cost,
        'cogs', x.cogs,
        'cogs_is_loss', x.cogs_is_loss,
        'allocated_shop_delivery', x.allocated_shop_delivery,
        'allocated_shop_cod_fee', x.allocated_shop_cod_fee,
        'allocated_shop_packing', x.allocated_shop_packing,
        'allocated_return_courier', x.allocated_return_courier,
        'allocated_fees_total', x.allocated_fees_total,
        'net_profit', x.net_profit
      )
      ORDER BY x.event_at DESC NULLS LAST, x.id DESC
    ),
    '[]'::jsonb
  )
  INTO v_lines
  FROM (
    SELECT
      p.id,
      p.invoice_id,
      p.invoice_item_id,
      p.stock_id,
      p.outcome,
      p.quantity,
      p.sell_amount,
      p.allocated_shop_delivery,
      p.allocated_shop_cod_fee,
      p.allocated_shop_packing,
      p.allocated_return_courier,
      p.allocated_fees_total,
      p.cogs_is_loss,
      p.event_at,
      p.event_date,
      ROUND(COALESCE(public.compute_thrift_landed_unit_cost(p.stock_id), 0.00), 2) AS landed_unit_cost,
      CASE
        WHEN p.sell_amount > 0 OR p.cogs_is_loss THEN
          ROUND(
            ROUND(COALESCE(public.compute_thrift_landed_unit_cost(p.stock_id), 0.00), 2)
            * p.quantity,
            2
          )
        ELSE 0.00
      END AS cogs,
      ROUND(
        p.sell_amount
        - CASE
            WHEN p.sell_amount > 0 OR p.cogs_is_loss THEN
              ROUND(
                ROUND(COALESCE(public.compute_thrift_landed_unit_cost(p.stock_id), 0.00), 2)
                * p.quantity,
                2
              )
            ELSE 0.00
          END
        - p.allocated_fees_total,
        2
      ) AS net_profit,
      inv.invoice_number,
      inv.date AS invoice_date,
      i.sell_price,
      i.discount_amount,
      i.final_price,
      st.name AS stock_name,
      st.barcode
    FROM public.thrift_sales_pnl_lines p
    JOIN public.thrift_sales_invoices inv
      ON inv.id = p.invoice_id
     AND inv.tenant_id = p.tenant_id
    LEFT JOIN public.thrift_sales_invoice_items i
      ON i.id = p.invoice_item_id
     AND i.tenant_id = p.tenant_id
    LEFT JOIN public.thrift_stocks st
      ON st.id = p.stock_id
     AND st.tenant_id = p.tenant_id
    WHERE p.tenant_id = p_tenant_id
      AND p.inbound_shipment_id = p_shipment_id
  ) x;

  RETURN jsonb_build_object(
    'shipment', v_shipment,
    'summary', COALESCE(v_summary, '{}'::jsonb),
    'by_outcome', COALESCE(v_by_outcome, '[]'::jsonb),
    'lines', COALESCE(v_lines, '[]'::jsonb)
  );
END;
$$;


ALTER FUNCTION "public"."get_thrift_shipment_sales_report"("p_tenant_id" bigint, "p_shipment_id" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_thrift_shipment_sales_report"("p_tenant_id" bigint, "p_shipment_id" bigint) IS 'Inbound shipment P&L from thrift_sales_pnl_lines + live COGS (includes cogs_is_loss).';



CREATE TABLE IF NOT EXISTS "public"."vendors" (
    "id" bigint NOT NULL,
    "name" "text" NOT NULL,
    "code" "text" NOT NULL,
    "market_code" "text" NOT NULL,
    "tenant_id" bigint,
    "email" "text",
    "phone" "text",
    "address" "text",
    "website" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "parent_tenant_id" bigint,
    "is_default" boolean DEFAULT false NOT NULL,
    CONSTRAINT "vendors_code_not_blank" CHECK (("length"(TRIM(BOTH FROM "code")) > 0)),
    CONSTRAINT "vendors_market_code_not_blank" CHECK (("length"(TRIM(BOTH FROM "market_code")) > 0)),
    CONSTRAINT "vendors_name_not_blank" CHECK (("length"(TRIM(BOTH FROM "name")) > 0))
);


