CREATE OR REPLACE FUNCTION "public"."grant_costing_file_viewer"("p_costing_file_id" bigint, "p_membership_id" bigint) RETURNS TABLE("costing_file_viewer_id" bigint, "costing_file_id" bigint, "membership_id" bigint, "name" "text", "email" "text", "role" "public"."app_role", "is_active" boolean, "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with target_file as (
    select cf.id, cf.tenant_id
    from public.costing_files cf
    where cf.id = p_costing_file_id
      and public.can_manage_costing_file_viewers(cf.tenant_id)
  ),
  target_viewer as (
    select m.id, m.email, m.role, m.is_active
    from public.memberships m
    inner join target_file tf
      on true
    where m.id = p_membership_id
      and m.tenant_id = tf.tenant_id
      and m.role = 'viewer'
      and m.is_active = true
  ),
  inserted as (
    insert into public.costing_file_viewers (
      costing_file_id,
      membership_id
    )
    select
      tf.id,
      tv.id
    from target_file tf
    cross join target_viewer tv
    on conflict (costing_file_id, membership_id) do update
      set updated_at = now()
    returning
      id as costing_file_viewer_id,
      costing_file_id,
      membership_id,
      created_at,
      updated_at
  )
  select
    i.costing_file_viewer_id,
    i.costing_file_id,
    i.membership_id,
    tv.email as name,
    tv.email,
    tv.role,
    tv.is_active,
    i.created_at,
    i.updated_at
  from inserted i
  inner join target_viewer tv
    on tv.id = i.membership_id;
$$;


ALTER FUNCTION "public"."grant_costing_file_viewer"("p_costing_file_id" bigint, "p_membership_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_membership_update"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if public.is_superadmin() then
    return new;
  end if;

  if old.tenant_id is distinct from new.tenant_id then
    raise exception 'Only superadmin can move memberships across tenants';
  end if;

  if lower(trim(old.email)) = lower(trim(public.current_user_email()))
    and old.email is not distinct from new.email
    and old.role is not distinct from new.role
    and old.is_active is not distinct from new.is_active
    and old.investor_id is not distinct from new.investor_id
    and old.tenant_role_id is not distinct from new.tenant_role_id
    and old.accent_color is not distinct from new.accent_color
    and old.preference is distinct from new.preference
  then
    return new;
  end if;

  if exists (
    select 1
    from public.memberships m
    where m.tenant_id = public.resolve_parent_tenant_id(old.tenant_id)
      and lower(trim(m.email)) = public.current_user_email()
      and m.role = 'owner'::public.app_role
      and m.is_active = true
  ) then
    if old.role = 'owner'::public.app_role and new.role is distinct from old.role then
      raise exception 'Use transfer_network_owner to change the network owner';
    end if;
    if new.role = 'owner'::public.app_role then
      raise exception 'Only transfer_network_owner can assign owner';
    end if;
    return new;
  end if;

  if exists (
    select 1
    from public.memberships m
    where m.tenant_id = old.tenant_id
      and lower(trim(m.email)) = public.current_user_email()
      and m.role = 'manager'::public.app_role
      and m.is_active = true
  ) then
    if old.role in ('owner'::public.app_role, 'manager'::public.app_role) then
      raise exception 'Managers cannot modify owner or manager memberships';
    end if;
    if new.role in ('owner'::public.app_role, 'manager'::public.app_role) then
      raise exception 'Managers cannot promote memberships to owner or manager';
    end if;
    return new;
  end if;

  if not public.is_tenant_admin(old.tenant_id) then
    raise exception 'Only tenant admins can update tenant memberships';
  end if;

  if old.role not in ('staff', 'viewer') then
    raise exception 'Tenant admins can only update staff or viewer memberships';
  end if;

  if new.role not in ('staff', 'viewer') then
    raise exception 'Tenant admins cannot promote membership role beyond staff/viewer';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."guard_membership_update"() OWNER TO "postgres";


