CREATE OR REPLACE FUNCTION "public"."hold_shop_grade_stock_for_order"("p_parent_tenant_id" bigint, "p_shop_tenant_id" bigint, "p_product_id" bigint, "p_grade_tag_id" bigint, "p_quantity" integer, "p_order_id" bigint, "p_notes" "text" DEFAULT NULL::"text") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_grade_tag_id bigint;
  v_remaining integer;
  v_stock record;
  v_take integer;
  v_primary_held bigint := NULL;
  v_held_stock_id bigint;
BEGIN
  IF p_quantity IS NULL OR p_quantity <= 0 THEN
    RAISE EXCEPTION 'quantity must be positive';
  END IF;

  v_grade_tag_id := coalesce(p_grade_tag_id, public.default_stock_grade_tag_id());
  v_remaining := p_quantity;

  FOR v_stock IN
    SELECT
      gs.id,
      gs.location_id,
      gs.grade_tag_id,
      gs.shipment_item_id,
      greatest(0, floor(public.global_stock_atp_qty(gs.id)))::integer AS atp
    FROM public.global_stocks gs
    JOIN public.global_shipment_items gsi ON gsi.id = gs.shipment_item_id
    JOIN public.global_shipments gship ON gship.id = gsi.shipment_id
    LEFT JOIN public.stock_locations sl ON sl.id = gs.location_id
    WHERE gsi.product_id = p_product_id
      AND coalesce(gs.grade_tag_id, public.default_stock_grade_tag_id()) = v_grade_tag_id
      AND gs.parent_tenant_id = p_parent_tenant_id
      AND public.shop_shipment_alloc_visible_to_tenant(gship.assigned_child_tenant_id, p_shop_tenant_id)
      AND gship.status = 'received'
      AND gs.availability = 'sellable'::public.stock_availability
      AND (gs.location_id IS NULL OR sl.is_pickable = TRUE)
    ORDER BY gs.id
    FOR UPDATE OF gs
  LOOP
    IF v_remaining <= 0 THEN
      EXIT;
    END IF;

    v_take := least(v_remaining, v_stock.atp);
    IF v_take <= 0 THEN
      CONTINUE;
    END IF;

    PERFORM public.create_and_post_stock_movement(
      p_parent_tenant_id,
      v_stock.id,
      v_take,
      v_stock.location_id,
      'held'::public.stock_availability,
      v_stock.grade_tag_id,
      'availability_transfer'::public.stock_movement_type,
      coalesce(p_notes, 'Shop order hold'),
      'shop_order',
      p_order_id::text
    );

    SELECT gs.id
    INTO v_held_stock_id
    FROM public.global_stocks gs
    WHERE gs.shipment_item_id = v_stock.shipment_item_id
      AND gs.parent_tenant_id = p_parent_tenant_id
      AND gs.availability = 'held'::public.stock_availability
      AND gs.location_id IS NOT DISTINCT FROM v_stock.location_id
      AND coalesce(gs.grade_tag_id, public.default_stock_grade_tag_id())
        = coalesce(v_stock.grade_tag_id, public.default_stock_grade_tag_id())
    ORDER BY gs.id DESC
    LIMIT 1;

    v_primary_held := coalesce(v_primary_held, v_held_stock_id);
    v_remaining := v_remaining - v_take;
  END LOOP;

  IF v_remaining > 0 THEN
    RAISE EXCEPTION 'insufficient sellable stock for product % (grade %): short by %',
      p_product_id, v_grade_tag_id, v_remaining;
  END IF;

  RETURN v_primary_held;
END;
$$;


ALTER FUNCTION "public"."hold_shop_grade_stock_for_order"("p_parent_tenant_id" bigint, "p_shop_tenant_id" bigint, "p_product_id" bigint, "p_grade_tag_id" bigint, "p_quantity" integer, "p_order_id" bigint, "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."hold_thrift_stock"("p_tenant_id" bigint, "p_stock_id" bigint, "p_held_for_phone" "text", "p_held_for_name" "text" DEFAULT NULL::"text", "p_hold_note" "text" DEFAULT NULL::"text", "p_held_by" "text" DEFAULT NULL::"text", "p_hold_expires_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_stock public.thrift_stocks%ROWTYPE;
  v_phone_normalized TEXT;
  v_updated INT;
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.memberships m
    WHERE m.tenant_id = p_tenant_id
      AND lower(trim(m.email)) = public.current_user_email()
      AND m.is_active = true
  ) THEN
    RAISE EXCEPTION 'Not authorized for this tenant';
  END IF;

  v_phone_normalized := public.normalize_thrift_phone(p_held_for_phone);
  IF v_phone_normalized = '' THEN
    RAISE EXCEPTION 'Hold requires a customer phone';
  END IF;

  SELECT *
  INTO v_stock
  FROM public.thrift_stocks
  WHERE id = p_stock_id
    AND tenant_id = p_tenant_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Stock item % not found for tenant %', p_stock_id, p_tenant_id;
  END IF;

  IF v_stock.status IS DISTINCT FROM 'AVAILABLE'::public.thrift_stock_status THEN
    RAISE EXCEPTION
      'Stock item % cannot be held (status=%); only AVAILABLE units can be held',
      p_stock_id,
      v_stock.status;
  END IF;

  UPDATE public.thrift_stocks
  SET
    status = 'RESERVED'::public.thrift_stock_status,
    held_for_name = NULLIF(trim(p_held_for_name), ''),
    held_for_phone = COALESCE(NULLIF(trim(p_held_for_phone), ''), v_phone_normalized),
    held_for_phone_normalized = v_phone_normalized,
    hold_note = NULLIF(trim(p_hold_note), ''),
    held_by = COALESCE(NULLIF(trim(p_held_by), ''), public.current_user_email()),
    held_at = NOW(),
    hold_expires_at = p_hold_expires_at,
    updated_at = NOW()
  WHERE id = p_stock_id
    AND tenant_id = p_tenant_id
    AND status = 'AVAILABLE'::public.thrift_stock_status;

  GET DIAGNOSTICS v_updated = ROW_COUNT;
  IF v_updated = 0 THEN
    RAISE EXCEPTION 'Stock item % became unavailable during hold', p_stock_id;
  END IF;

  RETURN jsonb_build_object(
    'id', p_stock_id,
    'status', 'RESERVED',
    'held_for_phone_normalized', v_phone_normalized
  );
END;
$$;


ALTER FUNCTION "public"."hold_thrift_stock"("p_tenant_id" bigint, "p_stock_id" bigint, "p_held_for_phone" "text", "p_held_for_name" "text", "p_hold_note" "text", "p_held_by" "text", "p_hold_expires_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."hold_thrift_stock"("p_tenant_id" bigint, "p_stock_id" bigint, "p_held_for_phone" "text", "p_held_for_name" "text", "p_hold_note" "text", "p_held_by" "text", "p_hold_expires_at" timestamp with time zone) IS 'Place AVAILABLE thrift stock on RESERVED hold for a customer phone (FB/online).';



