CREATE OR REPLACE FUNCTION "public"."is_network_owner"("p_tenant_id" bigint) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from public.memberships m
    where m.tenant_id = public.resolve_parent_tenant_id(p_tenant_id)
      and lower(trim(m.email)) = public.current_user_email()
      and m.role = 'owner'::public.app_role
      and m.is_active = true
  );
$$;


ALTER FUNCTION "public"."is_network_owner"("p_tenant_id" bigint) OWNER TO "postgres";


