CREATE OR REPLACE FUNCTION "public"."list_configurable_module_actions"("p_scope" "text", "p_tenant_id" bigint) RETURNS TABLE("id" bigint, "module_key" "text", "action" "text", "description" "text", "scope" "text", "tenant_configurable" boolean, "is_active" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if p_scope not in ('app', 'shop', 'investor') then
    raise exception 'Invalid scope: %', p_scope;
  end if;

  if not public.is_superadmin() and not exists (
    select 1
    from public.memberships m
    where m.tenant_id = p_tenant_id
      and lower(trim(m.email)) = public.current_user_email()
      and m.is_active = true
  ) then
    raise exception 'Access denied';
  end if;

  return query
  select
    ma.id,
    ma.module_key,
    ma.action,
    ma.description,
    ma.scope,
    ma.tenant_configurable,
    ma.is_active
  from public.module_actions ma
  where ma.is_active = true
    and ma.tenant_configurable = true
    and ma.scope = p_scope
    and ma.scope <> 'platform'
    and ma.module_key = any(public.get_active_module_keys_for_tenant(p_tenant_id));
end;
$$;


ALTER FUNCTION "public"."list_configurable_module_actions"("p_scope" "text", "p_tenant_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_costing_file_items"("p_costing_file_id" bigint) RETURNS TABLE("id" bigint, "costing_file_id" bigint, "name" "text", "image_url" "text", "website_url" "text", "quantity" integer, "product_weight" integer, "package_weight" integer, "price_in_web_gbp" numeric, "delivery_price_gbp" numeric, "auxiliary_price_gbp" numeric, "item_price_gbp" numeric, "cargo_rate" numeric, "costing_price_gbp" numeric, "costing_price_bdt" integer, "offer_price_bdt" integer, "customer_profit_rate" numeric, "status" "public"."costing_file_item_status", "created_by_email" "text", "assigned_shipment_id" bigint, "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    cfi.id,
    cfi.costing_file_id,
    cfi.name,
    cfi.image_url,
    cfi.website_url,
    cfi.quantity,
    cfi.product_weight,
    cfi.package_weight,
    cfi.price_in_web_gbp,
    cfi.delivery_price_gbp,
    cfi.auxiliary_price_gbp,
    cfi.item_price_gbp,
    cfi.cargo_rate,
    cfi.costing_price_gbp,
    cfi.costing_price_bdt,
    cfi.offer_price_bdt,
    cfi.customer_profit_rate,
    cfi.status,
    cfi.created_by_email,
    cfi.assigned_shipment_id,
    cfi.created_at,
    cfi.updated_at
  from public.costing_file_items cfi
  where cfi.costing_file_id = p_costing_file_id
    and public.can_view_costing_file(cfi.costing_file_id)
  order by cfi.id asc;
$$;


