CREATE OR REPLACE FUNCTION "public"."list_vendors_for_tenant"("p_tenant_id" bigint) RETURNS SETOF "public"."vendors"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if p_tenant_id is null then
    if not public.is_superadmin() then
      raise exception 'not allowed';
    end if;

    return query
    select v.*
    from public.vendors v
    where v.tenant_id is null
    order by v.id asc;

    return;
  end if;

  if not public.user_can_access_tenant_fetch(p_tenant_id) then
    raise exception 'not allowed';
  end if;

  if public.is_child_tenant(p_tenant_id) then
    return query
    select v.*
    from public.vendors v
    where v.tenant_id = p_tenant_id
    order by v.id asc;
  else
    return query
    select v.*
    from public.vendors v
    where v.parent_tenant_id = p_tenant_id
    order by v.id asc;
  end if;
end;
$$;


ALTER FUNCTION "public"."list_vendors_for_tenant"("p_tenant_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_wallet_entities_for_staff"("p_tenant_id" bigint, "p_entity_type" "text", "p_search" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 100, "p_offset" integer DEFAULT 0, "p_currency_code" "text" DEFAULT 'BDT'::"text") RETURNS TABLE("entity_id" bigint, "entity_type" "text", "name" "text", "code" "text", "caption" "text", "available_balance" numeric, "pending_balance" numeric, "locked_balance" numeric, "total_balance" numeric, "source_uuid" "uuid", "operating_tenant_id" bigint, "has_wallet_activity" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_books_id bigint;
  v_search text;
  v_limit integer;
  v_offset integer;
BEGIN
  IF p_entity_type NOT IN ('customer', 'vendor', 'courier', 'cargo_company', 'investor') THEN
    RAISE EXCEPTION 'Invalid entity_type %. Allowed: customer, vendor, courier, cargo_company, investor', p_entity_type;
  END IF;

  v_books_id := public.resolve_parent_tenant_id(p_tenant_id);
  IF NOT public.wallet_staff_can_view(p_tenant_id) THEN
    RETURN;
  END IF;

  v_search := nullif(trim(p_search), '');
  v_limit := greatest(least(coalesce(p_limit, 100), 500), 1);
  v_offset := greatest(coalesce(p_offset, 0), 0);

  IF p_entity_type = 'customer' THEN
    RETURN QUERY
    SELECT
      bp.id,
      'customer'::text,
      CASE WHEN cg.name IS NOT NULL THEN cg.name || ' · ' || bp.name ELSE bp.name END,
      NULL::text,
      nullif(trim(concat_ws(' • ', bp.phone, bp.email)), ''),
      coalesce(wa.available_balance, 0.0000),
      coalesce(wa.pending_balance, 0.0000),
      coalesce(wa.locked_balance, 0.0000),
      coalesce(wa.available_balance, 0) + coalesce(wa.pending_balance, 0) + coalesce(wa.locked_balance, 0),
      NULL::uuid,
      bp.tenant_id,
      wa.id IS NOT NULL
    FROM public.billing_profiles bp
    LEFT JOIN public.customer_groups cg ON cg.id = bp.customer_group_id
    LEFT JOIN public.wallet_accounts wa
      ON wa.parent_tenant_id = v_books_id
     AND wa.entity_type = 'customer'
     AND wa.entity_id = bp.id
     AND wa.currency_code = coalesce(p_currency_code, 'BDT')
    WHERE (bp.tenant_id = v_books_id
       OR bp.tenant_id IN (SELECT t.id FROM public.tenants t WHERE t.parent_id = v_books_id))
      AND (
        v_search IS NULL
        OR bp.name ILIKE '%' || v_search || '%'
        OR coalesce(cg.name, '') ILIKE '%' || v_search || '%'
        OR coalesce(bp.phone, '') ILIKE '%' || v_search || '%'
        OR coalesce(bp.email, '') ILIKE '%' || v_search || '%'
      )
    ORDER BY 3 ASC, bp.id ASC
    LIMIT v_limit OFFSET v_offset;

  ELSIF p_entity_type = 'vendor' THEN
    RETURN QUERY
    SELECT
      v.id, 'vendor'::text, v.name, v.code,
      nullif(trim(concat_ws(' • ', v.phone, v.email)), ''),
      coalesce(wa.available_balance, 0.0000),
      coalesce(wa.pending_balance, 0.0000),
      coalesce(wa.locked_balance, 0.0000),
      coalesce(wa.available_balance, 0) + coalesce(wa.pending_balance, 0) + coalesce(wa.locked_balance, 0),
      NULL::uuid, v.tenant_id, wa.id IS NOT NULL
    FROM public.vendors v
    LEFT JOIN public.wallet_accounts wa
      ON wa.parent_tenant_id = v_books_id AND wa.entity_type = 'vendor' AND wa.entity_id = v.id
     AND wa.currency_code = coalesce(p_currency_code, 'BDT')
    WHERE v.tenant_id = v_books_id
      AND (v_search IS NULL OR v.name ILIKE '%' || v_search || '%' OR coalesce(v.code, '') ILIKE '%' || v_search || '%')
    ORDER BY v.name ASC, v.id ASC
    LIMIT v_limit OFFSET v_offset;

  ELSIF p_entity_type = 'cargo_company' THEN
    RETURN QUERY
    SELECT
      c.id, 'cargo_company'::text, c.name, c.code,
      nullif(trim(concat_ws(' • ', c.phone, c.email)), ''),
      coalesce(wa.available_balance, 0.0000),
      coalesce(wa.pending_balance, 0.0000),
      coalesce(wa.locked_balance, 0.0000),
      coalesce(wa.available_balance, 0) + coalesce(wa.pending_balance, 0) + coalesce(wa.locked_balance, 0),
      NULL::uuid, c.tenant_id, wa.id IS NOT NULL
    FROM public.cargo_companies c
    LEFT JOIN public.wallet_accounts wa
      ON wa.parent_tenant_id = v_books_id AND wa.entity_type = 'cargo_company' AND wa.entity_id = c.id
     AND wa.currency_code = coalesce(p_currency_code, 'BDT')
    WHERE c.tenant_id = v_books_id
      AND (v_search IS NULL OR c.name ILIKE '%' || v_search || '%' OR coalesce(c.code, '') ILIKE '%' || v_search || '%')
    ORDER BY c.name ASC, c.id ASC
    LIMIT v_limit OFFSET v_offset;

  ELSIF p_entity_type = 'courier' THEN
    RETURN QUERY
    SELECT
      cs.wallet_entity_id,
      'courier'::text,
      cs.name,
      upper(cs.code),
      coalesce(nullif(trim(cs.notes), ''), 'Courier service'),
      coalesce(wa.available_balance, 0.0000),
      coalesce(wa.pending_balance, 0.0000),
      coalesce(wa.locked_balance, 0.0000),
      coalesce(wa.available_balance, 0) + coalesce(wa.pending_balance, 0) + coalesce(wa.locked_balance, 0),
      cs.id,
      coalesce(cs.tenant_id, v_books_id),
      wa.id IS NOT NULL
    FROM public.courier_services cs
    LEFT JOIN public.wallet_accounts wa
      ON wa.parent_tenant_id = v_books_id AND wa.entity_type = 'courier' AND wa.entity_id = cs.wallet_entity_id
     AND wa.currency_code = coalesce(p_currency_code, 'BDT')
    WHERE cs.is_active = true
      AND cs.wallet_entity_id IS NOT NULL
      AND (cs.tenant_id IS NULL OR cs.tenant_id = v_books_id
           OR cs.tenant_id IN (SELECT t.id FROM public.tenants t WHERE t.parent_id = v_books_id))
      AND (v_search IS NULL OR cs.name ILIKE '%' || v_search || '%' OR coalesce(cs.code, '') ILIKE '%' || v_search || '%')
    ORDER BY cs.name ASC, cs.wallet_entity_id ASC
    LIMIT v_limit OFFSET v_offset;

  ELSIF p_entity_type = 'investor' THEN
    RETURN QUERY
    SELECT
      i.id, 'investor'::text, i.name, NULL::text,
      nullif(trim(concat_ws(' • ', i.phone, i.email)), ''),
      coalesce(wa.available_balance, 0.0000),
      coalesce(wa.pending_balance, 0.0000),
      coalesce(wa.locked_balance, 0.0000),
      coalesce(wa.available_balance, 0) + coalesce(wa.pending_balance, 0) + coalesce(wa.locked_balance, 0),
      NULL::uuid, i.tenant_id, wa.id IS NOT NULL
    FROM public.investors i
    LEFT JOIN public.wallet_accounts wa
      ON wa.parent_tenant_id = v_books_id AND wa.entity_type = 'investor' AND wa.entity_id = i.id
     AND wa.currency_code = coalesce(p_currency_code, 'BDT')
    WHERE i.tenant_id = v_books_id
      AND (v_search IS NULL OR i.name ILIKE '%' || v_search || '%')
    ORDER BY i.name ASC, i.id ASC
    LIMIT v_limit OFFSET v_offset;
  END IF;
END;
$$;


ALTER FUNCTION "public"."list_wallet_entities_for_staff"("p_tenant_id" bigint, "p_entity_type" "text", "p_search" "text", "p_limit" integer, "p_offset" integer, "p_currency_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_wallet_ledger_for_staff"("p_tenant_id" bigint, "p_entity_type" "text", "p_entity_id" bigint, "p_search" "text" DEFAULT NULL::"text", "p_operating_tenant_id" bigint DEFAULT NULL::bigint, "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS TABLE("id" "uuid", "parent_tenant_id" bigint, "operating_tenant_id" bigint, "entity_type" "text", "entity_id" bigint, "type" "text", "amount" numeric, "currency_code" "text", "exchange_rate" numeric, "base_amount" numeric, "balance_after" numeric, "source_type" "text", "source_id" "text", "metadata" "jsonb", "created_at" timestamp with time zone, "is_reversal" boolean, "reversed_entry_id" "uuid")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_books_id bigint;
  v_entity_id bigint;
  v_search text;
BEGIN
  v_books_id := public.resolve_parent_tenant_id(p_tenant_id);
  v_entity_id := p_entity_id;
  IF p_entity_type = 'tenant' THEN v_entity_id := v_books_id; END IF;

  IF NOT public.wallet_staff_can_view(p_tenant_id) THEN RETURN; END IF;

  v_search := nullif(trim(p_search), '');

  RETURN QUERY
  SELECT
    l.id,
    l.parent_tenant_id,
    l.operating_tenant_id,
    l.entity_type,
    l.entity_id,
    l.type,
    l.amount,
    l.currency_code,
    l.exchange_rate,
    l.base_amount,
    l.balance_after,
    l.source_type,
    l.source_id,
    l.metadata,
    l.created_at,
    (l.metadata ? 'reversal_of'),
    CASE WHEN l.metadata ? 'reversal_of' THEN (l.metadata->>'reversal_of')::uuid ELSE NULL END
  FROM public.universal_wallet_ledger l
  WHERE l.parent_tenant_id = v_books_id
    AND l.entity_type = p_entity_type
    AND l.entity_id = v_entity_id
    AND (p_operating_tenant_id IS NULL OR l.operating_tenant_id = p_operating_tenant_id)
    AND (
      v_search IS NULL
      OR coalesce(l.source_id, '') ILIKE '%' || v_search || '%'
      OR coalesce(l.metadata->>'note', '') ILIKE '%' || v_search || '%'
      OR coalesce(l.metadata->>'trx_id', '') ILIKE '%' || v_search || '%'
      OR coalesce(l.metadata->>'section', '') ILIKE '%' || v_search || '%'
      OR coalesce(l.source_type, '') ILIKE '%' || v_search || '%'
    )
  ORDER BY l.created_at DESC, l.id DESC
  LIMIT greatest(least(coalesce(p_limit, 50), 200), 1)
  OFFSET greatest(coalesce(p_offset, 0), 0);
END;
$$;


ALTER FUNCTION "public"."list_wallet_ledger_for_staff"("p_tenant_id" bigint, "p_entity_type" "text", "p_entity_id" bigint, "p_search" "text", "p_operating_tenant_id" bigint, "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lock_global_shipment_costs"("p_shipment_id" bigint) RETURNS "public"."global_shipments"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_ship public.global_shipments%ROWTYPE;
BEGIN
  SELECT * INTO v_ship
  FROM public.global_shipments
  WHERE id = p_shipment_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'shipment not found';
  END IF;

  IF NOT public.user_can_manage_parent_tenant(v_ship.parent_tenant_id) THEN
    RAISE EXCEPTION 'not allowed';
  END IF;

  IF NOT public.global_shipment_stock_is_posted(v_ship) THEN
    RAISE EXCEPTION 'shipment stock is not posted; receive before locking costs';
  END IF;

  IF public.global_shipment_costs_are_locked(v_ship) THEN
    RAISE EXCEPTION 'shipment costs are already locked';
  END IF;

  PERFORM set_config('app.allow_costs_lock', '1', true);

  UPDATE public.global_shipments
  SET costs_locked = true,
      costs_locked_at = now(),
      costs_locked_by = auth.uid(),
      updated_at = now()
  WHERE id = p_shipment_id
  RETURNING * INTO v_ship;

  RETURN v_ship;
END;
$$;


ALTER FUNCTION "public"."lock_global_shipment_costs"("p_shipment_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_thrift_stock_loss_ledger"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
declare
  v_landed numeric(12, 2);
begin
  if (new.status in ('DAMAGED'::public.thrift_stock_status, 'STOLEN'::public.thrift_stock_status))
     and (old.status is null or old.status <> new.status) then
     
    v_landed := coalesce(public.compute_thrift_landed_unit_cost(new.id), 0.00);

    if v_landed > 0 then
      insert into public.thrift_accounting_ledger (
        tenant_id,
        type,
        source,
        reference_id,
        amount,
        inserted_by,
        note
      )
      values (
        new.tenant_id,
        'LOSS'::public.thrift_ledger_type,
        'SHIPMENT'::public.thrift_ledger_source,
        new.shipment_id,
        v_landed * new.quantity,
        new.inserted_by,
        'Auto-logged loss for stock item status set to ' || new.status || ' (Barcode: ' || coalesce(new.barcode, '') || ')'
      );
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."log_thrift_stock_loss_ledger"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_all_my_notifications_read"("p_tenant_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_updated_count bigint;
begin
  if v_user_id is null then
    raise exception 'Authentication required';
  end if;

  if p_tenant_id is null then
    raise exception 'p_tenant_id is required';
  end if;

  if not (
    public.is_superadmin()
    or public.has_active_tenant_membership(p_tenant_id)
    or public.user_can_manage_parent_tenant(public.resolve_parent_tenant_id(p_tenant_id))
    or public.has_shop_notification_access(p_tenant_id)
  ) then
    raise exception 'Permission denied for tenant %', p_tenant_id;
  end if;

  with updated as (
    update public.notification_recipients r
    set read_at = now()
    from public.notifications n
    where n.id = r.notification_id
      and r.user_id = v_user_id
      and r.read_at is null
      and public.notification_inbox_scope_matches(p_tenant_id, n.parent_tenant_id, n.operating_tenant_id)
    returning r.id
  )
  select count(*) into v_updated_count from updated;

  return jsonb_build_object(
    'success', true,
    'updated_count', coalesce(v_updated_count, 0)
  );
end;
$$;


ALTER FUNCTION "public"."mark_all_my_notifications_read"("p_tenant_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_dropship_order_delivered"("p_tenant_id" bigint, "p_order_id" bigint, "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_order public.shop_orders;
  v_invoice public.global_invoices;
  v_save jsonb;
begin
  if not public.is_tenant_staff(p_tenant_id) then
    raise exception 'access denied';
  end if;

  select * into v_order from public.shop_orders
  where id = p_order_id for update;

  if not found then
    raise exception 'order not found';
  end if;

  if v_order.tenant_id is distinct from p_tenant_id
     and v_order.parent_tenant_id is distinct from p_tenant_id then
    raise exception 'tenant mismatch';
  end if;

  if v_order.status <> 'shipped'::public.shop_order_status then
    raise exception 'mark as delivered requires shipped status (current: %)', v_order.status;
  end if;

  if v_order.global_invoice_id is null then
    raise exception 'merchant bill must be issued before deliver';
  end if;

  select * into v_invoice from public.global_invoices where id = v_order.global_invoice_id;
  if v_invoice.id is null then
    raise exception 'linked merchant bill not found';
  end if;

  if v_invoice.invoice_status <> 'issued'::public.global_invoice_status then
    raise exception 'merchant bill must be issued before deliver (current: %)', v_invoice.invoice_status;
  end if;

  perform public.canonicalize_dropship_order_wallet_source_ids(p_order_id);

  v_save := public.save_dropship_settlement_draft(p_tenant_id, p_order_id, p_payload);
  if coalesce(v_save->>'success', 'false') <> 'true' then
    return v_save;
  end if;

  update public.shop_orders
  set
    status = 'delivered'::public.shop_order_status,
    delivered_at = coalesce(delivered_at, now()),
    updated_at = now()
  where id = p_order_id;

  return jsonb_build_object(
    'success', true,
    'message', 'Order marked as delivered',
    'order_id', p_order_id,
    'invoice_id', v_order.global_invoice_id
  );
end;
$$;


ALTER FUNCTION "public"."mark_dropship_order_delivered"("p_tenant_id" bigint, "p_order_id" bigint, "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_dropship_order_returned"("p_order_id" bigint, "p_actual_return_charge" numeric, "p_deduct_from_middle_man" boolean, "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_items jsonb;
begin
  select jsonb_agg(
    jsonb_build_object(
      'order_item_id', id,
      'returned_qty', greatest(coalesce(delivered_quantity, quantity) - coalesce(returned_quantity, 0), 0),
      'condition', 'perfect'
    )
  )
  into v_items
  from public.shop_order_items
  where order_id = p_order_id;

  return public.finalize_dropship_return(
    p_order_id => p_order_id,
    p_items => coalesce(v_items, '[]'::jsonb),
    p_actual_return_charge => coalesce(p_actual_return_charge, 0.00),
    p_deduct_from_middle_man => coalesce(p_deduct_from_middle_man, true),
    p_override_reason => p_reason,
    p_return_ref => 'AUTO-RET-' || p_order_id::text || '-' || extract(epoch from now())::bigint
  );
end;
$$;


ALTER FUNCTION "public"."mark_dropship_order_returned"("p_order_id" bigint, "p_actual_return_charge" numeric, "p_deduct_from_middle_man" boolean, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_dropship_order_returned_from_settlement"("p_tenant_id" bigint, "p_order_id" bigint, "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_order public.shop_orders;
  v_save jsonb;
  v_finalize jsonb;
  v_return_items jsonb;
  v_return_fee numeric(15,2) := 0;
  v_line jsonb;
  v_deduct boolean := false;
  v_return_ref text;
  v_reason text;
  v_has_return_qty boolean := false;
  v_elem jsonb;
begin
  if not public.is_tenant_staff(p_tenant_id) then
    raise exception 'access denied';
  end if;

  select * into v_order
  from public.shop_orders
  where id = p_order_id
  for update;

  if not found then
    raise exception 'order not found';
  end if;

  if v_order.tenant_id is distinct from p_tenant_id
     and v_order.parent_tenant_id is distinct from p_tenant_id then
    raise exception 'order not found';
  end if;

  if v_order.shop_type_snapshot <> 'dropship' then
    raise exception 'not a dropship order';
  end if;

  if v_order.status <> 'shipped'::public.shop_order_status then
    raise exception 'mark as returned requires shipped status (current: %)', v_order.status;
  end if;

  v_return_items := coalesce(p_payload->'return_items', '[]'::jsonb);
  if jsonb_typeof(v_return_items) <> 'array' then
    raise exception 'return_items must be a JSON array';
  end if;

  for v_elem in select * from jsonb_array_elements(v_return_items) loop
    if coalesce((v_elem->>'returned_qty')::numeric, 0) > 0 then
      v_has_return_qty := true;
      exit;
    end if;
  end loop;

  if not v_has_return_qty then
    raise exception 'at least one return line with quantity > 0 is required';
  end if;

  v_deduct := coalesce((p_payload->>'deduct_from_middle_man')::boolean, false);
  v_return_ref := nullif(trim(coalesce(p_payload->>'return_ref', '')), '');
  if v_return_ref is null then
    v_return_ref := 'RET-' || p_order_id::text || '-' || extract(epoch from now())::bigint::text;
  end if;
  v_reason := nullif(trim(coalesce(p_payload->>'return_reason_note', '')), '');

  v_save := public.save_dropship_settlement_draft(p_tenant_id, p_order_id, p_payload);
  if coalesce(v_save->>'success', 'false') <> 'true' then
    return v_save;
  end if;

  for v_line in select * from jsonb_array_elements(coalesce(p_payload->'charge_lines', '[]'::jsonb)) loop
    if v_line->>'charge_type' = 'return' then
      v_return_fee := coalesce((v_line->>'amount')::numeric, 0);
      exit;
    end if;
  end loop;

  v_finalize := public.finalize_dropship_return(
    p_order_id => p_order_id,
    p_items => v_return_items,
    p_actual_return_charge => v_return_fee,
    p_deduct_from_middle_man => v_deduct,
    p_override_reason => v_reason,
    p_return_ref => v_return_ref
  );

  if coalesce(v_finalize->>'success', 'false') <> 'true' then
    return v_finalize;
  end if;

  return jsonb_build_object(
    'success', true,
    'message', 'Order marked as returned',
    'order_id', p_order_id,
    'status', 'returned',
    'return_ref', v_return_ref
  );
end;
$$;


ALTER FUNCTION "public"."mark_dropship_order_returned_from_settlement"("p_tenant_id" bigint, "p_order_id" bigint, "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_notification_read"("p_notification_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_read_at timestamptz;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF p_notification_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'p_notification_id is required');
  END IF;

  UPDATE public.notification_recipients
  SET read_at = now()
  WHERE notification_id = p_notification_id
    AND user_id = v_user_id
    AND read_at IS NULL
  RETURNING read_at INTO v_read_at;

  IF v_read_at IS NULL THEN
    SELECT r.read_at
    INTO v_read_at
    FROM public.notification_recipients r
    WHERE r.notification_id = p_notification_id
      AND r.user_id = v_user_id;
  END IF;

  IF v_read_at IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Notification not found');
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'notification_id', p_notification_id,
    'read_at', v_read_at
  );
END;
$$;


ALTER FUNCTION "public"."mark_notification_read"("p_notification_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_shop_order_item_shortfall"("p_order_item_id" bigint, "p_shortfall_qty" integer, "p_reason" "text" DEFAULT NULL::"text", "p_add_to_demand_bucket" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_item public.shop_order_items%rowtype;
  v_order public.shop_orders%rowtype;
  v_picked integer := 0;
  v_billing_profile_id bigint;
begin
  if p_shortfall_qty is null or p_shortfall_qty <= 0 then
    raise exception 'shortfall quantity must be positive';
  end if;

  select * into v_item from public.shop_order_items where id = p_order_item_id for update;
  select * into v_order from public.shop_orders where id = v_item.order_id for update;

  if not public.is_tenant_staff(v_order.tenant_id) then raise exception 'access denied'; end if;
  if v_order.status <> 'processing'::public.shop_order_status then
    raise exception 'shortfall only allowed while processing';
  end if;
  if coalesce(v_item.is_fulfillment_unavailable, false) then
    raise exception 'line is fully unavailable';
  end if;

  select coalesce(sum(sp.quantity), 0) into v_picked
  from public.shop_order_item_stock_picks sp where sp.order_item_id = p_order_item_id;

  if v_picked + p_shortfall_qty > v_item.quantity then
    raise exception 'shortfall exceeds remaining qty';
  end if;

  update public.shop_order_items
  set shortfall_quantity = p_shortfall_qty, updated_at = now()
  where id = p_order_item_id;

  if coalesce(p_add_to_demand_bucket, true) then
    v_billing_profile_id := coalesce(
      v_order.billing_profile_id,
      public.resolve_billing_profile_for_customer_group(v_order.tenant_id, v_order.customer_group_id)
    );
    if v_billing_profile_id is not null then
      perform public.add_demand_bucket_item(
        v_order.tenant_id, v_billing_profile_id, v_item.product_id,
        'shop_order'::public.demand_bucket_source_type, v_order.id,
        jsonb_build_object('order_item_id', v_item.id, 'reason', coalesce(p_reason, 'partial_shortfall')),
        p_shortfall_qty
      );
    end if;
  end if;

  perform public.recompute_dropship_cod_collect_amount(v_order.id);
  return jsonb_build_object('success', true);
end;
$$;


ALTER FUNCTION "public"."mark_shop_order_item_shortfall"("p_order_item_id" bigint, "p_shortfall_qty" integer, "p_reason" "text", "p_add_to_demand_bucket" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_shop_order_item_unavailable"("p_order_item_id" bigint, "p_reason" "text" DEFAULT NULL::"text", "p_add_to_demand_bucket" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_item public.shop_order_items%rowtype;
  v_order public.shop_orders%rowtype;
  v_pick_count integer := 0;
  v_billing_profile_id bigint;
begin
  select * into v_item from public.shop_order_items where id = p_order_item_id for update;
  if v_item.id is null then
    raise exception 'order item not found';
  end if;

  select * into v_order from public.shop_orders where id = v_item.order_id for update;
  if not public.is_tenant_staff(v_order.tenant_id) then
    raise exception 'access denied';
  end if;

  if v_order.status <> 'processing'::public.shop_order_status then
    raise exception 'unavailable is only allowed while order is processing';
  end if;

  select count(*) into v_pick_count
  from public.shop_order_item_stock_picks sp
  where sp.order_item_id = p_order_item_id;

  if v_pick_count > 0 then
    raise exception 'cannot mark unavailable while picks exist — remove picks first';
  end if;

  update public.shop_order_items
  set
    is_fulfillment_unavailable = true,
    unavailable_reason = nullif(trim(p_reason), ''),
    unavailable_at = now(),
    unavailable_by_email = public.current_user_email(),
    confirmed_quantity = 0,
    global_stock_id = null,
    updated_at = now()
  where id = p_order_item_id;

  if coalesce(p_add_to_demand_bucket, true) then
    v_billing_profile_id := coalesce(
      v_order.billing_profile_id,
      public.resolve_billing_profile_for_customer_group(v_order.tenant_id, v_order.customer_group_id)
    );
    if v_billing_profile_id is not null then
      perform public.add_demand_bucket_item(
        v_order.tenant_id,
        v_billing_profile_id,
        v_item.product_id,
        'shop_order'::public.demand_bucket_source_type,
        v_order.id,
        jsonb_build_object(
          'order_item_id', v_item.id,
          'name', v_item.name,
          'reason', coalesce(nullif(trim(p_reason), ''), 'fulfillment_unavailable')
        ),
        v_item.quantity
      );
    end if;
  end if;

  perform public.recompute_dropship_cod_collect_amount(v_order.id);

  return jsonb_build_object('success', true);
end;
$$;


ALTER FUNCTION "public"."mark_shop_order_item_unavailable"("p_order_item_id" bigint, "p_reason" "text", "p_add_to_demand_bucket" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_thrift_items_as_sold"("p_tenant_id" bigint, "p_invoice_number" "text", "p_recipient_name" "text", "p_address" "text", "p_phone" "text", "p_transaction_method" "public"."thrift_transaction_method", "p_cod_charge" numeric, "p_packing_charge" numeric, "p_invoice_print_charge" numeric, "p_shipping_charge_customer" numeric, "p_inserted_by" "text", "p_items" "jsonb") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
declare
  v_invoice_id bigint;
  v_item jsonb;
  v_stock_id bigint;
  v_qty integer;
  v_sold_price numeric(12,2);
  v_platform_fees numeric(12,2);
  v_ship_paid_by_shop numeric(12,2);
  v_available_qty integer;
  v_total_ship_paid_by_shop numeric(12,2) := 0.00;
begin
  -- 1. Insert Invoice
  insert into public.thrift_invoices (
    tenant_id,
    invoice_number,
    recipient_name,
    address,
    phone,
    transaction_method,
    cod_charge,
    packing_charge,
    invoice_print_charge,
    shipping_charge_customer,
    inserted_by
  )
  values (
    p_tenant_id,
    p_invoice_number,
    p_recipient_name,
    p_address,
    p_phone,
    p_transaction_method,
    p_cod_charge,
    p_packing_charge,
    p_invoice_print_charge,
    p_shipping_charge_customer,
    p_inserted_by
  )
  returning id into v_invoice_id;

  -- 2. Process items
  for v_item in select * from jsonb_array_elements(p_items) loop
    v_stock_id := (v_item->>'stock_id')::bigint;
    v_qty := (v_item->>'quantity')::integer;
    v_sold_price := (v_item->>'sold_price')::numeric;
    v_platform_fees := coalesce((v_item->>'platform_fees')::numeric, 0.00);
    v_ship_paid_by_shop := coalesce((v_item->>'shipping_cost_paid_by_shop')::numeric, 0.00);

    v_total_ship_paid_by_shop := v_total_ship_paid_by_shop + v_ship_paid_by_shop;

    -- Qty validation
    select quantity into v_available_qty
    from public.thrift_stocks
    where id = v_stock_id and tenant_id = p_tenant_id;

    if v_available_qty < v_qty then
      raise exception 'Insufficient stock for stock ID %', v_stock_id;
    end if;

    -- Add item to invoice
    insert into public.thrift_invoice_items (
      invoice_id,
      stock_id,
      quantity,
      sold_price,
      platform_fees,
      shipping_cost_paid_by_shop,
      item_status
    )
    values (
      v_invoice_id,
      v_stock_id,
      v_qty,
      v_sold_price,
      v_platform_fees,
      v_ship_paid_by_shop,
      'SOLD'::public.thrift_item_status
    );

    -- Deduct stock qty
    update public.thrift_stocks
    set 
      quantity = quantity - v_qty,
      status = case when (quantity - v_qty) = 0 then 'OUT_OF_STOCK'::public.thrift_stock_status else status end,
      updated_at = now()
    where id = v_stock_id;
  end loop;

  -- 3. Log Revenue (accrual basis)
  insert into public.thrift_accounting_ledger (
    tenant_id,
    type,
    source,
    reference_id,
    amount,
    inserted_by,
    note
  )
  select 
    p_tenant_id,
    'REVENUE'::public.thrift_ledger_type,
    'INVOICE'::public.thrift_ledger_source,
    v_invoice_id,
    total_invoice_amount,
    p_inserted_by,
    'Auto-logged revenue from Thrift Invoice #' || invoice_number
  from public.thrift_invoices
  where id = v_invoice_id;

  -- 4. Log Shipping Expense (if applicable)
  if v_total_ship_paid_by_shop > 0 then
    insert into public.thrift_accounting_ledger (
      tenant_id,
      type,
      source,
      reference_id,
      amount,
      inserted_by,
      note
    )
    values (
      p_tenant_id,
      'EXPENSE'::public.thrift_ledger_type,
      'INVOICE'::public.thrift_ledger_source,
      v_invoice_id,
      v_total_ship_paid_by_shop,
      p_inserted_by,
      'Auto-logged shipping cost absorbed by shop for Invoice #' || p_invoice_number
    );
  end if;

  return v_invoice_id;
end;
$$;


ALTER FUNCTION "public"."mark_thrift_items_as_sold"("p_tenant_id" bigint, "p_invoice_number" "text", "p_recipient_name" "text", "p_address" "text", "p_phone" "text", "p_transaction_method" "public"."thrift_transaction_method", "p_cod_charge" numeric, "p_packing_charge" numeric, "p_invoice_print_charge" numeric, "p_shipping_charge_customer" numeric, "p_inserted_by" "text", "p_items" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."mark_thrift_items_as_sold"("p_tenant_id" bigint, "p_invoice_number" "text", "p_recipient_name" "text", "p_address" "text", "p_phone" "text", "p_transaction_method" "public"."thrift_transaction_method", "p_cod_charge" numeric, "p_packing_charge" numeric, "p_invoice_print_charge" numeric, "p_shipping_charge_customer" numeric, "p_inserted_by" "text", "p_items" "jsonb") IS 'LEGACY ARCHIVE — execute revoked (P21). Use create_thrift_sales_invoice.';



CREATE OR REPLACE FUNCTION "public"."membership_has_module_action"("p_tenant_id" bigint, "p_module_key" "text", "p_action" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from public.memberships m
    where m.tenant_id = p_tenant_id
      and lower(trim(m.email)) = public.current_user_email()
      and m.is_active = true
      and (
        m.role in ('owner'::public.app_role, 'manager'::public.app_role)
        or public.has_module_action(p_tenant_id, p_module_key, p_action)
      )
  )
  or public.is_network_owner(p_tenant_id);
$$;


ALTER FUNCTION "public"."membership_has_module_action"("p_tenant_id" bigint, "p_module_key" "text", "p_action" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."membership_has_module_action_for_email"("p_email" "text", "p_tenant_id" bigint, "p_module_key" "text", "p_action" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_email text := lower(trim(coalesce(p_email, '')));
  v_member_id bigint;
  v_tenant_role_id bigint;
  v_role_is_admin boolean;
  v_member_role public.app_role;
  v_override_effect text;
  v_role_allowed boolean;
begin
  if v_email = '' or p_tenant_id is null or p_module_key is null then
    return false;
  end if;

  if public.is_network_owner_for_email(p_email, p_tenant_id) then
    return true;
  end if;

  if not (p_module_key = any(public.get_active_module_keys_for_tenant(p_tenant_id))) then
    return false;
  end if;

  select m.id, m.tenant_role_id, tr.is_admin, m.role
  into v_member_id, v_tenant_role_id, v_role_is_admin, v_member_role
  from public.memberships m
  left join public.tenant_roles tr on tr.id = m.tenant_role_id
  where m.tenant_id = p_tenant_id
    and lower(trim(m.email)) = v_email
    and m.is_active = true;

  if v_member_id is null then
    return false;
  end if;

  if v_member_role in ('owner'::public.app_role, 'manager'::public.app_role)
     or coalesce(v_role_is_admin, false) = true then
    return true;
  end if;

  select effect
  into v_override_effect
  from public.membership_grants
  where membership_id = v_member_id
    and module_key = p_module_key
    and action = p_action;

  if v_override_effect = 'deny' then
    return false;
  elsif v_override_effect = 'allow' then
    return true;
  end if;

  select allowed
  into v_role_allowed
  from public.tenant_role_grants
  where tenant_role_id = v_tenant_role_id
    and module_key = p_module_key
    and action = p_action;

  return coalesce(v_role_allowed, false);
end;
$$;


ALTER FUNCTION "public"."membership_has_module_action_for_email"("p_email" "text", "p_tenant_id" bigint, "p_module_key" "text", "p_action" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."migrate_legacy_inventory_to_global_stock"("p_tenant_id" bigint DEFAULT NULL::bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_item record;
  v_stock_id bigint;
  v_parent_id bigint;
  v_migrated integer := 0;
begin
  for v_item in
    select ii.*
    from public.inventory_items ii
    where (p_tenant_id is null or ii.tenant_id = p_tenant_id)
      and not exists (
        select 1 from public.global_stocks gs
        where gs.legacy_inventory_item_id = ii.id
      )
  loop
    v_parent_id := public.resolve_parent_tenant_id(v_item.tenant_id);

    insert into public.global_stocks (
      tenant_id,
      parent_tenant_id,
      name,
      cost,
      image_url,
      product_code,
      barcode,
      product_id,
      source_module,
      source_type,
      source_id,
      legacy_inventory_item_id
    )
    values (
      v_parent_id,
      v_parent_id,
      v_item.name,
      coalesce(v_item.cost, 0),
      v_item.image_url,
      v_item.product_code,
      v_item.barcode,
      v_item.product_id,
      'wholesale',
      coalesce(v_item.source_type, 'migration'),
      v_item.source_id,
      v_item.id
    )
    returning id into v_stock_id;

    insert into public.global_stock_quantities (stock_id, status, quantity)
    select v_stock_id, 'excellent', coalesce(s.available_quantity, 0)
    from public.inventory_stocks s
    where s.inventory_item_id = v_item.id
      and coalesce(s.available_quantity, 0) > 0
    on conflict (stock_id, status) do update set quantity = excluded.quantity;

    insert into public.global_stock_quantities (stock_id, status, quantity)
    select v_stock_id, 'box_less', coalesce(s.open_box_quantity, 0)
    from public.inventory_stocks s
    where s.inventory_item_id = v_item.id
      and coalesce(s.open_box_quantity, 0) > 0
    on conflict (stock_id, status) do update set quantity = excluded.quantity;

    insert into public.global_stock_quantities (stock_id, status, quantity)
    select v_stock_id, 'expired', coalesce(s.expired_quantity, 0)
    from public.inventory_stocks s
    where s.inventory_item_id = v_item.id
      and coalesce(s.expired_quantity, 0) > 0
    on conflict (stock_id, status) do update set quantity = excluded.quantity;

    insert into public.global_stock_quantities (stock_id, status, quantity)
    select v_stock_id, 'stolen', coalesce(s.stolen_quantity, 0)
    from public.inventory_stocks s
    where s.inventory_item_id = v_item.id
      and coalesce(s.stolen_quantity, 0) > 0
    on conflict (stock_id, status) do update set quantity = excluded.quantity;

    v_migrated := v_migrated + 1;
  end loop;

  return jsonb_build_object('migrated_count', v_migrated);
end;
$$;


ALTER FUNCTION "public"."migrate_legacy_inventory_to_global_stock"("p_tenant_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."next_tenant_scoped_counter"("p_tenant_id" bigint, "p_scope" "text") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_next bigint;
begin
  if p_tenant_id is null then
    raise exception 'tenant_id is required';
  end if;

  if p_scope not in ('shipment', 'order') then
    raise exception 'invalid scope: %', p_scope;
  end if;

  insert into public.tenant_scoped_counters (tenant_id, scope, last_value)
  values (p_tenant_id, p_scope, 1)
  on conflict (tenant_id, scope)
  do update
    set last_value = public.tenant_scoped_counters.last_value + 1
  returning last_value into v_next;

  return v_next;
end;
$$;


ALTER FUNCTION "public"."next_tenant_scoped_counter"("p_tenant_id" bigint, "p_scope" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_bd_mobile"("p_phone" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $_$
declare
  v text;
begin
  v := regexp_replace(coalesce(p_phone, ''), '[^0-9]', '', 'g');
  if left(v, 4) = '8801' then
    v := substring(v from 3);
  elsif left(v, 3) = '880' and length(v) = 13 then
    v := substring(v from 3);
  end if;
  if v !~ '^01[0-9]{9}$' then
    raise exception 'Invalid BD mobile phone: %', p_phone;
  end if;
  return v;
end;
$_$;


ALTER FUNCTION "public"."normalize_bd_mobile"("p_phone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_costing_file_item_fields"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  new.website_url := trim(coalesce(new.website_url, ''));

  if new.image_url is not null then
    new.image_url := nullif(trim(new.image_url), '');
  end if;

  if new.name is not null then
    new.name := nullif(trim(new.name), '');
  end if;

  if new.item_type is not null then
    new.item_type := nullif(trim(new.item_type), '');
  end if;

  if new.size is not null then
    new.size := nullif(trim(new.size), '');
  end if;

  if new.color is not null then
    new.color := nullif(trim(new.color), '');
  end if;

  if new.extra_information_1 is not null then
    new.extra_information_1 := nullif(trim(new.extra_information_1), '');
  end if;

  if new.extra_information_2 is not null then
    new.extra_information_2 := nullif(trim(new.extra_information_2), '');
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."normalize_costing_file_item_fields"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_costing_file_market"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  if new.market is null then
    return new;
  end if;

  new.market := nullif(upper(trim(new.market)), '');
  return new;
end;
$$;


ALTER FUNCTION "public"."normalize_costing_file_market"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_costing_file_status_po_placed"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
  if new.status::text = 'completed' then
    new.status = 'po_placed'::public.costing_file_status;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."normalize_costing_file_status_po_placed"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_customer_national_phone"("p_phone" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  select nullif(
    regexp_replace(
      regexp_replace(trim(coalesce(p_phone, '')), '[^0-9]', '', 'g'),
      '^0+',
      ''
    ),
    ''
  );
$$;


ALTER FUNCTION "public"."normalize_customer_national_phone"("p_phone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_membership_email"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
  new.email := lower(trim(coalesce(new.email, '')));

  if new.email = '' then
    raise exception 'membership email cannot be empty';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."normalize_membership_email"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_pbc_procurement_status"("p_status" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select case lower(trim(coalesce(p_status, '')))
    when 'placing_order' then 'procuring'
    when 'invoicing' then 'delivered'
    else lower(trim(coalesce(p_status, '')))
  end;
$$;


ALTER FUNCTION "public"."normalize_pbc_procurement_status"("p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_shop_order_procurement_status"("p_status" "public"."shop_order_status") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select case
    when p_status = 'ordered'::public.shop_order_status then 'ready_for_shipment'
    else p_status::text
  end;
$$;


ALTER FUNCTION "public"."normalize_shop_order_procurement_status"("p_status" "public"."shop_order_status") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_thrift_phone"("p_phone" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT regexp_replace(coalesce(p_phone, ''), '[^0-9]', '', 'g');
$$;


ALTER FUNCTION "public"."normalize_thrift_phone"("p_phone" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."normalize_thrift_phone"("p_phone" "text") IS 'Digits-only thrift customer phone key; empty/null input → empty string.';



CREATE OR REPLACE FUNCTION "public"."normalize_vendor_fields"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
  new.name = trim(new.name);
  new.code = upper(trim(new.code));
  new.market_code = upper(trim(new.market_code));

  if new.email is not null then
    new.email = nullif(lower(trim(new.email)), '');
  end if;

  if new.phone is not null then
    new.phone = nullif(trim(new.phone), '');
  end if;

  if new.address is not null then
    new.address = nullif(trim(new.address), '');
  end if;

  if new.website is not null then
    new.website = nullif(trim(new.website), '');
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."normalize_vendor_fields"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notification_inbox_scope_matches"("p_tenant_id" bigint, "p_parent_tenant_id" bigint, "p_operating_tenant_id" bigint) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    p_parent_tenant_id = public.resolve_parent_tenant_id(p_tenant_id)
    AND (
      NOT EXISTS (
        SELECT 1
        FROM public.tenants t
        WHERE t.id = p_tenant_id
          AND t.parent_id IS NOT NULL
      )
      OR p_operating_tenant_id IS NULL
      OR p_operating_tenant_id = p_tenant_id
    );
$$;


ALTER FUNCTION "public"."notification_inbox_scope_matches"("p_tenant_id" bigint, "p_parent_tenant_id" bigint, "p_operating_tenant_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_catalog_shop_order"("p_order_id" bigint, "p_notify_staff" boolean, "p_notify_customer" boolean, "p_event_type" "text", "p_title" "text", "p_body" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_order record;
  v_customer_user_ids uuid[];
begin
  select * into v_order from public.shop_orders where id = p_order_id;
  if not found then
    return;
  end if;

  if v_order.shop_type_snapshot <> 'vendor_catalog'::public.shop_type_enum then
    return;
  end if;

  if p_notify_staff then
    perform public.enqueue_notification(
      p_tenant_id := v_order.tenant_id,
      p_operating_tenant_id := v_order.tenant_id,
      p_audience := 'child_only',
      p_event_type := p_event_type,
      p_title := p_title,
      p_body := p_body,
      p_link_path := format('/app/shop/orders/%s', v_order.id),
      p_entity_type := 'shop_order',
      p_entity_id := v_order.id::text,
      p_module_key := 'shop_order_mgmt',
      p_action := 'view'
    );
  end if;

  if p_notify_customer and v_order.customer_group_id is not null then
    v_customer_user_ids := public.resolve_customer_group_notification_user_ids(v_order.customer_group_id);

    if v_customer_user_ids is not null and cardinality(v_customer_user_ids) > 0 then
      perform public.enqueue_notification(
        p_tenant_id := v_order.tenant_id,
        p_operating_tenant_id := v_order.tenant_id,
        p_audience := 'assignee_only',
        p_event_type := p_event_type,
        p_title := p_title,
        p_body := p_body,
        p_link_path := format('/shop/orders/%s', v_order.id),
        p_entity_type := 'shop_order',
        p_entity_id := v_order.id::text,
        p_recipient_user_ids := v_customer_user_ids,
        p_module_key := null,
        p_action := 'view'
      );
    end if;
  end if;
end;
$$;


ALTER FUNCTION "public"."notify_catalog_shop_order"("p_order_id" bigint, "p_notify_staff" boolean, "p_notify_customer" boolean, "p_event_type" "text", "p_title" "text", "p_body" "text") OWNER TO "postgres";


