CREATE OR REPLACE FUNCTION "public"."pay_settle_shipment_costs"("p_shipment_id" bigint, "p_cost_entry_ids" bigint[] DEFAULT NULL::bigint[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_ship public.global_shipments%rowtype;
  v_entry public.global_shipment_cost_entries%rowtype;
  v_amount numeric;
  v_settled_count integer := 0;
  v_wallet_posted boolean := false;
  v_ledger jsonb;
  v_wallet_entity_type text;
begin
  select * into v_ship
  from public.global_shipments
  where id = p_shipment_id
  for update;

  if not found then
    raise exception 'shipment not found';
  end if;

  if v_ship.status is distinct from 'received' then
    raise exception 'shipment must be received before settlement';
  end if;

  if not public.has_active_tenant_membership(v_ship.parent_tenant_id)
     and not public.is_superadmin() then
    raise exception 'not authorized';
  end if;

  for v_entry in
    select *
    from public.global_shipment_cost_entries
    where shipment_id = p_shipment_id
      and (p_cost_entry_ids is null or id = any(p_cost_entry_ids))
      and payment_source is not null
      and entity_type is not null
      and entity_id is not null
      and settled_at is null
  loop
    if v_entry.entity_type = 'shipment' then
      raise exception 'cost entry % cannot settle shipment entity', v_entry.id;
    end if;

    v_amount := round(coalesce(v_entry.amount, 0) * coalesce(v_entry.exchange_rate, 1), 4);
    if v_amount <= 0 then
      continue;
    end if;

    v_wallet_entity_type := case
      when v_entry.entity_type = 'cargo_company' then 'cargo_company'
      else v_entry.entity_type
    end;

    if v_entry.payment_source in ('cash', 'wallet') then
      v_ledger := public.record_ledger_transaction(
        p_tenant_id => v_ship.parent_tenant_id,
        p_entity_type => v_wallet_entity_type,
        p_entity_id => v_entry.entity_id,
        p_type => 'debit',
        p_amount => v_amount,
        p_currency_code => 'BDT',
        p_exchange_rate => 1.000000,
        p_source_type => 'shipment',
        p_source_id => p_shipment_id::text,
        p_metadata => jsonb_build_object(
          'cost_entry_id', v_entry.id,
          'payment_source', v_entry.payment_source,
          'purpose', 'shipment_cost_settle_payee'
        ),
        p_target_bucket => 'available'
      );

      v_ledger := public.record_ledger_transaction(
        p_tenant_id => v_ship.parent_tenant_id,
        p_entity_type => 'tenant',
        p_entity_id => v_ship.parent_tenant_id,
        p_type => 'debit',
        p_amount => v_amount,
        p_currency_code => 'BDT',
        p_exchange_rate => 1.000000,
        p_source_type => 'shipment',
        p_source_id => p_shipment_id::text,
        p_metadata => jsonb_build_object(
          'cost_entry_id', v_entry.id,
          'payment_source', v_entry.payment_source,
          'purpose', 'shipment_cost_settle_tenant_cash'
        ),
        p_target_bucket => 'available'
      );
      v_wallet_posted := true;

    elsif v_entry.payment_source = 'credit' then
      v_ledger := public.record_ledger_transaction(
        p_tenant_id => v_ship.parent_tenant_id,
        p_entity_type => v_wallet_entity_type,
        p_entity_id => v_entry.entity_id,
        p_type => 'credit',
        p_amount => v_amount,
        p_currency_code => 'BDT',
        p_exchange_rate => 1.000000,
        p_source_type => 'shipment',
        p_source_id => p_shipment_id::text,
        p_metadata => jsonb_build_object(
          'cost_entry_id', v_entry.id,
          'payment_source', 'credit',
          'purpose', 'shipment_cost_credit_payable'
        ),
        p_target_bucket => 'pending'
      );
      v_wallet_posted := true;
    else
      raise exception 'unsupported payment_source % on entry %', v_entry.payment_source, v_entry.id;
    end if;

    update public.global_shipment_cost_entries
    set
      settled_at = now(),
      settlement_ledger_id = coalesce((v_ledger->>'id')::uuid, settlement_ledger_id),
      updated_at = now()
    where id = v_entry.id;

    v_settled_count := v_settled_count + 1;
  end loop;

  return jsonb_build_object(
    'shipment_id', p_shipment_id,
    'settled_entries_count', v_settled_count,
    'wallet_posted', v_wallet_posted and v_settled_count > 0
  );
end;
$$;


ALTER FUNCTION "public"."pay_settle_shipment_costs"("p_shipment_id" bigint, "p_cost_entry_ids" bigint[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."place_koba_order"("p_tenant_id" bigint, "p_customer_group_id" bigint DEFAULT NULL::bigint, "p_shipping_name" "text" DEFAULT NULL::"text", "p_shipping_phone" "text" DEFAULT NULL::"text", "p_shipping_district" "text" DEFAULT NULL::"text", "p_shipping_thana" "text" DEFAULT NULL::"text", "p_shipping_address" "text" DEFAULT NULL::"text", "p_free_delivery" boolean DEFAULT false, "p_extra_profit_user" numeric DEFAULT 0, "p_extra_profit_company" numeric DEFAULT 0, "p_delivery_adjustment" numeric DEFAULT 0, "p_cod_charge" numeric DEFAULT 0, "p_packing_charge" numeric DEFAULT 0, "p_invoice_charge" numeric DEFAULT 0, "p_net_order_commission" numeric DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_cart_id bigint;
  v_order_id bigint;
  v_subtotal numeric(12,2) := 0;
  v_commission numeric(12,2) := 0;
  v_count integer := 0;
  v_gateway_charge numeric(12,2) := 20.00;
begin
  if not public.koba_context_access_allowed(p_tenant_id, p_customer_group_id) then
    raise exception 'not allowed';
  end if;

  select id into v_cart_id
  from public.koba_carts
  where tenant_id = p_tenant_id
    and customer_group_id is not distinct from p_customer_group_id
  limit 1;

  if v_cart_id is null then
    raise exception 'no cart found for this customer group';
  end if;

  select count(*) into v_count
  from public.koba_cart_items
  where cart_id = v_cart_id;

  if v_count = 0 then
    raise exception 'cart is empty';
  end if;

  -- Fetch gateway charge from settings for this tenant
  select coalesce(gateway_charge_flat, 20.00) into v_gateway_charge
  from public.koba_retail_settings
  where tenant_id = p_tenant_id
  limit 1;

  if v_gateway_charge is null then
    v_gateway_charge := 20.00;
  end if;

  -- Calculate totals: subtotal and total_commission (deducting gateway charge per unit)
  select
    coalesce(sum(coalesce(custom_price_gbp, unit_price_gbp, 0) * quantity), 0),
    coalesce(sum(greatest(0, coalesce(commission, 0) - v_gateway_charge) * quantity), 0),
    count(*)
  into v_subtotal, v_commission, v_count
  from public.koba_cart_items
  where cart_id = v_cart_id;

  insert into public.koba_orders (
    tenant_id,
    customer_group_id,
    shipping_name,
    shipping_phone,
    shipping_district,
    shipping_thana,
    shipping_address,
    free_delivery,
    subtotal_gbp,
    total_commission,
    item_count,
    status,
    extra_profit_user,
    extra_profit_company,
    delivery_adjustment,
    cod_charge,
    packing_charge,
    invoice_charge,
    net_order_commission
  ) values (
    p_tenant_id,
    p_customer_group_id,
    p_shipping_name,
    p_shipping_phone,
    p_shipping_district,
    p_shipping_thana,
    p_shipping_address,
    p_free_delivery,
    v_subtotal,
    v_commission,
    v_count,
    'pending',
    p_extra_profit_user,
    p_extra_profit_company,
    p_delivery_adjustment,
    p_cod_charge,
    p_packing_charge,
    p_invoice_charge,
    p_net_order_commission
  )
  returning id into v_order_id;

  insert into public.koba_order_items (
    order_id,
    product_id,
    product_code,
    barcode,
    name,
    brand,
    image_url,
    case_size,
    unit_price_gbp,
    custom_price_gbp,
    commission,
    commission_percentage,
    quantity
  )
  select
    v_order_id,
    product_id,
    product_code,
    barcode,
    name,
    brand,
    image_url,
    case_size,
    unit_price_gbp,
    custom_price_gbp,
    commission,
    commission_percentage,
    quantity
  from public.koba_cart_items
  where cart_id = v_cart_id;

  delete from public.koba_cart_items
  where cart_id = v_cart_id;

  return jsonb_build_object(
    'order_id', v_order_id,
    'customer_group_id', p_customer_group_id,
    'item_count', v_count,
    'subtotal_gbp', v_subtotal,
    'total_commission', v_commission,
    'status', 'pending'
  );
end;
$$;


ALTER FUNCTION "public"."place_koba_order"("p_tenant_id" bigint, "p_customer_group_id" bigint, "p_shipping_name" "text", "p_shipping_phone" "text", "p_shipping_district" "text", "p_shipping_thana" "text", "p_shipping_address" "text", "p_free_delivery" boolean, "p_extra_profit_user" numeric, "p_extra_profit_company" numeric, "p_delivery_adjustment" numeric, "p_cod_charge" numeric, "p_packing_charge" numeric, "p_invoice_charge" numeric, "p_net_order_commission" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."place_shop_order_for_procurement"("p_order_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_tenant_id bigint;
  v_status public.shop_order_status;
  v_type public.shop_type_enum;
begin
  select tenant_id, status, shop_type_snapshot
  into v_tenant_id, v_status, v_type
  from public.shop_orders
  where id = p_order_id;

  if v_tenant_id is null then
    raise exception 'order not found';
  end if;

  if not public.is_tenant_staff(v_tenant_id) then
    raise exception 'access denied';
  end if;

  if v_type <> 'vendor_catalog' then
    raise exception 'only vendor catalog orders can be placed for procurement';
  end if;

  if v_status <> 'confirmed' then
    raise exception 'order must be confirmed before placing';
  end if;

  update public.shop_orders
  set status = 'placed',
      placed_at = now(),
      updated_at = now()
  where id = p_order_id;
end;
$$;


ALTER FUNCTION "public"."place_shop_order_for_procurement"("p_order_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pop_demand_bucket_item"("p_bucket_item_id" bigint, "p_popped_into_type" "text", "p_popped_into_id" bigint) RETURNS "public"."customer_demand_bucket_items"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_row public.customer_demand_bucket_items;
begin
  if p_bucket_item_id is null then
    raise exception 'bucket_item_id is required';
  end if;
  if nullif(trim(coalesce(p_popped_into_type, '')), '') is null
     or p_popped_into_id is null then
    raise exception 'popped_into_type and popped_into_id are required';
  end if;

  select * into v_row
  from public.customer_demand_bucket_items
  where id = p_bucket_item_id;

  if not found then
    raise exception 'bucket item not found: %', p_bucket_item_id;
  end if;

  if v_row.status <> 'open' then
    raise exception 'bucket item % is not open', p_bucket_item_id;
  end if;

  if not public.can_access_demand_bucket_profile(v_row.tenant_id, v_row.billing_profile_id, false) then
    raise exception 'access denied';
  end if;

  update public.customer_demand_bucket_items
  set
    status = 'popped',
    popped_at = now(),
    popped_into_type = trim(p_popped_into_type),
    popped_into_id = p_popped_into_id,
    updated_at = now()
  where id = p_bucket_item_id
  returning * into v_row;

  return v_row;
end;
$$;


ALTER FUNCTION "public"."pop_demand_bucket_item"("p_bucket_item_id" bigint, "p_popped_into_type" "text", "p_popped_into_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pop_demand_bucket_items"("p_bucket_item_ids" bigint[], "p_popped_into_type" "text", "p_popped_into_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_id bigint;
  v_row public.customer_demand_bucket_items;
  v_items jsonb := '[]'::jsonb;
begin
  if p_bucket_item_ids is null or cardinality(p_bucket_item_ids) = 0 then
    return jsonb_build_object('items', '[]'::jsonb, 'count', 0);
  end if;

  foreach v_id in array p_bucket_item_ids loop
    v_row := public.pop_demand_bucket_item(v_id, p_popped_into_type, p_popped_into_id);
    v_items := v_items || jsonb_build_array(to_jsonb(v_row));
  end loop;

  return jsonb_build_object(
    'items', v_items,
    'count', jsonb_array_length(v_items)
  );
end;
$$;


ALTER FUNCTION "public"."pop_demand_bucket_items"("p_bucket_item_ids" bigint[], "p_popped_into_type" "text", "p_popped_into_id" bigint) OWNER TO "postgres";


