CREATE OR REPLACE FUNCTION "public"."preview_tenant_data_purge"("p_parent_tenant_id" bigint, "p_scope" "text" DEFAULT 'all_hierarchy'::"text", "p_target_child_id" bigint DEFAULT NULL::bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_target_tenant_ids BIGINT[];
    v_shipment_count BIGINT := 0;
    v_stock_count BIGINT := 0;
    v_invoice_count BIGINT := 0;
    v_order_count BIGINT := 0;
    v_cart_count BIGINT := 0;
    v_ledger_count BIGINT := 0;
    v_wallets_count BIGINT := 0;
BEGIN
    IF NOT (public.is_superadmin() OR public.user_can_manage_parent_tenant(p_parent_tenant_id)) THEN
        RAISE EXCEPTION 'Unauthorized: Only parent tenant administrators can preview data purges.';
    END IF;

    IF p_scope = 'all_hierarchy' THEN
        SELECT array_agg(id) INTO v_target_tenant_ids
        FROM public.tenants
        WHERE id = p_parent_tenant_id OR parent_id = p_parent_tenant_id;

        SELECT count(*) INTO v_shipment_count FROM public.global_shipments WHERE parent_tenant_id = p_parent_tenant_id;
        SELECT count(*) INTO v_stock_count FROM public.global_stocks WHERE parent_tenant_id = p_parent_tenant_id;
        SELECT count(*) INTO v_invoice_count FROM public.global_invoices WHERE parent_tenant_id = p_parent_tenant_id;
        SELECT count(*) INTO v_ledger_count FROM public.universal_wallet_ledger WHERE parent_tenant_id = p_parent_tenant_id;
        SELECT count(*) INTO v_wallets_count FROM public.wallet_accounts WHERE parent_tenant_id = p_parent_tenant_id;
    ELSE
        IF p_target_child_id IS NULL THEN
            RAISE EXCEPTION 'Target child tenant ID is required for child_only scope.';
        END IF;

        IF NOT EXISTS (SELECT 1 FROM public.tenants WHERE id = p_target_child_id AND parent_id = p_parent_tenant_id) THEN
            RAISE EXCEPTION 'Invalid child tenant ID for this parent organization.';
        END IF;

        v_target_tenant_ids := ARRAY[p_target_child_id];

        SELECT count(*) INTO v_invoice_count FROM public.global_invoices WHERE issued_by_tenant_id = p_target_child_id;
        SELECT count(*) INTO v_ledger_count FROM public.universal_wallet_ledger WHERE operating_tenant_id = p_target_child_id;
        SELECT count(*) INTO v_wallets_count FROM public.wallet_accounts WHERE tenant_id = p_target_child_id;
    END IF;

    SELECT count(*) INTO v_order_count FROM public.shop_orders WHERE tenant_id = ANY(v_target_tenant_ids);
    SELECT count(*) INTO v_cart_count FROM public.shop_carts WHERE tenant_id = ANY(v_target_tenant_ids);

    RETURN jsonb_build_object(
        'shipments', v_shipment_count,
        'stocks', v_stock_count,
        'invoices', v_invoice_count,
        'orders', v_order_count,
        'carts', v_cart_count,
        'ledgers', v_ledger_count,
        'wallets_to_reset', v_wallets_count
    );
END;
$$;


ALTER FUNCTION "public"."preview_tenant_data_purge"("p_parent_tenant_id" bigint, "p_scope" "text", "p_target_child_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_courier_bulk_remittance_batch"("p_batch_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_batch record;
  v_item record;
  v_order record;
  v_invoice record;
  v_payment_id bigint;
  v_processed_count integer := 0;
  v_error_count integer := 0;
  v_net_remitted numeric(12,2);
  v_total_allocated numeric(12,2) := 0.00;
begin
  -- Lock batch record
  select * into v_batch
  from public.courier_remittance_batches
  where id = p_batch_id for update;

  if v_batch.id is null then
    raise exception 'Remittance batch #% not found', p_batch_id;
  end if;

  if v_batch.status <> 'draft' then
    raise exception 'Batch #% is already %', v_batch.batch_no, v_batch.status;
  end if;

  -- Permission check
  if not (
    public.is_superadmin()
    or exists (
      select 1 from public.memberships m
      where m.tenant_id = v_batch.tenant_id
        and lower(trim(m.email)) = public.current_user_email()
        and m.is_active = true
        and m.role in ('admin', 'staff')
    )
  ) then
    raise exception 'Permission denied: Staff or Admin role required for tenant %', v_batch.tenant_id;
  end if;

  -- Process line items sequentially
  for v_item in
    select * from public.courier_remittance_items
    where batch_id = p_batch_id
    for update
  loop
    v_net_remitted := v_item.net_remitted_amount;

    -- Validate order
    if v_item.shop_order_id is null then
      update public.courier_remittance_items
      set status = 'error', error_message = 'Missing linked order'
      where id = v_item.id;
      v_error_count := v_error_count + 1;
      continue;
    end if;

    select * into v_order from public.shop_orders
    where id = v_item.shop_order_id for update;

    if v_order.id is null then
      update public.courier_remittance_items
      set status = 'error', error_message = 'Shop order record not found'
      where id = v_item.id;
      v_error_count := v_error_count + 1;
      continue;
    end if;

    if v_order.status <> 'delivered' then
      update public.courier_remittance_items
      set status = 'error', error_message = 'Order is not in delivered status (current: ' || v_order.status || ')'
      where id = v_item.id;
      v_error_count := v_error_count + 1;
      continue;
    end if;

    if v_order.global_invoice_id is null then
      update public.courier_remittance_items
      set status = 'error', error_message = 'Missing accounting global invoice'
      where id = v_item.id;
      v_error_count := v_error_count + 1;
      continue;
    end if;

    -- Lock & validate global invoice
    select * into v_invoice from public.global_invoices
    where id = v_order.global_invoice_id for update;

    if v_invoice.id is null then
      update public.courier_remittance_items
      set status = 'error', error_message = 'Global invoice not found'
      where id = v_item.id;
      v_error_count := v_error_count + 1;
      continue;
    end if;

    -- Create global payment record
    insert into public.global_payments (
      tenant_id,
      billing_profile_id,
      collection_source,
      amount,
      unallocated_amount,
      payment_date,
      method,
      reference,
      note
    )
    values (
      v_batch.tenant_id,
      v_invoice.billing_profile_id,
      v_invoice.collection_source,
      v_net_remitted,
      0.00,
      coalesce(v_batch.payment_date, current_date),
      'bank_transfer',
      v_batch.batch_no,
      'Courier remittance batch #' || v_batch.batch_no || ' order #' || v_order.order_no
    )
    returning id into v_payment_id;

    -- Insert invoice payment allocation
    insert into public.invoice_payments (tenant_id, payment_id, global_invoice_id, amount)
    values (v_batch.tenant_id, v_payment_id, v_order.global_invoice_id, v_net_remitted);

    -- Update invoice paid amount
    update public.global_invoices
    set
      paid_amount = coalesce(paid_amount, 0.00) + v_net_remitted,
      updated_at = now()
    where id = v_order.global_invoice_id;

    -- Recompute payment status
    perform public.recompute_global_invoice_payment_status(v_order.global_invoice_id);

    -- Update order status to payment_received & stamp references
    update public.shop_orders
    set
      status = 'payment_received'::public.shop_order_status,
      courier_remittance_ref = v_batch.batch_no,
      courier_bank_trx_id = coalesce(v_batch.bank_trx_id, courier_bank_trx_id),
      updated_at = now()
    where id = v_order.id;

    -- Mark item as processed
    update public.courier_remittance_items
    set
      status = 'processed',
      error_message = null,
      global_invoice_id = v_order.global_invoice_id
    where id = v_item.id;

    v_processed_count := v_processed_count + 1;
    v_total_allocated := v_total_allocated + v_net_remitted;
  end loop;

  -- Mark batch header as posted if no fatal block
  update public.courier_remittance_batches
  set
    status = 'posted',
    allocated_amount = v_total_allocated,
    variance_amount = net_deposited_amount - v_total_allocated,
    posted_at = now(),
    posted_by = auth.uid(),
    updated_at = now()
  where id = p_batch_id;

  return jsonb_build_object(
    'success', true,
    'batch_id', p_batch_id,
    'processed_count', v_processed_count,
    'error_count', v_error_count,
    'allocated_amount', v_total_allocated,
    'status', 'posted'
  );
end;
$$;


ALTER FUNCTION "public"."process_courier_bulk_remittance_batch"("p_batch_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_dropship_courier_remittance_uwl"("p_order_id" bigint, "p_net_amount" numeric, "p_courier_charge" numeric DEFAULT 0.00, "p_remittance_ref" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_order record;
  v_parent_tenant_id bigint;
  v_courier_id bigint := 0;
  v_cod numeric(12,2) := 0.00;
  v_charge numeric(12,2) := 0.00;
  v_net numeric(12,2) := 0.00;
  v_currency text;
begin
  select * into v_order from public.shop_orders where id = p_order_id for update;
  if v_order.id is null then
    raise exception 'Shop order #% not found', p_order_id;
  end if;

  v_parent_tenant_id := public.resolve_parent_tenant_id(v_order.tenant_id);
  v_currency := 'BDT';
  v_cod := coalesce(v_order.cod_collect_amount, 0.00);
  v_charge := greatest(coalesce(p_courier_charge, 0.00), 0.00);
  v_net := greatest(coalesce(p_net_amount, 0.00), 0.00);

  if v_order.courier_service_id is not null then
    select coalesce(wallet_entity_id, 0) into v_courier_id
    from public.courier_services
    where id = v_order.courier_service_id;

    if v_courier_id is null then
      v_courier_id := 0;
    end if;
  else
    v_courier_id := 0;
  end if;

  if v_net > 0 and not exists (
    select 1 from public.universal_wallet_ledger
    where parent_tenant_id = v_parent_tenant_id
      and entity_type = 'courier'
      and source_type = 'shop_order'
      and source_id = p_order_id::text
      and metadata->>'purpose' = 'courier_remittance'
  ) then
    perform public.record_ledger_transaction(
      p_parent_tenant_id => v_parent_tenant_id,
      p_operating_tenant_id => v_order.tenant_id,
      p_entity_type => 'courier',
      p_entity_id => v_courier_id,
      p_type => 'debit',
      p_amount => v_net,
      p_currency_code => v_currency,
      p_exchange_rate => 1.000000,
      p_source_type => 'shop_order',
      p_source_id => p_order_id::text,
      p_metadata => jsonb_build_object(
        'section', 'cod_pending',
        'purpose', 'courier_remittance',
        'transaction_type', 'courier_remittance',
        'label', 'COD Remittance to Tenant',
        'order_no', v_order.order_no,
        'courier_charge', v_charge,
        'net_remitted', v_net,
        'gross_cod', v_cod,
        'remittance_ref', p_remittance_ref,
        'courier_service_id', v_order.courier_service_id
      )
    );
  end if;

  if v_charge > 0 and not exists (
    select 1 from public.universal_wallet_ledger
    where parent_tenant_id = v_parent_tenant_id
      and entity_type = 'courier'
      and source_type = 'shop_order'
      and source_id = p_order_id::text
      and metadata->>'purpose' = 'courier_fee_retained'
  ) then
    perform public.record_ledger_transaction(
      p_parent_tenant_id => v_parent_tenant_id,
      p_operating_tenant_id => v_order.tenant_id,
      p_entity_type => 'courier',
      p_entity_id => v_courier_id,
      p_type => 'debit',
      p_amount => v_charge,
      p_currency_code => v_currency,
      p_exchange_rate => 1.000000,
      p_source_type => 'shop_order',
      p_source_id => p_order_id::text,
      p_metadata => jsonb_build_object(
        'section', 'cod_pending',
        'purpose', 'courier_fee_retained',
        'transaction_type', 'courier_fee_retained',
        'label', 'Courier COD / Delivery Fee Retained',
        'order_no', v_order.order_no,
        'courier_charge', v_charge,
        'net_remitted', v_net,
        'gross_cod', v_cod,
        'remittance_ref', p_remittance_ref,
        'courier_service_id', v_order.courier_service_id
      )
    );
  end if;

  if not exists (
    select 1 from public.universal_wallet_ledger
    where parent_tenant_id = v_parent_tenant_id
      and entity_type = 'tenant'
      and source_type = 'shop_order'
      and source_id = p_order_id::text
      and metadata->>'purpose' = 'tenant_remittance_received'
  ) then
    perform public.record_ledger_transaction(
      p_parent_tenant_id => v_parent_tenant_id,
      p_operating_tenant_id => v_order.tenant_id,
      p_entity_type => 'tenant',
      p_entity_id => v_parent_tenant_id,
      p_type => 'credit',
      p_amount => v_net,
      p_currency_code => v_currency,
      p_exchange_rate => 1.000000,
      p_source_type => 'shop_order',
      p_source_id => p_order_id::text,
      p_metadata => jsonb_build_object(
        'section', 'payment_received',
        'purpose', 'tenant_remittance_received',
        'transaction_type', 'courier_remittance_received',
        'label', 'Courier Remittance Received',
        'order_no', v_order.order_no,
        'gross_cod', v_cod,
        'courier_charge', v_charge,
        'net_remitted', v_net,
        'remittance_ref', p_remittance_ref
      )
    );
  end if;
end;
$$;


ALTER FUNCTION "public"."process_dropship_courier_remittance_uwl"("p_order_id" bigint, "p_net_amount" numeric, "p_courier_charge" numeric, "p_remittance_ref" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_dropship_shop_order"("p_order_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
declare
  v_order public.shop_orders%rowtype;
begin
  -- Fetch order
  select * into v_order from public.shop_orders where id = p_order_id;
  if not found then
    return jsonb_build_object('success', false, 'error', 'Order not found');
  end if;

  if v_order.shop_type_snapshot <> 'dropship' then
    return jsonb_build_object('success', false, 'error', 'Only dropship orders can be handed off to the dropship desk');
  end if;

  if v_order.status <> 'confirmed' then
    return jsonb_build_object('success', false, 'error', 'Only confirmed orders can be handed off to the dropship desk');
  end if;

  -- Update status to processing (merchant details will be added later)
  update public.shop_orders
  set
    status = 'processing',
    updated_at = now()
  where id = p_order_id;

  return jsonb_build_object(
    'success', true,
    'order_id', p_order_id,
    'new_status', 'processing'
  );
end;
$$;


ALTER FUNCTION "public"."process_dropship_shop_order"("p_order_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_wholesale_invoice_return"("p_invoice_id" bigint, "p_items" "jsonb", "p_return_charge_amount" numeric DEFAULT 0, "p_refund_method" "text" DEFAULT NULL::"text", "p_payout_account_id" bigint DEFAULT NULL::bigint, "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_invoice public.sales_invoices;
  v_item_elem jsonb;
  v_item_id bigint;
  v_return_qty numeric;
  v_to_availability public.stock_availability;
  v_to_grade_tag_id bigint;
  v_item_note text;
  v_db_item public.sales_invoice_items%rowtype;
  v_parent_id bigint;
  v_eff_tenant_id bigint;
  v_total_return_value numeric(12,2) := 0.00;
  v_line_unit_price numeric(12,2);
  v_line_return_val numeric(12,2);
  v_new_subtotal numeric(12,2) := 0.00;
  v_charges numeric(12,2) := 0.00;
  v_discount numeric(12,2) := 0.00;
  v_paid numeric(12,2) := 0.00;
  v_new_total numeric(12,2) := 0.00;
  v_new_due numeric(12,2) := 0.00;
  v_excess_paid numeric(12,2) := 0.00;
  v_refund_amount numeric(12,2) := 0.00;
  v_return_count integer := 0;
  v_payout_id text;
  v_charge numeric(12,2) := 0.00;
begin
  if p_invoice_id is null then
    raise exception 'Invoice ID is required';
  end if;

  select * into v_invoice
  from public.sales_invoices
  where id = p_invoice_id
  for update;

  if v_invoice.id is null then
    raise exception 'Invoice not found';
  end if;

  if v_invoice.invoice_status <> 'issued'::public.global_invoice_status then
    raise exception 'Returns can only be processed on issued/posted invoices';
  end if;

  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'At least one return item must be provided';
  end if;

  v_charge := greatest(coalesce(p_return_charge_amount, 0.00), 0.00);
  v_eff_tenant_id := coalesce(v_invoice.issued_by_tenant_id, v_invoice.parent_tenant_id);
  v_parent_id := coalesce(v_invoice.parent_tenant_id, v_invoice.issued_by_tenant_id);

  -- 1. Loop and process each return item
  for v_item_elem in select * from jsonb_array_elements(p_items) loop
    v_item_id := (v_item_elem->>'invoice_item_id')::bigint;
    v_return_qty := (v_item_elem->>'quantity')::numeric;
    v_to_availability := coalesce(
      (v_item_elem->>'to_availability')::public.stock_availability,
      'held'::public.stock_availability
    );
    v_to_grade_tag_id := (v_item_elem->>'to_grade_tag_id')::bigint;
    v_item_note := nullif(trim(v_item_elem->>'note'), '');

    if v_item_id is null then
      raise exception 'invoice_item_id is required for all items';
    end if;

    if v_return_qty is null or v_return_qty <= 0 then
      continue; -- Skip 0 or empty quantity items
    end if;

    select * into v_db_item
    from public.sales_invoice_items
    where id = v_item_id and invoice_id = p_invoice_id
    for update;

    if v_db_item.id is null then
      raise exception 'Invoice item % not found on this invoice', v_item_id;
    end if;

    if (v_db_item.return_quantity + v_return_qty) > v_db_item.quantity then
      raise exception 'Return quantity % exceeds available returnable quantity % for %',
        v_return_qty,
        (v_db_item.quantity - v_db_item.return_quantity),
        v_db_item.name_snapshot;
    end if;

    -- Calculate line return value
    v_line_unit_price := v_db_item.sell_price_amount;
    v_line_return_val := round(v_return_qty * v_line_unit_price, 2);
    v_total_return_value := v_total_return_value + v_line_return_val;

    -- Insert record into sales_return_items
    insert into public.sales_return_items (
      parent_tenant_id,
      invoice_id,
      invoice_item_id,
      global_stock_id,
      quantity,
      return_charge_amount,
      note
    ) values (
      v_parent_id,
      p_invoice_id,
      v_item_id,
      v_db_item.global_stock_id,
      v_return_qty,
      0.00,
      v_item_note
    );

    -- Update sales_invoice_items cumulative return_quantity; sold quantity stays.
    -- line_total_amount is the net after return credit (kept qty × price − line discount).
    update public.sales_invoice_items
    set
      return_quantity = return_quantity + v_return_qty,
      line_total_amount = greatest(
        (v_db_item.quantity - (v_db_item.return_quantity + v_return_qty)) * v_db_item.sell_price_amount
        - coalesce(v_db_item.line_discount_amount, 0),
        0
      ),
      updated_at = now()
    where id = v_item_id;

    -- Post return_inbound stock movement
    if v_db_item.global_stock_id is not null then
      perform public.create_and_post_stock_movement(
        p_tenant_id => v_parent_id,
        p_stock_id => v_db_item.global_stock_id,
        p_quantity => ceil(v_return_qty)::integer,
        p_to_location_id => public.default_returns_stock_location_id(v_parent_id),
        p_to_availability => v_to_availability,
        p_to_grade_tag_id => coalesce(v_to_grade_tag_id, public.default_stock_grade_tag_id()),
        p_movement_type => 'return_inbound'::public.stock_movement_type,
        p_notes => coalesce(v_item_note, 'Wholesale invoice return #' || coalesce(v_invoice.invoice_no, p_invoice_id::text)),
        p_reference_type => 'sales_invoice',
        p_reference_id => p_invoice_id::text
      );
    end if;

    v_return_count := v_return_count + 1;
  end loop;

  if v_return_count = 0 then
    raise exception 'No items with quantity > 0 were selected for return';
  end if;

  -- 2. Recalculate invoice totals based on retained quantities
  select coalesce(sum((quantity - return_quantity) * sell_price_amount - line_discount_amount), 0.00)
  into v_new_subtotal
  from public.sales_invoice_items
  where invoice_id = p_invoice_id;

  v_charges := coalesce(v_invoice.shipping_charge, 0.00)
             + coalesce(v_invoice.wrapping_charge, 0.00)
             + coalesce(v_invoice.print_charge, 0.00)
             + v_charge; -- add return handling charge if any

  v_discount := coalesce(v_invoice.discount_amount, 0.00);
  v_paid := coalesce(v_invoice.paid_amount, 0.00);

  v_new_total := greatest(v_new_subtotal + v_charges - v_discount, 0.00);
  v_new_due := greatest(v_new_total - v_paid, 0.00);
  v_excess_paid := greatest(v_paid - v_new_total, 0.00);

  -- 3. Handle excess overpayment refund if applicable
  if v_excess_paid > 0.00 then
    if p_refund_method = 'wallet_credit' and v_invoice.billing_profile_id is not null then
      -- Ensure wallet account exists
      insert into public.wallet_accounts (
        tenant_id, entity_type, entity_id, currency_code,
        available_balance, locked_balance, pending_balance
      ) values (
        v_eff_tenant_id, 'customer', v_invoice.billing_profile_id, 'BDT',
        0.0000, 0.0000, 0.0000
      ) on conflict (tenant_id, entity_type, entity_id, currency_code) do nothing;

      -- Credit Customer Wallet via universal ledger
      perform public.record_ledger_transaction(
        p_tenant_id => v_eff_tenant_id,
        p_entity_type => 'customer',
        p_entity_id => v_invoice.billing_profile_id,
        p_type => 'credit',
        p_amount => v_excess_paid,
        p_currency_code => 'BDT',
        p_exchange_rate => 1.000000,
        p_source_type => 'sales_invoice_return',
        p_source_id => p_invoice_id::text,
        p_metadata => jsonb_build_object(
          'section', 'returns',
          'purpose', 'wholesale_return_wallet_credit',
          'transaction_type', 'return_credit',
          'label', 'Return Credit (Wallet)',
          'invoice_id', p_invoice_id,
          'invoice_no', v_invoice.invoice_no,
          'notes', p_note
        )
      );

      v_refund_amount := v_excess_paid;

    elsif p_refund_method = 'payout' and v_invoice.billing_profile_id is not null then
      v_payout_id := 'RET-PO-' || gen_random_uuid()::text;

      -- Payout: Debit Tenant Cash (cash outflow from business to customer)
      perform public.record_ledger_transaction(
        p_tenant_id => v_eff_tenant_id,
        p_entity_type => 'tenant',
        p_entity_id => v_eff_tenant_id,
        p_type => 'debit',
        p_amount => v_excess_paid,
        p_currency_code => 'BDT',
        p_exchange_rate => 1.000000,
        p_source_type => 'payout',
        p_source_id => v_payout_id,
        p_metadata => jsonb_build_object(
          'section', 'payout_earned',
          'purpose', 'wholesale_return_payout',
          'transaction_type', 'return_cash_payout',
          'label', 'Return Cash Payout',
          'invoice_id', p_invoice_id,
          'invoice_no', v_invoice.invoice_no,
          'billing_profile_id', v_invoice.billing_profile_id,
          'notes', p_note
        )
      );

      v_refund_amount := v_excess_paid;
    end if;
  end if;

  -- 4. Update sales_invoices header
  update public.sales_invoices
  set
    subtotal_amount = v_new_subtotal,
    total_amount = v_new_total,
    due_amount = v_new_due,
    payment_status = case
      when v_new_due <= 0.00 then 'paid'
      when v_paid > 0.00 and v_new_due > 0.00 then 'partially_paid'
      else 'due'
    end,
    updated_at = now()
  where id = p_invoice_id
  returning * into v_invoice;

  return jsonb_build_object(
    'success', true,
    'invoice_id', v_invoice.id,
    'invoice_no', v_invoice.invoice_no,
    'new_subtotal', v_new_subtotal,
    'new_total', v_new_total,
    'new_due', v_new_due,
    'paid_amount', v_paid,
    'excess_paid', v_excess_paid,
    'refund_amount', v_refund_amount,
    'refund_method', p_refund_method,
    'payment_status', v_invoice.payment_status,
    'returned_items_count', v_return_count
  );
end;
$$;


ALTER FUNCTION "public"."process_wholesale_invoice_return"("p_invoice_id" bigint, "p_items" "jsonb", "p_return_charge_amount" numeric, "p_refund_method" "text", "p_payout_account_id" bigint, "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."purge_archived_shipment"("p_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_ship public.global_shipments%rowtype;
begin
  select * into v_ship
  from public.global_shipments
  where id = p_id
  for update;

  if not found then
    raise exception 'shipment not found';
  end if;

  if not public.user_can_manage_parent_tenant(v_ship.parent_tenant_id) then
    raise exception 'not allowed';
  end if;

  if v_ship.is_archived is not true then
    raise exception 'shipment must be archived before it can be permanently deleted';
  end if;

  -- Only draft and cancelled shipments can be permanently deleted
  if v_ship.status not in ('draft', 'cancelled') then
    raise exception 'shipment in status % cannot be deleted; only archived draft or cancelled shipments may be purged', v_ship.status;
  end if;

  -- Verify no physical stock was ever created for this shipment
  if exists (
    select 1
    from public.global_stocks gs
    where gs.shipment_item_id in (
      select id from public.global_shipment_items where shipment_id = p_id
    )
  ) or v_ship.stock_ready = true then
    raise exception 'cannot delete shipment: physical inventory records exist for this shipment';
  end if;

  -- Delete the global shipment record.
  -- Child records (items, sections, boxes, cost entries, investments) will be deleted
  -- automatically via ON DELETE CASCADE constraints on their foreign keys.
  delete from public.global_shipments where id = p_id;
end;
$$;


ALTER FUNCTION "public"."purge_archived_shipment"("p_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."purge_popped_demand_bucket_items"("p_tenant_id" bigint, "p_retention_days" integer DEFAULT 90) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_cutoff timestamptz;
  v_deleted integer;
  v_is_parent boolean;
begin
  if p_tenant_id is null then
    raise exception 'tenant_id is required';
  end if;

  select (t.parent_id is null) into v_is_parent
  from public.tenants t
  where t.id = p_tenant_id;

  if coalesce(v_is_parent, false) then
    if not public.user_can_manage_parent_tenant(p_tenant_id) then
      raise exception 'access denied';
    end if;
  elsif not public.is_tenant_staff(p_tenant_id) then
    raise exception 'access denied';
  end if;

  v_cutoff := now() - make_interval(days => greatest(coalesce(p_retention_days, 90), 1));

  delete from public.customer_demand_bucket_items b
  where b.status = 'popped'
    and b.popped_at is not null
    and b.popped_at < v_cutoff
    and (
      b.tenant_id = p_tenant_id
      or exists (
        select 1
        from public.tenants t
        where t.id = b.tenant_id
          and t.parent_id = p_tenant_id
      )
    );

  get diagnostics v_deleted = row_count;

  return jsonb_build_object(
    'tenant_id', p_tenant_id,
    'retention_days', greatest(coalesce(p_retention_days, 90), 1),
    'deleted_count', v_deleted
  );
end;
$$;


ALTER FUNCTION "public"."purge_popped_demand_bucket_items"("p_tenant_id" bigint, "p_retention_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."purge_shop_order_financial_artifacts"("p_order_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_order public.shop_orders;
  v_invoice public.global_invoices;
  v_invoice_id bigint;
begin
  select * into v_order
  from public.shop_orders
  where id = p_order_id;

  if v_order.id is null then
    return;
  end if;

  v_invoice_id := v_order.global_invoice_id;

  if v_invoice_id is null and v_order.shop_type_snapshot = 'dropship' then
    select i.id into v_invoice_id
    from public.global_invoices i
    where i.tenant_id = v_order.tenant_id
      and i.invoice_no = 'INV-DS-' || v_order.order_no
      and not exists (
        select 1
        from public.shop_orders o2
        where o2.global_invoice_id = i.id
          and o2.id <> v_order.id
      )
    order by i.id desc
    limit 1;
  end if;

  if v_invoice_id is not null then
    select * into v_invoice from public.global_invoices where id = v_invoice_id;
  end if;

  delete from public.courier_remittance_items
  where shop_order_id = p_order_id;

  perform public.purge_shop_order_wallet_ledger(
    p_order_id => p_order_id,
    p_tenant_id => v_order.tenant_id,
    p_order_no => v_order.order_no,
    p_invoice_id => v_invoice_id,
    p_invoice_no => v_invoice.invoice_no
  );

  if v_invoice_id is not null then
    perform public.purge_shop_order_invoice(v_invoice_id);
  end if;
end;
$$;


ALTER FUNCTION "public"."purge_shop_order_financial_artifacts"("p_order_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."purge_shop_order_invoice"("p_invoice_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_invoice public.global_invoices;
  v_payment_ids bigint[];
begin
  if p_invoice_id is null then
    return;
  end if;

  select * into v_invoice
  from public.global_invoices
  where id = p_invoice_id
  for update;

  if v_invoice.id is null then
    return;
  end if;

  select coalesce(array_agg(distinct ip.payment_id), '{}'::bigint[])
  into v_payment_ids
  from public.invoice_payments ip
  where ip.global_invoice_id = p_invoice_id;

  delete from public.invoice_payments
  where global_invoice_id = p_invoice_id;

  delete from public.global_payments gp
  where gp.id = any (v_payment_ids)
    and not exists (
      select 1
      from public.invoice_payments ip
      where ip.payment_id = gp.id
    );

  update public.sales_invoices
  set
    paid_amount = 0.00,
    payment_status = 'due',
    due_amount = coalesce(total_amount, 0.00),
    updated_at = now()
  where id = p_invoice_id;

  if v_invoice.invoice_status = 'issued'::public.global_invoice_status then
    perform public.unpost_global_invoice(p_invoice_id);
  end if;

  delete from public.global_return_items where invoice_id = p_invoice_id;
  delete from public.global_invoice_items where invoice_id = p_invoice_id;
  delete from public.sales_invoices where id = p_invoice_id;
end;
$$;


ALTER FUNCTION "public"."purge_shop_order_invoice"("p_invoice_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."purge_shop_order_wallet_ledger"("p_order_id" bigint, "p_tenant_id" bigint, "p_order_no" "text", "p_invoice_id" bigint DEFAULT NULL::bigint, "p_invoice_no" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_row public.universal_wallet_ledger;
begin
  for v_row in
    select *
    from public.universal_wallet_ledger u
    where (
      u.source_type = 'shop_order'
      and (
        u.source_id = p_order_id::text
        or (p_order_no is not null and u.source_id = p_order_no)
        or (p_invoice_no is not null and u.source_id = p_invoice_no)
      )
    )
    or u.metadata->>'order_id' = p_order_id::text
    or (p_invoice_id is not null and u.metadata->>'invoice_id' = p_invoice_id::text)
  loop
    perform public._undo_wallet_ledger_row_before_delete(v_row);
  end loop;

  delete from public.universal_wallet_ledger u
  where (
    u.source_type = 'shop_order'
    and (
      u.source_id = p_order_id::text
      or (p_order_no is not null and u.source_id = p_order_no)
      or (p_invoice_no is not null and u.source_id = p_invoice_no)
    )
  )
  or u.metadata->>'order_id' = p_order_id::text
  or (p_invoice_id is not null and u.metadata->>'invoice_id' = p_invoice_id::text);
end;
$$;


ALTER FUNCTION "public"."purge_shop_order_wallet_ledger"("p_order_id" bigint, "p_tenant_id" bigint, "p_order_no" "text", "p_invoice_id" bigint, "p_invoice_no" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."purge_tenant_operational_data"("p_parent_tenant_id" bigint, "p_scope" "text" DEFAULT 'all_hierarchy'::"text", "p_confirmation_slug" "text" DEFAULT ''::"text", "p_target_child_id" bigint DEFAULT NULL::bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_parent_slug TEXT;
    v_target_slug TEXT;
    v_target_id BIGINT;
    v_target_tenant_ids BIGINT[];
    v_counts JSONB;
    v_user_id UUID := auth.uid();
    v_user_email TEXT := COALESCE(public.current_user_email(), 'unknown');
BEGIN
    IF NOT (public.is_superadmin() OR public.user_can_manage_parent_tenant(p_parent_tenant_id)) THEN
        RAISE EXCEPTION 'Unauthorized: Administrative privileges on the parent tenant required.';
    END IF;

    SELECT slug INTO v_parent_slug FROM public.tenants WHERE id = p_parent_tenant_id AND parent_id IS NULL;
    IF v_parent_slug IS NULL THEN
        RAISE EXCEPTION 'Parent tenant not found or is not a root workspace.';
    END IF;

    IF p_scope = 'all_hierarchy' THEN
        v_target_id := p_parent_tenant_id;
        v_target_slug := v_parent_slug;

        SELECT array_agg(id) INTO v_target_tenant_ids
        FROM public.tenants
        WHERE id = p_parent_tenant_id OR parent_id = p_parent_tenant_id;
    ELSIF p_scope = 'child_only' THEN
        IF p_target_child_id IS NULL THEN
            RAISE EXCEPTION 'Target child tenant ID is required for child_only scope.';
        END IF;

        SELECT slug INTO v_target_slug
        FROM public.tenants
        WHERE id = p_target_child_id AND parent_id = p_parent_tenant_id;

        IF v_target_slug IS NULL THEN
            RAISE EXCEPTION 'Selected child tenant not found under this parent organization.';
        END IF;

        v_target_id := p_target_child_id;
        v_target_tenant_ids := ARRAY[p_target_child_id];
    ELSE
        RAISE EXCEPTION 'Invalid scope: %. Must be all_hierarchy or child_only.', p_scope;
    END IF;

    IF UPPER(TRIM(p_confirmation_slug)) <> UPPER(TRIM(v_target_slug)) THEN
        RAISE EXCEPTION 'Confirmation slug mismatch. Expected %, received %.', UPPER(TRIM(v_target_slug)), UPPER(TRIM(p_confirmation_slug));
    END IF;

    v_counts := public.preview_tenant_data_purge(p_parent_tenant_id, p_scope, p_target_child_id);

    -- PBC master data must never be purged:
    -- product_based_costing_files, product_based_costing_items, product_based_costing_backlog_items

    IF p_scope = 'all_hierarchy' THEN
        DELETE FROM public.sales_return_items WHERE parent_tenant_id = p_parent_tenant_id;
        DELETE FROM public.sales_invoice_items WHERE parent_tenant_id = p_parent_tenant_id;
        DELETE FROM public.sales_invoices WHERE parent_tenant_id = p_parent_tenant_id;
    ELSE
        DELETE FROM public.sales_return_items
        WHERE invoice_id IN (
            SELECT id FROM public.sales_invoices
            WHERE parent_tenant_id = p_parent_tenant_id
              AND issued_by_tenant_id = p_target_child_id
        );
        DELETE FROM public.sales_invoice_items
        WHERE invoice_id IN (
            SELECT id FROM public.sales_invoices
            WHERE parent_tenant_id = p_parent_tenant_id
              AND issued_by_tenant_id = p_target_child_id
        );
        DELETE FROM public.sales_invoices
        WHERE parent_tenant_id = p_parent_tenant_id
          AND issued_by_tenant_id = p_target_child_id;
    END IF;

    DELETE FROM public.dropship_order_settlements WHERE tenant_id = ANY(v_target_tenant_ids);
    DELETE FROM public.shop_orders WHERE tenant_id = ANY(v_target_tenant_ids);
    DELETE FROM public.shop_carts WHERE tenant_id = ANY(v_target_tenant_ids);
    DELETE FROM public.customer_demand_bucket_items WHERE tenant_id = ANY(v_target_tenant_ids);

    IF p_scope = 'all_hierarchy' THEN
        DELETE FROM public.universal_wallet_ledger WHERE parent_tenant_id = p_parent_tenant_id;
        UPDATE public.wallet_accounts
        SET available_balance = 0.0000,
            pending_balance = 0.0000,
            locked_balance = 0.0000,
            updated_at = now()
        WHERE parent_tenant_id = p_parent_tenant_id;
    ELSE
        DELETE FROM public.universal_wallet_ledger WHERE operating_tenant_id = p_target_child_id;
        UPDATE public.wallet_accounts
        SET available_balance = 0.0000,
            pending_balance = 0.0000,
            locked_balance = 0.0000,
            updated_at = now()
        WHERE tenant_id = p_target_child_id;
    END IF;

    IF p_scope = 'all_hierarchy' THEN
        DELETE FROM public.stock_movements WHERE tenant_id = ANY(v_target_tenant_ids);
        DELETE FROM public.global_stocks WHERE parent_tenant_id = p_parent_tenant_id;
        DELETE FROM public.global_shipments WHERE parent_tenant_id = p_parent_tenant_id;
    END IF;

    UPDATE public.sales_invoice_counters
    SET last_value = 0
    WHERE tenant_id = ANY(v_target_tenant_ids);

    INSERT INTO public.tenant_data_purge_logs (
        parent_tenant_id,
        target_tenant_id,
        scope,
        executed_by,
        executor_email,
        confirmation_phrase,
        deleted_counts
    ) VALUES (
        p_parent_tenant_id,
        v_target_id,
        p_scope,
        v_user_id,
        v_user_email,
        p_confirmation_slug,
        v_counts
    );

    RETURN jsonb_build_object(
        'success', true,
        'purged_counts', v_counts,
        'purged_at', now()
    );
END;
$$;


ALTER FUNCTION "public"."purge_tenant_operational_data"("p_parent_tenant_id" bigint, "p_scope" "text", "p_confirmation_slug" "text", "p_target_child_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recalculate_product_based_costing_file_offer_prices"("p_file_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
declare
  v_conversion_rate numeric;
  v_cargo_rate numeric;
  v_profit_rate numeric;
begin
  select conversion_rate, cargo_rate_kg_gbp, profit_rate
    into v_conversion_rate, v_cargo_rate, v_profit_rate
    from public.product_based_costing_files
   where id = p_file_id;

  update public.product_based_costing_items
     set offer_price = public.round_bdt_up_to_zero_or_five(
           ceil(
             round(
               (coalesce(price_gbp, 0) + ((coalesce(product_weight, 0) + coalesce(package_weight, 0)) / 1000.0) * coalesce(v_cargo_rate, 0)),
               2
             ) * coalesce(v_conversion_rate, 140) - 1e-9
           ) + (
             ceil(
               round(
                 (coalesce(price_gbp, 0) + ((coalesce(product_weight, 0) + coalesce(package_weight, 0)) / 1000.0) * coalesce(v_cargo_rate, 0)),
                 2
               ) * coalesce(v_conversion_rate, 140) - 1e-9
             ) * coalesce(v_profit_rate, 25) / 100.0
           )
         ),
         is_offer_price_manual = false
   where product_based_costing_file_id = p_file_id
     and (is_offer_price_manual is not true);
end;
$$;


ALTER FUNCTION "public"."recalculate_product_based_costing_file_offer_prices"("p_file_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recalculate_shipment_transaction_rate"("p_shipment_id" bigint) RETURNS numeric
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_product_conv numeric;
  v_cargo_conv numeric;
  v_cargo_rate numeric;
  v_received_weight numeric;
  v_shipment_type text;
  v_goods_cost_gbp numeric := 0;
  v_goods_cost_bdt numeric := 0;
  v_cargo_weight numeric := 0;
  v_cargo_cost_gbp numeric := 0;
  v_cargo_cost_bdt numeric := 0;
  v_total_cost_gbp numeric := 0;
  v_total_cost_bdt numeric := 0;
  v_transaction_rate numeric;
begin
  select
    product_conversion_rate,
    cargo_conversion_rate,
    cargo_rate,
    received_weight,
    shipment_type
  into
    v_product_conv,
    v_cargo_conv,
    v_cargo_rate,
    v_received_weight,
    v_shipment_type
  from public.shipments
  where id = p_shipment_id;

  if coalesce(v_shipment_type, 'international') <> 'international' then
    update public.shipments
    set transaction_rate = null
    where id = p_shipment_id;
    return null;
  end if;

  select coalesce(sum(price_gbp * quantity), 0)
  into v_goods_cost_gbp
  from public.shipment_items
  where shipment_id = p_shipment_id;

  v_goods_cost_bdt := coalesce(v_product_conv, 0) * v_goods_cost_gbp;
  v_cargo_weight := coalesce(v_received_weight, 0);
  v_cargo_cost_gbp := v_cargo_weight * coalesce(v_cargo_rate, 0);
  v_cargo_cost_bdt := v_cargo_cost_gbp * coalesce(v_cargo_conv, 0);
  v_total_cost_gbp := v_goods_cost_gbp + v_cargo_cost_gbp;
  v_total_cost_bdt := v_goods_cost_bdt + v_cargo_cost_bdt;

  if v_total_cost_gbp > 0 then
    v_transaction_rate := v_total_cost_bdt / v_total_cost_gbp;
  else
    v_transaction_rate := (coalesce(v_product_conv, 0) + coalesce(v_cargo_conv, 0)) / 2.0;
  end if;

  update public.shipments
  set transaction_rate = round(coalesce(v_transaction_rate, 1.0), 2)
  where id = p_shipment_id;

  return v_transaction_rate;
end;
$$;


ALTER FUNCTION "public"."recalculate_shipment_transaction_rate"("p_shipment_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recipient_profile_valid_for_issuer"("p_recipient_profile_id" bigint, "p_issued_by_tenant_id" bigint) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from public.recipient_profiles rp
    where rp.id = p_recipient_profile_id
      and (
        rp.tenant_id = p_issued_by_tenant_id
        or rp.tenant_id = public.resolve_parent_tenant_id(p_issued_by_tenant_id)
        or coalesce(rp.parent_tenant_id, rp.tenant_id)
          = public.resolve_parent_tenant_id(p_issued_by_tenant_id)
        or exists (
          select 1
          from public.tenants t
          where t.id = rp.tenant_id
            and t.parent_id = public.resolve_parent_tenant_id(p_issued_by_tenant_id)
        )
      )
  );
$$;


ALTER FUNCTION "public"."recipient_profile_valid_for_issuer"("p_recipient_profile_id" bigint, "p_issued_by_tenant_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recompute_dropship_cod_collect_amount"("p_order_id" bigint) RETURNS numeric
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_order public.shop_orders%rowtype;
  v_items_resell_delivered numeric := 0;
  v_recipient_charge_total numeric := 0;
  v_cod_collect_amount numeric;
begin
  select * into v_order from public.shop_orders where id = p_order_id for update;
  if v_order.id is null then
    raise exception 'order not found';
  end if;

  select coalesce(
    sum(
      coalesce(soi.customer_sell_price_amount, soi.final_price_amount, soi.unit_sell_price_amount, 0)
      * coalesce(soi.confirmed_quantity, 0)
    ),
    0
  )
  into v_items_resell_delivered
  from public.shop_order_items soi
  where soi.order_id = p_order_id;

  v_recipient_charge_total :=
    case when not coalesce(v_order.deduct_delivery_from_margin, false)
      then coalesce(v_order.delivery_charge_amount, 0) else 0 end +
    case when not coalesce(v_order.deduct_cod_from_margin, false)
      then coalesce(v_order.cod_charge_amount, 0) else 0 end +
    case when not coalesce(v_order.deduct_print_from_margin, false)
      then coalesce(v_order.print_charge_amount, 0) else 0 end +
    case when not coalesce(v_order.deduct_packing_from_margin, false)
      then coalesce(v_order.packing_charge_amount, 0) else 0 end;

  v_cod_collect_amount :=
    v_items_resell_delivered + v_recipient_charge_total - coalesce(v_order.discount_amount, 0);

  update public.shop_orders
  set cod_collect_amount = v_cod_collect_amount, updated_at = now()
  where id = p_order_id;

  return v_cod_collect_amount;
end;
$$;


ALTER FUNCTION "public"."recompute_dropship_cod_collect_amount"("p_order_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recompute_global_invoice_payment_status"("p_global_invoice_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_total numeric(12,2);
  v_paid numeric(12,2);
  v_written_off numeric(12,2);
  v_due numeric(12,2);
begin
  select total_amount into v_total from public.sales_invoices where id = p_global_invoice_id for update;
  if not found then return; end if;

  select coalesce(sum(amount), 0.00) into v_paid
  from public.invoice_payments where global_invoice_id = p_global_invoice_id;

  select coalesce(sum(amount), 0.00) into v_written_off
  from public.invoice_write_offs where invoice_id = p_global_invoice_id;

  v_due := greatest(coalesce(v_total, 0.00) - v_paid - v_written_off, 0.00);

  update public.sales_invoices
  set
    paid_amount = v_paid,
    written_off_amount = v_written_off,
    due_amount = v_due,
    payment_status = case
      when v_due = 0.00 and v_written_off > 0.00 then 'settled_with_write_off'
      when v_due = 0.00 and v_paid > 0.00 then 'paid'
      when v_paid > 0.00 or v_written_off > 0.00 then 'partially_paid'
      else 'due'
    end,
    updated_at = now()
  where id = p_global_invoice_id;
end;
$$;


ALTER FUNCTION "public"."recompute_global_invoice_payment_status"("p_global_invoice_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recompute_global_invoice_totals"("p_invoice_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_invoice public.global_invoices;
  v_subtotal numeric(12,2) := 0;
  v_charges numeric(12,2) := 0;
  v_discount numeric(12,2) := 0;
  v_paid numeric(12,2) := 0;
  v_total numeric(12,2) := 0;
begin
  select * into v_invoice from public.global_invoices where id = p_invoice_id;
  if v_invoice.id is null then return; end if;

  select coalesce(sum(line_total_amount), 0)
  into v_subtotal
  from public.global_invoice_items
  where invoice_id = p_invoice_id;

  v_charges := coalesce(v_invoice.shipping_charge, 0)
             + coalesce(v_invoice.cod_charge_amount, 0)
             + coalesce(v_invoice.wrapping_charge, 0)
             + coalesce(v_invoice.print_charge, 0);

  v_discount := coalesce(v_invoice.discount_amount, 0);
  v_paid := coalesce(v_invoice.paid_amount, 0);

  v_total := greatest(v_subtotal + v_charges - v_discount, 0);

  update public.sales_invoices
  set
    subtotal_amount = v_subtotal,
    total_amount = v_total,
    due_amount = greatest(v_total - v_paid, 0),
    updated_at = now()
  where id = p_invoice_id;
end;
$$;


ALTER FUNCTION "public"."recompute_global_invoice_totals"("p_invoice_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reconcile_single_order_remittance"("p_order_id" bigint, "p_courier_charge" numeric DEFAULT 0.00) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_order public.shop_orders;
  v_invoice public.global_invoices;
  v_payment_id bigint;
  v_cod numeric(12,2) := 0.00;
  v_charge numeric(12,2) := 0.00;
  v_net_remitted numeric(12,2) := 0.00;
begin
  select * into v_order
  from public.shop_orders
  where id = p_order_id for update;

  if v_order.id is null then
    raise exception 'Shop order #% not found', p_order_id;
  end if;

  if v_order.status <> 'delivered' then
    raise exception 'Order #% cannot be remitted because current status is "%" (must be "delivered")', v_order.order_no, v_order.status;
  end if;

  -- Permission check
  if not (
    public.is_superadmin()
    or exists (
      select 1 from public.memberships m
      where m.tenant_id = v_order.tenant_id
        and lower(trim(m.email)) = public.current_user_email()
        and m.is_active = true
        and m.role in ('admin', 'staff')
    )
  ) then
    raise exception 'Permission denied: Staff or Admin role required for tenant %', v_order.tenant_id;
  end if;

  -- Ensure global invoice exists or create it
  if v_order.global_invoice_id is null then
    perform public.create_dual_invoice_from_dropship_order(p_order_id);
    select * into v_order from public.shop_orders where id = p_order_id for update;
  end if;

  if v_order.global_invoice_id is null then
    raise exception 'Failed to resolve accounting invoice for order #%', v_order.order_no;
  end if;

  select * into v_invoice
  from public.global_invoices
  where id = v_order.global_invoice_id for update;

  v_cod := coalesce(v_order.cod_collect_amount, v_invoice.total_amount, 0.00);
  v_charge := coalesce(p_courier_charge, 0.00);
  v_net_remitted := greatest(v_cod - v_charge, 0.00);

  -- Record global payment with valid 'bank' method
  insert into public.global_payments (
    tenant_id,
    billing_profile_id,
    collection_source,
    amount,
    unallocated_amount,
    payment_date,
    method,
    reference,
    note
  )
  values (
    v_order.tenant_id,
    v_invoice.billing_profile_id,
    coalesce(v_invoice.collection_source, 'recipient'),
    v_net_remitted,
    0.00,
    current_date,
    'bank',
    coalesce(v_order.courier_awb_number, v_order.order_no),
    'Single-order inline remittance for order #' || v_order.order_no
  )
  returning id into v_payment_id;

  -- Allocate invoice payment
  insert into public.invoice_payments (tenant_id, payment_id, global_invoice_id, amount)
  values (v_order.tenant_id, v_payment_id, v_order.global_invoice_id, v_net_remitted);

  -- Update global invoice paid amount & status
  update public.global_invoices
  set
    paid_amount = coalesce(paid_amount, 0.00) + v_net_remitted,
    updated_at = now()
  where id = v_order.global_invoice_id;

  perform public.recompute_global_invoice_payment_status(v_order.global_invoice_id);

  -- Update shop order status to payment_received
  update public.shop_orders
  set
    status = 'payment_received'::public.shop_order_status,
    courier_remittance_ref = coalesce(courier_remittance_ref, 'SINGLE-REMIT-' || v_order.order_no),
    updated_at = now()
  where id = v_order.id;

  return jsonb_build_object(
    'success', true,
    'order_id', p_order_id,
    'new_status', 'payment_received',
    'net_remitted', v_net_remitted
  );
end;
$$;


ALTER FUNCTION "public"."reconcile_single_order_remittance"("p_order_id" bigint, "p_courier_charge" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_batch_customer_payment"("p_tenant_id" bigint, "p_customer_group_id" bigint DEFAULT NULL::bigint, "p_billing_profile_id" bigint DEFAULT NULL::bigint, "p_amount" numeric DEFAULT 0, "p_payment_date" "date" DEFAULT CURRENT_DATE, "p_method" "text" DEFAULT 'bank_transfer'::"text", "p_reference" "text" DEFAULT NULL::"text", "p_note" "text" DEFAULT NULL::"text", "p_allocations" "jsonb" DEFAULT '[]'::"jsonb", "p_write_offs" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_parent_id bigint;
  v_payment public.global_payments;
  v_alloc jsonb;
  v_wo jsonb;
  v_invoice_id bigint;
  v_alloc_amount numeric(12,2);
  v_wo_amount numeric(12,2);
  v_wo_reason text;
  v_wo_note text;
  v_total_alloc numeric(12,2) := 0.00;
  v_total_wo numeric(12,2) := 0.00;
  v_primary_bp_id bigint := p_billing_profile_id;
begin
  if p_tenant_id is null then
    raise exception 'Tenant is required.';
  end if;
  if coalesce(p_amount, 0) < 0 then
    raise exception 'Payment amount cannot be negative.';
  end if;

  v_parent_id := public.resolve_parent_tenant_id(p_tenant_id);

  -- If customer group provided but no billing profile, resolve first billing profile
  if v_primary_bp_id is null and p_customer_group_id is not null then
    select id into v_primary_bp_id
    from public.billing_profiles
    where customer_group_id = p_customer_group_id
    limit 1;
  end if;

  -- Create Payment record
  insert into public.global_payments (
    tenant_id,
    customer_group_id,
    billing_profile_id,
    amount,
    unallocated_amount,
    payment_date,
    method,
    reference,
    note
  )
  values (
    p_tenant_id,
    p_customer_group_id,
    v_primary_bp_id,
    coalesce(p_amount, 0.00),
    coalesce(p_amount, 0.00),
    coalesce(p_payment_date, current_date),
    coalesce(p_method, 'bank_transfer'),
    p_reference,
    p_note
  )
  returning * into v_payment;

  -- Process Allocations
  if jsonb_typeof(coalesce(p_allocations, '[]'::jsonb)) = 'array' then
    for v_alloc in select * from jsonb_array_elements(p_allocations)
    loop
      v_invoice_id := (v_alloc->>'invoice_id')::bigint;
      v_alloc_amount := coalesce((v_alloc->>'amount')::numeric, 0.00);

      if v_invoice_id is not null and v_alloc_amount > 0.00 then
        insert into public.invoice_payments (
          tenant_id,
          payment_id,
          global_invoice_id,
          amount
        )
        values (
          p_tenant_id,
          v_payment.id,
          v_invoice_id,
          v_alloc_amount
        );

        perform public.recompute_global_invoice_payment_status(v_invoice_id);
        v_total_alloc := v_total_alloc + v_alloc_amount;
      end if;
    end loop;
  end if;

  -- Process Write-Offs
  if jsonb_typeof(coalesce(p_write_offs, '[]'::jsonb)) = 'array' then
    for v_wo in select * from jsonb_array_elements(p_write_offs)
    loop
      v_invoice_id := (v_wo->>'invoice_id')::bigint;
      v_wo_amount := coalesce((v_wo->>'amount')::numeric, 0.00);
      v_wo_reason := coalesce(v_wo->>'reason', 'dispute_settlement');
      v_wo_note := v_wo->>'note';

      if v_invoice_id is not null and v_wo_amount > 0.00 then
        insert into public.invoice_write_offs (
          tenant_id,
          parent_tenant_id,
          invoice_id,
          payment_id,
          amount,
          reason,
          note,
          approved_by
        )
        values (
          p_tenant_id,
          v_parent_id,
          v_invoice_id,
          v_payment.id,
          v_wo_amount,
          v_wo_reason,
          v_wo_note,
          auth.uid()
        );

        perform public.recompute_global_invoice_payment_status(v_invoice_id);
        v_total_wo := v_total_wo + v_wo_amount;
      end if;
    end loop;
  end if;

  if v_total_alloc > coalesce(p_amount, 0.00) then
    raise exception 'Total allocations (% BDT) exceed payment received (% BDT).', v_total_alloc, p_amount;
  end if;

  -- Update unallocated amount
  update public.global_payments
  set unallocated_amount = coalesce(p_amount, 0.00) - v_total_alloc
  where id = v_payment.id;

  -- Universal Wallet Entries (if amount > 0)
  if coalesce(p_amount, 0.00) > 0.00 then
    -- 1. Tenant Cash Receipt
    perform public.record_ledger_transaction(
      p_parent_tenant_id => v_parent_id,
      p_operating_tenant_id => p_tenant_id,
      p_entity_type => 'tenant',
      p_entity_id => v_parent_id,
      p_type => 'credit',
      p_amount => p_amount,
      p_currency_code => 'BDT',
      p_exchange_rate => 1.000000,
      p_source_type => 'sales_invoice',
      p_source_id => v_payment.id::text,
      p_metadata => jsonb_build_object(
        'section', 'payments',
        'purpose', 'batch_payment_received',
        'payment_id', v_payment.id,
        'customer_group_id', p_customer_group_id,
        'reference', p_reference
      )
    );

    -- 2. Customer AR Reduction (if billing profile linked)
    if v_primary_bp_id is not null then
      perform public.record_ledger_transaction(
        p_parent_tenant_id => v_parent_id,
        p_operating_tenant_id => p_tenant_id,
        p_entity_type => 'customer',
        p_entity_id => v_primary_bp_id,
        p_type => 'credit',
        p_amount => p_amount,
        p_currency_code => 'BDT',
        p_exchange_rate => 1.000000,
        p_source_type => 'sales_invoice',
        p_source_id => v_payment.id::text,
        p_metadata => jsonb_build_object(
          'section', 'payments',
          'purpose', 'customer_ar_reduction',
          'payment_id', v_payment.id,
          'reference', p_reference
        )
      );
    end if;
  end if;

  return jsonb_build_object(
    'payment_id', v_payment.id,
    'total_amount', p_amount,
    'total_allocated', v_total_alloc,
    'total_written_off', v_total_wo,
    'unallocated_amount', coalesce(p_amount, 0.00) - v_total_alloc,
    'payment_date', v_payment.payment_date,
    'reference', v_payment.reference
  );
end;
$$;


ALTER FUNCTION "public"."record_batch_customer_payment"("p_tenant_id" bigint, "p_customer_group_id" bigint, "p_billing_profile_id" bigint, "p_amount" numeric, "p_payment_date" "date", "p_method" "text", "p_reference" "text", "p_note" "text", "p_allocations" "jsonb", "p_write_offs" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_dropship_courier_bank_transfer"("p_tenant_id" bigint, "p_order_id" bigint, "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_order public.shop_orders;
  v_settlement public.dropship_order_settlements;
  v_remit jsonb;
  v_profit jsonb;
  v_net_amount numeric(15,2);
  v_courier_charge numeric(15,2);
  v_collected_cod numeric(15,2);
  v_remittance_ref text;
  v_bank_trx_id text;
begin
  if not public.is_tenant_staff(p_tenant_id) then
    raise exception 'access denied';
  end if;

  select * into v_order
  from public.shop_orders
  where id = p_order_id
  for update;

  if not found then
    raise exception 'order not found';
  end if;

  if v_order.tenant_id is distinct from p_tenant_id
     and v_order.parent_tenant_id is distinct from p_tenant_id then
    raise exception 'order not found';
  end if;

  select * into v_settlement
  from public.dropship_order_settlements
  where shop_order_id = p_order_id;

  if not found then
    raise exception 'settlement is required before recording courier bank transfer';
  end if;

  if v_settlement.remittance_at is not null then
    v_profit := public.transfer_dropship_reseller_profit(p_tenant_id, p_order_id, '{}'::jsonb);
    return jsonb_build_object(
      'success', true,
      'already_recorded', true,
      'message', 'Courier bank transfer already recorded',
      'order_id', p_order_id,
      'reseller_profit', v_profit
    );
  end if;

  if v_order.status not in ('delivered', 'payment_received') then
    raise exception 'bank transfer requires delivered or payment_received status (current: %)', v_order.status;
  end if;

  v_remittance_ref := nullif(trim(coalesce(p_payload->>'remittance_ref', '')), '');
  v_bank_trx_id := nullif(trim(coalesce(p_payload->>'bank_trx_id', '')), '');

  if v_remittance_ref is null then
    raise exception 'remittance_ref is required';
  end if;

  v_collected_cod := coalesce(
    v_settlement.collected_cod_amount,
    v_order.cod_collect_amount,
    0
  );

  v_net_amount := coalesce((p_payload->>'net_amount')::numeric, 0);

  if v_net_amount <= 0 then
    raise exception 'net_amount must be positive';
  end if;

  if v_collected_cod > 0 and v_net_amount > (v_collected_cod + 0.01) then
    raise exception 'Net remittance (%) exceeds collected COD (%)', v_net_amount, v_collected_cod;
  end if;

  v_courier_charge := greatest(v_collected_cod - v_net_amount, 0);

  v_remit := public.record_dropship_courier_remittance(
    p_order_id,
    v_net_amount,
    v_remittance_ref,
    v_bank_trx_id,
    null,
    'bank_transfer',
    null,
    v_courier_charge
  );

  if coalesce(v_remit->>'success', 'false') <> 'true' then
    return v_remit;
  end if;

  update public.dropship_order_settlements
  set remittance_at = now(), updated_at = now()
  where shop_order_id = p_order_id;

  update public.shop_orders
  set
    courier_remittance_ref = coalesce(v_remittance_ref, courier_remittance_ref),
    courier_bank_trx_id = coalesce(v_bank_trx_id, courier_bank_trx_id),
    updated_at = now()
  where id = p_order_id;

  v_profit := public.transfer_dropship_reseller_profit(p_tenant_id, p_order_id, '{}'::jsonb);

  if coalesce(v_profit->>'success', 'false') <> 'true'
     and coalesce(v_profit->>'skipped', 'false') <> 'true'
     and coalesce(v_profit->>'already_recorded', 'false') <> 'true' then
    return v_profit;
  end if;

  return jsonb_build_object(
    'success', true,
    'message', 'Courier bank transfer recorded; invoice paid and merchant profit credited',
    'order_id', p_order_id,
    'net_amount', v_net_amount,
    'courier_charge', v_courier_charge,
    'collected_cod', v_collected_cod,
    'remittance', v_remit,
    'reseller_profit', v_profit
  );
end;
$$;


ALTER FUNCTION "public"."record_dropship_courier_bank_transfer"("p_tenant_id" bigint, "p_order_id" bigint, "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_dropship_courier_remittance"("p_order_id" bigint, "p_net_amount" numeric, "p_remittance_ref" "text", "p_bank_trx_id" "text" DEFAULT NULL::"text", "p_payment_date" "date" DEFAULT NULL::"date", "p_method" "text" DEFAULT 'cash'::"text", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  return public.record_dropship_courier_remittance(
    p_order_id,
    p_net_amount,
    p_remittance_ref,
    p_bank_trx_id,
    p_payment_date,
    p_method,
    p_note,
    0.00
  );
end;
$$;


ALTER FUNCTION "public"."record_dropship_courier_remittance"("p_order_id" bigint, "p_net_amount" numeric, "p_remittance_ref" "text", "p_bank_trx_id" "text", "p_payment_date" "date", "p_method" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_dropship_courier_remittance"("p_order_id" bigint, "p_net_amount" numeric, "p_remittance_ref" "text", "p_bank_trx_id" "text" DEFAULT NULL::"text", "p_payment_date" "date" DEFAULT NULL::"date", "p_method" "text" DEFAULT 'cash'::"text", "p_note" "text" DEFAULT NULL::"text", "p_courier_charge" numeric DEFAULT 0.00) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_order record;
  v_invoice public.global_invoices;
  v_parent_tenant_id bigint;
  v_payment_id bigint;
  v_ref text;
  v_cod numeric(12,2);
  v_charge numeric(12,2);
  v_net numeric(12,2);
  v_invoice_due numeric(12,2);
  v_invoice_pay numeric(12,2);
  v_remainder numeric(12,2);
  v_already_remitted boolean := false;
begin
  select * into v_order from public.shop_orders where id = p_order_id for update;
  if v_order.id is null then
    raise exception 'Order not found';
  end if;

  if v_order.shop_type_snapshot <> 'dropship' then
    raise exception 'Order is not a dropship order';
  end if;

  if v_order.status not in ('delivered', 'payment_received') then
    raise exception 'Courier remittance requires order status delivered or payment_received (current: %)', v_order.status;
  end if;

  if v_order.global_invoice_id is null then
    raise exception 'Accounting invoice is required before recording courier remittance';
  end if;

  v_parent_tenant_id := public.resolve_parent_tenant_id(v_order.tenant_id);

  select exists (
    select 1 from public.universal_wallet_ledger
    where parent_tenant_id = v_parent_tenant_id
      and entity_type = 'tenant'
      and source_type = 'shop_order'
      and source_id = p_order_id::text
      and metadata->>'purpose' = 'tenant_remittance_received'
  ) into v_already_remitted;

  if v_already_remitted then
    return jsonb_build_object(
      'success', true,
      'already_recorded', true,
      'invoice_id', v_order.global_invoice_id,
      'order_id', p_order_id,
      'status', v_order.status
    );
  end if;

  v_ref := nullif(trim(coalesce(p_remittance_ref, '')), '');
  if v_ref is null then
    raise exception 'Remittance reference is required';
  end if;

  v_net := coalesce(p_net_amount, 0.00);
  v_charge := coalesce(p_courier_charge, 0.00);

  select coalesce(s.collected_cod_amount, v_order.cod_collect_amount, 0.00)
  into v_cod
  from public.dropship_order_settlements s
  where s.shop_order_id = p_order_id;

  if not found then
    v_cod := coalesce(v_order.cod_collect_amount, 0.00);
  end if;

  if v_net <= 0.00 then
    raise exception 'Net remittance amount must be positive';
  end if;

  if v_charge < 0.00 then
    raise exception 'Courier charge cannot be negative';
  end if;

  if v_cod > 0 and (v_net + v_charge) > (v_cod + 0.01) then
    raise exception 'Remittance net (%) + charge (%) exceeds COD collect (%)', v_net, v_charge, v_cod;
  end if;

  if not (
    public.user_can_manage_parent_tenant(v_parent_tenant_id)
    or exists (
      select 1 from public.memberships m
      where m.tenant_id = v_order.tenant_id
        and lower(trim(m.email)) = public.current_user_email()
        and m.is_active = true
        and m.role in ('admin', 'staff')
    )
  ) then
    raise exception 'Permission denied: Staff or Admin role required';
  end if;

  select * into v_invoice from public.global_invoices where id = v_order.global_invoice_id for update;
  if v_invoice.id is null then
    raise exception 'Invoice not found';
  end if;

  if v_invoice.invoice_status <> 'issued'::public.global_invoice_status then
    raise exception 'Merchant bill must be issued before remittance (current: %)', v_invoice.invoice_status;
  end if;

  if v_invoice.billing_profile_id is null then
    raise exception 'Merchant billing profile is required on the invoice';
  end if;

  v_invoice_due := greatest(coalesce(v_invoice.total_amount, 0.00) - coalesce(v_invoice.paid_amount, 0.00), 0.00);
  v_invoice_pay := least(v_net, v_invoice_due);
  v_remainder := greatest(v_net - v_invoice_pay, 0.00);

  perform public.process_dropship_courier_remittance_uwl(
    p_order_id => p_order_id,
    p_net_amount => v_net,
    p_courier_charge => v_charge,
    p_remittance_ref => v_ref
  );

  update public.universal_wallet_ledger
  set metadata = metadata || jsonb_build_object(
    'invoice_allocated', v_invoice_pay,
    'merchant_funds_held', v_remainder
  )
  where parent_tenant_id = v_parent_tenant_id
    and entity_type = 'tenant'
    and source_type = 'shop_order'
    and source_id = p_order_id::text
    and metadata->>'purpose' = 'tenant_remittance_received';

  insert into public.global_payments (
    tenant_id,
    billing_profile_id,
    collection_source,
    amount,
    unallocated_amount,
    payment_date,
    method,
    reference,
    note
  )
  values (
    v_invoice.tenant_id,
    v_invoice.billing_profile_id,
    'billing_profile'::public.collection_source_type,
    v_net,
    v_remainder,
    coalesce(p_payment_date, current_date),
    coalesce(nullif(trim(p_method), ''), 'cash'),
    v_ref,
    coalesce(
      nullif(trim(p_note), ''),
      'Courier remittance order #' || v_order.order_no
        || coalesce(' bank:' || nullif(trim(p_bank_trx_id), ''), '')
    )
  )
  returning id into v_payment_id;

  if v_invoice_pay > 0 then
    insert into public.invoice_payments (tenant_id, payment_id, global_invoice_id, amount)
    values (v_invoice.tenant_id, v_payment_id, v_order.global_invoice_id, v_invoice_pay);

    update public.global_invoices
    set
      paid_amount = coalesce(paid_amount, 0.00) + v_invoice_pay,
      note = coalesce(nullif(trim(p_note), ''), note),
      updated_at = now()
    where id = v_order.global_invoice_id;

    perform public.recompute_global_invoice_payment_status(v_order.global_invoice_id);
  end if;

  if v_remainder > 0 and not exists (
    select 1
    from public.universal_wallet_ledger u
    where u.parent_tenant_id = v_parent_tenant_id
      and u.source_type = 'shop_order'
      and u.source_id = p_order_id::text
      and u.entity_type in ('middleman', 'customer')
      and u.entity_id = v_invoice.billing_profile_id
      and u.type = 'credit'
      and coalesce(u.metadata->>'transaction_type', '') = 'dropship_profit'
  ) then
    perform public.record_ledger_transaction(
      p_parent_tenant_id => v_parent_tenant_id,
      p_operating_tenant_id => v_order.tenant_id,
      p_entity_type => 'customer',
      p_entity_id => v_invoice.billing_profile_id,
      p_type => 'credit',
      p_amount => v_remainder,
      p_currency_code => 'BDT',
      p_exchange_rate => 1.000000,
      p_source_type => 'shop_order',
      p_source_id => p_order_id::text,
      p_metadata => jsonb_build_object(
        'section', 'payout_earned',
        'transaction_type', 'dropship_profit',
        'label', 'Dropship profit from remittance remainder',
        'order_no', v_order.order_no,
        'order_id', p_order_id,
        'shop_order_id', p_order_id::text,
        'invoice_id', v_order.global_invoice_id,
        'remittance_ref', v_ref,
        'net_remitted', v_net,
        'invoice_allocated', v_invoice_pay
      )
    );
  end if;

  update public.shop_orders
  set
    status = 'payment_received'::public.shop_order_status,
    courier_remittance_ref = v_ref,
    courier_bank_trx_id = coalesce(nullif(trim(p_bank_trx_id), ''), courier_bank_trx_id),
    payout_settlement_status = case when v_remainder > 0 then 'paid' else payout_settlement_status end,
    updated_at = now()
  where id = p_order_id;

  return jsonb_build_object(
    'success', true,
    'invoice_id', v_order.global_invoice_id,
    'payment_id', v_payment_id,
    'order_id', p_order_id,
    'status', 'payment_received',
    'net_amount', v_net,
    'courier_charge', v_charge,
    'invoice_allocated', v_invoice_pay,
    'merchant_remainder', v_remainder
  );
end;
$$;


ALTER FUNCTION "public"."record_dropship_courier_remittance"("p_order_id" bigint, "p_net_amount" numeric, "p_remittance_ref" "text", "p_bank_trx_id" "text", "p_payment_date" "date", "p_method" "text", "p_note" "text", "p_courier_charge" numeric) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."investor_transactions" (
    "id" bigint NOT NULL,
    "tenant_id" bigint NOT NULL,
    "investor_id" bigint NOT NULL,
    "amount" numeric(12,2) NOT NULL,
    "date" "date" DEFAULT CURRENT_DATE NOT NULL,
    "method" "public"."investor_payment_method" NOT NULL,
    "type" "public"."investor_transaction_type" NOT NULL,
    "note" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "investor_transactions_amount_check" CHECK (("amount" > (0)::numeric))
);


