    p_metadata => jsonb_build_object(
      'section', 'investor_capital',
      'purpose', 'investor_withdrawal_debit',
      'transaction_type', 'withdrawal_paid',
      'label', 'Capital Withdrawal Paid',
      'notes', p_note
    )
  );

  -- 2. Debit Tenant Cash (cash outflow from platform)
  perform public.record_ledger_transaction(
    p_tenant_id => p_tenant_id,
    p_entity_type => 'tenant',
    p_entity_id => p_tenant_id,
    p_type => 'debit',
    p_amount => p_amount,
    p_currency_code => 'BDT',
    p_exchange_rate => 1.000000,
    p_source_type => 'payout',
    p_source_id => v_row.id::text,
    p_metadata => jsonb_build_object(
      'section', 'investor_capital',
      'purpose', 'tenant_investor_cash_outflow',
      'transaction_type', 'withdrawal_paid',
      'label', 'Investor Withdrawal Outflow',
      'investor_id', p_investor_id,
      'notes', p_note
    )
  );

  return v_row;
end;
$$;


ALTER FUNCTION "public"."record_investor_withdrawal_paid"("p_tenant_id" bigint, "p_investor_id" bigint, "p_amount" numeric, "p_date" "date", "p_method" "public"."investor_payment_method", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_ledger_transaction"("p_parent_tenant_id" bigint, "p_operating_tenant_id" bigint, "p_entity_type" "text", "p_entity_id" bigint, "p_type" "text", "p_amount" numeric, "p_currency_code" "text" DEFAULT 'BDT'::"text", "p_exchange_rate" numeric DEFAULT 1.000000, "p_source_type" "text" DEFAULT 'adjustment'::"text", "p_source_id" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb", "p_target_bucket" "text" DEFAULT 'available'::"text", "p_allow_overdraft" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_account_id bigint;
  v_avail numeric(18,4);
  v_pend numeric(18,4);
  v_lock numeric(18,4);
  v_base_amount numeric(18,4);
  v_new_balance numeric(18,4);
  v_ledger_entry jsonb;
  v_ledger_id uuid;
  v_entity_id bigint;
BEGIN
  IF p_amount <= 0 THEN
    RAISE EXCEPTION 'Transaction amount must be greater than zero.';
  END IF;

  IF p_type NOT IN ('credit', 'debit') THEN
    RAISE EXCEPTION 'Transaction type must be credit or debit.';
  END IF;

  IF p_target_bucket NOT IN ('available', 'pending', 'locked') THEN
    RAISE EXCEPTION 'Target bucket must be available, pending, or locked.';
  END IF;

  v_entity_id := p_entity_id;
  IF p_entity_type = 'tenant' AND v_entity_id IS DISTINCT FROM p_parent_tenant_id THEN
    v_entity_id := p_parent_tenant_id;
  END IF;

  INSERT INTO public.wallet_accounts (
    tenant_id, parent_tenant_id, entity_type, entity_id, currency_code,
    available_balance, pending_balance, locked_balance
  )
  VALUES (
    p_parent_tenant_id, p_parent_tenant_id, p_entity_type, v_entity_id,
    coalesce(p_currency_code, 'BDT'), 0.0000, 0.0000, 0.0000
  )
  ON CONFLICT (parent_tenant_id, entity_type, entity_id, currency_code)
  DO UPDATE SET updated_at = now()
  RETURNING id, available_balance, pending_balance, locked_balance
  INTO v_account_id, v_avail, v_pend, v_lock;

  SELECT available_balance, pending_balance, locked_balance
  INTO v_avail, v_pend, v_lock
  FROM public.wallet_accounts
  WHERE id = v_account_id
  FOR UPDATE;

  IF p_target_bucket = 'available' THEN
    IF p_type = 'credit' THEN
      v_avail := v_avail + p_amount;
    ELSE
      IF v_avail < p_amount AND NOT coalesce(p_allow_overdraft, false) THEN
        RAISE EXCEPTION 'Insufficient available balance (Available: %, Requested debit: %).', v_avail, p_amount;
      END IF;
      v_avail := v_avail - p_amount;
    END IF;
    v_new_balance := v_avail;
  ELSIF p_target_bucket = 'pending' THEN
    IF p_type = 'credit' THEN
      v_pend := v_pend + p_amount;
    ELSE
      v_pend := v_pend - p_amount;
    END IF;
    v_new_balance := v_pend;
  ELSIF p_target_bucket = 'locked' THEN
    IF p_type = 'credit' THEN
      v_lock := v_lock + p_amount;
    ELSE
      v_lock := v_lock - p_amount;
    END IF;
    v_new_balance := v_lock;
  END IF;

  UPDATE public.wallet_accounts
  SET
    available_balance = v_avail,
    pending_balance = v_pend,
    locked_balance = v_lock,
    tenant_id = p_parent_tenant_id,
    updated_at = now()
  WHERE id = v_account_id;

  v_base_amount := p_amount * coalesce(p_exchange_rate, 1.000000);

  INSERT INTO public.universal_wallet_ledger (
    tenant_id,
    parent_tenant_id,
    operating_tenant_id,
    entity_type,
    entity_id,
    type,
    amount,
    currency_code,
    exchange_rate,
    base_amount,
    balance_after,
    source_type,
    source_id,
    metadata
  )
  VALUES (
    p_parent_tenant_id,
    p_parent_tenant_id,
    p_operating_tenant_id,
    p_entity_type,
    v_entity_id,
    p_type,
    p_amount,
    coalesce(p_currency_code, 'BDT'),
    coalesce(p_exchange_rate, 1.000000),
    v_base_amount,
    v_new_balance,
    coalesce(p_source_type, 'adjustment'),
    p_source_id,
    coalesce(p_metadata, '{}'::jsonb) || jsonb_build_object('target_bucket', p_target_bucket)
  )
  RETURNING id INTO v_ledger_id;

  SELECT jsonb_build_object(
    'id', id,
    'parent_tenant_id', parent_tenant_id,
    'operating_tenant_id', operating_tenant_id,
    'tenant_id', parent_tenant_id,
    'entity_type', entity_type,
    'entity_id', entity_id,
    'type', type,
    'amount', amount,
    'currency_code', currency_code,
    'exchange_rate', exchange_rate,
    'base_amount', base_amount,
    'balance_after', balance_after,
    'source_type', source_type,
    'source_id', source_id,
    'metadata', metadata,
    'created_at', created_at
  ) INTO v_ledger_entry
  FROM public.universal_wallet_ledger
  WHERE id = v_ledger_id;

  RETURN v_ledger_entry;
END;
$$;


ALTER FUNCTION "public"."record_ledger_transaction"("p_parent_tenant_id" bigint, "p_operating_tenant_id" bigint, "p_entity_type" "text", "p_entity_id" bigint, "p_type" "text", "p_amount" numeric, "p_currency_code" "text", "p_exchange_rate" numeric, "p_source_type" "text", "p_source_id" "text", "p_metadata" "jsonb", "p_target_bucket" "text", "p_allow_overdraft" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_recipient_invoice_collection"("p_global_invoice_id" bigint, "p_amount" numeric, "p_payment_date" "date" DEFAULT NULL::"date", "p_method" "text" DEFAULT 'cash'::"text", "p_reference" "text" DEFAULT NULL::"text", "p_note" "text" DEFAULT NULL::"text") RETURNS "public"."sales_invoices"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_invoice public.global_invoices;
  v_payment_id bigint;
begin
  select * into v_invoice from public.global_invoices where id = p_global_invoice_id for update;
  if v_invoice.id is null then raise exception 'invoice not found'; end if;
  if v_invoice.collection_source <> 'recipient'::public.collection_source_type then
    raise exception 'This invoice does not collect from recipient.';
  end if;
  if coalesce(p_amount, 0.00) <= 0.00 then raise exception 'Amount must be positive.'; end if;

  insert into public.global_payments (
    tenant_id,
    billing_profile_id,
    collection_source,
    amount,
    unallocated_amount,
    payment_date,
    method,
    reference,
    note
  )
  values (
    v_invoice.tenant_id,
    null,
    'recipient'::public.collection_source_type,
    p_amount,
    0.00,
    coalesce(p_payment_date, current_date),
    p_method,
    p_reference,
    nullif(trim(p_note), '')
  )
  returning id into v_payment_id;

  insert into public.invoice_payments (tenant_id, payment_id, global_invoice_id, amount)
  values (v_invoice.tenant_id, v_payment_id, p_global_invoice_id, p_amount);

  update public.global_invoices
  set
    paid_amount = coalesce(paid_amount, 0.00) + p_amount,
    note = coalesce(nullif(trim(p_note), ''), note),
    updated_at = now()
  where id = p_global_invoice_id
  returning * into v_invoice;

  perform public.recompute_global_invoice_payment_status(p_global_invoice_id);

  -- Record Tenant Cash Credit for direct cash collection
  perform public.record_ledger_transaction(
    p_tenant_id => v_invoice.tenant_id,
    p_entity_type => 'tenant',
    p_entity_id => v_invoice.tenant_id,
    p_type => 'credit',
    p_amount => p_amount,
    p_currency_code => 'BDT',
    p_exchange_rate => 1.000000,
    p_source_type => 'sales_invoice',
    p_source_id => p_global_invoice_id::text,
    p_metadata => jsonb_build_object(
      'section', 'payments',
      'purpose', 'recipient_cash_collection',
      'transaction_type', 'cash_collected',
      'label', 'Direct Cash Collection',
      'payment_id', v_payment_id,
      'invoice_id', p_global_invoice_id,
      'invoice_no', v_invoice.invoice_no
    )
  );

  return v_invoice;
end;
$$;


ALTER FUNCTION "public"."record_recipient_invoice_collection"("p_global_invoice_id" bigint, "p_amount" numeric, "p_payment_date" "date", "p_method" "text", "p_reference" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_thrift_cod_remittance"("p_tenant_id" bigint, "p_invoice_id" bigint, "p_remitted_amount" numeric, "p_actor" "text", "p_remitted_at" timestamp with time zone DEFAULT "now"(), "p_remittance_ref" "text" DEFAULT NULL::"text", "p_notes" "text" DEFAULT NULL::"text", "p_outcome" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_invoice public.thrift_sales_invoices%ROWTYPE;
  v_remitted NUMERIC(12,2);
  v_outcome TEXT;
  v_payment_status TEXT;
  v_notes TEXT;
BEGIN
  IF NOT (
    public.membership_has_module_action(p_tenant_id, 'thrift_sales', 'edit')
    OR public.membership_has_module_action(p_tenant_id, 'thrift_sales', 'create')
  ) THEN
    RAISE EXCEPTION 'Recording COD remittance requires thrift_sales edit or create permission';
  END IF;

  v_remitted := ROUND(COALESCE(p_remitted_amount, 0.00), 2);
  IF v_remitted < 0 THEN
    RAISE EXCEPTION 'Remitted amount cannot be negative';
  END IF;

  SELECT * INTO v_invoice
  FROM public.thrift_sales_invoices
  WHERE id = p_invoice_id
    AND tenant_id = p_tenant_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Invoice % not found for tenant %', p_invoice_id, p_tenant_id;
  END IF;

  IF upper(trim(COALESCE(v_invoice.sale_channel, ''))) IS DISTINCT FROM 'ONLINE' THEN
    RAISE EXCEPTION
      'Invoice % sale_channel is % — remittance only allowed on ONLINE invoices',
      p_invoice_id,
      v_invoice.sale_channel;
  END IF;

  IF v_invoice.status IS DISTINCT FROM 'ACTIVE' THEN
    RAISE EXCEPTION 'Invoice % is % — remittance only allowed on ACTIVE invoices', p_invoice_id, v_invoice.status;
  END IF;

  IF v_invoice.payment_status IS DISTINCT FROM 'COD_PENDING' THEN
    RAISE EXCEPTION
      'Invoice % payment_status is % — remittance only allowed when COD_PENDING',
      p_invoice_id,
      v_invoice.payment_status;
  END IF;

  v_outcome := upper(trim(COALESCE(p_outcome, '')));
  IF v_outcome = '' THEN
    IF v_invoice.cod_expected IS NULL OR v_remitted >= v_invoice.cod_expected THEN
      v_outcome := 'PAID';
    ELSE
      v_outcome := 'KEEP_PENDING';
    END IF;
  END IF;

  IF v_outcome NOT IN ('PAID', 'KEEP_PENDING', 'WRITTEN_OFF') THEN
    RAISE EXCEPTION 'Invalid outcome % (expected PAID, KEEP_PENDING, or WRITTEN_OFF)', p_outcome;
  END IF;

  IF v_outcome = 'WRITTEN_OFF' AND NULLIF(trim(COALESCE(p_notes, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Notes are required when writing off COD remittance';
  END IF;

  IF v_outcome = 'PAID' THEN
    v_payment_status := 'PAID';
  ELSIF v_outcome = 'WRITTEN_OFF' THEN
    v_payment_status := 'WRITTEN_OFF';
  ELSE
    v_payment_status := 'COD_PENDING';
  END IF;

  v_notes := v_invoice.notes;
  IF NULLIF(trim(p_notes), '') IS NOT NULL THEN
    v_notes := CASE
      WHEN NULLIF(trim(v_notes), '') IS NULL THEN trim(p_notes)
      ELSE trim(v_notes) || E'\n' || trim(p_notes)
    END;
  END IF;

  UPDATE public.thrift_sales_invoices
  SET
    cod_remitted_amount = v_remitted,
    cod_remitted_at = COALESCE(p_remitted_at, NOW()),
    cod_remittance_ref = COALESCE(NULLIF(trim(p_remittance_ref), ''), cod_remittance_ref),
    payment_status = v_payment_status,
    notes = v_notes,
    updated_at = NOW()
  WHERE id = p_invoice_id
    AND tenant_id = p_tenant_id;

  RETURN jsonb_build_object(
    'invoice_id', p_invoice_id,
    'payment_status', v_payment_status,
    'cod_expected', v_invoice.cod_expected,
    'cod_remitted_amount', v_remitted,
    'outcome', v_outcome
  );
END;
$$;


ALTER FUNCTION "public"."record_thrift_cod_remittance"("p_tenant_id" bigint, "p_invoice_id" bigint, "p_remitted_amount" numeric, "p_actor" "text", "p_remitted_at" timestamp with time zone, "p_remittance_ref" "text", "p_notes" "text", "p_outcome" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."record_thrift_cod_remittance"("p_tenant_id" bigint, "p_invoice_id" bigint, "p_remitted_amount" numeric, "p_actor" "text", "p_remitted_at" timestamp with time zone, "p_remittance_ref" "text", "p_notes" "text", "p_outcome" "text") IS 'Record Online COD cash on invoice. Outcomes PAID/KEEP_PENDING/WRITTEN_OFF. No ledger/PnL. WRITTEN_OFF requires notes.';



CREATE OR REPLACE FUNCTION "public"."record_vendor_grn_payable"("p_tenant_id" bigint, "p_vendor_id" bigint, "p_amount" numeric, "p_source_id" "text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_res jsonb;
begin
  if p_tenant_id is null or p_vendor_id is null then
    raise exception 'Tenant ID and Vendor ID are required.';
  end if;
  if coalesce(p_amount, 0) <= 0 then
    raise exception 'GRN payable amount must be positive.';
  end if;

  v_res := public.record_ledger_transaction(
    p_tenant_id => p_tenant_id,
    p_entity_type => 'vendor',
    p_entity_id => p_vendor_id,
    p_type => 'credit',
    p_amount => p_amount,
    p_currency_code => 'BDT',
    p_exchange_rate => 1.000000,
    p_source_type => 'vendor_purchase',
    p_source_id => p_source_id,
    p_metadata => jsonb_build_object(
      'section', 'procurement',
      'purpose', 'vendor_grn_payable',
      'transaction_type', 'vendor_payable',
      'label', 'Vendor Payable (GRN Received)'
    ) || coalesce(p_metadata, '{}'::jsonb)
  );

  return jsonb_build_object('success', true, 'entry', v_res);
end;
$$;


ALTER FUNCTION "public"."record_vendor_grn_payable"("p_tenant_id" bigint, "p_vendor_id" bigint, "p_amount" numeric, "p_source_id" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_vendor_payment_outflow"("p_tenant_id" bigint, "p_vendor_id" bigint, "p_amount" numeric, "p_payment_method" "text" DEFAULT 'bank_transfer'::"text", "p_reference" "text" DEFAULT NULL::"text", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_payment_id text;
  v_vendor_res jsonb;
  v_tenant_res jsonb;
begin
  if p_tenant_id is null or p_vendor_id is null then
    raise exception 'Tenant ID and Vendor ID are required.';
  end if;
  if coalesce(p_amount, 0) <= 0 then
    raise exception 'Vendor payment amount must be positive.';
  end if;

  v_payment_id := 'VP-' || gen_random_uuid()::text;

  -- Leg 1: Debit Vendor AP (reduces vendor payable balance)
  v_vendor_res := public.record_ledger_transaction(
    p_tenant_id => p_tenant_id,
    p_entity_type => 'vendor',
    p_entity_id => p_vendor_id,
    p_type => 'debit',
    p_amount => p_amount,
    p_currency_code => 'BDT',
    p_exchange_rate => 1.000000,
    p_source_type => 'vendor_purchase',
    p_source_id => v_payment_id,
    p_metadata => jsonb_build_object(
      'section', 'vendor_payments',
      'purpose', 'vendor_ap_settlement',
      'transaction_type', 'vendor_payment_paid',
      'label', 'Vendor Payment Settled',
      'payment_method', p_payment_method,
      'reference', p_reference,
      'notes', p_note
    )
  );

  -- Leg 2: Debit Tenant Cash (cash outflow from bank/cash account)
  v_tenant_res := public.record_ledger_transaction(
    p_tenant_id => p_tenant_id,
    p_entity_type => 'tenant',
    p_entity_id => p_tenant_id,
    p_type => 'debit',
    p_amount => p_amount,
    p_currency_code => 'BDT',
    p_exchange_rate => 1.000000,
    p_source_type => 'vendor_purchase',
    p_source_id => v_payment_id,
    p_metadata => jsonb_build_object(
      'section', 'vendor_payments',
      'purpose', 'tenant_vendor_cash_outflow',
      'transaction_type', 'vendor_payment_paid',
      'label', 'Cash Outflow (Vendor Payment)',
      'vendor_id', p_vendor_id,
      'payment_method', p_payment_method,
      'reference', p_reference,
      'notes', p_note
    )
  );

  return jsonb_build_object(
    'success', true,
    'payment_id', v_payment_id,
    'vendor_entry', v_vendor_res,
    'tenant_entry', v_tenant_res
  );
end;
$$;


ALTER FUNCTION "public"."record_vendor_payment_outflow"("p_tenant_id" bigint, "p_vendor_id" bigint, "p_amount" numeric, "p_payment_method" "text", "p_reference" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_wallet_manual_transaction_for_staff"("p_tenant_id" bigint, "p_action_type" "text", "p_primary_entity_type" "text", "p_primary_entity_id" bigint, "p_amount" numeric, "p_currency_code" "text" DEFAULT 'BDT'::"text", "p_exchange_rate" numeric DEFAULT 1.000000, "p_category" "text" DEFAULT NULL::"text", "p_payment_method" "text" DEFAULT NULL::"text", "p_reference_id" "text" DEFAULT NULL::"text", "p_note" "text" DEFAULT NULL::"text", "p_counterparty_entity_type" "text" DEFAULT NULL::"text", "p_counterparty_entity_id" bigint DEFAULT NULL::bigint, "p_target_bucket" "text" DEFAULT 'available'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_books_id bigint;
  v_operating_id bigint;
  v_source_id text;
  v_meta jsonb;
  v_primary_id bigint;
  v_ledger_ids uuid[] := '{}';
  v_entry jsonb;
  v_primary_entity_id bigint;
  v_counterparty_id bigint;
BEGIN
  IF NOT public.wallet_staff_can_edit(p_tenant_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'access denied');
  END IF;

  IF coalesce(p_amount, 0) <= 0 OR coalesce(p_exchange_rate, 0) <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'amount and exchange_rate must be positive');
  END IF;

  v_books_id := public.resolve_parent_tenant_id(p_tenant_id);
  v_operating_id := p_tenant_id;
  v_primary_entity_id := p_primary_entity_id;
  IF p_primary_entity_type = 'tenant' THEN v_primary_entity_id := v_books_id; END IF;

  v_source_id := coalesce(nullif(trim(p_reference_id), ''),
    CASE p_action_type
      WHEN 'pay' THEN 'MAN-PAY-' || gen_random_uuid()::text
      WHEN 'withdraw' THEN 'MAN-WD-' || gen_random_uuid()::text
      WHEN 'deposit' THEN 'MAN-DEP-' || gen_random_uuid()::text
      ELSE 'MAN-CR-' || gen_random_uuid()::text
    END);

  v_meta := jsonb_build_object(
    'section', p_category,
    'method', p_payment_method,
    'trx_id', v_source_id,
    'note', p_note,
    'action_type', p_action_type,
    'transaction_type', 'manual_adjustment',
    'label', initcap(p_action_type),
    'recorded_by', public.current_user_email(),
    'target_bucket', coalesce(p_target_bucket, 'available')
  );

  IF p_action_type IN ('pay', 'credit') AND p_primary_entity_type = 'tenant'
     AND (p_counterparty_entity_type IS NULL OR p_counterparty_entity_id IS NULL) THEN
    RETURN jsonb_build_object('success', false, 'error', 'counterparty required');
  END IF;

  IF p_action_type = 'deposit' THEN
    v_entry := public.record_ledger_transaction(
      v_books_id, v_operating_id, p_primary_entity_type, v_primary_entity_id,
      'credit', p_amount, p_currency_code, p_exchange_rate,
      'adjustment', v_source_id, v_meta, p_target_bucket, false
    );
    v_ledger_ids := array_append(v_ledger_ids, (v_entry->>'id')::uuid);

  ELSIF p_action_type = 'withdraw' THEN
    v_entry := public.record_ledger_transaction(
      v_books_id, v_operating_id, p_primary_entity_type, v_primary_entity_id,
      'debit', p_amount, p_currency_code, p_exchange_rate,
      'payout', v_source_id, v_meta, p_target_bucket, false
    );
    v_ledger_ids := array_append(v_ledger_ids, (v_entry->>'id')::uuid);

  ELSIF p_action_type = 'credit' AND p_primary_entity_type = 'tenant' THEN
    v_counterparty_id := p_counterparty_entity_id;
    v_entry := public.record_ledger_transaction(
      v_books_id, v_operating_id, p_counterparty_entity_type, v_counterparty_id,
      'credit', p_amount, p_currency_code, p_exchange_rate,
      'adjustment', v_source_id, v_meta, p_target_bucket, false
    );
    v_ledger_ids := array_append(v_ledger_ids, (v_entry->>'id')::uuid);

  ELSIF p_action_type = 'credit' THEN
    v_entry := public.record_ledger_transaction(
      v_books_id, v_operating_id, p_primary_entity_type, v_primary_entity_id,
      'credit', p_amount, p_currency_code, p_exchange_rate,
      'adjustment', v_source_id, v_meta, p_target_bucket, false
    );
    v_ledger_ids := array_append(v_ledger_ids, (v_entry->>'id')::uuid);

  ELSIF p_action_type = 'pay' AND p_primary_entity_type = 'tenant' THEN
    v_entry := public.record_ledger_transaction(
      v_books_id, v_operating_id, 'tenant', v_books_id,
      'debit', p_amount, p_currency_code, p_exchange_rate,
      CASE WHEN p_category = 'vendor_purchase' THEN 'vendor_purchase' ELSE 'adjustment' END,
      v_source_id, v_meta, p_target_bucket, false
    );
    v_ledger_ids := array_append(v_ledger_ids, (v_entry->>'id')::uuid);
    v_entry := public.record_ledger_transaction(
      v_books_id, v_operating_id, p_counterparty_entity_type, p_counterparty_entity_id,
      'credit', p_amount, p_currency_code, p_exchange_rate,
      CASE WHEN p_category = 'vendor_purchase' THEN 'vendor_purchase' ELSE 'adjustment' END,
      v_source_id, v_meta, p_target_bucket, false
    );
    v_ledger_ids := array_append(v_ledger_ids, (v_entry->>'id')::uuid);

  ELSIF p_action_type = 'pay' THEN
    v_entry := public.record_ledger_transaction(
      v_books_id, v_operating_id, 'tenant', v_books_id,
      'debit', p_amount, p_currency_code, p_exchange_rate,
      'adjustment', v_source_id, v_meta, p_target_bucket, false
    );
    v_ledger_ids := array_append(v_ledger_ids, (v_entry->>'id')::uuid);
    v_entry := public.record_ledger_transaction(
      v_books_id, v_operating_id, p_primary_entity_type, v_primary_entity_id,
      'credit', p_amount, p_currency_code, p_exchange_rate,
      'adjustment', v_source_id, v_meta, p_target_bucket, false
    );
    v_ledger_ids := array_append(v_ledger_ids, (v_entry->>'id')::uuid);

  ELSE
    RETURN jsonb_build_object('success', false, 'error', 'invalid action_type');
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'ledger_entry_ids', to_jsonb(v_ledger_ids),
    'primary_account', public.get_wallet_account_balances(v_books_id, p_primary_entity_type, v_primary_entity_id, p_currency_code)
  );
END;
$$;


ALTER FUNCTION "public"."record_wallet_manual_transaction_for_staff"("p_tenant_id" bigint, "p_action_type" "text", "p_primary_entity_type" "text", "p_primary_entity_id" bigint, "p_amount" numeric, "p_currency_code" "text", "p_exchange_rate" numeric, "p_category" "text", "p_payment_method" "text", "p_reference_id" "text", "p_note" "text", "p_counterparty_entity_type" "text", "p_counterparty_entity_id" bigint, "p_target_bucket" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_costing_file_item_calculations_for_file"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if
    new.cargo_rate_1kg is distinct from old.cargo_rate_1kg
    or new.cargo_rate_2kg is distinct from old.cargo_rate_2kg
    or new.conversion_rate is distinct from old.conversion_rate
    or new.admin_profit_rate is distinct from old.admin_profit_rate
  then
    update public.costing_file_items cfi
    set updated_at = now()
    where cfi.costing_file_id = new.id;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."refresh_costing_file_item_calculations_for_file"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_shipment_inventory_accounting"("p_tenant_id" bigint, "p_shipment_id" bigint DEFAULT NULL::bigint) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_rows integer := 0;
begin
  if p_tenant_id is null then
    raise exception 'tenant_id is required';
  end if;

  if not (
    public.is_superadmin()
    or exists (
      select 1
      from public.memberships m
      where m.tenant_id = p_tenant_id
        and lower(trim(m.email)) = public.current_user_email()
        and m.is_active = true
        and m.role in ('admin', 'staff')
    )
  ) then
    raise exception 'Not allowed to refresh shipment inventory accounting for this tenant.';
  end if;

  insert into public.shipment_inventory_accounting (
    tenant_id,
    shipment_id,
    usable_quantity,
    damaged_quantity,
    stolen_quantity,
    expired_quantity,
    usable_cost_total,
    damaged_cost_total,
    stolen_cost_total,
    expired_cost_total,
    inventory_cost_total
  )
  select
    s.tenant_id,
    s.id as shipment_id,
    coalesce(sum(greatest(
      0,
      coalesce(ist.available_quantity, 0)
      - coalesce(ist.reserved_quantity, 0)
      - coalesce(ist.damaged_quantity, 0)
      - coalesce(ist.stolen_quantity, 0)
      - coalesce(ist.expired_quantity, 0)
    )), 0)::integer as usable_quantity,
    coalesce(sum(coalesce(ist.damaged_quantity, 0)), 0)::integer as damaged_quantity,
    coalesce(sum(coalesce(ist.stolen_quantity, 0)), 0)::integer as stolen_quantity,
    coalesce(sum(coalesce(ist.expired_quantity, 0)), 0)::integer as expired_quantity,
    coalesce(sum(coalesce(ii.cost, 0) * greatest(
      0,
      coalesce(ist.available_quantity, 0)
      - coalesce(ist.reserved_quantity, 0)
      - coalesce(ist.damaged_quantity, 0)
      - coalesce(ist.stolen_quantity, 0)
      - coalesce(ist.expired_quantity, 0)
    )), 0)::numeric(14, 2) as usable_cost_total,
    coalesce(sum(coalesce(ii.cost, 0) * coalesce(ist.damaged_quantity, 0)), 0)::numeric(14, 2) as damaged_cost_total,
    coalesce(sum(coalesce(ii.cost, 0) * coalesce(ist.stolen_quantity, 0)), 0)::numeric(14, 2) as stolen_cost_total,
    coalesce(sum(coalesce(ii.cost, 0) * coalesce(ist.expired_quantity, 0)), 0)::numeric(14, 2) as expired_cost_total,
    (
      coalesce(sum(coalesce(ii.cost, 0) * greatest(
        0,
        coalesce(ist.available_quantity, 0)
        - coalesce(ist.reserved_quantity, 0)
        - coalesce(ist.damaged_quantity, 0)
        - coalesce(ist.stolen_quantity, 0)
        - coalesce(ist.expired_quantity, 0)
      )), 0)
      + coalesce(sum(coalesce(ii.cost, 0) * coalesce(ist.damaged_quantity, 0)), 0)
      + coalesce(sum(coalesce(ii.cost, 0) * coalesce(ist.stolen_quantity, 0)), 0)
      + coalesce(sum(coalesce(ii.cost, 0) * coalesce(ist.expired_quantity, 0)), 0)
    )::numeric(14, 2) as inventory_cost_total
  from public.shipments s
  left join public.shipment_items si
    on si.shipment_id = s.id
  left join public.inventory_items ii
    on ii.tenant_id = s.tenant_id
    and ii.source_type = 'shipment'
    and ii.source_id = si.id
  left join public.inventory_stocks ist
    on ist.inventory_item_id = ii.id
  where s.tenant_id = p_tenant_id
    and (p_shipment_id is null or s.id = p_shipment_id)
  group by s.tenant_id, s.id
  on conflict (tenant_id, shipment_id)
  do update
  set
    usable_quantity = excluded.usable_quantity,
    damaged_quantity = excluded.damaged_quantity,
    stolen_quantity = excluded.stolen_quantity,
    expired_quantity = excluded.expired_quantity,
    usable_cost_total = excluded.usable_cost_total,
    damaged_cost_total = excluded.damaged_cost_total,
    stolen_cost_total = excluded.stolen_cost_total,
    expired_cost_total = excluded.expired_cost_total,
    inventory_cost_total = excluded.inventory_cost_total,
    updated_at = now();

  get diagnostics v_rows = row_count;
  return v_rows;
end;
$$;


ALTER FUNCTION "public"."refresh_shipment_inventory_accounting"("p_tenant_id" bigint, "p_shipment_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_shipment_investor_profits"("p_global_shipment_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_shipment public.global_shipments;
  v_pnl jsonb;
  v_buy numeric(12,2);
  v_profit numeric(12,2);
  v_updated integer := 0;
  v_inv record;
  v_status text;
  v_sold_qty numeric;
  v_received_qty numeric;
  v_computed_profit numeric(12,2);
begin
  select * into v_shipment from public.global_shipments where id = p_global_shipment_id;
  if v_shipment.id is null then raise exception 'global shipment not found'; end if;

  if not public.user_can_manage_parent_tenant(v_shipment.parent_tenant_id) then
    raise exception 'not allowed';
  end if;

  v_pnl := public.get_shipment_pnl(v_shipment.parent_tenant_id, p_global_shipment_id);
  v_buy := coalesce((v_pnl -> 'totals' ->> 'landed_cost')::numeric, 0.00);
  v_profit := coalesce((v_pnl -> 'totals' ->> 'gross_profit')::numeric, 0.00);

  select
    coalesce(sum(ordered_quantity), 0),
    coalesce(sum(sold_qty), 0)
  into v_received_qty, v_sold_qty
  from (
    select
      si.ordered_quantity,
      coalesce(sum(ii.quantity - ii.return_quantity), 0) as sold_qty
    from public.global_shipment_items si
    left join public.global_invoice_items ii on ii.shipment_item_id = si.id
    left join public.global_invoices inv on inv.id = ii.invoice_id and inv.invoice_status = 'posted'::public.global_invoice_status
    where si.shipment_id = p_global_shipment_id
    group by si.id, si.ordered_quantity
  ) t;

  if v_received_qty = 0 then
    v_status := 'open';
  elsif v_sold_qty >= v_received_qty then
    v_status := 'realized';
  elsif v_sold_qty > 0 then
    v_status := 'partial';
  else
    v_status := 'open';
  end if;

  for v_inv in
    select * from public.shipment_investments
    where global_shipment_id = p_global_shipment_id
      and status = 'active'
      and cost_share_pct is not null
  loop
    v_computed_profit := round(v_profit * v_inv.cost_share_pct / 100.0, 2);

    update public.shipment_investments
    set
      allocated_cost = round(v_buy * v_inv.cost_share_pct / 100.0, 2),
      computed_profit = v_computed_profit,
      profit_status = v_status
    where id = v_inv.id;

    -- Update investor pending profit bucket if profit is realized
    if v_computed_profit > 0 and v_status = 'realized' then
      if not exists (
        select 1 from public.universal_wallet_ledger
        where tenant_id = v_shipment.parent_tenant_id
          and entity_type = 'investor'
          and entity_id = v_inv.investor_id
          and source_type = 'vendor_purchase'
          and source_id = p_global_shipment_id::text
          and metadata->>'purpose' = 'shipment_investor_profit'
      ) then
        perform public.record_ledger_transaction(
          p_tenant_id => v_shipment.parent_tenant_id,
          p_entity_type => 'investor',
          p_entity_id => v_inv.investor_id,
          p_type => 'credit',
          p_amount => v_computed_profit,
          p_currency_code => 'BDT',
          p_exchange_rate => 1.000000,
          p_source_type => 'vendor_purchase',
          p_source_id => p_global_shipment_id::text,
          p_metadata => jsonb_build_object(
            'section', 'investor_capital',
            'purpose', 'shipment_investor_profit',
            'transaction_type', 'profit_accrued',
            'label', 'Shipment Profit Distribution',
            'shipment_id', p_global_shipment_id
          ),
          p_target_bucket => 'pending'
        );
      end if;
    end if;

    v_updated := v_updated + 1;
  end loop;

  return jsonb_build_object(
    'global_shipment_id', p_global_shipment_id,
    'updated_count', v_updated,
    'buy_cost_total', v_buy,
    'profit_total', v_profit,
    'profit_status', v_status
  );
end;
$$;


ALTER FUNCTION "public"."refresh_shipment_investor_profits"("p_global_shipment_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."register_thrift_stock_from_app"("p_tenant_id" bigint, "p_barcode" "text", "p_shipment_id" bigint, "p_image_url" "text", "p_brand_name" "text" DEFAULT NULL::"text", "p_category_id" bigint DEFAULT NULL::bigint, "p_type_id" bigint DEFAULT NULL::bigint, "p_section" "text" DEFAULT NULL::"text", "p_shelf_id" bigint DEFAULT NULL::bigint, "p_color" "text" DEFAULT NULL::"text", "p_size" "text" DEFAULT NULL::"text", "p_condition" "text" DEFAULT NULL::"text", "p_box_id" bigint DEFAULT NULL::bigint, "p_product_weight" numeric DEFAULT NULL::numeric, "p_extra_weight" numeric DEFAULT NULL::numeric, "p_note" "text" DEFAULT NULL::"text", "p_origin_purchase_price" numeric DEFAULT NULL::numeric, "p_extra_origin_purchase_expense" numeric DEFAULT NULL::numeric, "p_cost_of_goods_sold" numeric DEFAULT 0, "p_target_price" numeric DEFAULT 0, "p_listed_price" numeric DEFAULT 0, "p_extra_expense_cost" numeric DEFAULT 0, "p_inserted_by" "text" DEFAULT 'app-user'::"text") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_barcode_row public.thrift_barcodes%rowtype;
  v_stock_id bigint;
  v_section public.thrift_section;
  v_condition public.thrift_condition;
  v_canonical_barcode text;
begin
  if trim(coalesce(p_barcode, '')) = '' then
    raise exception 'Barcode is required';
  end if;

  if trim(coalesce(p_image_url, '')) = '' then
    raise exception 'Image URL is required';
  end if;

  v_section := nullif(trim(coalesce(p_section, '')), '')::public.thrift_section;
  v_condition := nullif(trim(coalesce(p_condition, '')), '')::public.thrift_condition;

  if not exists (
    select 1
    from public.memberships m
    where m.tenant_id = p_tenant_id
      and lower(trim(m.email)) = public.current_user_email()
      and m.is_active = true
      and m.role in ('admin', 'staff')
  ) then
    raise exception 'Not authorized for this tenant';
  end if;

  v_canonical_barcode := public.resolve_thrift_barcode_id_internal(p_tenant_id, p_barcode);
  if v_canonical_barcode is null then
    raise exception 'Barcode not found in catalog';
  end if;

  select *
  into v_barcode_row
  from public.thrift_barcodes
  where tenant_id = p_tenant_id
    and barcode_id = v_canonical_barcode
  for update;

  if not found then
    raise exception 'Barcode not found in catalog';
  end if;

  select id
  into v_stock_id
  from public.thrift_stocks
  where tenant_id = p_tenant_id
    and barcode = v_canonical_barcode
  limit 1;

  if v_stock_id is null then
    if v_barcode_row.status <> 'AVAILABLE' then
      raise exception 'Barcode is already used';
    end if;

    insert into public.thrift_stocks (
      tenant_id,
      shipment_id,
      brand_name,
      category_id,
      type_id,
      section,
      shelf_id,
      color,
      size,
      condition,
      barcode,
      stock_type,
      quantity,
      box_id,
      product_weight,
      extra_weight,
      status,
      note,
      inserted_by,
      origin_purchase_price,
      extra_origin_purchase_expense
    )
    values (
      p_tenant_id,
      p_shipment_id,
      nullif(trim(coalesce(p_brand_name, '')), ''),
      p_category_id,
      p_type_id,
      v_section,
      p_shelf_id,
      nullif(trim(coalesce(p_color, '')), ''),
      nullif(trim(coalesce(p_size, '')), ''),
      v_condition,
      v_canonical_barcode,
      'SINGLE',
      1,
      p_box_id,
      p_product_weight,
      p_extra_weight,
      'AVAILABLE',
      coalesce(p_note, ''),
      p_inserted_by,
      p_origin_purchase_price,
      p_extra_origin_purchase_expense
    )
    returning id into v_stock_id;
  else
    update public.thrift_stocks
    set
      shipment_id = p_shipment_id,
      brand_name = nullif(trim(coalesce(p_brand_name, '')), ''),
      category_id = p_category_id,
      type_id = p_type_id,
      section = v_section,
      shelf_id = p_shelf_id,
      color = nullif(trim(coalesce(p_color, '')), ''),
      size = nullif(trim(coalesce(p_size, '')), ''),
      condition = v_condition,
      box_id = p_box_id,
      product_weight = p_product_weight,
      extra_weight = p_extra_weight,
      note = coalesce(p_note, ''),
      origin_purchase_price = p_origin_purchase_price,
      extra_origin_purchase_expense = p_extra_origin_purchase_expense,
      inserted_by = p_inserted_by
    where id = v_stock_id;
  end if;

  insert into public.thrift_pricings (
    stock_id,
    cost_of_goods_sold,
    target_price,
    listed_price,
    extra_expense_cost,
    inserted_by
  )
  values (
    v_stock_id,
    coalesce(p_cost_of_goods_sold, 0),
    coalesce(p_target_price, 0),
    coalesce(p_listed_price, 0),
    coalesce(p_extra_expense_cost, 0),
    p_inserted_by
  )
  on conflict (stock_id) do update
  set
    cost_of_goods_sold = excluded.cost_of_goods_sold,
    target_price = excluded.target_price,
    listed_price = excluded.listed_price,
    extra_expense_cost = excluded.extra_expense_cost,
    inserted_by = excluded.inserted_by;

  update public.thrift_stock_images
  set image_url = p_image_url,
      inserted_by = p_inserted_by
  where stock_id = v_stock_id
    and is_primary = true;

  if not found then
    insert into public.thrift_stock_images (
      stock_id,
      image_url,
      is_primary,
      inserted_by
    )
    values (
      v_stock_id,
      p_image_url,
      true,
      p_inserted_by
    );
  end if;

  update public.thrift_barcodes
  set status = 'USED'
  where tenant_id = p_tenant_id
    and barcode_id = v_canonical_barcode;

  return v_stock_id;
end;
$$;


ALTER FUNCTION "public"."register_thrift_stock_from_app"("p_tenant_id" bigint, "p_barcode" "text", "p_shipment_id" bigint, "p_image_url" "text", "p_brand_name" "text", "p_category_id" bigint, "p_type_id" bigint, "p_section" "text", "p_shelf_id" bigint, "p_color" "text", "p_size" "text", "p_condition" "text", "p_box_id" bigint, "p_product_weight" numeric, "p_extra_weight" numeric, "p_note" "text", "p_origin_purchase_price" numeric, "p_extra_origin_purchase_expense" numeric, "p_cost_of_goods_sold" numeric, "p_target_price" numeric, "p_listed_price" numeric, "p_extra_expense_cost" numeric, "p_inserted_by" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."register_thrift_stock_from_app"("p_tenant_id" bigint, "p_barcode" "text", "p_shipment_id" bigint, "p_image_url" "text", "p_brand_name" "text", "p_category_id" bigint, "p_type_id" bigint, "p_section" "text", "p_shelf_id" bigint, "p_color" "text", "p_size" "text", "p_condition" "text", "p_box_id" bigint DEFAULT NULL::bigint, "p_product_weight" numeric DEFAULT NULL::numeric, "p_extra_weight" numeric DEFAULT NULL::numeric, "p_note" "text" DEFAULT NULL::"text", "p_origin_purchase_price" numeric DEFAULT NULL::numeric, "p_cost_of_goods_sold" numeric DEFAULT 0, "p_target_price" numeric DEFAULT 0, "p_listed_price" numeric DEFAULT 0, "p_inserted_by" "text" DEFAULT 'app-user'::"text", "p_origin_unit_price" numeric DEFAULT NULL::numeric, "p_extra_origin_unit_price" numeric DEFAULT NULL::numeric, "p_listed_unit_price" numeric DEFAULT NULL::numeric, "p_extra_origin_purchase_expense" numeric DEFAULT NULL::numeric) RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_barcode_row public.thrift_barcodes%rowtype;
  v_stock_id bigint;
  v_origin_unit_price numeric := coalesce(p_origin_unit_price, p_origin_purchase_price);
  v_extra_origin_unit_price numeric := coalesce(p_extra_origin_unit_price, p_extra_origin_purchase_expense, 0);
  v_listed_unit_price numeric := coalesce(p_listed_unit_price, p_listed_price);
begin
  if trim(coalesce(p_barcode, '')) = '' then
    raise exception 'Barcode is required';
  end if;

  if trim(coalesce(p_image_url, '')) = '' then
    raise exception 'Image URL is required';
  end if;

  if not exists (
    select 1
    from public.memberships m
    where m.tenant_id = p_tenant_id
      and lower(trim(m.email)) = public.current_user_email()
      and m.is_active = true
      and m.role in ('admin', 'staff')
  ) then
    raise exception 'Not authorized for this tenant';
  end if;

  select *
  into v_barcode_row
  from public.thrift_barcodes
  where tenant_id = p_tenant_id
    and barcode_id = trim(p_barcode)
  for update;

  if not found then
    raise exception 'Barcode not found in catalog';
  end if;

  select id
  into v_stock_id
  from public.thrift_stocks
  where tenant_id = p_tenant_id
    and barcode = trim(p_barcode)
  limit 1;

  if v_stock_id is null then
    if v_barcode_row.status <> 'AVAILABLE' then
      raise exception 'Barcode is already used';
    end if;

    insert into public.thrift_stocks (
      tenant_id,
      shipment_id,
      brand_name,
      category_id,
      type_id,
      section,
      shelf_id,
      color,
      size,
      condition,
      barcode,
      stock_type,
      quantity,
      box_id,
      product_weight,
      extra_weight,
      status,
      note,
      inserted_by,
      origin_unit_price,
      extra_origin_unit_price
    )
    values (
      p_tenant_id,
      p_shipment_id,
      coalesce(p_brand_name, ''),
      p_category_id,
      p_type_id,
      p_section::public.thrift_section,
      p_shelf_id,
      p_color,
      p_size,
      p_condition::public.thrift_condition,
      trim(p_barcode),
      'SINGLE',
      1,
      p_box_id,
      p_product_weight,
      p_extra_weight,
      'AVAILABLE',
      coalesce(p_note, ''),
      p_inserted_by,
      v_origin_unit_price,
      v_extra_origin_unit_price
    )
    returning id into v_stock_id;
  else
    update public.thrift_stocks
    set
      shipment_id = p_shipment_id,
      brand_name = coalesce(p_brand_name, ''),
      category_id = p_category_id,
      type_id = p_type_id,
      section = p_section::public.thrift_section,
      shelf_id = p_shelf_id,
      color = p_color,
      size = p_size,
      condition = p_condition::public.thrift_condition,
      box_id = p_box_id,
      product_weight = p_product_weight,
      extra_weight = p_extra_weight,
      note = coalesce(p_note, ''),
      origin_unit_price = v_origin_unit_price,
      extra_origin_unit_price = v_extra_origin_unit_price,
      inserted_by = p_inserted_by
    where id = v_stock_id;
  end if;

  insert into public.thrift_pricings (
    stock_id,
    listed_unit_price,
    inserted_by
  )
  values (
    v_stock_id,
    coalesce(v_listed_unit_price, 0),
    p_inserted_by
  )
  on conflict (stock_id) do update
  set
    listed_unit_price = excluded.listed_unit_price,
    inserted_by = excluded.inserted_by;

  update public.thrift_stock_images
  set image_url = p_image_url,
      inserted_by = p_inserted_by
  where stock_id = v_stock_id
    and is_primary = true;

  if not found then
    insert into public.thrift_stock_images (
      stock_id,
      image_url,
      is_primary,
      inserted_by
    )
    values (
      v_stock_id,
      p_image_url,
      true,
      p_inserted_by
    );
  end if;

  update public.thrift_barcodes
  set status = 'USED'
  where tenant_id = p_tenant_id
    and barcode_id = trim(p_barcode);

  return v_stock_id;
end;
$$;


ALTER FUNCTION "public"."register_thrift_stock_from_app"("p_tenant_id" bigint, "p_barcode" "text", "p_shipment_id" bigint, "p_image_url" "text", "p_brand_name" "text", "p_category_id" bigint, "p_type_id" bigint, "p_section" "text", "p_shelf_id" bigint, "p_color" "text", "p_size" "text", "p_condition" "text", "p_box_id" bigint, "p_product_weight" numeric, "p_extra_weight" numeric, "p_note" "text", "p_origin_purchase_price" numeric, "p_cost_of_goods_sold" numeric, "p_target_price" numeric, "p_listed_price" numeric, "p_inserted_by" "text", "p_origin_unit_price" numeric, "p_extra_origin_unit_price" numeric, "p_listed_unit_price" numeric, "p_extra_origin_purchase_expense" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."release_dropship_order_stock"("p_order_id" bigint, "p_restore_display" boolean DEFAULT true) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_order public.shop_orders%rowtype;
  v_item record;
  v_pick record;
  v_skip_stock_release boolean := false;
  v_invoice_status public.global_invoice_status;
  v_parent_tenant_id bigint;
  v_stock public.global_stocks%rowtype;
  v_new_override_qty integer;
  v_new_sellable_qty integer;
  v_grade_tag_id bigint;
  v_held_stock_id bigint;
  v_release_qty integer;
begin
  select * into v_order from public.shop_orders where id = p_order_id;
  if v_order.id is null then return; end if;

  if coalesce(v_order.shop_type_snapshot, (
    select shop_type from public.shops where id = v_order.shop_id
  )) <> 'dropship' then
    return;
  end if;

  if v_order.global_invoice_id is not null then
    select invoice_status into v_invoice_status
    from public.global_invoices where id = v_order.global_invoice_id;
    if v_invoice_status = 'issued'::public.global_invoice_status then
      v_skip_stock_release := true;
    end if;
  end if;

  v_parent_tenant_id := public.resolve_parent_tenant_id(v_order.tenant_id);

  if not v_skip_stock_release then
    for v_pick in
      select * from public.shop_order_item_stock_picks where order_id = p_order_id
    loop
      if v_pick.held_stock_id is null then continue; end if;

      v_held_stock_id := v_pick.held_stock_id;
      v_release_qty := v_pick.quantity;

      update public.shop_order_item_stock_picks
      set held_stock_id = null, updated_at = now()
      where id = v_pick.id;

      select * into v_stock from public.global_stocks where id = v_held_stock_id for update;
      if found
         and v_stock.availability = 'held'::public.stock_availability
         and v_stock.quantity >= v_release_qty then
        perform public.create_and_post_stock_movement(
          p_tenant_id => v_parent_tenant_id,
          p_stock_id => v_stock.id,
          p_quantity => v_release_qty,
          p_to_location_id => v_stock.location_id,
          p_to_availability => 'sellable'::public.stock_availability,
          p_to_grade_tag_id => v_stock.grade_tag_id,
          p_movement_type => 'availability_transfer'::public.stock_movement_type,
          p_notes => 'Dropship order release (pick)',
          p_reference_type => 'shop_order',
          p_reference_id => p_order_id::text
        );
      end if;
    end loop;
  end if;

  for v_item in select * from public.shop_order_items where order_id = p_order_id
  loop
    v_grade_tag_id := coalesce(
      v_item.grade_tag_id,
      (select gs.grade_tag_id from public.global_stocks gs where gs.id = v_item.global_stock_id),
      public.default_stock_grade_tag_id()
    );

    if p_restore_display then
      if v_item.listing_id is not null then
        update public.shop_product_listings
        set display_quantity_override = display_quantity_override + v_item.quantity
        where id = v_item.listing_id and display_quantity_override is not null;
      end if;
    end if;

    if not v_skip_stock_release
       and v_item.global_stock_id is not null
       and not exists (
         select 1 from public.shop_order_item_stock_picks sp
         where sp.order_item_id = v_item.id
       ) then
      select * into v_stock from public.global_stocks where id = v_item.global_stock_id for update;
      if found
         and v_stock.availability = 'held'::public.stock_availability
         and v_stock.quantity >= coalesce(v_item.confirmed_quantity, v_item.quantity) then
        perform public.create_and_post_stock_movement(
          p_tenant_id => v_parent_tenant_id,
          p_stock_id => v_stock.id,
          p_quantity => coalesce(v_item.confirmed_quantity, v_item.quantity),
          p_to_location_id => v_stock.location_id,
          p_to_availability => 'sellable'::public.stock_availability,
          p_to_grade_tag_id => v_stock.grade_tag_id,
          p_movement_type => 'availability_transfer'::public.stock_movement_type,
          p_notes => 'Dropship order release (legacy line)',
          p_reference_type => 'shop_order',
          p_reference_id => p_order_id::text
        );
      end if;
    end if;

    if v_item.listing_id is not null then
      v_new_sellable_qty := public.shop_product_grade_available_units(
        v_order.tenant_id, v_item.product_id, v_grade_tag_id
      );
      select display_quantity_override into v_new_override_qty
      from public.shop_product_listings where id = v_item.listing_id;
      if coalesce(v_new_override_qty, v_new_sellable_qty, 0) > 0 then
        update public.shop_product_listings set is_active = true where id = v_item.listing_id;
      end if;
    end if;
  end loop;
end;
$$;


ALTER FUNCTION "public"."release_dropship_order_stock"("p_order_id" bigint, "p_restore_display" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."release_thrift_barcode_on_stock_delete"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if old.barcode is not null and trim(old.barcode) <> '' then
    update public.thrift_barcodes
    set status = 'AVAILABLE'
    where tenant_id = old.tenant_id
      and barcode_id = trim(old.barcode);
  end if;

  return old;
end;
$$;


ALTER FUNCTION "public"."release_thrift_barcode_on_stock_delete"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."release_thrift_stock_hold"("p_tenant_id" bigint, "p_stock_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_stock public.thrift_stocks%ROWTYPE;
  v_updated INT;
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.memberships m
    WHERE m.tenant_id = p_tenant_id
      AND lower(trim(m.email)) = public.current_user_email()
      AND m.is_active = true
  ) THEN
    RAISE EXCEPTION 'Not authorized for this tenant';
  END IF;

  SELECT *
  INTO v_stock
  FROM public.thrift_stocks
  WHERE id = p_stock_id
    AND tenant_id = p_tenant_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Stock item % not found for tenant %', p_stock_id, p_tenant_id;
  END IF;

  IF v_stock.status IS DISTINCT FROM 'RESERVED'::public.thrift_stock_status THEN
    RAISE EXCEPTION
      'Stock item % is not on hold (status=%)',
      p_stock_id,
      v_stock.status;
  END IF;

  UPDATE public.thrift_stocks
  SET
    status = 'AVAILABLE'::public.thrift_stock_status,
    updated_at = NOW()
  WHERE id = p_stock_id
    AND tenant_id = p_tenant_id
    AND status = 'RESERVED'::public.thrift_stock_status;

  GET DIAGNOSTICS v_updated = ROW_COUNT;
  IF v_updated = 0 THEN
    RAISE EXCEPTION 'Stock item % hold could not be released', p_stock_id;
  END IF;

  RETURN jsonb_build_object(
    'id', p_stock_id,
    'status', 'AVAILABLE'
  );
END;
$$;


ALTER FUNCTION "public"."release_thrift_stock_hold"("p_tenant_id" bigint, "p_stock_id" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."release_thrift_stock_hold"("p_tenant_id" bigint, "p_stock_id" bigint) IS 'Release RESERVED thrift stock back to AVAILABLE; clears hold metadata via trigger.';



CREATE OR REPLACE FUNCTION "public"."remove_global_invoice_item"("p_invoice_item_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_invoice public.global_invoices;
begin
  select gi.* into v_invoice
  from public.global_invoices gi
  inner join public.global_invoice_items gii on gii.invoice_id = gi.id
  where gii.id = p_invoice_item_id;

  if v_invoice.id is null then raise exception 'item not found'; end if;
  if v_invoice.invoice_status <> 'draft'::public.global_invoice_status then
    raise exception 'cannot remove items from a non-draft invoice';
  end if;

  delete from public.global_invoice_items
  where id = p_invoice_item_id;

  perform public.recompute_global_invoice_totals(v_invoice.id);
end;
$$;


ALTER FUNCTION "public"."remove_global_invoice_item"("p_invoice_item_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_shop_cart_item"("p_cart_item_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_cart_id bigint;
  v_shop_id bigint;
  v_tenant_id bigint;
begin
  select ci.cart_id, c.shop_id, c.tenant_id
  into v_cart_id, v_shop_id, v_tenant_id
  from public.shop_cart_items ci
  join public.shop_carts c on c.id = ci.cart_id
  where ci.id = p_cart_item_id;

  if v_cart_id is null then
    raise exception 'cart item not found';
  end if;

  -- Access verification
  if not public.is_cart_owner((select customer_group_id from public.shop_carts where id = v_cart_id), v_tenant_id) then
    raise exception 'access denied';
  end if;

  delete from public.shop_cart_items where id = p_cart_item_id;

  return public.get_or_create_shop_cart(v_shop_id);
end;
$$;


ALTER FUNCTION "public"."remove_shop_cart_item"("p_cart_item_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_shop_order_item_stock_pick"("p_pick_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_pick public.shop_order_item_stock_picks%rowtype;
  v_order public.shop_orders%rowtype;
  v_stock public.global_stocks%rowtype;
  v_parent_tenant_id bigint;
  v_held_stock_id bigint;
  v_release_qty integer;
begin
  select * into v_pick from public.shop_order_item_stock_picks where id = p_pick_id for update;
  if v_pick.id is null then
    raise exception 'pick not found';
  end if;

  select * into v_order from public.shop_orders where id = v_pick.order_id for update;
  if not public.is_tenant_staff(v_order.tenant_id) then
    raise exception 'access denied';
  end if;

  if v_order.status <> 'processing'::public.shop_order_status then
    raise exception 'pick removal is only allowed while order is processing';
  end if;

  v_parent_tenant_id := public.resolve_parent_tenant_id(v_order.tenant_id);
  v_held_stock_id := v_pick.held_stock_id;
  v_release_qty := v_pick.quantity;

  delete from public.shop_order_item_stock_picks where id = p_pick_id;

  perform public._recompute_shop_order_item_fulfillment(v_pick.order_item_id);
  perform public.recompute_dropship_cod_collect_amount(v_order.id);

  if v_held_stock_id is not null then
    select * into v_stock from public.global_stocks where id = v_held_stock_id for update;
    if found
       and v_stock.availability = 'held'::public.stock_availability
       and v_stock.quantity >= v_release_qty then
      perform public.create_and_post_stock_movement(
        p_tenant_id => v_parent_tenant_id,
        p_stock_id => v_stock.id,
        p_quantity => v_release_qty,
        p_to_location_id => v_stock.location_id,
        p_to_availability => 'sellable'::public.stock_availability,
        p_to_grade_tag_id => v_stock.grade_tag_id,
        p_movement_type => 'availability_transfer'::public.stock_movement_type,
        p_notes => 'Undo dropship processing pick',
        p_reference_type => 'shop_order',
        p_reference_id => v_order.id::text
      );
    end if;
  end if;

  return jsonb_build_object('success', true);
end;
$$;


ALTER FUNCTION "public"."remove_shop_order_item_stock_pick"("p_pick_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reorder_shipment_progress_flow_stages"("p_flow_id" bigint, "p_flow_stage_ids" bigint[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_flow public.shipment_progress_flows;
  v_idx integer;
  v_stage_id bigint;
begin
  select * into v_flow
  from public.shipment_progress_flows
  where id = p_flow_id;

  if not found then
    raise exception 'flow not found';
  end if;

  if not public.has_active_tenant_membership(v_flow.tenant_id)
     and not public.is_superadmin() then
    raise exception 'not authorized';
  end if;

  if p_flow_stage_ids is null or array_length(p_flow_stage_ids, 1) is null then
    return;
  end if;

  -- Unique (flow_id, sort_order) is checked per row; park first so swaps
  -- do not collide with a sort_order another stage still holds.
  update public.shipment_progress_flow_stages
  set sort_order = (-id)::integer
  where flow_id = p_flow_id
    and id = any(p_flow_stage_ids);

  for v_idx in 1..array_length(p_flow_stage_ids, 1) loop
    v_stage_id := p_flow_stage_ids[v_idx];

    update public.shipment_progress_flow_stages
    set sort_order = v_idx
    where id = v_stage_id
      and flow_id = p_flow_id;
  end loop;
end;
$$;


ALTER FUNCTION "public"."reorder_shipment_progress_flow_stages"("p_flow_id" bigint, "p_flow_stage_ids" bigint[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reorder_shipment_progress_tags"("p_tenant_id" bigint, "p_tag_ids" bigint[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_idx integer;
  v_id  bigint;
begin
  if not public.has_active_tenant_membership(p_tenant_id)
     and not public.is_superadmin() then
    raise exception 'not authorized';
  end if;

  for v_idx in 1..array_length(p_tag_ids, 1) loop
    v_id := p_tag_ids[v_idx];

    update public.tags
    set sort_order = v_idx
    where id = v_id
      and tenant_id = p_tenant_id
      and group_name = 'shipment_progress';
  end loop;
end;
$$;


ALTER FUNCTION "public"."reorder_shipment_progress_tags"("p_tenant_id" bigint, "p_tag_ids" bigint[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reorder_shipment_sections"("p_shipment_id" bigint, "p_section_ids" bigint[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_ship public.global_shipments;
  v_idx integer;
  v_section_id bigint;
begin
  select * into v_ship
  from public.global_shipments
  where id = p_shipment_id;

  if not found then
    raise exception 'shipment not found';
  end if;

  if not public.user_can_manage_parent_tenant(v_ship.parent_tenant_id)
     and not public.is_superadmin() then
    raise exception 'not authorized';
  end if;

  if p_section_ids is null or array_length(p_section_ids, 1) is null then
    return;
  end if;

  for v_idx in 1..array_length(p_section_ids, 1) loop
    v_section_id := p_section_ids[v_idx];

    update public.global_shipment_sections
    set sort_order = v_idx - 1,
        updated_at = now()
    where id = v_section_id
      and shipment_id = p_shipment_id;
  end loop;
end;
$$;


ALTER FUNCTION "public"."reorder_shipment_sections"("p_shipment_id" bigint, "p_section_ids" bigint[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_billing_profile_for_customer_group"("p_tenant_id" bigint, "p_customer_group_id" bigint) RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_billing_profile_id bigint;
  v_books_id bigint;
begin
  if p_customer_group_id is null then
    return null;
  end if;

  select id into v_billing_profile_id
  from public.billing_profiles
  where tenant_id = p_tenant_id
    and customer_group_id = p_customer_group_id
  order by id
  limit 1;

  if v_billing_profile_id is not null then
    return v_billing_profile_id;
  end if;

  v_books_id := public.resolve_parent_tenant_id(p_tenant_id);

  select id into v_billing_profile_id
  from public.billing_profiles bp
  where bp.customer_group_id = p_customer_group_id
    and (
      bp.tenant_id = v_books_id
      or bp.tenant_id in (
        select t.id from public.tenants t where t.parent_id = v_books_id
      )
    )
  order by
    case
      when bp.tenant_id = p_tenant_id then 0
      when bp.tenant_id = v_books_id then 1
      else 2
    end,
    bp.id
  limit 1;

  return v_billing_profile_id;
end;
$$;


ALTER FUNCTION "public"."resolve_billing_profile_for_customer_group"("p_tenant_id" bigint, "p_customer_group_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_costing_file_creator_label"("p_tenant_id" bigint, "p_customer_group_id" bigint, "p_created_by_email" "text") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select case
    when exists (
      select 1
      from public.memberships m
      where lower(trim(m.email)) = lower(trim(coalesce(p_created_by_email, '')))
        and m.is_active = true
        and (
          (m.tenant_id = p_tenant_id and m.role = 'admin')
          or (m.tenant_id is null and m.role = 'superadmin')
        )
    ) then 'admin'
    when exists (
      select 1
      from public.memberships m
      where lower(trim(m.email)) = lower(trim(coalesce(p_created_by_email, '')))
        and m.is_active = true
        and m.tenant_id = p_tenant_id
        and m.role = 'staff'
    ) then 'staff'
    else coalesce(
      (
        select cg.name
        from public.customer_group_members cgm
        inner join public.customer_groups cg
          on cg.id = cgm.customer_group_id
        where lower(trim(cgm.email)) = lower(trim(coalesce(p_created_by_email, '')))
          and cgm.is_active = true
          and cg.is_active = true
          and cgm.customer_group_id = p_customer_group_id
        limit 1
      ),
      'Unknown'
    )
  end;
$$;


ALTER FUNCTION "public"."resolve_costing_file_creator_label"("p_tenant_id" bigint, "p_customer_group_id" bigint, "p_created_by_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_customer_group_notification_user_ids"("p_customer_group_id" bigint) RETURNS "uuid"[]
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select coalesce(array_agg(distinct u.id), array[]::uuid[])
  from public.customer_group_members cgm
  join auth.users u on lower(trim(u.email)) = lower(trim(cgm.email))
  where cgm.customer_group_id = p_customer_group_id
    and cgm.is_active = true;
$$;


ALTER FUNCTION "public"."resolve_customer_group_notification_user_ids"("p_customer_group_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_notification_recipient_user_ids"("p_parent_tenant_id" bigint, "p_operating_tenant_id" bigint, "p_audience" "public"."notification_audience", "p_recipient_user_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_module_key" "text" DEFAULT NULL::"text", "p_action" "text" DEFAULT 'view'::"text") RETURNS "uuid"[]
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_ids uuid[];
begin
  if p_audience = 'assignee_only' then
    if p_recipient_user_ids is null or cardinality(p_recipient_user_ids) = 0 then
      return array[]::uuid[];
    end if;

    select coalesce(array_agg(distinct u.id), array[]::uuid[])
    into v_user_ids
    from unnest(p_recipient_user_ids) as input(user_id)
    join auth.users u on u.id = input.user_id
    where input.user_id is not null;

    return coalesce(v_user_ids, array[]::uuid[]);
  end if;

  if p_audience = 'child_only' and p_operating_tenant_id is null then
    return array[]::uuid[];
  end if;

  with pools as (
    select distinct
      u.id as user_id,
      m.tenant_id as membership_tenant_id,
      m.email as membership_email
    from public.memberships m
    join auth.users u on lower(trim(u.email)) = lower(trim(m.email))
    where m.is_active = true
      and (
        (
          p_audience in ('child_only', 'child_and_parent')
          and p_operating_tenant_id is not null
          and m.tenant_id = p_operating_tenant_id
        )
        or (
          p_audience in ('parent_only', 'child_and_parent')
          and m.tenant_id = p_parent_tenant_id
        )
        or (
          m.tenant_id = p_parent_tenant_id
          and m.role = 'owner'::public.app_role
        )
      )
  )
  select coalesce(array_agg(distinct p.user_id), array[]::uuid[])
  into v_user_ids
  from pools p
  where p_module_key is null
     or public.membership_has_module_action_for_email(
          p.membership_email,
          p.membership_tenant_id,
          p_module_key,
          p_action
        );

  return coalesce(v_user_ids, array[]::uuid[]);
end;
$$;


ALTER FUNCTION "public"."resolve_notification_recipient_user_ids"("p_parent_tenant_id" bigint, "p_operating_tenant_id" bigint, "p_audience" "public"."notification_audience", "p_recipient_user_ids" "uuid"[], "p_module_key" "text", "p_action" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_parent_tenant_id"("p_tenant_id" bigint) RETURNS bigint
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select coalesce(
    (select t.parent_id from public.tenants t where t.id = p_tenant_id),
    p_tenant_id
  );
$$;


ALTER FUNCTION "public"."resolve_parent_tenant_id"("p_tenant_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_shop_can_see_buy_price"("p_shop_type" "public"."shop_type_enum", "p_access_can_see_buy_price" boolean, "p_access_can_see_sell_price" boolean, "p_profile_default_can_see_buy_price" boolean, "p_profile_default_can_see_sell_price" boolean) RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select case
    when p_shop_type = 'dropship'::public.shop_type_enum then true
    when p_shop_type = 'vendor_catalog'::public.shop_type_enum then
      coalesce(p_access_can_see_buy_price, p_profile_default_can_see_buy_price, false)
    else
      coalesce(p_access_can_see_buy_price, p_profile_default_can_see_buy_price, false)
  end;
$$;


ALTER FUNCTION "public"."resolve_shop_can_see_buy_price"("p_shop_type" "public"."shop_type_enum", "p_access_can_see_buy_price" boolean, "p_access_can_see_sell_price" boolean, "p_profile_default_can_see_buy_price" boolean, "p_profile_default_can_see_sell_price" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_shop_order_item_landed_cost"("p_global_stock_id" bigint, "p_cost_price_amount" numeric DEFAULT NULL::numeric, "p_unit_list_price_amount" numeric DEFAULT NULL::numeric) RETURNS numeric
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select coalesce(
    p_cost_price_amount,
    (
      select coalesce(
        gsi.landed_cost_bdt,
        public.calculate_landed_unit_cost(gs.shipment_item_id)
      )
      from public.global_stocks gs
      join public.global_shipment_items gsi on gsi.id = gs.shipment_item_id
      where gs.id = p_global_stock_id
    ),
    p_unit_list_price_amount,
    0::numeric
  );
$$;


ALTER FUNCTION "public"."resolve_shop_order_item_landed_cost"("p_global_stock_id" bigint, "p_cost_price_amount" numeric, "p_unit_list_price_amount" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_tenant_for_entry"("p_slug" "text" DEFAULT NULL::"text", "p_hostname" "text" DEFAULT NULL::"text") RETURNS TABLE("id" bigint, "name" "text", "slug" "text", "public_domain" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with domain_match as (
    select *
    from public.find_active_tenant_by_public_domain(p_hostname)
  ),
  slug_match as (
    select *
    from public.find_active_tenant_by_slug(p_slug)
  )
  select *
  from domain_match
  union all
  select *
  from slug_match
  where not exists (select 1 from domain_match)
  limit 1;
$$;


ALTER FUNCTION "public"."resolve_tenant_for_entry"("p_slug" "text", "p_hostname" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_thrift_barcode"("p_tenant_id" bigint, "p_scanned_value" "text") RETURNS TABLE("barcode_id" "text", "status" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_canonical text;
begin
  if not exists (
    select 1
    from public.memberships m
    where m.tenant_id = p_tenant_id
      and lower(trim(m.email)) = public.current_user_email()
      and m.is_active = true
  ) then
    raise exception 'Not authorized for this tenant';
  end if;

  v_canonical := public.resolve_thrift_barcode_id_internal(p_tenant_id, p_scanned_value);
  if v_canonical is null then
    return;
  end if;

  return query
  select b.barcode_id, b.status
  from public.thrift_barcodes b
  where b.tenant_id = p_tenant_id
    and b.barcode_id = v_canonical
  limit 1;
end;
$$;


ALTER FUNCTION "public"."resolve_thrift_barcode"("p_tenant_id" bigint, "p_scanned_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_thrift_barcode_id_internal"("p_tenant_id" bigint, "p_scanned_value" "text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $_$
declare
  v_raw text;
  v_candidates text[] := array[]::text[];
  v_match text;
  v_tenant_prefix text;
  v_compact text[];
begin
  v_raw := upper(trim(regexp_replace(coalesce(p_scanned_value, ''), '[^A-Za-z0-9-]', '', 'g')));
  if v_raw = '' then
    return null;
  end if;

  v_tenant_prefix := lpad(p_tenant_id::text, 2, '0');
  v_candidates := array_append(v_candidates, v_raw);

  if v_raw ~ '^\d+-[A-Z]{2}-\d{2}-\d+$' then
    v_candidates := array_append(v_candidates,
      split_part(v_raw, '-', 1) || '-' ||
      split_part(v_raw, '-', 2) || '-' ||
      split_part(v_raw, '-', 3) || '-' ||
      lpad(split_part(v_raw, '-', 4), 6, '0'));
  end if;

  if v_raw ~ '^[A-Z]{2}-\d{2}-\d+$' then
    v_candidates := array_append(v_candidates, v_tenant_prefix || '-' || v_raw);
    v_candidates := array_append(v_candidates,
      v_tenant_prefix || '-' ||
      split_part(v_raw, '-', 1) || '-' ||
      split_part(v_raw, '-', 2) || '-' ||
      lpad(split_part(v_raw, '-', 3), 6, '0'));
  end if;

  v_compact := regexp_match(v_raw, '^(\d+)([A-Z]{2})(\d{2})(\d+)$');
  if v_compact is not null then
    v_candidates := array_append(v_candidates,
      v_compact[1] || '-' || v_compact[2] || '-' || v_compact[3] || '-' || lpad(v_compact[4], 6, '0'));
  end if;

  select b.barcode_id
  into v_match
  from public.thrift_barcodes b
  where b.tenant_id = p_tenant_id
    and b.barcode_id = any (v_candidates)
  order by b.barcode_id
  limit 1;

  return v_match;
end;
$_$;


ALTER FUNCTION "public"."resolve_thrift_barcode_id_internal"("p_tenant_id" bigint, "p_scanned_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."restock_dropship_order_on_delete"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_is_dropship boolean := false;
BEGIN
  IF OLD.shop_type_snapshot = 'dropship' THEN
    v_is_dropship := true;
  ELSE
    SELECT (shop_type = 'dropship') INTO v_is_dropship
    FROM public.shops
    WHERE id = OLD.shop_id;
  END IF;

  IF NOT coalesce(v_is_dropship, false) THEN
    RETURN OLD;
  END IF;

  PERFORM public.release_dropship_order_stock(
    OLD.id,
    OLD.status IS DISTINCT FROM 'cancelled'
  );

  RETURN OLD;
END;
$$;


ALTER FUNCTION "public"."restock_dropship_order_on_delete"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."return_shipment_to_vendor"("p_shipment_id" bigint, "p_items_qty" "jsonb", "p_outcome" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_ship public.global_shipments%rowtype;
  v_item jsonb;
  v_stock_id bigint;
  v_shipment_item_id bigint;
  v_qty numeric;
  v_mov_id bigint;
  v_amount numeric := 0;
  v_ledger jsonb;
  v_vendor_id bigint;
begin
  select * into v_ship
  from public.global_shipments
  where id = p_shipment_id
  for update;

  if not found then
    raise exception 'shipment not found';
  end if;

  if v_ship.status is distinct from 'received' then
    raise exception 'shipment must be received before return';
  end if;

  if p_outcome not in ('cash_refund', 'store_credit') then
    raise exception 'outcome must be cash_refund or store_credit';
  end if;

  if not public.has_active_tenant_membership(v_ship.parent_tenant_id)
     and not public.is_superadmin() then
    raise exception 'not authorized';
  end if;

  v_vendor_id := v_ship.vendor_id;

  insert into public.stock_movements (
    tenant_id, movement_no, movement_type, reference_type, reference_id, notes, created_by_email
  ) values (
    v_ship.parent_tenant_id,
    'VR-' || to_char(now(), 'YYYYMMDD') || '-' || lpad(nextval('stock_movements_id_seq')::text, 6, '0'),
    'return_inbound',
    'shipment_return',
    p_shipment_id::text,
    'Vendor return outcome: ' || p_outcome,
    public.current_user_email()
  )
  returning id into v_mov_id;

  for v_item in select value from jsonb_array_elements(coalesce(p_items_qty, '[]'::jsonb))
  loop
    v_stock_id := (v_item->>'global_stock_id')::bigint;
    v_shipment_item_id := (v_item->>'shipment_item_id')::bigint;
    v_qty := coalesce((v_item->>'quantity')::numeric, 0);

    if v_stock_id is null and v_shipment_item_id is not null then
      select gs.id into v_stock_id
      from public.global_stocks gs
      join public.global_stock_types gst on gst.id = gs.stock_type_id
      where gs.shipment_item_id = v_shipment_item_id
        and gs.parent_tenant_id = v_ship.parent_tenant_id
        and gst.is_sellable = true
        and gs.availability = 'sellable'::public.stock_availability
      order by gs.quantity desc, gs.id
      limit 1;
    end if;

    if v_stock_id is null or v_qty <= 0 then
      continue;
    end if;

    insert into public.stock_movement_lines (
      movement_id, stock_id, quantity, from_availability, to_availability
    ) values (
      v_mov_id, v_stock_id, v_qty, 'sellable'::public.stock_availability, 'held'::public.stock_availability
    );

    v_amount := v_amount + (v_qty * coalesce(
      (select gsi.landed_cost_bdt from public.global_stocks gs
       join public.global_shipment_items gsi on gsi.id = gs.shipment_item_id
       where gs.id = v_stock_id),
      0
    ));
  end loop;

  perform public.post_stock_movement(v_mov_id);

  if v_amount <= 0 then
    v_amount := coalesce((
      select sum(coalesce(e.amount, 0) * coalesce(e.exchange_rate, 1))
      from public.global_shipment_cost_entries e
      where e.shipment_id = p_shipment_id and e.cost_type = 'product'
    ), 0);
  end if;

  if p_outcome = 'cash_refund' then
    v_ledger := public.record_ledger_transaction(
      p_tenant_id => v_ship.parent_tenant_id,
      p_entity_type => 'tenant',
      p_entity_id => v_ship.parent_tenant_id,
      p_type => 'credit',
      p_amount => v_amount,
      p_currency_code => 'BDT',
      p_source_type => 'shipment_return',
      p_source_id => p_shipment_id::text,
      p_metadata => jsonb_build_object('outcome', 'cash_refund', 'movement_id', v_mov_id)
    );
    if v_vendor_id is not null then
      perform public.record_ledger_transaction(
        p_tenant_id => v_ship.parent_tenant_id,
        p_entity_type => 'vendor',
        p_entity_id => v_vendor_id,
        p_type => 'debit',
        p_amount => v_amount,
        p_currency_code => 'BDT',
        p_source_type => 'shipment_return',
        p_source_id => p_shipment_id::text,
        p_metadata => jsonb_build_object('outcome', 'cash_refund', 'movement_id', v_mov_id)
      );
    end if;
  else
    v_ledger := public.record_ledger_transaction(
      p_tenant_id => v_ship.parent_tenant_id,
      p_entity_type => 'vendor',
      p_entity_id => v_vendor_id,
      p_type => 'credit',
      p_amount => v_amount,
      p_currency_code => 'BDT',
      p_source_type => 'shipment_return',
      p_source_id => p_shipment_id::text,
      p_metadata => jsonb_build_object('outcome', 'store_credit', 'movement_id', v_mov_id)
    );
  end if;

  return jsonb_build_object(
    'shipment_id', p_shipment_id,
    'outcome', p_outcome,
    'movement_id', v_mov_id,
    'return_processed', true,
    'wallet_posted', true,
    'amount_bdt', v_amount
  );
end;
$$;


ALTER FUNCTION "public"."return_shipment_to_vendor"("p_shipment_id" bigint, "p_items_qty" "jsonb", "p_outcome" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reverse_wallet_ledger_entry_for_staff"("p_tenant_id" bigint, "p_ledger_entry_id" "uuid", "p_reason" "text", "p_reference_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_books_id bigint;
  v_orig public.universal_wallet_ledger%ROWTYPE;
  v_reversal_type text;
  v_reversal_id uuid;
  v_meta jsonb;
  v_entry jsonb;
BEGIN
  IF NOT public.wallet_staff_can_edit(p_tenant_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'access denied');
  END IF;

  IF nullif(trim(p_reason), '') IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'reason required');
  END IF;

  v_books_id := public.resolve_parent_tenant_id(p_tenant_id);

  SELECT * INTO v_orig FROM public.universal_wallet_ledger WHERE id = p_ledger_entry_id;
  IF v_orig.id IS NULL OR v_orig.parent_tenant_id <> v_books_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'entry not found');
  END IF;

  IF v_orig.metadata ? 'reversed_by' OR v_orig.metadata ? 'reversal_of' THEN
    RETURN jsonb_build_object('success', false, 'error', 'entry already reversed or is a reversal');
  END IF;

  IF v_orig.source_type = 'shop_order' AND NOT coalesce((v_orig.metadata->>'allow_manual_reversal')::boolean, false)
     AND NOT public.is_superadmin() THEN
    RETURN jsonb_build_object('success', false, 'error', 'system shop_order entries cannot be reversed');
  END IF;

  v_reversal_type := CASE WHEN v_orig.type = 'credit' THEN 'debit' ELSE 'credit' END;
  v_meta := jsonb_build_object(
    'reversal_of', v_orig.id::text,
    'transaction_type', 'manual_reversal',
    'note', p_reason,
    'trx_id', coalesce(p_reference_id, 'REV-' || gen_random_uuid()::text),
    'recorded_by', public.current_user_email()
  );

  v_entry := public.record_ledger_transaction(
    v_orig.parent_tenant_id,
    v_orig.operating_tenant_id,
    v_orig.entity_type,
    v_orig.entity_id,
    v_reversal_type,
    v_orig.amount,
    v_orig.currency_code,
    v_orig.exchange_rate,
    v_orig.source_type,
    coalesce(p_reference_id, v_orig.source_id),
    v_meta,
    coalesce(v_orig.metadata->>'target_bucket', 'available'),
    false
  );
  v_reversal_id := (v_entry->>'id')::uuid;

  UPDATE public.universal_wallet_ledger
  SET metadata = metadata || jsonb_build_object('reversed_by', v_reversal_id::text)
  WHERE id = v_orig.id;

  RETURN jsonb_build_object(
    'success', true,
    'reversal_entry_id', v_reversal_id,
    'account', public.get_wallet_account_balances(
      v_books_id, v_orig.entity_type, v_orig.entity_id, v_orig.currency_code
    )
  );
END;
$$;


ALTER FUNCTION "public"."reverse_wallet_ledger_entry_for_staff"("p_tenant_id" bigint, "p_ledger_entry_id" "uuid", "p_reason" "text", "p_reference_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."revert_thrift_sales_invoice"("p_tenant_id" bigint, "p_invoice_id" bigint, "p_reason" "text", "p_reverted_by" "text" DEFAULT 'cashier'::"text", "p_notes" "text" DEFAULT NULL::"text", "p_force" boolean DEFAULT false, "p_return_courier_amount" numeric DEFAULT 0.00) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_invoice public.thrift_sales_invoices%ROWTYPE;
  v_item RECORD;
  v_reason TEXT;
  v_invoice_number TEXT;
  v_force BOOLEAN := COALESCE(p_force, false);
  v_has_returns BOOLEAN := FALSE;
  v_return_courier NUMERIC(12,2);
  v_event_at TIMESTAMPTZ := NOW();
  v_is_online BOOLEAN;
  v_uncollected_delivery NUMERIC(12,2) := 0.00;
  v_advance_amount NUMERIC(12,2) := 0.00;
  v_ledger_refund NUMERIC(12,2) := 0.00;
  v_pool_delivery NUMERIC(12,2) := 0.00;
  v_pool_packing NUMERIC(12,2) := 0.00;
  v_pool_return NUMERIC(12,2) := 0.00;
  v_total_value NUMERIC(12,2) := 0.00;
  v_line_count INT := 0;
  v_idx INT := 0;
  v_cum_delivery NUMERIC(12,2) := 0.00;
  v_cum_packing NUMERIC(12,2) := 0.00;
  v_cum_return NUMERIC(12,2) := 0.00;
  v_line RECORD;
  v_line_value NUMERIC(12,2);
  v_share NUMERIC;
  v_alloc_delivery NUMERIC(12,2);
  v_alloc_packing NUMERIC(12,2);
  v_alloc_return NUMERIC(12,2);
  v_inbound_shipment_id BIGINT;
BEGIN
  v_reason := upper(trim(COALESCE(p_reason, '')));
  -- Legacy RETURN → RTO (temporary compat)
  IF v_reason = 'RETURN' THEN
    v_reason := 'RTO';
  END IF;

  IF v_reason NOT IN ('RTO', 'STAFF_MISTAKE') THEN
    RAISE EXCEPTION 'Invalid revert reason %. Expected RTO or STAFF_MISTAKE', p_reason;
  END IF;

  v_return_courier := ROUND(COALESCE(p_return_courier_amount, 0.00), 2);
  IF v_return_courier < 0 THEN
    RAISE EXCEPTION 'return_courier_amount cannot be negative';
  END IF;

  SELECT * INTO v_invoice
  FROM public.thrift_sales_invoices
  WHERE id = p_invoice_id
    AND tenant_id = p_tenant_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Invoice % not found for tenant %', p_invoice_id, p_tenant_id;
  END IF;

  IF v_invoice.status IS DISTINCT FROM 'ACTIVE' THEN
    RAISE EXCEPTION 'Invoice % is already % and cannot be reverted', p_invoice_id, v_invoice.status;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.thrift_sales_returns r
    WHERE r.tenant_id = p_tenant_id
      AND r.invoice_id = p_invoice_id
  )
  INTO v_has_returns;

  IF v_has_returns THEN
    RAISE EXCEPTION
      'Invoice % already has return documents; use create_thrift_sales_return, not whole-invoice RTO/staff mistake.',
      p_invoice_id;
  END IF;

  v_is_online := COALESCE(v_invoice.sale_channel, 'IN_STORE') = 'ONLINE';

  IF v_reason = 'STAFF_MISTAKE' THEN
    IF NOT public.membership_has_module_action(p_tenant_id, 'thrift_sales', 'staff_mistake') THEN
      RAISE EXCEPTION 'Staff mistake revert requires thrift_sales staff_mistake permission';
    END IF;
  ELSE
    -- RTO
    IF COALESCE(v_invoice.delivery_status, '') = 'DELIVERED' THEN
      RAISE EXCEPTION
        'Invoice % is already DELIVERED — use post-accept return (Return items), not Mark RTO',
        p_invoice_id;
    END IF;

    IF v_force THEN
      IF NOT public.membership_has_module_action(p_tenant_id, 'thrift_sales', 'force_return') THEN
        RAISE EXCEPTION
          'Force RTO requires thrift_sales force_return permission for tenant %',
          p_tenant_id;
      END IF;
    ELSE
      IF NOT public.membership_has_module_action(p_tenant_id, 'thrift_sales', 'return') THEN
        RAISE EXCEPTION 'Mark RTO requires thrift_sales return permission';
      END IF;
    END IF;

    IF NOT v_is_online THEN
      RAISE EXCEPTION 'Mark RTO applies to Online invoices only (use Return items for in-store)';
    END IF;
  END IF;

  v_invoice_number := v_invoice.invoice_number;

  -- Restore every sell line stock
  FOR v_item IN
    SELECT stock_id, quantity
    FROM public.thrift_sales_invoice_items
    WHERE invoice_id = p_invoice_id
      AND tenant_id = p_tenant_id
  LOOP
    UPDATE public.thrift_stocks
    SET
      quantity = quantity + GREATEST(v_item.quantity, 1),
      status = 'AVAILABLE'::public.thrift_stock_status,
      updated_at = NOW()
    WHERE id = v_item.stock_id
      AND tenant_id = p_tenant_id;
  END LOOP;

  IF v_reason = 'STAFF_MISTAKE' THEN
    DELETE FROM public.thrift_accounting_ledger
    WHERE tenant_id = p_tenant_id
      AND source = 'INVOICE'::public.thrift_ledger_source
      AND reference_id = p_invoice_id;

    DELETE FROM public.thrift_sales_pnl_lines
    WHERE tenant_id = p_tenant_id
      AND invoice_id = p_invoice_id;

    DELETE FROM public.thrift_sales_invoices
    WHERE id = p_invoice_id
      AND tenant_id = p_tenant_id;

    RETURN jsonb_build_object(
      'id', p_invoice_id,
      'invoice_number', v_invoice_number,
      'status', 'DELETED',
      'reason', 'STAFF_MISTAKE',
      'deleted', true,
      'counter_unchanged', true
    );
  END IF;

  -- ── RTO soft close ──────────────────────────────────────────────
  -- Ledger insert-only: REFUND item total minus non-refundable advance;
  -- LOSS uncollected customer delivery; LOSS return courier.
  -- Keep prior EXPENSE rows (shop packing / shop delivery). Advance is never paid back.

  v_advance_amount := ROUND(COALESCE(v_invoice.advance_amount, 0.00), 2);
  v_ledger_refund := GREATEST(
    0.00,
    ROUND(COALESCE(v_invoice.total_invoice_amount, 0.00) - v_advance_amount, 2)
  );

  IF v_ledger_refund > 0 THEN
    INSERT INTO public.thrift_accounting_ledger (
      tenant_id,
      type,
      source,
      reference_id,
      amount,
      note,
      inserted_by,
      date
    ) VALUES (
      p_tenant_id,
      'REFUND'::public.thrift_ledger_type,
      'INVOICE'::public.thrift_ledger_source,
      p_invoice_id,
      v_ledger_refund,
      'RTO refund for Sales Invoice #' || v_invoice_number
        || CASE WHEN v_advance_amount > 0
             THEN ' (advance retained ' || v_advance_amount::TEXT || ')'
             ELSE ''
           END
        || COALESCE(' — ' || NULLIF(trim(p_notes), ''), ''),
      p_reverted_by,
      v_event_at
    );
  END IF;

  IF upper(COALESCE(v_invoice.courier_paid_by, '')) = 'CUSTOMER'
     AND COALESCE(v_invoice.courier_amount, 0) > 0
  THEN
    v_uncollected_delivery := ROUND(v_invoice.courier_amount, 2);
    INSERT INTO public.thrift_accounting_ledger (
      tenant_id,
      type,
      source,
      reference_id,
      amount,
      note,
      inserted_by,
      date
    ) VALUES (
      p_tenant_id,
      'LOSS'::public.thrift_ledger_type,
      'INVOICE'::public.thrift_ledger_source,
      p_invoice_id,
      v_uncollected_delivery,
      'uncollected_delivery',
      p_reverted_by,
      v_event_at
    );
  END IF;

  IF v_return_courier > 0 THEN
    INSERT INTO public.thrift_accounting_ledger (
      tenant_id,
      type,
      source,
      reference_id,
      amount,
      note,
      inserted_by,
      date
    ) VALUES (
      p_tenant_id,
      'LOSS'::public.thrift_ledger_type,
      'INVOICE'::public.thrift_ledger_source,
      p_invoice_id,
      v_return_courier,
      'return_courier',
      p_reverted_by,
      v_event_at
    );
  END IF;

  -- PnL: all lines → RTO; pool = full forward delivery + packing + return courier
  v_pool_delivery := ROUND(COALESCE(v_invoice.courier_amount, 0), 2);
  v_pool_packing := ROUND(COALESCE(v_invoice.packing_amount, 0), 2);
  v_pool_return := v_return_courier;

  SELECT
    COALESCE(SUM(ROUND(i.final_price * i.quantity, 2)), 0),
    COUNT(*)::INT
  INTO v_total_value, v_line_count
  FROM public.thrift_sales_invoice_items i
  WHERE i.tenant_id = p_tenant_id
    AND i.invoice_id = p_invoice_id;

  IF v_line_count = 0 THEN
    RAISE EXCEPTION 'Invoice % has no lines; cannot close RTO', p_invoice_id;
  END IF;

  FOR v_line IN
    SELECT
      i.id AS invoice_item_id,
      i.stock_id,
      i.quantity,
      ROUND(i.final_price * i.quantity, 2) AS sell_amount,
      s.shipment_id
    FROM public.thrift_sales_invoice_items i
    JOIN public.thrift_stocks s
      ON s.id = i.stock_id
     AND s.tenant_id = i.tenant_id
    WHERE i.tenant_id = p_tenant_id
      AND i.invoice_id = p_invoice_id
    ORDER BY i.id
  LOOP
    v_idx := v_idx + 1;
    v_inbound_shipment_id := v_line.shipment_id;
    IF v_inbound_shipment_id IS NULL THEN
      RAISE EXCEPTION
        'Stock item % has no inbound shipment; cannot write RTO PnL',
        v_line.stock_id;
    END IF;

    v_line_value := v_line.sell_amount;
    IF v_total_value > 0 THEN
      v_share := v_line_value / v_total_value;
    ELSE
      v_share := 1.0 / v_line_count;
    END IF;

    IF v_idx = v_line_count THEN
      v_alloc_delivery := ROUND(v_pool_delivery - v_cum_delivery, 2);
      v_alloc_packing := ROUND(v_pool_packing - v_cum_packing, 2);
      v_alloc_return := ROUND(v_pool_return - v_cum_return, 2);
    ELSE
      v_alloc_delivery := ROUND(v_pool_delivery * v_share, 2);
      v_alloc_packing := ROUND(v_pool_packing * v_share, 2);
      v_alloc_return := ROUND(v_pool_return * v_share, 2);
      v_cum_delivery := v_cum_delivery + v_alloc_delivery;
      v_cum_packing := v_cum_packing + v_alloc_packing;
      v_cum_return := v_cum_return + v_alloc_return;
    END IF;

    INSERT INTO public.thrift_sales_pnl_lines (
      tenant_id,
      invoice_id,
      invoice_item_id,
      stock_id,
      inbound_shipment_id,
      outcome,
      return_id,
      quantity,
      sell_amount,
      allocated_shop_delivery,
      allocated_shop_cod_fee,
      allocated_shop_packing,
      allocated_return_courier,
      allocated_fees_total,
      cogs_is_loss,
      event_at,
      event_date
    ) VALUES (
      p_tenant_id,
      p_invoice_id,
      v_line.invoice_item_id,
      v_line.stock_id,
      v_inbound_shipment_id,
      'RTO',
      NULL,
      v_line.quantity,
      0.00,
      v_alloc_delivery,
      0.00,
      v_alloc_packing,
      v_alloc_return,
      ROUND(v_alloc_delivery + v_alloc_packing + v_alloc_return, 2),
      FALSE,
      v_event_at,
      (v_event_at AT TIME ZONE 'UTC')::DATE
    )
    ON CONFLICT (invoice_item_id) DO UPDATE SET
      outcome = 'RTO',
      return_id = NULL,
      sell_amount = 0.00,
      allocated_shop_delivery = EXCLUDED.allocated_shop_delivery,
      allocated_shop_cod_fee = 0.00,
      allocated_shop_packing = EXCLUDED.allocated_shop_packing,
      allocated_return_courier = EXCLUDED.allocated_return_courier,
      allocated_fees_total = EXCLUDED.allocated_fees_total,
      cogs_is_loss = FALSE,
      event_at = EXCLUDED.event_at,
      event_date = EXCLUDED.event_date,
      updated_at = NOW();
  END LOOP;

  UPDATE public.thrift_sales_invoices
  SET
    status = 'RETURNED',
    payment_status = 'REFUNDED',
    close_reason = 'RTO',
    delivery_status = 'RETURNED',
    return_courier_amount = v_return_courier,
    economics_closed_at = v_event_at,
    cod_expected = NULL,
    cod_remitted_amount = NULL,
    cod_remitted_at = NULL,
    cod_remittance_ref = NULL,
    reverted_at = v_event_at,
    reverted_by = p_reverted_by,
    revert_reason = 'RTO',
    revert_notes = NULLIF(trim(p_notes), ''),
    updated_at = NOW()
  WHERE id = p_invoice_id
    AND tenant_id = p_tenant_id;

  RETURN jsonb_build_object(
    'id', p_invoice_id,
    'invoice_number', v_invoice_number,
    'status', 'RETURNED',
    'close_reason', 'RTO',
    'delivery_status', 'RETURNED',
    'payment_status', 'REFUNDED',
    'return_courier_amount', v_return_courier,
    'ledger_refund_amount', v_ledger_refund,
    'advance_retained', v_advance_amount,
    'reason', 'RTO',
    'deleted', false
  );
END;
$$;


ALTER FUNCTION "public"."revert_thrift_sales_invoice"("p_tenant_id" bigint, "p_invoice_id" bigint, "p_reason" "text", "p_reverted_by" "text", "p_notes" "text", "p_force" boolean, "p_return_courier_amount" numeric) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."revert_thrift_sales_invoice"("p_tenant_id" bigint, "p_invoice_id" bigint, "p_reason" "text", "p_reverted_by" "text", "p_notes" "text", "p_force" boolean, "p_return_courier_amount" numeric) IS 'RTO: soft-close; ledger REFUND excludes advance_amount (non-refundable). STAFF_MISTAKE: hard-delete. Legacy RETURN→RTO.';



CREATE OR REPLACE FUNCTION "public"."revise_global_shipment_costs"("p_shipment_id" bigint, "p_entries" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_ship public.global_shipments%ROWTYPE;
  v_entry jsonb;
  v_stamped integer;
  v_old_costs jsonb;
BEGIN
  SELECT * INTO v_ship FROM public.global_shipments WHERE id = p_shipment_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'shipment not found';
  END IF;

  IF NOT public.user_can_manage_parent_tenant(v_ship.parent_tenant_id) THEN
    RAISE EXCEPTION 'not allowed';
  END IF;

  IF NOT public.global_shipment_stock_is_posted(v_ship) THEN
    RAISE EXCEPTION 'shipment not finalized; use upsert_global_shipment_cost_entry';
  END IF;

  IF public.global_shipment_costs_are_locked(v_ship) THEN
    RAISE EXCEPTION 'shipment costs are locked';
  END IF;

  IF p_entries IS NULL OR jsonb_typeof(p_entries) <> 'array' OR jsonb_array_length(p_entries) = 0 THEN
    RAISE EXCEPTION 'p_entries must be a non-empty array';
  END IF;

  SELECT coalesce(jsonb_agg(jsonb_build_object(
    'id', e.id,
    'cost_type', e.cost_type,
    'amount', e.amount,
    'exchange_rate', e.exchange_rate,
    'landed_snapshot', (
      SELECT coalesce(jsonb_agg(jsonb_build_object(
        'item_id', i.id,
        'landed_cost_bdt', i.landed_cost_bdt
      )), '[]'::jsonb)
      FROM public.global_shipment_items i
      WHERE i.shipment_id = p_shipment_id
    )
  )), '[]'::jsonb)
  INTO v_old_costs
  FROM public.global_shipment_cost_entries e
  WHERE e.shipment_id = p_shipment_id;

  DELETE FROM public.global_shipment_cost_entries WHERE shipment_id = p_shipment_id;

  FOR v_entry IN SELECT value FROM jsonb_array_elements(p_entries)
  LOOP
    INSERT INTO public.global_shipment_cost_entries (
      parent_tenant_id,
      shipment_id,
      cost_type,
      amount,
      currency_id,
      exchange_rate,
      payment_source,
      entity_type,
      entity_id,
      allocation,
      metadata
    ) VALUES (
      v_ship.parent_tenant_id,
      p_shipment_id,
      (v_entry->>'cost_type')::public.global_shipment_cost_type,
      (v_entry->>'amount')::numeric,
      nullif(v_entry->>'currency_id', '')::bigint,
      coalesce(nullif(v_entry->>'exchange_rate', '')::numeric, 1.0),
      nullif(v_entry->>'payment_source', ''),
      nullif(v_entry->>'entity_type', ''),
      nullif(v_entry->>'entity_id', '')::bigint,
      nullif(v_entry->>'allocation', ''),
      coalesce(v_entry->'metadata', '{}'::jsonb)
    );
  END LOOP;

  v_stamped := public.stamp_global_shipment_landed_costs(p_shipment_id);

  RETURN jsonb_build_object(
    'shipment_id', p_shipment_id,
    'items_stamped', v_stamped,
    'prior_entries', v_old_costs,
    'wallet_posted', false
  );
END;
$$;


ALTER FUNCTION "public"."revise_global_shipment_costs"("p_shipment_id" bigint, "p_entries" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."revoke_costing_file_viewer"("p_costing_file_id" bigint, "p_membership_id" bigint) RETURNS TABLE("costing_file_viewer_id" bigint, "costing_file_id" bigint, "membership_id" bigint, "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  delete from public.costing_file_viewers cfv
  using public.costing_files cf
  where cf.id = p_costing_file_id
    and cf.id = cfv.costing_file_id
    and cfv.membership_id = p_membership_id
    and public.can_manage_costing_file_viewers(cf.tenant_id)
  returning
    cfv.id as costing_file_viewer_id,
    cfv.costing_file_id,
    cfv.membership_id,
    cfv.created_at,
    cfv.updated_at;
$$;


ALTER FUNCTION "public"."revoke_costing_file_viewer"("p_costing_file_id" bigint, "p_membership_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."revoke_shipment_tracking_token"("p_shipment_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_ship public.global_shipments%rowtype;
begin
  select * into v_ship
  from public.global_shipments
  where id = p_shipment_id
  for update;

  if not found then
    raise exception 'shipment not found';
  end if;

  if not public.has_active_tenant_membership(v_ship.parent_tenant_id)
     and not public.is_superadmin() then
    raise exception 'not authorized';
  end if;

  update public.global_shipments
  set public_tracking_token = null, updated_at = now()
  where id = p_shipment_id;
end;
$$;


ALTER FUNCTION "public"."revoke_shipment_tracking_token"("p_shipment_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."round_bdt_up_to_zero_or_five"("p_value" numeric) RETURNS integer
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
declare
  v_rounded_up integer;
  v_remainder integer;
begin
  v_rounded_up := ceil(coalesce(p_value, 0))::integer;
  v_remainder := mod(v_rounded_up, 5);

  if v_remainder = 0 then
    return v_rounded_up;
  end if;

  return v_rounded_up + (5 - v_remainder);
end;
$$;


ALTER FUNCTION "public"."round_bdt_up_to_zero_or_five"("p_value" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_dropship_settlement_draft"("p_tenant_id" bigint, "p_order_id" bigint, "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_order public.shop_orders;
  v_detail jsonb;
  v_settlement public.dropship_order_settlements;
  v_has_settlement boolean := false;
  v_calculated_cod numeric(15,2);
  v_collected_cod numeric(15,2);
  v_items_resell_total numeric(15,2);
  v_order_discount_amount numeric(15,2);
  v_reseller_purchase_cost numeric(15,2);
  v_reseller_unit_purchase_cost numeric(15,2);
  v_company_procurement_cost numeric(15,2);
  v_discount_company_pay numeric(15,2);
  v_return_reason_note text;
  v_charge_lines jsonb;
  v_line jsonb;
  v_totals record;
  v_currency_id bigint;
  v_payload_unit numeric(15,2);
begin
  if not public.is_tenant_staff(p_tenant_id) then
    raise exception 'access denied';
  end if;

  select * into v_order
  from public.shop_orders
  where id = p_order_id
  for update;

  if not found then
    raise exception 'order not found';
  end if;

  if v_order.tenant_id is distinct from p_tenant_id
     and v_order.parent_tenant_id is distinct from p_tenant_id then
    raise exception 'order not found';
  end if;

  if v_order.shop_type_snapshot <> 'dropship' then
    raise exception 'not a dropship order';
  end if;

  v_collected_cod := coalesce((p_payload->>'collected_cod_amount')::numeric, 0);
  v_discount_company_pay := coalesce((p_payload->>'discount_company_pay')::numeric, 0);
  v_return_reason_note := nullif(trim(coalesce(p_payload->>'return_reason_note', '')), '');
  v_charge_lines := coalesce(p_payload->'charge_lines', '[]'::jsonb);

  if jsonb_typeof(v_charge_lines) <> 'array' then
    raise exception 'charge_lines must be a JSON array';
  end if;

  perform public.apply_dropship_order_charge_lines(p_order_id, v_charge_lines);

  v_payload_unit := (p_payload->>'reseller_unit_purchase_cost')::numeric;
  if v_payload_unit is not null then
    perform public.apply_dropship_reseller_unit_purchase(p_order_id, v_payload_unit);
  end if;

  select * into v_order
  from public.shop_orders
  where id = p_order_id;

  v_detail := public.get_dropship_order_detail_v2(p_tenant_id, p_order_id);
  v_calculated_cod := coalesce(
    (v_detail->'computed'->>'recipient_grand_total')::numeric,
    (v_detail->'summary'->>'cod_collect_amount')::numeric,
    coalesce(v_order.cod_collect_amount, 0)
  );
  v_items_resell_total := coalesce((v_detail->'computed'->>'items_resell_total')::numeric, 0);
  v_order_discount_amount := coalesce(
    (v_detail->'order'->>'discount_amount')::numeric,
    v_order.discount_amount,
    0
  );

  select s.sell_currency_id into v_currency_id
  from public.shops s where s.id = v_order.shop_id;

  select
    rp.reseller_unit_purchase_cost,
    rp.reseller_purchase_cost
  into v_reseller_unit_purchase_cost, v_reseller_purchase_cost
  from public.compute_dropship_order_reseller_purchase(p_order_id) rp;

  select coalesce(
    sum(public.resolve_shop_order_item_landed_cost(soi.global_stock_id, soi.cost_price_amount, soi.unit_list_price_amount) * soi.quantity),
    0
  )
  into v_company_procurement_cost
  from public.shop_order_items soi
  inner join public.shop_orders o on o.id = soi.order_id
  where soi.order_id = p_order_id;

  select * into v_settlement
  from public.dropship_order_settlements
  where shop_order_id = p_order_id;

  v_has_settlement := found;

  if v_has_settlement and v_settlement.status = 'confirmed' then
    raise exception 'settlement is confirmed and cannot be edited';
  end if;

  select * into v_totals
  from public.compute_dropship_settlement_totals(
    v_items_resell_total,
    v_order_discount_amount,
    v_reseller_purchase_cost,
    v_company_procurement_cost,
    v_discount_company_pay,
    v_charge_lines
  );

  if not v_has_settlement then
    insert into public.dropship_order_settlements (
      tenant_id,
      shop_order_id,
      billing_profile_id,
      currency_id,
      calculated_cod_amount,
      collected_cod_amount,
      reseller_unit_purchase_cost,
      reseller_purchase_cost,
      discount_company_pay,
      return_reason_note,
      total_cost,
      reseller_profit,
      company_profit,
      status
    ) values (
      v_order.tenant_id,
      p_order_id,
      v_order.billing_profile_id,
      v_currency_id,
      v_calculated_cod,
      v_collected_cod,
      v_reseller_unit_purchase_cost,
      v_reseller_purchase_cost,
      v_discount_company_pay,
      v_return_reason_note,
      v_totals.total_cost,
      v_totals.reseller_profit,
      v_totals.company_profit,
      'draft'
    )
    returning * into v_settlement;
  else
    update public.dropship_order_settlements
    set
      billing_profile_id = coalesce(v_order.billing_profile_id, billing_profile_id),
      currency_id = coalesce(v_currency_id, currency_id),
      calculated_cod_amount = v_calculated_cod,
      collected_cod_amount = v_collected_cod,
      reseller_unit_purchase_cost = v_reseller_unit_purchase_cost,
      reseller_purchase_cost = v_reseller_purchase_cost,
      discount_company_pay = v_discount_company_pay,
      return_reason_note = v_return_reason_note,
      total_cost = v_totals.total_cost,
      reseller_profit = v_totals.reseller_profit,
      company_profit = v_totals.company_profit,
      updated_at = now()
    where id = v_settlement.id
    returning * into v_settlement;
  end if;

  if v_settlement.id is null then
    raise exception 'settlement row missing after upsert';
  end if;

  delete from public.dropship_settlement_charge_lines
  where settlement_id = v_settlement.id;

  for v_line in select value from jsonb_array_elements(v_charge_lines)
  loop
    insert into public.dropship_settlement_charge_lines (
      settlement_id,
      charge_type,
      amount,
      payer
    ) values (
      v_settlement.id,
      (v_line->>'charge_type')::public.dropship_settlement_charge_type,
      coalesce((v_line->>'amount')::numeric, 0),
      (v_line->>'payer')::public.dropship_settlement_charge_payer
    );
  end loop;

  return jsonb_build_object(
    'success', true,
    'settlement_id', v_settlement.id,
    'settlement', jsonb_build_object(
      'id', v_settlement.id,
      'status', v_settlement.status,
      'calculated_cod_amount', v_calculated_cod,
      'collected_cod_amount', v_settlement.collected_cod_amount,
      'reseller_unit_purchase_cost', v_reseller_unit_purchase_cost,
      'reseller_purchase_cost', v_reseller_purchase_cost,
      'company_procurement_cost', v_company_procurement_cost,
      'discount_company_pay', v_settlement.discount_company_pay,
      'return_reason_note', v_settlement.return_reason_note,
      'total_cost', v_settlement.total_cost,
      'reseller_profit', v_settlement.reseller_profit,
      'company_profit', v_settlement.company_profit,
      'courier_cod_booked_at', v_settlement.courier_cod_booked_at,
      'remittance_at', v_settlement.remittance_at,
      'merchant_payout_at', v_settlement.merchant_payout_at
    )
  );
end;
$$;


ALTER FUNCTION "public"."save_dropship_settlement_draft"("p_tenant_id" bigint, "p_order_id" bigint, "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_global_shipment_cost_entries"("p_shipment_id" bigint, "p_entries" "jsonb", "p_delete_ids" bigint[] DEFAULT '{}'::bigint[], "p_received_weight" numeric DEFAULT NULL::numeric, "p_total_weight_kg" numeric DEFAULT NULL::numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_ship public.global_shipments%rowtype;
  v_entry jsonb;
  v_row public.global_shipment_cost_entries%rowtype;
  v_id bigint;
  v_amount numeric;
  v_rate numeric;
  v_stamped integer := 0;
  v_cost_entries jsonb;
  v_items jsonb;
begin
  select * into v_ship from public.global_shipments where id = p_shipment_id for update;
  if not found then
    raise exception 'shipment not found';
  end if;

  if not public.user_can_manage_parent_tenant(v_ship.parent_tenant_id) then
    raise exception 'not allowed';
  end if;

  if public.global_shipment_costs_are_locked(v_ship) then
    raise exception 'shipment costs are locked';
  end if;

  perform set_config('app.skip_shipment_landed_restamp', '1', true);

  if p_received_weight is not null or p_total_weight_kg is not null then
    update public.global_shipments
    set
      received_weight = coalesce(p_received_weight, received_weight),
      total_weight_kg = coalesce(p_total_weight_kg, total_weight_kg),
      updated_at = now()
    where id = p_shipment_id
    returning * into v_ship;
  end if;

  if p_delete_ids is not null and cardinality(p_delete_ids) > 0 then
    delete from public.global_shipment_cost_entries e
    where e.shipment_id = p_shipment_id
      and e.id = any(p_delete_ids);
  end if;

  if p_entries is not null and jsonb_typeof(p_entries) = 'array' then
    for v_entry in select value from jsonb_array_elements(p_entries)
    loop
      v_amount := nullif(v_entry->>'amount', '')::numeric;
      v_rate := coalesce(nullif(v_entry->>'exchange_rate', '')::numeric, 1.0);
      v_id := nullif(v_entry->>'id', '')::bigint;

      if v_amount is null or v_amount < 0 then
        raise exception 'amount must be >= 0';
      end if;

      if v_rate is null or v_rate <= 0 then
        raise exception 'exchange_rate must be > 0';
      end if;

      if v_id is not null then
        update public.global_shipment_cost_entries e
        set
          cost_type = (v_entry->>'cost_type')::public.global_shipment_cost_type,
          amount = v_amount,
          exchange_rate = v_rate,
          currency_id = nullif(v_entry->>'currency_id', '')::bigint,
          payment_source = nullif(v_entry->>'payment_source', ''),
          entity_type = nullif(v_entry->>'entity_type', ''),
          entity_id = nullif(v_entry->>'entity_id', '')::bigint,
          allocation = nullif(v_entry->>'allocation', ''),
          metadata = coalesce(v_entry->'metadata', '{}'::jsonb),
          updated_at = now()
        where e.id = v_id
          and e.shipment_id = p_shipment_id
        returning * into v_row;

        if not found then
          raise exception 'cost entry % not found on shipment %', v_id, p_shipment_id;
        end if;
      else
        insert into public.global_shipment_cost_entries (
          parent_tenant_id,
          shipment_id,
          cost_type,
          amount,
          currency_id,
          exchange_rate,
          payment_source,
          entity_type,
          entity_id,
          allocation,
          metadata
        ) values (
          v_ship.parent_tenant_id,
          p_shipment_id,
          (v_entry->>'cost_type')::public.global_shipment_cost_type,
          v_amount,
          nullif(v_entry->>'currency_id', '')::bigint,
          v_rate,
          nullif(v_entry->>'payment_source', ''),
          nullif(v_entry->>'entity_type', ''),
          nullif(v_entry->>'entity_id', '')::bigint,
          nullif(v_entry->>'allocation', ''),
          coalesce(v_entry->'metadata', '{}'::jsonb)
        )
        returning * into v_row;
      end if;
    end loop;
  end if;

  perform set_config('app.skip_shipment_landed_restamp', '0', true);

  if exists (select 1 from public.global_shipment_items where shipment_id = p_shipment_id) then
    v_stamped := public.stamp_global_shipment_landed_costs(p_shipment_id);
  end if;

  select coalesce(jsonb_agg(to_jsonb(e) order by e.id), '[]'::jsonb)
  into v_cost_entries
  from public.global_shipment_cost_entries e
  where e.shipment_id = p_shipment_id;

  select coalesce(jsonb_agg(to_jsonb(i) order by i.sort_order, i.id), '[]'::jsonb)
  into v_items
  from public.global_shipment_items i
  where i.shipment_id = p_shipment_id;

  return jsonb_build_object(
    'cost_entries', v_cost_entries,
    'items', v_items,
    'items_stamped', v_stamped,
    'shipment', jsonb_build_object(
      'id', v_ship.id,
      'received_weight', v_ship.received_weight,
      'total_weight_kg', v_ship.total_weight_kg,
      'updated_at', v_ship.updated_at
    )
  );
end;
$$;


ALTER FUNCTION "public"."save_global_shipment_cost_entries"("p_shipment_id" bigint, "p_entries" "jsonb", "p_delete_ids" bigint[], "p_received_weight" numeric, "p_total_weight_kg" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_my_push_subscription"("p_fcm_token" "text", "p_platform" "text" DEFAULT 'web'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_token text := nullif(trim(coalesce(p_fcm_token, '')), '');
  v_platform text := coalesce(nullif(trim(coalesce(p_platform, '')), ''), 'web');
  v_subscription_id uuid;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF v_token IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'p_fcm_token is required');
  END IF;

  IF v_platform NOT IN ('web', 'android') THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid platform');
  END IF;

  INSERT INTO public.user_push_subscriptions AS s (
    user_id,
    fcm_token,
    platform,
    last_used_at
  )
  VALUES (
    v_user_id,
    v_token,
    v_platform,
    now()
  )
  ON CONFLICT (user_id, fcm_token) DO UPDATE
  SET
    platform = EXCLUDED.platform,
    last_used_at = now()
  RETURNING s.id INTO v_subscription_id;

  INSERT INTO public.user_notification_preferences AS p (
    user_id,
    channel_push,
    updated_at
  )
  VALUES (
    v_user_id,
    true,
    now()
  )
  ON CONFLICT (user_id) DO UPDATE
  SET
    channel_push = true,
    updated_at = now();

  RETURN jsonb_build_object(
    'success', true,
    'subscription_id', v_subscription_id,
    'channel_push', true
  );
END;
$$;


ALTER FUNCTION "public"."save_my_push_subscription"("p_fcm_token" "text", "p_platform" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_sales_invoice_stock"("p_tenant_id" bigint, "p_search" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS TABLE("global_stock_id" bigint, "shipment_item_id" bigint, "product_id" bigint, "name" "text", "barcode" "text", "product_code" "text", "image_url" "text", "quantity" numeric, "available_atp" numeric, "unit_cost_price" numeric, "suggested_sell_price" numeric, "shipment_id" bigint, "shipment_name" "text", "holding_tenant_id" bigint, "holding_tenant_name" "text", "is_allocated_to_tenant" boolean, "allocation_rank" integer, "location_id" bigint, "location_name" "text", "stock_created_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_parent_id bigint;
  v_is_parent_context boolean;
begin
  if p_tenant_id is null then
    raise exception 'tenant_id is required';
  end if;

  v_parent_id := public.resolve_parent_tenant_id(p_tenant_id);
  v_is_parent_context := (p_tenant_id = v_parent_id);

  -- Verify membership & access (checks active tenant or parent tenant membership)
  if not exists (
    select 1
    from public.memberships m
    where (m.tenant_id = p_tenant_id or m.tenant_id = v_parent_id)
      and lower(trim(m.email)) = public.current_user_email()
      and m.is_active = true
  ) and not public.is_superadmin() then
    raise exception 'not allowed';
  end if;

  return query
  select
    gs.id as global_stock_id,
    gsi.id as shipment_item_id,
    gsi.product_id,
    gsi.name,
    gsi.barcode,
    gsi.product_code,
    gsi.image_url,
    gs.quantity::numeric as quantity,
    public.global_stock_atp_qty(gs.id)::numeric as available_atp,
    coalesce(gsi.landed_cost_bdt, gsi.purchase_price, 0)::numeric as unit_cost_price,
    coalesce(p.list_price_amount, 0)::numeric as suggested_sell_price,
    sh.id as shipment_id,
    sh.name as shipment_name,
    coalesce(sh.assigned_child_tenant_id, v_parent_id) as holding_tenant_id,
    coalesce(ht.name, pt.name) as holding_tenant_name,
    (coalesce(sh.assigned_child_tenant_id, v_parent_id) = p_tenant_id) as is_allocated_to_tenant,
    case
      -- 0 = Directly allocated to the requesting child/sister tenant
      when sh.assigned_child_tenant_id = p_tenant_id then 0
      -- 1 = Parent company stock / unallocated to specific child
      when sh.assigned_child_tenant_id is null or sh.assigned_child_tenant_id = v_parent_id then 1
      -- 2 = Allocated to another sister concern (visible in parent context)
      else 2
    end as allocation_rank,
    gs.location_id,
    sl.name as location_name,
    gs.created_at as stock_created_at
  from public.global_stocks gs
  inner join public.global_shipment_items gsi on gsi.id = gs.shipment_item_id
  inner join public.global_shipments sh on sh.id = gsi.shipment_id
  inner join public.tenants pt on pt.id = v_parent_id
  left join public.tenants ht on ht.id = coalesce(sh.assigned_child_tenant_id, v_parent_id)
  left join public.stock_locations sl on sl.id = gs.location_id
  left join public.products p on p.id = gsi.product_id
  where gs.parent_tenant_id = v_parent_id
    and (
      v_is_parent_context
      or sh.assigned_child_tenant_id is null
      or sh.assigned_child_tenant_id = p_tenant_id
    )
    and sh.status = 'received'
    and gs.availability = 'sellable'::public.stock_availability
    and gs.quantity > 0
    and (
      p_search is null
      or trim(p_search) = ''
      or (
        select coalesce(bool_and(
          gsi.name ilike '%' || trim(word) || '%'
          or coalesce(gsi.barcode, '') ilike '%' || trim(word) || '%'
          or coalesce(gsi.product_code, '') ilike '%' || trim(word) || '%'
          or coalesce(p.name, '') ilike '%' || trim(word) || '%'
        ), true)
        from unnest(string_to_array(trim(p_search), ' ')) as word
        where trim(word) <> ''
      )
    )
  order by
    -- 1. Show items allocated to the tenant first, then parent/unallocated, then others
    case
      when sh.assigned_child_tenant_id = p_tenant_id then 0
      when sh.assigned_child_tenant_id is null or sh.assigned_child_tenant_id = v_parent_id then 1
      else 2
    end asc,
    -- 2. FIFO Order: Oldest stock (earliest insert date) appears first
    gs.created_at asc,
    gs.id asc
  limit greatest(coalesce(p_limit, 50), 1)
  offset greatest(coalesce(p_offset, 0), 0);
end;
$$;


ALTER FUNCTION "public"."search_sales_invoice_stock"("p_tenant_id" bigint, "p_search" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_shop_catalog_for_customer"("p_tenant_id" bigint, "p_search" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 20, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_parent_tenant_id bigint;
  v_search text;
  v_limit integer;
  v_offset integer;
  v_result jsonb;
begin
  if p_tenant_id is null then
    raise exception 'tenant required';
  end if;

  if public.current_customer_group_id(p_tenant_id) is null then
    raise exception 'access denied';
  end if;

  v_search := nullif(trim(coalesce(p_search, '')), '');
  v_limit := greatest(1, least(coalesce(p_limit, 20), 50));
  v_offset := greatest(0, coalesce(p_offset, 0));

  if v_search is null then
    return jsonb_build_object(
      'data', '[]'::jsonb,
      'meta', jsonb_build_object(
        'total', 0,
        'page', 1,
        'page_size', v_limit,
        'total_pages', 1
      )
    );
  end if;

  v_parent_tenant_id := public.resolve_parent_tenant_id(p_tenant_id);

  with accessible_shops as (
    select
      s.id,
      s.slug,
      s.name,
      s.shop_type,
      s.vendor_code,
      s.vendor_filters,
      s.min_available_units,
      s.tenant_id,
      s.pricing_method,
      s.markup_percentage,
      bool_or(
        case
          when access.status = false or coalesce(profile.is_active, true) = false then false
          else public.resolve_shop_can_see_buy_price(
            s.shop_type,
            access.can_see_buy_price,
            access.can_see_sell_price,
            profile.default_can_see_buy_price,
            profile.default_can_see_sell_price
          )
        end
      ) as can_see_buy_price,
      bool_or(
        case
          when access.status = false or coalesce(profile.is_active, true) = false then false
          when s.shop_type = 'dropship' then true
          else coalesce(access.can_see_sell_price, profile.default_can_see_sell_price, false)
        end
      ) as can_see_sell_price
    from public.shops s
    join public.shop_customer_group_access access on access.shop_id = s.id
    join public.customer_groups cg on cg.id = access.customer_group_id
    left join public.customer_group_shop_profiles profile
      on profile.customer_group_id = cg.id and profile.tenant_id = s.tenant_id
    where s.is_active = true
      and s.deleted_at is null
      and s.tenant_id = p_tenant_id
      and cg.id = public.current_customer_group_id(p_tenant_id)
      and cg.is_active = true
      and access.status = true
      and coalesce(profile.is_active, true) = true
      and coalesce(access.can_browse, profile.default_can_browse, false) = true
    group by
      s.id,
      s.slug,
      s.name,
      s.shop_type,
      s.vendor_code,
      s.vendor_filters,
      s.min_available_units,
      s.tenant_id,
      s.pricing_method,
      s.markup_percentage
  ),
  vendor_catalog_rows as (
    select
      s.id as shop_id,
      s.slug as shop_slug,
      s.name as shop_name,
      p.id as product_id,
      p.name as product_name,
      p.image_url as product_image_url,
      p.barcode as product_barcode,
      p.product_code as product_code,
      p.brand as product_brand,
      p.category as product_category,
      case when s.can_see_buy_price then p.list_price_amount else null end as unit_price_amount,
      case when s.can_see_buy_price then p.list_price_currency_id else null end as unit_price_currency_id,
      case when s.can_see_buy_price then gc.symbol else null end as unit_price_currency_symbol
    from accessible_shops s
    join public.products p on p.parent_tenant_id = v_parent_tenant_id
    left join public.global_currencies gc on gc.id = p.list_price_currency_id
    where s.shop_type = 'vendor_catalog'
      and p.is_available = true
      and coalesce(p.hazardous, false) = false
      and (
        ((s.vendor_filters is null or jsonb_array_length(s.vendor_filters) = 0) and p.vendor_code = s.vendor_code)
        or (
          s.vendor_filters is not null and jsonb_array_length(s.vendor_filters) > 0 and exists (
            select 1
            from jsonb_to_recordset(s.vendor_filters) as vf(vendor_code text, brands text[])
            where vf.vendor_code = p.vendor_code
              and (vf.brands is null or array_length(vf.brands, 1) is null or p.brand = any(vf.brands))
          )
        )
      )
      and public.shop_catalog_meets_min_available_units(s.min_available_units, p.available_units)
      and (
        p.name ilike ('%' || v_search || '%')
        or p.product_code ilike ('%' || v_search || '%')
        or p.barcode ilike ('%' || v_search || '%')
      )
  ),
  listing_rows as (
    select
      s.id as shop_id,
      s.slug as shop_slug,
      s.name as shop_name,
      p.id as product_id,
      p.name as product_name,
      p.image_url as product_image_url,
      p.barcode as product_barcode,
      p.product_code as product_code,
      p.brand as product_brand,
      p.category as product_category,
      case
        when s.shop_type = 'dropship' and not s.can_see_buy_price then null
        when s.shop_type = 'fixed_price' and not s.can_see_sell_price then null
        when s.shop_type = 'fixed_price' and s.pricing_method = 'markup' then
          coalesce(gsi.landed_cost_bdt, public.calculate_landed_unit_cost(gsi.id)) * (1 + s.markup_percentage / 100.0)
        when s.shop_type = 'fixed_price' and s.pricing_method = 'direct_cost' then
          coalesce(gsi.landed_cost_bdt, public.calculate_landed_unit_cost(gsi.id))
        else l.sell_price_amount
      end as unit_price_amount,
      case
        when s.shop_type = 'dropship' and s.can_see_buy_price then l.sell_price_currency_id
        when s.shop_type = 'fixed_price' and s.can_see_sell_price then l.sell_price_currency_id
        else null
      end as unit_price_currency_id,
      case
        when s.shop_type = 'dropship' and s.can_see_buy_price then gc.symbol
        when s.shop_type = 'fixed_price' and s.can_see_sell_price then gc.symbol
        else null
      end as unit_price_currency_symbol
    from accessible_shops s
    join public.shop_product_listings l on l.shop_id = s.id
    join public.products p on p.id = l.product_id
    left join public.global_stocks gs on gs.id = l.global_stock_id
    left join public.global_shipment_items gsi on gsi.id = gs.shipment_item_id
    left join public.global_currencies gc on gc.id = l.sell_price_currency_id
    where s.shop_type <> 'vendor_catalog'
      and l.is_active = true
      and p.is_available = true
      and coalesce(p.hazardous, false) = false
      and (
        p.name ilike ('%' || v_search || '%')
        or p.product_code ilike ('%' || v_search || '%')
        or p.barcode ilike ('%' || v_search || '%')
      )
  ),
  combined as (
    select * from vendor_catalog_rows
    union all
    select * from listing_rows
  ),
  ranked as (
    select
      c.*,
      row_number() over (
        partition by c.product_id
        order by c.shop_name asc, c.shop_id asc
      ) as row_num
    from combined c
  ),
  deduped as (
    select * from ranked where row_num = 1
  )
  select jsonb_build_object(
    'data',
    coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'shop_id', d.shop_id,
            'shop_slug', d.shop_slug,
            'shop_name', d.shop_name,
            'product_id', d.product_id,
            'product_name', d.product_name,
            'product_image_url', d.product_image_url,
            'product_barcode', d.product_barcode,
            'product_code', d.product_code,
            'product_brand', d.product_brand,
            'product_category', d.product_category,
            'unit_price_amount', d.unit_price_amount,
            'unit_price_currency_id', d.unit_price_currency_id,
            'unit_price_currency_symbol', d.unit_price_currency_symbol
          )
          order by d.product_name asc, d.product_id asc
        )
        from (
          select *
          from deduped
          order by product_name asc, product_id asc
          limit v_limit
          offset v_offset
        ) d
      ),
      '[]'::jsonb
    ),
    'meta',
    jsonb_build_object(
      'total', (select count(*)::bigint from deduped),
      'page', (v_offset / v_limit) + 1,
      'page_size', v_limit,
      'total_pages', greatest(1, ceil((select count(*)::numeric from deduped) / v_limit::numeric))
    )
  )
  into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."search_shop_catalog_for_customer"("p_tenant_id" bigint, "p_search" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_stock_network"("p_context_tenant_id" bigint, "p_mode" "text" DEFAULT 'search'::"text", "p_search" "text" DEFAULT NULL::"text", "p_search_field" "text" DEFAULT NULL::"text", "p_product_id" bigint DEFAULT NULL::bigint, "p_status" "text" DEFAULT 'excellent'::"text", "p_shipment_id" bigint DEFAULT NULL::bigint, "p_exclude_zero_qty" boolean DEFAULT true, "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS TABLE("global_stock_id" bigint, "product_id" bigint, "name" "text", "barcode" "text", "product_code" "text", "image_url" "text", "shipment_item_id" bigint, "ordered_quantity" integer, "purchase_price" numeric, "product_weight" numeric, "package_weight" numeric, "shipment_type" "text", "product_conversion_rate" numeric, "cargo_conversion_rate" numeric, "cargo_rate" numeric, "received_weight" numeric, "transaction_rate" numeric, "shipment_id" bigint, "shipment_name" "text", "parent_tenant_id" bigint, "holding_tenant_id" bigint, "holding_tenant_name" "text", "allocated_qty" integer, "global_qty" integer, "excellent_qty" integer, "box_less_qty" integer, "box_damage_qty" integer, "expired_qty" integer, "stolen_qty" integer, "reserved_qty" integer, "total_qty" integer, "is_own_tenant" boolean, "is_pickable" boolean, "sort_rank" integer, "product_group_key" "text", "available_atp" numeric, "location_id" bigint, "location_name" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_parent_id bigint;
  v_is_parent_context boolean;
  v_avail public.stock_availability;
begin
  if p_context_tenant_id is null then
    raise exception 'context tenant is required';
  end if;

  if not exists (
    select 1
    from public.memberships m
    where m.tenant_id = p_context_tenant_id
      and lower(trim(m.email)) = public.current_user_email()
      and m.is_active = true
  ) then
    raise exception 'not allowed';
  end if;

  v_parent_id := public.resolve_parent_tenant_id(p_context_tenant_id);
  v_is_parent_context := (p_context_tenant_id = v_parent_id);

  v_avail := case lower(coalesce(nullif(trim(p_status), ''), 'excellent'))
    when 'excellent' then 'sellable'::public.stock_availability
    when 'sellable' then 'sellable'::public.stock_availability
    when 'held' then 'held'::public.stock_availability
    when 'hold' then 'held'::public.stock_availability
    when 'reserved' then 'held'::public.stock_availability
    when 'unsellable' then 'unsellable'::public.stock_availability
    when 'damaged' then 'unsellable'::public.stock_availability
    when 'box_damage' then 'unsellable'::public.stock_availability
    when 'box_less' then 'unsellable'::public.stock_availability
    when 'expired' then 'unsellable'::public.stock_availability
    when 'stolen' then 'unsellable'::public.stock_availability
    else null
  end;

  return query
  select
    gs.id as global_stock_id,
    gsi.product_id,
    gsi.name,
    gsi.barcode,
    gsi.product_code,
    gsi.image_url,
    gsi.id as shipment_item_id,
    gsi.ordered_quantity,
    gsi.purchase_price,
    gsi.product_weight,
    gsi.package_weight,
    sh.type::text as shipment_type,
    1.0::numeric as product_conversion_rate,
    1.0::numeric as cargo_conversion_rate,
    0::numeric as cargo_rate,
    sh.received_weight,
    1.0::numeric as transaction_rate,
    gsi.shipment_id,
    sh.name as shipment_name,
    gs.parent_tenant_id,
    coalesce(sh.assigned_child_tenant_id, v_parent_id) as holding_tenant_id,
    coalesce(ht.name, pt.name) as holding_tenant_name,
    gs.quantity as allocated_qty,
    gs.quantity as global_qty,
    case when gs.availability = 'sellable' then gs.quantity else 0 end as excellent_qty,
    0 as box_less_qty,
    case when gs.availability = 'unsellable' then gs.quantity else 0 end as box_damage_qty,
    0 as expired_qty,
    0 as stolen_qty,
    case when gs.availability = 'held' then gs.quantity else 0 end as reserved_qty,
    gs.quantity as total_qty,
    (coalesce(sh.assigned_child_tenant_id, v_parent_id) = p_context_tenant_id) as is_own_tenant,
    (gs.availability = 'sellable' and (gs.location_id is null or sl.is_pickable = true)) as is_pickable,
    case
      when coalesce(sh.assigned_child_tenant_id, v_parent_id) = p_context_tenant_id then 0
      else 1
    end as sort_rank,
    coalesce(gsi.product_id::text, 'stock:' || gs.id::text) as product_group_key,
    public.global_stock_atp_qty(gs.id) as available_atp,
    gs.location_id,
    sl.name as location_name
  from public.global_stocks gs
  inner join public.global_shipment_items gsi on gsi.id = gs.shipment_item_id
  inner join public.global_shipments sh on sh.id = gsi.shipment_id
  inner join public.tenants pt on pt.id = v_parent_id
  left join public.tenants ht on ht.id = coalesce(sh.assigned_child_tenant_id, v_parent_id)
  left join public.stock_locations sl on sl.id = gs.location_id
  where gs.parent_tenant_id = v_parent_id
    and (
      v_is_parent_context
      or sh.assigned_child_tenant_id is null
      or sh.assigned_child_tenant_id = p_context_tenant_id
    )
    and sh.status = 'received'
    and (p_shipment_id is null or sh.id = p_shipment_id)
    and (p_product_id is null or gsi.product_id = p_product_id)
    and (v_avail is null or gs.availability = v_avail)
    and (not coalesce(p_exclude_zero_qty, true) or gs.quantity > 0)
    and (
      p_search is null
      or trim(p_search) = ''
      or case coalesce(nullif(lower(trim(p_search_field)), ''), 'all')
        when 'name' then (
          select coalesce(bool_and(gsi.name ilike '%' || trim(word) || '%'), true)
          from unnest(string_to_array(trim(p_search), ' ')) as word
          where trim(word) <> ''
        )
        when 'barcode' then coalesce(gsi.barcode, '') ilike '%' || trim(p_search) || '%'
        when 'product_code' then coalesce(gsi.product_code, '') ilike '%' || trim(p_search) || '%'
        else (
          select coalesce(bool_and(
            gsi.name ilike '%' || trim(word) || '%'
            or coalesce(gsi.barcode, '') ilike '%' || trim(p_search) || '%'
            or coalesce(gsi.product_code, '') ilike '%' || trim(p_search) || '%'
          ), true)
          from unnest(string_to_array(trim(p_search), ' ')) as word
          where trim(word) <> ''
        )
      end
    )
  order by
    coalesce(gsi.product_id::text, 'stock:' || gs.id::text) asc,
    case
      when coalesce(sh.assigned_child_tenant_id, v_parent_id) = p_context_tenant_id then 0
      else 1
    end asc,
    gs.id desc
  limit greatest(coalesce(p_limit, 50), 1)
  offset greatest(coalesce(p_offset, 0), 0);
end;
$$;


ALTER FUNCTION "public"."search_stock_network"("p_context_tenant_id" bigint, "p_mode" "text", "p_search" "text", "p_search_field" "text", "p_product_id" bigint, "p_status" "text", "p_shipment_id" bigint, "p_exclude_zero_qty" boolean, "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_thrift_available_stocks_for_sale"("p_tenant_id" bigint, "p_search" "text" DEFAULT NULL::"text", "p_customer_phone" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_search TEXT := NULLIF(trim(COALESCE(p_search, '')), '');
  v_phone TEXT := public.normalize_thrift_phone(p_customer_phone);
  v_limit INT := LEAST(GREATEST(COALESCE(p_limit, 50), 1), 100);
  v_result JSONB;
BEGIN
  IF NOT (
    public.membership_has_module_action(p_tenant_id, 'thrift_sales', 'create')
    OR public.membership_has_module_action(p_tenant_id, 'thrift_sales', 'view')
    OR public.membership_has_module_action(p_tenant_id, 'thrift_stock', 'view')
  ) THEN
    RAISE EXCEPTION 'Searching thrift stock for sale requires thrift_sales or thrift_stock access';
  END IF;

  IF v_search IS NULL THEN
    RETURN '[]'::jsonb;
  END IF;

  WITH matched AS (
    SELECT s.*
    FROM public.thrift_stocks s
    WHERE s.tenant_id = p_tenant_id
      AND s.deleted_at IS NULL
      AND (
        s.name ILIKE '%' || v_search || '%'
        OR COALESCE(s.barcode, '') ILIKE '%' || v_search || '%'
        OR COALESCE(s.brand_name, '') ILIKE '%' || v_search || '%'
        OR COALESCE(s.color, '') ILIKE '%' || v_search || '%'
        OR COALESCE(s.size, '') ILIKE '%' || v_search || '%'
      )
      AND (
        s.status = 'AVAILABLE'::public.thrift_stock_status
        OR (
          v_phone <> ''
          AND s.status = 'RESERVED'::public.thrift_stock_status
          AND s.held_for_phone_normalized IS NOT DISTINCT FROM v_phone
        )
      )
    ORDER BY s.created_at DESC
    LIMIT v_limit
  ),
  enriched AS (
    SELECT
      b.id,
      b.created_at,
      b.name,
      b.barcode,
      b.available_quantity,
      b.landed_cost,
      b.category,
      b.status,
      b.brand_name,
      b.type_name,
      b.color,
      b.size,
      b.condition,
      b.section,
      b.shelf_code,
      b.box_name,
      b.image_url,
      b.shipment_id,
      b.shipment_name,
      b.held_for_phone,
      b.held_for_name,
      CASE
        WHEN b.is_listed_price_manual THEN b.listed_unit_price
        ELSE public.ceil_thrift_retail_price(
          b.landed_cost * (1 + b.applied_markup_rate)
        )
      END AS default_sell_price
    FROM (
      SELECT
        m.id,
        m.created_at,
        COALESCE(NULLIF(trim(m.name), ''), 'Unnamed Item') AS name,
        COALESCE(NULLIF(trim(m.barcode), ''), 'NO-BARCODE') AS barcode,
        GREATEST(COALESCE(m.quantity, 0), 0) AS available_quantity,
        ROUND(COALESCE(public.compute_thrift_landed_unit_cost(m.id), 0.00), 2) AS landed_cost,
        COALESCE(c.name, 'Uncategorized') AS category,
        m.status::text AS status,
        m.brand_name,
        t.name AS type_name,
        m.color,
        m.size,
        m.condition::text AS condition,
        m.section::text AS section,
        sh.shelf_code,
        b.name AS box_name,
        (
          SELECT i.image_url
          FROM public.thrift_stock_images i
          WHERE i.stock_id = m.id
          ORDER BY i.is_primary DESC NULLS LAST, i.id ASC
          LIMIT 1
        ) AS image_url,
        COALESCE(m.shipment_id, 0) AS shipment_id,
        ship.name AS shipment_name,
        m.held_for_phone,
        m.held_for_name,
        COALESCE(p.is_listed_price_manual, false) AS is_listed_price_manual,
        ROUND(COALESCE(p.listed_unit_price, 0), 2) AS listed_unit_price,
        COALESCE(p.markup_rate_override, ship.default_markup_rate, 0) AS applied_markup_rate
      FROM matched m
      LEFT JOIN public.thrift_categories c ON c.id = m.category_id
      LEFT JOIN public.thrift_types t ON t.id = m.type_id
      LEFT JOIN public.thrift_shelves sh ON sh.id = m.shelf_id
      LEFT JOIN public.thrift_boxes b ON b.id = m.box_id
      LEFT JOIN public.thrift_shipments ship ON ship.id = m.shipment_id
      LEFT JOIN LATERAL (
        SELECT
          pr.listed_unit_price,
          pr.is_listed_price_manual,
          pr.markup_rate_override
        FROM public.thrift_pricings pr
        WHERE pr.stock_id = m.id
        ORDER BY pr.id DESC
        LIMIT 1
      ) p ON TRUE
    ) b
  )
  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'id', e.id,
        'name', e.name,
        'barcode', e.barcode,
        'available_quantity', e.available_quantity,
        'landed_cost', e.landed_cost,
        'default_sell_price', e.default_sell_price,
        'category', e.category,
        'status', e.status,
        'brand_name', e.brand_name,
        'type', e.type_name,
        'color', e.color,
        'size', e.size,
        'condition', e.condition,
        'section', e.section,
        'shelf_code', e.shelf_code,
        'box_name', e.box_name,
        'image_url', e.image_url,
        'shipment_id', e.shipment_id,
        'shipment_name', e.shipment_name,
        'held_for_phone', e.held_for_phone,
        'held_for_name', e.held_for_name
      )
      ORDER BY e.created_at DESC
    ),
    '[]'::jsonb
  )
  INTO v_result
  FROM enriched e;

  RETURN COALESCE(v_result, '[]'::jsonb);
END;
$$;


ALTER FUNCTION "public"."search_thrift_available_stocks_for_sale"("p_tenant_id" bigint, "p_search" "text", "p_customer_phone" "text", "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."search_thrift_available_stocks_for_sale"("p_tenant_id" bigint, "p_search" "text", "p_customer_phone" "text", "p_limit" integer) IS 'POS stock picker: default_sell_price = manual listed else ceil_thrift_retail_price(landed*(1+markup)); hold-aware.';



CREATE OR REPLACE FUNCTION "public"."seed_tenant_roles_and_grants"("p_tenant_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_role record;
begin
  insert into public.tenant_roles (tenant_id, scope, name, slug, is_system, is_admin, source_app_role)
  values
    (p_tenant_id, 'app', 'Owner', 'owner', true, true, 'owner'::public.app_role),
    (p_tenant_id, 'app', 'Manager', 'manager', true, false, 'manager'::public.app_role),
    (p_tenant_id, 'app', 'Staff', 'staff', true, false, 'staff'::public.app_role),
    (p_tenant_id, 'app', 'Viewer', 'viewer', true, false, 'viewer'::public.app_role)
  on conflict (tenant_id, scope, slug) do nothing;

  insert into public.tenant_roles (tenant_id, scope, name, slug, is_system, is_admin, source_app_role)
  values
    (p_tenant_id, 'shop', 'Customer Admin', 'customer-admin', true, false, null),
    (p_tenant_id, 'shop', 'Negotiator', 'negotiator', true, false, null),
    (p_tenant_id, 'shop', 'Customer Staff', 'customer-staff', true, false, null)
  on conflict (tenant_id, scope, slug) do nothing;

  for v_role in (
    select id, scope, slug
    from public.tenant_roles
    where tenant_id = p_tenant_id and is_admin = false
  ) loop
    insert into public.tenant_role_grants (tenant_role_id, module_key, action, allowed)
    select v_role.id, t.module_key, t.action, t.allowed
    from public.system_role_templates t
    where t.scope = v_role.scope and t.role_slug = v_role.slug
    on conflict (tenant_role_id, module_key, action) do nothing;
  end loop;
end;
$$;


ALTER FUNCTION "public"."seed_tenant_roles_and_grants"("p_tenant_id" bigint) OWNER TO "postgres";


