CREATE OR REPLACE FUNCTION "public"."settle_shipment_payee"("p_shipment_id" bigint, "p_entity_type" "text", "p_entity_id" bigint, "p_action" "text", "p_amount" numeric, "p_exchange_rate" numeric DEFAULT NULL::numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_ship public.global_shipments%ROWTYPE;
  v_rate NUMERIC(12,6);
  v_bdt_amount NUMERIC(18,4);
  v_ledger JSONB;
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'Amount must be greater than zero.';
  END IF;

  IF p_entity_type NOT IN ('vendor', 'cargo_company') THEN
    RAISE EXCEPTION 'Entity type must be vendor or cargo_company.';
  END IF;

  IF p_action NOT IN ('pay', 'record_credit', 'use_credit') THEN
    RAISE EXCEPTION 'Action must be pay, record_credit, or use_credit.';
  END IF;

  -- Lock shipment row
  SELECT * INTO v_ship
  FROM public.global_shipments
  WHERE id = p_shipment_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'shipment not found';
  END IF;

  IF v_ship.status IS DISTINCT FROM 'received' THEN
    RAISE EXCEPTION 'shipment must be received before settlement';
  END IF;

  IF NOT public.has_active_tenant_membership(v_ship.parent_tenant_id)
     AND NOT public.is_superadmin() THEN
    RAISE EXCEPTION 'not authorized';
  END IF;

  -- Payee header validation
  IF p_entity_type = 'vendor' THEN
    IF v_ship.vendor_id IS NULL OR v_ship.vendor_id <> p_entity_id THEN
      RAISE EXCEPTION 'vendor_id does not match shipment header';
    END IF;
  ELSIF p_entity_type = 'cargo_company' THEN
    IF v_ship.cargo_company_id IS NULL OR v_ship.cargo_company_id <> p_entity_id THEN
      RAISE EXCEPTION 'cargo_company_id does not match shipment header';
    END IF;
  END IF;

  -- Determine exchange rate
  IF p_exchange_rate IS NOT NULL AND p_exchange_rate > 0 THEN
    v_rate := p_exchange_rate;
  ELSE
    IF p_entity_type = 'vendor' THEN
      SELECT COALESCE(exchange_rate, 1.000000) INTO v_rate
      FROM public.global_shipment_cost_entries
      WHERE shipment_id = p_shipment_id
        AND cost_category = 'product'
      ORDER BY id ASC
      LIMIT 1;
    ELSIF p_entity_type = 'cargo_company' THEN
      SELECT COALESCE(exchange_rate, 1.000000) INTO v_rate
      FROM public.global_shipment_cost_entries
      WHERE shipment_id = p_shipment_id
        AND cost_category = 'cargo'
      ORDER BY id ASC
      LIMIT 1;
    END IF;
  END IF;

  v_rate := COALESCE(v_rate, 1.000000);
  IF v_rate <= 0 THEN
    v_rate := 1.000000;
  END IF;

  v_bdt_amount := ROUND(p_amount * v_rate, 4);

  IF p_action = 'pay' THEN
    -- Action: pay — debit tenant available (overdraft allowed). Payee available untouched.
    v_ledger := public.record_ledger_transaction(
      p_tenant_id => v_ship.parent_tenant_id,
      p_entity_type => 'tenant',
      p_entity_id => v_ship.parent_tenant_id,
      p_type => 'debit',
      p_amount => v_bdt_amount,
      p_currency_code => 'BDT',
      p_exchange_rate => 1.000000,
      p_source_type => 'shipment',
      p_source_id => p_shipment_id::text,
      p_metadata => jsonb_build_object(
        'action', 'pay',
        'payee_type', p_entity_type,
        'payee_id', p_entity_id,
        'amount_input', p_amount,
        'exchange_rate', v_rate
      ),
      p_target_bucket => 'available',
      p_allow_overdraft => true
    );
  ELSIF p_action = 'record_credit' THEN
    -- Action: record_credit — credit payee available. Tenant unchanged.
    v_ledger := public.record_ledger_transaction(
      p_tenant_id => v_ship.parent_tenant_id,
      p_entity_type => p_entity_type,
      p_entity_id => p_entity_id,
      p_type => 'credit',
      p_amount => v_bdt_amount,
      p_currency_code => 'BDT',
      p_exchange_rate => 1.000000,
      p_source_type => 'shipment',
      p_source_id => p_shipment_id::text,
      p_metadata => jsonb_build_object(
        'action', 'record_credit',
        'payee_type', p_entity_type,
        'payee_id', p_entity_id,
        'amount_input', p_amount,
        'exchange_rate', v_rate
      ),
      p_target_bucket => 'available',
      p_allow_overdraft => false
    );
  ELSIF p_action = 'use_credit' THEN
    -- Action: use_credit — debit payee available (strict check). Tenant unchanged.
    v_ledger := public.record_ledger_transaction(
      p_tenant_id => v_ship.parent_tenant_id,
      p_entity_type => p_entity_type,
      p_entity_id => p_entity_id,
      p_type => 'debit',
      p_amount => v_bdt_amount,
      p_currency_code => 'BDT',
      p_exchange_rate => 1.000000,
      p_source_type => 'shipment',
      p_source_id => p_shipment_id::text,
      p_metadata => jsonb_build_object(
        'action', 'use_credit',
        'payee_type', p_entity_type,
        'payee_id', p_entity_id,
        'amount_input', p_amount,
        'exchange_rate', v_rate
      ),
      p_target_bucket => 'available',
      p_allow_overdraft => false
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'action', p_action,
    'amount_bdt', v_bdt_amount,
    'ledger', v_ledger
  );
END;
$$;


ALTER FUNCTION "public"."settle_shipment_payee"("p_shipment_id" bigint, "p_entity_type" "text", "p_entity_id" bigint, "p_action" "text", "p_amount" numeric, "p_exchange_rate" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ship_dropship_order_and_issue_merchant_bill"("p_tenant_id" bigint, "p_order_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_order public.shop_orders;
  v_issue jsonb;
begin
  if not public.is_tenant_staff(p_tenant_id) then
    return jsonb_build_object('success', false, 'error', 'access denied');
  end if;

  select * into v_order
  from public.shop_orders
  where id = p_order_id
  for update;

  if not found then
    return jsonb_build_object('success', false, 'error', 'order not found');
  end if;

  if v_order.tenant_id is distinct from p_tenant_id
     and v_order.parent_tenant_id is distinct from p_tenant_id then
    return jsonb_build_object('success', false, 'error', 'tenant mismatch');
  end if;

  if v_order.shop_type_snapshot <> 'dropship' then
    return jsonb_build_object('success', false, 'error', 'order is not a dropship order');
  end if;

  if v_order.status <> 'ready_for_pickup'::public.shop_order_status then
    return jsonb_build_object(
      'success', false,
      'error', format('ship requires ready_for_pickup (current: %s)', v_order.status)
    );
  end if;

  if v_order.billing_profile_id is null then
    return jsonb_build_object('success', false, 'error', 'billing profile is required before ship');
  end if;

  if v_order.courier_service_id is null then
    return jsonb_build_object('success', false, 'error', 'courier is required before ship');
  end if;

  if nullif(trim(coalesce(v_order.sender_name, '')), '') is null
     or nullif(trim(coalesce(v_order.pickup_phone, '')), '') is null
     or nullif(trim(coalesce(v_order.pickup_address, '')), '') is null then
    return jsonb_build_object('success', false, 'error', 'pickup location name, phone, and address are required before ship');
  end if;

  if exists (
    select 1
    from public.shop_order_items soi
    where soi.order_id = p_order_id
      and soi.quantity > 0
      and coalesce(soi.is_fulfillment_unavailable, false) = false
      and coalesce(soi.confirmed_quantity, 0) <= 0
      and not exists (
        select 1
        from public.shop_order_item_stock_picks sp
        where sp.order_item_id = soi.id
          and sp.quantity > 0
      )
  ) then
    return jsonb_build_object('success', false, 'error', 'every line must be picked or marked unavailable before ship');
  end if;

  v_issue := public.issue_dropship_tenant_b2b_invoice(p_tenant_id, p_order_id);
  if coalesce(v_issue->>'success', 'false') <> 'true' then
    return v_issue;
  end if;

  update public.shop_orders
  set
    status = 'shipped'::public.shop_order_status,
    updated_at = now()
  where id = p_order_id;

  return jsonb_build_object(
    'success', true,
    'order_id', p_order_id,
    'new_status', 'shipped',
    'invoice', v_issue->'invoice',
    'created', coalesce(v_issue->>'created', 'false')::boolean,
    'already_issued', coalesce(v_issue->>'already_issued', 'false')::boolean
  );
exception
  when others then
    return jsonb_build_object('success', false, 'error', sqlerrm);
end;
$$;


ALTER FUNCTION "public"."ship_dropship_order_and_issue_merchant_bill"("p_tenant_id" bigint, "p_order_id" bigint) OWNER TO "postgres";


