CREATE OR REPLACE FUNCTION "public"."sync_dropship_tenant_b2b_invoice_from_order"("p_order_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_order public.shop_orders;
  v_invoice public.global_invoices;
  v_pick record;
  v_item_sell_price numeric(12,2);
  v_item_line_total numeric(12,2);
  v_charges record;
begin
  select * into v_order from public.shop_orders where id = p_order_id;
  if v_order.id is null then
    return jsonb_build_object('success', false, 'error', 'Order not found');
  end if;

  if v_order.shop_type_snapshot <> 'dropship' then
    return jsonb_build_object('success', false, 'error', 'Order is not a dropship order');
  end if;

  if v_order.global_invoice_id is null then
    return jsonb_build_object('success', false, 'error', 'No tenant B2B invoice linked to order');
  end if;

  select * into v_invoice
  from public.global_invoices
  where id = v_order.global_invoice_id
  for update;

  if v_invoice.id is null then
    return jsonb_build_object('success', false, 'error', 'Linked invoice not found');
  end if;

  if v_invoice.invoice_type <> 'dropship'::public.global_invoice_type then
    return jsonb_build_object('success', false, 'error', 'Linked invoice is not a dropship B2B invoice');
  end if;

  if v_invoice.invoice_status = 'voided'::public.global_invoice_status then
    return jsonb_build_object('success', false, 'error', 'Cannot sync a voided invoice');
  end if;

  if v_invoice.payment_status in ('paid', 'partially_paid') then
    raise exception
      'Cannot sync dropship B2B invoice after payment (invoice %). Use scripts/sql/backfill_dropship_invoice_charge_payer_mismatch.sql',
      v_invoice.id;
  end if;

  select * into v_charges
  from public.get_dropship_merchant_billable_charges(p_order_id);

  for v_pick in (
    select
      sp.quantity as pick_quantity,
      sp.held_stock_id,
      soi.product_id,
      soi.unit_sell_price_amount,
      soi.final_price_amount,
      gs.shipment_item_id as stock_shipment_item_id
    from public.shop_order_item_stock_picks sp
    join public.shop_order_items soi on soi.id = sp.order_item_id
    left join public.global_stocks gs on gs.id = sp.held_stock_id
    where sp.order_id = v_order.id
      and sp.quantity > 0
      and coalesce(soi.is_fulfillment_unavailable, false) = false
  ) loop
    v_item_sell_price := coalesce(v_pick.unit_sell_price_amount, v_pick.final_price_amount, 0);
    v_item_line_total := v_pick.pick_quantity * v_item_sell_price;

    update public.global_invoice_items gii
    set
      quantity = v_pick.pick_quantity,
      sell_price_amount = v_item_sell_price,
      line_total_amount = v_item_line_total,
      unit_cost_price = coalesce(public.calculate_landed_unit_cost(v_pick.stock_shipment_item_id), gii.unit_cost_price),
      updated_at = now()
    where gii.invoice_id = v_invoice.id
      and gii.global_stock_id = v_pick.held_stock_id;
  end loop;

  update public.global_invoices
  set
    shipping_charge = coalesce(v_charges.delivery, 0),
    print_charge = coalesce(v_charges.print, 0),
    wrapping_charge = coalesce(v_charges.packing, 0),
    cod_charge_amount = coalesce(v_charges.cod, 0),
    discount_amount = coalesce(v_order.discount_amount, 0),
    collection_source = 'billing_profile'::public.collection_source_type,
    updated_at = now()
  where id = v_invoice.id;

  perform public.recompute_global_invoice_totals(v_invoice.id);
  perform public.recompute_global_invoice_payment_status(v_invoice.id);

  select * into v_invoice from public.global_invoices where id = v_invoice.id;

  return jsonb_build_object(
    'success', true,
    'invoice_id', v_invoice.id,
    'invoice_status', v_invoice.invoice_status,
    'payment_status', v_invoice.payment_status,
    'total_amount', v_invoice.total_amount,
    'due_amount', v_invoice.due_amount
  );
end;
$$;


ALTER FUNCTION "public"."sync_dropship_tenant_b2b_invoice_from_order"("p_order_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_global_shipment_header_aliases"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
  if tg_op = 'INSERT' then
    if new.total_weight_kg is null and new.received_weight is not null then
      new.total_weight_kg := new.received_weight;
    elsif new.received_weight is null and new.total_weight_kg is not null then
      new.received_weight := new.total_weight_kg;
    elsif new.total_weight_kg is distinct from new.received_weight then
      -- Prefer plan name when both provided
      if new.total_weight_kg is not null then
        new.received_weight := new.total_weight_kg;
      else
        new.total_weight_kg := new.received_weight;
      end if;
    end if;

    if new.inventory_added is null then
      new.inventory_added := coalesce(new.stock_ready, false);
    end if;
    new.stock_ready := new.inventory_added;
    return new;
  end if;

  -- UPDATE: whichever side changed wins
  if new.total_weight_kg is distinct from old.total_weight_kg then
    new.received_weight := new.total_weight_kg;
  elsif new.received_weight is distinct from old.received_weight then
    new.total_weight_kg := new.received_weight;
  end if;

  if new.inventory_added is distinct from old.inventory_added then
    new.stock_ready := new.inventory_added;
  elsif new.stock_ready is distinct from old.stock_ready then
    new.inventory_added := new.stock_ready;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."sync_global_shipment_header_aliases"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_lookup_tenant_id"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
declare
  v_tenant_id bigint;
  v_parent_tenant_id bigint;
begin
  if new.vendor_id is not null then
    select tenant_id, parent_tenant_id
    into v_tenant_id, v_parent_tenant_id
    from public.vendors
    where id = new.vendor_id;

    if v_tenant_id is not null then
      new.tenant_id := v_tenant_id;
    end if;

    if v_parent_tenant_id is not null then
      new.parent_tenant_id := v_parent_tenant_id;
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."sync_lookup_tenant_id"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_product_tenant_from_vendor"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
declare
  v_tenant_id bigint;
  v_parent_tenant_id bigint;
begin
  if new.vendor_id is not null then
    select v.tenant_id, v.parent_tenant_id
    into v_tenant_id, v_parent_tenant_id
    from public.vendors v
    where v.id = new.vendor_id;

    if v_parent_tenant_id is not null then
      new.parent_tenant_id := public.resolve_parent_tenant_id(v_parent_tenant_id);
    elsif v_tenant_id is not null then
      new.parent_tenant_id := public.resolve_parent_tenant_id(v_tenant_id);
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."sync_product_tenant_from_vendor"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_sales_invoice_charges_from_header"("p_invoice_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_inv public.sales_invoices;
  v_total numeric(12,2) := 0;
begin
  select * into v_inv from public.sales_invoices where id = p_invoice_id;
  if not found then
    return;
  end if;

  delete from public.sales_invoice_charges where invoice_id = p_invoice_id;

  if coalesce(v_inv.shipping_charge, 0) > 0 then
    insert into public.sales_invoice_charges (invoice_id, parent_tenant_id, charge_type, amount)
    values (p_invoice_id, v_inv.parent_tenant_id, 'delivery', v_inv.shipping_charge);
    v_total := v_total + v_inv.shipping_charge;
  end if;

  if coalesce(v_inv.print_charge, 0) > 0 then
    insert into public.sales_invoice_charges (invoice_id, parent_tenant_id, charge_type, amount)
    values (p_invoice_id, v_inv.parent_tenant_id, 'print', v_inv.print_charge);
    v_total := v_total + v_inv.print_charge;
  end if;

  if coalesce(v_inv.wrapping_charge, 0) > 0 then
    insert into public.sales_invoice_charges (invoice_id, parent_tenant_id, charge_type, amount)
    values (p_invoice_id, v_inv.parent_tenant_id, 'packing', v_inv.wrapping_charge);
    v_total := v_total + v_inv.wrapping_charge;
  end if;

  if coalesce(v_inv.cod_charge_amount, 0) > 0 then
    insert into public.sales_invoice_charges (invoice_id, parent_tenant_id, charge_type, amount)
    values (p_invoice_id, v_inv.parent_tenant_id, 'cod', v_inv.cod_charge_amount);
    v_total := v_total + v_inv.cod_charge_amount;
  end if;

  update public.sales_invoices
  set charges_amount = v_total,
      updated_at = now()
  where id = p_invoice_id;
end;
$$;


ALTER FUNCTION "public"."sync_sales_invoice_charges_from_header"("p_invoice_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_shop_cart_item_reservation"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
  if tg_op = 'DELETE' then
    delete from public.shop_stock_reservations where cart_item_id = old.id;
    return old;
  end if;

  if new.quantity > 0 and new.global_stock_id is not null then
    insert into public.shop_stock_reservations (cart_item_id, global_stock_id, global_stock_allocation_id, quantity)
    values (new.id, new.global_stock_id, null, new.quantity)
    on conflict (cart_item_id) do update set
      global_stock_id = excluded.global_stock_id,
      global_stock_allocation_id = null,
      quantity = excluded.quantity;
  else
    delete from public.shop_stock_reservations where cart_item_id = new.id;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."sync_shop_cart_item_reservation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_shop_order_collection_source_from_invoice"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_src public.collection_source_type;
begin
  if new.global_invoice_id is null then
    return new;
  end if;

  if tg_op = 'UPDATE'
     and old.global_invoice_id is not distinct from new.global_invoice_id
     and new.collection_source is not null then
    return new;
  end if;

  select collection_source into v_src
  from public.global_invoices
  where id = new.global_invoice_id;

  if v_src is not null then
    new.collection_source := v_src;
    if new.payout_settlement_status is null
       and new.shop_type_snapshot = 'dropship' then
      new.payout_settlement_status := 'unpaid';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."sync_shop_order_collection_source_from_invoice"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_vendor_reference_fields"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
declare
  v_id bigint;
  v_code text;
begin
  if new.vendor_id is not null then
    select id, code
    into v_id, v_code
    from public.vendors
    where id = new.vendor_id
    limit 1;

    if v_id is null then
      raise exception 'invalid vendor_id: %', new.vendor_id;
    end if;

    new.vendor_id := v_id;
    new.vendor_code := v_code;
    return new;
  end if;

  if new.vendor_code is not null and length(trim(new.vendor_code)) > 0 then
    select id, code
    into v_id, v_code
    from public.vendors
    where upper(trim(code)) = upper(trim(new.vendor_code))
    order by id asc
    limit 1;

    if v_id is not null then
      new.vendor_id := v_id;
      new.vendor_code := v_code;
    else
      new.vendor_id := null;
      new.vendor_code := upper(trim(new.vendor_code));
    end if;

    return new;
  end if;

  new.vendor_id := null;
  new.vendor_code := null;
  return new;
end;
$$;


ALTER FUNCTION "public"."sync_vendor_reference_fields"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."thrift_barcode_sequence_sort_key"("p_barcode_id" "text") RETURNS TABLE("sort_prefix" "text", "sort_year" "text", "sort_seq" integer)
    LANGUAGE "sql" IMMUTABLE
    AS $_$
  select
    case
      when p_barcode_id ~ '^\d+-[A-Z]{2}-\d{2}-\d+$'
        then split_part(p_barcode_id, '-', 2)
      when p_barcode_id ~ '^[A-Z]{2}-\d{2}-\d+$'
        then split_part(p_barcode_id, '-', 1)
      else coalesce(p_barcode_id, '')
    end as sort_prefix,
    case
      when p_barcode_id ~ '^\d+-[A-Z]{2}-\d{2}-\d+$'
        then split_part(p_barcode_id, '-', 3)
      when p_barcode_id ~ '^[A-Z]{2}-\d{2}-\d+$'
        then split_part(p_barcode_id, '-', 2)
      else ''
    end as sort_year,
    case
      when p_barcode_id ~ '^\d+-[A-Z]{2}-\d{2}-\d+$'
        then split_part(p_barcode_id, '-', 4)::integer
      when p_barcode_id ~ '^[A-Z]{2}-\d{2}-\d+$'
        then split_part(p_barcode_id, '-', 3)::integer
      else 0
    end as sort_seq;
$_$;


ALTER FUNCTION "public"."thrift_barcode_sequence_sort_key"("p_barcode_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."thrift_courier_providers_guard_system"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.is_system THEN
      RAISE EXCEPTION 'System courier providers cannot be deleted';
    END IF;
    RETURN OLD;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    IF OLD.is_system THEN
      RAISE EXCEPTION 'System courier providers cannot be updated';
    END IF;
    IF NEW.is_system IS DISTINCT FROM FALSE OR NEW.tenant_id IS NULL THEN
      RAISE EXCEPTION 'Tenant courier providers must keep is_system=false and a tenant_id';
    END IF;
    IF NEW.tenant_id IS DISTINCT FROM OLD.tenant_id THEN
      RAISE EXCEPTION 'Cannot move courier provider across tenants';
    END IF;
    RETURN NEW;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."thrift_courier_providers_guard_system"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."thrift_stocks_enforce_hold_metadata"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF NEW.status = 'RESERVED'::public.thrift_stock_status THEN
    IF COALESCE(NEW.held_for_phone_normalized, '') = '' THEN
      RAISE EXCEPTION 'RESERVED stock requires held_for_phone_normalized';
    END IF;
    NEW.held_for_phone_normalized := public.normalize_thrift_phone(
      COALESCE(NEW.held_for_phone_normalized, NEW.held_for_phone)
    );
    IF COALESCE(NEW.held_for_phone_normalized, '') = '' THEN
      RAISE EXCEPTION 'RESERVED stock requires a non-empty customer phone';
    END IF;
    IF NEW.held_at IS NULL THEN
      NEW.held_at := NOW();
    END IF;
  ELSIF TG_OP = 'UPDATE'
    AND OLD.status = 'RESERVED'::public.thrift_stock_status
  THEN
    NEW.held_for_name := NULL;
    NEW.held_for_phone := NULL;
    NEW.held_for_phone_normalized := NULL;
    NEW.hold_note := NULL;
    NEW.held_by := NULL;
    NEW.held_at := NULL;
    NEW.hold_expires_at := NULL;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."thrift_stocks_enforce_hold_metadata"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."transfer_dropship_reseller_profit"("p_tenant_id" bigint, "p_order_id" bigint, "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_order public.shop_orders;
  v_settlement public.dropship_order_settlements;
  v_save jsonb;
  v_billing_profile_id bigint;
  v_amount numeric(15,2);
  v_parent_tenant_id bigint;
begin
  if not public.is_tenant_staff(p_tenant_id) then
    raise exception 'access denied';
  end if;

  select * into v_order
  from public.shop_orders
  where id = p_order_id
  for update;

  if not found then
    raise exception 'order not found';
  end if;

  if v_order.tenant_id is distinct from p_tenant_id
     and v_order.parent_tenant_id is distinct from p_tenant_id then
    raise exception 'order not found';
  end if;

  select * into v_settlement
  from public.dropship_order_settlements
  where shop_order_id = p_order_id;

  if not found then
    raise exception 'settlement draft is required before crediting reseller profit';
  end if;

  if v_order.status = 'reseller_paid'::public.shop_order_status
     or v_settlement.merchant_payout_at is not null
     or v_settlement.status = 'confirmed' then
    return jsonb_build_object(
      'success', true,
      'already_recorded', true,
      'message', 'Reseller profit already credited to merchant wallet',
      'order_id', p_order_id,
      'status', coalesce(v_order.status::text, 'reseller_paid')
    );
  end if;

  if v_order.courier_remittance_ref is null
     and v_settlement.remittance_at is null
     and v_order.status <> 'payment_received'::public.shop_order_status then
    raise exception 'Courier remittance must be recorded before crediting reseller profit (current: %)', v_order.status;
  end if;

  if p_payload is not null and p_payload <> '{}'::jsonb then
    v_save := public.save_dropship_settlement_draft(p_tenant_id, p_order_id, p_payload);
    if coalesce(v_save->>'success', 'false') <> 'true' then
      return v_save;
    end if;

    select * into v_settlement
    from public.dropship_order_settlements
    where shop_order_id = p_order_id;
  end if;

  v_billing_profile_id := coalesce(v_order.billing_profile_id, v_settlement.billing_profile_id);
  if v_billing_profile_id is null then
    raise exception 'billing profile is required for reseller profit credit';
  end if;

  v_amount := coalesce(v_settlement.reseller_profit, 0);
  if v_amount <= 0 then
    return jsonb_build_object(
      'success', true,
      'skipped', true,
      'message', 'No reseller profit to credit',
      'order_id', p_order_id,
      'amount', 0
    );
  end if;

  v_parent_tenant_id := public.resolve_parent_tenant_id(v_order.tenant_id);

  if exists (
    select 1
    from public.universal_wallet_ledger u
    where u.parent_tenant_id = v_parent_tenant_id
      and u.source_type = 'shop_order'
      and u.source_id = p_order_id::text
      and u.entity_type in ('middleman', 'customer')
      and u.entity_id = v_billing_profile_id
      and u.type = 'credit'
      and coalesce(u.metadata->>'transaction_type', '') = 'dropship_profit'
  ) then
    return jsonb_build_object(
      'success', true,
      'already_recorded', true,
      'message', 'Reseller profit already credited to merchant wallet',
      'order_id', p_order_id,
      'amount', v_amount
    );
  end if;

  perform public.record_ledger_transaction(
    p_parent_tenant_id => v_parent_tenant_id,
    p_operating_tenant_id => v_order.tenant_id,
    p_entity_type => 'customer',
    p_entity_id => v_billing_profile_id,
    p_type => 'credit',
    p_amount => v_amount,
    p_currency_code => 'BDT',
    p_exchange_rate => 1.000000,
    p_source_type => 'shop_order',
    p_source_id => p_order_id::text,
    p_metadata => jsonb_build_object(
      'section', 'payout_earned',
      'transaction_type', 'dropship_profit',
      'label', 'Dropship profit earned',
      'order_no', v_order.order_no,
      'order_id', p_order_id,
      'shop_order_id', p_order_id::text,
      'invoice_id', v_order.global_invoice_id,
      'notes', coalesce(
        nullif(trim(p_payload->>'reference_notes'), ''),
        'Dropship reseller profit for order #' || v_order.order_no
      )
    )
  );

  update public.dropship_order_settlements
  set
    status = 'confirmed',
    confirmed_at = now(),
    confirmed_by = auth.uid(),
    merchant_payout_at = now(),
    updated_at = now()
  where id = v_settlement.id;

  update public.shop_orders
  set
    status = 'reseller_paid'::public.shop_order_status,
    payout_settlement_status = 'paid',
    updated_at = now()
  where id = p_order_id;

  return jsonb_build_object(
    'success', true,
    'message', 'Reseller profit credited to merchant wallet',
    'order_id', p_order_id,
    'amount', v_amount,
    'status', 'reseller_paid',
    'billing_profile_id', v_billing_profile_id
  );
end;
$$;


ALTER FUNCTION "public"."transfer_dropship_reseller_profit"("p_tenant_id" bigint, "p_order_id" bigint, "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."transfer_network_owner"("p_parent_tenant_id" bigint, "p_new_email" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_email text := lower(trim(p_new_email));
  v_old_owner public.memberships;
  v_new_membership public.memberships;
  v_owner_role_id bigint;
  v_manager_role_id bigint;
begin
  if not public.is_superadmin() and not public.is_network_owner(p_parent_tenant_id) then
    raise exception 'Only the current network owner or superadmin can transfer ownership';
  end if;

  if v_email = '' then
    raise exception 'p_new_email is required';
  end if;

  select t.parent_id into v_old_owner.tenant_id
  from public.tenants t
  where t.id = p_parent_tenant_id;

  if exists (
    select 1 from public.tenants t
    where t.id = p_parent_tenant_id and t.parent_id is not null
  ) then
    raise exception 'Ownership transfer must target the parent or standalone tenant';
  end if;

  select tr.id into v_owner_role_id
  from public.tenant_roles tr
  where tr.tenant_id = p_parent_tenant_id and tr.scope = 'app' and tr.slug = 'owner'
  limit 1;

  select tr.id into v_manager_role_id
  from public.tenant_roles tr
  where tr.tenant_id = p_parent_tenant_id and tr.scope = 'app' and tr.slug = 'manager'
  limit 1;

  select m.* into v_old_owner
  from public.memberships m
  where m.tenant_id = p_parent_tenant_id
    and m.role = 'owner'::public.app_role
    and m.is_active = true
  order by m.id asc
  limit 1;

  if v_old_owner.id is null then
    raise exception 'No active owner found for tenant %', p_parent_tenant_id;
  end if;

  if lower(trim(v_old_owner.email)) = v_email then
    return jsonb_build_object('success', true, 'owner_membership_id', v_old_owner.id);
  end if;

  update public.memberships
  set
    role = 'manager'::public.app_role,
    tenant_role_id = v_manager_role_id,
    updated_at = now()
  where id = v_old_owner.id;

  select m.* into v_new_membership
  from public.memberships m
  where m.tenant_id = p_parent_tenant_id
    and lower(trim(m.email)) = v_email
  limit 1;

  if v_new_membership.id is null then
    insert into public.memberships (email, tenant_id, role, is_active, tenant_role_id)
    values (v_email, p_parent_tenant_id, 'owner'::public.app_role, true, v_owner_role_id)
    returning * into v_new_membership;
  else
    update public.memberships
    set
      role = 'owner'::public.app_role,
      tenant_role_id = v_owner_role_id,
      is_active = true,
      updated_at = now()
    where id = v_new_membership.id
    returning * into v_new_membership;
  end if;

  return jsonb_build_object(
    'success', true,
    'previous_owner_membership_id', v_old_owner.id,
    'owner_membership_id', v_new_membership.id
  );
end;
$$;


ALTER FUNCTION "public"."transfer_network_owner"("p_parent_tenant_id" bigint, "p_new_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."transfer_wallet_balance"("p_tenant_id" bigint, "p_entity_type" "text", "p_entity_id" bigint, "p_from_bucket" "text", "p_to_bucket" "text", "p_amount" numeric, "p_currency_code" "text" DEFAULT 'BDT'::"text", "p_notes" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_parent_tenant_id bigint;
  v_operating_tenant_id bigint;
  v_account_id bigint;
  v_avail numeric(18,4);
  v_pend numeric(18,4);
  v_lock numeric(18,4);
  v_result jsonb;
  v_entity_id bigint;
BEGIN
  v_parent_tenant_id := public.resolve_parent_tenant_id(p_tenant_id);
  v_operating_tenant_id := p_tenant_id;
  IF p_amount <= 0 THEN
    RAISE EXCEPTION 'Transfer amount must be greater than zero.';
  END IF;

  IF p_from_bucket = p_to_bucket THEN
    RAISE EXCEPTION 'Source and target buckets cannot be identical.';
  END IF;

  IF p_from_bucket NOT IN ('available', 'pending', 'locked')
     OR p_to_bucket NOT IN ('available', 'pending', 'locked') THEN
    RAISE EXCEPTION 'Invalid bucket specifiers. Must be available, pending, or locked.';
  END IF;

  v_entity_id := p_entity_id;
  IF p_entity_type = 'tenant' THEN
    v_entity_id := v_parent_tenant_id;
  END IF;

  INSERT INTO public.wallet_accounts (
    tenant_id, parent_tenant_id, entity_type, entity_id, currency_code,
    available_balance, pending_balance, locked_balance
  )
  VALUES (
    v_parent_tenant_id, v_parent_tenant_id, p_entity_type, v_entity_id,
    coalesce(p_currency_code, 'BDT'), 0.0000, 0.0000, 0.0000
  )
  ON CONFLICT (parent_tenant_id, entity_type, entity_id, currency_code)
  DO UPDATE SET updated_at = now()
  RETURNING id, available_balance, pending_balance, locked_balance
  INTO v_account_id, v_avail, v_pend, v_lock;

  SELECT available_balance, pending_balance, locked_balance
  INTO v_avail, v_pend, v_lock
  FROM public.wallet_accounts
  WHERE id = v_account_id
  FOR UPDATE;

  IF p_from_bucket = 'pending' THEN
    IF v_pend < p_amount THEN
      RAISE EXCEPTION 'Insufficient pending balance (Pending: %, Requested: %).', v_pend, p_amount;
    END IF;
    v_pend := v_pend - p_amount;
  ELSIF p_from_bucket = 'available' THEN
    IF v_avail < p_amount THEN
      RAISE EXCEPTION 'Insufficient available balance (Available: %, Requested: %).', v_avail, p_amount;
    END IF;
    v_avail := v_avail - p_amount;
  ELSIF p_from_bucket = 'locked' THEN
    IF v_lock < p_amount THEN
      RAISE EXCEPTION 'Insufficient locked balance (Locked: %, Requested: %).', v_lock, p_amount;
    END IF;
    v_lock := v_lock - p_amount;
  END IF;

  IF p_to_bucket = 'pending' THEN
    v_pend := v_pend + p_amount;
  ELSIF p_to_bucket = 'available' THEN
    v_avail := v_avail + p_amount;
  ELSIF p_to_bucket = 'locked' THEN
    v_lock := v_lock + p_amount;
  END IF;

  UPDATE public.wallet_accounts
  SET
    available_balance = v_avail,
    pending_balance = v_pend,
    locked_balance = v_lock,
    tenant_id = v_parent_tenant_id,
    updated_at = now()
  WHERE id = v_account_id;

  INSERT INTO public.universal_wallet_ledger (
    tenant_id, parent_tenant_id, operating_tenant_id,
    entity_type, entity_id, type, amount, currency_code,
    exchange_rate, base_amount, balance_after, source_type, source_id, metadata
  )
  VALUES (
    v_parent_tenant_id, v_parent_tenant_id, v_operating_tenant_id,
    p_entity_type, v_entity_id, 'credit', p_amount, coalesce(p_currency_code, 'BDT'),
    1.000000, p_amount, v_avail, 'bucket_transfer', NULL,
    coalesce(p_metadata, '{}'::jsonb) || jsonb_build_object(
      'from_bucket', p_from_bucket,
      'to_bucket', p_to_bucket,
      'notes', p_notes
    )
  );

  SELECT jsonb_build_object(
    'account_id', v_account_id,
    'parent_tenant_id', v_parent_tenant_id,
    'tenant_id', v_parent_tenant_id,
    'entity_type', p_entity_type,
    'entity_id', v_entity_id,
    'currency_code', coalesce(p_currency_code, 'BDT'),
    'available_balance', v_avail,
    'pending_balance', v_pend,
    'locked_balance', v_lock
  ) INTO v_result;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."transfer_wallet_balance"("p_tenant_id" bigint, "p_entity_type" "text", "p_entity_id" bigint, "p_from_bucket" "text", "p_to_bucket" "text", "p_amount" numeric, "p_currency_code" "text", "p_notes" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trg_auto_create_billing_profile_for_customer_group"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_books_id bigint;
begin
  v_books_id := coalesce(new.parent_tenant_id, public.resolve_parent_tenant_id(new.tenant_id));

  if not exists (
    select 1
    from public.billing_profiles
    where customer_group_id = new.id
  ) then
    insert into public.billing_profiles (
      tenant_id,
      parent_tenant_id,
      customer_group_id,
      name,
      email,
      phone,
      address,
      created_at,
      updated_at
    )
    values (
      v_books_id,
      v_books_id,
      new.id,
      new.name,
      null,
      null,
      null,
      now(),
      now()
    );
  end if;

  return new;
end;
$$;


