CREATE OR REPLACE FUNCTION "public"."trg_fn_cgm_permission_guardrails"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_role_scope text;
  v_role_books bigint;
  v_cg_books bigint;
begin
  if new.tenant_role_id is not null then
    select tr.scope, public.resolve_parent_tenant_id(tr.tenant_id)
    into v_role_scope, v_role_books
    from public.tenant_roles tr
    where tr.id = new.tenant_role_id;

    select coalesce(cg.parent_tenant_id, public.resolve_parent_tenant_id(cg.tenant_id))
    into v_cg_books
    from public.customer_groups cg
    where cg.id = new.customer_group_id;

    if v_role_books is distinct from v_cg_books then
      raise exception 'Cross-tenant role assignment is not allowed';
    end if;

    if v_role_scope is distinct from 'shop' then
      raise exception 'Scope mismatch: customer group member cannot be assigned a % scoped role', v_role_scope;
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."trg_fn_cgm_permission_guardrails"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trg_fn_memberships_owner_placement"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_parent_id bigint;
begin
  if new.role = 'admin'::public.app_role then
    raise exception 'app_role admin is retired; use owner, manager, staff, or viewer';
  end if;

  if new.role = 'owner'::public.app_role then
    select t.parent_id into v_parent_id
    from public.tenants t
    where t.id = new.tenant_id;

    if v_parent_id is not null then
      raise exception 'Owner membership must be on the parent or standalone tenant, not a child desk';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."trg_fn_memberships_owner_placement"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trg_fn_memberships_permission_guardrails"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
declare
  v_role_scope text;
  v_role_tenant bigint;
begin
  if new.tenant_role_id is not null then
    select scope, tenant_id into v_role_scope, v_role_tenant
    from public.tenant_roles
    where id = new.tenant_role_id;

    if v_role_tenant <> new.tenant_id then
      raise exception 'Cross-tenant role assignment is not allowed';
    end if;

    if v_role_scope <> 'app' then
      raise exception 'Scope mismatch: app membership cannot be assigned a % scoped role', v_role_scope;
    end if;
  end if;

  if tg_op = 'UPDATE' and old.is_active = true then
    declare
      v_was_owner boolean;
      v_is_owner boolean;
      v_active_owners int;
    begin
      v_was_owner := old.role = 'owner'::public.app_role;
      v_is_owner := new.is_active = true and new.role = 'owner'::public.app_role;

      if v_was_owner and not v_is_owner then
        select count(*) into v_active_owners
        from public.memberships m
        where m.tenant_id = old.tenant_id
          and m.is_active = true
          and m.id <> old.id
          and m.role = 'owner'::public.app_role;

        if v_active_owners = 0 then
          raise exception 'Cannot downgrade or deactivate the last active owner for this tenant';
        end if;
      end if;
    end;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."trg_fn_memberships_permission_guardrails"() OWNER TO "postgres";


