  end if;
  if tg_op = 'INSERT'
     and new.landed_cost_bdt is not null
     and coalesce(current_setting('app.allow_landed_cost_stamp', true), '') is distinct from '1'
  then
    raise exception 'landed_cost_bdt is stamp-only; use finalize/revise RPCs';
  end if;
