CREATE OR REPLACE FUNCTION "public"."trg_item_assignees_notify_assigned"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_item public.items;
  v_assignee_user_id uuid;
  v_tenant_id bigint;
BEGIN
  SELECT i.*
  INTO v_item
  FROM public.items i
  WHERE i.id = NEW.item_id;

  IF NOT FOUND OR v_item.type IS DISTINCT FROM 'task' THEN
    RETURN NEW;
  END IF;

  v_tenant_id := v_item.tenant_id;
  IF v_tenant_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT u.id
  INTO v_assignee_user_id
  FROM auth.users u
  WHERE lower(trim(u.email)) = lower(trim(NEW.user_email))
  LIMIT 1;

  IF v_assignee_user_id IS NULL THEN
    RETURN NEW;
  END IF;

  PERFORM public.enqueue_notification(
    p_tenant_id := v_tenant_id,
    p_operating_tenant_id := v_tenant_id,
    p_audience := 'assignee_only',
    p_event_type := 'task.assigned',
    p_title := format('Task: %s', v_item.title),
    p_body := 'Open this task',
    p_link_path := '/app/tasks',
    p_entity_type := 'item',
    p_entity_id := v_item.id::text,
    p_recipient_user_ids := ARRAY[v_assignee_user_id],
    p_module_key := 'tasks',
    p_action := 'view'
  );

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."trg_item_assignees_notify_assigned"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trg_notification_recipients_dispatch"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'net'
    AS $$
DECLARE
  v_functions_url text;
  v_service_role_key text;
  v_url text;
BEGIN
  SELECT s.functions_url, s.service_role_key
  INTO v_functions_url, v_service_role_key
  FROM public.notification_dispatch_settings s
  WHERE s.id = 1;

  v_functions_url := coalesce(nullif(trim(v_functions_url), ''), 'http://kong:8000');
  v_service_role_key := nullif(trim(v_service_role_key), '');

  IF v_service_role_key IS NULL THEN
    RETURN NEW;
  END IF;

  v_url := rtrim(v_functions_url, '/') || '/functions/v1/dispatch-notification';

  BEGIN
    PERFORM net.http_post(
      url := v_url,
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'Authorization', 'Bearer ' || v_service_role_key
      ),
      body := jsonb_build_object(
        'notification_id', NEW.notification_id,
        'user_id', NEW.user_id
      )
    );
  EXCEPTION
    WHEN OTHERS THEN
      RAISE LOG 'dispatch-notification enqueue failed: %', SQLERRM;
  END;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."trg_notification_recipients_dispatch"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trg_reactive_adjust_child_listing_cost"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_new_landed_cost numeric;
begin
  if new.purchase_price <> old.purchase_price or coalesce(new.landed_cost_bdt, -1) <> coalesce(old.landed_cost_bdt, -1) then
    v_new_landed_cost := coalesce(new.landed_cost_bdt, round(new.purchase_price, 2));

    update public.shop_product_listings spl
    set
      minimum_sell_price_amount = case
        when spl.is_price_locked is true then spl.minimum_sell_price_amount
        else v_new_landed_cost
      end,
      sell_price_amount = case
        when spl.is_price_locked is true then spl.sell_price_amount
        else greatest(spl.sell_price_amount, v_new_landed_cost)
      end,
      updated_at = now()
    from public.global_stocks gs
    where spl.global_stock_id = gs.id
      and gs.shipment_item_id = new.id;
  end if;

  return new;
end;
$$;


