CREATE OR REPLACE FUNCTION "public"."update_sales_invoice_from_payload"("p_tenant_id" bigint, "p_invoice_id" bigint, "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  v_inv_patch jsonb;
  v_items jsonb;
  v_remove_ids jsonb;
  v_item_elem jsonb;
  v_invoice public.sales_invoices;
  v_parent_id bigint;
  v_item_id bigint;
  v_global_stock_id bigint;
  v_quantity numeric;
  v_sell_price numeric;
  v_line_discount numeric;
  v_line_total numeric;
  v_unit_cost numeric;
  v_shipment_item_id bigint;
  v_product_id bigint;
  v_name_snapshot text;
  v_barcode_snapshot text;
  v_product_code_snapshot text;
  v_assigned_child bigint;
  v_stock_parent bigint;
  v_db_item public.sales_invoice_items;
  v_removed_ids bigint[] := '{}';
  v_remove_id bigint;
  v_result_items jsonb := '[]'::jsonb;
  v_has_changes boolean := false;
  v_recompute boolean := true;
  v_dropship_sync boolean := false;
begin
  if not public.is_tenant_staff(p_tenant_id) then
    return jsonb_build_object('success', false, 'error', 'access denied', 'code', 'ACCESS_DENIED');
  end if;

  if p_payload is null or jsonb_typeof(p_payload) <> 'object' then
    return jsonb_build_object('success', false, 'error', 'payload must be a JSON object', 'code', 'VALIDATION_ERROR');
  end if;

  v_dropship_sync := coalesce((p_payload->'options'->>'dropship_sync')::boolean, false);

  select * into v_invoice
  from public.sales_invoices
  where id = p_invoice_id
  for update;

  if v_invoice.id is null then
    return jsonb_build_object('success', false, 'error', 'invoice not found', 'code', 'NOT_FOUND');
  end if;

  if v_invoice.issued_by_tenant_id <> p_tenant_id then
    return jsonb_build_object('success', false, 'error', 'invoice does not belong to tenant', 'code', 'ACCESS_DENIED');
  end if;

  if v_invoice.invoice_status not in (
    'draft'::public.global_invoice_status,
    'proforma_generated'::public.global_invoice_status
  ) then
    if not (
      v_dropship_sync
      and v_invoice.invoice_type = 'dropship'::public.global_invoice_type
      and v_invoice.invoice_status = 'issued'::public.global_invoice_status
    ) then
      return jsonb_build_object(
        'success', false,
        'error', format('invoice is not editable (status: %s)', v_invoice.invoice_status),
        'code', 'INVOICE_NOT_EDITABLE'
      );
    end if;
  end if;

  v_inv_patch := p_payload->'invoice';
  v_items := coalesce(p_payload->'items', '[]'::jsonb);
  v_remove_ids := coalesce(p_payload->'remove_item_ids', '[]'::jsonb);
  v_recompute := coalesce((p_payload->'options'->>'recompute_totals')::boolean, true);

  if v_dropship_sync and v_invoice.invoice_status = 'issued'::public.global_invoice_status then
    v_remove_ids := '[]'::jsonb;
  end if;

  if (v_inv_patch is null or v_inv_patch = '{}'::jsonb)
     and jsonb_array_length(v_items) = 0
     and jsonb_array_length(v_remove_ids) = 0 then
    return jsonb_build_object('success', false, 'error', 'nothing to update', 'code', 'EMPTY_PAYLOAD');
  end if;

  v_parent_id := v_invoice.parent_tenant_id;

  if v_inv_patch is not null and jsonb_typeof(v_inv_patch) = 'object' and v_inv_patch <> '{}'::jsonb then
    if v_inv_patch ? 'billing_profile_id' and nullif(v_inv_patch->>'billing_profile_id', '') is not null then
      if not exists (
        select 1 from public.billing_profiles bp
        where bp.id = (v_inv_patch->>'billing_profile_id')::bigint
          and bp.tenant_id = p_tenant_id
      ) then
        return jsonb_build_object('success', false, 'error', 'billing profile must belong to tenant', 'code', 'VALIDATION_ERROR');
      end if;
    end if;

    if v_inv_patch ? 'recipient_profile_id' and nullif(v_inv_patch->>'recipient_profile_id', '') is not null then
      if not exists (
        select 1 from public.recipient_profiles rp
        where rp.id = (v_inv_patch->>'recipient_profile_id')::bigint
          and rp.tenant_id = p_tenant_id
      ) then
        return jsonb_build_object('success', false, 'error', 'recipient profile must belong to tenant', 'code', 'VALIDATION_ERROR');
      end if;
    end if;

    update public.sales_invoices
    set
      invoice_no = case
        when v_inv_patch ? 'invoice_no' then coalesce(nullif(trim(v_inv_patch->>'invoice_no'), ''), invoice_no)
        else invoice_no
      end,
      invoice_date = case
        when v_inv_patch ? 'invoice_date' then coalesce(nullif(v_inv_patch->>'invoice_date', '')::date, invoice_date)
        else invoice_date
      end,
      due_date = case
        when v_inv_patch ? 'due_date' then nullif(v_inv_patch->>'due_date', '')::date
        else due_date
      end,
      billing_profile_id = case
        when v_inv_patch ? 'billing_profile_id' then nullif(v_inv_patch->>'billing_profile_id', '')::bigint
        else billing_profile_id
      end,
      recipient_profile_id = case
        when v_inv_patch ? 'recipient_profile_id' then nullif(v_inv_patch->>'recipient_profile_id', '')::bigint
        else recipient_profile_id
      end,
      recipient_name = case
        when v_inv_patch ? 'recipient_name' then nullif(trim(v_inv_patch->>'recipient_name'), '')
        else recipient_name
      end,
      recipient_phone = case
        when v_inv_patch ? 'recipient_phone' then nullif(trim(v_inv_patch->>'recipient_phone'), '')
        else recipient_phone
      end,
      recipient_address = case
        when v_inv_patch ? 'recipient_address' then nullif(trim(v_inv_patch->>'recipient_address'), '')
        else recipient_address
      end,
      note = case
        when v_inv_patch ? 'note' then nullif(trim(v_inv_patch->>'note'), '')
        else note
      end,
      discount_amount = case
        when v_inv_patch ? 'discount_amount' then coalesce(nullif(v_inv_patch->>'discount_amount', '')::numeric, 0)
        else discount_amount
      end,
      shipping_charge = case
        when v_inv_patch ? 'shipping_charge' then coalesce(nullif(v_inv_patch->>'shipping_charge', '')::numeric, 0)
        else shipping_charge
      end,
      cod_charge_amount = case
        when v_inv_patch ? 'cod_charge_amount' then coalesce(nullif(v_inv_patch->>'cod_charge_amount', '')::numeric, 0)
        when v_inv_patch ? 'cod_charge' then coalesce(nullif(v_inv_patch->>'cod_charge', '')::numeric, 0)
        else cod_charge_amount
      end,
      print_charge = case
        when v_inv_patch ? 'print_charge' then coalesce(nullif(v_inv_patch->>'print_charge', '')::numeric, 0)
        else print_charge
      end,
      wrapping_charge = case
        when v_inv_patch ? 'wrapping_charge' then coalesce(nullif(v_inv_patch->>'wrapping_charge', '')::numeric, 0)
        else wrapping_charge
      end,
      collection_source = case
        when v_inv_patch ? 'collection_source' and nullif(trim(v_inv_patch->>'collection_source'), '') is not null
          then (v_inv_patch->>'collection_source')::public.collection_source_type
        else collection_source
      end,
      updated_at = now()
    where id = p_invoice_id;

    v_has_changes := true;
  end if;

  if jsonb_typeof(v_remove_ids) = 'array' and jsonb_array_length(v_remove_ids) > 0 then
    for v_remove_id in
      select (value::text)::bigint
      from jsonb_array_elements(v_remove_ids) as t(value)
      where value is not null and value::text ~ '^[0-9]+$'
    loop
      delete from public.sales_invoice_items
      where id = v_remove_id
        and invoice_id = p_invoice_id
      returning id into v_item_id;

      if v_item_id is not null then
        v_removed_ids := array_append(v_removed_ids, v_item_id);
        v_has_changes := true;
      end if;
    end loop;
  end if;

  if jsonb_typeof(v_items) = 'array' and jsonb_array_length(v_items) > 0 then
    for v_item_elem in select value from jsonb_array_elements(v_items) as t(value) loop
      v_item_id := nullif(v_item_elem->>'id', '')::bigint;

      if v_item_id is not null then
        select * into v_db_item
        from public.sales_invoice_items
        where id = v_item_id
          and invoice_id = p_invoice_id;

        if v_db_item.id is null then
          return jsonb_build_object(
            'success', false,
            'error', format('invoice item %s not found on invoice', v_item_id),
            'code', 'NOT_FOUND'
          );
        end if;

        v_quantity := coalesce(
          case when v_item_elem ? 'quantity' then nullif(v_item_elem->>'quantity', '')::numeric else null end,
          v_db_item.quantity
        );
        v_sell_price := coalesce(
          case when v_item_elem ? 'sell_price_amount' then nullif(v_item_elem->>'sell_price_amount', '')::numeric else null end,
          v_db_item.sell_price_amount
        );
        v_line_discount := coalesce(
          case when v_item_elem ? 'line_discount_amount' then nullif(v_item_elem->>'line_discount_amount', '')::numeric else null end,
          v_db_item.line_discount_amount,
          0
        );

        if v_quantity <= 0 then
          return jsonb_build_object('success', false, 'error', 'quantity must be > 0', 'code', 'VALIDATION_ERROR');
        end if;
        if v_sell_price < 0 then
          return jsonb_build_object('success', false, 'error', 'sell_price_amount must be >= 0', 'code', 'VALIDATION_ERROR');
        end if;

        v_line_total := greatest((v_quantity * v_sell_price) - v_line_discount, 0);

        update public.sales_invoice_items
        set
          quantity = v_quantity,
          sell_price_amount = v_sell_price,
          line_discount_amount = v_line_discount,
          line_total_amount = v_line_total,
          name_snapshot = case
            when v_item_elem ? 'name_snapshot' then coalesce(nullif(trim(v_item_elem->>'name_snapshot'), ''), name_snapshot)
            else name_snapshot
          end,
          unit_cost_price = case
            when v_item_elem ? 'unit_cost_price' then coalesce(nullif(v_item_elem->>'unit_cost_price', '')::numeric, 0)
            else unit_cost_price
          end,
          updated_at = now()
        where id = v_item_id
        returning * into v_db_item;

        v_has_changes := true;
      elsif not v_dropship_sync then
        v_global_stock_id := nullif(v_item_elem->>'global_stock_id', '')::bigint;
        v_quantity := nullif(v_item_elem->>'quantity', '')::numeric;
        v_sell_price := nullif(v_item_elem->>'sell_price_amount', '')::numeric;
        v_line_discount := coalesce(nullif(v_item_elem->>'line_discount_amount', '')::numeric, 0);

        if v_global_stock_id is null then
          return jsonb_build_object('success', false, 'error', 'new items require global_stock_id', 'code', 'VALIDATION_ERROR');
        end if;
        if v_quantity is null or v_quantity <= 0 then
          return jsonb_build_object('success', false, 'error', 'new items require quantity > 0', 'code', 'VALIDATION_ERROR');
        end if;
        if v_sell_price is null or v_sell_price < 0 then
          return jsonb_build_object('success', false, 'error', 'new items require sell_price_amount >= 0', 'code', 'VALIDATION_ERROR');
        end if;

        select
          gs.parent_tenant_id,
          gs.shipment_item_id,
          gsi.name,
          gsi.barcode,
          gsi.product_code,
          sh.assigned_child_tenant_id,
          p.id
        into
          v_stock_parent,
          v_shipment_item_id,
          v_name_snapshot,
          v_barcode_snapshot,
          v_product_code_snapshot,
          v_assigned_child,
          v_product_id
        from public.global_stocks gs
        left join public.global_shipment_items gsi on gsi.id = gs.shipment_item_id
        left join public.global_shipments sh on sh.id = gsi.shipment_id
        left join public.products p on p.id = gsi.product_id
        where gs.id = v_global_stock_id;

        if v_stock_parent is null then
          return jsonb_build_object('success', false, 'error', format('stock %s not found', v_global_stock_id), 'code', 'NOT_FOUND');
        end if;

        if v_stock_parent <> v_parent_id then
          return jsonb_build_object(
            'success', false,
            'error', format('stock %s does not belong to invoice parent tenant', v_global_stock_id),
            'code', 'VALIDATION_ERROR'
          );
        end if;

        v_shipment_item_id := coalesce(nullif(v_item_elem->>'shipment_item_id', '')::bigint, v_shipment_item_id);
        v_product_id := coalesce(nullif(v_item_elem->>'product_id', '')::bigint, v_product_id);
        v_name_snapshot := coalesce(nullif(trim(v_item_elem->>'name_snapshot'), ''), v_name_snapshot, 'Item');
        v_barcode_snapshot := coalesce(nullif(trim(v_item_elem->>'barcode_snapshot'), ''), v_barcode_snapshot);
        v_product_code_snapshot := coalesce(nullif(trim(v_item_elem->>'product_code_snapshot'), ''), v_product_code_snapshot);
        v_assigned_child := coalesce(nullif(v_item_elem->>'assigned_child_tenant_id', '')::bigint, v_assigned_child);
        v_unit_cost := coalesce(
          nullif(v_item_elem->>'unit_cost_price', '')::numeric,
          public.calculate_landed_unit_cost(v_shipment_item_id),
          0
        );
        v_line_total := greatest((v_quantity * v_sell_price) - v_line_discount, 0);

        insert into public.sales_invoice_items (
          parent_tenant_id,
          invoice_id,
          global_stock_id,
          shipment_item_id,
          product_id,
          name_snapshot,
          barcode_snapshot,
          product_code_snapshot,
          quantity,
          unit_cost_price,
          sell_price_amount,
          line_discount_amount,
          line_total_amount,
          assigned_child_tenant_id
        )
        values (
          v_parent_id,
          p_invoice_id,
          v_global_stock_id,
          v_shipment_item_id,
          v_product_id,
          v_name_snapshot,
          v_barcode_snapshot,
          v_product_code_snapshot,
          v_quantity,
          v_unit_cost,
          v_sell_price,
          v_line_discount,
          v_line_total,
          v_assigned_child
        )
        returning * into v_db_item;

        v_has_changes := true;
      end if;
    end loop;
  end if;

  if not v_has_changes then
    return jsonb_build_object('success', false, 'error', 'nothing to update', 'code', 'EMPTY_PAYLOAD');
  end if;

  if v_recompute then
    perform public.recompute_global_invoice_totals(p_invoice_id);
  end if;

  select * into v_invoice from public.sales_invoices where id = p_invoice_id;

  if v_dropship_sync then
    if v_invoice.invoice_status in (
      'draft'::public.global_invoice_status,
      'proforma_generated'::public.global_invoice_status
    ) then
      perform public.post_sales_invoice(p_invoice_id);
      select * into v_invoice from public.sales_invoices where id = p_invoice_id;
    elsif v_invoice.payment_status not in ('paid', 'partially_paid') then
      update public.sales_invoices
      set
        payment_status = 'due',
        due_amount = greatest(coalesce(v_invoice.total_amount, 0) - coalesce(v_invoice.paid_amount, 0), 0),
        updated_at = now()
      where id = p_invoice_id;
      select * into v_invoice from public.sales_invoices where id = p_invoice_id;
    end if;
    perform public.recompute_global_invoice_payment_status(p_invoice_id);
    select * into v_invoice from public.sales_invoices where id = p_invoice_id;
  end if;

  select coalesce(jsonb_agg(to_jsonb(sii.*) order by sii.id), '[]'::jsonb)
  into v_result_items
  from public.sales_invoice_items sii
  where sii.invoice_id = p_invoice_id;

  return jsonb_build_object(
    'success', true,
    'invoice_id', v_invoice.id,
    'invoice_no', v_invoice.invoice_no,
    'invoice_type', v_invoice.invoice_type,
    'invoice_status', v_invoice.invoice_status,
    'payment_status', v_invoice.payment_status,
    'invoice', jsonb_build_object(
      'id', v_invoice.id,
      'parent_tenant_id', v_invoice.parent_tenant_id,
      'issued_by_tenant_id', v_invoice.issued_by_tenant_id,
      'invoice_type', v_invoice.invoice_type,
      'invoice_no', v_invoice.invoice_no,
      'invoice_status', v_invoice.invoice_status,
      'payment_status', v_invoice.payment_status,
      'billing_profile_id', v_invoice.billing_profile_id,
      'recipient_profile_id', v_invoice.recipient_profile_id,
      'recipient_name', v_invoice.recipient_name,
      'recipient_phone', v_invoice.recipient_phone,
      'recipient_address', v_invoice.recipient_address,
      'collection_source', v_invoice.collection_source,
      'subtotal_amount', v_invoice.subtotal_amount,
      'discount_amount', v_invoice.discount_amount,
      'shipping_charge', v_invoice.shipping_charge,
      'cod_charge_amount', v_invoice.cod_charge_amount,
      'print_charge', v_invoice.print_charge,
      'wrapping_charge', v_invoice.wrapping_charge,
      'total_amount', v_invoice.total_amount,
      'paid_amount', v_invoice.paid_amount,
      'due_amount', v_invoice.due_amount,
      'note', v_invoice.note,
      'due_date', v_invoice.due_date,
      'invoice_date', v_invoice.invoice_date
    ),
    'items', v_result_items,
    'removed_item_ids', to_jsonb(v_removed_ids)
  );
exception
  when others then
    return jsonb_build_object('success', false, 'error', sqlerrm, 'code', 'VALIDATION_ERROR');
end;
$_$;


ALTER FUNCTION "public"."update_sales_invoice_from_payload"("p_tenant_id" bigint, "p_invoice_id" bigint, "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_shipment"("p_id" bigint, "p_field" "text", "p_value" "text") RETURNS "public"."shipments"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_row public.shipments;
  v_field text;
  v_value text;
  v_type text;
begin
  select *
  into v_row
  from public.shipments
  where id = p_id;

  if v_row.id is null then
    raise exception 'shipment not found';
  end if;

  if not public.can_manage_shipment(v_row.tenant_id) then
    raise exception 'not allowed';
  end if;

  v_field := lower(trim(coalesce(p_field, '')));
  v_value := trim(coalesce(p_value, ''));

  if v_field = 'name' then
    update public.shipments set name = v_value where id = p_id returning * into v_row;
  elsif v_field = 'shipment_type' then
    v_type := lower(v_value);
    if v_type not in ('local', 'international') then
      raise exception 'invalid shipment_type: %', v_value;
    end if;
    update public.shipments set shipment_type = v_type where id = p_id returning * into v_row;
  elsif v_field = 'status' then
    update public.shipments set status = v_value where id = p_id returning * into v_row;
  elsif v_field = 'inventory_added' then
    update public.shipments
    set inventory_added = coalesce(nullif(v_value, '')::boolean, false)
    where id = p_id returning * into v_row;
  elsif v_field = 'product_conversion_rate' then
    update public.shipments
    set product_conversion_rate = nullif(v_value, '')::numeric
    where id = p_id returning * into v_row;
  elsif v_field = 'cargo_conversion_rate' then
    update public.shipments
    set cargo_conversion_rate = nullif(v_value, '')::numeric
    where id = p_id returning * into v_row;
  elsif v_field = 'cargo_rate' then
    update public.shipments
    set cargo_rate = nullif(v_value, '')::numeric
    where id = p_id returning * into v_row;
  elsif v_field = 'weight' then
    update public.shipments
    set weight = nullif(v_value, '')::numeric
    where id = p_id returning * into v_row;
  elsif v_field = 'received_weight' then
    update public.shipments
    set received_weight = nullif(v_value, '')::numeric
    where id = p_id returning * into v_row;
  elsif v_field = 'transaction_rate' then
    update public.shipments
    set transaction_rate = nullif(v_value, '')::numeric
    where id = p_id returning * into v_row;
  else
    raise exception 'unsupported shipment field: %', p_field;
  end if;

  return v_row;
end;
$$;


ALTER FUNCTION "public"."update_shipment"("p_id" bigint, "p_field" "text", "p_value" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."shipment_investments" (
    "id" bigint NOT NULL,
    "tenant_id" bigint NOT NULL,
    "shipment_id" bigint,
    "investor_id" bigint NOT NULL,
    "invested_amount" numeric(12,2) DEFAULT 0 NOT NULL,
    "actual_profit" numeric(12,2) DEFAULT 0 NOT NULL,
    "status" "public"."shipment_investment_status" DEFAULT 'active'::"public"."shipment_investment_status" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "cost_share_pct" numeric(5,2),
    "allocated_cost" numeric(12,2) DEFAULT 0 NOT NULL,
    "computed_profit" numeric(12,2) DEFAULT 0 NOT NULL,
    "profit_status" "text" DEFAULT 'open'::"text" NOT NULL,
    "global_shipment_id" bigint,
    CONSTRAINT "shipment_investments_cost_share_pct_check" CHECK ((("cost_share_pct" IS NULL) OR (("cost_share_pct" >= (0)::numeric) AND ("cost_share_pct" <= (100)::numeric)))),
    CONSTRAINT "shipment_investments_invested_amount_check" CHECK (("invested_amount" >= (0)::numeric)),
    CONSTRAINT "shipment_investments_profit_status_check" CHECK (("profit_status" = ANY (ARRAY['open'::"text", 'partial'::"text", 'realized'::"text"])))
);


ALTER TABLE "public"."shipment_investments" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_shipment_investment_cost_share"("p_shipment_investment_id" bigint, "p_cost_share_pct" numeric) RETURNS "public"."shipment_investments"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_row public.shipment_investments;
  v_total numeric(5,2);
begin
  select * into v_row from public.shipment_investments where id = p_shipment_investment_id;
  if v_row.id is null then raise exception 'investment not found'; end if;

  if not public.user_can_manage_parent_tenant(v_row.tenant_id) then
    raise exception 'not allowed';
  end if;

  if p_cost_share_pct < 0 or p_cost_share_pct > 100 then
    raise exception 'cost_share_pct must be between 0 and 100';
  end if;

  select coalesce(sum(cost_share_pct), 0) into v_total
  from public.shipment_investments
  where shipment_id = v_row.shipment_id
    and id <> p_shipment_investment_id
    and cost_share_pct is not null;

  if v_total + p_cost_share_pct > 100 then
    raise exception 'total cost_share_pct cannot exceed 100';
  end if;

  update public.shipment_investments
  set cost_share_pct = p_cost_share_pct
  where id = p_shipment_investment_id
  returning * into v_row;

  perform public.refresh_shipment_investor_profits(v_row.shipment_id);

  return v_row;
end;
$$;


ALTER FUNCTION "public"."update_shipment_investment_cost_share"("p_shipment_investment_id" bigint, "p_cost_share_pct" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_shipment_progress_flow"("p_flow_id" bigint, "p_name" "text" DEFAULT NULL::"text") RETURNS "public"."shipment_progress_flows"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_flow public.shipment_progress_flows;
  v_slug text;
begin
  select * into v_flow
  from public.shipment_progress_flows
  where id = p_flow_id
  for update;

  if not found then
    raise exception 'flow not found';
  end if;

  if not public.has_active_tenant_membership(v_flow.tenant_id)
     and not public.is_superadmin() then
    raise exception 'not authorized';
  end if;

  if p_name is null or trim(p_name) = '' then
    return v_flow;
  end if;

  v_slug := lower(regexp_replace(trim(p_name), '[^a-z0-9]+', '-', 'gi'));

  update public.shipment_progress_flows
  set
    name = trim(p_name),
    slug = v_slug
  where id = p_flow_id
  returning * into v_flow;

  return v_flow;
end;
$$;


ALTER FUNCTION "public"."update_shipment_progress_flow"("p_flow_id" bigint, "p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_shipment_progress_flow_stage"("p_flow_stage_id" bigint, "p_name" "text" DEFAULT NULL::"text", "p_color" "text" DEFAULT NULL::"text") RETURNS TABLE("flow_stage_id" bigint, "flow_id" bigint, "tag_id" bigint, "sort_order" integer, "name" "text", "slug" "text", "color" "text", "is_active" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_stage public.shipment_progress_flow_stages;
  v_flow public.shipment_progress_flows;
  v_tag public.tags;
  v_slug text;
begin
  select * into v_stage
  from public.shipment_progress_flow_stages
  where id = p_flow_stage_id
  for update;

  if not found then
    raise exception 'flow stage not found';
  end if;

  select * into v_flow
  from public.shipment_progress_flows
  where id = v_stage.flow_id;

  if not public.has_active_tenant_membership(v_flow.tenant_id)
     and not public.is_superadmin() then
    raise exception 'not authorized';
  end if;

  select * into v_tag
  from public.tags
  where id = v_stage.tag_id
  for update;

  if p_name is not null and trim(p_name) <> '' then
    v_slug := lower(regexp_replace(trim(p_name), '[^a-z0-9]+', '-', 'gi'));
  else
    v_slug := v_tag.slug;
  end if;

  update public.tags
  set
    name = coalesce(nullif(trim(p_name), ''), name),
    slug = v_slug,
    color = coalesce(p_color, color)
  where id = v_stage.tag_id
  returning * into v_tag;

  return query
  select
    v_stage.id,
    v_stage.flow_id,
    v_stage.tag_id,
    v_stage.sort_order,
    v_tag.name,
    v_tag.slug,
    v_tag.color,
    v_tag.is_active;
end;
$$;


ALTER FUNCTION "public"."update_shipment_progress_flow_stage"("p_flow_stage_id" bigint, "p_name" "text", "p_color" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_shipment_progress_tag"("p_tag_id" bigint, "p_name" "text" DEFAULT NULL::"text", "p_color" "text" DEFAULT NULL::"text", "p_sort_order" integer DEFAULT NULL::integer) RETURNS "public"."tags"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_tag public.tags;
  v_result public.tags;
  v_new_slug text;
begin
  select * into v_tag
  from public.tags
  where id = p_tag_id
  for update;

  if not found then
    raise exception 'tag not found';
  end if;

  if v_tag.group_name is distinct from 'shipment_progress' then
    raise exception 'tag is not a shipment_progress tag';
  end if;

  if not public.has_active_tenant_membership(v_tag.tenant_id)
     and not public.is_superadmin() then
    raise exception 'not authorized';
  end if;

  if v_tag.is_system then
    raise exception 'system tags cannot be updated via this RPC';
  end if;

  if p_name is not null and trim(p_name) <> '' then
    v_new_slug := lower(regexp_replace(trim(p_name), '[^a-z0-9]+', '-', 'gi'));
    if exists (
      select 1 from public.tags t
      where t.tenant_id = v_tag.tenant_id
        and t.group_name = 'shipment_progress'
        and t.slug = v_new_slug
        and t.id <> p_tag_id
    ) then
      raise exception 'a progress tag with this name already exists';
    end if;
  else
    v_new_slug := v_tag.slug;
  end if;

  update public.tags
  set
    name       = coalesce(nullif(trim(p_name), ''), name),
    slug       = v_new_slug,
    color      = coalesce(p_color, color),
    sort_order = coalesce(p_sort_order, sort_order)
  where id = p_tag_id
  returning * into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."update_shipment_progress_tag"("p_tag_id" bigint, "p_name" "text", "p_color" "text", "p_sort_order" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_shop_cart_item_price"("p_cart_item_id" bigint, "p_price" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_cart_id bigint;
  v_shop_id bigint;
  v_tenant_id bigint;
  v_shop_type public.shop_type_enum;
  v_global_stock_allocation_id bigint;
  v_sell_price_amount numeric;
  v_sell_price_currency_id bigint;
  v_customer_sell_price_currency_id bigint;
  v_min_sell_price_amount numeric;
  v_min_sell_price_currency_id bigint;
begin
  select ci.cart_id, ci.global_stock_allocation_id, c.shop_id, c.tenant_id, s.shop_type,
         ci.unit_sell_price_amount, ci.unit_sell_price_currency_id, ci.customer_sell_price_currency_id,
         ci.unit_minimum_sell_price_amount, ci.unit_minimum_sell_price_currency_id
  into v_cart_id, v_global_stock_allocation_id, v_shop_id, v_tenant_id, v_shop_type,
       v_sell_price_amount, v_sell_price_currency_id, v_customer_sell_price_currency_id,
       v_min_sell_price_amount, v_min_sell_price_currency_id
  from public.shop_cart_items ci
  join public.shop_carts c on c.id = ci.cart_id
  join public.shops s on s.id = c.shop_id
  where ci.id = p_cart_item_id;

  if v_cart_id is null then
    raise exception 'cart item not found';
  end if;

  if not public.is_cart_owner((select customer_group_id from public.shop_carts where id = v_cart_id), v_tenant_id) then
    raise exception 'access denied';
  end if;

  if v_shop_type <> 'dropship' then
    raise exception 'price updates only allowed for dropship shops';
  end if;

  if p_price < 0 then
    raise exception 'price cannot be negative';
  end if;

  -- Enforce minimum sell price floor
  if v_customer_sell_price_currency_id = v_min_sell_price_currency_id 
     and p_price < v_min_sell_price_amount then
    raise exception 'price cannot be lower than the minimum sell price %', v_min_sell_price_amount;
  end if;

  update public.shop_cart_items
  set customer_sell_price_amount = p_price, updated_at = now()
  where id = p_cart_item_id;

  return public.get_or_create_shop_cart(v_shop_id);
end;
$$;


ALTER FUNCTION "public"."update_shop_cart_item_price"("p_cart_item_id" bigint, "p_price" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_shop_cart_item_qty"("p_cart_item_id" bigint, "p_quantity" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_cart_id bigint;
  v_shop_id bigint;
  v_tenant_id bigint;
  v_shop_type public.shop_type_enum;
  v_product_id bigint;
  v_listing_id bigint;
  v_grade_tag_id bigint;
  v_display_qty_override integer;
  v_available_to_sell integer;
BEGIN
  IF p_quantity <= 0 THEN
    RETURN public.remove_shop_cart_item(p_cart_item_id);
  END IF;

  SELECT ci.cart_id, ci.product_id, ci.listing_id, ci.grade_tag_id,
         c.shop_id, c.tenant_id, s.shop_type
  INTO v_cart_id, v_product_id, v_listing_id, v_grade_tag_id,
       v_shop_id, v_tenant_id, v_shop_type
  FROM public.shop_cart_items ci
  JOIN public.shop_carts c ON c.id = ci.cart_id
  JOIN public.shops s ON s.id = c.shop_id
  WHERE ci.id = p_cart_item_id;

  IF v_cart_id IS NULL THEN
    RAISE EXCEPTION 'cart item not found';
  END IF;

  IF NOT public.is_cart_owner(
    (SELECT customer_group_id FROM public.shop_carts WHERE id = v_cart_id),
    v_tenant_id
  ) THEN
    RAISE EXCEPTION 'access denied';
  END IF;

  IF v_shop_type IN ('fixed_price', 'dropship') AND v_grade_tag_id IS NOT NULL THEN
    SELECT l.display_quantity_override
    INTO v_display_qty_override
    FROM public.shop_product_listings l
    WHERE l.id = coalesce(v_listing_id, -1);

    v_available_to_sell := public.shop_product_grade_available_units(
      v_tenant_id, v_product_id, v_grade_tag_id
    );
    IF v_display_qty_override IS NOT NULL THEN
      v_available_to_sell := v_display_qty_override;
    END IF;

    IF p_quantity > v_available_to_sell THEN
      RAISE EXCEPTION 'insufficient stock: requested %, available %',
        p_quantity, greatest(0, v_available_to_sell);
    END IF;
  END IF;

  UPDATE public.shop_cart_items
  SET quantity = p_quantity, updated_at = now()
  WHERE id = p_cart_item_id;

  RETURN public.get_or_create_shop_cart(v_shop_id);
END;
$$;


ALTER FUNCTION "public"."update_shop_cart_item_qty"("p_cart_item_id" bigint, "p_quantity" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_shop_order_charges_for_staff"("p_tenant_id" bigint, "p_order_id" bigint, "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_order record;
begin
  if p_tenant_id is null or p_order_id is null then
    raise exception 'tenant and order required';
  end if;

  if not public.is_tenant_staff(p_tenant_id) then
    raise exception 'access denied';
  end if;

  select * into v_order from public.shop_orders where id = p_order_id;
  if not found or (v_order.tenant_id is distinct from p_tenant_id and v_order.parent_tenant_id is distinct from p_tenant_id) then
    raise exception 'order not found';
  end if;

  update public.shop_orders o
  set
    delivery_charge_amount = coalesce((p_payload->>'delivery_charge_amount')::numeric, o.delivery_charge_amount),
    deduct_delivery_from_margin = coalesce((p_payload->>'deduct_delivery_from_margin')::boolean, o.deduct_delivery_from_margin),
    cod_charge_amount = coalesce((p_payload->>'cod_charge_amount')::numeric, o.cod_charge_amount),
    deduct_cod_from_margin = coalesce((p_payload->>'deduct_cod_from_margin')::boolean, o.deduct_cod_from_margin),
    print_charge_amount = coalesce((p_payload->>'print_charge_amount')::numeric, o.print_charge_amount),
    deduct_print_from_margin = coalesce((p_payload->>'deduct_print_from_margin')::boolean, o.deduct_print_from_margin),
    packing_charge_amount = coalesce((p_payload->>'packing_charge_amount')::numeric, o.packing_charge_amount),
    deduct_packing_from_margin = coalesce((p_payload->>'deduct_packing_from_margin')::boolean, o.deduct_packing_from_margin),
    updated_at = now()
  where o.id = p_order_id;

  return public.get_shop_order_for_staff(p_tenant_id, p_order_id);
end;
$$;


ALTER FUNCTION "public"."update_shop_order_charges_for_staff"("p_tenant_id" bigint, "p_order_id" bigint, "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_shop_order_status_for_staff"("p_tenant_id" bigint, "p_order_id" bigint, "p_status" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_order record;
begin
  if p_tenant_id is null or p_order_id is null or p_status is null then
    raise exception 'tenant, order, and status required';
  end if;

  if not public.is_tenant_staff(p_tenant_id) then
    raise exception 'access denied';
  end if;

  select * into v_order from public.shop_orders where id = p_order_id;
  if not found or (v_order.tenant_id is distinct from p_tenant_id and v_order.parent_tenant_id is distinct from p_tenant_id) then
    raise exception 'order not found';
  end if;

  update public.shop_orders o
  set
    status = p_status::public.shop_order_status,
    updated_at = now()
  where o.id = p_order_id;

  return public.get_shop_order_for_staff(p_tenant_id, p_order_id);
end;
$$;


ALTER FUNCTION "public"."update_shop_order_status_for_staff"("p_tenant_id" bigint, "p_order_id" bigint, "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_tenant_for_superadmin"("p_tenant_id" bigint, "p_name" "text", "p_slug" "text", "p_is_active" boolean, "p_public_domain" "text" DEFAULT NULL::"text", "p_parent_id" bigint DEFAULT NULL::bigint) RETURNS TABLE("id" bigint, "name" "text", "slug" "text", "public_domain" "text", "is_active" boolean, "parent_id" bigint, "preference" "jsonb", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
  with permission as (
    select public.is_superadmin() as allowed
  ),
  updated as (
    update public.tenants as t
    set
      name = trim(p_name),
      slug = lower(trim(p_slug)),
      public_domain = nullif(
        regexp_replace(
          lower(
            trim(
              split_part(
                regexp_replace(coalesce(p_public_domain, ''), '^https?://', '', 'i'),
                '/',
                1
              )
            )
          ),
          ':\d+$',
          ''
        ),
        ''
      ),
      is_active = coalesce(p_is_active, true),
      parent_id = p_parent_id
    from permission
    where allowed
      and t.id = p_tenant_id
    returning
      t.id,
      t.name,
      t.slug,
      t.public_domain,
      t.is_active,
      t.parent_id,
      t.preference,
      t.created_at,
      t.updated_at
  )
  select
    id,
    name,
    slug,
    public_domain,
    is_active,
    parent_id,
    preference,
    created_at,
    updated_at
  from updated;
$_$;


ALTER FUNCTION "public"."update_tenant_for_superadmin"("p_tenant_id" bigint, "p_name" "text", "p_slug" "text", "p_is_active" boolean, "p_public_domain" "text", "p_parent_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_tenant_module_for_superadmin"("p_id" bigint, "p_tenant_id" bigint DEFAULT NULL::bigint, "p_module_key" "text" DEFAULT NULL::"text", "p_is_active" boolean DEFAULT NULL::boolean) RETURNS TABLE("id" bigint, "tenant_id" bigint, "module_key" "text", "is_active" boolean, "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with permission as (
    select public.is_superadmin() as allowed
  ),
  updated as (
    update public.tenant_modules tm
    set
      tenant_id = coalesce(p_tenant_id, tm.tenant_id),
      module_key = coalesce(lower(trim(p_module_key)), tm.module_key),
      is_active = coalesce(p_is_active, tm.is_active)
    from permission
    where allowed
      and tm.id = p_id
    returning
      tm.id,
      tm.tenant_id,
      tm.module_key,
      tm.is_active,
      tm.created_at,
      tm.updated_at
  )
  select
    id,
    tenant_id,
    module_key,
    is_active,
    created_at,
    updated_at
  from updated;
$$;


ALTER FUNCTION "public"."update_tenant_module_for_superadmin"("p_id" bigint, "p_tenant_id" bigint, "p_module_key" "text", "p_is_active" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_tenant_preference_for_admin"("p_tenant_id" bigint, "p_preference" "jsonb") RETURNS TABLE("id" bigint, "name" "text", "slug" "text", "public_domain" "text", "is_active" boolean, "parent_id" bigint, "preference" "jsonb", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not (
    public.is_superadmin()
    or public.is_tenant_admin(p_tenant_id)
  ) then
    return;
  end if;

  if jsonb_typeof(p_preference) is distinct from 'object' then
    raise exception 'Tenant preference must be a JSON object';
  end if;

  return query
  update public.tenants as t
  set preference = p_preference
  where t.id = p_tenant_id
  returning
    t.id,
    t.name,
    t.slug,
    t.public_domain,
    t.is_active,
    t.parent_id,
    t.preference,
    t.created_at,
    t.updated_at;
end;
$$;


ALTER FUNCTION "public"."update_tenant_preference_for_admin"("p_tenant_id" bigint, "p_preference" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_tenant_role"("p_role_id" bigint, "p_name" "text", "p_is_admin" boolean) RETURNS "public"."tenant_roles"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_row public.tenant_roles;
begin
  select * into v_row from public.tenant_roles where id = p_role_id;

  if v_row.id is null then
    raise exception 'Role not found';
  end if;

  if not public.user_is_tenant_admin(v_row.tenant_id) then
    raise exception 'Unauthorized';
  end if;

  if p_is_admin = true and v_row.is_admin = false and exists (
    select 1 from public.tenant_roles
    where tenant_id = v_row.tenant_id and scope = v_row.scope and is_admin = true and id <> p_role_id
  ) then
    raise exception 'Only one Administrator role is allowed per scope';
  end if;

  if v_row.is_system = true and v_row.is_admin <> p_is_admin then
    raise exception 'Cannot modify admin status of system roles';
  end if;

  update public.tenant_roles
  set
    name = trim(p_name),
    is_admin = p_is_admin,
    updated_at = now()
  where id = p_role_id
  returning * into v_row;

  return v_row;
end;
$$;


ALTER FUNCTION "public"."update_tenant_role"("p_role_id" bigint, "p_name" "text", "p_is_admin" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_thrift_sales_delivery_status"("p_tenant_id" bigint, "p_invoice_id" bigint, "p_delivery_status" "text", "p_actor" "text" DEFAULT 'cashier'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_invoice public.thrift_sales_invoices%ROWTYPE;
  v_target TEXT;
  v_current TEXT;
  v_event_at TIMESTAMPTZ := NOW();
  v_pool_delivery NUMERIC(12,2) := 0.00;
  v_pool_cod NUMERIC(12,2) := 0.00;
  v_pool_packing NUMERIC(12,2) := 0.00;
  v_total_value NUMERIC(12,2) := 0.00;
  v_line_count INT := 0;
  v_idx INT := 0;
  v_cum_delivery NUMERIC(12,2) := 0.00;
  v_cum_cod NUMERIC(12,2) := 0.00;
  v_cum_packing NUMERIC(12,2) := 0.00;
  v_line RECORD;
  v_line_value NUMERIC(12,2);
  v_share NUMERIC;
  v_alloc_delivery NUMERIC(12,2);
  v_alloc_cod NUMERIC(12,2);
  v_alloc_packing NUMERIC(12,2);
  v_inbound_shipment_id BIGINT;
  v_pnl_exists BOOLEAN := FALSE;
  v_non_delivered_pnl INT := 0;
  v_deleted_pnl INT := 0;
  v_economics_closed_at TIMESTAMPTZ;
BEGIN
  IF NOT public.membership_has_module_action(p_tenant_id, 'thrift_sales', 'create')
     AND NOT public.membership_has_module_action(p_tenant_id, 'thrift_sales', 'return')
  THEN
    RAISE EXCEPTION 'Updating delivery status requires thrift_sales create or return permission';
  END IF;

  v_target := upper(trim(COALESCE(p_delivery_status, '')));
  IF v_target NOT IN ('PENDING', 'READY', 'IN_TRANSIT', 'DELIVERED', 'RETURNED') THEN
    RAISE EXCEPTION 'Invalid delivery_status: %', p_delivery_status;
  END IF;

  SELECT * INTO v_invoice
  FROM public.thrift_sales_invoices
  WHERE id = p_invoice_id
    AND tenant_id = p_tenant_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Invoice % not found for tenant %', p_invoice_id, p_tenant_id;
  END IF;

  IF COALESCE(v_invoice.sale_channel, 'IN_STORE') <> 'ONLINE' THEN
    RAISE EXCEPTION 'delivery_status applies to Online invoices only';
  END IF;

  IF v_invoice.status IS DISTINCT FROM 'ACTIVE' THEN
    RAISE EXCEPTION 'Cannot update delivery on invoice status %', v_invoice.status;
  END IF;

  IF v_target = 'RETURNED' THEN
    RAISE EXCEPTION
      'Set delivery RETURNED via revert_thrift_sales_invoice (RTO), not delivery advance';
  END IF;

  v_current := COALESCE(v_invoice.delivery_status, 'PENDING');
  v_economics_closed_at := v_invoice.economics_closed_at;

  IF v_current = v_target THEN
    RETURN jsonb_build_object(
      'id', v_invoice.id,
      'delivery_status', v_current,
      'unchanged', true,
      'economics_closed_at', v_invoice.economics_closed_at
    );
  END IF;

  -- Correction: undo mistaken deliver (only to IN_TRANSIT; reopen economics).
  IF v_current = 'DELIVERED' AND v_target = 'IN_TRANSIT' THEN
    SELECT COUNT(*)::INT
    INTO v_non_delivered_pnl
    FROM public.thrift_sales_pnl_lines p
    WHERE p.tenant_id = p_tenant_id
      AND p.invoice_id = p_invoice_id
      AND p.outcome IS DISTINCT FROM 'DELIVERED';

    IF v_non_delivered_pnl > 0 THEN
      RAISE EXCEPTION
        'Cannot move delivery from DELIVERED to IN_TRANSIT after return/RTO PnL exists';
    END IF;

    DELETE FROM public.thrift_sales_pnl_lines p
    WHERE p.tenant_id = p_tenant_id
      AND p.invoice_id = p_invoice_id
      AND p.outcome = 'DELIVERED';

    GET DIAGNOSTICS v_deleted_pnl = ROW_COUNT;

    UPDATE public.thrift_sales_invoices
    SET
      delivery_status = 'IN_TRANSIT',
      economics_closed_at = NULL,
      updated_at = NOW()
    WHERE id = p_invoice_id
      AND tenant_id = p_tenant_id;

    RETURN jsonb_build_object(
      'id', p_invoice_id,
      'delivery_status', 'IN_TRANSIT',
      'previous_delivery_status', v_current,
      'actor', COALESCE(NULLIF(trim(p_actor), ''), 'cashier'),
      'unchanged', false,
      'pnl_lines_deleted', v_deleted_pnl,
      'economics_closed_at', NULL
    );
  END IF;

  IF v_current = 'DELIVERED' AND v_target <> 'DELIVERED' THEN
    RAISE EXCEPTION 'Cannot move delivery from DELIVERED to %', v_target;
  END IF;

  UPDATE public.thrift_sales_invoices
  SET
    delivery_status = v_target,
    updated_at = NOW()
  WHERE id = p_invoice_id
    AND tenant_id = p_tenant_id;

  -- First DELIVERED: write PnL (shop-paid fee pools only). Never flip payment_status.
  IF v_target = 'DELIVERED' THEN
    SELECT EXISTS (
      SELECT 1
      FROM public.thrift_sales_pnl_lines p
      WHERE p.tenant_id = p_tenant_id
        AND p.invoice_id = p_invoice_id
    )
    INTO v_pnl_exists;

    IF NOT v_pnl_exists THEN
      v_pool_delivery := CASE
        WHEN upper(COALESCE(v_invoice.courier_paid_by, '')) = 'SHOP'
        THEN ROUND(COALESCE(v_invoice.courier_amount, 0), 2)
        ELSE 0.00
      END;
      v_pool_cod := CASE
        WHEN upper(COALESCE(v_invoice.cod_fee_paid_by, '')) = 'SHOP'
        THEN ROUND(COALESCE(v_invoice.cod_fee_amount, 0), 2)
        ELSE 0.00
      END;
      v_pool_packing := CASE
        WHEN upper(COALESCE(v_invoice.packing_paid_by, '')) = 'SHOP'
        THEN ROUND(COALESCE(v_invoice.packing_amount, 0), 2)
        ELSE 0.00
      END;

      SELECT
        COALESCE(SUM(ROUND(i.final_price * i.quantity, 2)), 0),
        COUNT(*)::INT
      INTO v_total_value, v_line_count
      FROM public.thrift_sales_invoice_items i
      WHERE i.tenant_id = p_tenant_id
        AND i.invoice_id = p_invoice_id;

      IF v_line_count = 0 THEN
        RAISE EXCEPTION 'Invoice % has no lines; cannot close economics', p_invoice_id;
      END IF;

      FOR v_line IN
        SELECT
          i.id AS invoice_item_id,
          i.stock_id,
          i.quantity,
          ROUND(i.final_price * i.quantity, 2) AS sell_amount,
          s.shipment_id
        FROM public.thrift_sales_invoice_items i
        JOIN public.thrift_stocks s
          ON s.id = i.stock_id
         AND s.tenant_id = i.tenant_id
        WHERE i.tenant_id = p_tenant_id
          AND i.invoice_id = p_invoice_id
        ORDER BY i.id
      LOOP
        v_idx := v_idx + 1;
        v_inbound_shipment_id := v_line.shipment_id;
        IF v_inbound_shipment_id IS NULL THEN
          RAISE EXCEPTION
            'Stock item % has no inbound shipment; cannot write PnL',
            v_line.stock_id;
        END IF;

        v_line_value := v_line.sell_amount;
        IF v_total_value > 0 THEN
          v_share := v_line_value / v_total_value;
        ELSE
          v_share := 1.0 / v_line_count;
        END IF;

        IF v_idx = v_line_count THEN
          v_alloc_delivery := ROUND(v_pool_delivery - v_cum_delivery, 2);
          v_alloc_cod := ROUND(v_pool_cod - v_cum_cod, 2);
          v_alloc_packing := ROUND(v_pool_packing - v_cum_packing, 2);
        ELSE
          v_alloc_delivery := ROUND(v_pool_delivery * v_share, 2);
          v_alloc_cod := ROUND(v_pool_cod * v_share, 2);
          v_alloc_packing := ROUND(v_pool_packing * v_share, 2);
          v_cum_delivery := v_cum_delivery + v_alloc_delivery;
          v_cum_cod := v_cum_cod + v_alloc_cod;
          v_cum_packing := v_cum_packing + v_alloc_packing;
        END IF;

        INSERT INTO public.thrift_sales_pnl_lines (
          tenant_id,
          invoice_id,
          invoice_item_id,
          stock_id,
          inbound_shipment_id,
          outcome,
          return_id,
          quantity,
          sell_amount,
          allocated_shop_delivery,
          allocated_shop_cod_fee,
          allocated_shop_packing,
          allocated_return_courier,
          allocated_fees_total,
          cogs_is_loss,
          event_at,
          event_date
        ) VALUES (
          p_tenant_id,
          p_invoice_id,
          v_line.invoice_item_id,
          v_line.stock_id,
          v_inbound_shipment_id,
          'DELIVERED',
          NULL,
          v_line.quantity,
          v_line_value,
          v_alloc_delivery,
          v_alloc_cod,
          v_alloc_packing,
          0.00,
          ROUND(v_alloc_delivery + v_alloc_cod + v_alloc_packing, 2),
          FALSE,
          v_event_at,
          (v_event_at AT TIME ZONE 'UTC')::DATE
        );
      END LOOP;

      UPDATE public.thrift_sales_invoices
      SET
        economics_closed_at = v_event_at,
        updated_at = NOW()
      WHERE id = p_invoice_id
        AND tenant_id = p_tenant_id;

      v_economics_closed_at := v_event_at;
    ELSIF v_invoice.economics_closed_at IS NULL THEN
      UPDATE public.thrift_sales_invoices
      SET
        economics_closed_at = v_event_at,
        updated_at = NOW()
      WHERE id = p_invoice_id
        AND tenant_id = p_tenant_id;

      v_economics_closed_at := v_event_at;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'id', p_invoice_id,
    'delivery_status', v_target,
    'previous_delivery_status', v_current,
    'actor', COALESCE(NULLIF(trim(p_actor), ''), 'cashier'),
    'unchanged', false,
    'economics_closed_at', CASE
      WHEN v_target = 'DELIVERED' THEN COALESCE(v_economics_closed_at, v_event_at)
      ELSE v_economics_closed_at
    END
  );
END;
$$;


ALTER FUNCTION "public"."update_thrift_sales_delivery_status"("p_tenant_id" bigint, "p_invoice_id" bigint, "p_delivery_status" "text", "p_actor" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_thrift_sales_delivery_status"("p_tenant_id" bigint, "p_invoice_id" bigint, "p_delivery_status" "text", "p_actor" "text") IS 'Advance Online parcel status. First DELIVERED inserts thrift_sales_pnl_lines (shop-paid fees) and sets economics_closed_at. DELIVERED→IN_TRANSIT deletes DELIVERED PnL and clears economics_closed_at. Never changes payment_status. RETURNED requires revert RTO.';



CREATE TABLE IF NOT EXISTS "public"."customer_group_member_grants" (
    "id" bigint NOT NULL,
    "customer_group_member_id" bigint NOT NULL,
    "module_key" "text" NOT NULL,
    "action" "text" NOT NULL,
    "effect" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "customer_group_member_grants_effect_check" CHECK (("effect" = ANY (ARRAY['allow'::"text", 'deny'::"text"])))
);


ALTER TABLE "public"."customer_group_member_grants" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_customer_group_member_grant"("p_cgm_id" bigint, "p_module_key" "text", "p_action" "text", "p_effect" "text") RETURNS "public"."customer_group_member_grants"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_member public.customer_group_members;
  v_group public.customer_groups;
  v_row public.customer_group_member_grants;
begin
  select * into v_member from public.customer_group_members where id = p_cgm_id;
  if v_member.id is null then
    raise exception 'Customer group member not found';
  end if;

  select * into v_group from public.customer_groups where id = v_member.customer_group_id;
  if v_group.id is null then
    raise exception 'Customer group not found';
  end if;

  if not public.user_is_tenant_admin(v_group.tenant_id) then
    raise exception 'Unauthorized';
  end if;

  if p_effect not in ('allow', 'deny') then
    raise exception 'Invalid effect: %', p_effect;
  end if;

  if not (p_module_key = any(public.get_active_module_keys_for_tenant(v_group.tenant_id))) then
    raise exception 'Module is not active for this tenant';
  end if;

  if not exists (
    select 1 from public.module_actions
    where module_key = p_module_key and action = p_action and is_active = true
  ) then
    raise exception 'Invalid or inactive action: % for module %', p_action, p_module_key;
  end if;

  insert into public.customer_group_member_grants (
    customer_group_member_id,
    module_key,
    action,
    effect
  )
  values (
    p_cgm_id,
    p_module_key,
    p_action,
    p_effect
  )
  on conflict (customer_group_member_id, module_key, action) do update set
    effect = excluded.effect
  returning * into v_row;

  perform public.bump_tenant_permission_version(v_group.tenant_id);
  return v_row;
end;
$$;


ALTER FUNCTION "public"."upsert_customer_group_member_grant"("p_cgm_id" bigint, "p_module_key" "text", "p_action" "text", "p_effect" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."customer_group_shop_profiles" (
    "id" bigint NOT NULL,
    "tenant_id" bigint NOT NULL,
    "customer_group_id" bigint NOT NULL,
    "is_active" boolean DEFAULT true NOT NULL,
    "default_can_browse" boolean DEFAULT true NOT NULL,
    "default_can_add_to_cart" boolean DEFAULT true NOT NULL,
    "default_can_place_order" boolean DEFAULT true NOT NULL,
    "default_can_negotiate" boolean DEFAULT false NOT NULL,
    "default_can_view_quantity" boolean DEFAULT true NOT NULL,
    "default_can_set_dropship_price" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "default_can_see_buy_price" boolean DEFAULT false NOT NULL,
    "default_can_see_sell_price" boolean DEFAULT false NOT NULL,
    "default_can_see_resell_minimum_price" boolean DEFAULT true NOT NULL
);


ALTER TABLE "public"."customer_group_shop_profiles" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_customer_group_shop_profile"("p_tenant_id" bigint, "p_customer_group_id" bigint, "p_is_active" boolean, "p_default_can_browse" boolean, "p_default_can_see_buy_price" boolean, "p_default_can_see_sell_price" boolean, "p_default_can_add_to_cart" boolean, "p_default_can_place_order" boolean, "p_default_can_negotiate" boolean, "p_default_can_view_quantity" boolean, "p_default_can_set_dropship_price" boolean) RETURNS SETOF "public"."customer_group_shop_profiles"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not public.user_can_manage_shop_tenant(p_tenant_id) then
    raise exception 'not allowed';
  end if;

  return query
  insert into public.customer_group_shop_profiles (
    tenant_id,
    customer_group_id,
    is_active,
    default_can_browse,
    default_can_see_buy_price,
    default_can_see_sell_price,
    default_can_add_to_cart,
    default_can_place_order,
    default_can_negotiate,
    default_can_view_quantity,
    default_can_set_dropship_price
  )
  values (
    p_tenant_id,
    p_customer_group_id,
    p_is_active,
    p_default_can_browse,
    p_default_can_see_buy_price,
    p_default_can_see_sell_price,
    p_default_can_add_to_cart,
    p_default_can_place_order,
    p_default_can_negotiate,
    p_default_can_view_quantity,
    p_default_can_set_dropship_price
  )
  on conflict (tenant_id, customer_group_id) do update set
    is_active = excluded.is_active,
    default_can_browse = excluded.default_can_browse,
    default_can_see_buy_price = excluded.default_can_see_buy_price,
    default_can_see_sell_price = excluded.default_can_see_sell_price,
    default_can_add_to_cart = excluded.default_can_add_to_cart,
    default_can_place_order = excluded.default_can_place_order,
    default_can_negotiate = excluded.default_can_negotiate,
    default_can_view_quantity = excluded.default_can_view_quantity,
    default_can_set_dropship_price = excluded.default_can_set_dropship_price,
    updated_at = now()
  returning *;
end;
$$;


ALTER FUNCTION "public"."upsert_customer_group_shop_profile"("p_tenant_id" bigint, "p_customer_group_id" bigint, "p_is_active" boolean, "p_default_can_browse" boolean, "p_default_can_see_buy_price" boolean, "p_default_can_see_sell_price" boolean, "p_default_can_add_to_cart" boolean, "p_default_can_place_order" boolean, "p_default_can_negotiate" boolean, "p_default_can_view_quantity" boolean, "p_default_can_set_dropship_price" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_global_shipment_cost_entry"("p_shipment_id" bigint, "p_cost_type" "public"."global_shipment_cost_type", "p_amount" numeric, "p_exchange_rate" numeric DEFAULT 1.0, "p_currency_id" bigint DEFAULT NULL::bigint, "p_payment_source" "text" DEFAULT NULL::"text", "p_entity_type" "text" DEFAULT NULL::"text", "p_entity_id" bigint DEFAULT NULL::bigint, "p_allocation" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb", "p_id" bigint DEFAULT NULL::bigint) RETURNS "public"."global_shipment_cost_entries"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_ship public.global_shipments%ROWTYPE;
  v_row public.global_shipment_cost_entries%ROWTYPE;
BEGIN
  SELECT * INTO v_ship FROM public.global_shipments WHERE id = p_shipment_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'shipment not found';
  END IF;

  IF NOT public.user_can_manage_parent_tenant(v_ship.parent_tenant_id) THEN
    RAISE EXCEPTION 'not allowed';
  END IF;

  IF public.global_shipment_costs_are_locked(v_ship) THEN
    RAISE EXCEPTION 'shipment costs are locked';
  END IF;

  IF p_amount IS NULL OR p_amount < 0 THEN
    RAISE EXCEPTION 'amount must be >= 0';
  END IF;

  IF p_exchange_rate IS NULL OR p_exchange_rate <= 0 THEN
    RAISE EXCEPTION 'exchange_rate must be > 0';
  END IF;

  IF p_id IS NOT NULL THEN
    UPDATE public.global_shipment_cost_entries e
    SET
      cost_type = p_cost_type,
      amount = p_amount,
      exchange_rate = p_exchange_rate,
      currency_id = p_currency_id,
      payment_source = p_payment_source,
      entity_type = p_entity_type,
      entity_id = p_entity_id,
      allocation = p_allocation,
      metadata = coalesce(p_metadata, '{}'::jsonb),
      updated_at = now()
    WHERE e.id = p_id
      AND e.shipment_id = p_shipment_id
    RETURNING * INTO v_row;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'cost entry % not found on shipment %', p_id, p_shipment_id;
    END IF;
  ELSE
    INSERT INTO public.global_shipment_cost_entries (
      parent_tenant_id,
      shipment_id,
      cost_type,
      amount,
      currency_id,
      exchange_rate,
      payment_source,
      entity_type,
      entity_id,
      allocation,
      metadata
    ) VALUES (
      v_ship.parent_tenant_id,
      p_shipment_id,
      p_cost_type,
      p_amount,
      p_currency_id,
      p_exchange_rate,
      p_payment_source,
      p_entity_type,
      p_entity_id,
      p_allocation,
      coalesce(p_metadata, '{}'::jsonb)
    )
    RETURNING * INTO v_row;
  END IF;

  IF EXISTS (SELECT 1 FROM public.global_shipment_items WHERE shipment_id = p_shipment_id) THEN
    PERFORM public.stamp_global_shipment_landed_costs(p_shipment_id);
  END IF;

  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."upsert_global_shipment_cost_entry"("p_shipment_id" bigint, "p_cost_type" "public"."global_shipment_cost_type", "p_amount" numeric, "p_exchange_rate" numeric, "p_currency_id" bigint, "p_payment_source" "text", "p_entity_type" "text", "p_entity_id" bigint, "p_allocation" "text", "p_metadata" "jsonb", "p_id" bigint) OWNER TO "postgres";


