ALTER FUNCTION "public"."upsert_global_stock_allocation"("p_parent_tenant_id" bigint, "p_child_tenant_id" bigint, "p_stock_id" bigint, "p_quantity" integer) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."investors" (
    "id" bigint NOT NULL,
    "tenant_id" bigint NOT NULL,
    "name" "text" NOT NULL,
    "phone" "text",
    "email" "text",
    "address" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "is_active" boolean DEFAULT true NOT NULL,
    "currency_code" "text" DEFAULT 'BDT'::"text" NOT NULL,
    "notes" "text"
);


ALTER TABLE "public"."investors" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_investor_profile"("p_id" bigint, "p_tenant_id" bigint, "p_name" "text", "p_phone" "text", "p_email" "text", "p_address" "text", "p_is_active" boolean, "p_currency_code" "text", "p_notes" "text") RETURNS "public"."investors"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_row public.investors;
  v_action text;
begin
  v_action := case when p_id is null then 'create' else 'edit' end;
  if not public.membership_has_module_action(p_tenant_id, 'investor_profiles', v_action) then
    raise exception 'not allowed';
  end if;

  if p_id is not null then
    update public.investors
    set
      name = p_name,
      phone = p_phone,
      email = p_email,
      address = p_address,
      is_active = p_is_active,
      currency_code = p_currency_code,
      notes = p_notes,
      updated_at = now()
    where id = p_id and tenant_id = p_tenant_id
    returning * into v_row;
  else
    insert into public.investors (
      tenant_id, name, phone, email, address, is_active, currency_code, notes
    ) values (
      p_tenant_id, p_name, p_phone, p_email, p_address, p_is_active, p_currency_code, p_notes
    )
    returning * into v_row;
  end if;

  return v_row;
end;
$$;


ALTER FUNCTION "public"."upsert_investor_profile"("p_id" bigint, "p_tenant_id" bigint, "p_name" "text", "p_phone" "text", "p_email" "text", "p_address" "text", "p_is_active" boolean, "p_currency_code" "text", "p_notes" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."membership_grants" (
    "id" bigint NOT NULL,
    "membership_id" bigint NOT NULL,
    "module_key" "text" NOT NULL,
    "action" "text" NOT NULL,
    "effect" "text" NOT NULL,
    "created_by_email" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "membership_grants_effect_check" CHECK (("effect" = ANY (ARRAY['allow'::"text", 'deny'::"text"])))
);


ALTER TABLE "public"."membership_grants" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_membership_grant"("p_membership_id" bigint, "p_module_key" "text", "p_action" "text", "p_effect" "text") RETURNS "public"."membership_grants"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_member public.memberships;
  v_row public.membership_grants;
begin
  select * into v_member from public.memberships where id = p_membership_id;
  if v_member.id is null then
    raise exception 'Membership not found';
  end if;

  if not public.user_is_tenant_admin(v_member.tenant_id) then
    raise exception 'Unauthorized';
  end if;

  if p_effect not in ('allow', 'deny') then
    raise exception 'Invalid effect: %', p_effect;
  end if;

  if not (p_module_key = any(public.get_active_module_keys_for_tenant(v_member.tenant_id))) then
    raise exception 'Module is not active for this tenant';
  end if;

  if not exists (
    select 1 from public.module_actions
    where module_key = p_module_key and action = p_action and is_active = true
  ) then
    raise exception 'Invalid or inactive action: % for module %', p_action, p_module_key;
  end if;

  insert into public.membership_grants (
    membership_id,
    module_key,
    action,
    effect,
    created_by_email
  )
  values (
    p_membership_id,
    p_module_key,
    p_action,
    p_effect,
    public.current_user_email()
  )
  on conflict (membership_id, module_key, action) do update set
    effect = excluded.effect,
    created_by_email = excluded.created_by_email,
    updated_at = now()
  returning * into v_row;

  perform public.bump_tenant_permission_version(v_member.tenant_id);
  return v_row;
end;
$$;


ALTER FUNCTION "public"."upsert_membership_grant"("p_membership_id" bigint, "p_module_key" "text", "p_action" "text", "p_effect" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_my_notification_preferences"("p_channel_push" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_row public.user_notification_preferences;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  INSERT INTO public.user_notification_preferences AS p (
    user_id,
    channel_push,
    updated_at
  )
  VALUES (
    v_user_id,
    coalesce(p_channel_push, false),
    now()
  )
  ON CONFLICT (user_id) DO UPDATE
  SET
    channel_push = EXCLUDED.channel_push,
    updated_at = now()
  RETURNING p.* INTO v_row;

  RETURN jsonb_build_object(
    'success', true,
    'channel_push', v_row.channel_push,
    'updated_at', v_row.updated_at
  );
END;
$$;


ALTER FUNCTION "public"."upsert_my_notification_preferences"("p_channel_push" boolean) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."product_based_costing_backlog_items" (
    "id" bigint NOT NULL,
    "tenant_id" bigint NOT NULL,
    "billing_profile_id" bigint NOT NULL,
    "product_id" bigint NOT NULL,
    "open_quantity" integer NOT NULL,
    "name" "text" NOT NULL,
    "image_url" "text",
    "barcode" "text",
    "product_code" "text",
    "price_gbp" numeric,
    "product_weight" numeric,
    "package_weight" numeric,
    "note" "text",
    "last_costing_file_id" bigint,
    "last_costing_item_id" bigint,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "product_based_costing_backlog_items_open_quantity_check" CHECK (("open_quantity" > 0))
);


ALTER TABLE "public"."product_based_costing_backlog_items" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_pbc_backlog_from_item"("p_costing_item_id" bigint) RETURNS "public"."product_based_costing_backlog_items"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_item public.product_based_costing_items%ROWTYPE;
  v_file public.product_based_costing_files%ROWTYPE;
  v_prod RECORD;
  v_confirmed_qty numeric;
  v_ordered_qty numeric;
  v_open_qty numeric;
  v_backlog_row public.product_based_costing_backlog_items;
  v_tenant_id bigint;
  v_price_gbp numeric;
BEGIN
  SELECT * INTO v_item
  FROM public.product_based_costing_items
  WHERE id = p_costing_item_id;

  IF v_item.id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT * INTO v_file
  FROM public.product_based_costing_files
  WHERE id = v_item.product_based_costing_file_id;

  IF v_file.id IS NULL THEN
    RAISE EXCEPTION 'costing file % not found', v_item.product_based_costing_file_id;
  END IF;

  v_tenant_id := v_file.tenant_id;
  IF v_tenant_id IS NULL AND v_file.billing_profile_id IS NOT NULL THEN
    SELECT tenant_id INTO v_tenant_id
    FROM public.billing_profiles
    WHERE id = v_file.billing_profile_id;
  END IF;

  IF v_tenant_id IS NOT NULL AND NOT (
    public.can_admin_manage_costing_file(v_tenant_id)
    OR public.can_staff_access_costing_file(v_tenant_id)
  ) THEN
    RAISE EXCEPTION 'access denied for tenant %', v_tenant_id;
  END IF;

  IF v_tenant_id IS NULL OR v_file.billing_profile_id IS NULL OR v_item.product_id IS NULL THEN
    RETURN NULL;
  END IF;

  v_confirmed_qty := coalesce(v_item.confirmed_quantity, v_item.quantity, 0);
  v_ordered_qty := coalesce(v_item.ordered_quantity, 0);
  v_open_qty := v_confirmed_qty - v_ordered_qty;

  IF v_confirmed_qty <= 0 OR v_open_qty <= 0 THEN
    DELETE FROM public.product_based_costing_backlog_items
    WHERE tenant_id = v_tenant_id
      AND billing_profile_id = v_file.billing_profile_id
      AND product_id = v_item.product_id;
    RETURN NULL;
  END IF;

  SELECT
    p.name,
    p.image_url,
    p.list_price_amount,
    p.product_weight,
    p.package_weight,
    p.barcode,
    p.product_code,
    p.brand,
    gc.code AS list_price_currency_code
  INTO v_prod
  FROM public.products p
  LEFT JOIN public.global_currencies gc ON gc.id = p.list_price_currency_id
  WHERE p.id = v_item.product_id;

  v_price_gbp := coalesce(
    v_item.price_gbp,
    CASE
      WHEN v_prod.list_price_currency_code IS NULL OR v_prod.list_price_currency_code = 'GBP'
        THEN v_prod.list_price_amount
      ELSE NULL
    END
  );

  INSERT INTO public.product_based_costing_backlog_items (
    tenant_id,
    billing_profile_id,
    product_id,
    open_quantity,
    name,
    image_url,
    barcode,
    product_code,
    price_gbp,
    product_weight,
    package_weight,
    last_costing_file_id,
    last_costing_item_id,
    updated_at
  )
  VALUES (
    v_tenant_id,
    v_file.billing_profile_id,
    v_item.product_id,
    v_open_qty,
    coalesce(v_item.name, v_prod.name),
    coalesce(v_item.image_url, v_prod.image_url),
    coalesce(v_item.barcode, v_prod.barcode),
    coalesce(v_item.product_code, v_prod.product_code),
    v_price_gbp,
    coalesce(v_item.product_weight::numeric, v_prod.product_weight),
    coalesce(v_item.package_weight::numeric, v_prod.package_weight),
    v_file.id,
    v_item.id,
    now()
  )
  ON CONFLICT (tenant_id, billing_profile_id, product_id)
  DO UPDATE SET
    open_quantity = EXCLUDED.open_quantity,
    name = EXCLUDED.name,
    image_url = EXCLUDED.image_url,
    barcode = EXCLUDED.barcode,
    product_code = EXCLUDED.product_code,
    price_gbp = EXCLUDED.price_gbp,
    product_weight = EXCLUDED.product_weight,
    package_weight = EXCLUDED.package_weight,
    last_costing_file_id = EXCLUDED.last_costing_file_id,
    last_costing_item_id = EXCLUDED.last_costing_item_id,
    updated_at = now()
  RETURNING * INTO v_backlog_row;

  RETURN v_backlog_row;
END;
$$;


ALTER FUNCTION "public"."upsert_pbc_backlog_from_item"("p_costing_item_id" bigint) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."preorder_demand" (
    "id" bigint NOT NULL,
    "tenant_id" bigint NOT NULL,
    "source_type" "public"."preorder_demand_source_type" NOT NULL,
    "source_id" bigint NOT NULL,
    "vendor_id" bigint,
    "placed_quantity" integer DEFAULT 0 NOT NULL,
    "delivered_quantity" integer DEFAULT 0 NOT NULL,
    "stock_picks" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "notes" "text",
    "updated_by_user_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "preorder_demand_delivered_quantity_check" CHECK (("delivered_quantity" >= 0)),
    CONSTRAINT "preorder_demand_placed_quantity_check" CHECK (("placed_quantity" >= 0)),
    CONSTRAINT "preorder_demand_stock_picks_is_array" CHECK (("jsonb_typeof"("stock_picks") = 'array'::"text"))
);


ALTER TABLE "public"."preorder_demand" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_preorder_demand"("p_tenant_id" bigint, "p_source_type" "public"."preorder_demand_source_type", "p_source_id" bigint, "p_vendor_id" bigint DEFAULT NULL::bigint, "p_placed_quantity" integer DEFAULT NULL::integer, "p_stock_picks" "jsonb" DEFAULT NULL::"jsonb", "p_notes" "text" DEFAULT NULL::"text") RETURNS "public"."preorder_demand"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_row public.preorder_demand;
  v_line_tenant_id bigint;
  v_doc_status text;
  v_open_qty integer;
  v_delivered integer;
  v_placed integer;
begin
  if p_tenant_id is null then
    raise exception 'tenant_id is required';
  end if;
  if p_source_id is null then
    raise exception 'source_id is required';
  end if;

  select g.tenant_id, g.open_qty, g.document_status
  into v_line_tenant_id, v_open_qty, v_doc_status
  from public.get_procurement_demand_open_qty(p_source_type, p_source_id) g;

  if v_line_tenant_id is null then
    raise exception 'demand line not found';
  end if;

  if not public.can_access_preorder_demand_tenant(p_tenant_id)
    and not public.can_access_preorder_demand_tenant(v_line_tenant_id) then
    raise exception 'access denied';
  end if;

  if v_line_tenant_id <> p_tenant_id then
    if not exists (
      select 1 from public.tenants t
      where t.id = v_line_tenant_id
        and t.parent_id = p_tenant_id
        and public.user_can_manage_parent_tenant(p_tenant_id)
    ) then
      raise exception 'tenant mismatch for demand line';
    end if;
  end if;

  if v_doc_status not in ('procuring', 'ready_for_shipment') then
    raise exception 'document is not open for preorder demand updates';
  end if;

  if p_placed_quantity is not null and v_doc_status <> 'procuring' then
    raise exception 'placed_quantity can only be updated while procuring';
  end if;

  if p_stock_picks is not null and v_doc_status <> 'procuring' then
    raise exception 'stock_picks can only be updated while procuring';
  end if;

  if p_placed_quantity is not null and coalesce(p_placed_quantity, 0) < 0 then
    raise exception 'placed_quantity cannot be negative';
  end if;

  if p_stock_picks is not null and not public.validate_preorder_stock_picks(p_stock_picks) then
    raise exception 'invalid stock_picks payload';
  end if;

  v_delivered := case
    when p_stock_picks is not null then public.sum_preorder_stock_picks(p_stock_picks)
    else null
  end;

  select pd.* into v_row
  from public.preorder_demand pd
  where pd.source_type = p_source_type
    and pd.source_id = p_source_id;

  if found then
    v_placed := coalesce(p_placed_quantity, v_row.placed_quantity, 0);
  else
    v_placed := coalesce(p_placed_quantity, 0);
  end if;

  if v_delivered is not null and v_delivered > coalesce(v_open_qty, 0) then
    raise exception 'delivered_quantity cannot exceed need quantity';
  end if;

  insert into public.preorder_demand (
    tenant_id,
    source_type,
    source_id,
    vendor_id,
    placed_quantity,
    delivered_quantity,
    stock_picks,
    notes,
    updated_by_user_id
  ) values (
    v_line_tenant_id,
    p_source_type,
    p_source_id,
    coalesce(p_vendor_id, case when found then v_row.vendor_id else null end),
    v_placed,
    coalesce(v_delivered, case when found then v_row.delivered_quantity else 0 end, 0),
    coalesce(p_stock_picks, case when found then v_row.stock_picks else '[]'::jsonb end, '[]'::jsonb),
    coalesce(nullif(trim(p_notes), ''), case when found then v_row.notes else null end),
    auth.uid()
  )
  on conflict (source_type, source_id) do update set
    vendor_id = case when p_vendor_id is not null then p_vendor_id else preorder_demand.vendor_id end,
    placed_quantity = case when p_placed_quantity is not null then p_placed_quantity else preorder_demand.placed_quantity end,
    delivered_quantity = case when v_delivered is not null then v_delivered else preorder_demand.delivered_quantity end,
    stock_picks = case when p_stock_picks is not null then p_stock_picks else preorder_demand.stock_picks end,
    notes = case when p_notes is not null then nullif(trim(p_notes), '') else preorder_demand.notes end,
    updated_by_user_id = auth.uid(),
    updated_at = now()
  returning * into v_row;

  return v_row;
end;
$$;


ALTER FUNCTION "public"."upsert_preorder_demand"("p_tenant_id" bigint, "p_source_type" "public"."preorder_demand_source_type", "p_source_id" bigint, "p_vendor_id" bigint, "p_placed_quantity" integer, "p_stock_picks" "jsonb", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_recipient_profile_and_address"("p_tenant_id" bigint, "p_name" "text", "p_phone" "text", "p_phone_secondary" "text" DEFAULT NULL::"text", "p_address" "text" DEFAULT NULL::"text", "p_district" "text" DEFAULT NULL::"text", "p_thana" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  return public.upsert_recipient_profile_by_phone(
    p_tenant_id => p_tenant_id,
    p_name => p_name,
    p_phone => p_phone,
    p_secondary_phone => p_phone_secondary,
    p_address => p_address,
    p_district => p_district,
    p_thana => p_thana
  );
end;
$$;


ALTER FUNCTION "public"."upsert_recipient_profile_and_address"("p_tenant_id" bigint, "p_name" "text", "p_phone" "text", "p_phone_secondary" "text", "p_address" "text", "p_district" "text", "p_thana" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_recipient_profile_by_phone"("p_tenant_id" bigint, "p_name" "text", "p_phone" "text", "p_secondary_phone" "text" DEFAULT NULL::"text", "p_address" "text" DEFAULT NULL::"text", "p_district" "text" DEFAULT NULL::"text", "p_thana" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_phone text;
  v_secondary text;
  v_name text;
  v_address text;
  v_district text;
  v_thana text;
  v_entry jsonb;
  v_addresses jsonb;
  v_next jsonb := '[]'::jsonb;
  v_elem jsonb;
  v_matched boolean := false;
  v_row public.recipient_profiles%rowtype;
  v_parent_id bigint;
  v_insert_tenant_id bigint;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  if not (
    public.has_active_tenant_membership(p_tenant_id)
    or public.user_can_manage_parent_tenant(p_tenant_id)
    or public.current_customer_group_id(p_tenant_id) is not null
  ) then
    raise exception 'access denied';
  end if;

  v_phone := public.normalize_bd_mobile(p_phone);
  v_name := nullif(trim(coalesce(p_name, '')), '');
  if v_name is null then
    raise exception 'Recipient name is required';
  end if;
  v_address := nullif(trim(coalesce(p_address, '')), '');
  if v_address is null then
    raise exception 'Recipient address is required';
  end if;
  v_district := nullif(trim(coalesce(p_district, '')), '');
  v_thana := nullif(trim(coalesce(p_thana, '')), '');

  if nullif(trim(coalesce(p_secondary_phone, '')), '') is not null then
    begin
      v_secondary := public.normalize_bd_mobile(p_secondary_phone);
    exception when others then
      v_secondary := nullif(trim(p_secondary_phone), '');
    end;
  else
    v_secondary := null;
  end if;

  v_entry := jsonb_build_object(
    'id', gen_random_uuid()::text,
    'line', v_address,
    'district', v_district,
    'thana', v_thana,
    'is_default', true,
    'updated_at', now()
  );

  v_parent_id := public.resolve_parent_tenant_id(p_tenant_id);

  if p_tenant_id = v_parent_id then
    v_insert_tenant_id := null;
  else
    v_insert_tenant_id := p_tenant_id;
  end if;

  select * into v_row
  from public.recipient_profiles
  where (parent_tenant_id = v_parent_id or (parent_tenant_id is null and tenant_id = v_parent_id) or tenant_id = p_tenant_id)
    and phone = v_phone
  order by (parent_tenant_id = v_parent_id) desc, updated_at desc
  limit 1
  for update;

  if v_row.id is null then
    insert into public.recipient_profiles (
      tenant_id, parent_tenant_id, name, phone, secondary_phone, address, district, thana, addresses
    )
    values (
      v_insert_tenant_id, v_parent_id, v_name, v_phone, v_secondary, v_address, v_district, v_thana,
      jsonb_build_array(v_entry)
    )
    returning * into v_row;
  else
    v_addresses := coalesce(v_row.addresses, '[]'::jsonb);
    v_next := '[]'::jsonb;
    v_matched := false;

    for v_elem in select * from jsonb_array_elements(v_addresses)
    loop
      if v_elem->>'line' = v_address then
        v_matched := true;
        v_next := v_next || jsonb_build_array(
          jsonb_build_object(
            'id', coalesce(v_elem->>'id', gen_random_uuid()::text),
            'line', v_address,
            'district', v_district,
            'thana', v_thana,
            'is_default', true,
            'updated_at', now()
          )
        );
      else
        v_next := v_next || jsonb_build_array(
          jsonb_set(v_elem, '{is_default}', 'false'::jsonb)
        );
      end if;
    end loop;

    if not v_matched then
      v_next := v_next || jsonb_build_array(v_entry);
    end if;

    update public.recipient_profiles
    set
      name = v_name,
      secondary_phone = coalesce(v_secondary, secondary_phone),
      address = v_address,
      district = v_district,
      thana = v_thana,
      addresses = v_next,
      parent_tenant_id = coalesce(parent_tenant_id, v_parent_id),
      updated_at = now()
    where id = v_row.id
    returning * into v_row;
  end if;

  return jsonb_build_object(
    'id', v_row.id,
    'name', v_row.name,
    'phone', v_row.phone,
    'secondary_phone', v_row.secondary_phone,
    'address', v_row.address,
    'district', v_row.district,
    'thana', v_row.thana,
    'addresses', v_row.addresses,
    'tenant_id', v_row.tenant_id,
    'parent_tenant_id', v_row.parent_tenant_id,
    'created_at', v_row.created_at,
    'updated_at', v_row.updated_at
  );
end;
$$;


ALTER FUNCTION "public"."upsert_recipient_profile_by_phone"("p_tenant_id" bigint, "p_name" "text", "p_phone" "text", "p_secondary_phone" "text", "p_address" "text", "p_district" "text", "p_thana" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_shipment_investment"("p_id" bigint, "p_tenant_id" bigint, "p_global_shipment_id" bigint, "p_investor_id" bigint, "p_cost_share_pct" numeric) RETURNS "public"."shipment_investments"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_total_cost_share numeric;
  v_row public.shipment_investments;
  v_action text;
begin
  v_action := case when p_id is null then 'create' else 'edit' end;
  if not public.membership_has_module_action(p_tenant_id, 'investor_shipment_share', v_action) then
    raise exception 'not allowed';
  end if;

  if p_cost_share_pct < 0 or p_cost_share_pct > 100 then
    raise exception 'cost share percentage must be between 0 and 100';
  end if;

  select coalesce(sum(cost_share_pct), 0) into v_total_cost_share
  from public.shipment_investments
  where global_shipment_id = p_global_shipment_id
    and status = 'active'
    and (p_id is null or id <> p_id);

  if v_total_cost_share + p_cost_share_pct > 100 then
    raise exception 'total cost share percentage cannot exceed 100%%';
  end if;

  if p_id is not null then
    update public.shipment_investments
    set
      cost_share_pct = p_cost_share_pct,
      updated_at = now()
    where id = p_id and tenant_id = p_tenant_id
    returning * into v_row;
  else
    insert into public.shipment_investments (
      tenant_id, global_shipment_id, investor_id, cost_share_pct, status
    ) values (
      p_tenant_id, p_global_shipment_id, p_investor_id, p_cost_share_pct, 'active'
    )
    returning * into v_row;
  end if;

  perform public.refresh_shipment_investor_profits(p_global_shipment_id);

  select * into v_row from public.shipment_investments where id = v_row.id;

  return v_row;
end;
$$;


ALTER FUNCTION "public"."upsert_shipment_investment"("p_id" bigint, "p_tenant_id" bigint, "p_global_shipment_id" bigint, "p_investor_id" bigint, "p_cost_share_pct" numeric) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."shops" (
    "id" bigint NOT NULL,
    "tenant_id" bigint NOT NULL,
    "name" "text" NOT NULL,
    "slug" "text" NOT NULL,
    "shop_type" "public"."shop_type_enum" NOT NULL,
    "vendor_code" "text",
    "order_mode" "public"."shop_order_mode_enum" NOT NULL,
    "is_negotiable" boolean DEFAULT false NOT NULL,
    "show_stock_quantity" boolean DEFAULT true NOT NULL,
    "default_currency_id" bigint,
    "global_stock_type_id" bigint,
    "is_active" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "buy_currency_id" bigint NOT NULL,
    "sell_currency_id" bigint NOT NULL,
    "pricing_method" "text" NOT NULL,
    "markup_percentage" numeric(5,2),
    "quantity_display_mode" "text" NOT NULL,
    "vendor_filters" "jsonb",
    "deleted_at" timestamp with time zone,
    "deleted_by" "text",
    "allow_delivery" boolean DEFAULT false NOT NULL,
    "default_print_charge_amount" numeric(12,2) DEFAULT 0 NOT NULL,
    "default_packing_charge_amount" numeric(12,2) DEFAULT 0 NOT NULL,
    "deduct_charges_from_margin" boolean DEFAULT false NOT NULL,
    "deduct_print_from_margin" boolean DEFAULT false NOT NULL,
    "deduct_packing_from_margin" boolean DEFAULT false NOT NULL,
    "deduct_return_charge_from_middle_man" boolean DEFAULT true,
    "description" "text",
    "category_ids" bigint[] DEFAULT '{}'::bigint[],
    "min_available_units" integer DEFAULT 0 NOT NULL,
    "parent_tenant_id" bigint,
    CONSTRAINT "shops_dropship_not_negotiable" CHECK ((("shop_type" <> 'dropship'::"public"."shop_type_enum") OR ("is_negotiable" = false))),
    CONSTRAINT "shops_min_available_units_check" CHECK (("min_available_units" >= 0)),
    CONSTRAINT "shops_sell_currency_match" CHECK (("sell_currency_id" = "default_currency_id")),
    CONSTRAINT "shops_vendor_catalog_requires_vendor_code" CHECK ((("shop_type" <> 'vendor_catalog'::"public"."shop_type_enum") OR ("is_active" = false) OR ("vendor_code" IS NOT NULL) OR (("vendor_filters" IS NOT NULL) AND ("jsonb_array_length"("vendor_filters") > 0))))
);


ALTER TABLE "public"."shops" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_shop"("p_tenant_id" bigint, "p_name" "text", "p_slug" "text", "p_order_mode" "public"."shop_order_mode_enum", "p_is_negotiable" boolean, "p_show_stock_quantity" boolean, "p_is_active" boolean, "p_shop_type" "public"."shop_type_enum" DEFAULT NULL::"public"."shop_type_enum", "p_vendor_code" "text" DEFAULT NULL::"text", "p_id" bigint DEFAULT NULL::bigint, "p_default_currency_id" bigint DEFAULT NULL::bigint, "p_global_stock_type_id" bigint DEFAULT NULL::bigint, "p_allow_delivery" boolean DEFAULT false, "p_buy_currency_id" bigint DEFAULT NULL::bigint, "p_sell_currency_id" bigint DEFAULT NULL::bigint, "p_pricing_method" "text" DEFAULT NULL::"text", "p_markup_percentage" numeric DEFAULT 0, "p_quantity_display_mode" "text" DEFAULT NULL::"text", "p_default_print_charge_amount" numeric DEFAULT 0, "p_default_packing_charge_amount" numeric DEFAULT 0, "p_deduct_charges_from_margin" boolean DEFAULT false, "p_vendor_filters" "jsonb" DEFAULT NULL::"jsonb", "p_deduct_print_from_margin" boolean DEFAULT false, "p_deduct_packing_from_margin" boolean DEFAULT false, "p_description" "text" DEFAULT NULL::"text", "p_category_ids" bigint[] DEFAULT '{}'::bigint[], "p_min_available_units" integer DEFAULT 0) RETURNS SETOF "public"."shops"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_shop_type public.shop_type_enum;
  v_result    public.shops;
  v_vendor_code text;
begin
  if not public.user_can_manage_shop_tenant(p_tenant_id) then
    raise exception 'not allowed';
  end if;

  if p_pricing_method is not null and p_pricing_method not in ('direct_cost', 'markup') then
    raise exception 'invalid pricing method';
  end if;
  if p_quantity_display_mode is not null and p_quantity_display_mode not in ('original', 'custom_override') then
    raise exception 'invalid quantity display mode';
  end if;
  if p_markup_percentage < 0 then
    raise exception 'markup percentage must be non-negative';
  end if;
  if coalesce(p_min_available_units, 0) < 0 then
    raise exception 'min_available_units must be non-negative';
  end if;

  v_vendor_code := nullif(trim(coalesce(p_vendor_code, '')), '');
  if v_vendor_code is null
     and p_vendor_filters is not null
     and jsonb_typeof(p_vendor_filters) = 'array'
     and jsonb_array_length(p_vendor_filters) > 0 then
    v_vendor_code := nullif(trim(coalesce(p_vendor_filters->0->>'vendor_code', '')), '');
  end if;

  if p_id is null then
    if p_shop_type is null then
      raise exception 'shop_type is required when creating a shop';
    end if;
    if p_shop_type = 'dropship' and p_is_negotiable then
      raise exception 'dropship shops cannot be negotiable';
    end if;

    insert into public.shops (
      tenant_id,
      name,
      slug,
      shop_type,
      vendor_code,
      order_mode,
      is_negotiable,
      show_stock_quantity,
      default_currency_id,
      global_stock_type_id,
      is_active,
      allow_delivery,
      buy_currency_id,
      sell_currency_id,
      pricing_method,
      markup_percentage,
      quantity_display_mode,
      default_print_charge_amount,
      default_packing_charge_amount,
      deduct_charges_from_margin,
      vendor_filters,
      deduct_print_from_margin,
      deduct_packing_from_margin,
      description,
      category_ids,
      min_available_units
    )
    values (
      p_tenant_id,
      trim(p_name),
      lower(trim(p_slug)),
      p_shop_type,
      v_vendor_code,
      p_order_mode,
      p_is_negotiable,
      p_show_stock_quantity,
      coalesce(p_default_currency_id, p_sell_currency_id),
      p_global_stock_type_id,
      p_is_active,
      p_allow_delivery,
      coalesce(p_buy_currency_id, p_default_currency_id, (select id from public.global_currencies where code = 'BDT' limit 1)),
      coalesce(p_sell_currency_id, p_default_currency_id, (select id from public.global_currencies where code = 'BDT' limit 1)),
      coalesce(p_pricing_method, 'direct_cost'),
      coalesce(p_markup_percentage, 0),
      coalesce(p_quantity_display_mode, 'original'),
      coalesce(p_default_print_charge_amount, 0),
      coalesce(p_default_packing_charge_amount, 0),
      coalesce(p_deduct_charges_from_margin, false),
      p_vendor_filters,
      coalesce(p_deduct_print_from_margin, false),
      coalesce(p_deduct_packing_from_margin, false),
      trim(p_description),
      coalesce(p_category_ids, '{}'),
      coalesce(p_min_available_units, 0)
    )
    returning * into v_result;
  else
    select shop_type into v_shop_type
    from public.shops
    where id = p_id and tenant_id = p_tenant_id
      and deleted_at is null;

    if v_shop_type is null then
      raise exception 'shop not found';
    end if;
    if v_shop_type = 'dropship' and p_is_negotiable then
      raise exception 'dropship shops cannot be negotiable';
    end if;

    update public.shops
    set
      name                            = trim(p_name),
      slug                            = lower(trim(p_slug)),
      order_mode                      = p_order_mode,
      is_negotiable                   = p_is_negotiable,
      show_stock_quantity             = p_show_stock_quantity,
      default_currency_id             = coalesce(p_default_currency_id, p_sell_currency_id, default_currency_id),
      global_stock_type_id            = p_global_stock_type_id,
      is_active                       = p_is_active,
      allow_delivery                  = p_allow_delivery,
      buy_currency_id                 = coalesce(p_buy_currency_id, buy_currency_id),
      sell_currency_id                = coalesce(p_sell_currency_id, p_default_currency_id, sell_currency_id),
      pricing_method                  = coalesce(p_pricing_method, pricing_method),
      markup_percentage               = coalesce(p_markup_percentage, markup_percentage),
      quantity_display_mode           = coalesce(p_quantity_display_mode, quantity_display_mode),
      default_print_charge_amount     = coalesce(p_default_print_charge_amount, default_print_charge_amount),
      default_packing_charge_amount   = coalesce(p_default_packing_charge_amount, default_packing_charge_amount),
      deduct_charges_from_margin      = coalesce(p_deduct_charges_from_margin, deduct_charges_from_margin),
      vendor_code                     = case
                                          when p_vendor_code is not null or p_vendor_filters is not null
                                            then v_vendor_code
                                          else vendor_code
                                        end,
      vendor_filters                  = coalesce(p_vendor_filters, vendor_filters),
      deduct_print_from_margin        = coalesce(p_deduct_print_from_margin, deduct_print_from_margin),
      deduct_packing_from_margin      = coalesce(p_deduct_packing_from_margin, deduct_packing_from_margin),
      description                     = trim(p_description),
      category_ids                    = coalesce(p_category_ids, '{}'),
      min_available_units             = coalesce(p_min_available_units, min_available_units),
      updated_at                      = now()
    where id = p_id
      and tenant_id = p_tenant_id
      and deleted_at is null
    returning * into v_result;

    if v_result is null then
      raise exception 'shop not found or update failed';
    end if;
  end if;

  return next v_result;
end;
$$;


ALTER FUNCTION "public"."upsert_shop"("p_tenant_id" bigint, "p_name" "text", "p_slug" "text", "p_order_mode" "public"."shop_order_mode_enum", "p_is_negotiable" boolean, "p_show_stock_quantity" boolean, "p_is_active" boolean, "p_shop_type" "public"."shop_type_enum", "p_vendor_code" "text", "p_id" bigint, "p_default_currency_id" bigint, "p_global_stock_type_id" bigint, "p_allow_delivery" boolean, "p_buy_currency_id" bigint, "p_sell_currency_id" bigint, "p_pricing_method" "text", "p_markup_percentage" numeric, "p_quantity_display_mode" "text", "p_default_print_charge_amount" numeric, "p_default_packing_charge_amount" numeric, "p_deduct_charges_from_margin" boolean, "p_vendor_filters" "jsonb", "p_deduct_print_from_margin" boolean, "p_deduct_packing_from_margin" boolean, "p_description" "text", "p_category_ids" bigint[], "p_min_available_units" integer) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."shop_customer_group_access" (
    "id" bigint NOT NULL,
    "shop_id" bigint NOT NULL,
    "customer_group_id" bigint NOT NULL,
    "status" boolean DEFAULT true NOT NULL,
    "can_browse" boolean,
    "can_add_to_cart" boolean,
    "can_place_order" boolean,
    "can_negotiate" boolean,
    "can_view_quantity" boolean,
    "can_set_dropship_price" boolean,
    "price_tier_code" "text",
    "credit_limit_amount" numeric(12,4) DEFAULT NULL::numeric,
    "credit_limit_currency_id" bigint,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "can_see_buy_price" boolean,
    "can_see_sell_price" boolean,
    "can_see_resell_minimum_price" boolean,
    CONSTRAINT "shop_customer_group_access_credit_limit_currency" CHECK ((("credit_limit_amount" IS NULL) = ("credit_limit_currency_id" IS NULL)))
);


ALTER TABLE "public"."shop_customer_group_access" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_shop_customer_group_access"("p_shop_id" bigint, "p_customer_group_id" bigint, "p_status" boolean, "p_can_browse" boolean DEFAULT NULL::boolean, "p_can_see_buy_price" boolean DEFAULT NULL::boolean, "p_can_see_sell_price" boolean DEFAULT NULL::boolean, "p_can_add_to_cart" boolean DEFAULT NULL::boolean, "p_can_place_order" boolean DEFAULT NULL::boolean, "p_can_negotiate" boolean DEFAULT NULL::boolean, "p_can_view_quantity" boolean DEFAULT NULL::boolean, "p_can_set_dropship_price" boolean DEFAULT NULL::boolean, "p_price_tier_code" "text" DEFAULT NULL::"text", "p_credit_limit_amount" numeric DEFAULT NULL::numeric, "p_credit_limit_currency_id" bigint DEFAULT NULL::bigint, "p_can_see_resell_minimum_price" boolean DEFAULT NULL::boolean) RETURNS SETOF "public"."shop_customer_group_access"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_tenant_id bigint;
begin
  select tenant_id into v_tenant_id
  from public.shops
  where id = p_shop_id;

  if v_tenant_id is null then
    raise exception 'shop not found';
  end if;

  if not public.user_can_manage_shop_tenant(v_tenant_id)
     and not public.user_can_manage_shop_tenant(public.resolve_parent_tenant_id(v_tenant_id))
     and not public.is_superadmin() then
    raise exception 'not allowed';
  end if;

  if (p_credit_limit_amount is null) <> (p_credit_limit_currency_id is null) then
    raise exception 'both credit_limit_amount and credit_limit_currency_id must be provided together or be null';
  end if;

  return query
  insert into public.shop_customer_group_access (
    shop_id,
    customer_group_id,
    status,
    can_browse,
    can_see_buy_price,
    can_see_sell_price,
    can_see_resell_minimum_price,
    can_add_to_cart,
    can_place_order,
    can_negotiate,
    can_view_quantity,
    can_set_dropship_price,
    price_tier_code,
    credit_limit_amount,
    credit_limit_currency_id
  )
  values (
    p_shop_id,
    p_customer_group_id,
    p_status,
    p_can_browse,
    p_can_see_buy_price,
