CREATE TABLE IF NOT EXISTS "public"."shop_product_listings" (
    "id" bigint NOT NULL,
    "tenant_id" bigint NOT NULL,
    "shop_id" bigint NOT NULL,
    "global_stock_allocation_id" bigint,
    "global_stock_id" bigint,
    "product_id" bigint NOT NULL,
    "sell_price_amount" numeric(12,4) NOT NULL,
    "sell_price_currency_id" bigint NOT NULL,
    "minimum_sell_price_amount" numeric(12,4) DEFAULT NULL::numeric,
    "minimum_sell_price_currency_id" bigint,
    "show_quantity" boolean,
    "display_quantity_override" integer,
    "is_active" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "is_price_locked" boolean DEFAULT false NOT NULL,
    "is_quantity_locked" boolean DEFAULT false NOT NULL,
    "quantity_override_type" "text" DEFAULT 'absolute'::"text" NOT NULL,
    "grade_tag_id" bigint,
    CONSTRAINT "shop_product_listings_min_sell_currency" CHECK ((("minimum_sell_price_amount" IS NULL) = ("minimum_sell_price_currency_id" IS NULL))),
    CONSTRAINT "shop_product_listings_qty_override_type_check" CHECK (("quantity_override_type" = ANY (ARRAY['absolute'::"text", 'relative'::"text"])))
);


ALTER TABLE "public"."shop_product_listings" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_shop_product_listing"("p_tenant_id" bigint, "p_shop_id" bigint, "p_global_stock_allocation_id" bigint, "p_sell_price_amount" numeric, "p_sell_price_currency_id" bigint, "p_minimum_sell_price_amount" numeric DEFAULT NULL::numeric, "p_minimum_sell_price_currency_id" bigint DEFAULT NULL::bigint, "p_show_quantity" boolean DEFAULT NULL::boolean, "p_display_quantity_override" integer DEFAULT NULL::integer, "p_is_active" boolean DEFAULT true, "p_id" bigint DEFAULT NULL::bigint) RETURNS SETOF "public"."shop_product_listings"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_global_stock_id bigint;
  v_product_id bigint;
begin
  -- Caller must be admin/staff of this tenant
  if not public.user_can_manage_shop_tenant(p_tenant_id) then
    raise exception 'not allowed';
  end if;

  -- Resolve denormalized IDs
  select gsa.stock_id, gsi.product_id
  into v_global_stock_id, v_product_id
  from public.global_stock_allocations gsa
  join public.global_stocks gs on gs.id = gsa.stock_id
  join public.global_shipment_items gsi on gsi.id = gs.shipment_item_id
  where gsa.id = p_global_stock_allocation_id;

  if v_global_stock_id is null or v_product_id is null then
    raise exception 'invalid global stock allocation';
  end if;

  -- Dropship dual money constraint
  if (p_minimum_sell_price_amount is null) <> (p_minimum_sell_price_currency_id is null) then
    raise exception 'both minimum_sell_price_amount and minimum_sell_price_currency_id must be provided together or be null';
  end if;

  return query
  insert into public.shop_product_listings (
    id,
    tenant_id,
    shop_id,
    global_stock_allocation_id,
    global_stock_id,
    product_id,
    sell_price_amount,
    sell_price_currency_id,
    minimum_sell_price_amount,
    minimum_sell_price_currency_id,
    show_quantity,
    display_quantity_override,
    is_active
  )
  overriding system value
  values (
    coalesce(p_id, nextval(pg_get_serial_sequence('public.shop_product_listings', 'id'))),
    p_tenant_id,
    p_shop_id,
    p_global_stock_allocation_id,
    v_global_stock_id,
    v_product_id,
    p_sell_price_amount,
    p_sell_price_currency_id,
    p_minimum_sell_price_amount,
    p_minimum_sell_price_currency_id,
    p_show_quantity,
    p_display_quantity_override,
    p_is_active
  )
  on conflict (shop_id, global_stock_allocation_id) do update set
    sell_price_amount = excluded.sell_price_amount,
    sell_price_currency_id = excluded.sell_price_currency_id,
    minimum_sell_price_amount = excluded.minimum_sell_price_amount,
    minimum_sell_price_currency_id = excluded.minimum_sell_price_currency_id,
    show_quantity = excluded.show_quantity,
    display_quantity_override = excluded.display_quantity_override,
    is_active = excluded.is_active,
    updated_at = now()
  returning *;
end;
$$;


ALTER FUNCTION "public"."upsert_shop_product_listing"("p_tenant_id" bigint, "p_shop_id" bigint, "p_global_stock_allocation_id" bigint, "p_sell_price_amount" numeric, "p_sell_price_currency_id" bigint, "p_minimum_sell_price_amount" numeric, "p_minimum_sell_price_currency_id" bigint, "p_show_quantity" boolean, "p_display_quantity_override" integer, "p_is_active" boolean, "p_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_shop_product_listing"("p_tenant_id" bigint, "p_shop_id" bigint, "p_global_stock_allocation_id" bigint, "p_sell_price_amount" numeric, "p_sell_price_currency_id" bigint, "p_minimum_sell_price_amount" numeric DEFAULT NULL::numeric, "p_minimum_sell_price_currency_id" bigint DEFAULT NULL::bigint, "p_show_quantity" boolean DEFAULT NULL::boolean, "p_display_quantity_override" integer DEFAULT NULL::integer, "p_is_active" boolean DEFAULT true, "p_id" bigint DEFAULT NULL::bigint, "p_is_price_locked" boolean DEFAULT NULL::boolean, "p_is_quantity_locked" boolean DEFAULT NULL::boolean, "p_quantity_override_type" "text" DEFAULT NULL::"text") RETURNS SETOF "public"."shop_product_listings"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_product_id bigint;
  v_global_stock_id bigint;
  v_existing record;
  v_price_locked boolean;
  v_qty_locked boolean;
  v_override_type text;
begin
  if not public.user_can_manage_shop_tenant(p_tenant_id) then
    raise exception 'not allowed';
  end if;

  -- Resolve stock & product id from allocation by joining global_stocks and global_shipment_items
  select gsa.stock_id, gsi.product_id
  into v_global_stock_id, v_product_id
  from public.global_stock_allocations gsa
  join public.global_stocks gs on gs.id = gsa.stock_id
  join public.global_shipment_items gsi on gsi.id = gs.shipment_item_id
  where gsa.id = p_global_stock_allocation_id;

  if v_global_stock_id is null then
    raise exception 'allocation not found';
  end if;

  if p_id is not null then
    select * into v_existing from public.shop_product_listings where id = p_id;
  else
    select * into v_existing from public.shop_product_listings
    where shop_id = p_shop_id and global_stock_allocation_id = p_global_stock_allocation_id;
  end if;

  v_price_locked := coalesce(p_is_price_locked, v_existing.is_price_locked, false);
  v_qty_locked := coalesce(p_is_quantity_locked, v_existing.is_quantity_locked, false);
  v_override_type := coalesce(p_quantity_override_type, v_existing.quantity_override_type, 'absolute');

  if v_existing.id is not null then
    return query
    update public.shop_product_listings
    set
      sell_price_amount = p_sell_price_amount,
      sell_price_currency_id = p_sell_price_currency_id,
      minimum_sell_price_amount = p_minimum_sell_price_amount,
      minimum_sell_price_currency_id = p_minimum_sell_price_currency_id,
      show_quantity = p_show_quantity,
      display_quantity_override = p_display_quantity_override,
      is_active = p_is_active,
      is_price_locked = v_price_locked,
      is_quantity_locked = v_qty_locked,
      quantity_override_type = v_override_type,
      updated_at = now()
    where id = v_existing.id
    returning *;
  else
    return query
    insert into public.shop_product_listings (
      tenant_id,
      shop_id,
      global_stock_allocation_id,
      global_stock_id,
      product_id,
      sell_price_amount,
      sell_price_currency_id,
      minimum_sell_price_amount,
      minimum_sell_price_currency_id,
      show_quantity,
      display_quantity_override,
      is_active,
      is_price_locked,
      is_quantity_locked,
      quantity_override_type
    )
    values (
      p_tenant_id,
      p_shop_id,
      p_global_stock_allocation_id,
      v_global_stock_id,
      v_product_id,
      p_sell_price_amount,
      p_sell_price_currency_id,
      p_minimum_sell_price_amount,
      p_minimum_sell_price_currency_id,
      p_show_quantity,
      p_display_quantity_override,
      p_is_active,
      v_price_locked,
      v_qty_locked,
      v_override_type
    )
    returning *;
  end if;
end;
$$;


ALTER FUNCTION "public"."upsert_shop_product_listing"("p_tenant_id" bigint, "p_shop_id" bigint, "p_global_stock_allocation_id" bigint, "p_sell_price_amount" numeric, "p_sell_price_currency_id" bigint, "p_minimum_sell_price_amount" numeric, "p_minimum_sell_price_currency_id" bigint, "p_show_quantity" boolean, "p_display_quantity_override" integer, "p_is_active" boolean, "p_id" bigint, "p_is_price_locked" boolean, "p_is_quantity_locked" boolean, "p_quantity_override_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_shop_product_listing"("p_tenant_id" bigint, "p_shop_id" bigint, "p_global_stock_allocation_id" bigint DEFAULT NULL::bigint, "p_sell_price_amount" numeric DEFAULT NULL::numeric, "p_sell_price_currency_id" bigint DEFAULT NULL::bigint, "p_minimum_sell_price_amount" numeric DEFAULT NULL::numeric, "p_minimum_sell_price_currency_id" bigint DEFAULT NULL::bigint, "p_show_quantity" boolean DEFAULT NULL::boolean, "p_display_quantity_override" integer DEFAULT NULL::integer, "p_is_active" boolean DEFAULT true, "p_id" bigint DEFAULT NULL::bigint, "p_is_price_locked" boolean DEFAULT NULL::boolean, "p_is_quantity_locked" boolean DEFAULT NULL::boolean, "p_quantity_override_type" "text" DEFAULT NULL::"text", "p_global_stock_id" bigint DEFAULT NULL::bigint) RETURNS SETOF "public"."shop_product_listings"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_product_id bigint;
  v_target_stock_id bigint;
  v_existing record;
  v_price_locked boolean;
  v_qty_locked boolean;
  v_override_type text;
begin
  if not public.user_can_manage_shop_tenant(p_tenant_id)
     and not public.user_can_manage_shop_tenant(public.resolve_parent_tenant_id(p_tenant_id))
     and not public.is_superadmin() then
    raise exception 'not allowed';
  end if;

  v_target_stock_id := coalesce(p_global_stock_id, p_global_stock_allocation_id);

  if v_target_stock_id is null then
    raise exception 'global stock not found';
  end if;

  select gsi.product_id into v_product_id
  from public.global_stocks gs
  join public.global_shipment_items gsi on gsi.id = gs.shipment_item_id
  where gs.id = v_target_stock_id;

  if v_product_id is null then
    raise exception 'global stock not found';
  end if;

  if p_id is not null then
    select * into v_existing from public.shop_product_listings where id = p_id;
  else
    select * into v_existing from public.shop_product_listings
    where shop_id = p_shop_id and global_stock_id = v_target_stock_id;
  end if;

  v_price_locked := coalesce(p_is_price_locked, v_existing.is_price_locked, false);
  v_qty_locked := coalesce(p_is_quantity_locked, v_existing.is_quantity_locked, false);
  v_override_type := coalesce(p_quantity_override_type, v_existing.quantity_override_type, 'absolute');

  if v_existing.id is not null then
    return query
    update public.shop_product_listings
    set
      sell_price_amount = p_sell_price_amount,
      sell_price_currency_id = p_sell_price_currency_id,
      minimum_sell_price_amount = p_minimum_sell_price_amount,
      minimum_sell_price_currency_id = p_minimum_sell_price_currency_id,
      show_quantity = coalesce(p_show_quantity, show_quantity),
      display_quantity_override = p_display_quantity_override,
      is_active = coalesce(p_is_active, true),
      is_price_locked = v_price_locked,
      is_quantity_locked = v_qty_locked,
      quantity_override_type = v_override_type,
      global_stock_allocation_id = null,
      updated_at = now()
    where id = v_existing.id
    returning *;
    return;
  end if;

  return query
  insert into public.shop_product_listings (
    tenant_id,
    shop_id,
    global_stock_allocation_id,
    global_stock_id,
    product_id,
    sell_price_amount,
    sell_price_currency_id,
    minimum_sell_price_amount,
    minimum_sell_price_currency_id,
    show_quantity,
    display_quantity_override,
    is_active,
    is_price_locked,
    is_quantity_locked,
    quantity_override_type
  ) values (
    p_tenant_id,
    p_shop_id,
    null,
    v_target_stock_id,
    v_product_id,
    p_sell_price_amount,
    p_sell_price_currency_id,
    p_minimum_sell_price_amount,
    p_minimum_sell_price_currency_id,
    p_show_quantity,
    p_display_quantity_override,
    coalesce(p_is_active, true),
    v_price_locked,
    v_qty_locked,
    v_override_type
  )
  returning *;
end;
$$;


ALTER FUNCTION "public"."upsert_shop_product_listing"("p_tenant_id" bigint, "p_shop_id" bigint, "p_global_stock_allocation_id" bigint, "p_sell_price_amount" numeric, "p_sell_price_currency_id" bigint, "p_minimum_sell_price_amount" numeric, "p_minimum_sell_price_currency_id" bigint, "p_show_quantity" boolean, "p_display_quantity_override" integer, "p_is_active" boolean, "p_id" bigint, "p_is_price_locked" boolean, "p_is_quantity_locked" boolean, "p_quantity_override_type" "text", "p_global_stock_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_shop_product_listing"("p_tenant_id" bigint, "p_shop_id" bigint, "p_global_stock_allocation_id" bigint DEFAULT NULL::bigint, "p_sell_price_amount" numeric DEFAULT NULL::numeric, "p_sell_price_currency_id" bigint DEFAULT NULL::bigint, "p_minimum_sell_price_amount" numeric DEFAULT NULL::numeric, "p_minimum_sell_price_currency_id" bigint DEFAULT NULL::bigint, "p_show_quantity" boolean DEFAULT NULL::boolean, "p_display_quantity_override" integer DEFAULT NULL::integer, "p_is_active" boolean DEFAULT NULL::boolean, "p_id" bigint DEFAULT NULL::bigint, "p_is_price_locked" boolean DEFAULT NULL::boolean, "p_is_quantity_locked" boolean DEFAULT NULL::boolean, "p_quantity_override_type" "text" DEFAULT NULL::"text", "p_global_stock_id" bigint DEFAULT NULL::bigint, "p_product_id" bigint DEFAULT NULL::bigint) RETURNS SETOF "public"."shop_product_listings"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_product_id bigint;
  v_target_stock_id bigint;
  v_grade_tag_id bigint;
  v_standard_grade_tag_id bigint;
  v_existing record;
  v_price_locked boolean;
  v_qty_locked boolean;
  v_override_type text;
  v_default_sell_amount numeric;
BEGIN
  v_standard_grade_tag_id := public.default_stock_grade_tag_id();

  IF NOT public.user_can_manage_shop_tenant(p_tenant_id)
     AND NOT public.user_can_manage_shop_tenant(public.resolve_parent_tenant_id(p_tenant_id))
     AND NOT public.is_superadmin() THEN
    RAISE EXCEPTION 'not allowed';
  END IF;

  IF p_id IS NOT NULL THEN
    SELECT * INTO v_existing FROM public.shop_product_listings WHERE id = p_id;

    IF v_existing.id IS NULL THEN
      RAISE EXCEPTION 'listing not found';
    END IF;

    IF v_existing.global_stock_id IS NULL
       AND coalesce(v_existing.grade_tag_id, v_standard_grade_tag_id) = v_standard_grade_tag_id THEN
      v_price_locked := coalesce(p_is_price_locked, v_existing.is_price_locked, false);
      v_qty_locked := coalesce(p_is_quantity_locked, v_existing.is_quantity_locked, false);
      v_override_type := coalesce(p_quantity_override_type, v_existing.quantity_override_type, 'absolute');

      RETURN QUERY
      UPDATE public.shop_product_listings
      SET
        grade_tag_id = coalesce(grade_tag_id, v_standard_grade_tag_id),
        sell_price_amount = coalesce(p_sell_price_amount, sell_price_amount),
        sell_price_currency_id = coalesce(p_sell_price_currency_id, sell_price_currency_id),
        minimum_sell_price_amount = p_minimum_sell_price_amount,
        minimum_sell_price_currency_id = p_minimum_sell_price_currency_id,
        show_quantity = coalesce(p_show_quantity, show_quantity),
        display_quantity_override = p_display_quantity_override,
        is_active = coalesce(p_is_active, is_active),
        is_price_locked = v_price_locked,
        is_quantity_locked = v_qty_locked,
        quantity_override_type = v_override_type,
        updated_at = now()
      WHERE id = v_existing.id
      RETURNING *;
      RETURN;
    END IF;
  END IF;

  v_target_stock_id := coalesce(p_global_stock_id, p_global_stock_allocation_id, v_existing.global_stock_id);

  IF v_target_stock_id IS NOT NULL THEN
    SELECT gsi.product_id, coalesce(gs.grade_tag_id, v_standard_grade_tag_id)
    INTO v_product_id, v_grade_tag_id
    FROM public.global_stocks gs
    JOIN public.global_shipment_items gsi ON gsi.id = gs.shipment_item_id
    WHERE gs.id = v_target_stock_id;

    IF v_product_id IS NULL THEN
      RAISE EXCEPTION 'global stock not found';
    END IF;

    IF p_id IS NOT NULL THEN
      SELECT * INTO v_existing FROM public.shop_product_listings WHERE id = p_id;
    ELSE
      SELECT * INTO v_existing
      FROM public.shop_product_listings
      WHERE shop_id = p_shop_id
        AND product_id = v_product_id
        AND grade_tag_id = v_grade_tag_id;
    END IF;

    v_price_locked := coalesce(p_is_price_locked, v_existing.is_price_locked, false);
    v_qty_locked := coalesce(p_is_quantity_locked, v_existing.is_quantity_locked, false);
    v_override_type := coalesce(p_quantity_override_type, v_existing.quantity_override_type, 'absolute');

    IF v_existing.id IS NOT NULL THEN
      RETURN QUERY
      UPDATE public.shop_product_listings
      SET
        sell_price_amount = coalesce(p_sell_price_amount, sell_price_amount),
        sell_price_currency_id = coalesce(p_sell_price_currency_id, sell_price_currency_id),
        minimum_sell_price_amount = p_minimum_sell_price_amount,
        minimum_sell_price_currency_id = p_minimum_sell_price_currency_id,
        show_quantity = coalesce(p_show_quantity, show_quantity),
        display_quantity_override = p_display_quantity_override,
        is_active = coalesce(p_is_active, is_active),
        is_price_locked = v_price_locked,
        is_quantity_locked = v_qty_locked,
        quantity_override_type = v_override_type,
        grade_tag_id = coalesce(grade_tag_id, v_grade_tag_id),
        global_stock_allocation_id = NULL,
        updated_at = now()
      WHERE id = v_existing.id
      RETURNING *;
      RETURN;
    END IF;

    RETURN QUERY
    INSERT INTO public.shop_product_listings (
      tenant_id, shop_id, global_stock_allocation_id, global_stock_id, product_id,
      grade_tag_id, sell_price_amount, sell_price_currency_id,
      minimum_sell_price_amount, minimum_sell_price_currency_id,
      show_quantity, display_quantity_override, is_active,
      is_price_locked, is_quantity_locked, quantity_override_type
    ) VALUES (
      p_tenant_id, p_shop_id, NULL, NULL, v_product_id,
      v_grade_tag_id, p_sell_price_amount, p_sell_price_currency_id,
      p_minimum_sell_price_amount, p_minimum_sell_price_currency_id,
      p_show_quantity, p_display_quantity_override, coalesce(p_is_active, true),
      v_price_locked, v_qty_locked, v_override_type
    )
    RETURNING *;
    RETURN;
  END IF;

  v_product_id := coalesce(p_product_id, v_existing.product_id);
  IF v_product_id IS NULL THEN
    RAISE EXCEPTION 'product or stock required';
  END IF;

  v_grade_tag_id := v_standard_grade_tag_id;

  SELECT p.id, coalesce(p.list_price_amount, p.reference_cost_amount, 0)::numeric
  INTO v_product_id, v_default_sell_amount
  FROM public.products p
  WHERE p.id = v_product_id;

  IF v_product_id IS NULL THEN
    RAISE EXCEPTION 'product not found';
  END IF;

  IF p_id IS NOT NULL THEN
    SELECT * INTO v_existing FROM public.shop_product_listings WHERE id = p_id;
  ELSE
    SELECT * INTO v_existing
    FROM public.shop_product_listings
    WHERE shop_id = p_shop_id
      AND product_id = v_product_id
      AND coalesce(grade_tag_id, v_standard_grade_tag_id) = v_standard_grade_tag_id
      AND global_stock_id IS NULL;
  END IF;

  v_price_locked := coalesce(p_is_price_locked, v_existing.is_price_locked, false);
  v_qty_locked := coalesce(p_is_quantity_locked, v_existing.is_quantity_locked, false);
  v_override_type := coalesce(p_quantity_override_type, v_existing.quantity_override_type, 'absolute');

  IF v_existing.id IS NOT NULL THEN
    RETURN QUERY
    UPDATE public.shop_product_listings
    SET
      grade_tag_id = coalesce(grade_tag_id, v_standard_grade_tag_id),
      sell_price_amount = coalesce(p_sell_price_amount, sell_price_amount),
      sell_price_currency_id = coalesce(p_sell_price_currency_id, sell_price_currency_id),
      minimum_sell_price_amount = p_minimum_sell_price_amount,
      minimum_sell_price_currency_id = p_minimum_sell_price_currency_id,
      show_quantity = coalesce(p_show_quantity, show_quantity),
      display_quantity_override = p_display_quantity_override,
      is_active = coalesce(p_is_active, is_active),
      is_price_locked = v_price_locked,
      is_quantity_locked = v_qty_locked,
      quantity_override_type = v_override_type,
      updated_at = now()
    WHERE id = v_existing.id
    RETURNING *;
    RETURN;
  END IF;

  RETURN QUERY
  INSERT INTO public.shop_product_listings (
    tenant_id, shop_id, global_stock_allocation_id, global_stock_id, product_id,
    grade_tag_id, sell_price_amount, sell_price_currency_id,
    minimum_sell_price_amount, minimum_sell_price_currency_id,
    show_quantity, display_quantity_override, is_active,
    is_price_locked, is_quantity_locked, quantity_override_type
  ) VALUES (
    p_tenant_id, p_shop_id, NULL, NULL, v_product_id,
    v_standard_grade_tag_id, coalesce(p_sell_price_amount, v_default_sell_amount, 0), p_sell_price_currency_id,
    p_minimum_sell_price_amount, p_minimum_sell_price_currency_id,
    coalesce(p_show_quantity, true), p_display_quantity_override, coalesce(p_is_active, false),
    v_price_locked, v_qty_locked, v_override_type
  )
  RETURNING *;
END;
$$;


ALTER FUNCTION "public"."upsert_shop_product_listing"("p_tenant_id" bigint, "p_shop_id" bigint, "p_global_stock_allocation_id" bigint, "p_sell_price_amount" numeric, "p_sell_price_currency_id" bigint, "p_minimum_sell_price_amount" numeric, "p_minimum_sell_price_currency_id" bigint, "p_show_quantity" boolean, "p_display_quantity_override" integer, "p_is_active" boolean, "p_id" bigint, "p_is_price_locked" boolean, "p_is_quantity_locked" boolean, "p_quantity_override_type" "text", "p_global_stock_id" bigint, "p_product_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_stock_location"("p_parent_tenant_id" bigint, "p_code" "text", "p_name" "text", "p_kind" "public"."stock_location_kind" DEFAULT 'box'::"public"."stock_location_kind", "p_is_pickable" boolean DEFAULT true, "p_sort_order" integer DEFAULT 0, "p_is_active" boolean DEFAULT true, "p_is_default" boolean DEFAULT false, "p_id" bigint DEFAULT NULL::bigint, "p_parent_location_id" bigint DEFAULT NULL::bigint) RETURNS "public"."stock_locations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_code text;
  v_name text;
  v_row public.stock_locations%rowtype;
  v_action text;
  v_is_leaf boolean;
  v_want_default boolean;
begin
  perform public._assert_parent_warehouse_tenant(p_parent_tenant_id);

  v_action := case when p_id is null then 'create' else 'edit' end;

  if not (
    public.user_can_manage_parent_tenant(p_parent_tenant_id)
    or public.membership_has_module_action(p_parent_tenant_id, 'global_stock_location', v_action)
  ) then
    raise exception 'not allowed';
  end if;

  v_code := upper(trim(coalesce(p_code, '')));
  v_name := trim(coalesce(p_name, ''));

  if length(v_code) = 0 then
    raise exception 'code is required';
  end if;
  if length(v_name) = 0 then
    raise exception 'name is required';
  end if;
  if p_kind is null then
    raise exception 'kind is required';
  end if;

  perform public._validate_stock_location_nesting(
    p_kind, p_parent_location_id, p_parent_tenant_id
  );

  if p_id is not null and p_parent_location_id = p_id then
    raise exception 'location cannot be its own parent';
  end if;

  v_want_default := coalesce(p_is_default, false) and coalesce(p_is_active, true);

  if p_id is null then
    if v_want_default then
      update public.stock_locations
      set is_default = false
      where parent_tenant_id = p_parent_tenant_id
        and is_default = true;
    end if;

    insert into public.stock_locations (
      parent_tenant_id,
      parent_location_id,
      code,
      name,
      kind,
      is_default,
      is_pickable,
      sort_order,
      is_active
    )
    values (
      p_parent_tenant_id,
      p_parent_location_id,
      v_code,
      v_name,
      p_kind,
      v_want_default,
      coalesce(p_is_pickable, true),
      coalesce(p_sort_order, 0),
      coalesce(p_is_active, true)
    )
    returning * into v_row;

    if p_parent_location_id is not null then
      update public.stock_locations
      set is_default = false
      where id = p_parent_location_id
        and is_default = true;
    end if;
  else
    update public.stock_locations
    set
      parent_location_id = p_parent_location_id,
      code = v_code,
      name = v_name,
      kind = p_kind,
      is_pickable = coalesce(p_is_pickable, is_pickable),
      sort_order = coalesce(p_sort_order, sort_order),
      is_active = coalesce(p_is_active, is_active)
    where id = p_id
      and parent_tenant_id = p_parent_tenant_id
    returning * into v_row;

    if not found then
      raise exception 'location not found';
    end if;

    v_is_leaf := public._stock_location_is_leaf(v_row.id);

    if v_want_default and not v_is_leaf then
      raise exception 'only leaf locations can be the default put-away';
    end if;

    if v_want_default then
      update public.stock_locations
      set is_default = false
      where parent_tenant_id = p_parent_tenant_id
        and is_default = true
        and id <> p_id;

      update public.stock_locations
      set is_default = true
      where id = p_id;
    elsif coalesce(p_is_default, false) = false and coalesce(p_is_active, true) = false then
      update public.stock_locations
      set is_default = false
      where id = p_id;
    elsif p_is_default is not null and p_is_default = false then
      update public.stock_locations
      set is_default = false
      where id = p_id;
    end if;

    if p_parent_location_id is not null then
      update public.stock_locations
      set is_default = false
      where id = p_parent_location_id
        and is_default = true;
    end if;
  end if;

  -- Optional: keep one leaf default if any leaves remain
  if not exists (
    select 1 from public.stock_locations l
    where l.parent_tenant_id = p_parent_tenant_id
      and l.is_default = true
      and l.is_active = true
      and public._stock_location_is_leaf(l.id)
  ) then
    update public.stock_locations
    set is_default = true
    where id = (
      select l.id from public.stock_locations l
      where l.parent_tenant_id = p_parent_tenant_id
        and l.is_active = true
        and public._stock_location_is_leaf(l.id)
      order by l.sort_order, l.id
      limit 1
    );
  end if;

  select * into v_row from public.stock_locations where id = v_row.id;
  return v_row;
end;
$$;


ALTER FUNCTION "public"."upsert_stock_location"("p_parent_tenant_id" bigint, "p_code" "text", "p_name" "text", "p_kind" "public"."stock_location_kind", "p_is_pickable" boolean, "p_sort_order" integer, "p_is_active" boolean, "p_is_default" boolean, "p_id" bigint, "p_parent_location_id" bigint) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."tenant_role_grants" (
    "id" bigint NOT NULL,
    "tenant_role_id" bigint NOT NULL,
    "module_key" "text" NOT NULL,
    "action" "text" NOT NULL,
    "allowed" boolean NOT NULL,
    "updated_by_email" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."tenant_role_grants" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_tenant_role_grant"("p_tenant_role_id" bigint, "p_module_key" "text", "p_action" "text", "p_allowed" boolean) RETURNS "public"."tenant_role_grants"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_role public.tenant_roles;
  v_row public.tenant_role_grants;
begin
  select * into v_role from public.tenant_roles where id = p_tenant_role_id;

  if v_role.id is null then
    raise exception 'Role not found';
  end if;

  if not public.user_is_tenant_admin(v_role.tenant_id) then
    raise exception 'Unauthorized';
  end if;

  if v_role.is_admin = true then
    raise exception 'Cannot assign explicit grants to an Administrator role';
  end if;

  if not (p_module_key = any(public.get_active_module_keys_for_tenant(v_role.tenant_id))) then
    raise exception 'Module is not active for this tenant';
  end if;

  if not exists (
    select 1 from public.module_actions
    where module_key = p_module_key and action = p_action and is_active = true
  ) then
    raise exception 'Invalid or inactive action: % for module %', p_action, p_module_key;
  end if;

  insert into public.tenant_role_grants (
    tenant_role_id,
    module_key,
    action,
    allowed,
    updated_by_email
  )
  values (
    p_tenant_role_id,
    p_module_key,
    p_action,
    p_allowed,
    public.current_user_email()
  )
  on conflict (tenant_role_id, module_key, action) do update set
    allowed = excluded.allowed,
    updated_by_email = excluded.updated_by_email,
    updated_at = now()
  returning * into v_row;

  return v_row;
end;
$$;


ALTER FUNCTION "public"."upsert_tenant_role_grant"("p_tenant_role_id" bigint, "p_module_key" "text", "p_action" "text", "p_allowed" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."user_can_access_tenant_fetch"("p_tenant_id" bigint) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    public.is_superadmin()
    or public.user_can_manage_parent_tenant(p_tenant_id)
    or exists (
      select 1
      from public.memberships m
      where m.tenant_id = p_tenant_id
        and lower(trim(m.email)) = public.current_user_email()
        and m.is_active = true
    )
    or public.current_customer_group_id(p_tenant_id) is not null;
$$;


ALTER FUNCTION "public"."user_can_access_tenant_fetch"("p_tenant_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."user_can_manage_parent_tenant"("p_parent_tenant_id" bigint) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from public.memberships m
    where m.tenant_id = p_parent_tenant_id
      and lower(trim(m.email)) = public.current_user_email()
      and m.is_active = true
      and (
        m.role = 'owner'::public.app_role
        or public.has_module_action(p_parent_tenant_id, 'procurement_stock', 'manage')
      )
  );
$$;


ALTER FUNCTION "public"."user_can_manage_parent_tenant"("p_parent_tenant_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."user_can_manage_shop_tenant"("p_tenant_id" bigint) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from public.memberships m
    where m.tenant_id = p_tenant_id
      and lower(trim(m.email)) = public.current_user_email()
      and m.is_active = true
      and m.role in ('admin', 'staff')
  );
$$;


ALTER FUNCTION "public"."user_can_manage_shop_tenant"("p_tenant_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."user_is_tenant_admin"("p_tenant_id" bigint) RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if public.is_superadmin() then
    return true;
  end if;

  if public.is_network_owner(p_tenant_id) or public.is_tenant_manager(p_tenant_id) then
    return true;
  end if;

  return exists (
    select 1
    from public.memberships m
    left join public.tenant_roles tr on tr.id = m.tenant_role_id
    where m.tenant_id = p_tenant_id
      and lower(trim(m.email)) = public.current_user_email()
      and m.is_active = true
      and (
        m.role = 'owner'::public.app_role
        or tr.is_admin = true
      )
  );
end;
$$;


ALTER FUNCTION "public"."user_is_tenant_admin"("p_tenant_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_costing_file_customer_group"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_group_tenant_id bigint;
begin
  select cg.tenant_id
  into v_group_tenant_id
  from public.customer_groups cg
  where cg.id = new.customer_group_id;

  if v_group_tenant_id is null then
    raise exception 'customer_group_id % does not exist', new.customer_group_id;
  end if;

  if v_group_tenant_id <> new.tenant_id then
    raise exception 'customer_group_id % does not belong to tenant_id %', new.customer_group_id, new.tenant_id;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_costing_file_customer_group"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_preorder_stock_picks"("p_stock_picks" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
declare
  v_elem jsonb;
  v_stock_id bigint;
  v_qty integer;
begin
  if p_stock_picks is null then
    return true;
  end if;
  if jsonb_typeof(p_stock_picks) <> 'array' then
    return false;
  end if;

  for v_elem in select value from jsonb_array_elements(p_stock_picks)
  loop
    v_stock_id := nullif(v_elem->>'global_stock_id', '')::bigint;
    v_qty := coalesce((v_elem->>'quantity')::integer, 0);
    if v_stock_id is null or v_qty <= 0 then
      return false;
    end if;
  end loop;

  return true;
end;
$$;


ALTER FUNCTION "public"."validate_preorder_stock_picks"("p_stock_picks" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."void_global_invoice"("p_invoice_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  perform public.void_sales_invoice(p_invoice_id);
end;
$$;


ALTER FUNCTION "public"."void_global_invoice"("p_invoice_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."void_sales_invoice"("p_invoice_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_invoice public.global_invoices;
begin
  select * into v_invoice from public.global_invoices where id = p_invoice_id for update;
  if v_invoice.id is null then raise exception 'invoice not found'; end if;
  if v_invoice.invoice_status <> 'posted'::public.global_invoice_status then
    raise exception 'only posted invoices can be voided';
  end if;
  if v_invoice.paid_amount > 0 then
    raise exception 'cannot void a paid or partially paid invoice; reverse collections/payments first';
  end if;

  -- Mark invoice as voided (Trigger on global_invoices handles restoring stock)
  update public.global_invoices
  set
    invoice_status = 'voided'::public.global_invoice_status,
    due_amount = 0.00
  where id = p_invoice_id;
end;
$$;


ALTER FUNCTION "public"."void_sales_invoice"("p_invoice_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."wallet_books_tenant_id"("p_tenant_id" bigint) RETURNS bigint
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT public.resolve_parent_tenant_id(p_tenant_id);
$$;


